def feature(board: chess.Board) -> float:
    'Passed pawn score weighted by advancement (white minus black); advanced passed pawns count more'
    try:
        pm = board.piece_map()
        def pawn_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                for rr in range(r+1, 8):
                    for ff in (f-1, f, f+1):
                        if 0 <= ff <= 7:
                            q = board.piece_at(chess.square(ff, rr))
                            if q is not None and q.piece_type == chess.PAWN and q.color == chess.BLACK:
                                return False
                return True
            else:
                for rr in range(r-1, -1, -1):
                    for ff in (f-1, f, f+1):
                        if 0 <= ff <= 7:
                            q = board.piece_at(chess.square(ff, rr))
                            if q is not None and q.piece_type == chess.PAWN and q.color == chess.WHITE:
                                return False
                return True
        white_score = 0.0
        black_score = 0.0
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                r = chess.square_rank(sq)
                if pawn_passed(sq, p.color):
                    # advancement factor: for white use rank/7, for black use (7-r)/7
                    if p.color == chess.WHITE:
                        adv = r / 7.0
                        white_score += adv
                    else:
                        adv = (7 - r) / 7.0
                        black_score += adv
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in board square coverage (number of squares attacked by white minus black) normalized by 64'
    try:
        white_cov = 0
        black_cov = 0
        for sq in range(64):
            if board.is_attacked_by(chess.WHITE, sq):
                white_cov += 1
            if board.is_attacked_by(chess.BLACK, sq):
                black_cov += 1
        return float((white_cov - black_cov) / 64.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of pieces with no legal moves (excluding kings) for White minus Black: potential trapped pieces'
    try:
        pm = board.piece_map()
        # map how many legal moves originate from each square
        moves_from = {}
        for mv in board.legal_moves:
            moves_from[mv.from_square] = moves_from.get(mv.from_square, 0) + 1
        white_trapped = 0
        black_trapped = 0
        for sq, p in pm.items():
            if p is None:
                continue
            if p.piece_type == chess.KING:
                continue
            # If piece exists but has zero legal moves from its square, count as trapped
            if moves_from.get(sq, 0) == 0:
                # Also ensure the piece actually has at least one pseudo-legal move normally (simple heuristic: check attacked/blocked not required)
                if p.color == chess.WHITE:
                    white_trapped += 1
                else:
                    black_trapped += 1
        return float(white_trapped - black_trapped)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pressure on major pieces: weighted attackers on rooks/queens (Black pressure on White majors minus White on Black)'
    try:
        pm = board.piece_map()
        values = {chess.ROOK:5.0, chess.QUEEN:9.0}
        def pressure_on_majors(victim_color):
            total = 0.0
            for sq, p in pm.items():
                if p and p.color==victim_color and p.piece_type in values:
                    attackers = board.attackers(not victim_color, sq)
                    atk_count = len(attackers)
                    total += float(atk_count) * values[p.piece_type]
            return total
        black_on_white = pressure_on_majors(chess.WHITE)
        white_on_black = pressure_on_majors(chess.BLACK)
        return float(black_on_white - white_on_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material tropism: (white pieces weighted inverse-distance to black king) - (black pieces weighted inverse-distance to white king)'
    try:
        vals = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        # locate kings
        white_king = None
        black_king = None
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        if white_king is None or black_king is None:
            return 0.0
        score_w = 0.0
        score_b = 0.0
        for sq, p in board.piece_map().items():
            v = vals.get(p.piece_type, 0.0)
            if v == 0.0:
                continue
            if p.color == chess.WHITE:
                d = chess.square_distance(sq, black_king)
                score_w += v / (1.0 + float(d))
            else:
                d = chess.square_distance(sq, white_king)
                score_b += v / (1.0 + float(d))
        return float(score_w - score_b)
    except Exception:
        return 0.0

