def feature(board: chess.Board) -> float:
    'Net king attack pressure: (White pressure on Black king) - (Black pressure on White king), weighted by attacker piece values'
    piece_value = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.25, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    def king_square(color):
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING and p.color == color:
                return sq
        return None
    def ring_squares(sq):
        if sq is None:
            return []
        rf = chess.square_file(sq); rr = chess.square_rank(sq)
        res = []
        for df in (-1,0,1):
            for dr in (-1,0,1):
                f = rf+df; r = rr+dr
                if 0 <= f < 8 and 0 <= r < 8:
                    res.append(chess.square(f,r))
        return res
    def pressure(attacker_color, target_king_sq):
        if target_king_sq is None:
            return 0.0
        total = 0.0
        for sq in ring_squares(target_king_sq):
            attackers = board.attackers(attacker_color, sq)
            for a in attackers:
                p = board.piece_at(a)
                if p is not None:
                    total += piece_value.get(p.piece_type, 0.0)
        return total
    wk = king_square(chess.WHITE); bk = king_square(chess.BLACK)
    white_on_black = pressure(chess.WHITE, bk)
    black_on_white = pressure(chess.BLACK, wk)
    return float(white_on_black - black_on_white)

