def feature(board: chess.Board) -> float:
    'Tactical exposure: difference in weighted sum of non-pawn pieces that are attacked more times than defended (white minus black). Uses simple piece values.'
    try:
        pm = board.piece_map()
        vals = {chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0}
        white_score = 0.0
        black_score = 0.0
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN or p.piece_type == chess.KING:
                continue
            attackers = len(board.attackers(not p.color, sq))
            defenders = len(board.attackers(p.color, sq))
            if attackers > defenders:
                weight = vals.get(p.piece_type, 0.0)
                contribution = weight * (attackers - defenders)
                if p.color == chess.WHITE:
                    white_score += contribution
                else:
                    black_score += contribution
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Weighted sum (in pawn units) of White pieces that are attacked by Black and have no White defenders (higher -> more hanging material)'
    try:
        pm = board.piece_map()
    except Exception:
        return 0.0
    value = {chess.PAWN: 1.0, chess.KNIGHT: 3.0, chess.BISHOP: 3.0, chess.ROOK: 5.0, chess.QUEEN: 9.0, chess.KING: 0.0}
    total = 0.0
    for sq, p in pm.items():
        if p.color != chess.WHITE:
            continue
        if p.piece_type == chess.KING:
            continue
        try:
            attackers = board.attackers(chess.BLACK, sq)
            defenders = board.attackers(chess.WHITE, sq)
        except Exception:
            attackers = set()
            defenders = set()
        if attackers and len(defenders) == 0:
            total += value.get(p.piece_type, 0.0)
    return float(total)

