def feature(board: chess.Board) -> float:
    'Queen mobility normalized by opponent major-piece count: (White) - (Black); higher means more active queen relative to enemy pieces'
    import chess
    pm = board.piece_map()
    legal = list(board.legal_moves)
    origin_move_count = {}
    for mv in legal:
        origin_move_count[mv.from_square] = origin_move_count.get(mv.from_square, 0) + 1
    def queen_score(color):
        qsq = None
        opp_majors = 0
        for sq, pc in pm.items():
            if pc.piece_type == chess.QUEEN and pc.color == color:
                qsq = sq
            if pc.color != color and pc.piece_type in (chess.ROOK, chess.QUEEN, chess.BISHOP, chess.KNIGHT):
                opp_majors += 1
        qmob = 0
        if qsq is not None:
            qmob = origin_move_count.get(qsq, 0)
        return qmob / (1.0 + opp_majors)
    return float(queen_score(chess.WHITE) - queen_score(chess.BLACK))

