def feature(board: chess.Board) -> float:
    'Proximity of the kings: 8 - Manhattan distance between kings (higher means kings are closer). Returns 0 if one or both kings are missing.'
    pm = board.piece_map()
    wk = None
    bk = None
    for sq, p in pm.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                wk = sq
            else:
                bk = sq
    if wk is None or bk is None:
        return 0.0
    dist = chess.square_distance(wk, bk)
    return float(max(0, 8 - dist))

def feature(board: chess.Board) -> float:
    'Rook intrusion metric: weighted count of rooks on opponent seventh rank and rooks on semi-open files (white minus black)'
    piece_map = board.piece_map()
    def file_has_pawn(file_idx):
        for r in range(8):
            name = chr(ord('a') + file_idx) + str(r + 1)
            sq = chess.parse_square(name)
            p = board.piece_at(sq)
            if p is not None and p.piece_type == chess.PAWN:
                return True
        return False
    white_score = 0.0
    black_score = 0.0
    for sq, pc in piece_map.items():
        if pc.piece_type == chess.ROOK:
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            # seventh rank: white rook on rank 6 (0-based), black rook on rank 1
            is_white_seventh = (pc.color == chess.WHITE and r == 6)
            is_black_seventh = (pc.color == chess.BLACK and r == 1)
            semi_open = not file_has_pawn(f) or not any((board.piece_at(chess.parse_square(chr(ord('a')+f)+str(rr+1)) ) is not None and board.piece_at(chess.parse_square(chr(ord('a')+f)+str(rr+1))).color == pc.color and board.piece_at(chess.parse_square(chr(ord('a')+f)+str(rr+1))).piece_type == chess.PAWN) for rr in range(8))
            score = (1.0 if is_white_seventh else 0.0) if pc.color == chess.WHITE else (1.0 if is_black_seventh else 0.0)
            score += 0.5 * (1.0 if semi_open else 0.0)
            if pc.color == chess.WHITE:
                white_score += score
            else:
                black_score += score
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Count of immediate mate-in-one threats available to each side (Black mates - White mates). Positive means Black has more immediate mating moves.'
    try:
        mate_black = 0
        mate_white = 0
        # helper to count mates for a given side (create a board copy and set turn)
        try:
            bcopy = board.copy()
        except Exception:
            # fallback: try shallow copy via FEN
            try:
                bcopy = chess.Board(board.fen())
            except Exception:
                return 0.0
        for color in (chess.WHITE, chess.BLACK):
            try:
                b2 = bcopy.copy()
            except Exception:
                try:
                    b2 = chess.Board(bcopy.fen())
                except Exception:
                    continue
            b2.turn = color
            for mv in list(b2.legal_moves):
                try:
                    b3 = b2.copy()
                except Exception:
                    try:
                        b3 = chess.Board(b2.fen())
                    except Exception:
                        continue
                try:
                    b3.push(mv)
                except Exception:
                    continue
                if b3.is_checkmate():
                    if color == chess.WHITE:
                        mate_white += 1
                    else:
                        mate_black += 1
        return float(mate_black - mate_white)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rook activity advantage (White minus Black): counts rooks on opponent\'s seventh rank and rooks on open files'
    try:
        pm = board.piece_map()
        def rook_score(color):
            score = 0.0
            for sq, p in pm.items():
                if p.piece_type == chess.ROOK and p.color == color:
                    f = chess.square_file(sq)
                    r = chess.square_rank(sq)
                    # on opponent seventh rank?
                    if color == chess.WHITE and r == 6:
                        score += 1.5
                    if color == chess.BLACK and r == 1:
                        score += 1.5
                    # open file?
                    open_file = True
                    for rr in range(8):
                        psq = rr*8 + f
                        q = board.piece_at(psq)
                        if q and q.piece_type == chess.PAWN:
                            open_file = False
                            break
                    if open_file:
                        score += 1.0
            return score
        return float(rook_score(chess.WHITE) - rook_score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net available one-move checks: (number of legal moves that give check for White) - (for Black) as a simple gauge of mating pressure'
    try:
        # iterate legal moves for both colors by toggling turn on copies
        checks_white = 0
        checks_black = 0
        # helper to count for a color
        def count_checks_for(color):
            cnt = 0
            try:
                b = board.copy()
                b.turn = color
                for mv in list(b.legal_moves):
                    b.push(mv)
                    if b.is_check():
                        cnt += 1
                    b.pop()
            except Exception:
                return 0
            return cnt
        checks_white = count_checks_for(chess.WHITE)
        checks_black = count_checks_for(chess.BLACK)
        return float(checks_white - checks_black)
    except Exception:
        return 0.0

