def feature(board: chess.Board) -> float:
    'Net material of hanging pieces (attacked more times than defended): (Black_hanging_value - White_hanging_value) in pawn units (pawn=1.0, knight=3.2,bishop=3.3,rook=5.0,queen=9.0)'
    values = {chess.PAWN: 1.0, chess.KNIGHT: 3.2, chess.BISHOP: 3.3, chess.ROOK: 5.0, chess.QUEEN: 9.0, chess.KING: 0.0}
    pm = board.piece_map()
    hanging_white = 0.0
    hanging_black = 0.0
    for sq, p in pm.items():
        if p.piece_type == chess.KING:
            continue
        attackers = board.attackers(1 - p.color, sq)
        defenders = board.attackers(p.color, sq)
        if len(attackers) > len(defenders):
            # the degree of being hanging scales with (attackers - defenders)
            penalty = values.get(p.piece_type, 0.0) * float(len(attackers) - len(defenders))
            if p.color == chess.WHITE:
                hanging_white += penalty
            else:
                hanging_black += penalty
    return float(hanging_black - hanging_white)

def feature(board: chess.Board) -> float:
    'Trapped piece count difference: number of non-king non-pawn pieces that have no safe legal move (positive = better for White)'
    try:
        legal_moves = list(board.legal_moves)
        moves_by_from = {}
        for m in legal_moves:
            moves_by_from.setdefault(m.from_square, []).append(m)
        white_trapped = 0
        black_trapped = 0
        # consider knights, bishops, rooks, queens
        for sq, piece in board.piece_map().items():
            if piece.piece_type in (chess.KING, chess.PAWN):
                continue
            my_moves = moves_by_from.get(sq, [])
            trapped = True
            if not my_moves:
                trapped = True
            else:
                for m in my_moves:
                    try:
                        board.push(m)
                        # check location of piece after move (might be captured immediately by en-passant? ignore)
                        to_sq = m.to_square
                        # if piece still exists on to_sq and is not attacked by opponent, consider it safe
                        p_after = board.piece_at(to_sq)
                        opp = not piece.color
                        if p_after is not None and p_after.piece_type==piece.piece_type and p_after.color==piece.color:
                            if not board.is_attacked_by(opp, to_sq):
                                trapped = False
                        else:
                            # capturing move or transformed piece: treat as not trapped
                            trapped = False
                        board.pop()
                        if not trapped:
                            break
                    except Exception:
                        try:
                            board.pop()
                        except Exception:
                            pass
            if trapped:
                if piece.color==chess.WHITE:
                    white_trapped += 1
                else:
                    black_trapped += 1
        return float(black_trapped - white_trapped)
    except Exception:
        return 0.0

