def feature(board: chess.Board) -> float:
    'Difference in number of advanced passed pawns (on/after 6th rank for White, on/at 3rd rank for Black): white - black'
    try:
        pm = board.piece_map()
        white_passed_advanced = 0
        black_passed_advanced = 0
        # precompute pawn squares by file for quick checks
        white_pawn_squares = [sq for sq, p in pm.items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        black_pawn_squares = [sq for sq, p in pm.items() if p.piece_type == chess.PAWN and p.color == chess.BLACK]
        black_pawn_by_file = {}
        white_pawn_by_file = {}
        for sq in black_pawn_squares:
            black_pawn_by_file.setdefault(chess.square_file(sq), []).append(sq)
        for sq in white_pawn_squares:
            white_pawn_by_file.setdefault(chess.square_file(sq), []).append(sq)
        for sq, p in pm.items():
            if p.piece_type != chess.PAWN:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                # passed if no black pawn on same or adjacent files with rank > r
                blocked = False
                for df in (-1, 0, 1):
                    ff = f + df
                    if 0 <= ff <= 7:
                        for b_sq in black_pawn_by_file.get(ff, []):
                            if chess.square_rank(b_sq) > r:
                                blocked = True
                                break
                    if blocked:
                        break
                if not blocked and r >= 5:
                    white_passed_advanced += 1
            else:
                blocked = False
                for df in (-1, 0, 1):
                    ff = f + df
                    if 0 <= ff <= 7:
                        for w_sq in white_pawn_by_file.get(ff, []):
                            if chess.square_rank(w_sq) < r:
                                blocked = True
                                break
                    if blocked:
                        break
                if not blocked and r <= 2:
                    black_passed_advanced += 1
        return float(white_passed_advanced - black_passed_advanced)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
