        def min_dist_to_pawn(king_color):
            ks = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == king_color), None)
            if ks is None:
                return 8.0
            dmin = 8
            for sq, p in pm.items():
                if p.piece_type == chess.PAWN and p.color == king_color:
                    d = chess.square_distance(ks, sq)
                    if d < dmin:
                        dmin = d
            return float(dmin if dmin != 8 else 8.0)
        return float(min_dist_to_pawn(chess.BLACK) - min_dist_to_pawn(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Space-control in enemy half: count squares on opponent\'s half that are attacked by your color (White - Black), normalized by half-board size'
    white_controls = 0
    black_controls = 0
    # white controls squares on ranks 4..7 (rank >=4)
    for r in range(4,8):
        for f in range(8):
            sq = chess.square(f,r)
            try:
                if board.is_attacked_by(chess.WHITE, sq):
                    white_controls += 1
                if board.is_attacked_by(chess.BLACK, chess.square(f,7-r)):  # symmetrical count for black's perspective
                    pass
            except Exception:
                pass
    # black controls squares on ranks 0..3 (from black's perspective opponent half is ranks 0..3)
    for r in range(0,4):
        for f in range(8):
            sq = chess.square(f,r)
            try:
                if board.is_attacked_by(chess.BLACK, sq):
                    black_controls += 1
            except Exception:
                pass
    # normalize by 32 (squares in half board)
    return (white_controls - black_controls) / 32.0

def feature(board: chess.Board) -> float:
    'Pawn structure fragility: (black pawn islands - white pawn islands) + 0.5*(black isolated - white isolated)'
    try:
        pm = board.piece_map()
        def pawn_files(color):
            files = set()
            for s, p in pm.items():
                if p.piece_type == chess.PAWN and p.color == color:
                    files.add(chess.square_file(s))
            return sorted(files)
        def pawn_islands_and_isolated(color):
            files = pawn_files(color)
            if not files:
                return 0, 0
            islands = 0
            isolated = 0
            prev = None
            files_set = set(files)
            for f in files:
                if prev is None or f != prev + 1:
                    islands += 1
                prev = f
                # isolated if no adjacent pawn files (either color) exist
                if (f - 1) not in files_set and (f + 1) not in files_set:
                    isolated += 1
            return islands, isolated
        w_islands, w_isol = pawn_islands_and_isolated(chess.WHITE)
        b_islands, b_isol = pawn_islands_and_isolated(chess.BLACK)
        return float((b_islands - w_islands) + 0.5 * (b_isol - w_isol))
    except Exception:
        return 0.0

