def feature(board: chess.Board) -> float:
    'King pawn shield strength difference: a heuristic count of friendly pawns on the three files around the king and in ranks near the king (White - Black). Higher = better shield.'
    try:
        def shield_strength_for(king_sq, color):
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            strength = 0.0
            for df in (-1, 0, 1):
                nf = kf + df
                if not (0 <= nf <= 7):
                    continue
                # consider up to 3 ranks ahead/behind relative to king for pawn shield
                for dr_offset, weight in ((0,1.0),(1,0.6),(2,0.3)):
                    if color == chess.WHITE:
                        nr = kr + dr_offset
                    else:
                        nr = kr - dr_offset
                    if not (0 <= nr <= 7):
                        continue
                    nsq = nf + nr*8
                    pc = board.piece_at(nsq)
                    if pc is not None and pc.piece_type == chess.PAWN and pc.color == color:
                        strength += weight
            return strength

        # find kings
        wking = None
        bking = None
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    wking = sq
                else:
                    bking = sq
        white_shield = shield_strength_for(wking, chess.WHITE)
        black_shield = shield_strength_for(bking, chess.BLACK)
        return white_shield - black_shield
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King exposure balance: difference (White exposure - Black exposure) where exposure = attacked squares within distance 2 minus defenders'
    import chess
    pm = board.piece_map()
    # locate kings
    wk_sq = bk_sq = None
    for sq, pc in pm.items():
        if pc.piece_type == chess.KING:
            if pc.color == chess.WHITE:
                wk_sq = sq
            else:
                bk_sq = sq
    def exposure(king_sq, own_color):
        if king_sq is None:
            return 0.0
        enemy = not own_color
        ex = 0.0
        for s in chess.SQUARES:
            if chess.square_distance(s, king_sq) <= 2:
                if board.is_attacked_by(enemy, s):
                    ex += 1.0
                if board.is_attacked_by(own_color, s):
                    ex -= 0.5
        return ex
    wexp = exposure(wk_sq, chess.WHITE)
    bexp = exposure(bk_sq, chess.BLACK)
    return float(wexp - bexp)

