    try:
        heavy = {chess.ROOK, chess.QUEEN}
        def mobility_for(color):
            b = board.copy()
            b.turn = color
            count = 0
            for mv in b.legal_moves:
                p = b.piece_at(mv.from_square)
                if p is not None and p.piece_type in heavy and p.color == color:
                    count += 1
            return count
        wm = mobility_for(chess.WHITE)
        bm = mobility_for(chess.BLACK)
        return float(wm - bm)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Sum of opponent piece activity toward the side-to-move king: sum(weight/(1+manhattan_distance)) where weight ~ piece value'
    try:
        values = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0, chess.KING:0.0}
        my_color = board.turn
        opp = not my_color
        king_sq = board.king(my_color)
        if king_sq is None:
            return 0.0
        total = 0.0
        for sq, piece in board.piece_map().items():
            if piece.color != opp:
                continue
            dist = chess.square_distance(sq, king_sq)
            # Avoid division by zero; if on king square (capture), use small distance
            denom = 1.0 + float(dist)
            total += values.get(piece.piece_type, 0.0) / denom
        # normalize to pawn units
        return float(total / 100.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in attacking cluster density: (pressure on white king minus pressure on black king). Pressure is inverse average Manhattan distance of opponent non-pawn pieces to the king.'
    try:
        pm = board.piece_map()
        white_king = None
        black_king = None
        white_attackers = []
        black_attackers = []
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        if white_king is None or black_king is None:
            return 0.0
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN or p.piece_type == chess.KING:
                continue
            if p.color == chess.WHITE:
                white_attackers.append(sq)
            else:
                black_attackers.append(sq)
        def pressure(attacker_list, target):
            if not attacker_list:
                return 0.0
            s = 0.0
            for a in attacker_list:
                d = chess.square_distance(a, target)
                s += d
            avg = s / len(attacker_list)
            return 1.0 / (avg + 0.1)
        pressure_on_white = pressure(black_attackers, white_king)
        pressure_on_black = pressure(white_attackers, black_king)
        return float(pressure_on_white - pressure_on_black)
    except Exception:
        return 0.0

