def feature(board: chess.Board) -> float:
    'Sum of attacker-weight on and around the opponent king (White attacking Black king minus Black attacking White king), weights by piece value'
    piece_values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:20000}
    pm = board.piece_map()
    def king_sq(color):
        for s,p in pm.items():
            if p.piece_type==chess.KING and p.color==color:
                return s
        return None
    def surrounding_squares(sq):
        if sq is None:
            return []
        res = []
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        for df in (-1,0,1):
            for dr in (-1,0,1):
                nf, nr = f+df, r+dr
                if 0 <= nf <=7 and 0 <= nr <=7:
                    res.append(chess.square(nf,nr))
        return res
    w_king = king_sq(chess.WHITE)
    b_king = king_sq(chess.BLACK)
    def attack_weight(attacker_color, target_king_sq):
        if target_king_sq is None:
            return 0.0
        total = 0.0
        for sq in surrounding_squares(target_king_sq):
            attackers = board.attackers(attacker_color, sq)
            for atk_sq in attackers:
                p = board.piece_at(atk_sq)
                if p:
                    # weight by piece value and distance penalty: center square more important
                    dist = max(1, abs(chess.square_file(sq)-chess.square_file(target_king_sq)) + abs(chess.square_rank(sq)-chess.square_rank(target_king_sq)))
                    total += piece_values.get(p.piece_type,100) / dist
        return total
    w_on_b = attack_weight(chess.WHITE, b_king)
    b_on_w = attack_weight(chess.BLACK, w_king)
    return float((w_on_b - b_on_w) / 100.0)

