def feature(board: chess.Board) -> float:
    'Count difference of "trapped" pieces (no legal moves from their square and attacked by opponent): (Black_trapped - White_trapped)'
    # collect from-squares that have at least one legal move
    try:
        legal = list(board.legal_moves)
    except Exception:
        legal = []
    from_squares = set(m.from_square for m in legal)
    trapped_white = 0
    trapped_black = 0
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.KING:
            continue
        if sq not in from_squares:
            opp = chess.BLACK if p.color == chess.WHITE else chess.WHITE
            try:
                attackers = board.attackers(opp, sq)
            except Exception:
                attackers = set()
            if attackers:
                if p.color == chess.WHITE:
                    trapped_white += 1
                else:
                    trapped_black += 1
    return float(trapped_black - trapped_white)

def feature(board: chess.Board) -> float:
    '2. Does the opponent have a checkmate in one (i.e., a mate-on-their-next-move)? (1.0 if yes, 0.0 otherwise)'
