def feature(board: chess.Board) -> float:
    'Difference in average mobility (attacked squares) of non-pawn non-king pieces (White minus Black)'
    pm = board.piece_map()
    white_counts = []; black_counts = []
    # For each square t, board.attackers(color,t) gives squares attacking t
    for sq_src,p in pm.items():
        if p.piece_type in (chess.PAWN, chess.KING):
            continue
        cnt = 0
        for t in range(64):
            try:
                at = board.attackers(p.color, t)
            except Exception:
                at = set()
            if sq_src in at:
                cnt += 1
        if p.color==chess.WHITE:
            white_counts.append(cnt)
        else:
            black_counts.append(cnt)
    wavg = float(sum(white_counts)/len(white_counts)) if white_counts else 0.0
    bavg = float(sum(black_counts)/len(black_counts)) if black_counts else 0.0
    return float(wavg - bavg)

def feature(board: chess.Board) -> float:
    'Net attack pressure on squares adjacent to each king (white minus black)'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.BLACK), None)
        def adjacent_squares(sq):
            if sq is None:
                return []
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            res = []
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    nf = f + df
                    nr = r + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        res.append(chess.square(nf, nr))
            return res
        white_pressure = 0
        black_pressure = 0
        for adj in adjacent_squares(white_king_sq):
            white_pressure += len(board.attackers(chess.BLACK, adj))
        for adj in adjacent_squares(black_king_sq):
            black_pressure += len(board.attackers(chess.WHITE, adj))
        return float(white_pressure - black_pressure)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Black threat density around the white king: sum(weight / (distance^2 + 0.1)) for all Black pieces (higher means concentrated threats)'
    try:
        pm = board.piece_map()
    except Exception:
        return 0.0
    wk_sq = None
    for sq, p in pm.items():
        if p.piece_type == chess.KING and p.color == chess.WHITE:
            wk_sq = sq
            break
    if wk_sq is None:
        return 0.0
    weights = {chess.PAWN: 1.0, chess.KNIGHT: 3.0, chess.BISHOP: 3.0, chess.ROOK: 5.0, chess.QUEEN: 9.0, chess.KING: 0.0}
    density = 0.0
    for sq, p in pm.items():
        if p.color != chess.BLACK:
            continue
        w = weights.get(p.piece_type, 0.0)
        if w <= 0.0:
            continue
        try:
            d = chess.square_distance(sq, wk_sq)
        except Exception:
            d = 8
        denom = (d * d) + 0.1
        density += w / denom
    return float(density)

def feature(board: chess.Board) -> float:
    'Rook file openness score: open file = 0.5, semi-open = 0.25 (white minus black)'
    try:
        pm = board.piece_map()
        white_score = 0.0
        black_score = 0.0
        for sq, p in pm.items():
            if p.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                pawns_on_file = []
                for r in range(8):
                    sqf = chess.square(f, r)
                    q = board.piece_at(sqf)
                    if q is not None and q.piece_type == chess.PAWN:
                        pawns_on_file.append(q)
                if len(pawns_on_file) == 0:
                    val = 0.5
                else:
                    # semi-open if no friendly pawns on file but opponent pawns exist
                    friendly_pawns = any(q.color == p.color for q in pawns_on_file)
                    opponent_pawns = any(q.color != p.color for q in pawns_on_file)
                    if not friendly_pawns and opponent_pawns:
                        val = 0.25
                    else:
                        val = 0.0
                if p.color == chess.WHITE:
                    white_score += val
                else:
                    black_score += val
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in average Manhattan distance of major pieces (rooks/queens) to the enemy king (black_avg - white_avg). Positive means white major pieces are on average closer to black king.'
    try:
        pm = board.piece_map()
        w_major = []
        b_major = []
        white_king_sq = None
        black_king_sq = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king_sq = sq
                else:
                    black_king_sq = sq
            if p.piece_type in (chess.ROOK, chess.QUEEN):
                if p.color == chess.WHITE:
                    w_major.append(sq)
                else:
                    b_major.append(sq)
        if black_king_sq is None or white_king_sq is None:
            return 0.0
        def avg_dist(list_sq, target):
            if not list_sq:
                return 10.0
            s = 0
            for sq in list_sq:
                s += chess.square_distance(sq, target)
            return s / len(list_sq)
        white_avg = avg_dist(w_major, black_king_sq)
        black_avg = avg_dist(b_major, white_king_sq)
        return float(black_avg - white_avg)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Queen tropism and proximity to enemy king: (White_score - Black_score) where score = sum(inverse distance to enemy king + attacks to squares around that king)'
    try:
        def queen_score(own_color):
            opp = not own_color
            k = board.king(opp)
            if k is None:
                return 0.0
            king_adjacent = [k] + [chess.square_file(k) and sq for sq in []]  # placeholder to make no error
            # collect adjacent squares to king (including diagonals)
            adj_sqs = []
            kr = chess.square_rank(k)
            kf = chess.square_file(k)
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    f = kf + df
                    r = kr + dr
                    if 0 <= f <= 7 and 0 <= r <= 7:
                        adj_sqs.append(chess.square(f, r))
            total = 0.0
            for sq, p in board.piece_map().items():
                if p.piece_type != chess.QUEEN or p.color != own_color:
                    continue
                # inverse distance to enemy king
                dist = chess.square_distance(sq, k)
                if dist == 0:
                    inv = 1.5
                else:
                    inv = 1.0 / dist
                # number of attacked squares in king adjacency
                attacks_near = sum(1 for s in adj_sqs if board.is_attacked_by(own_color, s))
                total += inv + 0.4 * attacks_near
            return total
        return float(queen_score(chess.WHITE) - queen_score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Edge-trapped piece penalty: pieces on the edge with <=1 legal moves weighted by piece value and distance-from-center (White - Black)'
    try:
        values = {chess.QUEEN:9.0, chess.ROOK:5.0, chess.BISHOP:3.0, chess.KNIGHT:3.0, chess.PAWN:1.0, chess.KING:0.0}
        pm = board.piece_map()
        moves_from = {}
        for m in board.legal_moves:
            moves_from[m.from_square] = moves_from.get(m.from_square, 0) + 1
        center_squares = [chess.parse_square(s) for s in ('d4','e4','d5','e5')]
        score = 0.0
        for sq, p in pm.items():
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if f in (0,7) or r in (0,7):
                mobility = moves_from.get(sq, 0)
                if mobility <= 1 and p.piece_type != chess.KING:
                    dist = min(chess.square_distance(sq, c) for c in center_squares)
                    weight = values.get(p.piece_type, 0.0) * (1.0 + (dist / 4.0))
                    score += (weight if p.color == chess.WHITE else -weight)
        return float(score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Space-control in enemy half: count squares on opponent\'s half that are attacked by your color (White - Black), normalized by half-board size'
    white_controls = 0
    black_controls = 0
    # white controls squares on ranks 4..7 (rank >=4)
    for r in range(4,8):
        for f in range(8):
            sq = chess.square(f,r)
            try:
                if board.is_attacked_by(chess.WHITE, sq):
                    white_controls += 1
                if board.is_attacked_by(chess.BLACK, chess.square(f,7-r)):  # symmetrical count for black's perspective
                    pass
            except Exception:
                pass
    # black controls squares on ranks 0..3 (from black's perspective opponent half is ranks 0..3)
    for r in range(0,4):
        for f in range(8):
            sq = chess.square(f,r)
            try:
                if board.is_attacked_by(chess.BLACK, sq):
                    black_controls += 1
            except Exception:
                pass
    # normalize by 32 (squares in half board)
    return (white_controls - black_controls) / 32.0

def feature(board: chess.Board) -> float:
    'Material balance (white minus black) in pawns=100 n=320 b=330 r=500 q=900 units, returned in pawn-equivalents (divide by 100)'
    try:
