def feature(board: chess.Board) -> float:
    'Difference in area controlled per non-king piece: (white attacked squares per piece) - (black attacked squares per piece)'
    piece_map = board.piece_map()
    white_pieces = 0
    black_pieces = 0
    for pc in piece_map.values():
        if pc.piece_type == chess.KING:
            continue
        if pc.color == chess.WHITE:
            white_pieces += 1
        else:
            black_pieces += 1
    # count attacked squares by each side
    white_attacked = 0
    black_attacked = 0
    for sq in range(64):
        if board.is_attacked_by(chess.WHITE, sq):
            white_attacked += 1
        if board.is_attacked_by(chess.BLACK, sq):
            black_attacked += 1
    # avoid division by zero
    wp = float(white_pieces) if white_pieces > 0 else 1.0
    bp = float(black_pieces) if black_pieces > 0 else 1.0
    return float((white_attacked / wp) - (black_attacked / bp))

def feature(board: chess.Board) -> float:
    'Net count of hanging (attacked and undefended) pieces: White hanging pieces minus Black hanging pieces'
    try:
        pm = board.piece_map()
        white_hanging = 0
        black_hanging = 0
        for sq, piece in pm.items():
            if piece is None:
                continue
            attackers = len(board.attackers(not piece.color, sq))
            defenders = len(board.attackers(piece.color, sq))
            if attackers > 0 and defenders == 0:
                if piece.color == chess.WHITE:
                    white_hanging += 1
                else:
                    black_hanging += 1
        return float(white_hanging - black_hanging)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in normalized piece activity: (sum over pieces of piece_value * legal_moves_from_that_piece) / (material_value + 1)'
    import chess
    VAL = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0, chess.KING:0.0}
    pm = board.piece_map()
    bd = board.copy()
    def activity_and_material(color):
        bd.turn = color
        moves = list(bd.legal_moves)
        moves_by_from = {}
        for m in moves:
            moves_by_from.setdefault(m.from_square, 0)
            moves_by_from[m.from_square] += 1
        activity = 0.0
        material = 0.0
        for sq, p in pm.items():
            if p.color != color:
                continue
            material += VAL.get(p.piece_type, 0.0)
            if p.piece_type == chess.KING:
                continue
            nm = moves_by_from.get(sq, 0)
            activity += VAL.get(p.piece_type, 0.0) * float(nm)
        return activity, material
    wa, wm = activity_and_material(chess.WHITE)
    ba, bm = activity_and_material(chess.BLACK)
    wnorm = wa / (wm + 1.0)
    bnorm = ba / (bm + 1.0)
    return float(wnorm - bnorm)

def feature(board: chess.Board) -> float:
    'Queen mobility minus exposure difference: for each queen (mobility - 1.5 * attackers) summed White minus Black'
    try:
        pieces = board.piece_map()
        legal_moves = list(board.legal_moves)
        # Pre-bucket legal moves by origin square
        origin_counts = {}
        for m in legal_moves:
            origin_counts.setdefault(m.from_square, 0)
            origin_counts[m.from_square] += 1
        white_score = 0.0
        black_score = 0.0
        for sq, p in pieces.items():
            if p.piece_type == chess.QUEEN:
                mobility = origin_counts.get(sq, 0)
                attackers = len(board.attackers(chess.BLACK if p.color == chess.WHITE else chess.WHITE, sq))
                value = mobility - 1.5 * attackers
                if p.color == chess.WHITE:
                    white_score += value
                else:
                    black_score += value
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Proportion of legal moves for the side to move that give check (forcing density) between 0 and 1'
    try:
        total = 0
        checks = 0
        for m in board.legal_moves:
            total += 1
            b = board.copy()
            b.push(m)
            if b.is_check():
                checks += 1
        if total == 0:
            return 0.0
        return float(checks) / float(total)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Trapped high-value piece metric: sum over sides of (flag * piece_value) where flag=1 if highest-value piece has <=1 legal moves and is attacked more than defended; returns (white - black)'
    try:
        pm = board.piece_map()
        vals = {chess.QUEEN: 9.0, chess.ROOK: 5.0, chess.BISHOP: 3.0, chess.KNIGHT: 3.0, chess.PAWN: 1.0}
        def side_metric(color):
            # find highest-value piece square for color
            best_sq = None
            best_val = -1.0
            for s, p in pm.items():
                if p.color != color:
                    continue
                v = vals.get(p.piece_type, 0.0)
                if v > best_val:
                    best_val = v
                    best_sq = s
            if best_sq is None or best_val <= 0.0:
                return 0.0
            # count legal moves from that square
            legal_from = 0
            for mv in board.legal_moves:
                if mv.from_square == best_sq:
                    legal_from += 1
            attackers = len(board.attackers(not color, best_sq))
            defenders = len(board.attackers(color, best_sq))
            if legal_from <= 1 and (attackers - defenders) >= 1:
                return best_val
            return 0.0
        w = side_metric(chess.WHITE)
        b = side_metric(chess.BLACK)
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Bishop-pair advantage penalized by same-color-pawn blocking: positive = White advantage'
    try:
        pm = board.piece_map()
        def square_color_parity(sq):
            return (chess.square_file(sq) + chess.square_rank(sq)) & 1
        # counts
        w_bishops = [s for s, p in pm.items() if p.piece_type == chess.BISHOP and p.color == chess.WHITE]
        b_bishops = [s for s, p in pm.items() if p.piece_type == chess.BISHOP and p.color == chess.BLACK]
        w_has_pair = 1.0 if len(w_bishops) >= 2 else 0.0
        b_has_pair = 1.0 if len(b_bishops) >= 2 else 0.0
        # blocking measure: count of pawns on same-color squares as each bishop
        w_block = 0
        b_block = 0
        for s, p in pm.items():
            if p.piece_type == chess.PAWN:
                parity = square_color_parity(s)
                # each bishop on that parity considered blocked +1
                for bs in w_bishops:
                    if square_color_parity(bs) == parity:
                        w_block += 1
                for bs in b_bishops:
                    if square_color_parity(bs) == parity:
                        b_block += 1
        # normalize blocking by a small factor to keep ranges reasonable
        block_norm = 8.0 if (w_bishops or b_bishops) else 1.0
        return (w_has_pair - b_has_pair) - ( (w_block - b_block) / block_norm )
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in average Manhattan distance of non-king pieces to their own king (white average minus black average)'
    try:
        pm = board.piece_map()
        def avg_dist(color):
            king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == color), None)
            if king_sq is None:
                return 0.0
            dists = []
            for sq, pc in pm.items():
                if pc.color == color and pc.piece_type != chess.KING:
                    dists.append(chess.square_distance(sq, king_sq))
            if not dists:
                return 0.0
            return float(sum(dists) / len(dists))
        return avg_dist(chess.WHITE) - avg_dist(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Space-control in enemy half: count squares on opponent\'s half that are attacked by your color (White - Black), normalized by half-board size'
    white_controls = 0
    black_controls = 0
    # white controls squares on ranks 4..7 (rank >=4)
    for r in range(4,8):
        for f in range(8):
            sq = chess.square(f,r)
            try:
                if board.is_attacked_by(chess.WHITE, sq):
                    white_controls += 1
                if board.is_attacked_by(chess.BLACK, chess.square(f,7-r)):  # symmetrical count for black's perspective
                    pass
            except Exception:
                pass
    # black controls squares on ranks 0..3 (from black's perspective opponent half is ranks 0..3)
    for r in range(0,4):
        for f in range(8):
            sq = chess.square(f,r)
            try:
                if board.is_attacked_by(chess.BLACK, sq):
                    black_controls += 1
            except Exception:
                pass
    # normalize by 32 (squares in half board)
    return (white_controls - black_controls) / 32.0

def feature(board: chess.Board) -> float:
    'Difference in average mobility (attacked squares) of non-pawn non-king pieces (White minus Black)'
    pm = board.piece_map()
    white_counts = []; black_counts = []
    # For each square t, board.attackers(color,t) gives squares attacking t
    for sq_src,p in pm.items():
        if p.piece_type in (chess.PAWN, chess.KING):
            continue
        cnt = 0
        for t in range(64):
            try:
                at = board.attackers(p.color, t)
            except Exception:
                at = set()
            if sq_src in at:
                cnt += 1
        if p.color==chess.WHITE:
            white_counts.append(cnt)
        else:
            black_counts.append(cnt)
    wavg = float(sum(white_counts)/len(white_counts)) if white_counts else 0.0
    bavg = float(sum(black_counts)/len(black_counts)) if black_counts else 0.0
    return float(wavg - bavg)

def feature(board: chess.Board) -> float:
    'Bishop activity: (central outpost bishops + 0.5 for bishop pair) white minus black'
    try:
        central = {chess.parse_square(s) for s in ('d4', 'e4', 'd5', 'e5')}
        pm = board.piece_map()
        def score(color):
            bishops = [sq for sq, pc in pm.items() if pc.piece_type == chess.BISHOP and pc.color == color]
            s = 0.0
            for sq in bishops:
                if sq in central:
                    s += 1.0
            if len(bishops) >= 2:
                s += 0.5
            return s
        return float(score(chess.WHITE) - score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Central pawn presence and chain strength (White minus Black): counts pawns on d/e files and pawns defended by other pawns'
    try:
        pm = board.piece_map()
        def pawn_central_chain_score(color):
            score = 0.0
            for sq, p in pm.items():
                if p.piece_type == chess.PAWN and p.color == color:
                    f = chess.square_file(sq)
                    r = chess.square_rank(sq)
                    # central file bonus (d=3, e=4)
                    if f in (3,4):
                        # more advanced central pawn gets more
                        rank_adv = r if color == chess.WHITE else (7 - r)
                        score += 0.6 + 0.4 * (rank_adv / 7.0)
                    # pawn defended by a pawn (chain)
                    for df, dr in ((-1, -1), (1, -1)) if color == chess.WHITE else ((-1, 1), (1, 1)):
                        nf, nr = f + df, r + dr
                        if 0 <= nf <= 7 and 0 <= nr <= 7:
                            nsq = nr*8 + nf
                            q = board.piece_at(nsq)
                            if q and q.piece_type == chess.PAWN and q.color == color:
                                score += 0.25
                                break
            return score
        return float(pawn_central_chain_score(chess.WHITE) - pawn_central_chain_score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'White minus Black: whether any rook attacks the opponent\'s most advanced passed pawn promotion square (1 if true, else 0), difference between sides'
    try:
        pieces = board.piece_map()
    except Exception:
        return 0.0
    pawns = [(sq, p) for sq, p in pieces.items() if p.piece_type == chess.PAWN]
    rooks = [(sq, p) for sq, p in pieces.items() if p.piece_type == chess.ROOK]
    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            for opp_sq, opp_piece in pawns:
                if opp_piece.color == chess.BLACK:
                    if abs(chess.square_file(opp_sq) - f) <= 1 and chess.square_rank(opp_sq) >= r:
                        return False
            return True
        else:
            for opp_sq, opp_piece in pawns:
                if opp_piece.color == chess.WHITE:
                    if abs(chess.square_file(opp_sq) - f) <= 1 and chess.square_rank(opp_sq) <= r:
                        return False
            return True
    white_passed = None
    black_passed = None
    for sq, p in pawns:
        if not is_passed(sq, p.color):
            continue
        if p.color == chess.WHITE:
            if white_passed is None or chess.square_rank(sq) > chess.square_rank(white_passed):
                white_passed = sq
        else:
            if black_passed is None or chess.square_rank(sq) < chess.square_rank(black_passed):
                black_passed = sq
    white_attack = 0.0
    black_attack = 0.0
    # compute target squares
    if black_passed is not None:
        target = chess.square(chess.square_file(black_passed), 0) if hasattr(chess, 'square') else None
        # compute by file/rank:
        tf = chess.square_file(black_passed); tr = 0
        for r_sq, r_p in rooks:
            if r_p.color == chess.WHITE:
                # does rook attack promotion square?
                # use board.is_attacked_by
                try:
                    if board.is_attacked_by(chess.WHITE, chess.square(tf, tr)) if hasattr(chess, 'square') else board.is_attacked_by(chess.WHITE, chess.parse_square(chess.square_name(black_passed)[0] + '1')):
                        white_attack = 1.0
                        break
                except Exception:
                    # fallback: test attackers
                    for a in board.attackers(chess.WHITE, black_passed):
                        if board.piece_at(a) and board.piece_at(a).piece_type == chess.ROOK:
                            white_attack = 1.0
                            break
                    if white_attack:
                        break
    if white_passed is not None:
        tf = chess.square_file(white_passed); tr = 7
        for r_sq, r_p in rooks:
            if r_p.color == chess.BLACK:
                try:
                    if board.is_attacked_by(chess.BLACK, chess.square(tf, tr)) if hasattr(chess, 'square') else board.is_attacked_by(chess.BLACK, board.parse_square(chess.square_name(white_passed)[0] + '8')):
                        black_attack = 1.0
                        break
                except Exception:
                    for a in board.attackers(chess.BLACK, white_passed):
                        if board.piece_at(a) and board.piece_at(a).piece_type == chess.ROOK:
                            black_attack = 1.0
                            break
                    if black_attack:
                        break
    return float(white_attack - black_attack)

def feature(board: chess.Board) -> float:
    'Outpost and knight/bishop advanced-squares score: (White_outpost_score - Black_outpost_score). Rewards minor pieces on advanced central squares, penalizes knights on rim'
    try:
        score = 0.0
        for sq, piece in board.piece_map().items():
            if piece.piece_type not in (chess.KNIGHT, chess.BISHOP):
                continue
            r = chess.square_rank(sq)
            f = chess.square_file(sq)
            side = 1.0 if piece.color == chess.WHITE else -1.0
            # advanced if on ranks 4-6 for white (r>=4), for black r<=3
            advanced = 0.0
            if piece.color == chess.WHITE and r >= 4:
                advanced = 0.8
            if piece.color == chess.BLACK and r <= 3:
                advanced = 0.8
            # central files bonus (c/d/e/f)
            central_file_bonus = 0.0
            if 2 <= f <= 5:
                central_file_bonus = 0.5
            # knight on rim penalty
            rim_pen = 0.0
            if piece.piece_type == chess.KNIGHT and (f == 0 or f == 7):
                rim_pen = -0.6
            # outpost heuristic: if a friendly pawn supports the square (attacks it) and no opponent pawn attacks it
            outpost = 0.0
            try:
                # check if any friendly pawn attacks this square
                pawns_support = any((board.piece_at(sq2) is not None and board.piece_at(sq2).piece_type == chess.PAWN and board.piece_at(sq2).color == piece.color)
                                     for sq2 in board.attackers(piece.color, sq))
                enemy_pawn_attacks = any((board.piece_at(sq2) is not None and board.piece_at(sq2).piece_type == chess.PAWN and board.piece_at(sq2).color != piece.color)
                                         for sq2 in board.attackers(not piece.color, sq))
                if pawns_support and not enemy_pawn_attacks:
                    outpost = 1.2
            except Exception:
                outpost = 0.0
            piece_val = (0.9 if piece.piece_type == chess.KNIGHT else 0.7) * (advanced + central_file_bonus + outpost) + rim_pen
            score += side * piece_val
        return float(score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in average pairwise Manhattan distance among major pieces (queen+rooks) (white_avg - black_avg); lower means tighter coordination'
    pm = board.piece_map()
    def avg_pairwise_dist(squares):
        n = len(squares)
        if n < 2:
            return 8.0
        total = 0
        pairs = 0
        for i in range(n):
            for j in range(i+1, n):
                total += chess.square_distance(squares[i], squares[j])
                pairs += 1
        return total / pairs if pairs > 0 else 8.0
    white_maj = []
    black_maj = []
    for sq, pc in pm.items():
        if pc.piece_type in (chess.QUEEN, chess.ROOK):
            if pc.color == chess.WHITE:
                white_maj.append(sq)
            else:
                black_maj.append(sq)
    return float(avg_pairwise_dist(white_maj) - avg_pairwise_dist(black_maj))

def feature(board: chess.Board) -> float:
    'Difference in count of under-defended pieces (attacked by opponent more than defended by own side): white minus black'
    try:
        pm = board.piece_map()
        white_under = 0
        black_under = 0
        for sq, p in pm.items():
            opp = chess.BLACK if p.color == chess.WHITE else chess.WHITE
            attackers = board.attackers(opp, sq)
            defenders = board.attackers(p.color, sq)
            if len(attackers) > len(defenders):
                if p.color == chess.WHITE:
                    white_under += 1
                else:
                    black_under += 1
        return float(white_under - black_under)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn promotion threat difference: sum over passed pawns of (1.0 / distance_to_promotion), (White - Black)'
    try:
        def is_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            for other_sq, other_p in board.piece_map().items():
                if other_p.piece_type != chess.PAWN or other_p.color == color:
                    continue
                of = chess.square_file(other_sq)
                orr = chess.square_rank(other_sq)
                if abs(of - f) <= 1:
                    # for white pawn, opponent pawn ahead (or at) blocks passing
                    if color == chess.WHITE and orr > r:
                        return False
                    if color == chess.BLACK and orr < r:
                        return False
            return True
        score = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type != chess.PAWN:
                continue
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                dist = 7 - r
            else:
                dist = r
            if dist <= 0:
                continue
            if is_passed(sq, p.color):
                score += (1.0 / dist) if p.color == chess.WHITE else -(1.0 / dist)
        return float(score)
    except Exception:
        return 0.0

