def feature(board: chess.Board) -> float:
    'Trapped-piece metric: (white trapped pieces) - (black trapped pieces). A trapped piece = non-king piece with <=2 legal moves and attacked by enemy.'
    try:
        def trapped_count(color):
            other = not color
            b = board.copy()
            count = 0
            for sq, p in board.piece_map().items():
                if p.color != color or p.piece_type == chess.KING:
                    continue
                # count legal moves from this square for that color
                tb = board.copy()
                tb.turn = color
                mobility = 0
                for mv in tb.legal_moves:
                    if mv.from_square == sq:
                        mobility += 1
                        if mobility > 2:
                            break
                attacked = board.is_attacked_by(other, sq)
                if mobility <= 2 and attacked:
                    count += 1
            return count
        tw = trapped_count(chess.WHITE)
        tb = trapped_count(chess.BLACK)
        return float(tw - tb)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rook+Queen sliding mobility difference: (white attacked squares by rooks/queens - black) normalized by 64'
    try:
        pm = board.piece_map()
        occ = {sq: True for sq in range(64) if sq in pm}
        def sliding_attacks_from(sq, deltas):
            attacks = set()
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            for df, dr in deltas:
                cf, cr = f + df, r + dr
                while 0 <= cf < 8 and 0 <= cr < 8:
                    tsq = chess.square(cf, cr)
                    attacks.add(tsq)
                    if tsq in occ:
                        break
                    cf += df; cr += dr
            return attacks
        rook_dirs = [(1,0),(-1,0),(0,1),(0,-1)]
        bishop_dirs = [(1,1),(1,-1),(-1,1),(-1,-1)]
        w_att = set(); b_att = set()
        for sq, pc in pm.items():
            if pc.piece_type == chess.ROOK or pc.piece_type == chess.QUEEN:
                wset = sliding_attacks_from(sq, rook_dirs)
                if pc.color == chess.WHITE:
                    w_att.update(wset)
                else:
                    b_att.update(wset)
            if pc.piece_type == chess.BISHOP or pc.piece_type == chess.QUEEN:
                bset = sliding_attacks_from(sq, bishop_dirs)
                if pc.color == chess.WHITE:
                    w_att.update(bset)
                else:
                    b_att.update(bset)
        # But we want rook+queen mobility specifically: approximate by taking rook_dirs from rooks/queens only
        # restrict to rook-like squares
        def rook_like_attacks(color):
            s = set()
            for sq, pc in pm.items():
                if pc.color == color and (pc.piece_type == chess.ROOK or pc.piece_type == chess.QUEEN):
                    s.update(sliding_attacks_from(sq, rook_dirs))
            return s
        w_rq = rook_like_attacks(chess.WHITE)
        b_rq = rook_like_attacks(chess.BLACK)
        return float(len(w_rq) - len(b_rq)) / 64.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Files adjacent-to-king exposure: counts files among king file +/-1 that lack any friendly pawn (higher = more exposed); returns White_exposure - Black_exposure'
    try:
        def exposure_for(color):
            kingsq = None
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == color:
                    kingsq = sq
                    break
            if kingsq is None:
                return 0.0
            kf = chess.square_file(kingsq)
            files = [f for f in range(max(0, kf-1), min(7, kf+1)+1)]
            exposed = 0
            for f in files:
                has_pawn = False
                for r in range(0,8):
                    sq = r*8 + f
                    p = board.piece_at(sq)
                    if p and p.piece_type == chess.PAWN and p.color == color:
                        has_pawn = True
                        break
                if not has_pawn:
                    exposed += 1
            return float(exposed)
        return float(exposure_for(chess.WHITE) - exposure_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of immediate mate-in-one threats available to each side (Black mates - White mates). Positive means Black has more immediate mating moves.'
    try:
        mate_black = 0
        mate_white = 0
        # helper to count mates for a given side (create a board copy and set turn)
        try:
            bcopy = board.copy()
        except Exception:
            # fallback: try shallow copy via FEN
            try:
                bcopy = chess.Board(board.fen())
            except Exception:
                return 0.0
        for color in (chess.WHITE, chess.BLACK):
            try:
                b2 = bcopy.copy()
            except Exception:
                try:
                    b2 = chess.Board(bcopy.fen())
                except Exception:
                    continue
            b2.turn = color
            for mv in list(b2.legal_moves):
                try:
                    b3 = b2.copy()
                except Exception:
                    try:
                        b3 = chess.Board(b2.fen())
                    except Exception:
                        continue
                try:
                    b3.push(mv)
                except Exception:
                    continue
                if b3.is_checkmate():
                    if color == chess.WHITE:
                        mate_white += 1
                    else:
                        mate_black += 1
        return float(mate_black - mate_white)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Minor-piece outpost score: (White outpost score - Black outpost score). An outpost is a knight/bishop on a central-ish square not attacked by enemy pawns and optionally defended (+0.5 if defended)'
    piece_map = board.piece_map()
    white_score = 0.0
    black_score = 0.0
    for sq, p in piece_map.items():
        if p.piece_type not in (chess.KNIGHT, chess.BISHOP):
            continue
        r = chess.square_rank(sq)
        # central-ish ranks 2..5 (0-based). Slightly prefer central squares.
        if r < 2 or r > 5:
            continue
        enemy = chess.BLACK if p.color == chess.WHITE else chess.WHITE
        # check whether any enemy pawn attacks this square
        pawn_attackers = [a for a in board.attackers(enemy, sq) if piece_map.get(a) and piece_map[a].piece_type == chess.PAWN]
        if len(pawn_attackers) > 0:
            continue
        # base score
        val = 1.0
        # bonus if defended by friendly piece
        defenders = board.attackers(p.color, sq)
        if len(defenders) > 0:
            val += 0.5
        if p.color == chess.WHITE:
            white_score += val
        else:
            black_score += val
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Advanced passed pawn score (white minus black). Counts passed pawns and weights by advancement (squared normalized rank).'
    try:
        pm = board.piece_map()
        white_passed = 0.0
        black_passed = 0.0
        # Precompute pawn squares by color for quick checks
        pawns_white = [sq for sq, p in pm.items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        pawns_black = [sq for sq, p in pm.items() if p.piece_type == chess.PAWN and p.color == chess.BLACK]
        pawn_set_white = set(pawns_white)
        pawn_set_black = set(pawns_black)
        for sq in pawns_white:
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            blocked = False
            for bf in range(max(0, f - 1), min(7, f + 1) + 1):
                # any black pawn ahead on same/adj file with higher rank?
                for br in range(r + 1, 8):
                    if chess.square(bf, br) in pawn_set_black:
                        blocked = True
                        break
                if blocked:
                    break
            if not blocked:
                adv = r / 7.0
                white_passed += adv * adv
        for sq in pawns_black:
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            blocked = False
            for bf in range(max(0, f - 1), min(7, f + 1) + 1):
                for br in range(0, r):
                    if chess.square(bf, br) in pawn_set_white:
                        blocked = True
                        break
                if blocked:
                    break
            if not blocked:
                adv = (7 - r) / 7.0
                black_passed += adv * adv
        return float(white_passed - black_passed)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Capture swing potential: (white - black) sum over legal captures of positive material gains (captured value - capturer value, clipped at 0).'
    try:
        values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        w = b = 0.0
        # iterate legal moves and consider obvious captures where a piece currently exists on destination
        for move in board.legal_moves:
            to_sq = move.to_square
            capt = board.piece_at(to_sq)
            if capt is None:
                # try to handle en passant heuristically: the captured pawn would be behind to_sq for white captures by pawn
                try:
                    moving = board.piece_at(move.from_square)
                    if moving and moving.piece_type == chess.PAWN and abs(chess.square_rank(move.from_square) - chess.square_rank(move.to_square)) == 1:
                        # unlikely reliable; skip if no direct capture
                        continue
                    else:
                        continue
                except Exception:
                    continue
            mover = board.piece_at(move.from_square)
            if mover is None:
                continue
            gain = values.get(capt.piece_type, 0.0) - values.get(mover.piece_type, 0.0)
            if gain > 0.0:
                if mover.color == chess.WHITE:
                    w += gain
                else:
                    b += gain
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rook-to-opponent-king closeness difference: (8 - min_distance white rooks -> black king) - (8 - min_distance black rooks -> white king). Higher means white rooks closer relative to black.'
    try:
        pm = board.piece_map()
        white_rook_sqs = [sq for sq,p in pm.items() if p.piece_type==chess.ROOK and p.color==chess.WHITE]
        black_rook_sqs = [sq for sq,p in pm.items() if p.piece_type==chess.ROOK and p.color==chess.BLACK]
        white_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.WHITE), None)
        black_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.BLACK), None)
        MAX = 8.0
        def min_dist(rooks, target):
            if target is None or not rooks:
                return MAX
            m = MAX
            for r in rooks:
                d = chess.square_distance(r, target)
                if d < m:
                    m = d
            return float(m)
        wd = min_dist(white_rook_sqs, black_king_sq)
        bd = min_dist(black_rook_sqs, white_king_sq)
        return float((MAX - wd) - (MAX - bd))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Average weighted proximity of opponent major/minor pieces to each king: (Black pieces proximity to White king) - (White pieces proximity to Black king). Higher positive => Black pieces are closer to White king (bad for White).'
    try:
        values = {chess.PAWN:0.5, chess.KNIGHT:1.0, chess.BISHOP:1.0, chess.ROOK:1.5, chess.QUEEN:2.0, chess.KING:0.0}
        # find kings
        wking = None
        bking = None
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    wking = sq
                else:
                    bking = sq
        def proximity_sum(target_king_sq, attackers_color):
            if target_king_sq is None:
                return 0.0
            s = 0.0
            for sq, pc in board.piece_map().items():
                if pc.color != attackers_color:
                    continue
                if pc.piece_type == chess.KING:
                    continue
                d = chess.square_distance(sq, target_king_sq)
                # weight inverse to distance (closer -> more)
                s += values.get(pc.piece_type, 0.0) / (1.0 + float(d))
            return s

        black_on_white = proximity_sum(wking, chess.BLACK)
        white_on_black = proximity_sum(bking, chess.WHITE)
        return black_on_white - white_on_black
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Proportion of legal moves for the side to move that give check (forcing density) between 0 and 1'
    try:
        total = 0
        checks = 0
        for m in board.legal_moves:
            total += 1
            b = board.copy()
            b.push(m)
            if b.is_check():
                checks += 1
        if total == 0:
            return 0.0
        return float(checks) / float(total)
    except Exception:
        return 0.0

