def feature(board: chess.Board) -> float:
    'White minus Black: difference in Chebyshev distance from the side\'s king to its most advanced passed pawn\'s promotion square (smaller is better for that side). Returns (black_dist - white_dist).'
    try:
        pieces = board.piece_map()
    except Exception:
        return 0.0
    pawns = [(sq, p) for sq, p in pieces.items() if p.piece_type == chess.PAWN]
    kings = {p.color: sq for sq, p in pieces.items() if p.piece_type == chess.KING}
    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            for opp_sq, opp_piece in pawns:
                if opp_piece.color == chess.BLACK:
                    if abs(chess.square_file(opp_sq) - f) <= 1 and chess.square_rank(opp_sq) >= r:
                        return False
            return True
        else:
            for opp_sq, opp_piece in pawns:
                if opp_piece.color == chess.WHITE:
                    if abs(chess.square_file(opp_sq) - f) <= 1 and chess.square_rank(opp_sq) <= r:
                        return False
            return True
    white_passed = None
    black_passed = None
    for sq, p in pawns:
        if not is_passed(sq, p.color):
            continue
        if p.color == chess.WHITE:
            if white_passed is None or chess.square_rank(sq) > chess.square_rank(white_passed):
                white_passed = sq
        else:
            if black_passed is None or chess.square_rank(sq) < chess.square_rank(black_passed):
                black_passed = sq
    def cheb_dist_sq(a, b):
        if a is None or b is None:
            return 100.0
        af = chess.square_file(a); ar = chess.square_rank(a)
        bf = chess.square_file(b); br = chess.square_rank(b)
        return float(max(abs(af - bf), abs(ar - br)))
    d_w = 100.0
    d_b = 100.0
    if white_passed is not None:
        promo_sq = chess.square(chess.square_file(white_passed), 7) if hasattr(chess, 'square') else chess.parse_square(chess.square_name(white_passed)[0] + '8')
        # safer compute promo coords
        pf = chess.square_file(white_passed); pr = 7
        promo_coords = (pf, pr)
        wk = kings.get(chess.WHITE)
        if wk is not None:
            wf = chess.square_file(wk); wr = chess.square_rank(wk)
            d_w = float(max(abs(wf - promo_coords[0]), abs(wr - promo_coords[1])))
    if black_passed is not None:
        pf = chess.square_file(black_passed); pr = 0
        promo_coords = (pf, pr)
        bk = kings.get(chess.BLACK)
        if bk is not None:
            bf = chess.square_file(bk); br = chess.square_rank(bk)
            d_b = float(max(abs(bf - promo_coords[0]), abs(br - promo_coords[1])))
    return float(d_b - d_w)

def feature(board: chess.Board) -> float:
    'Combined pawn-structure weakness score: (doubled + isolated) pawns difference (white - black)'
    try:
        pm = board.piece_map()
        # count pawns per file
        files_white = [0]*8
        files_black = [0]*8
        pawns_white_squares = []
        pawns_black_squares = []
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if p.color == chess.WHITE:
                    files_white[f] += 1
                    pawns_white_squares.append(sq)
                else:
                    files_black[f] += 1
                    pawns_black_squares.append(sq)
        def weakness(files, pawn_sqs, color):
            doubled = sum(max(0, c-1) for c in files)
            isolated = 0
            for sq in pawn_sqs:
                f = chess.square_file(sq)
                left = f-1
                right = f+1
                has_neighbor = False
                if 0 <= left <= 7 and files[left] > 0:
                    has_neighbor = True
                if 0 <= right <= 7 and files[right] > 0:
                    has_neighbor = True
                if not has_neighbor:
                    isolated += 1
            return doubled + isolated
        wweak = weakness(files_white, pawns_white_squares, chess.WHITE)
        bweak = weakness(files_black, pawns_black_squares, chess.BLACK)
        return float(wweak - bweak)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material tropism: (white pieces weighted inverse-distance to black king) - (black pieces weighted inverse-distance to white king)'
    try:
        vals = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        # locate kings
        white_king = None
        black_king = None
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        if white_king is None or black_king is None:
            return 0.0
        score_w = 0.0
        score_b = 0.0
        for sq, p in board.piece_map().items():
            v = vals.get(p.piece_type, 0.0)
            if v == 0.0:
                continue
            if p.color == chess.WHITE:
                d = chess.square_distance(sq, black_king)
                score_w += v / (1.0 + float(d))
            else:
                d = chess.square_distance(sq, white_king)
                score_b += v / (1.0 + float(d))
        return float(score_w - score_b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in pawn shield strength around each king (white minus black). Counts friendly pawns on up to 3-files-by-3-ranks in front of each king.'
    try:
        pm = board.piece_map()
        white_shield = 0
        black_shield = 0
        for sq, piece in pm.items():
            if piece.piece_type != chess.KING:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if piece.color == chess.WHITE:
                # look forward (increasing rank) up to 2 ranks ahead and same rank
                for rf in range(r, min(7, r + 2) + 1):
                    for ff in range(max(0, f - 1), min(7, f + 1) + 1):
                        sq2 = chess.square(ff, rf)
                        p2 = board.piece_at(sq2)
                        if p2 is not None and p2.piece_type == chess.PAWN and p2.color == chess.WHITE:
                            white_shield += 1
            else:
                # black king: forward is decreasing rank
                for rf in range(max(0, r - 2), r + 1):
                    for ff in range(max(0, f - 1), min(7, f + 1) + 1):
                        sq2 = chess.square(ff, rf)
                        p2 = board.piece_at(sq2)
                        if p2 is not None and p2.piece_type == chess.PAWN and p2.color == chess.BLACK:
                            black_shield += 1
        return float(white_shield - black_shield)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Trapped high-value piece metric: sum over sides of (flag * piece_value) where flag=1 if highest-value piece has <=1 legal moves and is attacked more than defended; returns (white - black)'
    try:
        pm = board.piece_map()
        vals = {chess.QUEEN: 9.0, chess.ROOK: 5.0, chess.BISHOP: 3.0, chess.KNIGHT: 3.0, chess.PAWN: 1.0}
        def side_metric(color):
            # find highest-value piece square for color
            best_sq = None
            best_val = -1.0
            for s, p in pm.items():
                if p.color != color:
                    continue
                v = vals.get(p.piece_type, 0.0)
                if v > best_val:
                    best_val = v
                    best_sq = s
            if best_sq is None or best_val <= 0.0:
                return 0.0
            # count legal moves from that square
            legal_from = 0
            for mv in board.legal_moves:
                if mv.from_square == best_sq:
                    legal_from += 1
            attackers = len(board.attackers(not color, best_sq))
            defenders = len(board.attackers(color, best_sq))
            if legal_from <= 1 and (attackers - defenders) >= 1:
                return best_val
            return 0.0
        w = side_metric(chess.WHITE)
        b = side_metric(chess.BLACK)
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn structure penalty difference (doubled+isolated pawns penalized, passed pawns slightly rewarded): (White_penalty - Black_penalty)'
    pm = board.piece_map()
    def pawn_stats(color):
        files = [0]*8
        pawn_sqs = []
        for sq,p in pm.items():
            if p.piece_type==chess.PAWN and p.color==color:
                f = chess.square_file(sq)
                files[f] += 1
                pawn_sqs.append(sq)
        doubled = sum(max(0, c-1) for c in files)
        isolated = 0
        for f,c in enumerate(files):
            if c>0:
                if (f-1<0 or files[f-1]==0) and (f+1>7 or files[f+1]==0):
                    isolated += c
        # passed pawn detection
        passed = 0
        for sq in pawn_sqs:
            f = chess.square_file(sq); r = chess.square_rank(sq)
            blocked = False
            if color == chess.WHITE:
                for of in (f-1,f,f+1):
                    if 0<=of<=7:
                        # any black pawn on same/adjacent file with rank > r blocks
                        for rr in range(r+1,8):
                            p = board.piece_at(chess.square(of, rr))
                            if p is not None and p.piece_type==chess.PAWN and p.color==chess.BLACK:
                                blocked = True; break
                        if blocked: break
                if not blocked:
                    passed += 1
            else:
                for of in (f-1,f,f+1):
                    if 0<=of<=7:
                        for rr in range(0, r):
                            p = board.piece_at(chess.square(of, rr))
                            if p is not None and p.piece_type==chess.PAWN and p.color==chess.WHITE:
                                blocked = True; break
                        if blocked: break
                if not blocked:
                    passed += 1
        penalty = 0.5 * doubled + 0.5 * isolated - 0.3 * passed
        return penalty
    return float(pawn_stats(chess.WHITE) - pawn_stats(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Net attack pressure on squares adjacent to each king (white minus black)'
    try:
        pm = board.piece_map()
