            r = chess.square_rank(sq)
            for bp in black_pawns:
                bf = chess.square_file(bp)
                br = chess.square_rank(bp)
                if abs(bf - f) <= 1 and br > r:
                    return False
            return True
        def is_black_passed(sq):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            for wp in white_pawns:
                wf = chess.square_file(wp)
                wr = chess.square_rank(wp)
                if abs(wf - f) <= 1 and wr < r:
                    return False
            return True
        wp = sum(1 for sq in white_pawns if is_white_passed(sq))
        bp = sum(1 for sq in black_pawns if is_black_passed(sq))
        return float(wp - bp)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Sum of weighted enemy attackers on squares within a 2-square Manhattan radius of each king (Black pressure on White minus White pressure on Black)'
