def feature(board: chess.Board) -> float:
    'Difference in "bad bishop" score: average fraction of same-colored pawns for bishops of each side (higher = more blocked/bad). Returns (White bad-bishop avg) - (Black bad-bishop avg).'
    try:
        pm = board.piece_map()
        def square_color(square):
            return (chess.square_file(square) + chess.square_rank(square)) & 1  # 0 or 1
        def bad_bishop_avg(color):
            bishops = [sq for sq,p in pm.items() if p.color==color and p.piece_type==chess.BISHOP]
            if not bishops:
                return 0.0
            pawns_same_color = 0
            total_pawns = 0
            for sq,p in pm.items():
                if p.piece_type == chess.PAWN and p.color == color:
                    total_pawns += 1
            # For each bishop, count how many friendly pawns sit on same square color
            total_fraction = 0.0
            for b in bishops:
                sc = square_color(b)
                same = 0
                for sq,p in pm.items():
                    if p.piece_type==chess.PAWN and p.color==color:
                        if square_color(sq) == sc:
                            same += 1
                # fraction of friendly pawns on same color (if no pawns, fraction = 0)
                frac = (same / total_pawns) if total_pawns > 0 else 0.0
                total_fraction += frac
            return total_fraction / len(bishops)
        return float(bad_bishop_avg(chess.WHITE) - bad_bishop_avg(chess.BLACK))
    except Exception:
        return 0.0

