def feature(board: chess.Board) -> float:
    'Queen vs rooks+minor material gap: (Q - (R+N+B)) weighted, White minus Black, highlights lone-queen or queen advantage'
    try:
        counts = {chess.WHITE: {chess.QUEEN:0, chess.ROOK:0, chess.BISHOP:0, chess.KNIGHT:0},
                  chess.BLACK: {chess.QUEEN:0, chess.ROOK:0, chess.BISHOP:0, chess.KNIGHT:0}}
        for sq, p in board.piece_map().items():
            if p.piece_type in counts[chess.WHITE]:
                counts[p.color][p.piece_type] += 1
        def score(col):
            return (counts[col][chess.QUEEN]*9.0) - (counts[col][chess.ROOK]*5.0 + counts[col][chess.BISHOP]*3.0 + counts[col][chess.KNIGHT]*3.0)
        return float(score(chess.WHITE) - score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of safe escape squares for each king (white_safe - black_safe), counting adjacent squares not occupied by same color and not attacked by opponent'
    try:
        pm = board.piece_map()
        def safe_squares(king_color):
            king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == king_color), None)
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            safe = 0
            opponent = not king_color
            for df in (-1,0,1):
                for dr in (-1,0,1):
                    if df == 0 and dr == 0:
                        continue
                    nf = kf + df
                    nr = kr + dr
                    if not (0 <= nf <= 7 and 0 <= nr <= 7):
                        continue
                    nsq = chess.square(nf, nr)
                    occupant = board.piece_at(nsq)
                    if occupant is not None and occupant.color == king_color:
                        continue
                    # square must not be attacked by opponent to be considered safe
                    try:
                        attacked = board.is_attacked_by(opponent, nsq)
                    except Exception:
                        attacked = False
                    if not attacked:
                        safe += 1
            return float(safe)
        return safe_squares(chess.WHITE) - safe_squares(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Promotion urgency difference: (black moves to promotion) - (white moves to promotion) for the most advanced passed pawns'
    def is_passed(sq, color):
        if not board.piece_at(sq) or board.piece_at(sq).piece_type != chess.PAWN:
            return False
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            for af in range(max(0, f-1), min(7, f+1)+1):
                for ar in range(r+1, 8):
                    p = board.piece_at(chess.square(af, ar))
                    if p and p.piece_type == chess.PAWN and p.color == chess.BLACK:
                        return False
            return True
        else:
            for af in range(max(0, f-1), min(7, f+1)+1):
                for ar in range(0, r):
                    p = board.piece_at(chess.square(af, ar))
                    if p and p.piece_type == chess.PAWN and p.color == chess.WHITE:
                        return False
            return True
    white_min_moves = 100
    black_min_moves = 100
    for sq, piece in board.piece_map().items():
        if piece.piece_type == chess.PAWN:
            r = chess.square_rank(sq)
            if piece.color == chess.WHITE and is_passed(sq, chess.WHITE):
                moves = 7 - r
                if moves < white_min_moves:
                    white_min_moves = moves
            if piece.color == chess.BLACK and is_passed(sq, chess.BLACK):
                moves = r - 0
                if moves < black_min_moves:
                    black_min_moves = moves
    # higher means white closer to promotion (positive favors white)
    if white_min_moves == 100 and black_min_moves == 100:
        return 0.0
    if white_min_moves == 100:
        return float(-black_min_moves)
    if black_min_moves == 100:
        return float(white_min_moves)
    return float(black_min_moves - white_min_moves)

