def feature(board: chess.Board) -> float:
    'Difference in bishop effectiveness: (white bishop mobility minus penalty for same-color pawns) - (black equivalent)'
    piece_map = board.piece_map()
    # helper to compute bishop mobility (pseudo-legal)
    bishop_deltas = ((1,1),(1,-1),(-1,1),(-1,-1))
    def bishop_mobility(sq):
        sf = chess.square_file(sq)
        sr = chess.square_rank(sq)
        mobility = 0
        for df, dr in bishop_deltas:
            nf = sf + df
            nr = sr + dr
            while 0 <= nf <= 7 and 0 <= nr <= 7:
                name = chr(ord('a') + nf) + str(nr + 1)
                s = chess.parse_square(name)
                p = board.piece_at(s)
                if p is None:
                    mobility += 1
                else:
                    # capture then stop
                    if p.color != piece_map[sq].color:
                        mobility += 1
                    break
                nf += df
                nr += dr
        return mobility
    def square_color(sq):
        return (chess.square_file(sq) + chess.square_rank(sq)) & 1
    white_score = 0.0
    black_score = 0.0
    # count pawns on light/dark squares per color
    pawn_color_count = { (chess.WHITE,0):0, (chess.WHITE,1):0, (chess.BLACK,0):0, (chess.BLACK,1):0 }
    for sq, pc in piece_map.items():
        if pc.piece_type == chess.PAWN:
            pawn_color_count[(pc.color, square_color(sq))] += 1
    for sq, pc in piece_map.items():
        if pc.piece_type == chess.BISHOP:
            mob = bishop_mobility(sq)
            same_color_pawns = pawn_color_count.get((pc.color, square_color(sq)), 0)
            score = float(mob) - 0.5 * float(same_color_pawns)
            if pc.color == chess.WHITE:
                white_score += score
            else:
                black_score += score
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
