def feature(board: chess.Board) -> float:
    'Net minimum manhattan distance of any non-king friendly piece to the opposing king (black_min - white_min). Smaller means more immediate pressure.'
    try:
        import chess
        piece_map = board.piece_map()
        white_king = None
        black_king = None
        white_min = 100
        black_min = 100
        for sq, pc in piece_map.items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        for sq, pc in piece_map.items():
            if pc.piece_type == chess.KING:
                continue
            if pc.color == chess.WHITE and black_king is not None:
                d = chess.square_distance(sq, black_king)
                if d < white_min:
                    white_min = d
            if pc.color == chess.BLACK and white_king is not None:
                d = chess.square_distance(sq, white_king)
                if d < black_min:
                    black_min = d
        if white_min == 100:
            white_min = 100.0
        if black_min == 100:
            black_min = 100.0
        return float(black_min - white_min)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net attack pressure on squares adjacent to each king (white minus black)'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.BLACK), None)
        def adjacent_squares(sq):
            if sq is None:
                return []
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            res = []
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    nf = f + df
                    nr = r + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        res.append(chess.square(nf, nr))
            return res
        white_pressure = 0
        black_pressure = 0
        for adj in adjacent_squares(white_king_sq):
            white_pressure += len(board.attackers(chess.BLACK, adj))
        for adj in adjacent_squares(black_king_sq):
            black_pressure += len(board.attackers(chess.WHITE, adj))
        return float(white_pressure - black_pressure)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Nearest passed pawn proximity to enemy king: (white - black) inverse distance score to opponent king (higher = closer threat).'
    try:
        def is_passed_pawn(sq, color):
            # basic passed pawn check: no enemy pawns on same file or adjacent files ahead of this pawn
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            enemy = not color
            if color == chess.WHITE:
                ahead_ranks = range(r+1, 8)
            else:
                ahead_ranks = range(0, r)
            for af in (f-1, f, f+1):
                if 0 <= af <= 7:
                    for ar in ahead_ranks:
                        p = board.piece_at(chess.square(af, ar))
                        if p and p.piece_type == chess.PAWN and p.color == enemy:
                            return False
            return True
        def best_proximity(color):
            # proximity of this color's passed pawn to opponent king, return inverse distance (10 - dist) clipped
            king_sq = None
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == (not color):
                    king_sq = sq
                    break
            if king_sq is None:
                return 0.0
            best = 100
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.PAWN and p.color == color and is_passed_pawn(sq, color):
                    d = chess.square_distance(sq, king_sq)
                    if d < best:
                        best = d
            if best == 100:
                return 0.0
            score = max(0.0, 10.0 - float(best))
            return score
        return float(best_proximity(chess.WHITE) - best_proximity(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net attacker pressure on opponent pieces: sum_over_opponent_pieces(len(attackers)) difference (White - Black) normalized'
    try:
        pm = board.piece_map()
        white_on_black = 0
        black_on_white = 0
        for sq, p in pm.items():
            if p.color == chess.BLACK:
                white_on_black += len(board.attackers(chess.WHITE, sq))
            else:
                black_on_white += len(board.attackers(chess.BLACK, sq))
        # normalize to keep values small
        return float((white_on_black - black_on_white) / 10.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in attacking cluster density: (pressure on white king minus pressure on black king). Pressure is inverse average Manhattan distance of opponent non-pawn pieces to the king.'
    try:
        pm = board.piece_map()
        white_king = None
        black_king = None
        white_attackers = []
        black_attackers = []
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        if white_king is None or black_king is None:
            return 0.0
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN or p.piece_type == chess.KING:
                continue
            if p.color == chess.WHITE:
                white_attackers.append(sq)
            else:
                black_attackers.append(sq)
        def pressure(attacker_list, target):
            if not attacker_list:
                return 0.0
            s = 0.0
            for a in attacker_list:
                d = chess.square_distance(a, target)
                s += d
            avg = s / len(attacker_list)
            return 1.0 / (avg + 0.1)
        pressure_on_white = pressure(black_attackers, white_king)
        pressure_on_black = pressure(white_attackers, black_king)
        return float(pressure_on_white - pressure_on_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in legal king moves: (white king legal moves) - (black king legal moves); positive favors White'
    try:
