def feature(board: chess.Board) -> float:
    'Piece coordination: (Black_avg_pairwise_distance - White_avg_pairwise_distance) among non-pawn, non-king pieces; positive means White pieces are more clustered (better coordination)'
    pm = board.piece_map()
    def avg_pairwise(c):
        coords = []
        for sq, pc in pm.items():
            if pc.color == c and pc.piece_type not in (chess.PAWN, chess.KING):
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                coords.append((f, r))
        n = len(coords)
        if n <= 1:
            return 0.0
        total = 0.0
        count = 0
        for i in range(n):
            for j in range(i+1, n):
                total += abs(coords[i][0] - coords[j][0]) + abs(coords[i][1] - coords[j][1])
                count += 1
        return total / count
    white_avg = avg_pairwise(chess.WHITE)
    black_avg = avg_pairwise(chess.BLACK)
    return black_avg - white_avg

def feature(board: chess.Board) -> float:
    'Minor piece centrality difference (White minus Black): sums centrality of knights and bishops by inverse distance to center'
    try:
        center_files = [3.5, 3.5]  # conceptual center at file 3.5, rank 3.5
        result_w = 0.0
        result_b = 0.0
        pm = board.piece_map()
        for sq, p in pm.items():
            if p.piece_type in (chess.KNIGHT, chess.BISHOP):
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                # Euclidean-ish centrality: smaller distance -> larger score
                df = (f - 3.5)
                dr = (r - 3.5)
                dist = (df*df + dr*dr) ** 0.5 + 0.001
                weight = 1.5 if p.piece_type == chess.KNIGHT else 1.0
                score = weight * (1.0 / dist)
                if p.color == chess.WHITE:
                    result_w += score
                else:
                    result_b += score
        return float(result_w - result_b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in average knight centralization (black_avg - white_avg). Uses Manhattan distance to board center (3.5,3.5); smaller is more centralized.'
    piece_map = board.piece_map()
    def avg_knight_dist(color):
        total = 0.0
        count = 0
        for sq, p in piece_map.items():
            if p.piece_type != chess.KNIGHT or p.color != color:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            dist = abs(f - 3.5) + abs(r - 3.5)
            total += dist
            count += 1
        if count == 0:
            return 10.0
        return total / count
    return float(avg_knight_dist(chess.BLACK) - avg_knight_dist(chess.WHITE))

def feature(board: chess.Board) -> float:
