    return float(white_threats - black_threats)

def feature(board: chess.Board) -> float:
    'Passed pawn promotion potential difference: weighted sum (White - Black) of pawn proximity to promotion adjusted for opposing pawn blockades'
    import chess
    try:
        piece_map = board.piece_map()
        def pawn_promo_potential(color):
            total = 0.0
            for sq, p in piece_map.items():
                if p.piece_type != chess.PAWN or p.color != color:
                    continue
                file = chess.square_file(sq)
                rank = chess.square_rank(sq)
                if color == chess.WHITE:
                    distance = 7 - rank
                    direction = 1
                    opponent = chess.BLACK
                    ahead_ranks = range(rank+1, 8)
                else:
                    distance = rank - 0
                    direction = -1
                    opponent = chess.WHITE
                    ahead_ranks = range(rank-1, -1, -1)
                base = max(0.0, (8 - distance) / 8.0)  # closer -> higher (0..1)
                # check if any opposing pawn exists on same file or adjacent files in front of this pawn (would block)
                blockade = 0.0
                for f in (file-1, file, file+1):
                    if 0 <= f <= 7:
                        for r in ahead_ranks:
                            sq2 = chess.square(f, r)
                            p2 = piece_map.get(sq2)
                            if p2 and p2.piece_type == chess.PAWN and p2.color == opponent:
                                # earlier blockers penalize potential
                                blockade += 1.0
                                break
                # passed pawn bonus if no opposing pawn in front or adjacent files
                passed_bonus = 0.7 if blockade == 0.0 else 0.0
                # weight by advancement and passed status, clipped
                score = base * (0.5 + passed_bonus) - 0.2 * min(blockade, 3.0)
                total += score
            return total
        return float(pawn_promo_potential(chess.WHITE) - pawn_promo_potential(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn advancement difference: sum of passed pawn advancement weights (0..1) for White minus Black'
    try:
        pawns = [ (sq,p) for sq,p in board.piece_map().items() if p.piece_type == chess.PAWN ]
        white_pass = 0.0
        black_pass = 0.0
        # precompute enemy pawn squares by file and rank
        black_pawn_files_ranks = [(chess.square_file(sq), chess.square_rank(sq)) for sq,p in pawns if p.color == chess.BLACK]
        white_pawn_files_ranks = [(chess.square_file(sq), chess.square_rank(sq)) for sq,p in pawns if p.color == chess.WHITE]
        for sq, p in pawns:
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                blocked = False
                for ef, er in black_pawn_files_ranks:
                    if abs(ef - f) <= 1 and er > r:
                        blocked = True
                        break
                if not blocked:
                    # advancement weight: 0 at rank1 up to 1 at rank7 (index 6)
                    weight = r / 6.0
                    white_pass += weight
            else:
                blocked = False
                for ef, er in white_pawn_files_ranks:
                    if abs(ef - f) <= 1 and er < r:
                        blocked = True
                        break
                if not blocked:
                    # black advancement weight: 0 at rank8(index7) to 1 at rank2(index1)
                    weight = (7 - r) / 6.0
                    black_pass += weight
        return float(white_pass - black_pass)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Capture swing potential: (white - black) sum over legal captures of positive material gains (captured value - capturer value, clipped at 0).'
    try:
        values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        w = b = 0.0
        # iterate legal moves and consider obvious captures where a piece currently exists on destination
        for move in board.legal_moves:
            to_sq = move.to_square
            capt = board.piece_at(to_sq)
            if capt is None:
                # try to handle en passant heuristically: the captured pawn would be behind to_sq for white captures by pawn
                try:
                    moving = board.piece_at(move.from_square)
                    if moving and moving.piece_type == chess.PAWN and abs(chess.square_rank(move.from_square) - chess.square_rank(move.to_square)) == 1:
                        # unlikely reliable; skip if no direct capture
                        continue
                    else:
                        continue
                except Exception:
                    continue
            mover = board.piece_at(move.from_square)
            if mover is None:
                continue
            gain = values.get(capt.piece_type, 0.0) - values.get(mover.piece_type, 0.0)
            if gain > 0.0:
                if mover.color == chess.WHITE:
                    w += gain
                else:
                    b += gain
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in heavy-piece (rooks+queens) mobility: (white mobility) - (black mobility)'
    try:
        heavy = {chess.ROOK, chess.QUEEN}
        def mobility_for(color):
            b = board.copy()
            b.turn = color
            count = 0
            for mv in b.legal_moves:
                p = b.piece_at(mv.from_square)
                if p is not None and p.piece_type in heavy and p.color == color:
                    count += 1
            return count
        wm = mobility_for(chess.WHITE)
        bm = mobility_for(chess.BLACK)
        return float(wm - bm)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Local material imbalance around kings: (material of White pieces within Chebyshev distance 3 of Black king) - (material of Black pieces within distance 3 of White king), normalized by 1000'
    vals = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    pm = board.piece_map()
    def king_sq(color):
        for sq,p in pm.items():
            if p.piece_type==chess.KING and p.color==color:
                return sq
        return None
    def material_near(king_sq, by_color):
        if king_sq is None:
            return 0
        total = 0
        kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
        for sq,p in pm.items():
            if p.color==by_color:
                df = abs(chess.square_file(sq)-kf)
                dr = abs(chess.square_rank(sq)-kr)
                if max(df,dr) <= 3:
                    total += vals.get(p.piece_type,0)
        return total
    w_near_bking = material_near(king_sq(chess.BLACK), chess.WHITE)
    b_near_wking = material_near(king_sq(chess.WHITE), chess.BLACK)
    return float(w_near_bking - b_near_wking) / 1000.0

def feature(board: chess.Board) -> float:
    'Indicator of immediate mate-in-one availability: 1.0 if White has mate in one, -1.0 if Black has mate in one, 0.0 otherwise (checks both sides regardless of current turn)'
    # Check for mate-in-one for a given color by temporarily setting turn to that color and trying moves
    for color, out in ((chess.WHITE, 1.0), (chess.BLACK, -1.0)):
        try:
            b = board.copy()
            b.turn = color
            for mv in b.legal_moves:
                b2 = b.copy()
                b2.push(mv)
                if b2.is_checkmate():
                    return float(out)
        except Exception:
            # some exotic positions might raise; treat as no mate found
            continue
    return 0.0

def feature(board: chess.Board) -> float:
    'Normalized mobility difference: (White legal moves - Black legal moves) / (total + 1)'
    try:
        # count white moves
        bcopy = board.copy()
    except Exception:
        bcopy = None
    # current side moves
    try:
        moves_current = sum(1 for _ in board.legal_moves)
    except Exception:
        moves_current = 0
    # count moves for both colors by flipping turn on a copy
    try:
        if bcopy is None:
            # fallback: if copy not available, try toggling attribute (but avoid changing original)
            bcopy = board.copy()
        bcopy.turn = chess.WHITE
        white_moves = sum(1 for _ in bcopy.legal_moves)
        bcopy.turn = chess.BLACK
        black_moves = sum(1 for _ in bcopy.legal_moves)
    except Exception:
        # fallback: approximate using current side and zero for other
        if board.turn==chess.WHITE:
            white_moves = moves_current; black_moves = 0
        else:
            black_moves = moves_current; white_moves = 0
    denom = float(max(1, white_moves + black_moves))
    return float((white_moves - black_moves) / denom)

def feature(board: chess.Board) -> float:
    'Endgame indicator: if only kings, bishops and pawns remain, return (pawn_count_white - pawn_count_black) + 0.5*(white_has_bishop - black_has_bishop), else 0'
    piece_map = board.piece_map()
    non_kbp = 0
    white_pawns = 0
    black_pawns = 0
    white_bishop = 0
    black_bishop = 0
    for sq, p in piece_map.items():
        if p.piece_type in (chess.KING, chess.BISHOP, chess.PAWN):
            if p.piece_type == chess.PAWN:
                if p.color == chess.WHITE:
                    white_pawns += 1
                else:
                    black_pawns += 1
            if p.piece_type == chess.BISHOP:
                if p.color == chess.WHITE:
                    white_bishop += 1
                else:
                    black_bishop += 1
        else:
            non_kbp += 1
    if non_kbp > 0:
        return 0.0
    return float((white_pawns - black_pawns) + 0.5 * (1 if white_bishop > 0 else 0) - 0.5 * (1 if black_bishop > 0 else 0))

def feature(board: chess.Board) -> float:
    'Material weighted by piece activity: sum over pieces of (base_value * (1 + 0.1 * mobility)) for White minus Black; mobility is reachable/capture squares for that piece'
    try:
        pm = board.piece_map()
        values = {chess.PAWN:1.0, chess.KNIGHT:3.2, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        def piece_mobility(sq, piece):
            pt = piece.piece_type
            color = piece.color
            sf = chess.square_file(sq)
            sr = chess.square_rank(sq)
            mob = 0
            if pt == chess.KNIGHT:
                for df, dr in ((1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)):
                    f = sf + df; r = sr + dr
                    if 0 <= f < 8 and 0 <= r < 8:
                        target = f + r*8
                        occ = board.piece_at(target)
                        if occ is None or occ.color != color:
                            mob += 1
            elif pt == chess.KING:
                for df in (-1,0,1):
                    for dr in (-1,0,1):
                        if df == 0 and dr == 0:
                            continue
                        f = sf + df; r = sr + dr
                        if 0 <= f < 8 and 0 <= r < 8:
                            target = f + r*8
                            occ = board.piece_at(target)
                            if occ is None or occ.color != color:
                                mob += 1
            elif pt == chess.PAWN:
                # count pawn capture squares
                if color == chess.WHITE:
                    for df in (-1,1):
                        f = sf + df; r = sr + 1
                        if 0 <= f < 8 and 0 <= r < 8:
                            target = f + r*8
                            occ = board.piece_at(target)
                            if occ is None or occ.color != color:
                                mob += 1
                else:
                    for df in (-1,1):
                        f = sf + df; r = sr - 1
                        if 0 <= f < 8 and 0 <= r < 8:
                            target = f + r*8
                            occ = board.piece_at(target)
                            if occ is None or occ.color != color:
                                mob += 1
            else:
                # sliding pieces: bishop, rook, queen
                directions = []
                if pt in (chess.BISHOP, chess.QUEEN):
                    directions += [(1,1),(1,-1),(-1,1),(-1,-1)]
                if pt in (chess.ROOK, chess.QUEEN):
                    directions += [(1,0),(-1,0),(0,1),(0,-1)]
                for df, dr in directions:
                    f = sf + df; r = sr + dr
                    while 0 <= f < 8 and 0 <= r < 8:
                        target = f + r*8
                        occ = board.piece_at(target)
                        if occ is None:
                            mob += 1
                            f += df; r += dr
                            continue
                        else:
                            if occ.color != color:
                                mob += 1
                            break
            return mob
        white_sum = 0.0
        black_sum = 0.0
        for s, p in pm.items():
            base = values.get(p.piece_type, 0.0)
            mob = piece_mobility(s, p)
            val = base * (1.0 + 0.1 * mob)
            if p.color == chess.WHITE:
                white_sum += val
            else:
                black_sum += val
        return float(white_sum - black_sum)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
