    black_bishop = 0
    for sq, p in piece_map.items():
        if p.piece_type in (chess.KING, chess.BISHOP, chess.PAWN):
            if p.piece_type == chess.PAWN:
                if p.color == chess.WHITE:
                    white_pawns += 1
                else:
                    black_pawns += 1
            if p.piece_type == chess.BISHOP:
                if p.color == chess.WHITE:
                    white_bishop += 1
                else:
                    black_bishop += 1
        else:
            non_kbp += 1
    if non_kbp > 0:
        return 0.0
    return float((white_pawns - black_pawns) + 0.5 * (1 if white_bishop > 0 else 0) - 0.5 * (1 if black_bishop > 0 else 0))

def feature(board: chess.Board) -> float:
    'For passed pawns, compares enemy king vs enemy rook proximity: sum over white passed pawns of (enemy_king_dist - enemy_rook_dist) minus same for black passed pawns'
    try:
        piece_map = board.piece_map()
        pawns_by_color = {chess.WHITE: [], chess.BLACK: []}
        for sq, p in piece_map.items():
            if p.piece_type == chess.PAWN:
                pawns_by_color[p.color].append(sq)
        # helper to detect passed as before
        black_pawn_files_by_rank = {}
        white_pawn_files_by_rank = {}
        for sq in pawns_by_color[chess.BLACK]:
            f = chess.square_file(sq); r = chess.square_rank(sq)
            black_pawn_files_by_rank.setdefault(f, []).append(r)
        for sq in pawns_by_color[chess.WHITE]:
            f = chess.square_file(sq); r = chess.square_rank(sq)
            white_pawn_files_by_rank.setdefault(f, []).append(r)
        def is_passed_white(sq):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            for df in (-1,0,1):
                ff = f+df
                if 0 <= ff < 8:
                    for br in black_pawn_files_by_rank.get(ff, []):
                        if br > r:
                            return False
            return True
        def is_passed_black(sq):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            for df in (-1,0,1):
                ff = f+df
                if 0 <= ff < 8:
                    for wr in white_pawn_files_by_rank.get(ff, []):
                        if wr < r:
                            return False
            return True
        # lists of enemy kings and rooks
        wk = bk = None
        white_rooks = []
        black_rooks = []
        for sq, p in piece_map.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE: wk = sq
                else: bk = sq
            if p.piece_type == chess.ROOK:
                if p.color == chess.WHITE: white_rooks.append(sq)
                else: black_rooks.append(sq)
        score = 0.0
        # for each white passed pawn, enemy is black
        for sq in pawns_by_color[chess.WHITE]:
            if is_passed_white(sq):
                rook_dist = min((chess.square_distance(sq, rr) for rr in black_rooks), default=99)
                king_dist = chess.square_distance(sq, bk) if bk is not None else 99
                score += float(king_dist - rook_dist)
        # for each black passed pawn, enemy is white -> subtract (king_dist - rook_dist)
        for sq in pawns_by_color[chess.BLACK]:
            if is_passed_black(sq):
                rook_dist = min((chess.square_distance(sq, rr) for rr in white_rooks), default=99)
                king_dist = chess.square_distance(sq, wk) if wk is not None else 99
                score -= float(king_dist - rook_dist)
        return float(score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net value of "trapped" pieces: pieces that are attacked and have ≤1 legal squares to move to when it is their side to move (Black - White), in centipawn units'
    values = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0, chess.KING:20000.0}
    pm = board.piece_map()
    trapped_white = 0.0
    trapped_black = 0.0
    for sq,p in pm.items():
        if p is None: continue
        color = p.color
        enemy = not color
        attackers = board.attackers(enemy, sq)
        if len(attackers)==0:
            continue
        # count legal moves for that piece if that side were to move
        try:
            bcopy = board.copy()
            bcopy.turn = color
            moves_from = 0
            for m in bcopy.legal_moves:
                if m.from_square == sq:
                    moves_from += 1
            if moves_from <= 1:
                if color==chess.WHITE:
                    trapped_white += values.get(p.piece_type,0.0)
                else:
                    trapped_black += values.get(p.piece_type,0.0)
        except Exception:
            # fallback: if we cannot copy, use 0 or heuristic
            # treat as not trapped
            continue
    # return Black - White (positive means Black has more trapped material => worse for Black)
    return float(trapped_black - trapped_white)

def feature(board: chess.Board) -> float:
    '2. Does the opponent have a checkmate in one (i.e., a mate-on-their-next-move)? (1.0 if yes, 0.0 otherwise)'
    try:
        b2 = board.copy()
        b2.turn = not b2.turn
        for mv in b2.legal_moves:
            b3 = b2.copy()
            b3.push(mv)
            if b3.is_checkmate():
                return 1.0
    except Exception:
        pass
    return 0.0

def feature(board: chess.Board) -> float:
    'Difference in minimal pawn promotion distance (black_min - white_min). Smaller for side closer to promotion.'
    try:
        INF = 12.0
        w_min = INF
        b_min = INF
        for sq, piece in board.piece_map().items():
            if piece.piece_type != chess.PAWN:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if piece.color == chess.WHITE:
                if r >= 7:
                    d = 0.0
                else:
                    d = 7 - r
                    # penalize if directly blocked
                    forward_sq = None
                    if r + 1 <= 7:
                        forward_sq = chess.square(f, r + 1)
                    if forward_sq is not None and board.piece_at(forward_sq) is not None:
                        d += 4.0
                w_min = min(w_min, d)
            else:
                if r <= 0:
                    d = 0.0
                else:
                    d = r
                    forward_sq = None
                    if r - 1 >= 0:
                        forward_sq = chess.square(f, r - 1)
                    if forward_sq is not None and board.piece_at(forward_sq) is not None:
                        d += 4.0
                b_min = min(b_min, d)
        if w_min == INF:
            w_min = 12.0
        if b_min == INF:
            b_min = 12.0
        return float(b_min - w_min)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Minor-piece centralization: sum of centrality (knights and bishops) white - black, higher means more centralized pieces'
    import math
    try:
        pm = board.piece_map()
        center_x = 3.5
        center_y = 3.5
        def centrality(sq):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            d = math.hypot(f - center_x, r - center_y)
            # max possible distance ~5.0 -> scale to a roughly 0..4 range
            return max(0.0, 4.0 - d)
        white_sum = 0.0
        black_sum = 0.0
        for sq, p in pm.items():
            if p.piece_type in (chess.KNIGHT, chess.BISHOP):
                if p.color == chess.WHITE:
                    white_sum += centrality(sq)
                else:
                    black_sum += centrality(sq)
        return float(white_sum - black_sum)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Trapped piece count difference: number of non-king pieces with no legal non-attacked destination (white - black)'
    try:
        pm = board.piece_map()
        white_trapped = 0.0
        black_trapped = 0.0
        # Precompute legal moves grouped by from_square
        moves_by_from = {}
        for m in board.legal_moves:
            moves_by_from.setdefault(m.from_square, []).append(m.to_square)
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                continue
            dests = moves_by_from.get(sq, [])
            if not dests:
                # no legal moves from this piece -> trapped
                if p.color == chess.WHITE:
                    white_trapped += 1.0
                else:
                    black_trapped += 1.0
            else:
                opp = not p.color
                # if all destinations are attacked by opponent, consider trapped
                all_attacked = True
                for to_sq in dests:
                    if not board.is_attacked_by(opp, to_sq):
                        all_attacked = False
                        break
                if all_attacked:
                    if p.color == chess.WHITE:
                        white_trapped += 1.0
                    else:
                        black_trapped += 1.0
        return float(white_trapped - black_trapped)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of rooks on semi-open files (no friendly pawns on that file): white - black'
    try:
        # build pawn file maps
        pawn_files_white = set()
        pawn_files_black = set()
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                if p.color == chess.WHITE:
                    pawn_files_white.add(chess.square_file(sq))
                else:
                    pawn_files_black.add(chess.square_file(sq))
        white_semiopen = 0
        black_semiopen = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                if p.color == chess.WHITE:
                    if f not in pawn_files_white:
                        white_semiopen += 1
                else:
                    if f not in pawn_files_black:
                        black_semiopen += 1
        return float(white_semiopen - black_semiopen)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'White minus Black material concentration index: (heavy - light)/total where heavy = Q+R, light = N+B+P (in centipawns), normalized'
    vals = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900}
    def concentration(color: bool) -> float:
        heavy = 0
        light = 0
        for p in board.piece_map().values():
            if p.color != color:
                continue
            if p.piece_type in (chess.QUEEN, chess.ROOK):
                heavy += vals.get(p.piece_type, 0)
            elif p.piece_type in (chess.KNIGHT, chess.BISHOP, chess.PAWN):
                light += vals.get(p.piece_type, 0)
        total = heavy + light
        if total == 0:
            return 0.0
        return float((heavy - light) / total)
    return float(concentration(chess.WHITE) - concentration(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Net coordination advantage: (white_coord - black_coord) where coord = number of target squares attacked by two or more friendly pieces, indicating tactical cooperation'
    try:
        coord_white = 0
        coord_black = 0
        for sq in range(64):
            wa = len(board.attackers(chess.WHITE, sq))
            ba = len(board.attackers(chess.BLACK, sq))
            if wa >= 2:
                coord_white += 1
            if ba >= 2:
                coord_black += 1
        return float(coord_white - coord_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) in local defender density around each king: number of friendly pieces within Manhattan distance <=2 of the king (includes pawns)'
    import chess
    pm = board.piece_map()
    def local_density(color):
        ksq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==color), None)
        if ksq is None:
            return 0.0
        kr = chess.square_rank(ksq); kf = chess.square_file(ksq)
        d = 0
        for sq,p in pm.items():
            if p.color!=color:
                continue
            rf = chess.square_file(sq); rr = chess.square_rank(sq)
            if abs(rf-kf) + abs(rr-kr) <= 2:
                d += 1
        return float(d)
    return float(local_density(chess.WHITE) - local_density(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Half-open file control: difference in number of half-open files where side has at least one rook or queen on that file (white - black). Half-open = opponent has no pawns on that file.'
    try:
        pm = board.piece_map()
        white_score = 0.0
        black_score = 0.0
        for f in range(8):
            # check if opponent pawns exist on this file
            white_has_pawn = any((p.piece_type == chess.PAWN and p.color == chess.WHITE) for sq,p in pm.items() if chess.square_file(sq) == f)
            black_has_pawn = any((p.piece_type == chess.PAWN and p.color == chess.BLACK) for sq,p in pm.items() if chess.square_file(sq) == f)
            # white half-open if white has no pawns but black does not matter; we want files where opponent has no pawns
            # For white: opponent (black) has no pawns on file and white has rook/queen on file
            if not black_has_pawn:
                if any((p.piece_type in (chess.ROOK, chess.QUEEN) and p.color == chess.WHITE) for sq,p in pm.items() if chess.square_file(sq) == f):
                    white_score += 1.0
            if not white_has_pawn:
                if any((p.piece_type in (chess.ROOK, chess.QUEEN) and p.color == chess.BLACK) for sq,p in pm.items() if chess.square_file(sq) == f):
                    black_score += 1.0
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material balance (white minus black) in pawns=100 n=320 b=330 r=500 q=900 units, returned in pawn-equivalents (divide by 100)'
    try:
        values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        w = 0
        b = 0
        for sq, pc in board.piece_map().items():
            val = values.get(pc.piece_type, 0)
            if pc.color == chess.WHITE:
                w += val
            else:
                b += val
        return float((w - b) / 100.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in average Manhattan distance of major pieces (rooks/queens) to the enemy king (black_avg - white_avg). Positive means white major pieces are on average closer to black king.'
    try:
        pm = board.piece_map()
        w_major = []
        b_major = []
        white_king_sq = None
        black_king_sq = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king_sq = sq
                else:
                    black_king_sq = sq
            if p.piece_type in (chess.ROOK, chess.QUEEN):
                if p.color == chess.WHITE:
                    w_major.append(sq)
                else:
                    b_major.append(sq)
        if black_king_sq is None or white_king_sq is None:
            return 0.0
        def avg_dist(list_sq, target):
            if not list_sq:
                return 10.0
            s = 0
            for sq in list_sq:
                s += chess.square_distance(sq, target)
            return s / len(list_sq)
        white_avg = avg_dist(w_major, black_king_sq)
        black_avg = avg_dist(b_major, white_king_sq)
        return float(black_avg - white_avg)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in queen-rook proximity coordination: sum over queen-rook pairs of 1/(1+manhattan_distance) (White - Black)'
    try:
        pm = board.piece_map()
        w_qs = []
        b_qs = []
        w_rs = []
        b_rs = []
        for s, p in pm.items():
            if p.piece_type == chess.QUEEN:
                if p.color == chess.WHITE:
                    w_qs.append(s)
                else:
                    b_qs.append(s)
            if p.piece_type == chess.ROOK:
                if p.color == chess.WHITE:
                    w_rs.append(s)
                else:
                    b_rs.append(s)
        def coord_sum(queens, rooks):
            total = 0.0
            for q in queens:
                for r in rooks:
                    d = chess.square_distance(q, r)
                    total += 1.0 / (1.0 + d)
            return total
        w_sum = coord_sum(w_qs, w_rs)
        b_sum = coord_sum(b_qs, b_rs)
        return float(w_sum - b_sum)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material tropism: (white pieces weighted inverse-distance to black king) - (black pieces weighted inverse-distance to white king)'
    try:
        vals = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        # locate kings
        white_king = None
        black_king = None
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        if white_king is None or black_king is None:
            return 0.0
        score_w = 0.0
        score_b = 0.0
        for sq, p in board.piece_map().items():
            v = vals.get(p.piece_type, 0.0)
            if v == 0.0:
                continue
            if p.color == chess.WHITE:
                d = chess.square_distance(sq, black_king)
                score_w += v / (1.0 + float(d))
            else:
                d = chess.square_distance(sq, white_king)
                score_b += v / (1.0 + float(d))
        return float(score_w - score_b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of pawns blocked by a friendly piece immediately ahead (white - black)'
    try:
        pm = board.piece_map()
        wblocked = 0
        bblocked = 0
        for sq, p in pm.items():
            if p.piece_type != chess.PAWN:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                if r < 7:
                    ahead_sq = (r + 1) * 8 + f
                    pa = board.piece_at(ahead_sq)
                    if pa is not None and pa.color == chess.WHITE:
                        wblocked += 1
            else:
                if r > 0:
                    ahead_sq = (r - 1) * 8 + f
                    pa = board.piece_at(ahead_sq)
                    if pa is not None and pa.color == chess.BLACK:
                        bblocked += 1
        return float(wblocked - bblocked)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Penalty for non-pawn non-king pieces that have very few legal moves (trapped or nearly trapped); returns white_penalty - black_penalty in pawn units'
    value_map = {chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0}
    pm = board.piece_map()
    legal_moves = list(board.legal_moves)
    # map from from_square to count of legal moves
    move_count = {}
    for mv in legal_moves:
        move_count[mv.from_square] = move_count.get(mv.from_square, 0) + 1
    white_pen = 0.0
    black_pen = 0.0
    for sq, piece in pm.items():
        if piece.piece_type == chess.PAWN or piece.piece_type == chess.KING:
            continue
        cnt = move_count.get(sq, 0)
        if cnt <= 1:
            v = value_map.get(piece.piece_type, 0.0)
            # moves 0 -> full penalty v, moves 1 -> half penalty
            penalty = v * (1.0 if cnt == 0 else 0.5)
            if piece.color == chess.WHITE:
                white_pen += penalty
            else:
                black_pen += penalty
    return float(white_pen - black_pen)

def feature(board: chess.Board) -> float:
    'Rook trappedness difference: sum over rooks of (1 - sliding mobility/14) for each side (low mobility -> trapped). Returns White - Black'
    try:
        def rook_mobility(sq):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            mobility = 0
            for df, dr in ((1,0),(-1,0),(0,1),(0,-1)):
                nf, nr = f+df, r+dr
                while 0<=nf<8 and 0<=nr<8:
                    mobility += 1
                    if board.piece_at(nr*8+nf) is not None:
                        break
                    nf += df; nr += dr
            return mobility  # max possible 14
        white_score = 0.0
        black_score = 0.0
        for sq,p in board.piece_map().items():
            if p.piece_type==chess.ROOK:
                mob = rook_mobility(sq)
                trappedness = 1.0 - (mob / 14.0)
                if p.color==chess.WHITE:
                    white_score += trappedness
                else:
                    black_score += trappedness
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Tactical pressure near kings: (sum of opponent attacker values attacking squares within manhattan distance <=2 of white king) - (same measure for black king); captures localized threats'
    vals = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    pm = board.piece_map()
    def pressure_on_king(color):
        # color is side being attacked (i.e., we compute attackers of opponent near this king)
        king_sq = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING and p.color == color:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        kf = chess.square_file(king_sq)
        kr = chess.square_rank(king_sq)
        total = 0.0
        atk_color = not color
        # iterate squares within manhattan <= 2 (a small diamond), but also include Chebyshev <=2 area for proximity
        for df in range(-2, 3):
            for dr in range(-2, 3):
                if abs(df) + abs(dr) > 2:
                    continue
                f = kf + df
                r = kr + dr
                if f < 0 or f > 7 or r < 0 or r > 7:
                    continue
                name = chr(ord('a') + f) + str(r + 1)
                try:
                    sq = chess.parse_square(name)
                except Exception:
                    continue
                attackers = board.attackers(atk_color, sq)
                for atk_sq in attackers:
                    p = board.piece_at(atk_sq)
                    if p:
                        total += vals.get(p.piece_type, 0)
        return total
    return pressure_on_king(chess.WHITE) - pressure_on_king(chess.BLACK)

def feature(board: chess.Board) -> float:
    'Difference in bishop scope (sum of reachable squares excluding squares occupied by same color): White - Black'
    pm = board.piece_map()
    def bishop_reach(square, color):
        total = 0
        f0 = chess.square_file(square)
        r0 = chess.square_rank(square)
        for df, dr in ((1,1),(1,-1),(-1,1),(-1,-1)):
            f = f0 + df
            r = r0 + dr
            while 0 <= f <= 7 and 0 <= r <= 7:
                s2 = chess.square(f, r)
                p = board.piece_at(s2)
                if p is None:
                    total += 1
                else:
                    if p.color != color:
                        total += 1
                    break
                f += df
                r += dr
        return total
    wsum = 0
    bsum = 0
    for sq, pc in pm.items():
        if pc.piece_type == chess.BISHOP:
            if pc.color == chess.WHITE:
                wsum += bishop_reach(sq, chess.WHITE)
            else:
                bsum += bishop_reach(sq, chess.BLACK)
    # normalize to avoid huge values; divide by max(1, count_of_bishops)
    wcount = sum(1 for p in pm.values() if p.piece_type == chess.BISHOP and p.color == chess.WHITE)
    bcount = sum(1 for p in pm.values() if p.piece_type == chess.BISHOP and p.color == chess.BLACK)
    wnorm = wsum / max(1, wcount)
    bnorm = bsum / max(1, bcount)
    return float(wnorm - bnorm)

def feature(board: chess.Board) -> float:
    'Material weighted by piece activity: for each piece value * number of squares it (currently) attacks; return (white - black)'
    values = {chess.PAWN: 100.0, chess.KNIGHT: 320.0, chess.BISHOP: 330.0, chess.ROOK: 500.0, chess.QUEEN: 900.0, chess.KING: 20000.0}
    pm = board.piece_map()
    white_score = 0.0
    black_score = 0.0
    for sq, p in pm.items():
        # count number of squares this piece attacks (approx): any target for which this piece's square appears in board.attackers(p.color, target)
        activity = 0
        for target in range(64):
            if sq in board.attackers(p.color, target):
                activity += 1
        val = values.get(p.piece_type, 100.0) * float(activity)
        if p.color == chess.WHITE:
            white_score += val
        else:
            black_score += val
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Central pawn mass: (white pawns on d4,e4,d5,e5 and advanced d/e pawns) - (black same), counts weighted by advancement'
    try:
        center_sqs = [chess.parse_square(s) for s in ('d4','e4','d5','e5')]
        pm = board.piece_map()
        wcenter = 0.0
        bcenter = 0.0
        for sq, p in pm.items():
            if p.piece_type != chess.PAWN:
                continue
            if sq in center_sqs:
                if p.color == chess.WHITE:
                    wcenter += 1.5
                else:
                    bcenter += 1.5
            # additional bonus for pawns on d/e files that are advanced (ranks 3-6)
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if f in (3,4) and 2 <= r <= 5:
                bonus = 0.5 + 0.5 * ((r-2)/3.0) if p.color == chess.WHITE else 0.5 + 0.5 * ((5-r)/3.0)
                if p.color == chess.WHITE:
                    wcenter += bonus
                else:
                    bcenter += bonus
        return float(wcenter - bcenter)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in average Manhattan distance of non-king pieces to their own king (white average minus black average)'
    try:
        pm = board.piece_map()
        def avg_dist(color):
            king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == color), None)
            if king_sq is None:
                return 0.0
            dists = []
            for sq, pc in pm.items():
                if pc.color == color and pc.piece_type != chess.KING:
                    dists.append(chess.square_distance(sq, king_sq))
            if not dists:
                return 0.0
            return float(sum(dists) / len(dists))
        return avg_dist(chess.WHITE) - avg_dist(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in total pawn advancement (white minus black); counts ranks advanced toward promotion (normalized by 8)'
    try:
        adv_w = 0
        adv_b = 0
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.PAWN:
                r = chess.square_rank(sq)
                if pc.color == chess.WHITE:
                    adv_w += r  # 0..7, higher means more advanced
                else:
                    adv_b += (7 - r)  # distance toward white promotion
        # normalize by maximum total (8 ranks * up to 8 pawns ~ 64) but keep scale reasonable
        return float((adv_w - adv_b) / 8.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Piece coordination index difference: sum of inverse distances between pairs of non-pawn pieces of the same color (White - Black). Higher means more tightly coordinated'
    try:
        pm = board.piece_map()
        from itertools import combinations
        def coord_score(color):
            squares = [sq for sq, p in pm.items() if p.color == color and p.piece_type != chess.PAWN]
            score = 0.0
            for a, b in combinations(squares, 2):
                d = chess.square_distance(a, b)
                # add small epsilon to avoid divide by zero
                score += 1.0 / (1.0 + float(d))
            return score
        return float(coord_score(chess.WHITE) - coord_score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Combined pawn-structure weakness score: (doubled + isolated) pawns difference (white - black)'
    try:
        pm = board.piece_map()
        # count pawns per file
        files_white = [0]*8
        files_black = [0]*8
        pawns_white_squares = []
        pawns_black_squares = []
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if p.color == chess.WHITE:
                    files_white[f] += 1
                    pawns_white_squares.append(sq)
                else:
                    files_black[f] += 1
                    pawns_black_squares.append(sq)
        def weakness(files, pawn_sqs, color):
            doubled = sum(max(0, c-1) for c in files)
            isolated = 0
            for sq in pawn_sqs:
                f = chess.square_file(sq)
                left = f-1
                right = f+1
                has_neighbor = False
                if 0 <= left <= 7 and files[left] > 0:
                    has_neighbor = True
                if 0 <= right <= 7 and files[right] > 0:
                    has_neighbor = True
                if not has_neighbor:
                    isolated += 1
            return doubled + isolated
        wweak = weakness(files_white, pawns_white_squares, chess.WHITE)
        bweak = weakness(files_black, pawns_black_squares, chess.BLACK)
        return float(wweak - bweak)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net attack pressure on squares adjacent to each king (white minus black)'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.BLACK), None)
        def adjacent_squares(sq):
            if sq is None:
                return []
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            res = []
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    nf = f + df
                    nr = r + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        res.append(chess.square(nf, nr))
            return res
        white_pressure = 0
        black_pressure = 0
        for adj in adjacent_squares(white_king_sq):
            white_pressure += len(board.attackers(chess.BLACK, adj))
        for adj in adjacent_squares(black_king_sq):
            black_pressure += len(board.attackers(chess.WHITE, adj))
        return float(white_pressure - black_pressure)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Relative king centralization: (White king distance from e1) - (Black king distance from e8). Larger positive means White king is farther from its home square than Black.'
    pm = board.piece_map()
    w_king_sq = None
    b_king_sq = None
    for sq, p in pm.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                w_king_sq = sq
            else:
                b_king_sq = sq
    # default to 0 if missing
    dist_w = 0
    dist_b = 0
    try:
        if w_king_sq is not None:
            dist_w = chess.square_distance(w_king_sq, chess.parse_square('e1'))
        if b_king_sq is not None:
            dist_b = chess.square_distance(b_king_sq, chess.parse_square('e8'))
    except Exception:
        pass
    return float(dist_w - dist_b)

def feature(board: chess.Board) -> float:
    'Centralization score: sum over non-pawn pieces of (4 - min_distance_to_center) for white minus black (higher => more centralized white pieces)'
    pm = board.piece_map()
    center_sqs = [chess.parse_square(s) for s in ('d4', 'e4', 'd5', 'e5')]
    def piece_central_score(sq):
        dmin = min(chess.square_distance(sq, c) for c in center_sqs)
        return max(0, 4 - dmin)
    white_score = 0.0
    black_score = 0.0
    for sq, p in pm.items():
        if p.piece_type == chess.PAWN:
            continue
        score = piece_central_score(sq)
        if p.color == chess.WHITE:
            white_score += score
        else:
            black_score += score
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Trapped-king score difference: (black trapped score) - (white trapped score); positive favors White if Black is trapped. Edge, few king moves and many adjacent attackers increase the score.'
    try:
        pm = board.piece_map()
        def trap_score_for(king_color):
            king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == king_color), None)
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            on_edge = 1 if (kf == 0 or kf == 7 or kr == 0 or kr == 7) else 0
            # king legal moves
            k_moves = 0
            for mv in board.legal_moves:
                try:
                    if mv.from_square == king_sq:
                        k_moves += 1
                except Exception:
                    continue
            # adjacent attackers by opponent
            opponent = chess.WHITE if king_color == chess.BLACK else chess.BLACK
            adj_att = 0
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    nf = kf + df
                    nr = kr + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        sq = chess.parse_square('abcdefgh'[nf] + str(nr + 1))
                        adj_att += len(board.attackers(opponent, sq))
            score = on_edge * max(0, 4 - k_moves) * adj_att
            return float(score)
        black_trap = trap_score_for(chess.BLACK)
        white_trap = trap_score_for(chess.WHITE)
        return float(black_trap - white_trap)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn-structure fragility around kings: difference (White fragile pawns near White king) - (Black near Black king). Counts isolated/doubled/backward pawns in 3-file neighborhood ahead of each king'
    try:
        pm = board.piece_map()
        def frag_for_king(color):
            king_sq = None
            for sq, p in pm.items():
                if p.piece_type == chess.KING and p.color == color:
                    king_sq = sq
                    break
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            frag = 0.0
            # examine files kf-1..kf+1 and ranks forward (toward center/opponent)
            if color == chess.WHITE:
                ranks = range(kr+1, min(7, kr+3)+1)
            else:
                ranks = range(max(0, kr-2), kr)
            for f in range(max(0,kf-1), min(7,kf+1)+1):
                for r in ranks:
                    p = board.piece_at(chess.square(f, r))
                    if p is None or p.piece_type != chess.PAWN or p.color != color:
                        continue
                    # isolated if no friendly pawn on adjacent files
                    adj = False
                    for af in (f-1, f+1):
                        if 0 <= af <= 7:
                            for rr in range(8):
                                q = board.piece_at(chess.square(af, rr))
                                if q is not None and q.piece_type == chess.PAWN and q.color == color:
                                    adj = True
                                    break
                            if adj:
                                break
                    if not adj:
                        frag += 1.0
                    # doubled if another friendly pawn on same file
                    count_same = 0
                    for rr in range(8):
                        q = board.piece_at(chess.square(f, rr))
                        if q is not None and q.piece_type == chess.PAWN and q.color == color:
                            count_same += 1
                    if count_same > 1:
                        frag += 0.7
                    # backward: if no friendly pawn ahead on same file
                    ahead_exists = False
                    if color == chess.WHITE:
                        for rr in range(r+1, 8):
                            q = board.piece_at(chess.square(f, rr))
                            if q is not None and q.piece_type == chess.PAWN and q.color == color:
                                ahead_exists = True
                                break
                    else:
                        for rr in range(0, r):
                            q = board.piece_at(chess.square(f, rr))
                            if q is not None and q.piece_type == chess.PAWN and q.color == color:
                                ahead_exists = True
                                break
                    if not ahead_exists:
                        frag += 0.5
            return frag
        return float(frag_for_king(chess.WHITE) - frag_for_king(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Localized king-zone attack concentration: (White pressure on Black king) - (Black pressure on White king) where pressure sums attacker piece values on squares adjacent to king, normalized by 1000'
    values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    pm = board.piece_map()
    def king_square(color):
        for sq,p in pm.items():
            if p.piece_type==chess.KING and p.color==color:
                return sq
        return None
    def pressure_on_king(king_sq, attacker_color):
        if king_sq is None:
            return 0
        kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
        total = 0
        for i in range(8):
            sq = i
        for sq,p in pm.items():
            if p.color==attacker_color:
                df = abs(chess.square_file(sq)-kf)
                dr = abs(chess.square_rank(sq)-kr)
                if max(df,dr) <= 1:
                    total += values.get(p.piece_type,0)
                else:
                    # also count pieces that attack any adjacent square
                    # check each adjacent square
                    for df2 in (-1,0,1):
                        for dr2 in (-1,0,1):
                            tf = kf+df2; tr = kr+dr2
                            if 0 <= tf <= 7 and 0 <= tr <= 7:
                                tsq = chess.square(tf,tr)
                                try:
                                    if board.is_attacked_by(attacker_color, tsq):
                                        # add fractional credit depending on distance
                                        dist = max(abs(chess.square_file(sq)-tf), abs(chess.square_rank(sq)-tr))
                                        total += values.get(p.piece_type,0) * (0.5 if dist==2 else 0.25)
                                        break
                                except Exception:
                                    continue
                        else:
                            continue
                        break
        return total
    wking = king_square(chess.WHITE)
    bking = king_square(chess.BLACK)
    white_pressure_on_black = pressure_on_king(bking, chess.WHITE)
    black_pressure_on_white = pressure_on_king(wking, chess.BLACK)
    return float(white_pressure_on_black - black_pressure_on_white) / 1000.0

def feature(board: chess.Board) -> float:
    'Net trapped-piece indicator: (Black pieces under-defended and over-attacked) - (White pieces similarly), positive favors White'
    def trapped_count(color):
        count = 0
        for sq, p in board.piece_map().items():
            if p.color != color or p.piece_type == chess.KING:
                continue
            attackers = len(board.attackers(not color, sq))
            defenders = len(board.attackers(color, sq))
            # consider trapped if attackers exceed defenders by at least 2 (risky) or attackers>=defenders and defenders==0
            if attackers >= defenders + 2 or (attackers >= defenders and defenders == 0):
                count += 1
        return count
    return float(trapped_count(chess.BLACK) - trapped_count(chess.WHITE))

def feature(board: chess.Board) -> float:
    'Weighted opponent attack pressure on the 3x3 king zone: (pressure_on_white_king - pressure_on_black_king)'
    try:
        pm = board.piece_map()
        piece_value = {chess.PAWN: 1.0, chess.KNIGHT: 3.0, chess.BISHOP: 3.0, chess.ROOK: 5.0, chess.QUEEN: 9.0, chess.KING: 0.0}
        def zone_pressure(king_sq, attacker_color):
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            total = 0.0
            # squares in 1-square Chebyshev neighbourhood
            for f in range(max(0, kf - 1), min(7, kf + 1) + 1):
                for r in range(max(0, kr - 1), min(7, kr + 1) + 1):
                    sq = chess.square(f, r)
                    attackers = board.attackers(attacker_color, sq)
                    for a in attackers:
                        attacker_piece = pm.get(a)
                        if attacker_piece is None:
                            continue
                        val = piece_value.get(attacker_piece.piece_type, 0.0)
                        # closer attackers count more; distance to king as tie-break
                        d = chess.square_distance(a, king_sq)
                        total += val / (1.0 + d)
            return total
        wking = None
        bking = None
        for s, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    wking = s
                else:
                    bking = s
        # pressure on white king is from black pieces
        pressure_on_white = zone_pressure(wking, chess.BLACK)
        pressure_on_black = zone_pressure(bking, chess.WHITE)
        return float(pressure_on_white - pressure_on_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net weighted attacker value (in pawn units) targeting each king\'s immediate neighborhood (White minus Black)'
    values = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500, chess.QUEEN: 900, chess.KING: 0}
    # find king squares
    king_sq = {chess.WHITE: None, chess.BLACK: None}
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.KING:
            king_sq[p.color] = sq
    def neighborhood(square):
        if square is None:
            return []
        f0 = chess.square_file(square)
        r0 = chess.square_rank(square)
        neigh = []
        for f in range(max(0, f0 - 1), min(7, f0 + 1) + 1):
            for r in range(max(0, r0 - 1), min(7, r0 + 1) + 1):
                neigh.append(chess.square(f, r))
        return neigh
    def pressure_on_king(color):
        # sum unique attacker piece values that attack any square in the king neighborhood
        sq = king_sq[color]
        if sq is None:
            return 0.0
        neigh = neighborhood(sq)
        attacker_squares = set()
        for n in neigh:
            # squares attacking this neighbor by opponent color
            try:
                atks = board.attackers(not color, n)
            except Exception:
                atks = set()
            attacker_squares |= set(atks)
        total = 0
        for a in attacker_squares:
            p = board.piece_at(a)
            if p:
                total += values.get(p.piece_type, 0)
        return float(total)
    white_pressure = pressure_on_king(chess.WHITE)
    black_pressure = pressure_on_king(chess.BLACK)
    return (white_pressure - black_pressure) / 100.0

def feature(board: chess.Board) -> float:
    'Enemy capture pressure score difference: (black_capture_pressure - white_capture_pressure), sum over attacks weighted by captured piece value'
    import chess
    try:
        val = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        def capture_pressure_for(color):
            total = 0.0
            for sq, p in board.piece_map().items():
                if p.color == color:
                    # what opponent pieces does this side attack?
                    # iterate opponent pieces and check if attacked
                    for osq, op in board.piece_map().items():
                        if op.color == (not color):
                            if sq in board.attackers(color, osq):  # attacker origin square attacks osq
                                total += val.get(op.piece_type, 0.0)
            return total
        return float(capture_pressure_for(chess.BLACK) - capture_pressure_for(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
