def feature(board: chess.Board) -> float:
    'Centralization: net centralization score (white - black) for knights/bishops/rooks/queens based on distance to central squares'
    try:
        center_squares = [chess.parse_square(n) for n in ('d4','e4','d5','e5')]
        pm = board.piece_map()
        score_w = 0.0
        score_b = 0.0
        for sq, pc in pm.items():
            if pc.piece_type in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
                d = min(chess.square_distance(sq, c) for c in center_squares)
                base = max(0.0, 4.0 - float(d))  # closer to center gives higher base
                mult = 1.0
                if pc.piece_type == chess.QUEEN:
                    mult = 1.5
                elif pc.piece_type == chess.ROOK:
                    mult = 1.2
                elif pc.piece_type == chess.BISHOP:
                    mult = 1.0
                elif pc.piece_type == chess.KNIGHT:
                    mult = 1.1
                if pc.color == chess.WHITE:
                    score_w += base * mult
                else:
                    score_b += base * mult
        return float(score_w - score_b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Piece coordination index: (black_avg_pairdist - white_avg_pairdist) positive when white pieces are more tightly coordinated'
    pm = board.piece_map()
    def avg_pair_distance(color):
        locs = [sq for sq,p in pm.items() if p.color==color and p.piece_type!=chess.KING]
        n = len(locs)
        if n <= 1:
            return 8.0
        total = 0
        pairs = 0
        for i in range(n):
            for j in range(i+1,n):
                total += chess.square_distance(locs[i], locs[j])
                pairs += 1
        return total / pairs if pairs>0 else 8.0
    return (avg_pair_distance(chess.BLACK) - avg_pair_distance(chess.WHITE))

def feature(board: chess.Board) -> float:
    'Sum of material of hanging pieces weighted by proximity to their own king: (White - Black). Hanging = attacked by more opponents than defended.'
    values = {chess.PAWN:1.0, chess.KNIGHT:3.2, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0}
    pm = board.piece_map()
    white_king = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.WHITE), None)
    black_king = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.BLACK), None)
    if white_king is None or black_king is None:
        return 0.0
    white_sum = 0.0
    black_sum = 0.0
    for sq, piece in pm.items():
        if piece.piece_type == chess.KING:
            continue
        attackers = len(board.attackers(not piece.color, sq))
        defenders = len(board.attackers(piece.color, sq))
        if attackers > defenders:
            own_king = white_king if piece.color==chess.WHITE else black_king
            dist = chess.square_distance(sq, own_king)
            # weight: closer to own king => more dangerous (less mitigated)
            weight = 1.0 / (1.0 + dist)
            v = values.get(piece.piece_type, 0.0) * weight
            if piece.color == chess.WHITE:
                white_sum += v
            else:
                black_sum += v
    return float(white_sum - black_sum)

def feature(board: chess.Board) -> float:
    'Indicator (1.0/0.0) whether any white rook is directly behind the most advanced white pawn on the same file with no pieces between (support-from-behind).'
    try:
        # find most advanced white pawn (highest rank)
        white_pawns = [sq for sq, p in board.piece_map().items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        if not white_pawns:
            return 0.0
        pawn_sq = max(white_pawns, key=lambda s: chess.square_rank(s))
        pawn_file = chess.square_file(pawn_sq)
        pawn_rank = chess.square_rank(pawn_sq)
        # find white rooks on same file with lower rank
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK and p.color == chess.WHITE and chess.square_file(sq) == pawn_file and chess.square_rank(sq) < pawn_rank:
                # ensure path between rook and pawn is clear
                clear = True
                for r in range(chess.square_rank(sq) + 1, pawn_rank):
                    if board.piece_at(chess.square(pawn_file, r)) is not None:
                        clear = False
                        break
                if clear:
                    return 1.0
        return 0.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in pawn-chain defense ratio: proportion of pawns defended by another pawn (White ratio minus Black ratio)'
    pm = board.piece_map()
    def pawn_defended_ratio(color):
        pawn_sqs = [sq for sq, p in pm.items() if p.piece_type == chess.PAWN and p.color == color]
        if not pawn_sqs:
            return 0.0
        defended = 0
        for sq in pawn_sqs:
            f, r = chess.square_file(sq), chess.square_rank(sq)
            # white pawns are defended from behind (rank-1), black from behind (rank+1)
            if color == chess.WHITE:
                candidates = []
                if f - 1 >= 0 and r - 1 >= 0:
                    candidates.append((f - 1) + 8 * (r - 1))
                if f + 1 <= 7 and r - 1 >= 0:
                    candidates.append((f + 1) + 8 * (r - 1))
            else:
                candidates = []
                if f - 1 >= 0 and r + 1 <= 7:
                    candidates.append((f - 1) + 8 * (r + 1))
                if f + 1 <= 7 and r + 1 <= 7:
                    candidates.append((f + 1) + 8 * (r + 1))
            for c in candidates:
                pc = pm.get(c)
                if pc is not None and pc.piece_type == chess.PAWN and pc.color == color:
                    defended += 1
                    break
        return defended / len(pawn_sqs)
    return float(pawn_defended_ratio(chess.WHITE) - pawn_defended_ratio(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Material balance (in pawn units) divided by (1 + absolute mobility difference) to highlight disproportionate material with little mobility'
    values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    mat_white = 0
    mat_black = 0
    for sq, pc in board.piece_map().items():
        val = values.get(pc.piece_type, 0)
        if pc.color == chess.WHITE:
            mat_white += val
        else:
            mat_black += val
    material_balance = (mat_white - mat_black) / 100.0  # in pawn units
    # compute mobility (legal moves) for both sides by setting turn on copies
    mob_white = 0
    mob_black = 0
    try:
        b1 = board.copy(); b1.turn = chess.WHITE
        mob_white = sum(1 for _ in b1.legal_moves)
    except Exception:
        mob_white = 0
    try:
        b2 = board.copy(); b2.turn = chess.BLACK
        mob_black = sum(1 for _ in b2.legal_moves)
    except Exception:
        mob_black = 0
    mobility_diff = float(mob_white - mob_black)
    denom = 1.0 + max(0.1, abs(mobility_diff))
    return float(material_balance) / denom

def feature(board: chess.Board) -> float:
    'King pawn shield imbalance: (White pawn shield score around White king) - (Black pawn shield score around Black king), normalized to [ -1 .. 1 ]'
    try:
        piece_map = board.piece_map()
        def find_king(color):
            for sq, p in piece_map.items():
                if p.piece_type == chess.KING and p.color == color:
                    return sq
            return None
        def pawn_shield(king_sq, color):
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
            count = 0
            # consider pawns on king file and adjacent files up to two ranks in front (direction depends on color)
            dr_sign = 1 if color == chess.WHITE else -1
            for df in (-1, 0, 1):
                for step in (1, 2):
                    f = kf + df
                    r = kr + dr_sign * step
                    if 0 <= f <= 7 and 0 <= r <= 7:
                        sq = chess.square(f, r)
                        p = board.piece_at(sq)
                        if p is not None and p.piece_type == chess.PAWN and p.color == color:
                            # closer pawns contribute more
                            count += 1.0 / step
            # normalize by possible max (3 files * (1 + 1/2)) = 4.5
            return count / 4.5
        return pawn_shield(find_king(chess.WHITE), chess.WHITE) - pawn_shield(find_king(chess.BLACK), chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Trapped non-pawn pieces count difference: (white_trapped - black_trapped); piece is trapped if it has zero legal moves'
    legal = list(board.legal_moves)
    moves_from = {}
    for mv in legal:
        moves_from.setdefault(mv.from_square, 0)
        moves_from[mv.from_square] += 1
    white_trapped = 0
    black_trapped = 0
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.PAWN:
            continue
        has_moves = moves_from.get(sq, 0) > 0
        if not has_moves:
            if p.color == chess.WHITE:
                white_trapped += 1
            else:
                black_trapped += 1
    return float(white_trapped - black_trapped)

def feature(board: chess.Board) -> float:
    'Max attacker-minus-defender weighted by piece value for opponent pieces (black_max - white_max); large positive means White pieces are more under-defended/attacked (bad for White).'
    try:
        vals = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        pm = board.piece_map()
        white_max = 0.0
        black_max = 0.0
        for sq, pc in pm.items():
            if pc.piece_type == chess.KING:
                continue
            attackers = len(board.attackers(not pc.color, sq))
            defenders = len(board.attackers(pc.color, sq))
            score = (attackers - defenders) * vals.get(pc.piece_type, 1.0)
            if pc.color == chess.WHITE:
                white_max = max(white_max, score)
            else:
                black_max = max(black_max, score)
        return float(black_max - white_max)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) in count of friendly pieces that are defended by at least one friendly piece (non-king) -- measures coordination'
    pm = board.piece_map()
    white_defended = 0
    black_defended = 0
    for sq, pc in pm.items():
        if pc.piece_type == chess.KING:
            continue
        defenders = board.attackers(pc.color, sq)
        # ignore self-attack by the piece itself (shouldn't happen)
        if any(board.piece_at(d) and board.piece_at(d).color == pc.color for d in defenders):
            if pc.color == chess.WHITE:
                white_defended += 1
            else:
                black_defended += 1
    return float(white_defended - black_defended)

def feature(board: chess.Board) -> float:
    'Sum of material of hanging pieces weighted by proximity to their own king: (White - Black). Hanging = attacked by more opponents than defended.'
    values = {chess.PAWN:1.0, chess.KNIGHT:3.2, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0}
    pm = board.piece_map()
    white_king = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.WHITE), None)
    black_king = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.BLACK), None)
    if white_king is None or black_king is None:
        return 0.0
    white_sum = 0.0
    black_sum = 0.0
    for sq, piece in pm.items():
        if piece.piece_type == chess.KING:
            continue
        attackers = len(board.attackers(not piece.color, sq))
        defenders = len(board.attackers(piece.color, sq))
        if attackers > defenders:
            own_king = white_king if piece.color==chess.WHITE else black_king
            dist = chess.square_distance(sq, own_king)
            # weight: closer to own king => more dangerous (less mitigated)
            weight = 1.0 / (1.0 + dist)
            v = values.get(piece.piece_type, 0.0) * weight
            if piece.color == chess.WHITE:
                white_sum += v
            else:
                black_sum += v
    return float(white_sum - black_sum)

def feature(board: chess.Board) -> float:
    'Difference in "trapped-ness" of major pieces (rooks and queens): higher means white majors more constrained than black'
    piece_map = board.piece_map()
    # helper to compute pseudo-legal escape squares for rook/bishop/queen
    def ray_count(start_sq, deltas):
        count = 0
        sf = chess.square_file(start_sq)
        sr = chess.square_rank(start_sq)
        for df, dr in deltas:
            nf = sf + df
            nr = sr + dr
            while 0 <= nf <= 7 and 0 <= nr <= 7:
                name = chr(ord('a') + nf) + str(nr + 1)
                sq = chess.parse_square(name)
                p = board.piece_at(sq)
                if p is None:
                    count += 1
                else:
                    # can capture opponent, then stop
                    if p.color != piece_map[start_sq].color:
                        count += 1
                    break
                nf += df
                nr += dr
        return count
    rook_deltas = ((1,0),(-1,0),(0,1),(0,-1))
    bishop_deltas = ((1,1),(1,-1),(-1,1),(-1,-1))
    white_score = 0.0
    black_score = 0.0
    values = {chess.ROOK:5.0, chess.QUEEN:9.0}
    for sq, pc in piece_map.items():
        if pc.piece_type in (chess.ROOK, chess.QUEEN):
            if pc.piece_type == chess.ROOK:
                esc = ray_count(sq, rook_deltas)
            else:
                esc = ray_count(sq, rook_deltas) + ray_count(sq, bishop_deltas)
            # trappedness score: larger when fewer escapes
            score = values.get(pc.piece_type, 0.0) * (1.0 / (esc + 1.0))
            if pc.color == chess.WHITE:
                white_score += score
            else:
                black_score += score
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Backrank vulnerability indicator difference: 1 if king has no pawns on its backrank and opponent has heavy on same rank attacking, else 0 (White - Black)'
    try:
        pm = board.piece_map()
        # find kings
        king_sq = {chess.WHITE: None, chess.BLACK: None}
        for sq, pc in pm.items():
            if pc.piece_type == chess.KING:
                king_sq[pc.color] = sq
        def backrank_vul(color):
            ks = king_sq[color]
            if ks is None:
                return 0.0
            kr = chess.square_rank(ks)
            back_rank = kr
            # count own pawns on that rank
            own_pawn_on_rank = 0
            for sq, pc in pm.items():
                if pc.piece_type == chess.PAWN and pc.color == color and chess.square_rank(sq) == back_rank:
                    own_pawn_on_rank += 1
            if own_pawn_on_rank > 0:
                return 0.0
            # check if opponent has rook/queen on same rank or attacking any square of the rank
            opp = not color
            attacked = False
            for file in range(8):
                sq = chess.square(file, back_rank)
                # if opponent rook/queen attacks this square OR there is an opponent rook/queen on same rank not blocked
                if board.is_attacked_by(opp, sq):
                    # ensure attacker is heavy piece along rank or queen (rough check)
                    attackers = board.attackers(opp, sq)
                    for a in attackers:
                        p = pm.get(a)
                        if p and (p.piece_type in (chess.ROOK, chess.QUEEN)):
                            attacked = True
                            break
                if attacked:
                    break
            return 1.0 if attacked else 0.0
        return float(backrank_vul(chess.WHITE) - backrank_vul(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn score weighted by advancement (white minus black); advanced passed pawns count more'
    try:
        pm = board.piece_map()
        def pawn_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                for rr in range(r+1, 8):
                    for ff in (f-1, f, f+1):
                        if 0 <= ff <= 7:
                            q = board.piece_at(chess.square(ff, rr))
                            if q is not None and q.piece_type == chess.PAWN and q.color == chess.BLACK:
                                return False
                return True
            else:
                for rr in range(r-1, -1, -1):
                    for ff in (f-1, f, f+1):
                        if 0 <= ff <= 7:
                            q = board.piece_at(chess.square(ff, rr))
                            if q is not None and q.piece_type == chess.PAWN and q.color == chess.WHITE:
                                return False
                return True
        white_score = 0.0
        black_score = 0.0
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                r = chess.square_rank(sq)
                if pawn_passed(sq, p.color):
                    # advancement factor: for white use rank/7, for black use (7-r)/7
                    if p.color == chess.WHITE:
                        adv = r / 7.0
                        white_score += adv
                    else:
                        adv = (7 - r) / 7.0
                        black_score += adv
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn promotion threat difference: sum over passed pawns of (1.0 / distance_to_promotion), (White - Black)'
    try:
        def is_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            for other_sq, other_p in board.piece_map().items():
                if other_p.piece_type != chess.PAWN or other_p.color == color:
                    continue
                of = chess.square_file(other_sq)
                orr = chess.square_rank(other_sq)
                if abs(of - f) <= 1:
                    # for white pawn, opponent pawn ahead (or at) blocks passing
                    if color == chess.WHITE and orr > r:
                        return False
                    if color == chess.BLACK and orr < r:
                        return False
            return True
        score = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type != chess.PAWN:
                continue
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                dist = 7 - r
            else:
                dist = r
            if dist <= 0:
                continue
            if is_passed(sq, p.color):
                score += (1.0 / dist) if p.color == chess.WHITE else -(1.0 / dist)
        return float(score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Immediate capture value available difference: sum of captured-piece centipawn values for White - Black over legal captures'
    try:
        VALUES = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0, chess.KING:0.0}
        white_cap = 0.0
        black_cap = 0.0
        for mv in board.legal_moves:
            to_sq = getattr(mv, 'to_square', None)
            from_sq = getattr(mv, 'from_square', None)
            if to_sq is None or from_sq is None:
                continue
            target = board.piece_at(to_sq)
            mover = board.piece_at(from_sq)
            if target is None or mover is None:
                # ignore en-passant or ambiguous cases where destination appears empty
                continue
            if target.color == mover.color:
                continue
            val = VALUES.get(target.piece_type, 0.0)
            if mover.color == chess.WHITE:
                white_cap += val
            else:
                black_cap += val
        return float(white_cap - black_cap)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material balance (white minus black) in pawns=100 n=320 b=330 r=500 q=900 units, returned in pawn-equivalents (divide by 100)'
    try:
        values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        w = 0
        b = 0
        for sq, pc in board.piece_map().items():
            val = values.get(pc.piece_type, 0)
            if pc.color == chess.WHITE:
                w += val
            else:
                b += val
        return float((w - b) / 100.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of "unstoppable" passed pawns weighted by advancement (white minus black). A pawn is counted as unstoppable if the opposing king is farther (Manhattan) from its promotion square than the pawn needs to promote.'
    try:
        import chess
        result_white = 0.0
        result_black = 0.0
        piece_map = board.piece_map()
        # find kings for distance calculations
        white_king_sq = None
        black_king_sq = None
        for sq, pc in piece_map.items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    white_king_sq = sq
                else:
                    black_king_sq = sq
        for sq, pc in piece_map.items():
            if pc.piece_type != chess.PAWN:
                continue
            rank = chess.square_rank(sq)
            file = chess.square_file(sq)
            if pc.color == chess.WHITE:
                steps = 7 - rank
                promo_sq = chess.square(file, 7)
                king_dist = chess.square_distance(promo_sq, black_king_sq) if black_king_sq is not None else 100
                if king_dist > steps:
                    # weight by advancement: more advanced pawns count more
                    weight = 1.0 + (rank / 7.0)
                    result_white += weight
            else:
                steps = rank - 0
                promo_sq = chess.square(file, 0)
                king_dist = chess.square_distance(promo_sq, white_king_sq) if white_king_sq is not None else 100
                if king_dist > steps:
                    weight = 1.0 + ((7 - rank) / 7.0)
                    result_black += weight
        return float(result_white - result_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Bishop blockage: for each bishop compute (potential diagonal reach ignoring legality) - (legal moves available); sum for white minus black (higher means more blocked)'
    vm = board.piece_map()
    # map legal moves counts per origin square
    legal_from_count = {}
    for mv in board.legal_moves:
        legal_from_count[mv.from_square] = legal_from_count.get(mv.from_square, 0) + 1
    def potential_diagonal_reach(sq, color):
        file = chess.square_file(sq)
        rank = chess.square_rank(sq)
        total = 0
        # four diagonal directions: (df,dr) pairs
        for df, dr in ((1,1),(1,-1),(-1,1),(-1,-1)):
            f = file + df
            r = rank + dr
            while 0 <= f <= 7 and 0 <= r <= 7:
                psq = chess.square(f, r)
                p = board.piece_at(psq)
                total += 1.0
                if p is not None:
                    break  # blocked by piece (capture square counted)
                f += df
                r += dr
        return total
    white_block = 0.0
    black_block = 0.0
    for sq, p in vm.items():
        if p.piece_type != chess.BISHOP:
            continue
        potential = potential_diagonal_reach(sq, p.color)
        legal = float(legal_from_count.get(sq, 0))
        blocked_amount = potential - legal
        if blocked_amount < 0.0:
            blocked_amount = 0.0
        if p.color == chess.WHITE:
            white_block += blocked_amount
        else:
            black_block += blocked_amount
    return float(white_block - black_block)

def feature(board: chess.Board) -> float:
    'Trapped piece count difference: number of non-king pieces with no legal non-attacked destination (white - black)'
    try:
        pm = board.piece_map()
        white_trapped = 0.0
        black_trapped = 0.0
        # Precompute legal moves grouped by from_square
        moves_by_from = {}
        for m in board.legal_moves:
            moves_by_from.setdefault(m.from_square, []).append(m.to_square)
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                continue
            dests = moves_by_from.get(sq, [])
            if not dests:
                # no legal moves from this piece -> trapped
                if p.color == chess.WHITE:
                    white_trapped += 1.0
                else:
                    black_trapped += 1.0
            else:
                opp = not p.color
                # if all destinations are attacked by opponent, consider trapped
                all_attacked = True
                for to_sq in dests:
                    if not board.is_attacked_by(opp, to_sq):
                        all_attacked = False
                        break
                if all_attacked:
                    if p.color == chess.WHITE:
                        white_trapped += 1.0
                    else:
                        black_trapped += 1.0
        return float(white_trapped - black_trapped)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Connected passed pawns (white - black): count of passed pawns that have a friendly pawn on an adjacent file supporting them'
    piece_map = board.piece_map()
    pawns_by_color = {chess.WHITE:[], chess.BLACK:[]}
    for sq, pc in piece_map.items():
        if pc.piece_type == chess.PAWN:
            pawns_by_color[pc.color].append(sq)
    def is_passed(p_sq, color):
        f = chess.square_file(p_sq); r = chess.square_rank(p_sq)
        if color == chess.WHITE:
            for sq2 in pawns_by_color[chess.BLACK]:
                if abs(chess.square_file(sq2) - f) <= 1 and chess.square_rank(sq2) > r:
                    return False
            return True
        else:
            for sq2 in pawns_by_color[chess.WHITE]:
                if abs(chess.square_file(sq2) - f) <= 1 and chess.square_rank(sq2) < r:
                    return False
            return True
    white_conn = 0.0; black_conn = 0.0
    for color in (chess.WHITE, chess.BLACK):
        for sq in pawns_by_color[color]:
            if not is_passed(sq, color): continue
            f = chess.square_file(sq); r = chess.square_rank(sq)
            connected = False
            for df in (-1,1):
                nf = f + df
                if 0 <= nf <= 7:
                    # find any friendly pawn on adjacent file with rank >= (for white) or <= (for black) this pawn
                    for sq2 in pawns_by_color[color]:
                        if chess.square_file(sq2) == nf:
                            r2 = chess.square_rank(sq2)
                            if (color == chess.WHITE and r2 >= r) or (color == chess.BLACK and r2 <= r):
                                connected = True; break
                    if connected: break
            if connected:
                if color == chess.WHITE: white_conn += 1.0
                else: black_conn += 1.0
    return white_conn - black_conn

def feature(board: chess.Board) -> float:
    'Queen distress: (White queen legal moves - Black queen legal moves) penalized when queen is attacked and undefended'
    try:
        pm = board.piece_map()
        white_q = next((sq for sq, p in pm.items() if p.piece_type == chess.QUEEN and p.color == chess.WHITE), None)
        black_q = next((sq for sq, p in pm.items() if p.piece_type == chess.QUEEN and p.color == chess.BLACK), None)
        white_q_moves = 0
        black_q_moves = 0
        for mv in board.legal_moves:
            if white_q is not None and mv.from_square == white_q:
                white_q_moves += 1
            if black_q is not None and mv.from_square == black_q:
                black_q_moves += 1
        def attack_penalty(q_sq, q_color):
            if q_sq is None:
                return 0.0
            attackers = len(board.attackers(not q_color, q_sq))
            defenders = len(board.attackers(q_color, q_sq))
            return max(0, attackers - defenders) * 0.5
        pen = attack_penalty(white_q, chess.WHITE) - attack_penalty(black_q, chess.BLACK)
        return float((white_q_moves - black_q_moves) - pen)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material balance excluding queens, returned in pawn units (White - Black) using weights P=100 N=320 B=330 R=500, then divided by 100'
    values = {
        chess.PAWN: 100,
        chess.KNIGHT: 320,
        chess.BISHOP: 330,
