def feature(board: chess.Board) -> float:
    'Edge-trapped piece penalty: pieces on the edge with <=1 legal moves weighted by piece value and distance-from-center (White - Black)'
    try:
        values = {chess.QUEEN:9.0, chess.ROOK:5.0, chess.BISHOP:3.0, chess.KNIGHT:3.0, chess.PAWN:1.0, chess.KING:0.0}
        pm = board.piece_map()
        moves_from = {}
        for m in board.legal_moves:
            moves_from[m.from_square] = moves_from.get(m.from_square, 0) + 1
        center_squares = [chess.parse_square(s) for s in ('d4','e4','d5','e5')]
        score = 0.0
        for sq, p in pm.items():
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if f in (0,7) or r in (0,7):
                mobility = moves_from.get(sq, 0)
                if mobility <= 1 and p.piece_type != chess.KING:
                    dist = min(chess.square_distance(sq, c) for c in center_squares)
                    weight = values.get(p.piece_type, 0.0) * (1.0 + (dist / 4.0))
                    score += (weight if p.color == chess.WHITE else -weight)
        return float(score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Fraction of material considered "safe" (not attacked or defended at least as many times as attacked) for White minus Black, range roughly -1..1'
    values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900}
    white_total = 0
    black_total = 0
    white_safe = 0
    black_safe = 0
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.KING:
            continue
        val = values.get(p.piece_type,0)
        if p.color == chess.WHITE:
            white_total += val
            attackers = len(board.attackers(not p.color, sq))
            defenders = len(board.attackers(p.color, sq))
            if attackers == 0 or defenders >= attackers:
                white_safe += val
        else:
            black_total += val
            attackers = len(board.attackers(not p.color, sq))
            defenders = len(board.attackers(p.color, sq))
            if attackers == 0 or defenders >= attackers:
                black_safe += val
    # avoid division by zero
    w_frac = (white_safe / white_total) if white_total > 0 else 0.0
    b_frac = (black_safe / black_total) if black_total > 0 else 0.0
    return float(w_frac - b_frac)

def feature(board: chess.Board) -> float:
    'Pressure on major pieces: weighted attackers on rooks/queens (Black pressure on White majors minus White on Black)'
    try:
        pm = board.piece_map()
        values = {chess.ROOK:5.0, chess.QUEEN:9.0}
        def pressure_on_majors(victim_color):
            total = 0.0
            for sq, p in pm.items():
                if p and p.color==victim_color and p.piece_type in values:
                    attackers = board.attackers(not victim_color, sq)
                    atk_count = len(attackers)
                    total += float(atk_count) * values[p.piece_type]
            return total
        black_on_white = pressure_on_majors(chess.WHITE)
        white_on_black = pressure_on_majors(chess.BLACK)
        return float(black_on_white - white_on_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
