                sq = chess.square(f,r)
                w_att += len(board.attackers(chess.WHITE, sq))
                b_att += len(board.attackers(chess.BLACK, sq))
        # normalize by a modest factor to keep scale moderate
        return float((w_att - b_att) / 8.0)
    except Exception:
