def feature(board: chess.Board) -> float:
    'Bishop mobility proxy: difference in effective bishop mobility where each bishop is penalized by number of own pawns on same-colored squares (white minus black).'
    try:
        pieces = board.piece_map()
        def square_color(sq):
            return (chess.square_file(sq) + chess.square_rank(sq)) & 1
        def bishop_score(color):
            score = 0.0
            # collect own pawn squares color counts
            pawn_color_count = {0:0,1:0}
            for sq,p in pieces.items():
                if p.piece_type == chess.PAWN and p.color==color:
                    pawn_color_count[square_color(sq)] += 1
            for sq,p in pieces.items():
                if p.piece_type == chess.BISHOP and p.color==color:
                    sc = square_color(sq)
                    # bishops are good when few own pawns on same color
                    penalty = pawn_color_count.get(sc,0) * 0.25
                    score += 1.0 - penalty
            return score
        return float(bishop_score(chess.WHITE) - bishop_score(chess.BLACK))
    except Exception:
        return 0.0

