def feature(board: chess.Board) -> float:
    'Piece centralization index: sum of piece-value * centrality (closer to center squares d4/d5/e4/e5 is better) (white - black)'
    pm = board.piece_map()
    vals = {chess.PAWN:0.8, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:2.5, chess.QUEEN:7.5, chess.KING:1.0}
    center_sqs = [chess.square(3,3), chess.square(4,3), chess.square(3,4), chess.square(4,4)]
    white_score = 0.0
    black_score = 0.0
    for sq,p in pm.items():
        if p is None: continue
        # Manhattan distance to nearest center square
        dmin = min(chess.square_distance(sq, c) for c in center_sqs)
        # map 0..7 -> centrality 1..0
        centrality = max(0.0, (8.0 - float(dmin)) / 8.0)
        weight = vals.get(p.piece_type, 0.0)
        if p.color == chess.WHITE:
            white_score += weight * centrality
        else:
            black_score += weight * centrality
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Net safe-adjacent-escape count for major pieces (queen/rook): sum of empty neighbor squares not attacked by opponent (White minus Black)'
    piece_map = board.piece_map()
    white_safe = 0
    black_safe = 0
    for sq, p in piece_map.items():
        if p.piece_type not in (chess.QUEEN, chess.ROOK):
            continue
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        opp = not p.color
        safe = 0
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                if df == 0 and dr == 0:
                    continue
                ff = f + df
                rr = r + dr
                if 0 <= ff <= 7 and 0 <= rr <= 7:
                    sq_name = chr(ord('a') + ff) + str(rr + 1)
                    nsq = chess.parse_square(sq_name)
                    occ = board.piece_at(nsq)
                    try:
                        attacked = board.is_attacked_by(opp, nsq)
                    except Exception:
                        attacked = False
                    if occ is None and not attacked:
                        safe += 1
        if p.color == chess.WHITE:
            white_safe += safe
        else:
            black_safe += safe
    return float(white_safe - black_safe)

def feature(board: chess.Board) -> float:
    'Count of pieces with no legal moves (excluding kings) for White minus Black: potential trapped pieces'
    try:
        pm = board.piece_map()
        # map how many legal moves originate from each square
        moves_from = {}
        for mv in board.legal_moves:
            moves_from[mv.from_square] = moves_from.get(mv.from_square, 0) + 1
        white_trapped = 0
        black_trapped = 0
        for sq, p in pm.items():
            if p is None:
                continue
            if p.piece_type == chess.KING:
                continue
            # If piece exists but has zero legal moves from its square, count as trapped
            if moves_from.get(sq, 0) == 0:
                # Also ensure the piece actually has at least one pseudo-legal move normally (simple heuristic: check attacked/blocked not required)
                if p.color == chess.WHITE:
                    white_trapped += 1
                else:
                    black_trapped += 1
        return float(white_trapped - black_trapped)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Central pawn presence and chain strength (White minus Black): counts pawns on d/e files and pawns defended by other pawns'
    try:
        pm = board.piece_map()
        def pawn_central_chain_score(color):
            score = 0.0
            for sq, p in pm.items():
                if p.piece_type == chess.PAWN and p.color == color:
                    f = chess.square_file(sq)
                    r = chess.square_rank(sq)
                    # central file bonus (d=3, e=4)
                    if f in (3,4):
                        # more advanced central pawn gets more
                        rank_adv = r if color == chess.WHITE else (7 - r)
                        score += 0.6 + 0.4 * (rank_adv / 7.0)
                    # pawn defended by a pawn (chain)
                    for df, dr in ((-1, -1), (1, -1)) if color == chess.WHITE else ((-1, 1), (1, 1)):
                        nf, nr = f + df, r + dr
                        if 0 <= nf <= 7 and 0 <= nr <= 7:
                            nsq = nr*8 + nf
                            q = board.piece_at(nsq)
                            if q and q.piece_type == chess.PAWN and q.color == color:
                                score += 0.25
                                break
            return score
        return float(pawn_central_chain_score(chess.WHITE) - pawn_central_chain_score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Weak squares near king balance (White - Black): empty squares within Manhattan distance 2 of king that are not defended by a friendly pawn'
    try:
        pieces = board.piece_map()
        def weak_squares_for(color):
            ksq = None
            for sq, pc in pieces.items():
                if pc.piece_type == chess.KING and pc.color == color:
                    ksq = sq
                    break
            if ksq is None:
                return 0
            kf = chess.square_file(ksq)
            kr = chess.square_rank(ksq)
            cnt = 0
            for f in range(0,8):
                for r in range(0,8):
                    sq = chess.square(f, r)
                    if chess.square_distance(sq, ksq) <= 2:
                        if sq in pieces:
                            continue
                        attackers = board.attackers(color, sq)
                        pawn_defended = False
                        for a in attackers:
                            pc = pieces.get(a)
                            if pc is not None and pc.piece_type == chess.PAWN and pc.color == color:
                                pawn_defended = True
                                break
                        if not pawn_defended:
                            cnt += 1
            return cnt
        return float(weak_squares_for(chess.WHITE) - weak_squares_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of heavy pieces (rook or queen) on the opponent king file: (Black heavy pieces on White king file - White heavy pieces on Black king file)'
    pm = board.piece_map()
    wking = None
    bking = None
    for sq, pc in pm.items():
        if pc.piece_type == chess.KING:
            if pc.color == chess.WHITE:
                wking = sq
            else:
                bking = sq
    def heavy_on_file(king_sq, attacker_color):
        if king_sq is None:
            return 0
        target_file = chess.square_file(king_sq)
        cnt = 0
        for sq, pc in pm.items():
            if pc is None:
                continue
            if pc.color != attacker_color:
                continue
            if pc.piece_type in (chess.ROOK, chess.QUEEN) and chess.square_file(sq) == target_file:
                cnt += 1
        return cnt
    black_on_white = heavy_on_file(wking, chess.BLACK)
    white_on_black = heavy_on_file(bking, chess.WHITE)
    return float(black_on_white - white_on_black)

def feature(board: chess.Board) -> float:
    'Combined pawn-structure weakness score: (doubled + isolated) pawns difference (white - black)'
    try:
        pm = board.piece_map()
        # count pawns per file
        files_white = [0]*8
        files_black = [0]*8
        pawns_white_squares = []
        pawns_black_squares = []
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if p.color == chess.WHITE:
                    files_white[f] += 1
                    pawns_white_squares.append(sq)
                else:
                    files_black[f] += 1
                    pawns_black_squares.append(sq)
        def weakness(files, pawn_sqs, color):
            doubled = sum(max(0, c-1) for c in files)
            isolated = 0
            for sq in pawn_sqs:
                f = chess.square_file(sq)
                left = f-1
                right = f+1
                has_neighbor = False
                if 0 <= left <= 7 and files[left] > 0:
                    has_neighbor = True
                if 0 <= right <= 7 and files[right] > 0:
                    has_neighbor = True
                if not has_neighbor:
                    isolated += 1
            return doubled + isolated
        wweak = weakness(files_white, pawns_white_squares, chess.WHITE)
        bweak = weakness(files_black, pawns_black_squares, chess.BLACK)
        return float(wweak - bweak)
    except Exception:
        return 0.0

