def feature(board: chess.Board) -> float:
    'Blocked minor pieces difference: counts of bishops/knights whose nearby squares are blocked by own pawns or have low static mobility (White - Black)'
    import chess
    try:
        piece_map = board.piece_map()
        def blocked_minors(color):
            blocked = 0.0
            for sq, p in piece_map.items():
                if p.color != color:
                    continue
                if p.piece_type == chess.BISHOP:
                    f = chess.square_file(sq)
                    r = chess.square_rank(sq)
                    # check immediate diagonal neighbors; if both diagonals in at least one direction blocked by own pawn, count
                    diag_blocks = 0
                    for df, dr in ((1,1),(1,-1),(-1,1),(-1,-1)):
                        nf = f + df
                        nr = r + dr
                        if 0 <= nf <= 7 and 0 <= nr <= 7:
                            sq2 = chess.square(nf, nr)
                            p2 = piece_map.get(sq2)
                            if p2 and p2.color == color and p2.piece_type == chess.PAWN:
                                diag_blocks += 1
                    # if bishop has 2+ immediate pawn blocks treat as restricted
                    if diag_blocks >= 2:
                        blocked += 1.0
                elif p.piece_type == chess.KNIGHT:
                    knight_moves = [(2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)]
                    f = chess.square_file(sq)
                    r = chess.square_rank(sq)
                    free_targets = 0
                    for df, dr in knight_moves:
                        nf = f + df
                        nr = r + dr
                        if 0 <= nf <= 7 and 0 <= nr <= 7:
                            sq2 = chess.square(nf, nr)
                            p2 = piece_map.get(sq2)
                            if p2 is None or p2.color != color:
                                free_targets += 1
                    # if knight has <=2 free targets consider it restricted/blocked
                    if free_targets <= 2:
                        blocked += 1.0
            return blocked
        return float(blocked_minors(chess.WHITE) - blocked_minors(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Mobility-weighted material: sum over pieces of (piece value * number of legal moves from that square) difference (White - Black), scaled'
    values = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0, chess.KING:0.0}
    try:
        wcopy = board.copy(); wcopy.turn = chess.WHITE
        bcopy = board.copy(); bcopy.turn = chess.BLACK
        w_moves_from = {}
        b_moves_from = {}
        for mv in wcopy.legal_moves:
            w_moves_from.setdefault(mv.from_square, 0)
            w_moves_from[mv.from_square] += 1
        for mv in bcopy.legal_moves:
            b_moves_from.setdefault(mv.from_square, 0)
            b_moves_from[mv.from_square] += 1
        wsum = 0.0; bsum = 0.0
        for sq,p in board.piece_map().items():
            mvcount = (w_moves_from.get(sq,0) if p.color==chess.WHITE else b_moves_from.get(sq,0))
            val = values.get(p.piece_type, 0.0)
            if p.color == chess.WHITE:
                wsum += val * mvcount
            else:
                bsum += val * mvcount
        return float((wsum - bsum) / 100.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Minor-piece centralization difference: (Black average distance to center) - (White average distance to center); positive means White more centralized'
    try:
        pm = board.piece_map()
        center_sqs = [chess.parse_square(s) for s in ('d4','d5','e4','e5')]
        def avg_dist(color):
            dists = []
            for sq, p in pm.items():
                if p.color == color and (p.piece_type == chess.KNIGHT or p.piece_type == chess.BISHOP):
                    md = min(chess.square_distance(sq, c) for c in center_sqs)
                    dists.append(md)
            if not dists:
                return 8.0
            return sum(dists) / len(dists)
        return float(avg_dist(chess.BLACK) - avg_dist(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn shield integrity: count pawns directly in front (1-2 ranks) and on adjacent files of each king (white minus black)'
    try:
        pm = board.piece_map()
        def shield_count(color):
            king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == color), None)
            if king_sq is None:
                return 0.0
            f = chess.square_file(king_sq)
            r = chess.square_rank(king_sq)
            files = [ff for ff in (f-1, f, f+1) if 0 <= ff <= 7]
            ranks = []
            if color == chess.WHITE:
                ranks = [nr for nr in (r+1, r+2) if 0 <= nr <= 7]
            else:
                ranks = [nr for nr in (r-1, r-2) if 0 <= nr <= 7]
            count = 0
            for nf in files:
                for nr in ranks:
                    sq = chess.square(nf, nr)
                    pc = board.piece_at(sq)
                    if pc is not None and pc.piece_type == chess.PAWN and pc.color == color:
                        count += 1
            return float(count)
        return shield_count(chess.WHITE) - shield_count(chess.BLACK)
    except Exception:
        return 0.0

