def feature(board: chess.Board) -> float:
    'King exposure via unobstructed enemy lines: weighted count of opponent sliding attackers (rook/bishop/queen) that have an unobstructed ray to any square in king zone (white minus black)'
    try:
        piece_map = board.piece_map()
        wking = next((sq for sq, p in piece_map.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        bking = next((sq for sq, p in piece_map.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        if wking is None or bking is None:
            return 0.0
        def king_zone(sq):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            zones = []
            for df in (-1,0,1):
                for dr in (-1,0,1):
                    nf, nr = f+df, r+dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        zones.append(chess.square(nf, nr))
            return set(zones)
        wz = king_zone(wking)
        bz = king_zone(bking)
        def ray_unobstructed(src, target):
            sf, sr = chess.square_file(src), chess.square_rank(src)
            tf, tr = chess.square_file(target), chess.square_rank(target)
            df = tf - sf
            dr = tr - sr
            stepf = 0 if df == 0 else (1 if df > 0 else -1)
            stepr = 0 if dr == 0 else (1 if dr > 0 else -1)
            # must be straight line or diagonal
            if (stepf == 0 or stepr == 0) or (abs(df) == abs(dr)):
                nf, nr = sf + stepf, sr + stepr
                while (nf, nr) != (tf, tr):
                    if not (0 <= nf <= 7 and 0 <= nr <= 7):
                        return False
                    if board.piece_at(chess.square(nf, nr)) is not None:
                        return False
                    nf += stepf; nr += stepr
                return True
            return False
        def exposure_for(color):
            total = 0.0
            # attackers are opponent pieces aiming at king zone
            for sq, p in piece_map.items():
                if p.color != color and p.piece_type in (chess.ROOK, chess.BISHOP, chess.QUEEN):
                    # check if this piece has unobstructed ray to any square in color's king zone
                    target_zone = wz if color == chess.WHITE else bz
                    for tz in target_zone:
                        if ray_unobstructed(sq, tz):
                            # weight by piece type
                            w = 1.0 if p.piece_type == chess.ROOK else (0.9 if p.piece_type == chess.BISHOP else 1.2)
                            total += w
                            break
            return total
        wexp = exposure_for(chess.WHITE)
        bexp = exposure_for(chess.BLACK)
        return float(wexp - bexp)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of attackers (enemy pieces) attacking the most advanced pawn promotion square: (white_promo_defenders_by_enemy - black_promo_defenders_by_enemy)'
    try:
        pm = board.piece_map()
        white_pawns = [sq for sq, p in pm.items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        black_pawns = [sq for sq, p in pm.items() if p.piece_type == chess.PAWN and p.color == chess.BLACK]
        def promo_square_of_most_advanced(pawns, color):
            if not pawns:
                return None
            if color == chess.WHITE:
                s = max(pawns, key=lambda x: chess.square_rank(x))
                f = chess.square_file(s); r = 7
            else:
                s = min(pawns, key=lambda x: chess.square_rank(x))
                f = chess.square_file(s); r = 0
            return r*8 + f
        w_promo = promo_square_of_most_advanced(white_pawns, chess.WHITE)
        b_promo = promo_square_of_most_advanced(black_pawns, chess.BLACK)
        def enemy_attackers_to(square, enemy_color):
            if square is None:
                return 0
            atk = board.attackers(enemy_color, square)
            return len(atk) if atk is not None else 0
        # attackers of white promo square by black minus attackers of black promo square by white
        w_def_by_black = enemy_attackers_to(w_promo, chess.BLACK)
        b_def_by_white = enemy_attackers_to(b_promo, chess.WHITE)
        return float(w_def_by_black - b_def_by_white)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Knights on central/outpost squares: central (d4,e4,d5,e5) weighted 1.0, near-central weighted 0.5; returns (White - Black)'
    central = {chess.parse_square(s) for s in ['d4','e4','d5','e5']}
    near = set()
    # generate near central squares manually
    for name in ['c3','c4','c5','d3','e3','f3','f4','f5','c2','f2','b4','g4','b5','g5']:
        try:
            near.add(chess.parse_square(name))
        except Exception:
            pass
    pm = board.piece_map()
    w = b = 0.0
    for sq, pc in pm.items():
        if pc.piece_type != chess.KNIGHT:
            continue
        if sq in central:
            val = 1.0
        elif sq in near:
            val = 0.5
        else:
            val = 0.0
        if pc.color == chess.WHITE:
            w += val
        else:
            b += val
    return w - b

def feature(board: chess.Board) -> float:
    'Difference in number of connected passed pawns (white minus black); a passed pawn is "connected" if a friendly pawn exists on an adjacent file within one rank distance'
    try:
        def is_passed_local(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                for ff in range(max(0, f - 1), min(7, f + 1) + 1):
                    for rr in range(r + 1, 8):
                        occ = board.piece_at(chess.square(ff, rr))
                        if occ is not None and occ.piece_type == chess.PAWN and occ.color == chess.BLACK:
                            return False
                return True
            else:
                for ff in range(max(0, f - 1), min(7, f + 1) + 1):
                    for rr in range(0, r):
                        occ = board.piece_at(chess.square(ff, rr))
                        if occ is not None and occ.piece_type == chess.PAWN and occ.color == chess.WHITE:
                            return False
                return True
        def connected_passed(color):
            cnt = 0
            for sq, pc in board.piece_map().items():
                if pc.piece_type == chess.PAWN and pc.color == color and is_passed_local(sq, color):
                    f = chess.square_file(sq)
                    r = chess.square_rank(sq)
                    connected = False
                    for ff in range(max(0, f - 1), min(7, f + 1) + 1):
                        for rr in range(max(0, r - 1), min(7, r + 1) + 1):
                            if ff == f and rr == r:
                                continue
                            occ = board.piece_at(chess.square(ff, rr))
                            if occ is not None and occ.piece_type == chess.PAWN and occ.color == color:
                                connected = True
                                break
                        if connected:
                            break
                    if connected:
                        cnt += 1
            return cnt
        return float(connected_passed(chess.WHITE) - connected_passed(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Average piece centralization: (black average distance to center - white average distance to center), positive favors White'
    try:
        pm = board.piece_map()
        centers = [chess.parse_square(s) for s in ('d4','e4','d5','e5')]
        def avg_center_dist(color):
            dsum = 0.0; count = 0
            for sq, p in pm.items():
                if p.color != color:
                    continue
                if p.piece_type == chess.KING:
                    continue
                d = min(chess.square_distance(sq, c) for c in centers)
                dsum += d; count += 1
            if count == 0:
                return 8.0
            return dsum / count
        return float((avg_center_dist(chess.BLACK) - avg_center_dist(chess.WHITE)) / 8.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
