                return None
            if color == chess.WHITE:
                s = max(pawns, key=lambda x: chess.square_rank(x))
                f = chess.square_file(s); r = 7
            else:
                s = min(pawns, key=lambda x: chess.square_rank(x))
                f = chess.square_file(s); r = 0
            return r*8 + f
        w_promo = promo_square_of_most_advanced(white_pawns, chess.WHITE)
        b_promo = promo_square_of_most_advanced(black_pawns, chess.BLACK)
        def enemy_attackers_to(square, enemy_color):
            if square is None:
                return 0
            atk = board.attackers(enemy_color, square)
            return len(atk) if atk is not None else 0
        # attackers of white promo square by black minus attackers of black promo square by white
        w_def_by_black = enemy_attackers_to(w_promo, chess.BLACK)
        b_def_by_white = enemy_attackers_to(b_promo, chess.WHITE)
        return float(w_def_by_black - b_def_by_white)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Average weighted proximity of opponent major/minor pieces to each king: (Black pieces proximity to White king) - (White pieces proximity to Black king). Higher positive => Black pieces are closer to White king (bad for White).'
    try:
        values = {chess.PAWN:0.5, chess.KNIGHT:1.0, chess.BISHOP:1.0, chess.ROOK:1.5, chess.QUEEN:2.0, chess.KING:0.0}
        # find kings
        wking = None
        bking = None
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    wking = sq
                else:
                    bking = sq
        def proximity_sum(target_king_sq, attackers_color):
            if target_king_sq is None:
                return 0.0
            s = 0.0
            for sq, pc in board.piece_map().items():
                if pc.color != attackers_color:
                    continue
                if pc.piece_type == chess.KING:
                    continue
                d = chess.square_distance(sq, target_king_sq)
                # weight inverse to distance (closer -> more)
                s += values.get(pc.piece_type, 0.0) / (1.0 + float(d))
            return s

        black_on_white = proximity_sum(wking, chess.BLACK)
        white_on_black = proximity_sum(bking, chess.WHITE)
        return black_on_white - white_on_black
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Local congestion metric difference: average number of same-color pieces within Chebyshev distance 1 of each piece (white - black)'
    piece_map = board.piece_map()
    w_counts = []
    b_counts = []
    for sq, pc in piece_map.items():
        f = chess.square_file(sq); r = chess.square_rank(sq)
        count = 0
        for df in (-1,0,1):
            for dr in (-1,0,1):
                if df == 0 and dr == 0:
                    continue
                nf, nr = f+df, r+dr
                if 0 <= nf <= 7 and 0 <= nr <= 7:
                    np = board.piece_at(chess.square(nf, nr))
                    if np is not None and np.color == pc.color:
                        count += 1
        if pc.color == chess.WHITE:
            w_counts.append(count)
        else:
            b_counts.append(count)
    w_avg = sum(w_counts)/len(w_counts) if w_counts else 0.0
    b_avg = sum(b_counts)/len(b_counts) if b_counts else 0.0
    return float(b_avg - w_avg)

def feature(board: chess.Board) -> float:
    'White minus Black: sum over passed pawns of whether a rook of the same color sits directly behind the pawn on the same file, weighted by pawn advancement (0..1)'
    result_w = 0.0
    result_b = 0.0
    try:
        pieces = board.piece_map()
    except Exception:
        return 0.0
    # find pawns and rooks
    pawns = [(sq, p) for sq, p in pieces.items() if p.piece_type == chess.PAWN]
    rooks = [(sq, p) for sq, p in pieces.items() if p.piece_type == chess.ROOK]
    # helper to test passed pawn
    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            for opp_sq, opp_piece in pawns:
                if opp_piece.color == chess.BLACK:
                    ff = chess.square_file(opp_sq)
                    rr = chess.square_rank(opp_sq)
                    if abs(ff - f) <= 1 and rr >= r:
                        return False
            return True
        else:
            for opp_sq, opp_piece in pawns:
                if opp_piece.color == chess.WHITE:
                    ff = chess.square_file(opp_sq)
                    rr = chess.square_rank(opp_sq)
                    if abs(ff - f) <= 1 and rr <= r:
                        return False
            return True
    for sq, p in pawns:
        color = p.color
        if not is_passed(sq, color):
            continue
        rank = chess.square_rank(sq)
        advancement = (rank / 7.0) if color == chess.WHITE else ((7 - rank) / 7.0)
        # check rooks on same file behind pawn
        f = chess.square_file(sq)
        for r_sq, r_piece in rooks:
            if r_piece.color != color:
                continue
            if chess.square_file(r_sq) != f:
                continue
            rrank = chess.square_rank(r_sq)
            if color == chess.WHITE:
                if rrank < rank:
                    if color == chess.WHITE:
                        result_w += advancement
                    else:
                        result_b += advancement
            else:
                if rrank > rank:
                    if color == chess.WHITE:
                        result_w += advancement
                    else:
                        result_b += advancement
    return float(result_w - result_b)

def feature(board: chess.Board) -> float:
    'Central pawn presence and chain strength (White minus Black): counts pawns on d/e files and pawns defended by other pawns'
    try:
        pm = board.piece_map()
        def pawn_central_chain_score(color):
            score = 0.0
            for sq, p in pm.items():
                if p.piece_type == chess.PAWN and p.color == color:
                    f = chess.square_file(sq)
                    r = chess.square_rank(sq)
                    # central file bonus (d=3, e=4)
                    if f in (3,4):
                        # more advanced central pawn gets more
                        rank_adv = r if color == chess.WHITE else (7 - r)
                        score += 0.6 + 0.4 * (rank_adv / 7.0)
                    # pawn defended by a pawn (chain)
                    for df, dr in ((-1, -1), (1, -1)) if color == chess.WHITE else ((-1, 1), (1, 1)):
                        nf, nr = f + df, r + dr
                        if 0 <= nf <= 7 and 0 <= nr <= 7:
                            nsq = nr*8 + nf
                            q = board.piece_at(nsq)
                            if q and q.piece_type == chess.PAWN and q.color == color:
                                score += 0.25
                                break
            return score
        return float(pawn_central_chain_score(chess.WHITE) - pawn_central_chain_score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material balance (white minus black) in pawns=100 n=320 b=330 r=500 q=900 units, returned in pawn-equivalents (divide by 100)'
    try:
        values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        w = 0
        b = 0
        for sq, pc in board.piece_map().items():
            val = values.get(pc.piece_type, 0)
            if pc.color == chess.WHITE:
                w += val
            else:
                b += val
        return float((w - b) / 100.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in king proximity to a corner (8 - Manhattan distance) (white minus black) — higher means closer to corner'
    try:
        corners = [chess.A1, chess.H1, chess.A8, chess.H8]
        pm = board.piece_map()
        def min_corner_score(color):
            king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == color), None)
            if king_sq is None:
                return 0.0
            md = min(chess.square_distance(king_sq, c) for c in corners)
            # normalize to a positive small scale
            return float(max(0.0, 8.0 - md))
        return min_corner_score(chess.WHITE) - min_corner_score(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed-pawn clear-promotion score: for each passed pawn, reward if its promotion square is less attacked by the opponent, weighted by advancement (White minus Black)'
    pm = board.piece_map()
    def is_passed(sq, color):
        file = chess.square_file(sq)
        rank = chess.square_rank(sq)
        opp = chess.BLACK if color == chess.WHITE else chess.WHITE
        if color == chess.WHITE:
            for r in range(rank + 1, 8):
                for f in range(max(0, file - 1), min(7, file + 1) + 1):
                    p = board.piece_at(f + 8 * r)
                    if p is not None and p.color == opp and p.piece_type == chess.PAWN:
                        return False
            return True
        else:
            for r in range(rank - 1, -1, -1):
                for f in range(max(0, file - 1), min(7, file + 1) + 1):
                    p = board.piece_at(f + 8 * r)
                    if p is not None and p.color == opp and p.piece_type == chess.PAWN:
                        return False
            return True
    white_score = 0.0
    black_score = 0.0
    for sq, piece in pm.items():
        if piece.piece_type != chess.PAWN:
            continue
        file = chess.square_file(sq)
        rank = chess.square_rank(sq)
        if is_passed(sq, piece.color):
            # promotion square
            if piece.color == chess.WHITE:
                promo_sq = file + 8 * 7
                opp = chess.BLACK
                advancement = rank / 7.0
                attacked = 1.0 if board.is_attacked_by(opp, promo_sq) else 0.0
                white_score += advancement * (1.0 - attacked)
            else:
                promo_sq = file + 8 * 0
                opp = chess.WHITE
                advancement = (7 - rank) / 7.0
                attacked = 1.0 if board.is_attacked_by(opp, promo_sq) else 0.0
                black_score += advancement * (1.0 - attacked)
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Material concentration: standard deviation of piece values (excluding kings) for white minus black (higher -> material concentrated in few pieces)'
    try:
        values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900}
        from math import sqrt
        def std_for(color):
            vals = []
            for sq, p in board.piece_map().items():
                if p.color == color and p.piece_type in values:
                    vals.append(values[p.piece_type])
            if not vals:
                return 0.0
            mean = sum(vals)/len(vals)
            var = sum((v-mean)**2 for v in vals)/len(vals)
            return sqrt(var)/100.0  # scale down
        return float(std_for(chess.WHITE) - std_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Support for passed pawns: (sum of friendly attackers to the square in front of each passed pawn, weighted by advancement), positive means White better supported'
    import chess
    pieces = board.piece_map()
    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        for osq, p in pieces.items():
            if p.piece_type == chess.PAWN and p.color != color:
                of = chess.square_file(osq)
                orank = chess.square_rank(osq)
                if abs(of - f) <= 1:
                    if color == chess.WHITE and orank > r:
                        return False
                    if color == chess.BLACK and orank < r:
                        return False
        return True
    support = {chess.WHITE: 0.0, chess.BLACK: 0.0}
    for sq, p in pieces.items():
        if p.piece_type == chess.PAWN and is_passed(sq, p.color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                ahead_r = min(7, r+1)
            else:
                ahead_r = max(0, r-1)
            ahead_sq = chess.square(f, ahead_r)
            # count friendly attackers to the forward square
            attackers = board.attackers(p.color, ahead_sq)
            score = len(attackers)
            # weight by advancement (closer to promotion weights more)
            dist_to_prom = (7 - r) if p.color == chess.WHITE else r
            weight = 1.0 / (1.0 + dist_to_prom)
            support[p.color] += score * weight
    return float(support[chess.WHITE] - support[chess.BLACK])

def feature(board: chess.Board) -> float:
    'Average mobility per non-pawn piece difference: (avg moves by non-pawn pieces White) - (Black)'
    try:
        pm = board.piece_map()
        white_nonpawn = sum(1 for p in pm.values() if p.color == chess.WHITE and p.piece_type != chess.PAWN)
        black_nonpawn = sum(1 for p in pm.values() if p.color == chess.BLACK and p.piece_type != chess.PAWN)
        white_moves = 0
        black_moves = 0
        for mv in board.legal_moves:
            from_sq = getattr(mv, 'from_square', None)
            if from_sq is None:
                continue
            piece = board.piece_at(from_sq)
            if piece is None or piece.piece_type == chess.PAWN:
                continue
            if piece.color == chess.WHITE:
                white_moves += 1
            else:
                black_moves += 1
        avg_w = (white_moves / white_nonpawn) if white_nonpawn > 0 else 0.0
        avg_b = (black_moves / black_nonpawn) if black_nonpawn > 0 else 0.0
        return float(avg_w - avg_b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Back-rank vulnerability difference: (White vulnerability) - (Black vulnerability) where higher means more trapped on back rank'
    try:
        piece_map = board.piece_map()
        def find_king(color):
            for sq, p in piece_map.items():
                if p.piece_type == chess.KING and p.color == color:
                    return sq
            return None
        def backrank_vuln(color):
            ksq = find_king(color)
            if ksq is None:
                return 0.0
            kf = chess.square_file(ksq); kr = chess.square_rank(ksq)
            # if king not on back rank, vulnerability is low
            back_rank = 0 if color == chess.WHITE else 7
            if kr != back_rank:
                return 0.0
            # count luft squares in front of king (same file and adjacent files on the rank in front)
            dr = 1 if color == chess.WHITE else -1
            luft = 0
            for df in (-1, 0, 1):
                f = kf + df; r = kr + dr
                if 0 <= f <= 7 and 0 <= r <= 7:
                    sq = chess.square(f, r)
                    if board.piece_at(sq) is None:
                        luft += 1
            # vulnerability increases as luft decreases; normalize to 0..1 (max vuln when luft=0)
            return (3 - luft) / 3.0
        return backrank_vuln(chess.WHITE) - backrank_vuln(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material value of "loose" (more attackers than defenders) pieces: sum(piece value * (attackers>defenders)) (White - Black)'
    values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:20000}
    pm = board.piece_map()
    white_loose = 0
    black_loose = 0
    for sq, pc in pm.items():
        color = pc.color
        opp = not color
        try:
            attackers = len(board.attackers(opp, sq))
            defenders = len(board.attackers(color, sq))
        except Exception:
            attackers = defenders = 0
        if attackers > defenders:
            if color == chess.WHITE:
                white_loose += values.get(pc.piece_type,0)
            else:
                black_loose += values.get(pc.piece_type,0)
    # loose material is bad for its owner -> return (Black loose - White loose) as advantage for White
    return (black_loose - white_loose) / 100.0

def feature(board: chess.Board) -> float:
    'Fraction of the up-to-8 squares adjacent to the white king that are attacked by Black (0..1)'
    try:
        pm = board.piece_map()
    except Exception:
        return 0.0
    wk_sq = None
    for sq, p in pm.items():
        if p.piece_type == chess.KING and p.color == chess.WHITE:
            wk_sq = sq
            break
    if wk_sq is None:
        return 0.0
    wf = chess.square_file(wk_sq)
    wr = chess.square_rank(wk_sq)
    adj_total = 0
    adj_attacked = 0
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            if df == 0 and dr == 0:
                continue
            nf = wf + df
            nr = wr + dr
            if 0 <= nf <= 7 and 0 <= nr <= 7:
                adj_total += 1
                sq = nr * 8 + nf
                try:
                    if board.is_attacked_by(chess.BLACK, sq):
                        adj_attacked += 1
                except Exception:
                    pass
    if adj_total == 0:
        return 0.0
    return float(adj_attacked) / float(adj_total)

def feature(board: chess.Board) -> float:
    'Concentration of major pieces (rooks and queens) in the opponent half: (white_prop - black_prop), where prop is fraction on opponent half'
    try:
        pm = board.piece_map()
        def prop_major_in_enemy_half(color):
            majors = []
            for sq, p in pm.items():
                if p.color == color and p.piece_type in (chess.ROOK, chess.QUEEN):
                    majors.append(sq)
            if not majors:
                return 0.0
            count_in_enemy = 0
            for sq in majors:
                rk = chess.square_rank(sq)  # 0..7, rank 0 = rank1 for white
                if color == chess.WHITE:
                    # enemy half for white: ranks 4..7
                    if rk >= 4:
                        count_in_enemy += 1
                else:
                    # enemy half for black: ranks 0..3
                    if rk <= 3:
                        count_in_enemy += 1
            return float(count_in_enemy) / float(len(majors))
        return prop_major_in_enemy_half(chess.WHITE) - prop_major_in_enemy_half(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material concentration difference: coefficient of variation of non-pawn material values (White - Black)'
    import math
    values_map = {chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0}
    def cov(color):
        vals = [v for sq,p in board.piece_map().items() if p.color==color and p.piece_type in values_map for v in (values_map[p.piece_type],)]
        if not vals:
            return 0.0
        mean = sum(vals)/len(vals)
        if mean == 0.0:
            return 0.0
        var = sum((x-mean)**2 for x in vals)/len(vals)
        sd = math.sqrt(var)
        return sd/mean
    return float(cov(chess.WHITE) - cov(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Difference in average Manhattan distance from minor pieces (bishops+knights) to the enemy king (black_avg - white_avg); lower means that side\'s minors are closer to the enemy king'
    try:
        pieces = board.piece_map()
        w_minors = []
        b_minors = []
        w_king_sq = None
        b_king_sq = None
        for sq, pc in pieces.items():
            if pc.piece_type in (chess.BISHOP, chess.KNIGHT):
                if pc.color == chess.WHITE:
                    w_minors.append(sq)
                else:
                    b_minors.append(sq)
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    w_king_sq = sq
                else:
                    b_king_sq = sq
        if w_king_sq is None or b_king_sq is None:
            return 0.0
        def avg_dist(minors, target_sq):
            if not minors:
                return 8.0  # large default (max Manhattan within board is 14 but 8 is safe)
            s = 0
            for sq in minors:
                s += chess.square_distance(sq, target_sq)
            return s / len(minors)
        white_avg = avg_dist(w_minors, b_king_sq)
        black_avg = avg_dist(b_minors, w_king_sq)
        return float(black_avg - white_avg)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of pieces with no legal moves (excluding kings) for White minus Black: potential trapped pieces'
    try:
        pm = board.piece_map()
        # map how many legal moves originate from each square
        moves_from = {}
        for mv in board.legal_moves:
            moves_from[mv.from_square] = moves_from.get(mv.from_square, 0) + 1
        white_trapped = 0
        black_trapped = 0
        for sq, p in pm.items():
            if p is None:
                continue
            if p.piece_type == chess.KING:
                continue
            # If piece exists but has zero legal moves from its square, count as trapped
            if moves_from.get(sq, 0) == 0:
                # Also ensure the piece actually has at least one pseudo-legal move normally (simple heuristic: check attacked/blocked not required)
                if p.color == chess.WHITE:
                    white_trapped += 1
                else:
                    black_trapped += 1
        return float(white_trapped - black_trapped)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Piece centralization index: sum of piece-value * centrality (closer to center squares d4/d5/e4/e5 is better) (white - black)'
    pm = board.piece_map()
    vals = {chess.PAWN:0.8, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:2.5, chess.QUEEN:7.5, chess.KING:1.0}
    center_sqs = [chess.square(3,3), chess.square(4,3), chess.square(3,4), chess.square(4,4)]
    white_score = 0.0
    black_score = 0.0
    for sq,p in pm.items():
        if p is None: continue
        # Manhattan distance to nearest center square
        dmin = min(chess.square_distance(sq, c) for c in center_sqs)
        # map 0..7 -> centrality 1..0
        centrality = max(0.0, (8.0 - float(dmin)) / 8.0)
        weight = vals.get(p.piece_type, 0.0)
        if p.color == chess.WHITE:
            white_score += weight * centrality
        else:
            black_score += weight * centrality
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Net available one-move checks: (number of legal moves that give check for White) - (for Black) as a simple gauge of mating pressure'
    try:
        # iterate legal moves for both colors by toggling turn on copies
        checks_white = 0
        checks_black = 0
        # helper to count for a color
        def count_checks_for(color):
            cnt = 0
            try:
                b = board.copy()
                b.turn = color
                for mv in list(b.legal_moves):
                    b.push(mv)
                    if b.is_check():
                        cnt += 1
                    b.pop()
            except Exception:
                return 0
            return cnt
        checks_white = count_checks_for(chess.WHITE)
        checks_black = count_checks_for(chess.BLACK)
        return float(checks_white - checks_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King zone attack pressure difference: (White pressure around Black king) - (Black pressure around White king)'
    import chess
    try:
        # helper to get king square for a color
        wk = next((sq for sq, p in board.piece_map().items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        bk = next((sq for sq, p in board.piece_map().items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        def zone_attack_pressure(king_sq, attacker_color):
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            pressure = 0
            # king zone: squares with chebyshev distance <=2
            for file in range(max(0, kf-2), min(7, kf+2)+1):
                for rank in range(max(0, kr-2), min(7, kr+2)+1):
                    sq = chess.square(file, rank)
                    attackers = board.attackers(attacker_color, sq)
                    pressure += len(attackers)
            # normalize by zone size to keep scale bounded
            zone_size = ((min(7, kf+2) - max(0, kf-2) + 1) * (min(7, kr+2) - max(0, kr-2) + 1))
            return pressure / max(1.0, zone_size)
        w_pressure_on_bk = zone_attack_pressure(bk, chess.WHITE)
        b_pressure_on_wk = zone_attack_pressure(wk, chess.BLACK)
        return float(w_pressure_on_bk - b_pressure_on_wk)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn structure weakness score difference: (white penalty - black penalty) where penalty = 0.6*isolated + 0.4*(doubled count).'
    pm = board.piece_map()
    white_files = [0]*8
    black_files = [0]*8
    for sq, pc in pm.items():
        if pc.piece_type == chess.PAWN:
            f = chess.square_file(sq)
            if pc.color == chess.WHITE:
                white_files[f] += 1
            else:
                black_files[f] += 1
    def penalty(files):
        isolated = 0
        doubled = 0
        for f in range(8):
            if files[f] > 0:
                left = files[f-1] if f-1 >= 0 else 0
                right = files[f+1] if f+1 <= 7 else 0
                if left == 0 and right == 0 and files[f] == 1:
                    isolated += 1
                if files[f] > 1:
                    doubled += (files[f] - 1)
        return 0.6*isolated + 0.4*float(doubled)
    return float(penalty(white_files) - penalty(black_files))

def feature(board: chess.Board) -> float:
    'Minor piece centrality difference: sum of distance-based centrality for Knights and Bishops (White minus Black)'
    try:
        pieces = board.piece_map()
        centers = [chess.parse_square(s) for s in ('d4', 'e4', 'd5', 'e5')]
        def centrality(sq):
            d = min(chess.square_distance(sq, c) for c in centers)
            # map Manhattan distance to [0,1], closer -> higher
            val = max(0.0, (4.0 - d) / 4.0)
            return val
        white_sum = 0.0
        black_sum = 0.0
        for sq, p in pieces.items():
            if p.piece_type in (chess.KNIGHT, chess.BISHOP):
                if p.color == chess.WHITE:
                    white_sum += centrality(sq)
                else:
                    black_sum += centrality(sq)
        return float(white_sum - black_sum)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Endgame indicator: if only kings, bishops and pawns remain, return (pawn_count_white - pawn_count_black) + 0.5*(white_has_bishop - black_has_bishop), else 0'
    piece_map = board.piece_map()
    non_kbp = 0
    white_pawns = 0
    black_pawns = 0
    white_bishop = 0
    black_bishop = 0
    for sq, p in piece_map.items():
        if p.piece_type in (chess.KING, chess.BISHOP, chess.PAWN):
            if p.piece_type == chess.PAWN:
                if p.color == chess.WHITE:
                    white_pawns += 1
                else:
                    black_pawns += 1
            if p.piece_type == chess.BISHOP:
                if p.color == chess.WHITE:
                    white_bishop += 1
                else:
                    black_bishop += 1
        else:
            non_kbp += 1
    if non_kbp > 0:
        return 0.0
    return float((white_pawns - black_pawns) + 0.5 * (1 if white_bishop > 0 else 0) - 0.5 * (1 if black_bishop > 0 else 0))

def feature(board: chess.Board) -> float:
    'Pawn promotion pressure: sum over pawns of 1/(1+steps_to_promotion) weighted by being passed (white minus black). Encourages advanced, passed pawns.'
    try:
        import chess
        piece_map = board.piece_map()
        def is_passed(sq, color):
            file = chess.square_file(sq)
            rank = chess.square_rank(sq)
            if color == chess.WHITE:
                ahead_ranks = range(rank+1, 8)
                enemy = chess.BLACK
                for r in ahead_ranks:
                    for f in (file-1, file, file+1):
                        if 0 <= f <= 7:
                            s = chess.square(f, r)
                            pc = piece_map.get(s)
                            if pc is not None and pc.piece_type == chess.PAWN and pc.color == enemy:
                                return False
                return True
            else:
                ahead_ranks = range(0, rank)
                enemy = chess.WHITE
                for r in ahead_ranks:
                    for f in (file-1, file, file+1):
                        if 0 <= f <= 7:
                            s = chess.square(f, r)
                            pc = piece_map.get(s)
                            if pc is not None and pc.piece_type == chess.PAWN and pc.color == enemy:
                                return False
                return True
        white_score = 0.0
        black_score = 0.0
        for sq, pc in piece_map.items():
            if pc.piece_type != chess.PAWN:
                continue
            rank = chess.square_rank(sq)
            if pc.color == chess.WHITE:
                steps = 7 - rank
                weight = 1.0 / (1.0 + float(steps))
                if is_passed(sq, chess.WHITE):
                    weight *= 1.5
                white_score += weight
            else:
                steps = rank - 0
                weight = 1.0 / (1.0 + float(steps))
                if is_passed(sq, chess.BLACK):
                    weight *= 1.5
                black_score += weight
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Drawish indicator: higher when likely drawish (insufficient material, high 50-move clock, low total material)'
    # insufficient material
    if board.is_insufficient_material():
        return 1.0
    # halfmove clock contributes (0..1 approx)
    hm = float(board.halfmove_clock) / 100.0
    # total material (pawn units) small => drawish
    vals = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    total = 0.0
    for p in board.piece_map().values():
        total += vals.get(p.piece_type, 0.0)
    # invert total: more material -> less drawish
    material_component = 1.0 / (1.0 + total)
    return min(1.0, hm + material_component)

def feature(board: chess.Board) -> float:
    'Difference (black_dist - white_dist) of Manhattan distances of kings to the promotion square of the most advanced white pawn (positive if White king is closer).'
    try:
        kings = {p.color: sq for sq, p in board.piece_map().items() if p.piece_type == chess.KING}
        if chess.WHITE not in kings or chess.BLACK not in kings:
            return 0.0
        white_pawns = [sq for sq, p in board.piece_map().items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        if not white_pawns:
            return 0.0
        pawn_sq = max(white_pawns, key=lambda s: chess.square_rank(s))
        promo_sq = chess.square(chess.square_file(pawn_sq), 7)
        wd = chess.square_distance(kings[chess.WHITE], promo_sq)
        bd = chess.square_distance(kings[chess.BLACK], promo_sq)
        return float(bd - wd)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Fraction of squares on the pawn-to-promotion path that are empty for the most advanced white pawn (1.0 means completely clear).'
    try:
        white_pawns = [sq for sq, p in board.piece_map().items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        if not white_pawns:
            return 0.0
        pawn_sq = max(white_pawns, key=lambda s: chess.square_rank(s))
        pr = chess.square_rank(pawn_sq)
        file = chess.square_file(pawn_sq)
        steps = 7 - pr
        if steps <= 0:
            return 1.0
        empty = 0
        for r in range(pr + 1, 8):
            if board.piece_at(chess.square(file, r)) is None:
                empty += 1
        return float(empty) / float(steps)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in Manhattan distance from kings to their nearest pawn promotion square: (black_min_dist - white_min_dist)'
    pieces = board.piece_map()
    kings = {p.color: sq for sq, p in pieces.items() if p.piece_type == chess.KING}
    white_min = 100
    black_min = 100
    for sq, p in pieces.items():
        if p.piece_type != chess.PAWN:
            continue
        promo_sq = chess.square(chess.square_file(sq), 7 if p.color == chess.WHITE else 0)
        if chess.square_rank(sq) >= 0:  # any pawn
            if p.color == chess.WHITE and kings.get(chess.WHITE) is not None:
                d = chess.square_distance(kings[chess.WHITE], promo_sq)
                if d < white_min:
                    white_min = d
            if p.color == chess.BLACK and kings.get(chess.BLACK) is not None:
                d = chess.square_distance(kings[chess.BLACK], promo_sq)
                if d < black_min:
                    black_min = d
    if white_min == 100:
        white_min = 14
    if black_min == 100:
        black_min = 14
    return float(black_min - white_min)

def feature(board: chess.Board) -> float:
    'Pawn shield density around each king: sum of nearby pawn supports for white king minus black king (decayed by distance)'
    def shield_for_king(king_sq, color):
        if king_sq is None:
            return 0.0
        kf = chess.square_file(king_sq)
        kr = chess.square_rank(king_sq)
        total = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type != chess.PAWN or p.color != color:
                continue
            pf = chess.square_file(sq)
            pr = chess.square_rank(sq)
            df = abs(pf - kf)
            dr = pr - kr if color == chess.WHITE else kr - pr
            # We consider pawns ahead of the king (toward center/opponent) and within 1 file as shield
            if df <= 1 and dr >= 0 and dr <= 3:
                # weight nearer pawns more
                total += 1.0 / (1 + dr + df)
        return total
    white_king = black_king = None
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                white_king = sq
            else:
                black_king = sq
    return float(shield_for_king(white_king, chess.WHITE) - shield_for_king(black_king, chess.BLACK))

def feature(board: chess.Board) -> float:
    'Count of white pawns on the 7th rank (i.e., one step from promotion).'
    try:
        count = 0
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.PAWN and piece.color == chess.WHITE:
                if chess.square_rank(sq) == 6:
                    count += 1
        return float(count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Endgame king proximity bonus: (closer kings -> higher) weighted by endgame factor (1 when little material)'
    try:
        # compute material excluding kings
        values = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0}
        material = 0.0
        piece_map = board.piece_map()
        for p in piece_map.values():
            if p.piece_type in values:
                material += values[p.piece_type]
        # weight: 1 when material==0, 0 when material >= 2000
        weight = max(0.0, 1.0 - min(material / 2000.0, 1.0))
        # find kings
        wk = next((sq for sq, p in piece_map.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        bk = next((sq for sq, p in piece_map.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        if wk is None or bk is None:
            return 0.0
        dist = chess.square_distance(wk, bk)  # 0..7+ maybe
        # normalized closeness: (8 - dist) / 8
        closeness = max(0.0, (8.0 - float(dist)) / 8.0)
        return float(weight * closeness)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material imbalance restricted to kingside files (f,g,h): (white kingside material) - (black kingside material) in centipawns'
    try:
        ks_files = {5,6,7}
        vals = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:20000}
        w_score = 0
        b_score = 0
        for sq, p in board.piece_map().items():
            if p is None:
                continue
            f = chess.square_file(sq)
            if f in ks_files:
                v = vals.get(p.piece_type, 0)
                if p.color == chess.WHITE:
                    w_score += v
                else:
                    b_score += v
        return float(w_score - b_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    '9. Piece activity toward enemy king: sum(1/(1+manhattan_distance)) for pieces attacking/opposing king (white - black)'
    try:
        wk = board.king(chess.WHITE)
        bk = board.king(chess.BLACK)
        white_score = 0.0
        black_score = 0.0
        for sq, pc in board.piece_map().items():
            if pc.piece_type in (chess.ROOK, chess.BISHOP, chess.QUEEN, chess.KNIGHT):
                if pc.color == chess.WHITE and bk is not None:
                    d = chess.square_distance(sq, bk)
                    white_score += 1.0 / (1.0 + d)
                if pc.color == chess.BLACK and wk is not None:
                    d = chess.square_distance(sq, wk)
                    black_score += 1.0 / (1.0 + d)
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net trapped queen pressure: sum over queens of (attackers - defenders) weighted by queen count (White - Black)'
    try:
        pm = board.piece_map()
        # count mobility for queen by legal moves originating from its square
        queen_move_counts = {}
        for mv in board.legal_moves:
            from_sq = mv.from_square
            if from_sq in pm and pm[from_sq].piece_type == chess.QUEEN:
                queen_move_counts[from_sq] = queen_move_counts.get(from_sq, 0) + 1
        def queen_metric(color):
            s = 0.0
            for sq, pc in pm.items():
                if pc.piece_type == chess.QUEEN and pc.color == color:
                    attackers = len(board.attackers(not color, sq))
                    defenders = len(board.attackers(color, sq))
                    mobility = queen_move_counts.get(sq, 0)
                    # trapped if many attackers and few defenders and low mobility
                    s += (attackers - defenders) * (1.0 + max(0.0, 4.0 - mobility) * 0.25)
            return s
        return float(queen_metric(chess.WHITE) - queen_metric(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Queen influence in opponent half: (sum squares attacked by white queens in ranks 4..7) - (same for black queens in ranks 0..3). Reflects queen activity toward enemy territory.'
    try:
        def queen_half_influence(color):
            total = 0
            for sq, pc in board.piece_map().items():
                if pc.piece_type == chess.QUEEN and pc.color == color:
                    for t in chess.SQUARES:
                        # count if queen attacks that square and square is in opponent half
                        if board.is_attacked_by(color, t) and ((color == chess.WHITE and chess.square_rank(t) >= 4) or (color == chess.BLACK and chess.square_rank(t) <= 3)):
                            total += 1
            return total
        return float(queen_half_influence(chess.WHITE) - queen_half_influence(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Bishop-pair advantage penalized by same-color-pawn blocking: positive = White advantage'
    try:
        pm = board.piece_map()
        def square_color_parity(sq):
            return (chess.square_file(sq) + chess.square_rank(sq)) & 1
        # counts
        w_bishops = [s for s, p in pm.items() if p.piece_type == chess.BISHOP and p.color == chess.WHITE]
        b_bishops = [s for s, p in pm.items() if p.piece_type == chess.BISHOP and p.color == chess.BLACK]
        w_has_pair = 1.0 if len(w_bishops) >= 2 else 0.0
        b_has_pair = 1.0 if len(b_bishops) >= 2 else 0.0
        # blocking measure: count of pawns on same-color squares as each bishop
        w_block = 0
        b_block = 0
        for s, p in pm.items():
            if p.piece_type == chess.PAWN:
                parity = square_color_parity(s)
                # each bishop on that parity considered blocked +1
                for bs in w_bishops:
                    if square_color_parity(bs) == parity:
                        w_block += 1
                for bs in b_bishops:
                    if square_color_parity(bs) == parity:
                        b_block += 1
        # normalize blocking by a small factor to keep ranges reasonable
        block_norm = 8.0 if (w_bishops or b_bishops) else 1.0
        return (w_has_pair - b_has_pair) - ( (w_block - b_block) / block_norm )
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in pawn-chain defense ratio: proportion of pawns defended by another pawn (White ratio minus Black ratio)'
    pm = board.piece_map()
    def pawn_defended_ratio(color):
        pawn_sqs = [sq for sq, p in pm.items() if p.piece_type == chess.PAWN and p.color == color]
        if not pawn_sqs:
            return 0.0
        defended = 0
        for sq in pawn_sqs:
            f, r = chess.square_file(sq), chess.square_rank(sq)
            # white pawns are defended from behind (rank-1), black from behind (rank+1)
            if color == chess.WHITE:
                candidates = []
                if f - 1 >= 0 and r - 1 >= 0:
                    candidates.append((f - 1) + 8 * (r - 1))
                if f + 1 <= 7 and r - 1 >= 0:
                    candidates.append((f + 1) + 8 * (r - 1))
            else:
                candidates = []
                if f - 1 >= 0 and r + 1 <= 7:
                    candidates.append((f - 1) + 8 * (r + 1))
                if f + 1 <= 7 and r + 1 <= 7:
                    candidates.append((f + 1) + 8 * (r + 1))
            for c in candidates:
                pc = pm.get(c)
                if pc is not None and pc.piece_type == chess.PAWN and pc.color == color:
                    defended += 1
                    break
        return defended / len(pawn_sqs)
    return float(pawn_defended_ratio(chess.WHITE) - pawn_defended_ratio(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Passed pawn score weighted by advancement (white minus black); advanced passed pawns count more'
    try:
        pm = board.piece_map()
        def pawn_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                for rr in range(r+1, 8):
                    for ff in (f-1, f, f+1):
                        if 0 <= ff <= 7:
                            q = board.piece_at(chess.square(ff, rr))
                            if q is not None and q.piece_type == chess.PAWN and q.color == chess.BLACK:
                                return False
                return True
            else:
                for rr in range(r-1, -1, -1):
                    for ff in (f-1, f, f+1):
                        if 0 <= ff <= 7:
                            q = board.piece_at(chess.square(ff, rr))
                            if q is not None and q.piece_type == chess.PAWN and q.color == chess.WHITE:
                                return False
                return True
        white_score = 0.0
        black_score = 0.0
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                r = chess.square_rank(sq)
                if pawn_passed(sq, p.color):
                    # advancement factor: for white use rank/7, for black use (7-r)/7
                    if p.color == chess.WHITE:
                        adv = r / 7.0
                        white_score += adv
                    else:
                        adv = (7 - r) / 7.0
                        black_score += adv
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Mobility of major pieces difference (White - Black): count of legal moves by queens and rooks for each side.'
    white_moves = 0
    black_moves = 0
    # board.legal_moves is an iterator of Move objects
    for mv in board.legal_moves:
        psq = mv.from_square
        p = board.piece_at(psq)
        if p is None:
            continue
        if p.piece_type in (chess.ROOK, chess.QUEEN):
            if p.color == chess.WHITE:
                white_moves += 1
            else:
                black_moves += 1
    return float(white_moves - black_moves)

def feature(board: chess.Board) -> float:
    'Difference in active-material ratio: (sum value of pieces on opponent half-board for white / white_total) - (same for black). Values in centipawns scaled between -1 and 1.'
    try:
        piece_values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        pm = board.piece_map()
        white_total = 0
        black_total = 0
        white_active = 0
        black_active = 0
        for sq,p in pm.items():
            val = piece_values.get(p.piece_type, 0)
            rank = chess.square_rank(sq)
            if p.color == chess.WHITE:
                white_total += val
                # active if on ranks 4-7 (opponent half) or on central files (c,d,e,f)
                if rank >= 4 or chess.square_file(sq) in (2,3,4,5):
                    white_active += val
            else:
                black_total += val
                if rank <= 3 or chess.square_file(sq) in (2,3,4,5):
                    black_active += val
        # avoid division by zero
        w_ratio = (white_active/white_total) if white_total>0 else 0.0
        b_ratio = (black_active/black_total) if black_total>0 else 0.0
        return float(w_ratio - b_ratio)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Kingside pawn majority: (White pawns on files f-g-h) - (Black pawns on files f-g-h), positive favors White.'
    try:
        w = 0
        b = 0
        for r in range(8):
            for f in (5,6,7):  # files f,g,h
                sq = chess.square(f, r)
                p = board.piece_at(sq)
                if p is None:
                    continue
                if p.piece_type == chess.PAWN:
                    if p.color == chess.WHITE:
                        w += 1
                    else:
                        b += 1
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Minor-piece outpost count difference: (white - black) normalized by 4. Outpost = minor piece on advanced/central rank not attacked by enemy pawns'
    try:
        pieces = board.piece_map()
        white_outposts = 0
        black_outposts = 0
        for sq, p in pieces.items():
            if p.piece_type not in (chess.KNIGHT, chess.BISHOP):
                continue
            r = chess.square_rank(sq)
            # central/advanced band where outposts matter
            if 3 <= r <= 5:
                opp = not p.color
                attackers = board.attackers(opp, sq)
                attacked_by_pawn = False
                for a in attackers:
                    apr = pieces.get(a)
                    if apr and apr.piece_type == chess.PAWN:
                        attacked_by_pawn = True
                        break
                if not attacked_by_pawn:
                    if p.color == chess.WHITE:
                        white_outposts += 1
                    else:
                        black_outposts += 1
        return float((white_outposts - black_outposts) / 4.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Normalized mobility gap: (white_mobility - black_mobility) / max(1, total_nonking_pieces), where mobility counts legal moves for each side'
    try:
        pieces = board.piece_map()
    except Exception:
        pieces = {}
    total_pieces = max(1, sum(1 for p in pieces.values() if p.piece_type != chess.KING))
    # compute mobility for side to move and opponent by copying board
    try:
        bcopy = board.copy()
    except Exception:
        # fallback: estimate mobility by attacked squares count
        def attacked_count(color):
            s = 0
            for sq in range(64):
                try:
                    if board.is_attacked_by(color, sq):
                        s += 1
                except Exception:
                    pass
            return s
        w_mob = attacked_count(chess.WHITE)
        b_mob = attacked_count(chess.BLACK)
        return float((w_mob - b_mob) / total_pieces)
    # count legal moves for white
    bcopy.turn = chess.WHITE
    w_mob = sum(1 for _ in bcopy.legal_moves)
    bcopy.turn = chess.BLACK
    b_mob = sum(1 for _ in bcopy.legal_moves)
    return float((w_mob - b_mob) / total_pieces)

def feature(board: chess.Board) -> float:
    'Trapped-king score difference: (black trapped score) - (white trapped score); positive favors White if Black is trapped. Edge, few king moves and many adjacent attackers increase the score.'
    try:
        pm = board.piece_map()
        def trap_score_for(king_color):
            king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == king_color), None)
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            on_edge = 1 if (kf == 0 or kf == 7 or kr == 0 or kr == 7) else 0
            # king legal moves
            k_moves = 0
            for mv in board.legal_moves:
                try:
                    if mv.from_square == king_sq:
                        k_moves += 1
                except Exception:
                    continue
            # adjacent attackers by opponent
            opponent = chess.WHITE if king_color == chess.BLACK else chess.BLACK
            adj_att = 0
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    nf = kf + df
                    nr = kr + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        sq = chess.parse_square('abcdefgh'[nf] + str(nr + 1))
                        adj_att += len(board.attackers(opponent, sq))
            score = on_edge * max(0, 4 - k_moves) * adj_att
            return float(score)
        black_trap = trap_score_for(chess.BLACK)
        white_trap = trap_score_for(chess.WHITE)
        return float(black_trap - white_trap)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Normalized mobility gap: (white_mobility - black_mobility) / max(1, total_nonking_pieces), where mobility counts legal moves for each side'
    try:
        pieces = board.piece_map()
    except Exception:
        pieces = {}
    total_pieces = max(1, sum(1 for p in pieces.values() if p.piece_type != chess.KING))
    # compute mobility for side to move and opponent by copying board
    try:
        bcopy = board.copy()
    except Exception:
        # fallback: estimate mobility by attacked squares count
        def attacked_count(color):
            s = 0
            for sq in range(64):
                try:
                    if board.is_attacked_by(color, sq):
                        s += 1
                except Exception:
                    pass
            return s
        w_mob = attacked_count(chess.WHITE)
        b_mob = attacked_count(chess.BLACK)
        return float((w_mob - b_mob) / total_pieces)
    # count legal moves for white
    bcopy.turn = chess.WHITE
    w_mob = sum(1 for _ in bcopy.legal_moves)
    bcopy.turn = chess.BLACK
    b_mob = sum(1 for _ in bcopy.legal_moves)
    return float((w_mob - b_mob) / total_pieces)

def feature(board: chess.Board) -> float:
    'Threatened major-piece value imbalance: weighted sum of attacked rooks/queens where attackers outnumber defenders (White - Black), scaled in pawn units'
    try:
        values = {chess.ROOK: 500.0, chess.QUEEN: 900.0}
        def threatened_value_for(color):
            opp = not color
            total = 0.0
            for sq, p in board.piece_map().items():
                if p.color != color or p.piece_type not in values:
                    continue
                attackers = len(board.attackers(opp, sq))
                defenders = len(board.attackers(color, sq))
                if attackers <= 0:
                    continue
                # weight by how unfavorable the net attack is
                net = max(0.0, attackers - defenders + 0.5)
                total += (values[p.piece_type] * net) / 100.0  # convert to pawn units
            return total
        return float(threatened_value_for(chess.WHITE) - threatened_value_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in average Manhattan distance of non-king pieces to their own king (white average minus black average)'
    try:
        pm = board.piece_map()
        def avg_dist(color):
            king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == color), None)
            if king_sq is None:
                return 0.0
            dists = []
            for sq, pc in pm.items():
                if pc.color == color and pc.piece_type != chess.KING:
                    dists.append(chess.square_distance(sq, king_sq))
            if not dists:
                return 0.0
            return float(sum(dists) / len(dists))
        return avg_dist(chess.WHITE) - avg_dist(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Piece coordination index: (black_avg_pairdist - white_avg_pairdist) positive when white pieces are more tightly coordinated'
    pm = board.piece_map()
    def avg_pair_distance(color):
        locs = [sq for sq,p in pm.items() if p.color==color and p.piece_type!=chess.KING]
        n = len(locs)
        if n <= 1:
            return 8.0
        total = 0
        pairs = 0
        for i in range(n):
            for j in range(i+1,n):
                total += chess.square_distance(locs[i], locs[j])
                pairs += 1
        return total / pairs if pairs>0 else 8.0
    return (avg_pair_distance(chess.BLACK) - avg_pair_distance(chess.WHITE))

def feature(board: chess.Board) -> float:
    'Difference in average Manhattan distance of major pieces (rooks/queens) to the enemy king (black_avg - white_avg). Positive means white major pieces are on average closer to black king.'
    try:
        pm = board.piece_map()
        w_major = []
        b_major = []
        white_king_sq = None
        black_king_sq = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king_sq = sq
                else:
                    black_king_sq = sq
            if p.piece_type in (chess.ROOK, chess.QUEEN):
                if p.color == chess.WHITE:
                    w_major.append(sq)
                else:
                    b_major.append(sq)
        if black_king_sq is None or white_king_sq is None:
            return 0.0
        def avg_dist(list_sq, target):
            if not list_sq:
                return 10.0
            s = 0
            for sq in list_sq:
                s += chess.square_distance(sq, target)
            return s / len(list_sq)
        white_avg = avg_dist(w_major, black_king_sq)
        black_avg = avg_dist(b_major, white_king_sq)
        return float(black_avg - white_avg)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Potential capture opportunities difference: weighted count of opponent pieces attackable by each side (White - Black) in pawn units'
    try:
        pm = board.piece_map()
        values = {chess.PAWN:1.0, chess.KNIGHT:3.2, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        def potential_capture_value(attacker_color):
            total = 0.0
            for sq, p in pm.items():
                if p.color != attacker_color:
                    if len(board.attackers(attacker_color, sq)) > 0:
                        total += values.get(p.piece_type, 0.0)
            return total
        return float(potential_capture_value(chess.WHITE) - potential_capture_value(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of connected passed pawns (white minus black); a passed pawn is "connected" if a friendly pawn exists on an adjacent file within one rank distance'
    try:
        def is_passed_local(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                for ff in range(max(0, f - 1), min(7, f + 1) + 1):
                    for rr in range(r + 1, 8):
                        occ = board.piece_at(chess.square(ff, rr))
                        if occ is not None and occ.piece_type == chess.PAWN and occ.color == chess.BLACK:
                            return False
                return True
            else:
                for ff in range(max(0, f - 1), min(7, f + 1) + 1):
                    for rr in range(0, r):
                        occ = board.piece_at(chess.square(ff, rr))
                        if occ is not None and occ.piece_type == chess.PAWN and occ.color == chess.WHITE:
                            return False
                return True
        def connected_passed(color):
            cnt = 0
            for sq, pc in board.piece_map().items():
                if pc.piece_type == chess.PAWN and pc.color == color and is_passed_local(sq, color):
                    f = chess.square_file(sq)
                    r = chess.square_rank(sq)
                    connected = False
                    for ff in range(max(0, f - 1), min(7, f + 1) + 1):
                        for rr in range(max(0, r - 1), min(7, r + 1) + 1):
                            if ff == f and rr == r:
                                continue
                            occ = board.piece_at(chess.square(ff, rr))
                            if occ is not None and occ.piece_type == chess.PAWN and occ.color == color:
                                connected = True
                                break
                        if connected:
                            break
                    if connected:
                        cnt += 1
            return cnt
        return float(connected_passed(chess.WHITE) - connected_passed(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net attack pressure on squares adjacent to each king (white minus black)'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.BLACK), None)
        def adjacent_squares(sq):
            if sq is None:
                return []
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            res = []
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    nf = f + df
                    nr = r + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        res.append(chess.square(nf, nr))
            return res
        white_pressure = 0
        black_pressure = 0
        for adj in adjacent_squares(white_king_sq):
            white_pressure += len(board.attackers(chess.BLACK, adj))
        for adj in adjacent_squares(black_king_sq):
            black_pressure += len(board.attackers(chess.WHITE, adj))
        return float(white_pressure - black_pressure)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Fraction of king-adjacent squares that are safe (not attacked by opponent and not occupied by a friendly piece); 0..1'
    king_sq = None
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.KING and p.color == board.turn:
            king_sq = sq
            break
    if king_sq is None:
        return 0.0
    kf = chess.square_file(king_sq)
    kr = chess.square_rank(king_sq)
    safe = 0
    total = 0
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            if df == 0 and dr == 0:
                continue
            nf = kf + df
            nr = kr + dr
            if not (0 <= nf <= 7 and 0 <= nr <= 7):
                continue
            total += 1
            nsq = chess.parse_square(chr(ord('a') + nf) + str(nr+1))
            occ = board.piece_at(nsq)
            # occupied by friendly piece => not safe as escape
            if occ is not None and occ.color == board.turn:
                continue
            # attacked by opponent => not safe
            if board.is_attacked_by(not board.turn, nsq):
                continue
            safe += 1
    if total == 0:
        return 0.0
    return float(safe) / float(total)

def feature(board: chess.Board) -> float:
    'Balance of rooks on open and semi-open files: weighted (white - black)'
    try:
        pm = board.piece_map()
        # Determine pawn presence per file for each color
        white_pawn_files = [False] * 8
        black_pawn_files = [False] * 8
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if p.color == chess.WHITE:
                    white_pawn_files[f] = True
                else:
                    black_pawn_files[f] = True
        white_open = white_semi = black_open = black_semi = 0
        # For each rook, check its file
        for sq, p in pm.items():
            if p.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                # open file: no pawns at all; semi-open for a color: no friendly pawns
                no_pawns = not (white_pawn_files[f] or black_pawn_files[f])
                if p.color == chess.WHITE:
                    if no_pawns:
                        white_open += 1
                    elif not white_pawn_files[f]:
                        white_semi += 1
                else:
                    if no_pawns:
                        black_open += 1
                    elif not black_pawn_files[f]:
                        black_semi += 1
        # weight open more than semi-open
        return (1.5 * white_open + 0.8 * white_semi) - (1.5 * black_open + 0.8 * black_semi)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King pawn shield integrity: difference (white - black) of friendly pawns in three files around king in two ranks in front/back'
    try:
        pm = board.piece_map()
        def king_shield(color):
            # locate king
            king_sq = None
            for sq,pc in pm.items():
                if pc.piece_type==chess.KING and pc.color==color:
                    king_sq = sq; break
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
            count = 0
            if color == chess.WHITE:
                ranks = range(max(0, kr-2), kr+1)  # pawns behind or same rank count a bit
            else:
                ranks = range(kr, min(7, kr+2)+1)
            for df in (-1,0,1):
                for rr in ranks:
                    ff = kf + df
                    if 0 <= ff < 8 and 0 <= rr < 8:
                        tsq = chess.square(ff, rr)
                        pc = pm.get(tsq)
                        if pc and pc.piece_type==chess.PAWN and pc.color==color:
                            count += 1
            return count
        return float(king_shield(chess.WHITE) - king_shield(chess.BLACK)) / 6.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn promotion proximity score (white minus black), with penalty if an enemy rook sits in front on the file'
    try:
        pm = board.piece_map()
        white_score = 0.0
        black_score = 0.0
        # collect black pawn squares and white pawn squares for passed detection
        black_pawns = [s for s, p in pm.items() if p.piece_type == chess.PAWN and p.color == chess.BLACK]
        white_pawns = [s for s, p in pm.items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        black_pawn_set = set(black_pawns)
        white_pawn_set = set(white_pawns)
        # helper to detect passed pawn and compute score
        for s in white_pawns:
            f = chess.square_file(s); r = chess.square_rank(s)
            blocked = False
            is_passed = True
            for bs in black_pawns:
                bf = chess.square_file(bs); br = chess.square_rank(bs)
                if abs(bf - f) <= 1 and br > r:
                    is_passed = False
                    break
            if is_passed:
                dist = 7 - r
                # closer to promotion is better: use inverse distance
                white_score += 1.0 / (dist + 0.3)
                # penalty if any enemy rook sits ahead on same file between pawn and promotion
                for sq,pc in pm.items():
                    if pc.piece_type == chess.ROOK and pc.color == chess.BLACK and chess.square_file(sq) == f and chess.square_rank(sq) > r:
                        white_score -= 0.5
                        break
        for s in black_pawns:
            f = chess.square_file(s); r = chess.square_rank(s)
            is_passed = True
            for ws in white_pawns:
                wf = chess.square_file(ws); wr = chess.square_rank(ws)
                if abs(wf - f) <= 1 and wr < r:
                    is_passed = False
                    break
            if is_passed:
                dist = r - 0
                black_score += 1.0 / (dist + 0.3)
                for sq,pc in pm.items():
                    if pc.piece_type == chess.ROOK and pc.color == chess.WHITE and chess.square_file(sq) == f and chess.square_rank(sq) < r:
                        black_score -= 0.5
                        break
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net piece coordination score: inverse average Manhattan distance between non-pawn pieces (white - black), normalized to [ -1, 1 ]'
    try:
        pm = board.piece_map()
        def coord(color):
            squares = [sq for sq, p in pm.items() if p.color == color and p.piece_type != chess.PAWN and p.piece_type != chess.KING]
            n = len(squares)
            if n < 2:
                return 0.0
            total = 0.0
            pairs = 0
            for i in range(n):
                for j in range(i+1, n):
                    total += chess.square_distance(squares[i], squares[j])
                    pairs += 1
            avg = total / pairs if pairs > 0 else 8.0
            # smaller avg -> better coordination; invert and normalize by max distance (8)
            return (8.0 - avg) / 8.0
        return float(coord(chess.WHITE) - coord(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Queen centralization: sum over queens of (7 - Manhattan distance to board center) normalized, (White - Black). Higher = more centralized queens for White'
    piece_map = board.piece_map()
    def center_score(sq):
        if sq is None:
            return 0.0
        f = chess.square_file(sq) + 0.5
        r = chess.square_rank(sq) + 0.5
        # center at (3.5,3.5)
        dist = abs(f - 3.5) + abs(r - 3.5)
        return max(0.0, 7.0 - dist)  # larger = more central
    w = 0.0
    b = 0.0
    for sq, p in piece_map.items():
        if p.piece_type == chess.QUEEN:
            if p.color == chess.WHITE:
                w += center_score(sq)
            else:
                b += center_score(sq)
    # normalize roughly
    return float((w - b) / 7.0)

def feature(board: chess.Board) -> float:
    'Advanced passed pawn score (white minus black). Counts passed pawns and weights by advancement (squared normalized rank).'
    try:
        pm = board.piece_map()
        white_passed = 0.0
        black_passed = 0.0
        # Precompute pawn squares by color for quick checks
        pawns_white = [sq for sq, p in pm.items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        pawns_black = [sq for sq, p in pm.items() if p.piece_type == chess.PAWN and p.color == chess.BLACK]
        pawn_set_white = set(pawns_white)
        pawn_set_black = set(pawns_black)
        for sq in pawns_white:
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            blocked = False
            for bf in range(max(0, f - 1), min(7, f + 1) + 1):
                # any black pawn ahead on same/adj file with higher rank?
                for br in range(r + 1, 8):
                    if chess.square(bf, br) in pawn_set_black:
                        blocked = True
                        break
                if blocked:
                    break
            if not blocked:
                adv = r / 7.0
                white_passed += adv * adv
        for sq in pawns_black:
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            blocked = False
            for bf in range(max(0, f - 1), min(7, f + 1) + 1):
                for br in range(0, r):
                    if chess.square(bf, br) in pawn_set_white:
                        blocked = True
                        break
                if blocked:
                    break
            if not blocked:
                adv = (7 - r) / 7.0
                black_passed += adv * adv
        return float(white_passed - black_passed)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pressure from opponent rooks/queens on open or semi-open files adjacent to each king (white_pressure - black_pressure)'
    pm = board.piece_map()
    def pressure_on_king(king_sq, own_color):
        if king_sq is None:
            return 0.0
        kf = chess.square_file(king_sq)
        pressure = 0.0
        # consider files kf-1, kf, kf+1
        for f in (kf - 1, kf, kf + 1):
            if f < 0 or f > 7:
                continue
            # check if own pawns exist on this file (then not open/semi-open)
            own_pawn_on_file = any(p.piece_type == chess.PAWN and p.color == own_color and chess.square_file(sq) == f for sq, p in pm.items())
            if own_pawn_on_file:
                continue
            # opponent major pieces on this file
            for sq, p in pm.items():
                if chess.square_file(sq) != f:
                    continue
                if p.color == own_color:
                    continue
                if p.piece_type == chess.ROOK:
                    pressure += 1.0
                elif p.piece_type == chess.QUEEN:
                    pressure += 0.9
        return pressure
    # find kings
    wking = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
    bking = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
    wpress = pressure_on_king(wking, chess.WHITE)
    bpress = pressure_on_king(bking, chess.BLACK)
    return float(wpress - bpress)

def feature(board: chess.Board) -> float:
    'Queen influence in opponent half: (sum squares attacked by white queens in ranks 4..7) - (same for black queens in ranks 0..3). Reflects queen activity toward enemy territory.'
    try:
        def queen_half_influence(color):
            total = 0
            for sq, pc in board.piece_map().items():
                if pc.piece_type == chess.QUEEN and pc.color == color:
                    for t in chess.SQUARES:
                        # count if queen attacks that square and square is in opponent half
                        if board.is_attacked_by(color, t) and ((color == chess.WHITE and chess.square_rank(t) >= 4) or (color == chess.BLACK and chess.square_rank(t) <= 3)):
                            total += 1
            return total
        return float(queen_half_influence(chess.WHITE) - queen_half_influence(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn promotion threat difference: sum over passed pawns of (1.0 / distance_to_promotion), (White - Black)'
    try:
        def is_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            for other_sq, other_p in board.piece_map().items():
                if other_p.piece_type != chess.PAWN or other_p.color == color:
                    continue
                of = chess.square_file(other_sq)
                orr = chess.square_rank(other_sq)
                if abs(of - f) <= 1:
                    # for white pawn, opponent pawn ahead (or at) blocks passing
                    if color == chess.WHITE and orr > r:
                        return False
                    if color == chess.BLACK and orr < r:
                        return False
            return True
        score = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type != chess.PAWN:
                continue
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                dist = 7 - r
            else:
                dist = r
            if dist <= 0:
                continue
            if is_passed(sq, p.color):
                score += (1.0 / dist) if p.color == chess.WHITE else -(1.0 / dist)
        return float(score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of "unstoppable" passed pawns weighted by advancement (white minus black). A pawn is counted as unstoppable if the opposing king is farther (Manhattan) from its promotion square than the pawn needs to promote.'
    try:
        import chess
        result_white = 0.0
        result_black = 0.0
        piece_map = board.piece_map()
        # find kings for distance calculations
        white_king_sq = None
        black_king_sq = None
        for sq, pc in piece_map.items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    white_king_sq = sq
                else:
                    black_king_sq = sq
        for sq, pc in piece_map.items():
            if pc.piece_type != chess.PAWN:
                continue
            rank = chess.square_rank(sq)
            file = chess.square_file(sq)
            if pc.color == chess.WHITE:
                steps = 7 - rank
                promo_sq = chess.square(file, 7)
                king_dist = chess.square_distance(promo_sq, black_king_sq) if black_king_sq is not None else 100
                if king_dist > steps:
                    # weight by advancement: more advanced pawns count more
                    weight = 1.0 + (rank / 7.0)
                    result_white += weight
            else:
                steps = rank - 0
                promo_sq = chess.square(file, 0)
                king_dist = chess.square_distance(promo_sq, white_king_sq) if white_king_sq is not None else 100
                if king_dist > steps:
                    weight = 1.0 + ((7 - rank) / 7.0)
                    result_black += weight
        return float(result_white - result_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Imbalance between majors (rooks+queens) and minor pieces (knights+bishops) in pawn units, White minus Black'
    vals = {chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500, chess.QUEEN: 900}
    sum_side = {chess.WHITE: 0, chess.BLACK: 0}
    minor_side = {chess.WHITE: 0, chess.BLACK: 0}
    for sq, p in board.piece_map().items():
        if p.piece_type in (chess.ROOK, chess.QUEEN):
            sum_side[p.color] += vals.get(p.piece_type, 0)
        if p.piece_type in (chess.KNIGHT, chess.BISHOP):
            minor_side[p.color] += vals.get(p.piece_type, 0)
    imbalance_white = sum_side[chess.WHITE] - minor_side[chess.WHITE]
    imbalance_black = sum_side[chess.BLACK] - minor_side[chess.BLACK]
    return float((imbalance_white - imbalance_black) / 100.0)

def feature(board: chess.Board) -> float:
    'Material imbalance restricted to kingside files (f,g,h): (white kingside material) - (black kingside material) in centipawns'
    try:
        ks_files = {5,6,7}
        vals = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:20000}
        w_score = 0
        b_score = 0
        for sq, p in board.piece_map().items():
            if p is None:
                continue
            f = chess.square_file(sq)
            if f in ks_files:
                v = vals.get(p.piece_type, 0)
                if p.color == chess.WHITE:
                    w_score += v
                else:
                    b_score += v
        return float(w_score - b_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Relative proximity of queens to the enemy king: (1/(1+d)) for white queen to black king minus same for black queen to white king'
    try:
        pm = board.piece_map()
        white_queens = [sq for sq, pc in pm.items() if pc.piece_type == chess.QUEEN and pc.color == chess.WHITE]
        black_queens = [sq for sq, pc in pm.items() if pc.piece_type == chess.QUEEN and pc.color == chess.BLACK]
        white_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.BLACK), None)
        def inv_dist_min(queen_sqs, target_sq):
            if not queen_sqs or target_sq is None:
                return 0.0
            md = min(chess.square_distance(qs, target_sq) for qs in queen_sqs)
            return 1.0 / (1.0 + float(md))
        return inv_dist_min(white_queens, black_king_sq) - inv_dist_min(black_queens, white_king_sq)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net attack pressure on squares adjacent to each king (white minus black)'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.BLACK), None)
        def adjacent_squares(sq):
            if sq is None:
                return []
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            res = []
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    nf = f + df
                    nr = r + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        res.append(chess.square(nf, nr))
            return res
        white_pressure = 0
        black_pressure = 0
        for adj in adjacent_squares(white_king_sq):
            white_pressure += len(board.attackers(chess.BLACK, adj))
        for adj in adjacent_squares(black_king_sq):
            black_pressure += len(board.attackers(chess.WHITE, adj))
        return float(white_pressure - black_pressure)
    except Exception:
        return 0.0

