def feature(board: chess.Board) -> float:
    'Difference in number of safe escape squares for each king (white_safe - black_safe), counting adjacent squares not occupied by same color and not attacked by opponent'
    try:
        pm = board.piece_map()
        def safe_squares(king_color):
            king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == king_color), None)
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            safe = 0
            opponent = not king_color
            for df in (-1,0,1):
                for dr in (-1,0,1):
                    if df == 0 and dr == 0:
                        continue
                    nf = kf + df
                    nr = kr + dr
                    if not (0 <= nf <= 7 and 0 <= nr <= 7):
                        continue
                    nsq = chess.square(nf, nr)
                    occupant = board.piece_at(nsq)
                    if occupant is not None and occupant.color == king_color:
                        continue
                    # square must not be attacked by opponent to be considered safe
                    try:
                        attacked = board.is_attacked_by(opponent, nsq)
                    except Exception:
                        attacked = False
                    if not attacked:
                        safe += 1
            return float(safe)
        return safe_squares(chess.WHITE) - safe_squares(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material value of "loose" (more attackers than defenders) pieces: sum(piece value * (attackers>defenders)) (White - Black)'
    values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:20000}
    pm = board.piece_map()
    white_loose = 0
    black_loose = 0
    for sq, pc in pm.items():
        color = pc.color
        opp = not color
        try:
            attackers = len(board.attackers(opp, sq))
            defenders = len(board.attackers(color, sq))
        except Exception:
            attackers = defenders = 0
        if attackers > defenders:
            if color == chess.WHITE:
                white_loose += values.get(pc.piece_type,0)
            else:
                black_loose += values.get(pc.piece_type,0)
    # loose material is bad for its owner -> return (Black loose - White loose) as advantage for White
    return (black_loose - white_loose) / 100.0

def feature(board: chess.Board) -> float:
    'Net defensive presence around kings: (White defenders around White king) - (Black defenders around Black king), normalized to [-1,1]'
    try:
        piece_map = board.piece_map()
        def find_king(color):
            for sq, p in piece_map.items():
                if p.piece_type == chess.KING and p.color == color:
                    return sq
            return None
        def defenders_around(king_sq, color):
            if king_sq is None:
                return 0.0
            total = 0
            kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    f = kf + df; r = kr + dr
                    if 0 <= f <= 7 and 0 <= r <= 7:
                        sq = chess.square(f, r)
                        # count friendly pieces that occupy or attack this square
                        occ = board.piece_at(sq)
                        if occ is not None and occ.color == color:
                            total += 1.0
                        # friendly attackers to that square
                        total += len(board.attackers(color, sq)) * 0.3
            # normalize by an approximate max (8 occupancy + attackers) -> scale to [-1,1] after comparing sides
            return total / (8.0 + 8.0 * 0.3)
        w = defenders_around(find_king(chess.WHITE), chess.WHITE)
        b = defenders_around(find_king(chess.BLACK), chess.BLACK)
        return w - b
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Total material value (pawns=1,knight=3.2,bishop=3.3,rook=5,queen=9) of hanging pieces located in central 4 squares (d4,e4,d5,e5), White - Black'
    try:
        central_files = {3,4}
        central_ranks = {3,4}
        val = {chess.PAWN:1.0, chess.KNIGHT:3.2, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        white_sum = 0.0
        black_sum = 0.0
        pm = board.piece_map()
        for sq, p in pm.items():
            if chess.square_file(sq) in central_files and chess.square_rank(sq) in central_ranks:
                opp = not p.color
                attackers = board.attackers(opp, sq)
                defenders = board.attackers(p.color, sq)
                if len(attackers) > len(defenders) and len(attackers) > 0:
                    v = val.get(p.piece_type, 0.0)
                    if p.color == chess.WHITE:
                        white_sum += v
                    else:
                        black_sum += v
        return float(white_sum - black_sum)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'White minus Black: closeness (inverted Chebyshev distance) of the nearest same-color rook to the most advanced passed pawn\'s promotion square (higher is better)'
    def cheb(a, b):
        return max(abs(a[0] - b[0]), abs(a[1] - b[1]))
    try:
        pieces = board.piece_map()
    except Exception:
        return 0.0
    pawns = [(sq, p) for sq, p in pieces.items() if p.piece_type == chess.PAWN]
    rooks = [(sq, p) for sq, p in pieces.items() if p.piece_type == chess.ROOK]
    best_w = 100
    best_b = 100
    # find most advanced passed pawn per color
    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            for opp_sq, opp_piece in pawns:
                if opp_piece.color == chess.BLACK:
                    if abs(chess.square_file(opp_sq) - f) <= 1 and chess.square_rank(opp_sq) >= r:
                        return False
            return True
        else:
            for opp_sq, opp_piece in pawns:
                if opp_piece.color == chess.WHITE:
                    if abs(chess.square_file(opp_sq) - f) <= 1 and chess.square_rank(opp_sq) <= r:
                        return False
            return True
    white_passed = None
    black_passed = None
    for sq, p in pawns:
        if not is_passed(sq, p.color):
            continue
        r = chess.square_rank(sq)
        if p.color == chess.WHITE:
            if white_passed is None or r > chess.square_rank(white_passed):
                white_passed = sq
        else:
            if black_passed is None or r < chess.square_rank(black_passed):
                black_passed = sq
    # compute best rook cheb distance to promotion square
    for r_sq, r_p in rooks:
        rf = chess.square_file(r_sq)
        rr = chess.square_rank(r_sq)
        if white_passed is not None and r_p.color == chess.WHITE:
            promo = (chess.square_file(white_passed), 7)
            d = cheb((rf, rr), promo)
            best_w = min(best_w, d)
        if black_passed is not None and r_p.color == chess.BLACK:
            promo = (chess.square_file(black_passed), 0)
            d = cheb((rf, rr), promo)
            best_b = min(best_b, d)
    val_w = 0.0 if best_w == 100 else (8.0 - float(best_w)) / 8.0
    val_b = 0.0 if best_b == 100 else (8.0 - float(best_b)) / 8.0
    return float(val_w - val_b)

def feature(board: chess.Board) -> float:
    'Central control score: for central 4x4 area (files c..f, ranks 3..6) add +1 for squares where White has more attackers than Black, -1 for the opposite'
    import chess
    score = 0.0
    for f in range(2, 6):  # c..f -> files 2..5
        for r in range(2, 6):  # ranks 3..6 -> 2..5 (0-based)
            sq = chess.square(f, r)
            try:
                wa = len(board.attackers(chess.WHITE, sq))
            except Exception:
                wa = 0
            try:
                ba = len(board.attackers(chess.BLACK, sq))
            except Exception:
                ba = 0
            if wa > ba:
                score += 1.0
            elif ba > wa:
                score -= 1.0
    return float(score)

def feature(board: chess.Board) -> float:
    'Passed pawns difference: (#white passed pawns) - (#black passed pawns)'
    try:
        pawn_map = {sq: p for sq, p in board.piece_map().items() if p.piece_type == chess.PAWN}
        white_pawns = [sq for sq, p in pawn_map.items() if p.color == chess.WHITE]
        black_pawns = [sq for sq, p in pawn_map.items() if p.color == chess.BLACK]
        def is_white_passed(sq):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            for bp in black_pawns:
                bf = chess.square_file(bp)
                br = chess.square_rank(bp)
                if abs(bf - f) <= 1 and br > r:
                    return False
            return True
        def is_black_passed(sq):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            for wp in white_pawns:
                wf = chess.square_file(wp)
                wr = chess.square_rank(wp)
                if abs(wf - f) <= 1 and wr < r:
                    return False
            return True
        wp = sum(1 for sq in white_pawns if is_white_passed(sq))
        bp = sum(1 for sq in black_pawns if is_black_passed(sq))
        return float(wp - bp)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) total score of passed pawns with clear promotion path (no opposing pieces between pawn and promotion on its file), weighted by advancement (0..1)'
    def is_passed(sq, color):
        pr = chess.square_rank(sq)
        pf = chess.square_file(sq)
        opp = not color
        if color == chess.WHITE:
            ranks = range(pr + 1, 8)
        else:
            ranks = range(pr - 1, -1, -1)
        for r in ranks:
            for f in (pf - 1, pf, pf + 1):
                if 0 <= f <= 7:
                    piece = board.piece_at(chess.square(f, r))
                    if piece is not None and piece.piece_type == chess.PAWN and piece.color == opp:
                        return False
        return True

    wm = 0.0
    bm = 0.0
    try:
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.PAWN and is_passed(sq, piece.color):
                pr = chess.square_rank(sq)
                pf = chess.square_file(sq)
                # check blocking pieces on same file between pawn and promotion
                blocking = 0
                if piece.color == chess.WHITE:
                    for r in range(pr + 1, 8):
                        p = board.piece_at(chess.square(pf, r))
                        if p is not None and p.piece_type != chess.KING:
                            blocking += 1
                else:
                    for r in range(pr - 1, -1, -1):
                        p = board.piece_at(chess.square(pf, r))
                        if p is not None and p.piece_type != chess.KING:
                            blocking += 1
                adv = (pr / 7.0) if piece.color == chess.WHITE else ((7 - pr) / 7.0)
                score = adv * (1.0 if blocking == 0 else 0.0)
                if piece.color == chess.WHITE:
                    wm += score
                else:
                    bm += score
    except Exception:
        return 0.0
    return float(wm - bm)

def feature(board: chess.Board) -> float:
    'Difference in control of open/semi-open files by rooks/queens (White - Black), normalized by 8 files'
    file_control_white = 0
    file_control_black = 0
    pm = board.piece_map()
    for f in range(8):
        file_sqs = [chess.square(f,r) for r in range(8)]
        white_controls = False
        black_controls = False
        for sq in file_sqs:
            try:
                attackers = board.attackers(chess.WHITE, sq)
            except Exception:
                attackers = set()
            for a in attackers:
                p = board.piece_at(a)
                if p is not None and (p.piece_type==chess.ROOK or p.piece_type==chess.QUEEN):
                    white_controls = True
                    break
            try:
                attackers_b = board.attackers(chess.BLACK, sq)
            except Exception:
                attackers_b = set()
            for a in attackers_b:
                p = board.piece_at(a)
                if p is not None and (p.piece_type==chess.ROOK or p.piece_type==chess.QUEEN):
                    black_controls = True
                    break
            if white_controls and black_controls:
                break
        if white_controls and not black_controls:
            file_control_white += 1
        if black_controls and not white_controls:
            file_control_black += 1
    return float((file_control_white - file_control_black) / 8.0)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of rook centralization: sum of 1/(1+euclidean_distance_to_center) for rooks'
    import chess, math
    pieces = board.piece_map()
    def rook_score(sq):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        # center is between d4/e5: use (3.5,3.5)
        dx = (f - 3.5)
        dy = (r - 3.5)
        d = math.hypot(dx, dy)
        return 1.0 / (1.0 + d)
    w = 0.0
    b = 0.0
    for sq, p in pieces.items():
        if p.piece_type == chess.ROOK:
            if p.color == chess.WHITE:
                w += rook_score(sq)
            else:
                b += rook_score(sq)
    return float(w - b)

def feature(board: chess.Board) -> float:
    'Net king pressure: weighted sum of pieces within manhattan distance<=2 from king (attacker strength); returns (pressure on Black king by White) - (pressure on White king by Black)'
    pm = board.piece_map()
    values = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0, chess.KING:0.0}
    def king_pressure(king_color):
        # find king
        king_sq = None
        for sq, pc in pm.items():
            if pc.piece_type == chess.KING and pc.color == king_color:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        pressure = 0.0
        attacker_color = not king_color
        for sq, pc in pm.items():
            if pc.color == attacker_color:
                dist = chess.square_distance(sq, king_sq)
                if dist <= 2:
                    weight = values.get(pc.piece_type, 0.0) / (1.0 + dist)
                    pressure += weight
        return pressure
    return float(king_pressure(chess.BLACK) - king_pressure(chess.WHITE))

def feature(board: chess.Board) -> float:
    'Passed pawn score difference (White - Black), each passed pawn weighted by rank advancement (0..1)'
    import chess
    pm = board.piece_map()
    white_pawns = [sq for sq, pc in pm.items() if pc.piece_type == chess.PAWN and pc.color == chess.WHITE]
    black_pawns = [sq for sq, pc in pm.items() if pc.piece_type == chess.PAWN and pc.color == chess.BLACK]
    black_pawn_set = set(black_pawns)
    white_pawn_set = set(white_pawns)
    def is_white_passed(sq):
        f = chess.square_file(sq); r = chess.square_rank(sq)
        for bf in [f-1, f, f+1]:
            if 0 <= bf <= 7:
                for bp in black_pawns:
                    if chess.square_file(bp) == bf and chess.square_rank(bp) >= r:
                        return False
        return True
    def is_black_passed(sq):
        f = chess.square_file(sq); r = chess.square_rank(sq)
        for wf in [f-1, f, f+1]:
            if 0 <= wf <= 7:
                for wp in white_pawns:
                    if chess.square_file(wp) == wf and chess.square_rank(wp) <= r:
                        return False
        return True
    wscore = 0.0
    for sq in white_pawns:
        if is_white_passed(sq):
            rank = chess.square_rank(sq)
            weight = rank / 7.0
            wscore += (0.5 + 0.5 * weight)
    bscore = 0.0
    for sq in black_pawns:
        if is_black_passed(sq):
            rank = 7 - chess.square_rank(sq)
            weight = rank / 7.0
            bscore += (0.5 + 0.5 * weight)
    return float(wscore - bscore)

def feature(board: chess.Board) -> float:
    'Pawn structure penalty: (doubled + isolated) pawn penalty for white minus black (positive is better for white)'
    try:
        piece_map = board.piece_map()
        files_w = {f:0 for f in range(8)}
        files_b = {f:0 for f in range(8)}
        pawn_sqs_w = []
        pawn_sqs_b = []
        for sq, p in piece_map.items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if p.color == chess.WHITE:
                    files_w[f] += 1
                    pawn_sqs_w.append(sq)
                else:
                    files_b[f] += 1
                    pawn_sqs_b.append(sq)
        def penalty(pawn_sqs, files):
            doubled = sum(max(0, cnt-1) for cnt in files.values())
            isolated = 0
            for sq in pawn_sqs:
                f = chess.square_file(sq)
                if (files.get(f-1,0) == 0) and (files.get(f+1,0) == 0):
                    isolated += 1
            # combine with weights: doubled heavier
            return doubled * 1.2 + isolated * 0.9
        wp = penalty(pawn_sqs_w, files_w)
        bp = penalty(pawn_sqs_b, files_b)
        # return goodness = negative penalty, so higher = better
        return float((bp - wp))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net king-zone safety difference: (White king defenders - Black attackers in white zone) - (Black king defenders - White attackers in black zone)'
    try:
        wk = board.king(chess.WHITE)
        bk = board.king(chess.BLACK)
        if wk is None or bk is None:
            return 0.0
        def zone_net(king_sq, king_color):
            others = []
            for sq in range(64):
                if chess.square_distance(sq, king_sq) <= 2:
                    others.append(sq)
            attackers = 0
            defenders = 0
            for sq in others:
                attackers += len(board.attackers(not king_color, sq))
                defenders += len(board.attackers(king_color, sq))
            return defenders - attackers
        net_w = zone_net(wk, chess.WHITE)
        net_b = zone_net(bk, chess.BLACK)
        return float(net_w - net_b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn proximity to opposing king: sum over pawns of (advancement_rank * inverse distance to enemy king), white minus black'
    piece_map = board.piece_map()
    white_king = black_king = None
    for sq, p in piece_map.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                white_king = sq
            else:
                black_king = sq
    white_sum = 0.0
    black_sum = 0.0
    for sq, p in piece_map.items():
        if p.piece_type == chess.PAWN:
            if p.color == chess.WHITE:
                adv = chess.square_rank(sq)  # 0..7, higher => more advanced
                dist = chess.square_distance(sq, black_king) if black_king is not None else 8
                white_sum += (1.0 + adv/7.0) / (1.0 + dist)
            else:
                adv = 7 - chess.square_rank(sq)
                dist = chess.square_distance(sq, white_king) if white_king is not None else 8
                black_sum += (1.0 + adv/7.0) / (1.0 + dist)
    return float(white_sum - black_sum)

def feature(board: chess.Board) -> float:
    'Number of legal moves available to the side to move (mobility of the side to move)'
    try:
        # legal_moves is an iterator; take its length safely
        lm = list(board.legal_moves)
        return float(len(lm))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Trapped minor-piece count difference: knights or bishops with <=2 legal moves and under attack (White - Black)'
    def trapped_count(color):
        cnt = 0
        try:
            b = board.copy(); b.turn = color
            legal_from = {}
            for mv in b.legal_moves:
                legal_from.setdefault(mv.from_square, 0)
                legal_from[mv.from_square] += 1
            for sq,p in board.piece_map().items():
                if p.color==color and p.piece_type in (chess.KNIGHT, chess.BISHOP):
                    moves = legal_from.get(sq, 0)
                    if moves <= 2 and board.is_attacked_by(not color, sq):
                        cnt += 1
        except Exception:
            return 0.0
        return float(cnt)
    return float(trapped_count(chess.WHITE) - trapped_count(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Difference in rook mobility measured as number of reachable ray-squares (white_total - black_total). Counts empty and capture squares along ranks/files until blocked.'
    piece_map = board.piece_map()
    def sq_index(file, rank):
        return rank * 8 + file
    white_total = 0.0
    black_total = 0.0
    for sq, p in piece_map.items():
        if p.piece_type != chess.ROOK:
            continue
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        dirs = [(1,0),(-1,0),(0,1),(0,-1)]
        mobility = 0
        for df, dr in dirs:
            cf, cr = f + df, r + dr
            while 0 <= cf < 8 and 0 <= cr < 8:
                idx = sq_index(cf, cr)
                if idx in piece_map:
                    # can capture the first occupied square
                    mobility += 1
                    break
                mobility += 1
                cf += df
                cr += dr
        if p.color == chess.WHITE:
            white_total += float(mobility)
        else:
            black_total += float(mobility)
    return float(white_total - black_total)

def feature(board: chess.Board) -> float:
