def feature(board: chess.Board) -> float:
    'Difference in pseudo-mobility of major pieces (rooks+queens): (white reach squares) - (black reach squares)'
    try:
        pm = board.piece_map()
        def sliding_reach_from(sq, dirs):
            reach = 0
            r0 = chess.square_rank(sq)
            f0 = chess.square_file(sq)
            for dr, df in dirs:
                r = r0 + dr
                f = f0 + df
                while 0 <= r <= 7 and 0 <= f <= 7:
                    s2 = chess.square(f, r)
                    reach += 1
                    if board.piece_at(s2) is not None:
                        break
                    r += dr
                    f += df
            return reach
        orth = ((1,0),(-1,0),(0,1),(0,-1))
        diag = ((1,1),(1,-1),(-1,1),(-1,-1))
        w_reach = 0
        b_reach = 0
        for sq, p in pm.items():
            if p.piece_type == chess.ROOK:
                if p.color == chess.WHITE:
                    w_reach += sliding_reach_from(sq, orth)
                else:
                    b_reach += sliding_reach_from(sq, orth)
            if p.piece_type == chess.QUEEN:
                if p.color == chess.WHITE:
                    w_reach += sliding_reach_from(sq, orth + diag)
                else:
                    b_reach += sliding_reach_from(sq, orth + diag)
        return float(w_reach - b_reach)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Queen tropism and proximity to enemy king: (White_score - Black_score) where score = sum(inverse distance to enemy king + attacks to squares around that king)'
    try:
        def queen_score(own_color):
            opp = not own_color
            k = board.king(opp)
            if k is None:
                return 0.0
            king_adjacent = [k] + [chess.square_file(k) and sq for sq in []]  # placeholder to make no error
            # collect adjacent squares to king (including diagonals)
            adj_sqs = []
            kr = chess.square_rank(k)
            kf = chess.square_file(k)
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    f = kf + df
                    r = kr + dr
                    if 0 <= f <= 7 and 0 <= r <= 7:
                        adj_sqs.append(chess.square(f, r))
            total = 0.0
            for sq, p in board.piece_map().items():
                if p.piece_type != chess.QUEEN or p.color != own_color:
                    continue
                # inverse distance to enemy king
                dist = chess.square_distance(sq, k)
                if dist == 0:
                    inv = 1.5
                else:
                    inv = 1.0 / dist
                # number of attacked squares in king adjacency
                attacks_near = sum(1 for s in adj_sqs if board.is_attacked_by(own_color, s))
                total += inv + 0.4 * attacks_near
            return total
        return float(queen_score(chess.WHITE) - queen_score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of likely trapped non-pawn pieces (<=1 legal move and attacked by more opponents than defenders) (White - Black)'
    pm = board.piece_map()
    moves_from = {}
    for mv in board.legal_moves:
        moves_from[mv.from_square] = moves_from.get(mv.from_square, 0) + 1
    white_trapped = 0
    black_trapped = 0
    for sq, pc in pm.items():
        if pc.piece_type in (chess.PAWN, chess.KING):
            continue
        moves = moves_from.get(sq, 0)
        defenders = len(board.attackers(pc.color, sq))
        attackers = len(board.attackers(not pc.color, sq))
        if moves <= 1 and attackers > defenders:
            if pc.color == chess.WHITE:
                white_trapped += 1
            else:
                black_trapped += 1
    return float(white_trapped - black_trapped)

def feature(board: chess.Board) -> float:
    'Rook influence on enemy half: (squares on opponent half attacked by your rooks normalized) difference (white - black)'
    def rook_attacks_on_half(color):
        attacked = 0
        # opponent half: for white it's ranks 4..7, for black ranks 0..3
        ranks = range(4, 8) if color == chess.WHITE else range(0, 4)
        for r in ranks:
            for f in range(0, 8):
                sq = chess.square(f, r)
                # check if any rook of color attacks this square
                attackers = board.attackers(color, sq)
                for a in attackers:
                    p = board.piece_at(a)
                    if p and p.piece_type == chess.ROOK and p.color == color:
                        attacked += 1
                        break
        return attacked
    w = rook_attacks_on_half(chess.WHITE)
    b = rook_attacks_on_half(chess.BLACK)
    # normalize by half-board size (32)
    return float((w - b) / 32.0)

def feature(board: chess.Board) -> float:
