def feature(board: chess.Board) -> float:
    'Trapped-king score difference: (black trapped score) - (white trapped score); positive favors White if Black is trapped. Edge, few king moves and many adjacent attackers increase the score.'
    try:
        pm = board.piece_map()
        def trap_score_for(king_color):
            king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == king_color), None)
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            on_edge = 1 if (kf == 0 or kf == 7 or kr == 0 or kr == 7) else 0
            # king legal moves
            k_moves = 0
            for mv in board.legal_moves:
                try:
                    if mv.from_square == king_sq:
                        k_moves += 1
                except Exception:
                    continue
            # adjacent attackers by opponent
            opponent = chess.WHITE if king_color == chess.BLACK else chess.BLACK
            adj_att = 0
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    nf = kf + df
                    nr = kr + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        sq = chess.parse_square('abcdefgh'[nf] + str(nr + 1))
                        adj_att += len(board.attackers(opponent, sq))
            score = on_edge * max(0, 4 - k_moves) * adj_att
            return float(score)
        black_trap = trap_score_for(chess.BLACK)
        white_trap = trap_score_for(chess.WHITE)
        return float(black_trap - white_trap)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Minor-piece outpost count in central region protected by a pawn behind (White minus Black)'
    try:
        pm = board.piece_map()
        white_outposts = 0
        black_outposts = 0
        for sq, p in pm.items():
            if p is None:
                continue
            if p.piece_type not in (chess.KNIGHT, chess.BISHOP):
                continue
            file = chess.square_file(sq); rank = chess.square_rank(sq)
            # central region c3-f6 -> files 2..5 ranks 2..5
            if not (2 <= file <= 5 and 2 <= rank <= 5):
                continue
            # check friendly pawn on one of three squares behind the piece (for white behind = rank-1)
            found_backing_pawn = False
            if p.color == chess.WHITE:
                back_rank = rank - 1
                for df in (-1,0,1):
                    bf = file + df
                    if 0 <= bf < 8 and 0 <= back_rank < 8:
                        sqb = chess.square(bf, back_rank)
                        q = pm.get(sqb)
                        if q and q.piece_type==chess.PAWN and q.color==chess.WHITE:
                            found_backing_pawn = True
                            break
                if found_backing_pawn:
                    white_outposts += 1
            else:
                back_rank = rank + 1
                for df in (-1,0,1):
                    bf = file + df
                    if 0 <= bf < 8 and 0 <= back_rank < 8:
                        sqb = chess.square(bf, back_rank)
                        q = pm.get(sqb)
                        if q and q.piece_type==chess.PAWN and q.color==chess.BLACK:
                            found_backing_pawn = True
                            break
                if found_backing_pawn:
                    black_outposts += 1
        return float(white_outposts - black_outposts)
    except Exception:
        return 0.0

