def feature(board: chess.Board) -> float:
    'Net weighted attacking pressure in each king zone: sum of enemy attackers (weighted by piece value) inside a 2-manhattan radius of the king (White - Black)'
    values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:20000}
    pm = board.piece_map()
    # find kings
    wk = bk = None
    for sq, pc in pm.items():
        if pc.piece_type == chess.KING:
            if pc.color == chess.WHITE:
                wk = sq
            else:
                bk = sq
    def zone_squares(king_sq):
        if king_sq is None:
            return []
        res = []
        kf, kr = chess.square_file(king_sq), chess.square_rank(king_sq)
        for f in range(max(0,kf-2), min(7,kf+2)+1):
            for r in range(max(0,kr-2), min(7,kr+2)+1):
                res.append(chess.square(f,r))
        return res
    def pressure_on_king(king_sq, defender_color):
        # attackers are opposite color
        if king_sq is None:
            return 0.0
        atk_color = not defender_color
        total = 0.0
        for sq in zone_squares(king_sq):
            try:
                attackers = board.attackers(atk_color, sq)
            except Exception:
                attackers = set()
            for a in attackers:
                pc = board.piece_at(a)
                if pc is None:
                    continue
                total += values.get(pc.piece_type,0)
        return total
    white_pressure = pressure_on_king(wk, chess.WHITE)
    black_pressure = pressure_on_king(bk, chess.BLACK)
    # return in pawns (divide by 100) to keep scale moderate
    return (white_pressure - black_pressure) / 100.0

def feature(board: chess.Board) -> float:
    'Open-file control difference: number of completely pawn-free files controlled by White rooks/queens minus those controlled by Black, normalized by 8'
    pm = board.piece_map()
    pawn_files = set()
    for sq,p in pm.items():
        if p.piece_type==chess.PAWN:
            pawn_files.add(chess.square_file(sq))
    white_ctrl = 0
    black_ctrl = 0
    for f in range(8):
        if f in pawn_files:
            continue
        # control approximated by presence of rook/queen on that file
        for sq,p in pm.items():
            if chess.square_file(sq)!=f: continue
            if p.piece_type in (chess.ROOK, chess.QUEEN):
                if p.color==chess.WHITE:
                    white_ctrl += 1
                else:
                    black_ctrl += 1
                break
    return float((white_ctrl - black_ctrl)/8.0)

def feature(board: chess.Board) -> float:
    'Difference in local pawn shield size around each king (white - black); counts same-color pawns within Manhattan distance <= 3 of the king'
    wm = 0
    bm = 0
    pm = board.piece_map()
    # find kings
    wking = None
    bking = None
    for sq, pc in pm.items():
        if pc.piece_type == chess.KING:
            if pc.color == chess.WHITE:
                wking = sq
            else:
                bking = sq
    def shield_count(king_sq, color):
        if king_sq is None:
            return 0
        cnt = 0
        for sq, pc in pm.items():
            if pc.piece_type == chess.PAWN and pc.color == color:
                if chess.square_distance(king_sq, sq) <= 3:
