        return cnt
    wm = shield_count(wking, chess.WHITE)
    bm = shield_count(bking, chess.BLACK)
    return float(wm - bm)

def feature(board: chess.Board) -> float:
    'Pressure on major pieces: weighted attackers on rooks/queens (Black pressure on White majors minus White on Black)'
    try:
        pm = board.piece_map()
        values = {chess.ROOK:5.0, chess.QUEEN:9.0}
        def pressure_on_majors(victim_color):
            total = 0.0
            for sq, p in pm.items():
                if p and p.color==victim_color and p.piece_type in values:
                    attackers = board.attackers(not victim_color, sq)
                    atk_count = len(attackers)
                    total += float(atk_count) * values[p.piece_type]
            return total
        black_on_white = pressure_on_majors(chess.WHITE)
        white_on_black = pressure_on_majors(chess.BLACK)
        return float(black_on_white - white_on_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King safety mobility and centralization composite: (white safe adjacent squares - black safe adjacent squares) minus distance-from-center penalty (closer to center = +)'
    centers = [chess.parse_square(s) for s in ('d4','e4','d5','e5')]
    def safe_adjacent_and_center(sq, color):
        if sq is None:
            return 0.0
        r = chess.square_rank(sq); f = chess.square_file(sq)
        safe = 0
        for dr in (-1,0,1):
            for df in (-1,0,1):
                if dr == 0 and df == 0:
                    continue
                rr, ff = r + dr, f + df
                if 0 <= rr <= 7 and 0 <= ff <= 7:
                    to = chess.square(ff, rr)
                    occ = board.piece_at(to)
                    if occ is not None and occ.color == color:
                        continue
                    # square considered safe if not attacked by opponent
                    if not board.is_attacked_by(not color, to):
                        safe += 1
        center_bonus = 1.0 if sq in centers else 0.0
        return safe + center_bonus
    wking = board.king(chess.WHITE)
    bking = board.king(chess.BLACK)
    wval = safe_adjacent_and_center(wking, chess.WHITE) if wking is not None else 0.0
    bval = safe_adjacent_and_center(bking, chess.BLACK) if bking is not None else 0.0
    # also subtract normalized distance from center (closer is better); use Manhattan to center of board (3.5,3.5)
    def center_dist_bonus(sq):
        if sq is None:
            return 0.0
        r = chess.square_rank(sq); f = chess.square_file(sq)
        return - (abs(r - 3.5) + abs(f - 3.5)) * 0.1
    return float((wval + center_dist_bonus(wking)) - (bval + center_dist_bonus(bking)))

def feature(board: chess.Board) -> float:
    'Net "mating-net" coverage: difference in fraction of adjacent king-squares attacked by the enemy (black_on_white_frac - white_on_black_frac)'
    piece_map = board.piece_map()
    white_king_sq = None
    black_king_sq = None
    for sq, pc in piece_map.items():
        if pc.piece_type == chess.KING:
            if pc.color == chess.WHITE:
                white_king_sq = sq
            else:
                black_king_sq = sq
    def attacked_fraction(king_sq, defender_color):
        if king_sq is None:
            return 0.0
        kr = chess.square_rank(king_sq)
        kf = chess.square_file(king_sq)
        total = 0
        attacked = 0
        for dr in (-1, 0, 1):
            for df in (-1, 0, 1):
                if dr == 0 and df == 0:
                    continue
                rr = kr + dr
                ff = kf + df
                if 0 <= rr <= 7 and 0 <= ff <= 7:
                    total += 1
                    sq = chess.square(ff, rr)
                    if board.is_attacked_by(not defender_color, sq):
                        attacked += 1
        return (attacked / total) if total > 0 else 0.0
    black_frac = attacked_fraction(white_king_sq, chess.WHITE)
    white_frac = attacked_fraction(black_king_sq, chess.BLACK)
    return float(black_frac - white_frac)

