def feature(board: chess.Board) -> float:
    'Approximate mobility per piece: (White_mobility_per_piece - Black_mobility_per_piece) where mobility counts pseudo-legal target squares (ignores pins)'
    pm = board.piece_map()
    # helper to count moves ignoring pins (pseudo-legal)
    def pseudo_targets_from(sq, pc):
        targets = set()
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if pc.piece_type == chess.KNIGHT:
            knights = [(2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)]
            for df, dr in knights:
                nf, nr = f+df, r+dr
                if 0 <= nf <=7 and 0 <= nr <=7:
                    tsq = chess.square(nf, nr)
                    tp = board.piece_at(tsq)
                    if tp is None or tp.color != pc.color:
                        targets.add(tsq)
        elif pc.piece_type in (chess.BISHOP, chess.ROOK, chess.QUEEN):
            directions = []
            if pc.piece_type in (chess.BISHOP, chess.QUEEN):
                directions += [(1,1),(1,-1),(-1,1),(-1,-1)]
            if pc.piece_type in (chess.ROOK, chess.QUEEN):
                directions += [(1,0),(-1,0),(0,1),(0,-1)]
            for df, dr in directions:
                nf, nr = f+df, r+dr
                while 0 <= nf <=7 and 0 <= nr <=7:
                    tsq = chess.square(nf, nr)
                    tp = board.piece_at(tsq)
                    if tp is None:
                        targets.add(tsq)
                    else:
                        if tp.color != pc.color:
                            targets.add(tsq)
                        break
                    nf += df
                    nr += dr
        elif pc.piece_type == chess.KING:
            for df in (-1,0,1):
                for dr in (-1,0,1):
                    if df==0 and dr==0:
                        continue
                    nf, nr = f+df, r+dr
                    if 0 <= nf <=7 and 0 <= nr <=7:
                        tsq = chess.square(nf, nr)
                        tp = board.piece_at(tsq)
                        if tp is None or tp.color != pc.color:
                            targets.add(tsq)
        elif pc.piece_type == chess.PAWN:
            if pc.color == chess.WHITE:
                # single push
                if r < 7:
                    tsq = chess.square(f, r+1)
                    if board.piece_at(tsq) is None:
                        targets.add(tsq)
                    # captures
                    for df in (-1,1):
                        nf = f+df
                        nr = r+1
                        if 0 <= nf <=7 and nr <=7:
                            tsq = chess.square(nf, nr)
                            tp = board.piece_at(tsq)
                            if tp is not None and tp.color == chess.BLACK:
                                targets.add(tsq)
            else:
                if r > 0:
                    tsq = chess.square(f, r-1)
                    if board.piece_at(tsq) is None:
                        targets.add(tsq)
                    for df in (-1,1):
                        nf = f+df
                        nr = r-1
                        if 0 <= nf <=7 and nr >=0:
                            tsq = chess.square(nf, nr)
                            tp = board.piece_at(tsq)
                            if tp is not None and tp.color == chess.WHITE:
                                targets.add(tsq)
        return targets
    white_moves = 0
    black_moves = 0
    white_count = 0
    black_count = 0
    for sq, pc in pm.items():
        if pc.color == chess.WHITE:
            white_moves += len(pseudo_targets_from(sq, pc))
            white_count += 1
        else:
            black_moves += len(pseudo_targets_from(sq, pc))
            black_count += 1
    white_avg = white_moves / (white_count + 1e-6)
    black_avg = black_moves / (black_count + 1e-6)
    return white_avg - black_avg

def feature(board: chess.Board) -> float:
    'Minor-piece outpost score: knights and bishops on advanced safe squares (not attacked by enemy pawns) with bonus if supported by a pawn: (White - Black)'
    pm = board.piece_map()
    def pawn_attacks_of(color):
        attacks = set()
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN and p.color == color:
                f = chess.square_file(sq); r = chess.square_rank(sq)
                if color == chess.WHITE:
                    for df in (-1,1):
                        nf, nr = f+df, r+1
                        if 0 <= nf <= 7 and 0 <= nr <= 7:
                            attacks.add(chess.square(nf,nr))
                else:
                    for df in (-1,1):
                        nf, nr = f+df, r-1
                        if 0 <= nf <= 7 and 0 <= nr <= 7:
                            attacks.add(chess.square(nf,nr))
        return attacks
    white_pawn_att = pawn_attacks_of(chess.BLACK)  # squares attacked by black pawns
    black_pawn_att = pawn_attacks_of(chess.WHITE)  # squares attacked by white pawns
    def score_for(color):
        score = 0.0
        for sq, p in pm.items():
            if p.color != color:
                continue
            if p.piece_type not in (chess.KNIGHT, chess.BISHOP):
                continue
            r = chess.square_rank(sq)
            advanced_ok = (color==chess.WHITE and r >= 3) or (color==chess.BLACK and r <= 4)
            if not advanced_ok:
                continue
            attacked_by_enemy_pawn = (sq in (white_pawn_att if color==chess.WHITE else black_pawn_att))
            if attacked_by_enemy_pawn:
                continue
            # base score
            s = 1.0
            # bonus if defended by a pawn
            defended_by_pawn = False
            for df, dr in ((-1,1),(1,1)) if color==chess.WHITE else ((-1,-1),(1,-1)):
                f = chess.square_file(sq) + df
                r2 = chess.square_rank(sq) + dr
                if 0 <= f <= 7 and 0 <= r2 <= 7:
                    sq2 = chess.square(f, r2)
                    p2 = board.piece_at(sq2)
                    if p2 is not None and p2.piece_type==chess.PAWN and p2.color==color:
                        defended_by_pawn = True
                        break
            if defended_by_pawn:
                s += 0.5
            score += s
        return score
    return score_for(chess.WHITE) - score_for(chess.BLACK)

def feature(board: chess.Board) -> float:
    'Difference in count of low-mobility (<=1 legal move) non-pawn non-king pieces (white minus black). Uses current legal move list.'
    try:
        legal = list(board.legal_moves)
        moves_from = {}
        for mv in legal:
            moves_from.setdefault(mv.from_square, 0)
            moves_from[mv.from_square] += 1
        pm = board.piece_map()
        white_trapped = 0
        black_trapped = 0
        for sq, piece in pm.items():
            if piece.piece_type in (chess.PAWN, chess.KING):
                continue
            mobility = moves_from.get(sq, 0)
            if mobility <= 1:
                if piece.color == chess.WHITE:
                    white_trapped += 1
                else:
                    black_trapped += 1
        return float(white_trapped - black_trapped)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn structure weakness score: (doubled * 0.5 + isolated * 0.7 + pawn_islands * 0.2) for White minus Black'
    pm = board.piece_map()
    white_files = [0]*8
    black_files = [0]*8
    for sq,p in pm.items():
        if p.piece_type == chess.PAWN:
            f = chess.square_file(sq)
            if p.color == chess.WHITE:
                white_files[f] += 1
            else:
                black_files[f] += 1
    def score(files):
        doubled = sum(max(0, c-1) for c in files)
        isolated = 0
        islands = 0
        in_island = False
        for i,c in enumerate(files):
            if c > 0:
                if (i==0 or files[i-1]==0) and (i==7 or files[i+1]==0):
                    isolated += 1
                if not in_island:
                    islands += 1
                    in_island = True
            else:
                in_island = False
        return doubled*0.5 + isolated*0.7 + islands*0.2
    return float(score(white_files) - score(black_files))

def feature(board: chess.Board) -> float:
    'Count of promotion squares attacked by enemy bishops minus those attacked by friendly bishops (positive favors the side with more promotion control)'
    white_score = 0
    black_score = 0
    for sq, pc in board.piece_map().items():
        if pc.piece_type != chess.PAWN:
            continue
        file = chess.square_file(sq)
        rank = chess.square_rank(sq)
        if pc.color == chess.WHITE:
            promo = chess.square(file, 7)
            if any(board.piece_at(sq2) and board.piece_at(sq2).piece_type == chess.BISHOP and board.piece_at(sq2).color == chess.WHITE for sq2 in board.attackers(chess.WHITE, promo)):
                white_score += 1
            if any(board.piece_at(sq2) and board.piece_at(sq2).piece_type == chess.BISHOP and board.piece_at(sq2).color == chess.BLACK for sq2 in board.attackers(chess.BLACK, promo)):
                black_score += 1
        else:
            promo = chess.square(file, 0)
            if any(board.piece_at(sq2) and board.piece_at(sq2).piece_type == chess.BISHOP and board.piece_at(sq2).color == chess.BLACK for sq2 in board.attackers(chess.BLACK, promo)):
                black_score += 1
            if any(board.piece_at(sq2) and board.piece_at(sq2).piece_type == chess.BISHOP and board.piece_at(sq2).color == chess.WHITE for sq2 in board.attackers(chess.WHITE, promo)):
                white_score += 1
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Difference in non-pawn control of central squares d4,e4,d5,e5 (white - black); counts unique non-pawn attackers controlling those squares'
    center_names = ['d4', 'e4', 'd5', 'e5']
    centers = [chess.parse_square(n) for n in center_names]
    pm = board.piece_map()
    def control_nonpawn(color):
        attackers_set = set()
        for c in centers:
            try:
                att = board.attackers(color, c)
            except Exception:
                att = set()
            for a in att:
                pc = pm.get(a)
                if pc is not None and pc.piece_type != chess.PAWN:
                    attackers_set.add(a)
        return len(attackers_set)
    w = control_nonpawn(chess.WHITE)
    b = control_nonpawn(chess.BLACK)
    return float(w - b)

def feature(board: chess.Board) -> float:
    'Pawn-file majority score: for each file +1 if White has more pawns than Black on that file, -1 if Black has more, sum over files. Positive favors White central pawn presence.'
    try:
        pm = board.piece_map()
        score = 0.0
        for f in range(8):
            white_p = 0
            black_p = 0
            for r in range(8):
                sq = chess.square(f, r)
                p = pm.get(sq)
                if p and p.piece_type == chess.PAWN:
                    if p.color == chess.WHITE:
                        white_p += 1
                    else:
                        black_p += 1
            if white_p > black_p:
                score += 1.0
            elif black_p > white_p:
                score -= 1.0
        return float(score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Relative proximity of queens to the enemy king: (1/(1+d)) for white queen to black king minus same for black queen to white king'
    try:
        pm = board.piece_map()
        white_queens = [sq for sq, pc in pm.items() if pc.piece_type == chess.QUEEN and pc.color == chess.WHITE]
        black_queens = [sq for sq, pc in pm.items() if pc.piece_type == chess.QUEEN and pc.color == chess.BLACK]
        white_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.BLACK), None)
        def inv_dist_min(queen_sqs, target_sq):
            if not queen_sqs or target_sq is None:
                return 0.0
            md = min(chess.square_distance(qs, target_sq) for qs in queen_sqs)
            return 1.0 / (1.0 + float(md))
        return inv_dist_min(white_queens, black_king_sq) - inv_dist_min(black_queens, white_king_sq)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Immediate promotion available for side-to-move (1.0) else 0.0; indicates tactical immediacy'
    try:
        for mv in board.legal_moves:
            # a promotion move will have mv.promotion set (int piece type)
            if getattr(mv, 'promotion', None):
                return 1.0
        return 0.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Attack pressure on the side-to-move king: sum of opponent attackers on the king square and its 8 neighbors'
    try:
        pm = board.piece_map()
        stm = board.turn
        king_sq = None
        for sq, pc in pm.items():
            if pc.piece_type == chess.KING and pc.color == stm:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        opp = not stm
        total = 0.0
        kf = chess.square_file(king_sq)
        kr = chess.square_rank(king_sq)
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                f = kf + df
                r = kr + dr
                if 0 <= f <= 7 and 0 <= r <= 7:
                    sq = chess.square(f, r)
                    total += float(len(board.attackers(opp, sq)))
        return total
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Relative queen activation: (white queen closeness to black king weighted by value) - (black queen closeness to white king). Closer queens score higher.'
    qval = 900.0
    def queen_score(color):
        # queen of color attacking the enemy king
        ks = board.king(not color)
        if ks is None:
            return 0.0
        score = 0.0
        for sq, p in board.piece_map().items():
            if p is not None and p.piece_type == chess.QUEEN and p.color == color:
                d = chess.square_distance(sq, ks)
                d = max(1, d)
                score += qval / d
        return score
    return float(queen_score(chess.WHITE) - queen_score(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Normalized mobility gap: (white_mobility - black_mobility) / max(1, total_nonking_pieces), where mobility counts legal moves for each side'
    try:
        pieces = board.piece_map()
    except Exception:
        pieces = {}
    total_pieces = max(1, sum(1 for p in pieces.values() if p.piece_type != chess.KING))
    # compute mobility for side to move and opponent by copying board
    try:
        bcopy = board.copy()
    except Exception:
        # fallback: estimate mobility by attacked squares count
        def attacked_count(color):
            s = 0
            for sq in range(64):
                try:
                    if board.is_attacked_by(color, sq):
                        s += 1
                except Exception:
                    pass
            return s
        w_mob = attacked_count(chess.WHITE)
        b_mob = attacked_count(chess.BLACK)
        return float((w_mob - b_mob) / total_pieces)
    # count legal moves for white
    bcopy.turn = chess.WHITE
    w_mob = sum(1 for _ in bcopy.legal_moves)
    bcopy.turn = chess.BLACK
    b_mob = sum(1 for _ in bcopy.legal_moves)
    return float((w_mob - b_mob) / total_pieces)

def feature(board: chess.Board) -> float:
    'Difference in attack span provided by major pieces (rook/bishop/queen): squares attacked by majors (White - Black)'
    import chess
    pm = board.piece_map()
    def major_attacked_squares(color):
        attacked = set()
        for sq in chess.SQUARES:
            atks = board.attackers(color, sq)
            for a in atks:
                p = board.piece_at(a)
                if p and p.piece_type in (chess.ROOK, chess.BISHOP, chess.QUEEN):
                    attacked.add(sq)
                    break
        return len(attacked)
    return float(major_attacked_squares(chess.WHITE) - major_attacked_squares(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Net attack pressure on squares adjacent to each king (white minus black)'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.BLACK), None)
        def adjacent_squares(sq):
            if sq is None:
                return []
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            res = []
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    nf = f + df
                    nr = r + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        res.append(chess.square(nf, nr))
            return res
        white_pressure = 0
        black_pressure = 0
        for adj in adjacent_squares(white_king_sq):
            white_pressure += len(board.attackers(chess.BLACK, adj))
        for adj in adjacent_squares(black_king_sq):
            black_pressure += len(board.attackers(chess.WHITE, adj))
        return float(white_pressure - black_pressure)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material balance (white minus black) in pawns=100 n=320 b=330 r=500 q=900 units, returned in pawn-equivalents (divide by 100)'
    try:
        values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        w = 0
        b = 0
        for sq, pc in board.piece_map().items():
            val = values.get(pc.piece_type, 0)
            if pc.color == chess.WHITE:
                w += val
            else:
                b += val
        return float((w - b) / 100.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in king-zone domination: fraction of squares within Chebyshev distance 2 of the king that are attacked by the enemy (higher = more dominated by attacker).'
    try:
        pm = board.piece_map()
        def zone_attack_fraction(color):
            king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==color), None)
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
            opp = not color
            zone = []
            for df in range(-2,3):
                for dr in range(-2,3):
                    nf, nr = kf+df, kr+dr
                    if not (0 <= nf <= 7 and 0 <= nr <= 7):
                        continue
                    zone.append(chess.square(nf,nr))
            if not zone:
                return 0.0
            attacked = 0
            for sq in zone:
                if board.is_attacked_by(opp, sq):
                    attacked += 1
            return float(attacked) / float(len(zone))
        return float(zone_attack_fraction(chess.BLACK) - zone_attack_fraction(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in rook legal move counts (white rooks moves - black rooks moves), normalized by 10.'
    try:
        w_moves = 0
        b_moves = 0
        for mv in board.legal_moves:
            p = board.piece_at(mv.from_square)
            if p is None:
                continue
            if p.piece_type != chess.ROOK:
                continue
            if p.color == chess.WHITE:
                w_moves += 1
            else:
                b_moves += 1
        return float(w_moves - b_moves) / 10.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in board square coverage (number of squares attacked by white minus black) normalized by 64'
    try:
        white_cov = 0
        black_cov = 0
        for sq in range(64):
            if board.is_attacked_by(chess.WHITE, sq):
                white_cov += 1
            if board.is_attacked_by(chess.BLACK, sq):
                black_cov += 1
        return float((white_cov - black_cov) / 64.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Signed fraction of legal moves (for side to move) that move a piece closer to the enemy king; positive if white to move, negative if black to move'
    import chess
    pm = board.piece_map()
    opp_color = not board.turn
    king_sq = None
    for sq, pc in pm.items():
        if pc.piece_type == chess.KING and pc.color == opp_color:
            king_sq = sq
            break
    if king_sq is None:
        return 0.0
    total = 0
    closer = 0
    for mv in board.legal_moves:
        total += 1
        try:
            d_from = chess.square_distance(mv.from_square, king_sq)
            d_to = chess.square_distance(mv.to_square, king_sq)
            if d_to < d_from:
                closer += 1
        except Exception:
            continue
    frac = (float(closer) / float(total)) if total > 0 else 0.0
    return frac if board.turn == chess.WHITE else -frac

def feature(board: chess.Board) -> float:
    'Trapped minor pieces difference: count of white minor pieces (N/B) with no safe destination (moves either blocked or all attacked) minus same for black'
    knight_offsets = [(-2,-1),(-2,1),(-1,-2),(-1,2),(1,-2),(1,2),(2,-1),(2,1)]
    def safe_moves_for_piece(sq, p):
        moves_found = 0
        f0 = chess.square_file(sq)
        r0 = chess.square_rank(sq)
        if p.piece_type == chess.KNIGHT:
            for df,dr in knight_offsets:
                f = f0 + df
                r = r0 + dr
                if 0 <= f < 8 and 0 <= r < 8:
                    dst = chess.square(f,r)
                    occ = board.piece_at(dst)
                    if occ is not None and occ.color == p.color:
                        continue
                    # if destination is not attacked by opponent, count as safe
                    if not board.is_attacked_by(not p.color, dst):
                        moves_found += 1
        elif p.piece_type == chess.BISHOP:
            for step_f,step_r in ((1,1),(1,-1),(-1,1),(-1,-1)):
                f = f0 + step_f
                r = r0 + step_r
                while 0 <= f < 8 and 0 <= r < 8:
                    dst = chess.square(f,r)
                    occ = board.piece_at(dst)
                    if occ is not None and occ.color == p.color:
                        break
                    if occ is None or occ.color != p.color:
                        if not board.is_attacked_by(not p.color, dst):
                            moves_found += 1
                            # we still consider other rays (but count only existence)
                            break
                    if occ is not None:
                        break
                    f += step_f
                    r += step_r
        else:
            return 0
        return moves_found
    white_trapped = 0
    black_trapped = 0
    for sq,p in board.piece_map().items():
        if p.piece_type in (chess.KNIGHT, chess.BISHOP):
            safe = safe_moves_for_piece(sq, p)
            if safe == 0:
                if p.color == chess.WHITE:
                    white_trapped += 1
                else:
                    black_trapped += 1
    return float(white_trapped - black_trapped)

def feature(board: chess.Board) -> float:
    'Potential immediate capture net gains (approx): sum for pieces that can be captured by a less valuable attacker (white - black), values using standard piece weights'
    try:
        piece_map = board.piece_map()
        values = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0, chess.KING:20000.0}
        def capture_potential_for(attacker_color):
            total = 0.0
            # for each enemy piece, see if any attacker of attacker_color attacks it
            for sq_t, tgt in piece_map.items():
                if tgt.color == attacker_color:
                    continue
                attackers = board.attackers(attacker_color, sq_t)
                if not attackers:
                    continue
                # find cheapest attacker
                min_att = None
                min_val = 1e9
                for a in attackers:
                    ap = piece_map.get(a)
                    if ap is None:
                        continue
                    v = values.get(ap.piece_type, 0.0)
                    if v < min_val:
                        min_val = v
                        min_att = a
                captured_val = values.get(tgt.piece_type, 0.0)
                # approximate net gain if cheapest attacker captures this target
                net = captured_val - min_val
                if net > 0:
                    total += net
            return total
        return float(capture_potential_for(chess.WHITE) - capture_potential_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of safe escape squares for each king (white_safe - black_safe), counting adjacent squares not occupied by same color and not attacked by opponent'
    try:
        pm = board.piece_map()
        def safe_squares(king_color):
            king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == king_color), None)
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            safe = 0
            opponent = not king_color
            for df in (-1,0,1):
                for dr in (-1,0,1):
                    if df == 0 and dr == 0:
                        continue
                    nf = kf + df
                    nr = kr + dr
                    if not (0 <= nf <= 7 and 0 <= nr <= 7):
                        continue
                    nsq = chess.square(nf, nr)
                    occupant = board.piece_at(nsq)
                    if occupant is not None and occupant.color == king_color:
                        continue
                    # square must not be attacked by opponent to be considered safe
                    try:
                        attacked = board.is_attacked_by(opponent, nsq)
                    except Exception:
                        attacked = False
                    if not attacked:
                        safe += 1
            return float(safe)
        return safe_squares(chess.WHITE) - safe_squares(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net available one-move checks: (number of legal moves that give check for White) - (for Black) as a simple gauge of mating pressure'
    try:
        # iterate legal moves for both colors by toggling turn on copies
        checks_white = 0
        checks_black = 0
        # helper to count for a color
        def count_checks_for(color):
            cnt = 0
            try:
                b = board.copy()
                b.turn = color
                for mv in list(b.legal_moves):
                    b.push(mv)
                    if b.is_check():
                        cnt += 1
                    b.pop()
            except Exception:
                return 0
            return cnt
        checks_white = count_checks_for(chess.WHITE)
        checks_black = count_checks_for(chess.BLACK)
        return float(checks_white - checks_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Fraction of the up-to-8 squares adjacent to the white king that are attacked by Black (0..1)'
    try:
        pm = board.piece_map()
    except Exception:
        return 0.0
    wk_sq = None
    for sq, p in pm.items():
        if p.piece_type == chess.KING and p.color == chess.WHITE:
            wk_sq = sq
            break
    if wk_sq is None:
        return 0.0
    wf = chess.square_file(wk_sq)
    wr = chess.square_rank(wk_sq)
    adj_total = 0
    adj_attacked = 0
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            if df == 0 and dr == 0:
                continue
            nf = wf + df
            nr = wr + dr
            if 0 <= nf <= 7 and 0 <= nr <= 7:
                adj_total += 1
                sq = nr * 8 + nf
                try:
                    if board.is_attacked_by(chess.BLACK, sq):
                        adj_attacked += 1
                except Exception:
                    pass
    if adj_total == 0:
        return 0.0
    return float(adj_attacked) / float(adj_total)

def feature(board: chess.Board) -> float:
    'Difference (Black_exposed_ratio - White_exposed_ratio): fraction of non-pawn pieces attacked by enemy; positive means Black pieces are more exposed (favors White)'
    try:
        white_total = white_attacked = 0
        black_total = black_attacked = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                continue
            if p.color == chess.WHITE:
                white_total += 1
                if board.is_attacked_by(chess.BLACK, sq):
                    white_attacked += 1
            else:
                black_total += 1
                if board.is_attacked_by(chess.WHITE, sq):
                    black_attacked += 1
        def ratio(att, tot):
            return (att / tot) if tot > 0 else 0.0
        return float(ratio(black_attacked, black_total) - ratio(white_attacked, white_total))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Relative king centralization: (White king distance from e1) - (Black king distance from e8). Larger positive means White king is farther from its home square than Black.'
    pm = board.piece_map()
    w_king_sq = None
    b_king_sq = None
    for sq, p in pm.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                w_king_sq = sq
            else:
                b_king_sq = sq
    # default to 0 if missing
    dist_w = 0
    dist_b = 0
    try:
        if w_king_sq is not None:
            dist_w = chess.square_distance(w_king_sq, chess.parse_square('e1'))
        if b_king_sq is not None:
            dist_b = chess.square_distance(b_king_sq, chess.parse_square('e8'))
    except Exception:
        pass
    return float(dist_w - dist_b)

def feature(board: chess.Board) -> float:
    '8. Pawn shield count difference: number of friendly pawns in 3x3 king neighborhood (white - black)'
    try:
        def pawns_around(king_sq, color):
            if king_sq is None:
                return 0
            kr = chess.square_rank(king_sq)
            kf = chess.square_file(king_sq)
            cnt = 0
            for dr in (-1, 0, 1):
                for df in (-1, 0, 1):
                    if dr == 0 and df == 0:
                        continue
                    r = kr + dr
                    f = kf + df
                    if 0 <= r < 8 and 0 <= f < 8:
                        sq = r * 8 + f
                        pc = board.piece_at(sq)
                        if pc is not None and pc.piece_type == chess.PAWN and pc.color == color:
                            cnt += 1
            return cnt
        wk = board.king(chess.WHITE)
        bk = board.king(chess.BLACK)
        return float(pawns_around(wk, chess.WHITE) - pawns_around(bk, chess.BLACK))
    except Exception:
        return 0.0

