def feature(board: chess.Board) -> float:
    'Rook on open or semi-open file advantage: (White_open_rook_score - Black_open_rook_score), open file = no pawns, semi-open = only opponent pawns'
    try:
        def rook_score_for_color(color):
            score = 0.0
            for sq, p in board.piece_map().items():
                if p.piece_type != chess.ROOK or p.color != color:
                    continue
                f = chess.square_file(sq)
                pawns_on_file = [board.piece_at(chess.square(f, r)) for r in range(8)]
                pawn_colors = [pp.color for pp in pawns_on_file if pp is not None and pp.piece_type == chess.PAWN]
                if len(pawn_colors) == 0:
                    score += 1.0  # open file
                elif all(pc != color for pc in pawn_colors):
                    score += 0.6  # semi-open (only opponent pawns)
                else:
                    score += 0.0
                # extra bonus if rook is on seventh rank (rank 6 for white-rook advanced)
                rnk = chess.square_rank(sq)
                if (color == chess.WHITE and rnk == 6) or (color == chess.BLACK and rnk == 1):
                    score += 0.7
            return score
        return float(rook_score_for_color(chess.WHITE) - rook_score_for_color(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in average Manhattan distance of non-king pieces to their own king (white average minus black average)'
    try:
        pm = board.piece_map()
        def avg_dist(color):
            king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == color), None)
            if king_sq is None:
                return 0.0
            dists = []
            for sq, pc in pm.items():
                if pc.color == color and pc.piece_type != chess.KING:
                    dists.append(chess.square_distance(sq, king_sq))
            if not dists:
                return 0.0
            return float(sum(dists) / len(dists))
        return avg_dist(chess.WHITE) - avg_dist(chess.BLACK)
    except Exception:
        return 0.0

