def feature(board: chess.Board) -> float:
    'Mutual defense coordination: (number of mutually-defending piece pairs weighted by piece values) White - Black'
    values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:20000}
    coords = {chess.WHITE:0.0, chess.BLACK:0.0}
    pieces = board.piece_map()
    squares = list(pieces.keys())
    for i in range(len(squares)):
        a_sq = squares[i]
        pa = pieces[a_sq]
        for j in range(i+1, len(squares)):
            b_sq = squares[j]
            pb = pieces[b_sq]
            if pa.color != pb.color:
                continue
            c = pa.color
            # check mutual attack/defend
            if a_sq in board.attackers(c, b_sq) and b_sq in board.attackers(c, a_sq):
                # weight by average value of the two pieces
                w = 0.5 * (values.get(pa.piece_type,100) + values.get(pb.piece_type,100))
                coords[c] += w
    return float(coords[chess.WHITE] - coords[chess.BLACK])

def feature(board: chess.Board) -> float:
    'Minor piece centrality difference (White minus Black): sums centrality of knights and bishops by inverse distance to center'
    try:
        center_files = [3.5, 3.5]  # conceptual center at file 3.5, rank 3.5
        result_w = 0.0
        result_b = 0.0
        pm = board.piece_map()
        for sq, p in pm.items():
            if p.piece_type in (chess.KNIGHT, chess.BISHOP):
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                # Euclidean-ish centrality: smaller distance -> larger score
                df = (f - 3.5)
                dr = (r - 3.5)
                dist = (df*df + dr*dr) ** 0.5 + 0.001
                weight = 1.5 if p.piece_type == chess.KNIGHT else 1.0
                score = weight * (1.0 / dist)
                if p.color == chess.WHITE:
                    result_w += score
                else:
                    result_b += score
        return float(result_w - result_b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) of a passed-pawn danger score: advanced passed pawns that are far from opposing pieces score higher'
    piece_map = board.piece_map()
    def passed_pawns_score(color):
        score = 0.0
        opp = not color
        # gather opponent pawns positions for quick checks
        opp_pawn_squares = [sq for sq, p in piece_map.items() if p.piece_type == chess.PAWN and p.color == opp]
        opp_piece_squares = [sq for sq, p in piece_map.items() if p.color == opp and p.piece_type != chess.KING]
        for sq, p in piece_map.items():
            if p.piece_type != chess.PAWN or p.color != color:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            is_passed = True
            if color == chess.WHITE:
                for ff in range(max(0, f-1), min(7, f+1)+1):
                    for rr in range(r+1, 8):
                        check_sq = chess.square(ff, rr)
                        if check_sq in opp_pawn_squares:
                            is_passed = False
                            break
                    if not is_passed:
                        break
            else:
                for ff in range(max(0, f-1), min(7, f+1)+1):
                    for rr in range(0, r):
                        check_sq = chess.square(ff, rr)
                        if check_sq in opp_pawn_squares:
                            is_passed = False
                            break
                    if not is_passed:
                        break
            if not is_passed:
                continue
            # advancement: normalized 0..1
            advancement = (r / 7.0) if color == chess.WHITE else ((7 - r) / 7.0)
            # min distance to nearest opposing piece (excluding king); if none, set to 7
            if opp_piece_squares:
                min_dist = min(chess.square_distance(sq, o) for o in opp_piece_squares)
            else:
                min_dist = 7
            # score grows with advancement and with distance (farther from blockers better)
            pawn_score = advancement * (1.0 + (min_dist / 7.0))
            score += pawn_score
        return score
    return float(passed_pawns_score(chess.WHITE) - passed_pawns_score(chess.BLACK))

