def feature(board: chess.Board) -> float:
    'Difference in active-material ratio: (sum value of pieces on opponent half-board for white / white_total) - (same for black). Values in centipawns scaled between -1 and 1.'
    try:
        piece_values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        pm = board.piece_map()
        white_total = 0
        black_total = 0
        white_active = 0
        black_active = 0
        for sq,p in pm.items():
            val = piece_values.get(p.piece_type, 0)
            rank = chess.square_rank(sq)
            if p.color == chess.WHITE:
                white_total += val
                # active if on ranks 4-7 (opponent half) or on central files (c,d,e,f)
                if rank >= 4 or chess.square_file(sq) in (2,3,4,5):
                    white_active += val
            else:
                black_total += val
                if rank <= 3 or chess.square_file(sq) in (2,3,4,5):
                    black_active += val
        # avoid division by zero
        w_ratio = (white_active/white_total) if white_total>0 else 0.0
        b_ratio = (black_active/black_total) if black_total>0 else 0.0
        return float(w_ratio - b_ratio)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net attack pressure on squares adjacent to each king (white minus black)'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.BLACK), None)
        def adjacent_squares(sq):
            if sq is None:
                return []
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            res = []
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    nf = f + df
                    nr = r + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        res.append(chess.square(nf, nr))
            return res
        white_pressure = 0
        black_pressure = 0
        for adj in adjacent_squares(white_king_sq):
            white_pressure += len(board.attackers(chess.BLACK, adj))
        for adj in adjacent_squares(black_king_sq):
            black_pressure += len(board.attackers(chess.WHITE, adj))
        return float(white_pressure - black_pressure)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net advantage in overwhelming attacks on squares adjacent to the king: sum(max(0, attackers - defenders)) over adjacent squares, White - Black'
    try:
        def adj_overwhelm(king_color, attacker_color):
            # sum over squares adjacent to king of positive surplus of attackers over defenders
            ks = None
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == king_color:
                    ks = sq
                    break
            if ks is None:
                return 0
            total = 0
            for sq in chess.SQUARES:
                if chess.square_distance(sq, ks) <= 1 and sq != ks:
                    atk = len(board.attackers(attacker_color, sq))
                    defn = len(board.attackers(king_color, sq))
                    surplus = atk - defn
                    if surplus > 0:
                        total += surplus
            return total
        w_over = adj_overwhelm(chess.BLACK, chess.WHITE)  # white attacking black king
        b_over = adj_overwhelm(chess.WHITE, chess.BLACK)  # black attacking white king
        return float(w_over - b_over)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) in weighted central pawn presence: pawns on files c,d,e,f weighted by advancement toward center (advanced = more weight)'
    piece_map = board.piece_map()
    central_files = {2, 3, 4, 5}  # c,d,e,f -> files 2..5
    white_score = 0.0
    black_score = 0.0
    for sq, p in piece_map.items():
        if p.piece_type != chess.PAWN:
            continue
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if f not in central_files:
            continue
        if p.color == chess.WHITE:
            weight = (r / 7.0)  # more advanced pawns count more
            white_score += weight
        else:
            weight = ((7 - r) / 7.0)
            black_score += weight
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Difference (Black_exposed_ratio - White_exposed_ratio): fraction of non-pawn pieces attacked by enemy; positive means Black pieces are more exposed (favors White)'
