def feature(board: chess.Board) -> float:
    'White minus Black: bishop-pair advantage (1 if side has two bishops) and extra if rook on enemy back/7th rank presence'
    white_bp = 0.0
    black_bp = 0.0
    pm = board.piece_map()
    # bishop pair
    wb = sum(1 for p in pm.values() if p.piece_type == chess.BISHOP and p.color == chess.WHITE)
    bb = sum(1 for p in pm.values() if p.piece_type == chess.BISHOP and p.color == chess.BLACK)
    if wb >= 2:
        white_bp += 1.0
    if bb >= 2:
        black_bp += 1.0
    # rooks on opponent back/7th rank (strong pressure)
    for sq, p in pm.items():
        if p.piece_type == chess.ROOK:
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                # White rook on rank 6 (7th for White) or rank 7 (back rank of Black)
                if r >= 6:
                    white_bp += 0.5
            else:
                if r <= 1:
                    black_bp += 0.5
    return float(white_bp - black_bp)

def feature(board: chess.Board) -> float:
    'Difference in king proximity to the center (black_dist_min - white_dist_min). Smaller means king is more centralized.'
    try:
        centers = [chess.parse_square(s) for s in ('d4','e4','d5','e5')]
        pm = board.piece_map()
        def min_center_dist(king_color):
            king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == king_color), None)
            if king_sq is None:
                return 0.0
            d = min(chess.square_distance(king_sq, c) for c in centers)
            return float(d)
        w = min_center_dist(chess.WHITE)
        b = min_center_dist(chess.BLACK)
        return float(b - w)
    except Exception:
        return 0.0

