def feature(board: chess.Board) -> float:
    'Rook+Queen sliding mobility difference: (white attacked squares by rooks/queens - black) normalized by 64'
    try:
        pm = board.piece_map()
        occ = {sq: True for sq in range(64) if sq in pm}
        def sliding_attacks_from(sq, deltas):
            attacks = set()
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            for df, dr in deltas:
                cf, cr = f + df, r + dr
                while 0 <= cf < 8 and 0 <= cr < 8:
                    tsq = chess.square(cf, cr)
                    attacks.add(tsq)
                    if tsq in occ:
                        break
                    cf += df; cr += dr
            return attacks
        rook_dirs = [(1,0),(-1,0),(0,1),(0,-1)]
        bishop_dirs = [(1,1),(1,-1),(-1,1),(-1,-1)]
        w_att = set(); b_att = set()
        for sq, pc in pm.items():
            if pc.piece_type == chess.ROOK or pc.piece_type == chess.QUEEN:
                wset = sliding_attacks_from(sq, rook_dirs)
                if pc.color == chess.WHITE:
                    w_att.update(wset)
                else:
                    b_att.update(wset)
            if pc.piece_type == chess.BISHOP or pc.piece_type == chess.QUEEN:
                bset = sliding_attacks_from(sq, bishop_dirs)
                if pc.color == chess.WHITE:
                    w_att.update(bset)
                else:
                    b_att.update(bset)
        # But we want rook+queen mobility specifically: approximate by taking rook_dirs from rooks/queens only
        # restrict to rook-like squares
        def rook_like_attacks(color):
            s = set()
            for sq, pc in pm.items():
                if pc.color == color and (pc.piece_type == chess.ROOK or pc.piece_type == chess.QUEEN):
                    s.update(sliding_attacks_from(sq, rook_dirs))
            return s
        w_rq = rook_like_attacks(chess.WHITE)
        b_rq = rook_like_attacks(chess.BLACK)
        return float(len(w_rq) - len(b_rq)) / 64.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Local material imbalance around kings: (material of White pieces within Chebyshev distance 3 of Black king) - (material of Black pieces within distance 3 of White king), normalized by 1000'
    vals = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    pm = board.piece_map()
    def king_sq(color):
        for sq,p in pm.items():
            if p.piece_type==chess.KING and p.color==color:
                return sq
        return None
    def material_near(king_sq, by_color):
        if king_sq is None:
            return 0
        total = 0
        kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
        for sq,p in pm.items():
            if p.color==by_color:
                df = abs(chess.square_file(sq)-kf)
                dr = abs(chess.square_rank(sq)-kr)
                if max(df,dr) <= 3:
                    total += vals.get(p.piece_type,0)
        return total
    w_near_bking = material_near(king_sq(chess.BLACK), chess.WHITE)
    b_near_wking = material_near(king_sq(chess.WHITE), chess.BLACK)
    return float(w_near_bking - b_near_wking) / 1000.0

def feature(board: chess.Board) -> float:
    'Coordination metric: number of squares attacked by >=2 pieces of a side, weighted by centrality (White minus Black)'
    import chess
    try:
        center_files = [3.5, 3.5]  # center at (3.5,3.5)
        def centrality_weight(sq):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            # smaller distance to center -> bigger weight
            dist = ((f - 3.5) ** 2 + (r - 3.5) ** 2) ** 0.5
            return 1.0 / (1.0 + dist)
        w_score = 0.0
        b_score = 0.0
        for sq in range(64):
            aw = board.attackers(chess.WHITE, sq)
            ab = board.attackers(chess.BLACK, sq)
            cw = centrality_weight(sq)
            if len(aw) >= 2:
                w_score += cw
            if len(ab) >= 2:
                b_score += cw
        return float(w_score - b_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in queen-rook proximity coordination: sum over queen-rook pairs of 1/(1+manhattan_distance) (White - Black)'
    try:
        pm = board.piece_map()
        w_qs = []
        b_qs = []
        w_rs = []
        b_rs = []
        for s, p in pm.items():
            if p.piece_type == chess.QUEEN:
                if p.color == chess.WHITE:
                    w_qs.append(s)
                else:
                    b_qs.append(s)
            if p.piece_type == chess.ROOK:
                if p.color == chess.WHITE:
                    w_rs.append(s)
                else:
                    b_rs.append(s)
        def coord_sum(queens, rooks):
            total = 0.0
            for q in queens:
                for r in rooks:
                    d = chess.square_distance(q, r)
                    total += 1.0 / (1.0 + d)
            return total
        w_sum = coord_sum(w_qs, w_rs)
        b_sum = coord_sum(b_qs, b_rs)
        return float(w_sum - b_sum)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Value of advanced enemy pieces attacked by you: sum(piece values in pawn units) White - Black'
    import chess
    try:
        values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900}
        pm = board.piece_map()
        w_sum = 0.0
        b_sum = 0.0
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                continue
            r = chess.square_rank(sq)
            if p.color == chess.BLACK and r >= 4:
                # black piece advanced into white half; is it attacked by white?
                if len(board.attackers(chess.WHITE, sq)) > 0:
                    w_sum += values.get(p.piece_type, 0) / 100.0
            if p.color == chess.WHITE and r <= 3:
                # white piece advanced into black half; attacked by black?
                if len(board.attackers(chess.BLACK, sq)) > 0:
                    b_sum += values.get(p.piece_type, 0) / 100.0
        return float(w_sum - b_sum)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of opponent non-pawn pieces located within Manhattan distance <=3 of the king (White pressure - Black pressure)'
    pm = board.piece_map()
    white_king = None
    black_king = None
    for sq, pc in pm.items():
        if pc.piece_type == chess.KING:
            if pc.color == chess.WHITE:
                white_king = sq
            else:
                black_king = sq
    def nearby_attackers(king_sq, opponent_color):
        if king_sq is None:
            return 0
        cnt = 0
        for sq, pc in pm.items():
            if pc.color == opponent_color and pc.piece_type != chess.PAWN:
