                    cnt += 1
        return cnt
    wpress = nearby_attackers(white_king, chess.BLACK)
    bpress = nearby_attackers(black_king, chess.WHITE)
    return float(wpress - bpress)

def feature(board: chess.Board) -> float:
    'Pawn shield density in front of each king: weighted count of friendly pawns on the three files ahead (closer pawns count more), returned White minus Black'
    weights = {0: 1.0, 1: 0.6, 2: 0.3}  # distance in ranks from king's back rank
    def find_king(color):
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING and p.color == color:
                return sq
        return None
    def shield_density(color):
        sq = find_king(color)
        if sq is None:
            return 0.0
        kf = chess.square_file(sq)
        kr = chess.square_rank(sq)
        total = 0.0
        if color == chess.WHITE:
            # ranks in front: 1,2,3 (ranks 1..3)
            for dist in range(0, 3):
                r = 1 + dist
                for f in range(max(0, kf - 1), min(7, kf + 1) + 1):
                    s = chess.square(f, r)
                    p = board.piece_at(s)
                    if p and p.piece_type == chess.PAWN and p.color == color:
                        total += weights.get(dist, 0.0)
        else:
            # black: ranks 6,5,4
            for dist in range(0, 3):
                r = 6 - dist
                for f in range(max(0, kf - 1), min(7, kf + 1) + 1):
                    s = chess.square(f, r)
                    p = board.piece_at(s)
                    if p and p.piece_type == chess.PAWN and p.color == color:
                        total += weights.get(dist, 0.0)
        return total
    w = shield_density(chess.WHITE)
    b = shield_density(chess.BLACK)
    return float(w - b)

