def feature(board: chess.Board) -> float:
    'Number of pawnless files among the king file and its adjacent files (white_count - black_count)'
    try:
        piece_map = board.piece_map()
        # helper to get pawnless count around a king
        def pawnless_adjacent(king_color):
            king_sq = next((sq for sq, p in piece_map.items() if p.piece_type == chess.KING and p.color == king_color), None)
            if king_sq is None:
                return 0.0
            f = chess.square_file(king_sq)
            count = 0
            for nf in (f-1, f, f+1):
                if 0 <= nf <= 7:
                    has_pawn = False
                    for sq, p in piece_map.items():
                        if p.piece_type == chess.PAWN and chess.square_file(sq) == nf:
                            has_pawn = True
                            break
                    if not has_pawn:
                        count += 1
            return float(count)
        return pawnless_adjacent(chess.WHITE) - pawnless_adjacent(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in king pawn-shelter: number of friendly pawns within Manhattan distance <=2 of each king (white - black), normalized'
    try:
        pm = board.piece_map()
        white_ksq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_ksq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        white_shelter = 0
        black_shelter = 0
        for sq, p in pm.items():
            if p.piece_type != chess.PAWN:
                continue
            d = 0
            if white_ksq is not None and p.color == chess.WHITE:
                d = chess.square_distance(sq, white_ksq)
                if d <= 2:
                    white_shelter += 1
            if black_ksq is not None and p.color == chess.BLACK:
                d = chess.square_distance(sq, black_ksq)
                if d <= 2:
                    black_shelter += 1
        return float((white_shelter - black_shelter) / 8.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Weighted count of hanging pieces: sum over pieces(attacker_count - defender_count >0 ? piece_value*(attackers-defenders) ), White minus Black normalized'
    values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    pm = board.piece_map()
    white_score = 0.0
    black_score = 0.0
    total_mat = 0.0
    for sq, p in pm.items():
        if p.piece_type == chess.KING:
            continue
        total_mat += values.get(p.piece_type,0.0)
        attackers = len(board.attackers(not p.color, sq))
        defenders = len(board.attackers(p.color, sq))
        diff = attackers - defenders
        if diff > 0:
            w = values.get(p.piece_type, 0.0) * float(diff)
            if p.color == chess.WHITE:
                white_score += w
            else:
                black_score += w
    denom = total_mat if total_mat > 0 else 1.0
    return float((white_score - black_score) / denom)

def feature(board: chess.Board) -> float:
    'Queen tropism and proximity to enemy king: (White_score - Black_score) where score = sum(inverse distance to enemy king + attacks to squares around that king)'
    try:
        def queen_score(own_color):
            opp = not own_color
            k = board.king(opp)
            if k is None:
                return 0.0
            king_adjacent = [k] + [chess.square_file(k) and sq for sq in []]  # placeholder to make no error
            # collect adjacent squares to king (including diagonals)
            adj_sqs = []
            kr = chess.square_rank(k)
            kf = chess.square_file(k)
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    f = kf + df
                    r = kr + dr
                    if 0 <= f <= 7 and 0 <= r <= 7:
                        adj_sqs.append(chess.square(f, r))
            total = 0.0
            for sq, p in board.piece_map().items():
                if p.piece_type != chess.QUEEN or p.color != own_color:
                    continue
                # inverse distance to enemy king
                dist = chess.square_distance(sq, k)
                if dist == 0:
                    inv = 1.5
                else:
                    inv = 1.0 / dist
                # number of attacked squares in king adjacency
                attacks_near = sum(1 for s in adj_sqs if board.is_attacked_by(own_color, s))
                total += inv + 0.4 * attacks_near
            return total
        return float(queen_score(chess.WHITE) - queen_score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in average pairwise Chebyshev distance between non-king pieces (Black avg - White avg); positive means White pieces are more clustered'
    try:
        pm = board.piece_map()
        white_sq = [sq for sq, p in pm.items() if p.piece_type != chess.KING and p.color == chess.WHITE]
        black_sq = [sq for sq, p in pm.items() if p.piece_type != chess.KING and p.color == chess.BLACK]
        def avg_pairwise(sqs):
            n = len(sqs)
            if n <= 1:
                return 0.0
            total = 0.0
            pairs = 0
            for i in range(n):
                for j in range(i+1, n):
                    total += chess.square_distance(sqs[i], sqs[j])
                    pairs += 1
            return total / pairs if pairs else 0.0
        wa = avg_pairwise(white_sq)
        ba = avg_pairwise(black_sq)
        return float(ba - wa)
    except Exception:
        return 0.0

