def feature(board: chess.Board) -> float:
    'Piece coordination: normalized count of friendly piece-to-friendly-piece attacks (defenses/connections) difference (White - Black)'
    try:
        piece_map = board.piece_map()
        def coordination(color):
            squares = [sq for sq, p in piece_map.items() if p.color == color]
            n = len(squares)
            if n <= 1:
                return 0.0
            conn = 0
            for a in squares:
                for b in squares:
                    if a == b:
                        continue
                    # does piece on 'a' attack square 'b'?
                    if a in board.attackers(color, b):
                        conn += 1
            # normalize by number of ordered pairs to keep feature scale roughly [-1,1] bounds
            return conn / max(1, n*(n-1))
        return float(coordination(chess.WHITE) - coordination(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Space/control in the advanced half: number of squares in the opponent half attacked by each side (White - Black), normalized by 16'
    white_control = 0
    black_control = 0
    # For White, opponent half is ranks 4..7 (0-based ranks 4..7); for Black, opponent half is ranks 0..3
    for r in range(4, 8):
        for f in range(0, 8):
            sqname = chr(ord('a') + f) + str(r + 1)
            try:
                sq = chess.parse_square(sqname)
            except Exception:
                continue
            if board.is_attacked_by(chess.WHITE, sq):
                white_control += 1
            if board.is_attacked_by(chess.BLACK, sq):
                black_control += 1
    # normalization by 16 (approx number of squares per half to keep values moderate)
    return float((white_control - black_control) / 16.0)

