def feature(board: chess.Board) -> float:
    'Immediate capture value available difference: sum of captured-piece centipawn values for White - Black over legal captures'
    try:
        VALUES = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0, chess.KING:0.0}
        white_cap = 0.0
        black_cap = 0.0
        for mv in board.legal_moves:
            to_sq = getattr(mv, 'to_square', None)
            from_sq = getattr(mv, 'from_square', None)
            if to_sq is None or from_sq is None:
                continue
            target = board.piece_at(to_sq)
            mover = board.piece_at(from_sq)
            if target is None or mover is None:
                # ignore en-passant or ambiguous cases where destination appears empty
                continue
            if target.color == mover.color:
                continue
            val = VALUES.get(target.piece_type, 0.0)
            if mover.color == chess.WHITE:
                white_cap += val
            else:
                black_cap += val
        return float(white_cap - black_cap)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in longest pawn-support chain length (white_longest_chain - black_longest_chain)'
    try:
        pieces = board.piece_map()
        white_pawns = {sq for sq,pc in pieces.items() if pc.piece_type==chess.PAWN and pc.color==chess.WHITE}
        black_pawns = {sq for sq,pc in pieces.items() if pc.piece_type==chess.PAWN and pc.color==chess.BLACK}
        def longest_chain(pawns, color_is_white):
            cache = {}
            def supports(sq):
                if sq in cache:
                    return cache[sq]
                f = chess.square_file(sq); r = chess.square_rank(sq)
                # supporting pawn for white sits one rank behind (r-1) at adjacent files
                candidates = []
                if color_is_white:
                    behind_rank = r - 1
                else:
                    behind_rank = r + 1
                for df in (-1, 1):
                    bf = f + df
                    if 0 <= bf <= 7 and 0 <= behind_rank <= 7:
                        b_sq = chess.square(bf, behind_rank)
                        if b_sq in pawns:
                            candidates.append(b_sq)
                if not candidates:
                    cache[sq] = 1
                    return 1
                best = 1 + max(supports(c) for c in candidates)
                cache[sq] = best
                return best
            best_len = 0
            for s in pawns:
                try:
                    best_len = max(best_len, supports(s))
                except Exception:
                    continue
            return best_len
        w_chain = longest_chain(white_pawns, True)
        b_chain = longest_chain(black_pawns, False)
        return float(w_chain - b_chain)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of immediate mate-in-one threats available to each side (Black mates - White mates). Positive means Black has more immediate mating moves.'
    try:
        mate_black = 0
        mate_white = 0
        # helper to count mates for a given side (create a board copy and set turn)
        try:
            bcopy = board.copy()
        except Exception:
            # fallback: try shallow copy via FEN
            try:
                bcopy = chess.Board(board.fen())
            except Exception:
                return 0.0
        for color in (chess.WHITE, chess.BLACK):
            try:
                b2 = bcopy.copy()
            except Exception:
                try:
                    b2 = chess.Board(bcopy.fen())
                except Exception:
                    continue
            b2.turn = color
            for mv in list(b2.legal_moves):
                try:
                    b3 = b2.copy()
                except Exception:
                    try:
                        b3 = chess.Board(b2.fen())
                    except Exception:
                        continue
                try:
                    b3.push(mv)
                except Exception:
                    continue
                if b3.is_checkmate():
                    if color == chess.WHITE:
                        mate_white += 1
                    else:
                        mate_black += 1
        return float(mate_black - mate_white)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Central pawn presence and pawn-tension on central squares (d4,e4,d5,e5): (White net) + 0.5*(pawn attacks net)'
    try:
        centers = [chess.parse_square(s) for s in ('d4', 'e4', 'd5', 'e5')]
        pieces = board.piece_map()
        white_center_pawns = 0
        black_center_pawns = 0
        white_pawn_attacks = 0
        black_pawn_attacks = 0
        for c in centers:
            p = board.piece_at(c)
            if p is not None and p.piece_type == chess.PAWN:
                if p.color == chess.WHITE:
                    white_center_pawns += 1
                else:
                    black_center_pawns += 1
            # count pawn attackers specifically
            attackers = board.attackers(chess.WHITE, c)
            for a in attackers:
                pa = board.piece_at(a)
                if pa is not None and pa.piece_type == chess.PAWN:
                    white_pawn_attacks += 1
            attackers = board.attackers(chess.BLACK, c)
            for a in attackers:
                pa = board.piece_at(a)
                if pa is not None and pa.piece_type == chess.PAWN:
                    black_pawn_attacks += 1
        return float((white_center_pawns - black_center_pawns) + 0.5 * (white_pawn_attacks - black_pawn_attacks))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Capture swing potential: (white - black) sum over legal captures of positive material gains (captured value - capturer value, clipped at 0).'
    try:
        values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        w = b = 0.0
        # iterate legal moves and consider obvious captures where a piece currently exists on destination
        for move in board.legal_moves:
            to_sq = move.to_square
            capt = board.piece_at(to_sq)
            if capt is None:
                # try to handle en passant heuristically: the captured pawn would be behind to_sq for white captures by pawn
                try:
                    moving = board.piece_at(move.from_square)
                    if moving and moving.piece_type == chess.PAWN and abs(chess.square_rank(move.from_square) - chess.square_rank(move.to_square)) == 1:
                        # unlikely reliable; skip if no direct capture
                        continue
                    else:
                        continue
                except Exception:
                    continue
            mover = board.piece_at(move.from_square)
            if mover is None:
                continue
            gain = values.get(capt.piece_type, 0.0) - values.get(mover.piece_type, 0.0)
            if gain > 0.0:
                if mover.color == chess.WHITE:
                    w += gain
                else:
                    b += gain
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Concentration of major pieces (rooks and queens) in the opponent half: (white_prop - black_prop), where prop is fraction on opponent half'
    try:
        pm = board.piece_map()
        def prop_major_in_enemy_half(color):
            majors = []
            for sq, p in pm.items():
                if p.color == color and p.piece_type in (chess.ROOK, chess.QUEEN):
                    majors.append(sq)
            if not majors:
                return 0.0
            count_in_enemy = 0
            for sq in majors:
                rk = chess.square_rank(sq)  # 0..7, rank 0 = rank1 for white
                if color == chess.WHITE:
                    # enemy half for white: ranks 4..7
                    if rk >= 4:
                        count_in_enemy += 1
                else:
                    # enemy half for black: ranks 0..3
                    if rk <= 3:
                        count_in_enemy += 1
            return float(count_in_enemy) / float(len(majors))
        return prop_major_in_enemy_half(chess.WHITE) - prop_major_in_enemy_half(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in minimum king-to-friendly-pawn distance (black_min - white_min); smaller distance = better shield'
    try:
        pm = board.piece_map()
        def min_dist_to_pawn(king_color):
            ks = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == king_color), None)
            if ks is None:
                return 8.0
            dmin = 8
            for sq, p in pm.items():
                if p.piece_type == chess.PAWN and p.color == king_color:
                    d = chess.square_distance(ks, sq)
                    if d < dmin:
                        dmin = d
            return float(dmin if dmin != 8 else 8.0)
        return float(min_dist_to_pawn(chess.BLACK) - min_dist_to_pawn(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Major-piece safety: difference in number of rooks/queens that have at least one friendly defender (white - black)'
    piece_map = board.piece_map()
    white_safe = 0
    black_safe = 0
    for sq, p in piece_map.items():
        if p.piece_type in (chess.ROOK, chess.QUEEN):
            defenders = board.attackers(p.color, sq)
            # defenders is a set of squares; if non-empty the piece has at least one defender
            if len(defenders) > 0:
                if p.color == chess.WHITE:
                    white_safe += 1
                else:
                    black_safe += 1
    return float(white_safe - black_safe)

def feature(board: chess.Board) -> float:
    'Net piece coordination: weighted fraction of material value that is defended (White - Black), normalized to [-1,1]'
    try:
        piece_map = board.piece_map()
        values = {chess.PAWN:100, chess.KNIGHT:300, chess.BISHOP:300, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        def defended_value(color):
            total = 0
            defended = 0
            for sq, p in piece_map.items():
                if p.color != color:
                    continue
                v = values.get(p.piece_type, 0)
                total += v
                # defended if there is at least one friendly attacker to that square (excluding itself)
                if len(board.attackers(color, sq)) > 0:
                    defended += v
            return defended, total
        dw, tw = defended_value(chess.WHITE)
        db, tb = defended_value(chess.BLACK)
        # avoid division by zero
        frac_w = (dw / tw) if tw > 0 else 0.0
        frac_b = (db / tb) if tb > 0 else 0.0
        return frac_w - frac_b
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
