def feature(board: chess.Board) -> float:
    'White minus Black: difference in Chebyshev distance from the side\'s king to its most advanced passed pawn\'s promotion square (smaller is better for that side). Returns (black_dist - white_dist).'
    try:
        pieces = board.piece_map()
    except Exception:
        return 0.0
    pawns = [(sq, p) for sq, p in pieces.items() if p.piece_type == chess.PAWN]
    kings = {p.color: sq for sq, p in pieces.items() if p.piece_type == chess.KING}
    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            for opp_sq, opp_piece in pawns:
                if opp_piece.color == chess.BLACK:
                    if abs(chess.square_file(opp_sq) - f) <= 1 and chess.square_rank(opp_sq) >= r:
                        return False
            return True
        else:
            for opp_sq, opp_piece in pawns:
                if opp_piece.color == chess.WHITE:
                    if abs(chess.square_file(opp_sq) - f) <= 1 and chess.square_rank(opp_sq) <= r:
                        return False
            return True
    white_passed = None
    black_passed = None
    for sq, p in pawns:
        if not is_passed(sq, p.color):
            continue
        if p.color == chess.WHITE:
            if white_passed is None or chess.square_rank(sq) > chess.square_rank(white_passed):
                white_passed = sq
        else:
            if black_passed is None or chess.square_rank(sq) < chess.square_rank(black_passed):
                black_passed = sq
    def cheb_dist_sq(a, b):
        if a is None or b is None:
            return 100.0
        af = chess.square_file(a); ar = chess.square_rank(a)
        bf = chess.square_file(b); br = chess.square_rank(b)
        return float(max(abs(af - bf), abs(ar - br)))
    d_w = 100.0
    d_b = 100.0
    if white_passed is not None:
        promo_sq = chess.square(chess.square_file(white_passed), 7) if hasattr(chess, 'square') else chess.parse_square(chess.square_name(white_passed)[0] + '8')
        # safer compute promo coords
        pf = chess.square_file(white_passed); pr = 7
        promo_coords = (pf, pr)
        wk = kings.get(chess.WHITE)
        if wk is not None:
            wf = chess.square_file(wk); wr = chess.square_rank(wk)
            d_w = float(max(abs(wf - promo_coords[0]), abs(wr - promo_coords[1])))
    if black_passed is not None:
        pf = chess.square_file(black_passed); pr = 0
        promo_coords = (pf, pr)
        bk = kings.get(chess.BLACK)
        if bk is not None:
            bf = chess.square_file(bk); br = chess.square_rank(bk)
            d_b = float(max(abs(bf - promo_coords[0]), abs(br - promo_coords[1])))
    return float(d_b - d_w)

def feature(board: chess.Board) -> float:
    'Fraction of the up-to-8 squares adjacent to the white king that are attacked by Black (0..1)'
    try:
        pm = board.piece_map()
    except Exception:
        return 0.0
    wk_sq = None
    for sq, p in pm.items():
        if p.piece_type == chess.KING and p.color == chess.WHITE:
            wk_sq = sq
            break
    if wk_sq is None:
        return 0.0
    wf = chess.square_file(wk_sq)
    wr = chess.square_rank(wk_sq)
    adj_total = 0
    adj_attacked = 0
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            if df == 0 and dr == 0:
                continue
            nf = wf + df
            nr = wr + dr
            if 0 <= nf <= 7 and 0 <= nr <= 7:
                adj_total += 1
                sq = nr * 8 + nf
                try:
                    if board.is_attacked_by(chess.BLACK, sq):
                        adj_attacked += 1
                except Exception:
                    pass
    if adj_total == 0:
        return 0.0
    return float(adj_attacked) / float(adj_total)

def feature(board: chess.Board) -> float:
    'Average closeness of non-king pieces to the board center (3.5,3.5): (Black_avg - White_avg) where smaller distance is better for activity'
    try:
        pm = board.piece_map()
        def avg_dist(color):
            s = 0.0
            c = 0
            for sq, p in pm.items():
                if p.color != color or p.piece_type == chess.KING:
                    continue
                fx = chess.square_file(sq)
                ry = chess.square_rank(sq)
                # Euclidean distance to center (3.5,3.5)
                d = ((fx - 3.5)**2 + (ry - 3.5)**2)**0.5
                s += d
                c += 1
            return s / c if c > 0 else 8.0
        w_avg = avg_dist(chess.WHITE)
        b_avg = avg_dist(chess.BLACK)
        # return Black_avg - White_avg (positive means Black pieces further from center -> worse for Black)
        return float(b_avg - w_avg)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Piece coordination index: normalized number of close same-color piece pairs (distance<=2) difference (white - black)'
    pm = board.piece_map()
    def coord(color):
        sqs = [sq for sq, p in pm.items() if p.color == color]
        n = len(sqs)
        if n < 2:
            return 0.0
        pairs = 0
        for i in range(n):
            for j in range(i+1, n):
                if chess.square_distance(sqs[i], sqs[j]) <= 2:
                    pairs += 1
        # normalize by maximum possible pairs
        max_pairs = n * (n - 1) / 2
        return pairs / (max_pairs + 1e-6)
    try:
        return float(coord(chess.WHITE) - coord(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Average distance of non-pawn pieces to own king difference: (white_avg_dist - black_avg_dist); higher = pieces further from defended king'
    import chess, math
    try:
        def avg_dist_for(color):
            k = board.king(color)
            if k is None:
                return 8.0
            dists = []
            for sq, p in board.piece_map().items():
                if p.color == color and p.piece_type != chess.PAWN and p.piece_type != chess.KING:
                    dists.append(chess.square_distance(sq, k))
            if not dists:
                return 8.0
            return float(sum(dists)/len(dists))
        return float(avg_dist_for(chess.WHITE) - avg_dist_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Centralization score: sum over non-pawn pieces of (4 - min_distance_to_center) for white minus black (higher => more centralized white pieces)'
    pm = board.piece_map()
    center_sqs = [chess.parse_square(s) for s in ('d4', 'e4', 'd5', 'e5')]
    def piece_central_score(sq):
        dmin = min(chess.square_distance(sq, c) for c in center_sqs)
        return max(0, 4 - dmin)
    white_score = 0.0
    black_score = 0.0
    for sq, p in pm.items():
        if p.piece_type == chess.PAWN:
            continue
        score = piece_central_score(sq)
        if p.color == chess.WHITE:
            white_score += score
        else:
            black_score += score
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Promotion threat difference: weighted count of pawns on the seventh rank (white - black), accounting for defenders and nearby enemy king'
    try:
        pm = board.piece_map()
        def promo_score_for_color(color):
            score = 0.0
            target_rank = 6 if color == chess.WHITE else 1
            forward = 1 if color == chess.WHITE else -1
            enemy_color = not color
            for f in range(8):
                sq = target_rank * 8 + f
                p = board.piece_at(sq)
                if p is None or p.piece_type != chess.PAWN or p.color != color:
                    continue
                s = 1.0
                # defended?
                defs = board.attackers(color, sq)
                if defs:
                    s += 0.5
                # promotion square occupied?
                promo_sq = (target_rank + forward) * 8 + f if 0 <= (target_rank + forward) <= 7 else None
                if promo_sq is not None:
                    occ = board.piece_at(promo_sq)
                    if occ is not None and occ.color == enemy_color:
                        s -= 0.4
                # distance of enemy king to this pawn reduces chance slightly
                # find enemy king
                ek = None
                for sqk, pk in pm.items():
                    if pk.piece_type == chess.KING and pk.color == enemy_color:
                        ek = sqk
                        break
                if ek is not None:
                    d = chess.square_distance(sq, ek)
                    s -= 0.05 * (d / 8.0)
                score += max(0.0, s)
            return score
        return float(promo_score_for_color(chess.WHITE) - promo_score_for_color(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn isolation index: fraction of isolated pawns (no friendly pawn on adjacent files) white minus black'
    try:
        pieces = board.piece_map()
        white_pawns = [sq for sq, p in pieces.items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        black_pawns = [sq for sq, p in pieces.items() if p.piece_type == chess.PAWN and p.color == chess.BLACK]
        def isolated_fraction(pawns, color):
            if not pawns:
                return 0.0
            pawn_files = {}
            for sq in pawns:
                f = chess.square_file(sq)
                pawn_files.setdefault(f, []).append(sq)
            isolated = 0
            for sq in pawns:
                f = chess.square_file(sq)
                if (f-1) not in pawn_files and (f+1) not in pawn_files:
                    isolated += 1
            return isolated / float(len(pawns))
        return float(isolated_fraction(white_pawns, chess.WHITE) - isolated_fraction(black_pawns, chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Opposite-colored bishops indicator: 1.0 if both sides have only bishops on a single color and those colors are opposite, else 0.0'
    try:
        pm = board.piece_map()
        def bishop_color_counts(color):
            counts = {0:0, 1:0}
            for sq, p in pm.items():
                if p.piece_type == chess.BISHOP and p.color == color:
                    sq_color = (chess.square_file(sq) + chess.square_rank(sq)) & 1
                    counts[sq_color] += 1
            return counts
        w_counts = bishop_color_counts(chess.WHITE)
        b_counts = bishop_color_counts(chess.BLACK)
        # whites bishops all on one color and blacks all on one color and colors are different
        w_single = (w_counts[0] == 0) != (w_counts[1] == 0)  # True if only one side nonzero
        b_single = (b_counts[0] == 0) != (b_counts[1] == 0)
        if w_single and b_single:
            w_color = 0 if w_counts[0] > 0 else 1
            b_color = 0 if b_counts[0] > 0 else 1
            return 1.0 if w_color != b_color else 0.0
        return 0.0
    except Exception:
        return 0.0

