def feature(board: chess.Board) -> float:
    'Bishop pair bonus minus bad-bishop penalty (white minus black). Bad bishop penalty increases with number of same-colored pawns on the bishop color.'
    try:
        pm = board.piece_map()
        white_bishops = []
        black_bishops = []
        white_pawns = [sq for sq, p in pm.items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        black_pawns = [sq for sq, p in pm.items() if p.piece_type == chess.PAWN and p.color == chess.BLACK]
        white_pawn_colors = {}
        black_pawn_colors = {}
        for sq in white_pawns:
            col = (chess.square_file(sq) + chess.square_rank(sq)) & 1
            white_pawn_colors[col] = white_pawn_colors.get(col, 0) + 1
        for sq in black_pawns:
            col = (chess.square_file(sq) + chess.square_rank(sq)) & 1
            black_pawn_colors[col] = black_pawn_colors.get(col, 0) + 1
        for sq, p in pm.items():
            if p.piece_type == chess.BISHOP:
                if p.color == chess.WHITE:
                    white_bishops.append(sq)
                else:
                    black_bishops.append(sq)
        def score_bish(bish_list, pawn_colors):
            score = 0.0
            if len(bish_list) >= 2:
                score += 0.5
            for sq in bish_list:
                col = (chess.square_file(sq) + chess.square_rank(sq)) & 1
                # penalty proportional to number of own pawns on same color squares
                score -= 0.1 * pawn_colors.get(col, 0)
            return score
        wscore = score_bish(white_bishops, white_pawn_colors)
        bscore = score_bish(black_bishops, black_pawn_colors)
        return float(wscore - bscore)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Queen proximity + pin risk difference: (black_threat_score - white_threat_score) where threat = (8 - min_dist_to_queen) + 2*pin_count'
    import chess
    try:
        def threat_score_against(color):
            # how threatened is the king of color by enemy queens/lines
            king_sq = board.king(color)
            if king_sq is None:
                return 0.0
            enemy = not color
            min_dist = 8
            for sq, p in board.piece_map().items():
                if p.color == enemy and p.piece_type == chess.QUEEN:
                    d = chess.square_distance(sq, king_sq)
                    if d < min_dist:
                        min_dist = d
            # compute simple pin count: sliding enemy piece with exactly one piece between it and king on same line
            pin_count = 0
            for sq, p in board.piece_map().items():
                if p.color == enemy and p.piece_type in (chess.ROOK, chess.BISHOP, chess.QUEEN):
                    # check collinearity
                    kr = chess.square_rank(king_sq); kf = chess.square_file(king_sq)
                    pr = chess.square_rank(sq); pf = chess.square_file(sq)
                    dr = pr - kr; df = pf - kf
                    if dr == 0:
                        step_r, step_f = 0, 1 if df < 0 else -1
                        between = []
                        for f in range(pf+step_f, kf, step_f):
                            between.append(chess.square(f, kr))
                    elif df == 0:
                        step_r, step_f = 1 if dr < 0 else -1, 0
                        between = []
                        for r in range(pr+step_r, kr, step_r):
                            between.append(chess.square(pf, r))
                    elif abs(dr) == abs(df):
                        step_r = 1 if dr < 0 else -1
                        step_f = 1 if df < 0 else -1
                        between = []
                        r, f = pr + step_r, pf + step_f
                        while (r != kr) and (f != kf):
                            between.append(chess.square(f, r))
                            r += step_r; f += step_f
                    else:
                        continue
                    # count pieces between
                    pieces_between = sum(1 for s in between if board.piece_at(s) is not None)
                    if pieces_between == 1:
                        pin_count += 1
            prox = (8 - min_dist) if min_dist < 8 else 0
            return float(prox + 2*pin_count)
        return float(threat_score_against(chess.WHITE) - threat_score_against(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn structure penalty: (doubled + isolated) pawn penalty for white minus black (positive is better for white)'
    try:
        piece_map = board.piece_map()
        files_w = {f:0 for f in range(8)}
        files_b = {f:0 for f in range(8)}
        pawn_sqs_w = []
        pawn_sqs_b = []
        for sq, p in piece_map.items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if p.color == chess.WHITE:
                    files_w[f] += 1
                    pawn_sqs_w.append(sq)
                else:
                    files_b[f] += 1
                    pawn_sqs_b.append(sq)
        def penalty(pawn_sqs, files):
            doubled = sum(max(0, cnt-1) for cnt in files.values())
            isolated = 0
            for sq in pawn_sqs:
                f = chess.square_file(sq)
                if (files.get(f-1,0) == 0) and (files.get(f+1,0) == 0):
                    isolated += 1
            # combine with weights: doubled heavier
            return doubled * 1.2 + isolated * 0.9
        wp = penalty(pawn_sqs_w, files_w)
        bp = penalty(pawn_sqs_b, files_b)
        # return goodness = negative penalty, so higher = better
        return float((bp - wp))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) in heavy-piece (rook/queen) pressure on the opponent king rank (counts attackers on each square of the king rank)'
    piece_map = board.piece_map()
    # Find kings
    white_king_sq = None
    black_king_sq = None
    for sq, p in piece_map.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                white_king_sq = sq
            else:
                black_king_sq = sq
    def heavy_pressure_on_rank(king_sq, attacker_color):
        if king_sq is None:
            return 0
        rank = chess.square_rank(king_sq)
        pressure = 0
        for f in range(8):
            sq = chess.square(f, rank)
            attackers = board.attackers(attacker_color, sq)
            for a in attackers:
                ap = piece_map.get(a)
                if ap is not None and (ap.piece_type == chess.ROOK or ap.piece_type == chess.QUEEN):
                    pressure += 1
        return pressure
    white_pressure_on_black = heavy_pressure_on_rank(black_king_sq, chess.WHITE)
    black_pressure_on_white = heavy_pressure_on_rank(white_king_sq, chess.BLACK)
    return float(white_pressure_on_black - black_pressure_on_white)

def feature(board: chess.Board) -> float:
    'Mating-net density: distinct enemy pieces attacking any square within Manhattan distance 2 of the king, weighted by piece value and closeness (higher -> tighter mating net). Returns White_net - Black_net'
    pm = board.piece_map()
    white_king = None
    black_king = None
    for sq, p in pm.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                white_king = sq
            else:
                black_king = sq
    values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    def net_score(king_sq, attacker_color):
        if king_sq is None:
            return 0.0
        attackers_min_dist = {}
        for f in range(8):
            for r in range(8):
                sq = chess.square(f, r)
                if chess.square_distance(sq, king_sq) <= 2:
                    for a in board.attackers(attacker_color, sq):
                        # track minimum distance from attacker to king
                        d = chess.square_distance(a, king_sq)
                        prev = attackers_min_dist.get(a)
                        if prev is None or d < prev:
                            attackers_min_dist[a] = d
        score = 0.0
        for a, d in attackers_min_dist.items():
            p = board.piece_at(a)
            if p:
                score += values.get(p.piece_type,0.0) / (1.0 + float(d))
        return float(score)
    w_net = net_score(white_king, chess.BLACK)
    b_net = net_score(black_king, chess.WHITE)
    return float(w_net - b_net)

def feature(board: chess.Board) -> float:
    'Non-pawn mobility relative to non-pawn material: (mobility / (material+1)) for White minus Black (positive favors White)'
    try:
        piece_map = board.piece_map()
        values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        directions_rook = [(1,0),(-1,0),(0,1),(0,-1)]
        directions_bishop = [(1,1),(1,-1),(-1,1),(-1,-1)]
        knight_moves = [(1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]
        def mobility_and_material(color):
            mobility = 0.0
            material = 0.0
            for sq,p in piece_map.items():
                if p.color != color:
                    continue
                if p.piece_type == chess.PAWN or p.piece_type == chess.KING:
                    continue
                material += values.get(p.piece_type, 0.0)
                f = chess.square_file(sq); r = chess.square_rank(sq)
                if p.piece_type == chess.ROOK or p.piece_type == chess.QUEEN or p.piece_type == chess.BISHOP:
                    dirs = []
                    if p.piece_type == chess.ROOK:
                        dirs = directions_rook
                    elif p.piece_type == chess.BISHOP:
                        dirs = directions_bishop
                    else:
                        dirs = directions_rook + directions_bishop
                    for df,dr in dirs:
                        nf, nr = f+df, r+dr
                        while 0 <= nf < 8 and 0 <= nr < 8:
                            nsq = chess.square(nf, nr)
                            mobility += 1.0
                            if board.piece_at(nsq) is not None:
                                break
                            nf += df; nr += dr
                elif p.piece_type == chess.KNIGHT:
                    for df,dr in knight_moves:
                        nf, nr = f+df, r+dr
                        if 0 <= nf < 8 and 0 <= nr < 8:
                            nsq = chess.square(nf, nr)
                            mobility += 1.0
            ratio = mobility / (material + 1.0)
            return ratio
        return float(mobility_and_material(chess.WHITE) - mobility_and_material(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in minor-piece centralization: (White centralization - Black centralization). Centralization is negative average Euclidean distance from center (3.5,3.5) for knights and bishops so higher is better'
    pm = board.piece_map()
    def centralization(color):
        total = 0.0
        count = 0
        for sq, p in pm.items():
            if p.color != color:
                continue
            if p.piece_type in (chess.KNIGHT, chess.BISHOP):
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                dx = (f - 3.5)
                dy = (r - 3.5)
                dist = (dx*dx + dy*dy) ** 0.5
                total += dist
                count += 1
        if count == 0:
            return 0.0
        avg = total / count
        # return negative so smaller distance -> larger centralization score
        return -avg
    return float(centralization(chess.WHITE) - centralization(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Difference in number of isolated pawns: white_isolated_pawns - black_isolated_pawns (isolated = no friendly pawn on adjacent files)'
    pm = board.piece_map()
    pawn_files_by_color = {chess.WHITE: {}, chess.BLACK: {}}
    for sq, p in pm.items():
        if p.piece_type == chess.PAWN:
            f = chess.square_file(sq)
            pawn_files_by_color[p.color].setdefault(f, 0)
            pawn_files_by_color[p.color][f] += 1
    white_iso = 0
    black_iso = 0
    for sq, p in pm.items():
        if p.piece_type != chess.PAWN:
            continue
        f = chess.square_file(sq)
        d = pawn_files_by_color[p.color]
        left = (f-1 in d)
        right = (f+1 in d)
        if not left and not right:
            if p.color == chess.WHITE:
                white_iso += 1
            else:
                black_iso += 1
    return float(white_iso - black_iso)

def feature(board: chess.Board) -> float:
    'Passed pawn advancement score: sum of advanced passed-pawn progress for White minus Black (0..1 per pawn, more for more advanced passed pawns)'
    import chess
    pm = board.piece_map()
    def passed_score(color):
        score = 0.0
        enemy = not color
        for sq, p in pm.items():
            if p.piece_type!=chess.PAWN or p.color!=color:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            is_passed = True
            for ef, er in [(f-1, None),(f, None),(f+1, None)]:
                if ef < 0 or ef > 7:
                    continue
                for esq, ep in pm.items():
                    if ep.piece_type==chess.PAWN and ep.color==enemy:
                        ef2 = chess.square_file(esq)
                        er2 = chess.square_rank(esq)
                        if ef2==ef:
                            # enemy pawn on same file
                            # For white, enemy pawn ahead means er2 >= r; for black, er2 <= r
                            if color==chess.WHITE and er2>=r:
                                is_passed = False
                                break
                            if color==chess.BLACK and er2<=r:
                                is_passed = False
                                break
                if not is_passed:
                    break
            if is_passed:
                progress = (r / 7.0) if color==chess.WHITE else ((7 - r) / 7.0)
                score += progress
        return score
    return passed_score(chess.WHITE) - passed_score(chess.BLACK)

def feature(board: chess.Board) -> float:
    'Net attack pressure on squares adjacent to each king (white minus black)'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.BLACK), None)
        def adjacent_squares(sq):
            if sq is None:
                return []
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            res = []
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    nf = f + df
                    nr = r + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        res.append(chess.square(nf, nr))
            return res
        white_pressure = 0
        black_pressure = 0
        for adj in adjacent_squares(white_king_sq):
            white_pressure += len(board.attackers(chess.BLACK, adj))
        for adj in adjacent_squares(black_king_sq):
            black_pressure += len(board.attackers(chess.WHITE, adj))
        return float(white_pressure - black_pressure)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn advancement advantage: sum over passed pawns of (progress toward promotion in ranks) for White minus Black (measured in pawn-units: 100 per pawn)'
    try:
        pm = board.piece_map()
        score_w = 0.0
        score_b = 0.0
        for sq, pc in pm.items():
            if pc.piece_type != chess.PAWN:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            is_white = (pc.color == chess.WHITE)
            passed = True
            if is_white:
                for opp_sq, opp_pc in pm.items():
                    if opp_pc.piece_type == chess.PAWN and opp_pc.color == chess.BLACK:
                        of = chess.square_file(opp_sq)
                        orank = chess.square_rank(opp_sq)
                        if abs(of - f) <= 1 and orank >= r:
                            passed = False
                            break
                if passed:
                    # advancement value: rank (0..7) where higher rank closer to promotion
                    progress = r / 7.0
                    score_w += 100.0 * (0.5 + progress)  # base + advancement
            else:
                for opp_sq, opp_pc in pm.items():
                    if opp_pc.piece_type == chess.PAWN and opp_pc.color == chess.WHITE:
                        of = chess.square_file(opp_sq)
                        orank = chess.square_rank(opp_sq)
                        if abs(of - f) <= 1 and orank <= r:
                            passed = False
                            break
                if passed:
                    progress = (7 - r) / 7.0
                    score_b += 100.0 * (0.5 + progress)
        return float(score_w - score_b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of outside passed pawns (on files a,b or g,h): white - black'
    def is_passed(sq, color):
        f = chess.square_file(sq); r = chess.square_rank(sq)
        if color == chess.WHITE:
            for rf in range(r+1,8):
                for ff in range(max(0,f-1), min(7,f+1)+1):
                    s = rf*8 + ff
                    pc = board.piece_at(s)
                    if pc is not None and pc.piece_type == chess.PAWN and pc.color == chess.BLACK:
                        return False
            return True
        else:
            for rf in range(0,r):
                for ff in range(max(0,f-1), min(7,f+1)+1):
                    s = rf*8 + ff
                    pc = board.piece_at(s)
                    if pc is not None and pc.piece_type == chess.PAWN and pc.color == chess.WHITE:
                        return False
            return True
    outside_files = {0,1,6,7}
    w = 0; b = 0
    for sq, pc in board.piece_map().items():
        if pc.piece_type == chess.PAWN:
            if chess.square_file(sq) in outside_files and is_passed(sq, pc.color):
                if pc.color == chess.WHITE:
                    w += 1
                else:
                    b += 1
    return float(w - b)

def feature(board: chess.Board) -> float:
    'Difference in active-material ratio: (sum value of pieces on opponent half-board for white / white_total) - (same for black). Values in centipawns scaled between -1 and 1.'
    try:
        piece_values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        pm = board.piece_map()
        white_total = 0
        black_total = 0
        white_active = 0
        black_active = 0
        for sq,p in pm.items():
            val = piece_values.get(p.piece_type, 0)
            rank = chess.square_rank(sq)
            if p.color == chess.WHITE:
                white_total += val
                # active if on ranks 4-7 (opponent half) or on central files (c,d,e,f)
                if rank >= 4 or chess.square_file(sq) in (2,3,4,5):
                    white_active += val
            else:
                black_total += val
                if rank <= 3 or chess.square_file(sq) in (2,3,4,5):
                    black_active += val
        # avoid division by zero
        w_ratio = (white_active/white_total) if white_total>0 else 0.0
        b_ratio = (black_active/black_total) if black_total>0 else 0.0
        return float(w_ratio - b_ratio)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Queen penetration: (White queen advancement into Black half and centralization) - (Black queen similar), higher positive favors White'
    score_w = 0.0; score_b = 0.0
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.QUEEN:
            rank = chess.square_rank(sq); file = chess.square_file(sq)
            center_dist = (abs(file - 3.5) + abs(rank - 3.5)) / 7.0  # 0..1 smaller is more central
            if p.color == chess.WHITE:
                adv = max(0.0, (rank - 3) / 4.0)  # how much into black half
                score_w += (0.5 * (1.0 - center_dist) + 0.5 * adv)
            else:
                adv = max(0.0, (4 - rank) / 4.0)
                score_b += (0.5 * (1.0 - center_dist) + 0.5 * adv)
    return float(score_w - score_b)

def feature(board: chess.Board) -> float:
    'Backrank vulnerability indicator difference: 1 if king has no pawns on its backrank and opponent has heavy on same rank attacking, else 0 (White - Black)'
    try:
        pm = board.piece_map()
        # find kings
        king_sq = {chess.WHITE: None, chess.BLACK: None}
        for sq, pc in pm.items():
            if pc.piece_type == chess.KING:
                king_sq[pc.color] = sq
        def backrank_vul(color):
            ks = king_sq[color]
            if ks is None:
                return 0.0
            kr = chess.square_rank(ks)
            back_rank = kr
            # count own pawns on that rank
            own_pawn_on_rank = 0
            for sq, pc in pm.items():
                if pc.piece_type == chess.PAWN and pc.color == color and chess.square_rank(sq) == back_rank:
                    own_pawn_on_rank += 1
            if own_pawn_on_rank > 0:
                return 0.0
            # check if opponent has rook/queen on same rank or attacking any square of the rank
            opp = not color
            attacked = False
            for file in range(8):
                sq = chess.square(file, back_rank)
                # if opponent rook/queen attacks this square OR there is an opponent rook/queen on same rank not blocked
                if board.is_attacked_by(opp, sq):
                    # ensure attacker is heavy piece along rank or queen (rough check)
                    attackers = board.attackers(opp, sq)
                    for a in attackers:
                        p = pm.get(a)
                        if p and (p.piece_type in (chess.ROOK, chess.QUEEN)):
                            attacked = True
                            break
                if attacked:
                    break
            return 1.0 if attacked else 0.0
        return float(backrank_vul(chess.WHITE) - backrank_vul(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Queen vs material imbalance heuristic: (White_has_queen * Black_minor_rook_total - Black_has_queen * White_minor_rook_total) normalized'
    try:
        import chess
        def minor_rook_total(color):
            cnt = 0
            for p in board.piece_map().values():
                if p.color == color and p.piece_type in (chess.ROOK, chess.BISHOP, chess.KNIGHT):
                    # weight rook heavier
                    if p.piece_type == chess.ROOK:
                        cnt += 5
                    else:
                        cnt += 3
            return cnt
        white_queen = any(p.piece_type == chess.QUEEN and p.color == chess.WHITE for p in board.piece_map().values())
        black_queen = any(p.piece_type == chess.QUEEN and p.color == chess.BLACK for p in board.piece_map().values())
        wr = minor_rook_total(chess.WHITE)
        br = minor_rook_total(chess.BLACK)
        val = (1.0 if white_queen else 0.0) * float(br) - (1.0 if black_queen else 0.0) * float(wr)
        # normalize by total minor_rook material + 1 to avoid huge values
        norm = float(max(1, wr + br))
        return val / norm
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material balance (white minus black) in pawns=100 n=320 b=330 r=500 q=900 units, returned in pawn-equivalents (divide by 100)'
    try:
        values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        w = 0
        b = 0
        for sq, pc in board.piece_map().items():
            val = values.get(pc.piece_type, 0)
            if pc.color == chess.WHITE:
                w += val
            else:
                b += val
        return float((w - b) / 100.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Number of hanging pieces (pieces attacked by opponent and not defended) for both sides combined'
    try:
        pm = board.piece_map()
        count = 0
        for sq, pc in pm.items():
            own = pc.color
            opp = not own
            attackers_by_opp = board.attackers(opp, sq)
            defenders_by_own = board.attackers(own, sq)
            if attackers_by_opp and not defenders_by_own:
                count += 1
        return float(count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Proximity of enemy major pieces (rooks/queens) to the opposing king: lower distance increases value (White proximity to Black king minus Black proximity to White king), normalized'
    pm = board.piece_map()
    def king_sq(color):
        for sq,p in pm.items():
            if p.piece_type==chess.KING and p.color==color:
                return sq
        return None
    def sum_inv_dist_to_king(king_sq, attacker_color):
        if king_sq is None:
            return 0.0
        s = 0.0
        for sq,p in pm.items():
            if p.color==attacker_color and (p.piece_type==chess.ROOK or p.piece_type==chess.QUEEN):
                # use Chebyshev distance
                df = abs(chess.square_file(sq)-chess.square_file(king_sq))
                dr = abs(chess.square_rank(sq)-chess.square_rank(king_sq))
                d = max(df,dr)
                if d == 0:
                    inv = 10.0
                else:
                    inv = 1.0 / d
                s += inv * (1.0 if p.piece_type==chess.ROOK else 1.5)
        return s
    wprox = sum_inv_dist_to_king(king_sq(chess.BLACK), chess.WHITE)
    bprox = sum_inv_dist_to_king(king_sq(chess.WHITE), chess.BLACK)
    return float(wprox - bprox)

def feature(board: chess.Board) -> float:
    'Count of "unstoppable" passed pawns weighted by advancement (white minus black). A pawn is counted as unstoppable if the opposing king is farther (Manhattan) from its promotion square than the pawn needs to promote.'
    try:
        import chess
        result_white = 0.0
        result_black = 0.0
        piece_map = board.piece_map()
        # find kings for distance calculations
        white_king_sq = None
        black_king_sq = None
        for sq, pc in piece_map.items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    white_king_sq = sq
                else:
                    black_king_sq = sq
        for sq, pc in piece_map.items():
            if pc.piece_type != chess.PAWN:
                continue
            rank = chess.square_rank(sq)
            file = chess.square_file(sq)
            if pc.color == chess.WHITE:
                steps = 7 - rank
                promo_sq = chess.square(file, 7)
                king_dist = chess.square_distance(promo_sq, black_king_sq) if black_king_sq is not None else 100
                if king_dist > steps:
                    # weight by advancement: more advanced pawns count more
                    weight = 1.0 + (rank / 7.0)
                    result_white += weight
            else:
                steps = rank - 0
                promo_sq = chess.square(file, 0)
                king_dist = chess.square_distance(promo_sq, white_king_sq) if white_king_sq is not None else 100
                if king_dist > steps:
                    weight = 1.0 + ((7 - rank) / 7.0)
                    result_black += weight
        return float(result_white - result_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net attack pressure on squares adjacent to each king (white minus black)'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.BLACK), None)
        def adjacent_squares(sq):
            if sq is None:
                return []
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            res = []
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    nf = f + df
                    nr = r + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        res.append(chess.square(nf, nr))
            return res
        white_pressure = 0
        black_pressure = 0
        for adj in adjacent_squares(white_king_sq):
            white_pressure += len(board.attackers(chess.BLACK, adj))
        for adj in adjacent_squares(black_king_sq):
            black_pressure += len(board.attackers(chess.WHITE, adj))
        return float(white_pressure - black_pressure)
    except Exception:
        return 0.0

