def feature(board: chess.Board) -> float:
    'Space-control in enemy half: count squares on opponent\'s half that are attacked by your color (White - Black), normalized by half-board size'
    white_controls = 0
    black_controls = 0
    # white controls squares on ranks 4..7 (rank >=4)
    for r in range(4,8):
        for f in range(8):
            sq = chess.square(f,r)
            try:
                if board.is_attacked_by(chess.WHITE, sq):
                    white_controls += 1
                if board.is_attacked_by(chess.BLACK, chess.square(f,7-r)):  # symmetrical count for black's perspective
                    pass
            except Exception:
                pass
    # black controls squares on ranks 0..3 (from black's perspective opponent half is ranks 0..3)
    for r in range(0,4):
        for f in range(8):
            sq = chess.square(f,r)
            try:
                if board.is_attacked_by(chess.BLACK, sq):
                    black_controls += 1
            except Exception:
                pass
    # normalize by 32 (squares in half board)
    return (white_controls - black_controls) / 32.0

def feature(board: chess.Board) -> float:
    'Net pawn control of the central squares (d4,e4,d5,e5): (white control) - (black control) counting pawn attacks'
    try:
        center = [chess.parse_square(n) for n in ('d4','e4','d5','e5')]
        w = 0
        b = 0
        for sq in center:
            for att in board.attackers(chess.WHITE, sq):
                p = board.piece_at(att)
                if p is not None and p.piece_type == chess.PAWN:
                    w += 1
            for att in board.attackers(chess.BLACK, sq):
                p = board.piece_at(att)
                if p is not None and p.piece_type == chess.PAWN:
                    b += 1
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Potential favorable captures: sum (in pawn units) of opponent pieces that can be captured by a lower-value attacker (White - Black)'
    values = {chess.PAWN: 100.0, chess.KNIGHT: 320.0, chess.BISHOP: 330.0, chess.ROOK: 500.0, chess.QUEEN: 900.0, chess.KING: 0.0}
    pm = board.piece_map()
    white_potential = 0.0
    black_potential = 0.0
    for sq, target in pm.items():
        targ_color = target.color
        opp = not targ_color
        attackers = board.attackers(opp, sq)
        if not attackers:
            continue
        targ_val = values.get(target.piece_type, 0.0)
        for a in attackers:
            attacker_piece = board.piece_at(a)
            if attacker_piece is None:
                continue
            att_val = values.get(attacker_piece.piece_type, 0.0)
            if att_val < targ_val:
                # opponent (attacker) can capture a higher-value target
                if opp == chess.WHITE:
                    white_potential += targ_val
                else:
                    black_potential += targ_val
                break
    return float((white_potential - black_potential) / 100.0)

def feature(board: chess.Board) -> float:
    'Open-file control difference: number of open files controlled more by White than Black minus vice versa (White - Black)'
    try:
        pm = board.piece_map()
    except Exception:
        return 0.0
    white_control = 0
    black_control = 0
    for f in range(8):
        # check if file is open (no pawns)
        pawn_on_file = False
        for r in range(8):
            p = board.piece_at(chess.square(f, r))
            if p is not None and p.piece_type == chess.PAWN:
                pawn_on_file = True
                break
        if pawn_on_file:
            continue
        wcount = 0
        bcount = 0
        for r in range(8):
            sq = chess.square(f, r)
            # a square is "controlled" by a color if attacked by it or occupied by its piece
            if board.is_attacked_by(chess.WHITE, sq):
                wcount += 1
            occ = board.piece_at(sq)
            if occ is not None and occ.color == chess.WHITE:
                wcount += 1
            if board.is_attacked_by(chess.BLACK, sq):
                bcount += 1
            if occ is not None and occ.color == chess.BLACK:
                bcount += 1
        if wcount > bcount:
            white_control += 1
        elif bcount > wcount:
            black_control += 1
    return float(white_control - black_control)

def feature(board: chess.Board) -> float:
    'Pawn proximity to opposing king: sum over pawns of (advancement_rank * inverse distance to enemy king), white minus black'
    piece_map = board.piece_map()
    white_king = black_king = None
    for sq, p in piece_map.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                white_king = sq
            else:
                black_king = sq
    white_sum = 0.0
    black_sum = 0.0
    for sq, p in piece_map.items():
        if p.piece_type == chess.PAWN:
            if p.color == chess.WHITE:
                adv = chess.square_rank(sq)  # 0..7, higher => more advanced
                dist = chess.square_distance(sq, black_king) if black_king is not None else 8
                white_sum += (1.0 + adv/7.0) / (1.0 + dist)
            else:
                adv = 7 - chess.square_rank(sq)
                dist = chess.square_distance(sq, white_king) if white_king is not None else 8
                black_sum += (1.0 + adv/7.0) / (1.0 + dist)
    return float(white_sum - black_sum)

def feature(board: chess.Board) -> float:
    'Concentration of major pieces (rooks and queens) in the opponent half: (white_prop - black_prop), where prop is fraction on opponent half'
    try:
        pm = board.piece_map()
        def prop_major_in_enemy_half(color):
            majors = []
            for sq, p in pm.items():
                if p.color == color and p.piece_type in (chess.ROOK, chess.QUEEN):
                    majors.append(sq)
            if not majors:
                return 0.0
            count_in_enemy = 0
            for sq in majors:
                rk = chess.square_rank(sq)  # 0..7, rank 0 = rank1 for white
                if color == chess.WHITE:
                    # enemy half for white: ranks 4..7
                    if rk >= 4:
                        count_in_enemy += 1
                else:
                    # enemy half for black: ranks 0..3
                    if rk <= 3:
                        count_in_enemy += 1
            return float(count_in_enemy) / float(len(majors))
        return prop_major_in_enemy_half(chess.WHITE) - prop_major_in_enemy_half(chess.BLACK)
    except Exception:
        return 0.0

