def feature(board: chess.Board) -> float:
    'Standard deviation difference of non-pawn, non-king piece mobility (White - Black): mobility computed via pseudo-legal attack counts'
    try:
        knight_offsets = [(1,2),(2,1),(-1,2),( -2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]
        bishop_dirs = [(1,1),(1,-1),(-1,1),(-1,-1)]
        rook_dirs = [(1,0),(-1,0),(0,1),(0,-1)]
        def mobility_of_piece(sq, pc):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if pc.piece_type == chess.KNIGHT:
                cnt = 0
                for df, dr in knight_offsets:
                    nf, nr = f + df, r + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        cnt += 1
                return cnt
            if pc.piece_type == chess.BISHOP:
                cnt = 0
                for df, dr in bishop_dirs:
                    nf, nr = f + df, r + dr
                    while 0 <= nf <= 7 and 0 <= nr <= 7:
                        cnt += 1
                        if board.piece_at(nr*8+nf) is not None:
                            break
                        nf += df; nr += dr
                return cnt
            if pc.piece_type == chess.ROOK:
                cnt = 0
                for df, dr in rook_dirs:
                    nf, nr = f + df, r + dr
                    while 0 <= nf <= 7 and 0 <= nr <= 7:
                        cnt += 1
                        if board.piece_at(nr*8+nf) is not None:
                            break
                        nf += df; nr += dr
                return cnt
            if pc.piece_type == chess.QUEEN:
                cnt = 0
                for df, dr in bishop_dirs + rook_dirs:
                    nf, nr = f + df, r + dr
                    while 0 <= nf <= 7 and 0 <= nr <= 7:
                        cnt += 1
                        if board.piece_at(nr*8+nf) is not None:
                            break
                        nf += df; nr += dr
                return cnt
            return 0
        import math
        def std_mobility(color):
            vals = []
            for sq, pc in board.piece_map().items():
                if pc.color == color and pc.piece_type not in (chess.PAWN, chess.KING):
                    vals.append(mobility_of_piece(sq, pc))
            if not vals:
                return 0.0
            mean = sum(vals)/len(vals)
            var = sum((v-mean)**2 for v in vals)/len(vals)
            return math.sqrt(var)
        return float(std_mobility(chess.WHITE) - std_mobility(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in control of open/semi-open files by rooks/queens (White - Black), normalized by 8 files'
    file_control_white = 0
    file_control_black = 0
    pm = board.piece_map()
    for f in range(8):
        file_sqs = [chess.square(f,r) for r in range(8)]
        white_controls = False
        black_controls = False
        for sq in file_sqs:
            try:
                attackers = board.attackers(chess.WHITE, sq)
            except Exception:
                attackers = set()
            for a in attackers:
                p = board.piece_at(a)
                if p is not None and (p.piece_type==chess.ROOK or p.piece_type==chess.QUEEN):
                    white_controls = True
                    break
            try:
                attackers_b = board.attackers(chess.BLACK, sq)
            except Exception:
                attackers_b = set()
            for a in attackers_b:
                p = board.piece_at(a)
                if p is not None and (p.piece_type==chess.ROOK or p.piece_type==chess.QUEEN):
                    black_controls = True
                    break
            if white_controls and black_controls:
                break
        if white_controls and not black_controls:
            file_control_white += 1
        if black_controls and not white_controls:
            file_control_black += 1
    return float((file_control_white - file_control_black) / 8.0)

def feature(board: chess.Board) -> float:
    'Relative proximity of queens to the enemy king: (1/(1+d)) for white queen to black king minus same for black queen to white king'
    try:
        pm = board.piece_map()
        white_queens = [sq for sq, pc in pm.items() if pc.piece_type == chess.QUEEN and pc.color == chess.WHITE]
        black_queens = [sq for sq, pc in pm.items() if pc.piece_type == chess.QUEEN and pc.color == chess.BLACK]
        white_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == chess.BLACK), None)
        def inv_dist_min(queen_sqs, target_sq):
            if not queen_sqs or target_sq is None:
                return 0.0
            md = min(chess.square_distance(qs, target_sq) for qs in queen_sqs)
            return 1.0 / (1.0 + float(md))
        return inv_dist_min(white_queens, black_king_sq) - inv_dist_min(black_queens, white_king_sq)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Centralization score: sum over non-pawn pieces of (4 - min_distance_to_center) for white minus black (higher => more centralized white pieces)'
    pm = board.piece_map()
    center_sqs = [chess.parse_square(s) for s in ('d4', 'e4', 'd5', 'e5')]
    def piece_central_score(sq):
        dmin = min(chess.square_distance(sq, c) for c in center_sqs)
        return max(0, 4 - dmin)
    white_score = 0.0
    black_score = 0.0
    for sq, p in pm.items():
        if p.piece_type == chess.PAWN:
            continue
        score = piece_central_score(sq)
        if p.color == chess.WHITE:
            white_score += score
        else:
            black_score += score
    return float(white_score - black_score)

