def feature(board: chess.Board) -> float:
    'Difference in pseudo-mobility of major pieces (rooks+queens): (white reach squares) - (black reach squares)'
    try:
        pm = board.piece_map()
        def sliding_reach_from(sq, dirs):
            reach = 0
            r0 = chess.square_rank(sq)
            f0 = chess.square_file(sq)
            for dr, df in dirs:
                r = r0 + dr
                f = f0 + df
                while 0 <= r <= 7 and 0 <= f <= 7:
                    s2 = chess.square(f, r)
                    reach += 1
                    if board.piece_at(s2) is not None:
                        break
                    r += dr
                    f += df
            return reach
        orth = ((1,0),(-1,0),(0,1),(0,-1))
        diag = ((1,1),(1,-1),(-1,1),(-1,-1))
        w_reach = 0
        b_reach = 0
        for sq, p in pm.items():
            if p.piece_type == chess.ROOK:
                if p.color == chess.WHITE:
                    w_reach += sliding_reach_from(sq, orth)
                else:
                    b_reach += sliding_reach_from(sq, orth)
            if p.piece_type == chess.QUEEN:
                if p.color == chess.WHITE:
                    w_reach += sliding_reach_from(sq, orth + diag)
                else:
                    b_reach += sliding_reach_from(sq, orth + diag)
        return float(w_reach - b_reach)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net count of rooks on the opponent seventh rank (white rooks on rank 7 minus black rooks on rank 2)'
    try:
        pm = board.piece_map()
        w_count = 0
        b_count = 0
        for sq, pc in pm.items():
            if pc.piece_type != chess.ROOK:
                continue
            r = chess.square_rank(sq)
            if pc.color == chess.WHITE:
                # white rook on black seventh (rank index 6)
                if r == 6:
                    w_count += 1
            else:
                # black rook on white seventh (rank index 1)
                if r == 1:
                    b_count += 1
        return float(w_count - b_count)
    except Exception:
        return 0.0

