def feature(board: chess.Board) -> float:
    'Coordination metric: difference in average Manhattan distance among non-pawn non-king pieces (black_avg - white_avg). Positive => white pieces more clustered (better coordination)'
    piece_map = board.piece_map()
    def avg_distance(color):
        locs = [ (chess.square_file(sq), chess.square_rank(sq)) for sq,p in piece_map.items() if p.color==color and p.piece_type not in (chess.PAWN, chess.KING) ]
        n = len(locs)
        if n <= 1:
            return 8.0
        total = 0.0; count=0
        for i in range(n):
            for j in range(i+1,n):
                total += abs(locs[i][0]-locs[j][0]) + abs(locs[i][1]-locs[j][1])
                count += 1
        return total / count
    return float(avg_distance(chess.BLACK) - avg_distance(chess.WHITE))

def feature(board: chess.Board) -> float:
    'Difference in number of pawns whose promotion square color is covered by an enemy bishop (white - black). Values in [ -8 .. 8 ].'
    piece_map = board.piece_map()
    bishops_by_color = {chess.WHITE: [], chess.BLACK: []}
    pawns_by_color = {chess.WHITE: [], chess.BLACK: []}
    for sq, p in piece_map.items():
        if p.piece_type == chess.BISHOP:
            bishops_by_color[p.color].append(sq)
        if p.piece_type == chess.PAWN:
            pawns_by_color[p.color].append(sq)
    def square_color(sq):
        return (chess.square_file(sq) + chess.square_rank(sq)) & 1
    def promotion_square(pawn_sq, color):
        f = chess.square_file(pawn_sq)
        rank = 7 if color == chess.WHITE else 0
        return chess.square(f, rank)
    def covered_count(color):
        opp = not color
        opp_bishop_colors = set(square_color(b) for b in bishops_by_color[opp])
        cnt = 0
        for p_sq in pawns_by_color[color]:
            promo = promotion_square(p_sq, color)
            if square_color(promo) in opp_bishop_colors:
                cnt += 1
        return cnt
    return float(covered_count(chess.WHITE) - covered_count(chess.BLACK))

def feature(board: chess.Board) -> float:
    '1. Does the side to move have a checkmate in one? (1.0 if yes, 0.0 otherwise)'
    try:
        for mv in board.legal_moves:
            b2 = board.copy()
            b2.push(mv)
            if b2.is_checkmate():
                return 1.0
    except Exception:
        pass
    return 0.0

def feature(board: chess.Board) -> float:
    'Average mobility of edge non-pawn, non-king pieces difference: (white_avg - black_avg), 0 if no such pieces'
    try:
        pieces = board.piece_map()
    except Exception:
        pieces = {}
    def is_edge(sq):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        return f == 0 or f == 7 or r == 0 or r == 7
    w_moves = 0
    w_count = 0
    b_moves = 0
    b_count = 0
    # to count mobility we must count legal moves for that piece; iterate legal moves
    legal_moves = list(board.legal_moves)
    moves_by_from = {}
    for m in legal_moves:
        moves_by_from.setdefault(m.from_square, 0)
        moves_by_from[m.from_square] += 1
    for sq, p in pieces.items():
        if p.piece_type in (chess.PAWN, chess.KING):
            continue
        if not is_edge(sq):
            continue
        cnt = moves_by_from.get(sq, 0)
        if p.color == chess.WHITE:
            w_moves += cnt
            w_count += 1
        else:
            b_moves += cnt
            b_count += 1
    w_avg = (w_moves / w_count) if w_count>0 else 0.0
    b_avg = (b_moves / b_count) if b_count>0 else 0.0
    return float(w_avg - b_avg)

def feature(board: chess.Board) -> float:
    'Piece coordination: (Black_avg_pairwise_distance - White_avg_pairwise_distance) among non-pawn, non-king pieces; positive means White pieces are more clustered (better coordination)'
    pm = board.piece_map()
    def avg_pairwise(c):
        coords = []
        for sq, pc in pm.items():
            if pc.color == c and pc.piece_type not in (chess.PAWN, chess.KING):
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                coords.append((f, r))
        n = len(coords)
        if n <= 1:
            return 0.0
        total = 0.0
        count = 0
        for i in range(n):
            for j in range(i+1, n):
                total += abs(coords[i][0] - coords[j][0]) + abs(coords[i][1] - coords[j][1])
                count += 1
        return total / count
    white_avg = avg_pairwise(chess.WHITE)
    black_avg = avg_pairwise(chess.BLACK)
    return black_avg - white_avg

def feature(board: chess.Board) -> float:
    'Sum of opponent piece activity toward the side-to-move king: sum(weight/(1+manhattan_distance)) where weight ~ piece value'
    try:
        values = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0, chess.KING:0.0}
        my_color = board.turn
        opp = not my_color
        king_sq = board.king(my_color)
        if king_sq is None:
            return 0.0
        total = 0.0
        for sq, piece in board.piece_map().items():
            if piece.color != opp:
                continue
            dist = chess.square_distance(sq, king_sq)
            # Avoid division by zero; if on king square (capture), use small distance
            denom = 1.0 + float(dist)
            total += values.get(piece.piece_type, 0.0) / denom
        # normalize to pawn units
        return float(total / 100.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn majority on queenside (files a-c): (white_queenside_pawns - black_queenside_pawns)'
    try:
        white = 0
        black = 0
        for f in range(0, 3):
            for r in range(8):
                p = board.piece_at(chess.square(f, r))
                if p and p.piece_type == chess.PAWN:
                    if p.color == chess.WHITE:
                        white += 1
                    else:
                        black += 1
        return float(white - black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Edge-trapped piece penalty: pieces on the edge with <=1 legal moves weighted by piece value and distance-from-center (White - Black)'
    try:
        values = {chess.QUEEN:9.0, chess.ROOK:5.0, chess.BISHOP:3.0, chess.KNIGHT:3.0, chess.PAWN:1.0, chess.KING:0.0}
        pm = board.piece_map()
        moves_from = {}
        for m in board.legal_moves:
            moves_from[m.from_square] = moves_from.get(m.from_square, 0) + 1
        center_squares = [chess.parse_square(s) for s in ('d4','e4','d5','e5')]
        score = 0.0
        for sq, p in pm.items():
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if f in (0,7) or r in (0,7):
                mobility = moves_from.get(sq, 0)
                if mobility <= 1 and p.piece_type != chess.KING:
                    dist = min(chess.square_distance(sq, c) for c in center_squares)
                    weight = values.get(p.piece_type, 0.0) * (1.0 + (dist / 4.0))
                    score += (weight if p.color == chess.WHITE else -weight)
        return float(score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in minimal Manhattan distance from opponent king to advanced pawns (White advantage positive if Black king is farther from White advanced pawn than vice versa)'
    try:
        def min_dist_to_opp_king(own_color):
            best = 100.0
            king_sq = None
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color != own_color:
                    king_sq = sq
                    break
            if king_sq is None:
                return 100.0
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.PAWN and p.color == own_color:
                    r = chess.square_rank(sq)
                    # consider only advanced pawns (6th rank or beyond considered advanced here: rank >=5 for White, <=2 for Black)
                    if (own_color == chess.WHITE and r >= 4) or (own_color == chess.BLACK and r <= 3):
                        d = chess.square_distance(sq, king_sq)
                        if d < best:
                            best = float(d)
            return best
        w_min = min_dist_to_opp_king(chess.WHITE)
        b_min = min_dist_to_opp_king(chess.BLACK)
        # Positive when White has a closer pawn to Black king (which makes defense easier for Black), so invert:
        # We want positive when White's advanced pawn is LESS DEFENDED (i.e., Black king is FARTHER) => b_min large relative to w_min
        result = (b_min - w_min)
        return float(result)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material balance (white minus black) in pawns=100 n=320 b=330 r=500 q=900 units, returned in pawn-equivalents (divide by 100)'
    try:
        values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        w = 0
        b = 0
        for sq, pc in board.piece_map().items():
            val = values.get(pc.piece_type, 0)
            if pc.color == chess.WHITE:
                w += val
            else:
                b += val
        return float((w - b) / 100.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King pawn-shield integrity: difference (White - Black) of pawn shield completeness in front of each king (0..1)'
    try:
        pieces = board.piece_map()
        white_king_sq = next((sq for sq, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        def shield_score(king_sq, color):
            if king_sq is None:
                return 0.0
            f = chess.square_file(king_sq)
            r = chess.square_rank(king_sq)
            score = 0.0
            # For white, pawns in front are at higher ranks; for black, lower ranks
            dir = 1 if color == chess.WHITE else -1
            candidates = []
            # three-file pawn shield on rank directly in front
            for df in (-1, 0, 1):
                rf = r + dir
                ff = f + df
                if 0 <= rf <= 7 and 0 <= ff <= 7:
                    candidates.append(chess.square(ff, rf))
            # add an extra central pawn two ranks ahead (typical shield)
            rf2 = r + 2 * dir
            if 0 <= rf2 <= 7 and 0 <= f <= 7:
                candidates.append(chess.square(f, rf2))
            for sq in candidates:
                p = board.piece_at(sq)
                if p is not None and p.piece_type == chess.PAWN and p.color == color:
                    score += 1.0
            # normalize by up to 4 possible shield pawns
            return score / max(1.0, len(candidates))
        w = shield_score(white_king_sq, chess.WHITE)
        b = shield_score(black_king_sq, chess.BLACK)
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material-to-mobility ratio difference: (attacked-squares-count / material) for White minus Black; higher suggests activity per unit material'
    pm = board.piece_map()
    val = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.25, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    material = {chess.WHITE:0.0, chess.BLACK:0.0}
    for p in pm.values():
        material[p.color] += val.get(p.piece_type, 0.0)
    attacked_by = {chess.WHITE:set(), chess.BLACK:set()}
    # count all squares attacked by each side (union)
    for sq in range(64):
        if board.is_attacked_by(chess.WHITE, sq):
            attacked_by[chess.WHITE].add(sq)
        if board.is_attacked_by(chess.BLACK, sq):
            attacked_by[chess.BLACK].add(sq)
    mobility = {chess.WHITE: float(len(attacked_by[chess.WHITE])), chess.BLACK: float(len(attacked_by[chess.BLACK]))}
    # avoid division by zero
    white_ratio = mobility[chess.WHITE] / max(1.0, material[chess.WHITE])
    black_ratio = mobility[chess.BLACK] / max(1.0, material[chess.BLACK])
    return float(white_ratio - black_ratio)

def feature(board: chess.Board) -> float:
    'Back-rank escape squares difference: number of empty squares on the king\'s current rank within two files that are not attacked by the opponent. Returns white - black.'
    def escapes(color):
        ksq = board.king(color)
        if ksq is None:
            return 0.0
        f = chess.square_file(ksq)
        r = chess.square_rank(ksq)
        opp = not color
        cnt = 0
        for af in range(max(0,f-2), min(7,f+2)+1):
            sq = chess.square(af, r)
            if board.piece_at(sq) is None and not board.is_attacked_by(opp, sq):
                cnt += 1
        return float(cnt)
    return float(escapes(chess.WHITE) - escapes(chess.BLACK))

def feature(board: chess.Board) -> float:
    'King pawn shield gaps: number of empty or enemy-occupied shield squares in 1-3 ranks in front of king across adjacent files (positive favors White)'
    try:
        pieces = board.piece_map()
        def shield_gaps(color):
            king_sq = next((s for s,p in pieces.items() if p.piece_type==chess.KING and p.color==color), None)
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            gaps = 0.0
            for df in (-1,0,1):
                f = kf+df
                if f<0 or f>7: continue
                if color==chess.WHITE:
                    ranks = range(kr+1, min(7,kr+3)+1)
                else:
                    ranks = range(max(0,kr-3), kr)
                for r in ranks:
                    sq = chess.square(f,r)
                    p = pieces.get(sq)
                    if p is None:
                        gaps += 0.5
                    elif p.color!=color:
                        gaps += 0.8
            return gaps
        return float(shield_gaps(chess.BLACK) - shield_gaps(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in legal queen move counts (White queen legal moves minus Black queen legal moves), computed by flipping side to move safely'
    # compute legal queen moves for both colors by copying the board and setting turn
    try:
        b_white = board.copy()
        b_white.turn = chess.WHITE
        wq_moves = 0
        for mv in b_white.legal_moves:
            p = b_white.piece_at(mv.from_square)
            if p is not None and p.piece_type == chess.QUEEN and p.color == chess.WHITE:
                wq_moves += 1
        b_black = board.copy()
        b_black.turn = chess.BLACK
        bq_moves = 0
        for mv in b_black.legal_moves:
            p = b_black.piece_at(mv.from_square)
            if p is not None and p.piece_type == chess.QUEEN and p.color == chess.BLACK:
                bq_moves += 1
        # normalize by a moderate denominator
        return float(wq_moves - bq_moves) / 16.0
    except Exception:
        # fallback if copy or move properties not available
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn promotion pressure: sum over pawns of 1/(1+steps_to_promotion) weighted by being passed (white minus black). Encourages advanced, passed pawns.'
    try:
        import chess
        piece_map = board.piece_map()
        def is_passed(sq, color):
            file = chess.square_file(sq)
            rank = chess.square_rank(sq)
            if color == chess.WHITE:
                ahead_ranks = range(rank+1, 8)
                enemy = chess.BLACK
                for r in ahead_ranks:
                    for f in (file-1, file, file+1):
                        if 0 <= f <= 7:
                            s = chess.square(f, r)
                            pc = piece_map.get(s)
                            if pc is not None and pc.piece_type == chess.PAWN and pc.color == enemy:
                                return False
                return True
            else:
                ahead_ranks = range(0, rank)
                enemy = chess.WHITE
                for r in ahead_ranks:
                    for f in (file-1, file, file+1):
                        if 0 <= f <= 7:
                            s = chess.square(f, r)
                            pc = piece_map.get(s)
                            if pc is not None and pc.piece_type == chess.PAWN and pc.color == enemy:
                                return False
                return True
        white_score = 0.0
        black_score = 0.0
        for sq, pc in piece_map.items():
            if pc.piece_type != chess.PAWN:
                continue
            rank = chess.square_rank(sq)
            if pc.color == chess.WHITE:
                steps = 7 - rank
                weight = 1.0 / (1.0 + float(steps))
                if is_passed(sq, chess.WHITE):
                    weight *= 1.5
                white_score += weight
            else:
                steps = rank - 0
                weight = 1.0 / (1.0 + float(steps))
                if is_passed(sq, chess.BLACK):
                    weight *= 1.5
                black_score += weight
        return float(white_score - black_score)
    except Exception:
        return 0.0

