            if king_sq is None:
                return 0.0
            f = chess.square_file(king_sq)
            r = chess.square_rank(king_sq)
            files = [ff for ff in (f-1, f, f+1) if 0 <= ff <= 7]
            ranks = []
            if color == chess.WHITE:
                ranks = [nr for nr in (r+1, r+2) if 0 <= nr <= 7]
            else:
                ranks = [nr for nr in (r-1, r-2) if 0 <= nr <= 7]
            count = 0
            for nf in files:
                for nr in ranks:
                    sq = chess.square(nf, nr)
                    pc = board.piece_at(sq)
                    if pc is not None and pc.piece_type == chess.PAWN and pc.color == color:
                        count += 1
            return float(count)
        return shield_count(chess.WHITE) - shield_count(chess.BLACK)
    except Exception:
