def feature(board: chess.Board) -> float:
    'Difference in average Manhattan distance of non-king pieces to their own king (white average minus black average)'
    try:
        pm = board.piece_map()
        def avg_dist(color):
            king_sq = next((sq for sq, pc in pm.items() if pc.piece_type == chess.KING and pc.color == color), None)
            if king_sq is None:
                return 0.0
            dists = []
            for sq, pc in pm.items():
                if pc.color == color and pc.piece_type != chess.KING:
                    dists.append(chess.square_distance(sq, king_sq))
            if not dists:
                return 0.0
            return float(sum(dists) / len(dists))
        return avg_dist(chess.WHITE) - avg_dist(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Weighted sum of opponent pieces that attack each king (white_attack_weight - black_attack_weight)'
    try:
        piece_map = board.piece_map()
        # find king squares
        white_king_sq = next((sq for sq, p in piece_map.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, p in piece_map.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        val = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        def attackers_weight(target_sq, attacker_color):
            if target_sq is None:
                return 0.0
            total = 0.0
            try:
                for attacker_sq in board.attackers(attacker_color, target_sq):
                    p = board.piece_at(attacker_sq)
                    if p is not None:
                        total += val.get(p.piece_type, 0.0)
            except Exception:
                return 0.0
            return total
        # weight of black attackers on white king minus white attackers on black king
        white_under_attack = attackers_weight(white_king_sq, chess.BLACK)
        black_under_attack = attackers_weight(black_king_sq, chess.WHITE)
        return float(white_under_attack - black_under_attack)
    except Exception:
        return 0.0

