def feature(board: chess.Board) -> float:
    'White minus Black: defenders minus attackers by rooks on the most advanced passed pawn (for each side, pick most advanced passed pawn and compute (defenders_by_rook+king) - attackers_by_rook).'
    try:
        pieces = board.piece_map()
    except Exception:
        return 0.0
    pawns = [(sq, p) for sq, p in pieces.items() if p.piece_type == chess.PAWN]
    rooks = [(sq, p) for sq, p in pieces.items() if p.piece_type == chess.ROOK]
    kings = {p.color: sq for sq, p in pieces.items() if p.piece_type == chess.KING}
    def is_passed(sq, color):
        f = chess.square_file(sq); r = chess.square_rank(sq)
        if color == chess.WHITE:
            for opp_sq, opp_piece in pawns:
                if opp_piece.color == chess.BLACK:
                    if abs(chess.square_file(opp_sq) - f) <= 1 and chess.square_rank(opp_sq) >= r:
                        return False
            return True
        else:
            for opp_sq, opp_piece in pawns:
                if opp_piece.color == chess.WHITE:
                    if abs(chess.square_file(opp_sq) - f) <= 1 and chess.square_rank(opp_sq) <= r:
                        return False
            return True
    white_best = None
    black_best = None
    for sq, p in pawns:
        if not is_passed(sq, p.color):
            continue
        if p.color == chess.WHITE:
            if white_best is None or chess.square_rank(sq) > chess.square_rank(white_best):
                white_best = sq
        else:
            if black_best is None or chess.square_rank(sq) < chess.square_rank(black_best):
                black_best = sq
    def pawn_def_balance(pawn_sq, color):
        if pawn_sq is None:
            return 0.0
        # attackers by enemy rooks
        att_rooks = 0
        for a in board.attackers(not color, pawn_sq):
            piece = board.piece_at(a)
            if piece and piece.piece_type == chess.ROOK and piece.color != color:
                att_rooks += 1
        # defenders by own rooks and own king (king counts as 1 if it can reach pawn square in one move)
        def_cnt = 0
        for a in board.attackers(color, pawn_sq):
            piece = board.piece_at(a)
            if piece and piece.color == color and (piece.piece_type == chess.ROOK or piece.piece_type == chess.KING):
                def_cnt += 1
        return float(def_cnt - att_rooks)
    wbal = pawn_def_balance(white_best, chess.WHITE)
