def feature(board: chess.Board) -> float:
    'White minus Black: back-rank safety measure = normalized number of legal king moves when the king is on the back rank (0..1). Returns white_safety - black_safety.'
    try:
        pieces = board.piece_map()
    except Exception:
        return 0.0
    kings = {p.color: sq for sq, p in pieces.items() if p.piece_type == chess.KING}
    # count legal king moves for each side
    legal_moves = list(board.legal_moves) if board is not None else []
    king_moves_count = {chess.WHITE: 0, chess.BLACK: 0}
    for m in legal_moves:
        try:
            if getattr(m, 'from_square', None) is not None:
                from_sq = m.from_square
            else:
                from_sq = m.from_square
        except Exception:
            continue
        piece = board.piece_at(from_sq)
        if piece and piece.piece_type == chess.KING:
            king_moves_count[piece.color] += 1
    safety_w = 0.0
    safety_b = 0.0
    # normalize: 0 moves -> 0.0, 1 move -> 0.5, >=2 moves -> 1.0
    kmw = king_moves_count.get(chess.WHITE, 0)
    kmb = king_moves_count.get(chess.BLACK, 0)
    safety_w = min(1.0, kmw / 2.0)
    safety_b = min(1.0, kmb / 2.0)
    return float(safety_w - safety_b)

def feature(board: chess.Board) -> float:
