def feature(board: chess.Board) -> float:
    'Net attack pressure on kings: (White pressure on Black king area) - (Black pressure on White king area), weighted by attacker piece values'
    try:
        piece_values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    except Exception:
        piece_values = {1:100,2:320,3:330,4:500,5:900,6:0}
    def king_area(sq):
        # king square plus up to 8 neighbors
        area = [sq]
        file = chess.square_file(sq)
        rank = chess.square_rank(sq)
        for df in (-1,0,1):
            for dr in (-1,0,1):
                if df==0 and dr==0:
                    continue
                f = file+df
                r = rank+dr
                if 0<=f<8 and 0<=r<8:
                    area.append(chess.square(f,r))
        return area
    try:
        wking = board.king(chess.WHITE)
        bking = board.king(chess.BLACK)
        white_pressure = 0.0
        black_pressure = 0.0
        if bking is not None:
            for sq in king_area(bking):
                attackers = board.attackers(chess.WHITE, sq)
                for a in attackers:
                    p = board.piece_at(a)
                    if p:
                        white_pressure += piece_values.get(p.piece_type,0)
        if wking is not None:
            for sq in king_area(wking):
                attackers = board.attackers(chess.BLACK, sq)
                for a in attackers:
                    p = board.piece_at(a)
                    if p:
                        black_pressure += piece_values.get(p.piece_type,0)
        return float(white_pressure - black_pressure)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Total value of undefended (hanging) pieces: (White hanging value) - (Black hanging value) in centipawn units'
    values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    pm = board.piece_map()
    white_vuln = 0
    black_vuln = 0
    try:
        for sq, pc in pm.items():
            attackers = board.attackers(not pc.color, sq)
            if not attackers:
                continue
            defenders = board.attackers(pc.color, sq)
            if len(defenders) == 0:
                val = values.get(pc.piece_type,0)
                if pc.color == chess.WHITE:
                    white_vuln += val
                else:
                    black_vuln += val
        return float(white_vuln - black_vuln)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in rooks on open files: (White open-file rooks count) - (Black open-file rooks count)'
    try:
        white_count = 0
        black_count = 0
        pawns = [sq for sq, p in board.piece_map().items() if p and p.piece_type == chess.PAWN]
        pawn_files = set(chess.square_file(sq) for sq in pawns)
        for sq, p in board.piece_map().items():
            if p and p.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                if f not in pawn_files:
                    if p.color == chess.WHITE:
