        return float(white_count - black_count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rooks on the opponent seventh rank difference: (White rooks on rank 7) - (Black rooks on rank 2)'
    try:
        white = 0
        black = 0
        for sq, p in board.piece_map().items():
            if not p or p.piece_type != chess.ROOK:
                continue
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                # opponent's seventh rank is rank index 6
                if r == 6:
                    white += 1
            else:
                # Black on White's seventh (rank index 1)
                if r == 1:
                    black += 1
        return float(white - black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Centralized minor pieces difference: number of knights/bishops on central 4x4 (c3-f6) squares, (White - Black)'
    try:
        white = 0
        black = 0
        for sq, p in board.piece_map().items():
            if not p or p.piece_type not in (chess.KNIGHT, chess.BISHOP):
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            # central 4x4: files c-f -> 2..5, ranks 2..5
            if 2 <= f <= 5 and 2 <= r <= 5:
                if p.color == chess.WHITE:
                    white += 1
                else:
                    black += 1
        return float(white - black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Bishop-pair bonus difference: 1.0 if White has bishop pair, -1.0 if Black has bishop pair, net (White - Black)'
    try:
        wb = sum(1 for p in board.piece_map().values() if p and p.color==chess.WHITE and p.piece_type==chess.BISHOP)
        bb = sum(1 for p in board.piece_map().values() if p and p.color==chess.BLACK and p.piece_type==chess.BISHOP)
        return float((1.0 if wb>=2 else 0.0) - (1.0 if bb>=2 else 0.0))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King pawn-shield exposure difference: (Black exposure) - (White exposure); exposure = missing shield pawns + 0.5 * enemy attackers on shield squares'
    try:
        def exposure_for(color):
            k = board.king(color)
            if k is None:
                return 0.0
            f = chess.square_file(k)
            r = chess.square_rank(k)
            # For White king, shield squares are one rank forward (r+1), for Black (r-1)
            forward = 1 if color == chess.WHITE else -1
            exp = 0.0
            for df in (-1,0,1):
                ff = f + df
                rr = r + forward
                if 0 <= ff < 8 and 0 <= rr < 8:
                    sq = chess.square(ff, rr)
                    p = board.piece_at(sq)
                    if not p or p.piece_type != chess.PAWN or p.color != color:
                        exp += 1.0  # missing pawn
                    # enemy attackers on that shield square
                    enemy = not color
                    attackers = len(board.attackers(enemy, sq))
                    exp += 0.5 * attackers
            return exp
        bexp = exposure_for(chess.BLACK)
        wexp = exposure_for(chess.WHITE)
        return float(bexp - wexp)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Trapped-piece vulnerability value difference: sum of piece-values for pieces attacked, undefended and with ≤1 legal move (White - Black)'
    values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    try:
        pm = board.piece_map()
        white_v = 0
        black_v = 0
        # Precompute legal moves per from-square
        moves_from = {}
        for mv in board.legal_moves:
            moves_from.setdefault(mv.from_square, 0)
            moves_from[mv.from_square] += 1
        for sq, p in pm.items():
            if not p or p.piece_type == chess.KING:
                continue
            attackers = len(board.attackers(not p.color, sq))
            defenders = len(board.attackers(p.color, sq))
            legal_moves_count = moves_from.get(sq, 0)
            if attackers > 0 and defenders == 0 and legal_moves_count <= 1:
                val = values.get(p.piece_type,0)
                if p.color == chess.WHITE:
                    white_v += val
                else:
                    black_v += val
        return float(white_v - black_v)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Forward control difference: how many squares in the opponent half are attacked by each side (White - Black), normalized by 16'
    try:
        white_count = 0
        black_count = 0
        # White forward half = ranks 4..7 (indices 4..7), Black forward half = ranks 0..3
        for sq in range(64):
            r = chess.square_rank(sq)
            if 4 <= r <= 7:
                if board.is_attacked_by(chess.WHITE, sq):
                    white_count += 1
            if 0 <= r <= 3:
                if board.is_attacked_by(chess.BLACK, sq):
                    black_count += 1
        # Normalize by max 32 (but we say 16 to keep scale small); use 16 to match doc idea
        return float((white_count - black_count) / 16.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King distance-to-center difference: (Black king min manhattan distance to central squares) - (White king min distance), positive means White king is closer to center'
    try:
        center_squares = [chess.parse_square(s) for s in ('d4','e4','d5','e5')]
        def min_dist_to_center(color):
            k = board.king(color)
            if k is None:
                return 8.0
            dmin = 8
            for c in center_squares:
                d = chess.square_distance(k, c)
                if d < dmin:
                    dmin = d
            return float(dmin)
        bd = min_dist_to_center(chess.BLACK)
        wd = min_dist_to_center(chess.WHITE)
        return float(bd - wd)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Weighted sum of enemy attackers on/around the kings (black pressure on White king minus white pressure on Black king)'
    import chess
    try:
        weights = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        def pressure_on_king(king_sq, attacker_color):
            if king_sq is None:
                return 0.0
            total = 0.0
            kr = chess.square_rank(king_sq); kf = chess.square_file(king_sq)
            for dr in (-1,0,1):
                for df in (-1,0,1):
                    r = kr + dr; f = kf + df
                    if 0 <= r <= 7 and 0 <= f <= 7:
                        sq = chess.square(f, r)
                        for att_sq in board.attackers(attacker_color, sq):
                            p = board.piece_at(att_sq)
                            if p:
                                total += weights.get(p.piece_type,0.0)
            return total
        wking = board.king(chess.WHITE); bking = board.king(chess.BLACK)
        black_on_white = pressure_on_king(wking, chess.BLACK)
        white_on_black = pressure_on_king(bking, chess.WHITE)
        return float(black_on_white - white_on_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Back-rank / same-rank major-piece pressure: count enemy rooks/queens on the same rank as the king with a clear path (black advantage positive)'
    import chess
    try:
        def backrank_score_for(color):
            king_sq = board.king(color)
            if king_sq is None:
                return 0.0
            rank = chess.square_rank(king_sq)
            score = 0.0
            enemy = not color
            for sq, p in board.piece_map().items():
                if p.color == enemy and (p.piece_type == chess.ROOK or p.piece_type == chess.QUEEN):
                    if chess.square_rank(sq) == rank:
                        # check clear path between piece and king
                        kf = chess.square_file(king_sq); pf = chess.square_file(sq)
                        step = 1 if pf < kf else -1
                        blocked = False
                        for f in range(pf+step, kf, step):
                            if board.piece_at(chess.square(f, rank)):
                                blocked = True
                                break
                        if not blocked:
                            score += (5.0 if p.piece_type == chess.ROOK else 9.0)
            return score
        black_vuln = backrank_score_for(chess.WHITE)  # pieces attacking white king's rank
        white_vuln = backrank_score_for(chess.BLACK)
        return float(black_vuln - white_vuln)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn score difference: (black passed pawn advancement score) - (white passed pawn advancement score)'
    import chess, math
    try:
        def passed_score_for(color):
            score = 0.0
            for sq, p in board.piece_map().items():
                if p.piece_type != chess.PAWN or p.color != color:
                    continue
                rank = chess.square_rank(sq)
                file = chess.square_file(sq)
                passed = True
                if color == chess.WHITE:
                    for df in (-1,0,1):
                        f = file + df
                        if 0 <= f <= 7:
                            # any enemy pawn ahead of or on same square blocks passed-ness
                            for r in range(rank+1,8):
                                s2 = chess.square(f, r)
                                q = board.piece_at(s2)
                                if q and q.piece_type == chess.PAWN and q.color == chess.BLACK:
                                    passed = False; break
                            if not passed: break
                    if passed:
                        adv = rank / 7.0
                        score += (1.0 * (adv ** 1.5))
                else:
                    for df in (-1,0,1):
                        f = file + df
                        if 0 <= f <= 7:
                            for r in range(0, rank):
                                s2 = chess.square(f, r)
                                q = board.piece_at(s2)
                                if q and q.piece_type == chess.PAWN and q.color == chess.WHITE:
                                    passed = False; break
                            if not passed: break
                    if passed:
                        adv = (7 - rank) / 7.0
                        score += (1.0 * (adv ** 1.5))
            return score
        return float(passed_score_for(chess.BLACK) - passed_score_for(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King escape squares difference: (#safe escape squares for White king) - (#safe escape squares for Black king)'
    import chess
    try:
        def safe_spaces_for(color):
            ks = board.king(color)
            if ks is None:
                return 0.0
            kr = chess.square_rank(ks); kf = chess.square_file(ks)
            opp = not color
            count = 0
            for dr in (-1,0,1):
                for df in (-1,0,1):
                    if dr == 0 and df == 0:
                        continue
                    r = kr + dr; f = kf + df
                    if 0 <= r <= 7 and 0 <= f <= 7:
                        sq = chess.square(f, r)
                        occ = board.piece_at(sq)
                        if occ and occ.color == color:
                            continue
                        # square must not be attacked by opponent
                        if not board.is_attacked_by(opp, sq):
                            count += 1
            # also allow current square safety: if king currently in check it's less safe but we exclude it
            return float(count)
        return float(safe_spaces_for(chess.WHITE) - safe_spaces_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rook activity on files: (white open/semi-open rook score) - (black open/semi-open rook score), open=2, semi-open=1'
    import chess
    try:
        def rook_score_for(color):
            score = 0.0
            pawn_files = {f: {'w':0, 'b':0} for f in range(8)}
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.PAWN:
                    f = chess.square_file(sq)
                    pawn_files[f]['w' if p.color == chess.WHITE else 'b'] += 1
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.ROOK and p.color == color:
                    f = chess.square_file(sq)
                    pf = pawn_files[f]
                    if pf['w'] + pf['b'] == 0:
                        score += 2.0
                    elif (color == chess.WHITE and pf['w'] == 0) or (color == chess.BLACK and pf['b'] == 0):
                        score += 1.0
            return score
        return float(rook_score_for(chess.WHITE) - rook_score_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Minor-piece outpost score difference: central outposts occupied by knights/bishops (white minus black), knights valued higher'
    import chess
    try:
        outposts = {chess.parse_square(s) for s in ['c4','d4','e4','f4','c5','d5','e5','f5']}
        def outpost_score_for(color):
            sc = 0.0
            for sq, p in board.piece_map().items():
                if p.color != color:
                    continue
                if p.piece_type not in (chess.KNIGHT, chess.BISHOP):
                    continue
                if sq in outposts:
                    base = 3.0 if p.piece_type == chess.KNIGHT else 2.0
                    defenders = len(board.attackers(color, sq))
                    sc += base + (1.0 if defenders >= 1 else 0.0)
            return sc
        return float(outpost_score_for(chess.WHITE) - outpost_score_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of likely trapped pieces difference: (black_trapped_count - white_trapped_count) where trapped means no legal moves when it is that side\'s turn and attacked more than defended'
    import chess
    try:
        def trapped_count_for(color):
            cnt = 0
            # create a copy to safely set turn for move generation
            bcopy = board.copy()
            for sq, p in board.piece_map().items():
                if p.color != color or p.piece_type == chess.KING:
                    continue
                bcopy.turn = color
                moves = 0
                for m in bcopy.legal_moves:
                    if m.from_square == sq:
                        moves += 1
                        if moves > 0:
                            break
                attackers = len(board.attackers(not color, sq))
                defenders = len(board.attackers(color, sq))
                if moves == 0 and attackers > defenders:
                    cnt += 1
            return float(cnt)
        return float(trapped_count_for(chess.BLACK) - trapped_count_for(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Average distance of non-pawn pieces to own king difference: (white_avg_dist - black_avg_dist); higher = pieces further from defended king'
    import chess, math
    try:
        def avg_dist_for(color):
            k = board.king(color)
            if k is None:
                return 8.0
            dists = []
            for sq, p in board.piece_map().items():
                if p.color == color and p.piece_type != chess.PAWN and p.piece_type != chess.KING:
                    dists.append(chess.square_distance(sq, k))
            if not dists:
                return 8.0
            return float(sum(dists)/len(dists))
        return float(avg_dist_for(chess.WHITE) - avg_dist_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Enemy capture pressure score difference: (black_capture_pressure - white_capture_pressure), sum over attacks weighted by captured piece value'
    import chess
    try:
        val = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        def capture_pressure_for(color):
            total = 0.0
            for sq, p in board.piece_map().items():
                if p.color == color:
                    # what opponent pieces does this side attack?
                    # iterate opponent pieces and check if attacked
                    for osq, op in board.piece_map().items():
                        if op.color == (not color):
                            if sq in board.attackers(color, osq):  # attacker origin square attacks osq
                                total += val.get(op.piece_type, 0.0)
            return total
        return float(capture_pressure_for(chess.BLACK) - capture_pressure_for(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Queen proximity + pin risk difference: (black_threat_score - white_threat_score) where threat = (8 - min_dist_to_queen) + 2*pin_count'
    import chess
    try:
        def threat_score_against(color):
            # how threatened is the king of color by enemy queens/lines
            king_sq = board.king(color)
            if king_sq is None:
                return 0.0
            enemy = not color
            min_dist = 8
            for sq, p in board.piece_map().items():
                if p.color == enemy and p.piece_type == chess.QUEEN:
                    d = chess.square_distance(sq, king_sq)
                    if d < min_dist:
                        min_dist = d
            # compute simple pin count: sliding enemy piece with exactly one piece between it and king on same line
            pin_count = 0
            for sq, p in board.piece_map().items():
                if p.color == enemy and p.piece_type in (chess.ROOK, chess.BISHOP, chess.QUEEN):
                    # check collinearity
                    kr = chess.square_rank(king_sq); kf = chess.square_file(king_sq)
                    pr = chess.square_rank(sq); pf = chess.square_file(sq)
                    dr = pr - kr; df = pf - kf
                    if dr == 0:
                        step_r, step_f = 0, 1 if df < 0 else -1
                        between = []
                        for f in range(pf+step_f, kf, step_f):
                            between.append(chess.square(f, kr))
                    elif df == 0:
                        step_r, step_f = 1 if dr < 0 else -1, 0
                        between = []
                        for r in range(pr+step_r, kr, step_r):
                            between.append(chess.square(pf, r))
                    elif abs(dr) == abs(df):
                        step_r = 1 if dr < 0 else -1
                        step_f = 1 if df < 0 else -1
                        between = []
                        r, f = pr + step_r, pf + step_f
                        while (r != kr) and (f != kf):
                            between.append(chess.square(f, r))
                            r += step_r; f += step_f
                    else:
                        continue
                    # count pieces between
                    pieces_between = sum(1 for s in between if board.piece_at(s) is not None)
                    if pieces_between == 1:
                        pin_count += 1
            prox = (8 - min_dist) if min_dist < 8 else 0
            return float(prox + 2*pin_count)
        return float(threat_score_against(chess.WHITE) - threat_score_against(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in king pawn-shield strength (White minus Black); counts friendly pawns on the 3 files in the two ranks in front of each king'
    try:
        pm = board.piece_map()
        white_king = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        def shield_for(king_sq, color):
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            count = 0
            # For white king, "forward" is increasing rank; for black decreasing rank
            if color == chess.WHITE:
                target_ranks = [kr+1, kr+2]
            else:
                target_ranks = [kr-1, kr-2]
            for rf in range(kf-1, kf+2):
                if rf < 0 or rf > 7:
                    continue
                for rr in target_ranks:
                    if rr < 0 or rr > 7:
                        continue
                    sq = chess.square(rf, rr)
                    p = board.piece_at(sq)
                    if p is not None and p.piece_type == chess.PAWN and p.color == color:
                        count += 1
            return float(count)
        white_shield = shield_for(white_king, chess.WHITE)
        black_shield = shield_for(black_king, chess.BLACK)
        # normalize by up to 6 pawns per shield
        return float((white_shield - black_shield) / 6.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn advancement score (White minus Black); each passed pawn weighted by its advancement toward promotion (0..1)'
    try:
        pm = board.piece_map()
        white_pawns = [sq for sq, p in pm.items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        black_pawns = [sq for sq, p in pm.items() if p.piece_type == chess.PAWN and p.color == chess.BLACK]
        def is_passed(sq, color, enemy_pawns):
            sf = chess.square_file(sq)
            sr = chess.square_rank(sq)
            if color == chess.WHITE:
                for ep in enemy_pawns:
                    ef = chess.square_file(ep); er = chess.square_rank(ep)
                    if abs(ef - sf) <= 1 and er > sr:
                        return False
                return True
            else:
                for ep in enemy_pawns:
                    ef = chess.square_file(ep); er = chess.square_rank(ep)
                    if abs(ef - sf) <= 1 and er < sr:
                        return False
                return True
        wscore = 0.0
        for sq in white_pawns:
            if is_passed(sq, chess.WHITE, black_pawns):
                # advancement: rank 0..7 -> scale 0..1
                adv = chess.square_rank(sq) / 7.0
                wscore += adv + 0.25  # slight base bonus for being passed
        bscore = 0.0
        for sq in black_pawns:
            if is_passed(sq, chess.BLACK, white_pawns):
                adv = (7 - chess.square_rank(sq)) / 7.0
                bscore += adv + 0.25
        return float(wscore - bscore)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rooks on the opponent 7th rank difference (White minus Black); rooks on 7th rank (rank index 6 for White, 1 for Black) are counted as strong'
    try:
        pm = board.piece_map()
        white_rooks_7 = 0
        black_rooks_7 = 0
        for sq, p in pm.items():
            if p.piece_type == chess.ROOK:
                r = chess.square_rank(sq)
                if p.color == chess.WHITE and r == 6:
                    white_rooks_7 += 1
                if p.color == chess.BLACK and r == 1:
                    black_rooks_7 += 1
        return float(white_rooks_7 - black_rooks_7)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn-structure penalty difference (Black penalty minus White penalty): doubled + isolated pawns counted per side; positive means White has relatively better pawn structure'
    try:
        pm = board.piece_map()
        def pawn_penalty(color):
            files = {f: 0 for f in range(8)}
            pawns = [sq for sq, p in pm.items() if p.piece_type == chess.PAWN and p.color == color]
            for sq in pawns:
                files[chess.square_file(sq)] += 1
            doubled = sum(max(0, cnt-1) for cnt in files.values())
            isolated = 0
            for f in range(8):
                if files[f] > 0:
                    left = files.get(f-1, 0)
                    right = files.get(f+1, 0)
                    if left == 0 and right == 0:
                        isolated += files[f]
            return float(doubled + isolated)
        wp = pawn_penalty(chess.WHITE)
        bp = pawn_penalty(chess.BLACK)
        # return black - white so positive means White is structurally better
        return float(bp - wp)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Knight outpost advantage (White minus Black): counts advanced central knights not attackable by enemy pawns'
    try:
        pm = board.piece_map()
        def outpost_count(color):
            cnt = 0.0
            enemy = chess.BLACK if color == chess.WHITE else chess.WHITE
            for sq, p in pm.items():
                if p.piece_type == chess.KNIGHT and p.color == color:
                    f = chess.square_file(sq); r = chess.square_rank(sq)
                    # central files c-f (2..5); advanced ranks: for White >=4, Black <=3
                    if f < 2 or f > 5:
                        continue
                    if color == chess.WHITE:
                        if r < 4:
                            continue
                    else:
                        if r > 3:
                            continue
                    # check if attacked by any enemy pawn
                    attackers = board.attackers(enemy, sq)
                    pawn_attack = False
                    for a in attackers:
                        ap = board.piece_at(a)
                        if ap is not None and ap.piece_type == chess.PAWN and ap.color == enemy:
                            pawn_attack = True
                            break
                    if not pawn_attack:
                        cnt += 1.0
            return cnt
        return float(outpost_count(chess.WHITE) - outpost_count(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pinned pieces difference (White pinned pieces count minus Black pinned pieces count); detects pieces between king and an enemy sliding piece'
    try:
        pm = board.piece_map()
        white_king = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        def count_pinned(color, king_sq):
            if king_sq is None:
                return 0.0
            cnt = 0
            for sq, p in pm.items():
                if p.color != color or p.piece_type == chess.KING:
                    continue
                kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
                pf = chess.square_file(sq); pr = chess.square_rank(sq)
                df = pf - kf; dr = pr - kr
                if df == 0 and dr == 0:
                    continue
                # check alignment
                maxd = max(abs(df), abs(dr))
                if not (df == 0 or dr == 0 or abs(df) == abs(dr)):
                    continue
                step_f = 0 if df == 0 else (df // maxd)
                step_r = 0 if dr == 0 else (dr // maxd)
                # walk from king towards the piece, ensure piece is first encountered (no other piece between king and this)
                cur_f = kf + step_f; cur_r = kr + step_r
                blocked_before = False
                while (cur_f != pf or cur_r != pr):
                    if cur_f < 0 or cur_f > 7 or cur_r < 0 or cur_r > 7:
                        blocked_before = True; break
                    sq_check = chess.square(cur_f, cur_r)
                    if sq_check in pm and sq_check != sq:
                        blocked_before = True
                        break
                    cur_f += step_f; cur_r += step_r
                if blocked_before:
                    continue
                # now look beyond the piece in same direction to find first piece
                cur_f = pf + step_f; cur_r = pr + step_r
                found = None
                while 0 <= cur_f <= 7 and 0 <= cur_r <= 7:
                    sq_check = chess.square(cur_f, cur_r)
                    if sq_check in pm:
                        found = pm[sq_check]
                        break
                    cur_f += step_f; cur_r += step_r
                if found is None:
                    continue
                # if found is enemy sliding piece of appropriate type, piece at sq is pinned
                if found.color != color:
                    if (step_f == 0 or step_r == 0) and (found.piece_type in (chess.ROOK, chess.QUEEN)):
                        cnt += 1.0
                    elif abs(step_f) == abs(step_r) and (found.piece_type in (chess.BISHOP, chess.QUEEN)):
                        cnt += 1.0
            return cnt
        w_pinned = count_pinned(chess.WHITE, white_king)
        b_pinned = count_pinned(chess.BLACK, black_king)
        return float(w_pinned - b_pinned)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rook control of open/semi-open files (White minus Black); open file = no pawns, semi-open = no friendly pawns on that file; open=1.0, semi-open=0.5 per rook'
    try:
        pm = board.piece_map()
        pawn_files = {f: {'white':0, 'black':0} for f in range(8)}
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                pawn_files[chess.square_file(sq)]['white' if p.color==chess.WHITE else 'black'] += 1
        white_score = 0.0
        black_score = 0.0
        for sq, p in pm.items():
            if p.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                wf = pawn_files[f]['white']; bf = pawn_files[f]['black']
                if wf == 0 and bf == 0:
                    val = 1.0
                elif (p.color == chess.WHITE and wf == 0) or (p.color == chess.BLACK and bf == 0):
                    val = 0.5
                else:
                    val = 0.0
                if p.color == chess.WHITE:
                    white_score += val
                else:
                    black_score += val
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Central control difference (White minus Black): number of attacked squares in the 4x4 central block (files c-f, ranks 3-6) attacked by each side'
    try:
        files = range(2, 6)  # c..f -> 2..5 but inclusive edges of central block use 2..5; choose 2..5 ranks 2..5 or 2..5?
        ranks = range(2, 6)  # using ranks 3..6 (0-indexed 2..5) gives central 4x4
        w = 0
        b = 0
        for f in files:
            for r in ranks:
                sq = chess.square(f, r)
                if board.is_attacked_by(chess.WHITE, sq):
                    w += 1
                if board.is_attacked_by(chess.BLACK, sq):
                    b += 1
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Sliding-piece pressure on kings (White advantage): number of sliding attackers (rook/bishop/queen) aiming at the opponent king minus vice versa'
    try:
        pm = board.piece_map()
        wking = next((sq for sq, p in pm.items() if p.piece_type==chess.KING and p.color==chess.WHITE), None)
        bking = next((sq for sq, p in pm.items() if p.piece_type==chess.KING and p.color==chess.BLACK), None)
        def sliding_attackers_of_king(king_sq, attacker_color):
            if king_sq is None:
                return 0
            attackers = board.attackers(attacker_color, king_sq)
            cnt = 0
            for a in attackers:
                p = board.piece_at(a)
                if p is None:
                    continue
                if p.piece_type in (chess.ROOK, chess.BISHOP, chess.QUEEN):
                    cnt += 1
            return cnt
        white_on_black = sliding_attackers_of_king(bking, chess.WHITE)
        black_on_white = sliding_attackers_of_king(wking, chess.BLACK)
        return float(white_on_black - black_on_white)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Minor-piece centralization (White minus Black): counts knights and bishops on the central 4x4 block (files c-f, ranks 3-6), bishops and knights weighted equally'
    try:
        pm = board.piece_map()
        central_files = range(2, 6)
        central_ranks = range(2, 6)
        w = 0.0
        b = 0.0
        for sq, p in pm.items():
            if p.piece_type in (chess.KNIGHT, chess.BISHOP):
                f = chess.square_file(sq); r = chess.square_rank(sq)
                if f in central_files and r in central_ranks:
                    if p.color == chess.WHITE:
                        w += 1.0
                    else:
                        b += 1.0
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn shield strength difference: counts friendly pawns in front of each king within one file left/right and one or two ranks ahead (White - Black)'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        def pawns_in_shield(king_sq, color):
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            count = 0
            # direction: white pawns are ahead if rank increases, black pawns if rank decreases
            directions = [1, 2] if color == chess.WHITE else [-1, -2]
            for df in (-1, 0, 1):
                for d_rank in directions:
                    rf = kf + df
                    rr = kr + d_rank
                    if 0 <= rf <= 7 and 0 <= rr <= 7:
                        sq = chess.square(rf, rr)
                        piece = board.piece_at(sq)
                        if piece is not None and piece.piece_type == chess.PAWN and piece.color == color:
                            count += 1
            return float(count)
        w_shield = pawns_in_shield(white_king_sq, chess.WHITE)
        b_shield = pawns_in_shield(black_king_sq, chess.BLACK)
        return float(w_shield - b_shield)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rook open/semi-open file advantage: (#rooks on fully open files) + 0.5*(#rooks on semi-open files) difference (White - Black)'
    try:
        files_have_white_pawn = [False]*8
        files_have_black_pawn = [False]*8
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if p.color == chess.WHITE:
                    files_have_white_pawn[f] = True
                else:
                    files_have_black_pawn[f] = True
        w_score = 0.0
        b_score = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                has_any = files_have_white_pawn[f] or files_have_black_pawn[f]
                has_friendly = files_have_white_pawn[f] if p.color == chess.WHITE else files_have_black_pawn[f]
                # open file: no pawns of either color
                if not has_any:
                    if p.color == chess.WHITE:
                        w_score += 1.0
                    else:
                        b_score += 1.0
                # semi-open: no friendly pawns but enemy pawns exist
                elif not has_friendly:
                    if p.color == chess.WHITE:
                        w_score += 0.5
                    else:
                        b_score += 0.5
        return float(w_score - b_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Advanced piece pressure: count of non-pawn white pieces on rank 7 (7th rank, index 6) minus black pieces on rank 2 (index 1)'
    try:
        w_count = 0
        b_count = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                continue
            r = chess.square_rank(sq)
            if p.color == chess.WHITE and r == 6:
                w_count += 1
            if p.color == chess.BLACK and r == 1:
                b_count += 1
        return float(w_count - b_count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King attack pressure difference: weighted sum of opponent attackers on king (weights: pawn=1,knight=3,bishop=3,rook=5,queen=9); (White attacking black king) - (Black attacking white king)'
    try:
        weights = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        pm = board.piece_map()
        white_king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        def attack_value_on(square, by_color):
            if square is None:
                return 0.0
            attackers = board.attackers(by_color, square)
            total = 0.0
            for a in attackers:
                piece = board.piece_at(a)
                if piece is None:
                    continue
                total += weights.get(piece.piece_type, 0.0)
            return total
        val_white_on_black = attack_value_on(black_king_sq, chess.WHITE)
        val_black_on_white = attack_value_on(white_king_sq, chess.BLACK)
        return float(val_white_on_black - val_black_on_white)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Hanging pieces difference: count of pieces attacked by opponent and not defended (White - Black)'
    try:
        pm = board.piece_map()
        w_hanging = 0
        b_hanging = 0
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                continue
            attackers = board.attackers(not p.color, sq)
            defenders = board.attackers(p.color, sq)
            if len(attackers) > 0 and len(defenders) == 0:
                if p.color == chess.WHITE:
                    w_hanging += 1
                else:
                    b_hanging += 1
        return float(w_hanging - b_hanging)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King mobility difference: count of safe adjacent squares for each king (not occupied by friendly piece and not attacked by opponent). Returns White - Black'
    try:
        pm = board.piece_map()
        def king_mobility(color):
            king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == color), None)
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            cnt = 0
            opp = not color
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    nf = kf + df
                    nr = kr + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        s = chess.square(nf, nr)
                        occ = board.piece_at(s)
                        if occ is not None and occ.color == color:
                            continue
                        # square is "safe" if not attacked by opponent
                        try:
                            attacked = board.is_attacked_by(opp, s)
                        except Exception:
                            attacked = False
                        if not attacked:
                            cnt += 1
            return float(cnt)
        return float(king_mobility(chess.WHITE) - king_mobility(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Current king attackers count difference: number of pieces currently attacking the king (White attacking black king) - (Black attacking white king)'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        w_on_black = float(len(board.attackers(chess.WHITE, black_king_sq))) if black_king_sq is not None else 0.0
        b_on_white = float(len(board.attackers(chess.BLACK, white_king_sq))) if white_king_sq is not None else 0.0
        return float(w_on_black - b_on_white)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn potential: weighted count of passed pawns (advanced white pawns minus advanced black pawns). Each passed pawn weighted by normalized rank advancement [0..1]'
    try:
        pm = board.piece_map()
        w_score = 0.0
        b_score = 0.0
        for sq, p in pm.items():
            if p.piece_type != chess.PAWN:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                # check for any black pawns on files f-1..f+1 with rank > r
                blocked = False
                for bf_sq, bp in pm.items():
                    if bp.piece_type == chess.PAWN and bp.color == chess.BLACK:
                        bf = chess.square_file(bf_sq)
                        br = chess.square_rank(bf_sq)
                        if abs(bf - f) <= 1 and br > r:
                            blocked = True
                            break
                if not blocked:
                    adv = r / 7.0  # 0..1, 0 at rank0 (rare) to 1 at rank7
                    w_score += 1.0 + adv
            else:
                blocked = False
                for wf_sq, wp in pm.items():
                    if wp.piece_type == chess.PAWN and wp.color == chess.WHITE:
                        wf = chess.square_file(wf_sq)
                        wr = chess.square_rank(wf_sq)
                        if abs(wf - f) <= 1 and wr < r:
                            blocked = True
                            break
                if not blocked:
                    adv = (7 - r) / 7.0
                    b_score += 1.0 + adv
        return float(w_score - b_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Piece coordination index difference: sum of inverse distances between pairs of non-pawn pieces of the same color (White - Black). Higher means more tightly coordinated'
    try:
        pm = board.piece_map()
        from itertools import combinations
        def coord_score(color):
            squares = [sq for sq, p in pm.items() if p.color == color and p.piece_type != chess.PAWN]
            score = 0.0
            for a, b in combinations(squares, 2):
                d = chess.square_distance(a, b)
                # add small epsilon to avoid divide by zero
                score += 1.0 / (1.0 + float(d))
            return score
        return float(coord_score(chess.WHITE) - coord_score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of direct attackers to each king (Black->White minus White->Black)'
    pm = board.piece_map()
    white_king = None
    black_king = None
    for sq, pc in pm.items():
