def feature(board: chess.Board) -> float:
    'Queen proximity tropism: (white queen closeness to black king) - (black queen closeness to white king); closeness = 9 / (1 + square_distance)'
    try:
        def closest_queen_to_king(queen_color: bool, king_color: bool) -> float:
            ksq = None
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == king_color:
                    ksq = sq; break
            if ksq is None:
                return 0.0
            best = 0.0
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.QUEEN and p.color == queen_color:
                    d = chess.square_distance(sq, ksq)
                    score = 9.0 / (1.0 + float(d))
                    if score > best:
                        best = score
            return best
        wq = closest_queen_to_king(chess.WHITE, chess.BLACK)
        bq = closest_queen_to_king(chess.BLACK, chess.WHITE)
        return float(wq - bq)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King pawn-shield differential: (white pawn shield strength) - (black pawn shield strength); higher is better for White'
    try:
        import chess
    except Exception:
        pass
    # piece values for weighting attackers if needed
    pawn = chess.PAWN
    # find kings
    white_king_sq = None
    black_king_sq = None
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                white_king_sq = sq
            else:
                black_king_sq = sq
    def pawn_shield_strength(king_sq, color):
        if king_sq is None:
            return 0.0
        strength = 0.0
        kr = chess.square_rank(king_sq)
        kf = chess.square_file(king_sq)
        # For white, pawn shield is ranks ahead (higher ranks); for black, ranks behind (lower ranks)
        directions = [1] if color == chess.WHITE else [-1]
        # check up to two ranks in front of king and adjacent files
        for d in directions:
            for dr in (1, 2):
                r = kr + d * dr
                if not (0 <= r <= 7):
                    continue
                for df in (-1, 0, 1):
                    f = kf + df
                    if not (0 <= f <= 7):
                        continue
                    sq = chess.square(f, r)
                    p = board.piece_at(sq)
                    if p is not None and p.piece_type == chess.PAWN and p.color == color:
                        # pawns closer give more shield
                        strength += 1.0 / dr
        return strength
    w_shield = pawn_shield_strength(white_king_sq, chess.WHITE)
    b_shield = pawn_shield_strength(black_king_sq, chess.BLACK)
    return float(w_shield - b_shield)

def feature(board: chess.Board) -> float:
    'Mobility differential: (legal moves available to White) - (legal moves available to Black), normalized by 10'
    try:
