    try:
        white_moves = 0
        black_moves = 0
        # count for current turn
        if board.turn == chess.WHITE:
            white_moves = board.legal_moves.count()
            bcopy = board.copy()
            bcopy.turn = chess.BLACK
            black_moves = bcopy.legal_moves.count()
        else:
            black_moves = board.legal_moves.count()
            wcopy = board.copy()
            wcopy.turn = chess.WHITE
            white_moves = wcopy.legal_moves.count()
    except Exception:
        # safe fallback
        white_moves = 0
        black_moves = 0
    # normalize to keep values small
    return float((white_moves - black_moves) / 10.0)

def feature(board: chess.Board) -> float:
