def feature(board: chess.Board) -> float:
    'Bishop-pair and opposite-color advantage: (white advantage) - (black advantage); positive if White has strong bishop situation'
    try:
        import chess
    except Exception:
        pass
    def bishop_colors(color):
        cols = set()
        count = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.BISHOP and p.color == color:
                count += 1
                # compute parity of square color: True for light, False for dark
                parity = (chess.square_rank(sq) + chess.square_file(sq)) % 2
                cols.add(parity)
        return count, cols
    wc, wcols = bishop_colors(chess.WHITE)
    bc, bcols = bishop_colors(chess.BLACK)
    score = 0.0
    # bishop pair bonus
    if wc >= 2:
        score += 0.6
    if bc >= 2:
        score -= 0.6
    # bonus for bishops on both colors (flexibility)
    if len(wcols) == 2:
        score += 0.4
    if len(bcols) == 2:
        score -= 0.4
    return float(score)

def feature(board: chess.Board) -> float:
    'Pawn-island differential: (white pawn islands) - (black pawn islands), negative is worse for White'
    try:
