                files_with_pawn[chess.square_file(sq)] = True
        islands = 0
        i = 0
        while i < 8:
            if files_with_pawn[i]:
                islands += 1
                while i < 8 and files_with_pawn[i]:
                    i += 1
            else:
                i += 1
        return islands
    w_islands = pawn_islands(chess.WHITE)
    b_islands = pawn_islands(chess.BLACK)
    # fewer islands is better => return white minus black (higher better)
    return float((b_islands - w_islands))

def feature(board: chess.Board) -> float:
    'Piece coordination: (average pairwise distance among White non-pawn pieces) subtracted from Black; positive => White pieces more tightly clustered'
    try:
        import chess
    except Exception:
        pass
    def avg_pair_distance(color):
        sqs = [sq for sq,p in board.piece_map().items() if p.color==color and p.piece_type != chess.PAWN and p.piece_type != chess.KING]
        if len(sqs) <= 1:
            return 8.0  # large distance if isolated / no pieces
        total = 0.0
        count = 0
        for i in range(len(sqs)):
            for j in range(i+1, len(sqs)):
                total += chess.square_distance(sqs[i], sqs[j])
                count += 1
        return total / count if count>0 else 8.0
    w_avg = avg_pair_distance(chess.WHITE)
    b_avg = avg_pair_distance(chess.BLACK)
    # positive if white pieces are more tightly grouped (bigger b_avg - w_avg)
    return float(b_avg - w_avg)

def feature(board: chess.Board) -> float:
    'King-adjacent attack pressure: (sum of attacker weights to squares around Black king) - (same for White king); weights: pawn=0.8,knight=2.8,bishop=3.0,rook=4.8,queen=8.5'
    try:
        import chess
    except Exception:
        pass
    weights = {chess.PAWN:0.8, chess.KNIGHT:2.8, chess.BISHOP:3.0, chess.ROOK:4.8, chess.QUEEN:8.5, chess.KING:0.0}
    # locate kings
    white_king_sq = None
    black_king_sq = None
    for sq,p in board.piece_map().items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                white_king_sq = sq
            else:
                black_king_sq = sq
    def pressure_on_king(king_sq, attacker_color):
        if king_sq is None:
            return 0.0
        pts = 0.0
        kr = chess.square_rank(king_sq)
        kf = chess.square_file(king_sq)
        for dr in (-1,0,1):
            for df in (-1,0,1):
                r = kr + dr
                f = kf + df
                if not (0 <= r <= 7 and 0 <= f <= 7):
                    continue
                sq = chess.square(f, r)
                attackers = board.attackers(attacker_color, sq)
                for a in attackers:
                    p = board.piece_at(a)
                    if p is None:
                        continue
                    pts += weights.get(p.piece_type, 0.0)
        return pts
    white_pressure_on_black = pressure_on_king(black_king_sq, chess.WHITE)
    black_pressure_on_white = pressure_on_king(white_king_sq, chess.BLACK)
    return float(white_pressure_on_black - black_pressure_on_white)

def feature(board: chess.Board) -> float:
    'Endgame king-centralization weighted score: (black king distance to center - white king distance to center) * endgame_weight; endgame_weight ~1 if low material else 0.2'
    try:
        import chess
    except Exception:
        pass
    # compute total material excluding kings (in pawn units)
    values = {chess.PAWN:1.0, chess.KNIGHT:3.2, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0}
    total = 0.0
    white_mat = 0.0
    black_mat = 0.0
    white_king_sq = None
    black_king_sq = None
    for sq,p in board.piece_map().items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                white_king_sq = sq
            else:
                black_king_sq = sq
            continue
        v = values.get(p.piece_type, 0.0)
        total += v
        if p.color == chess.WHITE:
            white_mat += v
        else:
            black_mat += v
    # endgame weight: stronger if total material small (<12 pawns)
    endgame_weight = 1.0 if total <= 12.0 else 0.2
    # center squares are d4,e4,d5,e5 center coords (3,3),(4,3),(3,4),(4,4)
    def king_center_distance(king_sq):
        if king_sq is None:
            return 8.0
        kr = chess.square_rank(king_sq)
        kf = chess.square_file(king_sq)
        # distance to nearest center square (Manhattan)
        dists = []
        for cf, cr in ((3,3),(4,3),(3,4),(4,4)):
            dists.append(abs(kf-cf)+abs(kr-cr))
        return min(dists)
    wd = king_center_distance(white_king_sq)
    bd = king_center_distance(black_king_sq)
    # positive means White king more centralized (bd - wd positive)
    return float((bd - wd) * endgame_weight)

def feature(board: chess.Board) -> float:
