    # Cap and normalize to avoid extreme values
    return float(min(moves, 100)) / 100.0

def feature(board: chess.Board) -> float:
    'Distance between the two kings (Manhattan distance 0..14) normalized to 0..1'
    pm = board.piece_map()
    white_king_sq = None
    black_king_sq = None
    for sq, p in pm.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                white_king_sq = sq
            else:
                black_king_sq = sq
    if white_king_sq is None or black_king_sq is None:
        return 0.0
    d = chess.square_distance(white_king_sq, black_king_sq)
    # Max possible Manhattan distance on 8x8 is 14
    return float(d) / 14.0

def feature(board: chess.Board) -> float:
    'Rook activity on open/semi-open files: (white_score - black_score), open=1, semi-open=0.5'
    pm = board.piece_map()
    # Determine pawn occupancy per file
    pawn_files_white = [False] * 8
    pawn_files_black = [False] * 8
    for sq, p in pm.items():
        if p.piece_type == chess.PAWN:
            f = chess.square_file(sq)
            if p.color == chess.WHITE:
                pawn_files_white[f] = True
            else:
                pawn_files_black[f] = True
    white_score = 0.0
    black_score = 0.0
    for sq, p in pm.items():
        if p.piece_type == chess.ROOK:
            f = chess.square_file(sq)
            # open file: no pawns of either side
            if not pawn_files_white[f] and not pawn_files_black[f]:
                if p.color == chess.WHITE:
                    white_score += 1.0
                else:
                    black_score += 1.0
            # semi-open: pawns only of opponent absent
            elif not pawn_files_white[f] and pawn_files_black[f]:
                if p.color == chess.WHITE:
                    white_score += 0.5
            elif pawn_files_white[f] and not pawn_files_black[f]:
                if p.color == chess.BLACK:
                    black_score += 0.5
    return white_score - black_score

def feature(board: chess.Board) -> float:
    'Bishop effectiveness: bishop-pair bonus minus penalty for bishops blocked by many same-color pawns; returns (white - black)'
    pm = board.piece_map()
    def pawn_color_counts_on_square_color(color):
        # returns dict color_of_squares -> count of friendly pawns on light squares for that color
        pawn_on_light = {}
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN and p.color == color:
                light = ((chess.square_file(sq) + chess.square_rank(sq)) % 2 == 0)
                pawn_on_light.setdefault(light, 0)
                pawn_on_light[light] += 1
        return pawn_on_light
    white_pawn_counts = pawn_color_counts_on_square_color(chess.WHITE)
    black_pawn_counts = pawn_color_counts_on_square_color(chess.BLACK)
    white_bishops = []
    black_bishops = []
    for sq, p in pm.items():
        if p.piece_type == chess.BISHOP:
            light = ((chess.square_file(sq) + chess.square_rank(sq)) % 2 == 0)
            if p.color == chess.WHITE:
                white_bishops.append(light)
            else:
                black_bishops.append(light)
    def bishop_score(bishops, pawn_counts):
        if not bishops:
            return 0.0
        score = 0.0
        if len(bishops) >= 2:
            score += 0.75  # bishop pair bonus
        for light in bishops:
            same_color_pawns = pawn_counts.get(light, 0)
            # Penalty for being "bad" (many friendly pawns on same color squares)
            score -= 0.12 * min(same_color_pawns, 6)
        return score
    wscore = bishop_score(white_bishops, white_pawn_counts)
    bscore = bishop_score(black_bishops, black_pawn_counts)
    return wscore - bscore

def feature(board: chess.Board) -> float:
    'Rooks on the 7th (for white) or 2nd (for black) rank: (white_count - black_count)'
    pm = board.piece_map()
