            return True
        else:
            for opp_sq, opp in bd.piece_map().items():
                if opp.piece_type == chess.PAWN and opp.color == chess.WHITE:
                    of = chess.square_file(opp_sq)
                    orank = chess.square_rank(opp_sq)
                    if abs(of - f) <= 1 and orank < r:
                        return False
            return True
    white_count = 0
    black_count = 0
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.PAWN and is_passed(board, sq):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            # look for rooks on same file
            for sq2, p2 in board.piece_map().items():
                if p2.piece_type == chess.ROOK and p2.color == p.color:
                    rf = chess.square_file(sq2)
                    rr = chess.square_rank(sq2)
                    if rf == f:
                        if p.color == chess.WHITE and rr < r:
                            white_count += 1
                            break
                        if p.color == chess.BLACK and rr > r:
                            black_count += 1
                            break
    return float(white_count - black_count)

