    for sq, p in board.piece_map().items():
        if p.piece_type == chess.PAWN and is_passed(board, sq):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if p.color == chess.WHITE and bking is not None:
                kr = chess.square_rank(bking)
                kf = chess.square_file(bking)
                # king directly in front
                if kf == f and kr == r + 1:
                    wc += 1
                # also consider king within one square ahead (blockading)
                elif kr >= r and abs(kf - f) <= 1 and (kr - r) <= 1:
                    wc += 1
            if p.color == chess.BLACK and wking is not None:
                kr = chess.square_rank(wking)
                kf = chess.square_file(wking)
                if kf == f and kr == r - 1:
                    bc += 1
                elif kr <= r and abs(kf - f) <= 1 and (r - kr) <= 1:
                    bc += 1
    return float(wc - bc)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in number of rooks placed on open files (no pawns on that file)'
    pawn_files = set()
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.PAWN:
            pawn_files.add(chess.square_file(sq))
    w = 0
    b = 0
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.ROOK:
            f = chess.square_file(sq)
            if f not in pawn_files:
                if p.color == chess.WHITE:
                    w += 1
                else:
                    b += 1
    return float(w - b)

def feature(board: chess.Board) -> float:
    'Maximum pawn promotion progress for White minus Black: fraction to promotion of the most advanced pawn for each side (range -1..1)'
    w_max = 0.0
    b_max = 0.0
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.PAWN:
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                prog = r / 7.0
                if prog > w_max:
                    w_max = prog
            else:
                prog = (7 - r) / 7.0
                if prog > b_max:
                    b_max = prog
    return float(w_max - b_max)

def feature(board: chess.Board) -> float:
    'King-safety ring attack difference: sum of opponent attackers on the 8 neighboring squares around each king, White - Black'
    def ring_squares(sq):
        if sq is None:
            return []
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        res = []
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                if df == 0 and dr == 0:
                    continue
                nf = f + df
                nr = r + dr
                if 0 <= nf <= 7 and 0 <= nr <= 7:
                    res.append(nr * 8 + nf)
        return res
    wking = None
    bking = None
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                wking = sq
            else:
                bking = sq
    w_attacks = 0
    b_attacks = 0
    if wking is not None:
        for sq in ring_squares(wking):
            # attackers by black to this square
            try:
                if board.is_attacked_by(chess.BLACK, sq):
                    # count number of attackers to be more informative
                    w_attacks += len(board.attackers(chess.BLACK, sq))
            except Exception:
                pass
    if bking is not None:
        for sq in ring_squares(bking):
            try:
                if board.is_attacked_by(chess.WHITE, sq):
                    b_attacks += len(board.attackers(chess.WHITE, sq))
            except Exception:
                pass
    return float(b_attacks * -1 + w_attacks)  # White - Black

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in number of rooks occupying the opponent seventh rank (White rooks on rank 6, Black rooks on rank 1)'
    w = 0
