                b += 1
    return float(w - b)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in number of pawns on the seventh rank (one step from promotion) that are defended by a rook/king/pawn (supported advanced pawns)'
    w = 0
    b = 0
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.PAWN:
            r = chess.square_rank(sq)
            color = p.color
            if (color == chess.WHITE and r == 6) or (color == chess.BLACK and r == 1):
                # any friendly rook/king/pawn attacking this square?
                attackers = []
                try:
                    attackers = board.attackers(color, sq)
                except Exception:
                    attackers = set()
                supported = False
                for a in attackers:
                    ap = board.piece_at(a)
                    if ap is None:
                        continue
                    if ap.color == color and ap.piece_type in (chess.ROOK, chess.KING, chess.PAWN):
                        supported = True
                        break
                if supported:
                    if color == chess.WHITE:
                        w += 1
                    else:
                        b += 1
    return float(w - b)

def feature(board: chess.Board) -> float:
    'Cutoff advantage: difference (White - Black) counting passed pawns for which a friendly rook is strictly closer to the promotion square than the opposing king (helps secure promotion)'
    def is_passed(bd, sq):
        piece = bd.piece_at(sq)
        if piece is None or piece.piece_type != chess.PAWN:
            return False
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if piece.color == chess.WHITE:
            for opp_sq, opp in bd.piece_map().items():
                if opp.piece_type == chess.PAWN and opp.color == chess.BLACK:
                    of = chess.square_file(opp_sq)
                    orank = chess.square_rank(opp_sq)
                    if abs(of - f) <= 1 and orank > r:
                        return False
            return True
        else:
            for opp_sq, opp in bd.piece_map().items():
                if opp.piece_type == chess.PAWN and opp.color == chess.WHITE:
                    of = chess.square_file(opp_sq)
                    orank = chess.square_rank(opp_sq)
                    if abs(of - f) <= 1 and orank < r:
                        return False
            return True
    w = 0
    b = 0
    # find kings
    wking = None
    bking = None
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                wking = sq
            else:
                bking = sq
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.PAWN and is_passed(board, sq):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                prom_sq = (7 * 8) + f  # rank 7
                king_dist = 8 if bking is None else chess.square_distance(bking, prom_sq)
                # distance to closest friendly rook
                rook_dist = 99
                for s2, p2 in board.piece_map().items():
                    if p2.piece_type == chess.ROOK and p2.color == chess.WHITE:
                        d = chess.square_distance(s2, prom_sq)
                        if d < rook_dist:
                            rook_dist = d
                if rook_dist + 1 < king_dist:
                    w += 1
            else:
                prom_sq = (0 * 8) + f  # rank 0
                king_dist = 8 if wking is None else chess.square_distance(wking, prom_sq)
                rook_dist = 99
                for s2, p2 in board.piece_map().items():
                    if p2.piece_type == chess.ROOK and p2.color == chess.BLACK:
                        d = chess.square_distance(s2, prom_sq)
                        if d < rook_dist:
                            rook_dist = d
                if rook_dist + 1 < king_dist:
                    b += 1
    return float(w - b)

def feature(board: chess.Board) -> float:
    'White passed pawn count minus Black passed pawn count (simple passed-pawn detector)'
    def is_passed(sq, color):
        if not board.piece_at(sq) or board.piece_at(sq).piece_type != chess.PAWN:
            return False
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            # squares ahead on same or adjacent files
            for af in range(max(0, f-1), min(7, f+1)+1):
                for ar in range(r+1, 8):
                    p = board.piece_at(chess.square(af, ar))
                    if p and p.piece_type == chess.PAWN and p.color == chess.BLACK:
                        return False
            return True
        else:
            for af in range(max(0, f-1), min(7, f+1)+1):
                for ar in range(0, r):
                    p = board.piece_at(chess.square(af, ar))
                    if p and p.piece_type == chess.PAWN and p.color == chess.WHITE:
                        return False
            return True
    white = 0
    black = 0
    for sq, piece in board.piece_map().items():
        if piece.piece_type == chess.PAWN:
            if piece.color == chess.WHITE and is_passed(sq, chess.WHITE):
                white += 1
            if piece.color == chess.BLACK and is_passed(sq, chess.BLACK):
                black += 1
    return float(white - black)

def feature(board: chess.Board) -> float:
    'Difference (black_distance - white_distance) of nearest friendly rook distance to the most advanced passed pawn (smaller is better for that side)'
    # find most advanced passed pawn for each side
    def is_passed(sq, color):
        if not board.piece_at(sq) or board.piece_at(sq).piece_type != chess.PAWN:
            return False
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            for af in range(max(0, f-1), min(7, f+1)+1):
                for ar in range(r+1, 8):
                    p = board.piece_at(chess.square(af, ar))
                    if p and p.piece_type == chess.PAWN and p.color == chess.BLACK:
                        return False
            return True
        else:
            for af in range(max(0, f-1), min(7, f+1)+1):
                for ar in range(0, r):
                    p = board.piece_at(chess.square(af, ar))
                    if p and p.piece_type == chess.PAWN and p.color == chess.WHITE:
                        return False
            return True
    def min_rook_dist_to_sq(color, target_sq):
        best = 999
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.ROOK and piece.color == color:
                d = chess.square_distance(sq, target_sq)
                if d < best:
                    best = d
        return best
    white_most = None
    black_most = None
    # choose most advanced passed pawn (highest rank for white, lowest for black)
    for sq, piece in board.piece_map().items():
        if piece.piece_type == chess.PAWN:
            if piece.color == chess.WHITE and is_passed(sq, chess.WHITE):
                if white_most is None or chess.square_rank(sq) > chess.square_rank(white_most):
                    white_most = sq
            if piece.color == chess.BLACK and is_passed(sq, chess.BLACK):
                if black_most is None or chess.square_rank(sq) < chess.square_rank(black_most):
                    black_most = sq
    white_dist = min_rook_dist_to_sq(chess.WHITE, white_most) if white_most is not None else 99
    black_dist = min_rook_dist_to_sq(chess.BLACK, black_most) if black_most is not None else 99
    # positive means white rooks are relatively closer to their passed pawn
    return float(black_dist - white_dist)

def feature(board: chess.Board) -> float:
    'Promotion urgency difference: (black moves to promotion) - (white moves to promotion) for the most advanced passed pawns'
    def is_passed(sq, color):
        if not board.piece_at(sq) or board.piece_at(sq).piece_type != chess.PAWN:
            return False
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            for af in range(max(0, f-1), min(7, f+1)+1):
                for ar in range(r+1, 8):
                    p = board.piece_at(chess.square(af, ar))
                    if p and p.piece_type == chess.PAWN and p.color == chess.BLACK:
                        return False
            return True
        else:
            for af in range(max(0, f-1), min(7, f+1)+1):
                for ar in range(0, r):
                    p = board.piece_at(chess.square(af, ar))
                    if p and p.piece_type == chess.PAWN and p.color == chess.WHITE:
                        return False
            return True
    white_min_moves = 100
    black_min_moves = 100
    for sq, piece in board.piece_map().items():
        if piece.piece_type == chess.PAWN:
            r = chess.square_rank(sq)
            if piece.color == chess.WHITE and is_passed(sq, chess.WHITE):
                moves = 7 - r
                if moves < white_min_moves:
                    white_min_moves = moves
            if piece.color == chess.BLACK and is_passed(sq, chess.BLACK):
                moves = r - 0
                if moves < black_min_moves:
                    black_min_moves = moves
    # higher means white closer to promotion (positive favors white)
    if white_min_moves == 100 and black_min_moves == 100:
        return 0.0
    if white_min_moves == 100:
        return float(-black_min_moves)
    if black_min_moves == 100:
        return float(white_min_moves)
    return float(black_min_moves - white_min_moves)

def feature(board: chess.Board) -> float:
    'Count of passed pawns that have a friendly rook behind them on the same file (white - black)'
    def is_passed(sq, color):
        if not board.piece_at(sq) or board.piece_at(sq).piece_type != chess.PAWN:
            return False
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            for af in range(max(0, f-1), min(7, f+1)+1):
                for ar in range(r+1, 8):
                    p = board.piece_at(chess.square(af, ar))
                    if p and p.piece_type == chess.PAWN and p.color == chess.BLACK:
