            return True
        else:
            for af in range(max(0, f-1), min(7, f+1)+1):
                for ar in range(0, r):
                    p = board.piece_at(chess.square(af, ar))
                    if p and p.piece_type == chess.PAWN and p.color == chess.WHITE:
                        return False
            return True
    wcnt = 0
    bcnt = 0
    for sq, piece in board.piece_map().items():
        if piece.piece_type == chess.PAWN and is_passed(sq, piece.color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            # look for a friendly rook on same file behind the pawn (towards own side)
            found = False
            for r_sq, r_piece in board.piece_map().items():
                if r_piece.piece_type == chess.ROOK and r_piece.color == piece.color and chess.square_file(r_sq) == f:
                    rr = chess.square_rank(r_sq)
                    if piece.color == chess.WHITE and rr < r:
                        found = True
                        break
                    if piece.color == chess.BLACK and rr > r:
                        found = True
                        break
            if piece.color == chess.WHITE and found:
                wcnt += 1
            if piece.color == chess.BLACK and found:
                bcnt += 1
    return float(wcnt - bcnt)

def feature(board: chess.Board) -> float:
    'Whether the promotion square of the most advanced passed pawn is defended by a rook or king (white - black)'
    def most_advanced_passed(color):
        best = None
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.PAWN and piece.color == color:
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                # passed test
                passed = True
                if color == chess.WHITE:
                    for af in range(max(0, f-1), min(7, f+1)+1):
                        for ar in range(r+1, 8):
                            p = board.piece_at(chess.square(af, ar))
                            if p and p.piece_type == chess.PAWN and p.color == chess.BLACK:
                                passed = False
                                break
                        if not passed:
                            break
                    if passed and (best is None or r > chess.square_rank(best)):
                        best = sq
                else:
                    for af in range(max(0, f-1), min(7, f+1)+1):
                        for ar in range(0, r):
                            p = board.piece_at(chess.square(af, ar))
                            if p and p.piece_type == chess.PAWN and p.color == chess.WHITE:
                                passed = False
                                break
                        if not passed:
                            break
                    if passed and (best is None or r < chess.square_rank(best)):
                        best = sq
        return best
    def promotion_square_for(sq, color):
        if sq is None:
            return None
        f = chess.square_file(sq)
        return chess.square(f, 7) if color == chess.WHITE else chess.square(f, 0)
    wm = most_advanced_passed(chess.WHITE)
    bm = most_advanced_passed(chess.BLACK)
    wp = promotion_square_for(wm, chess.WHITE)
    bp = promotion_square_for(bm, chess.BLACK)
    def defended_by_rook_or_king(color, sq):
        if sq is None:
            return 0
        attackers = board.attackers(color, sq)
        for a in attackers:
            p = board.piece_at(a)
            if p and (p.piece_type == chess.ROOK or p.piece_type == chess.KING) and p.color == color:
                return 1
        return 0
    return float(defended_by_rook_or_king(chess.WHITE, wp) - defended_by_rook_or_king(chess.BLACK, bp))

def feature(board: chess.Board) -> float:
    'Blockers: whether an enemy rook sits on the file between a passed pawn and its promotion square (positive favors White)'
    def is_passed(sq, color):
        if not board.piece_at(sq) or board.piece_at(sq).piece_type != chess.PAWN:
            return False
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            for af in range(max(0, f-1), min(7, f+1)+1):
                for ar in range(r+1, 8):
                    p = board.piece_at(chess.square(af, ar))
                    if p and p.piece_type == chess.PAWN and p.color == chess.BLACK:
                        return False
            return True
        else:
            for af in range(max(0, f-1), min(7, f+1)+1):
                for ar in range(0, r):
                    p = board.piece_at(chess.square(af, ar))
                    if p and p.piece_type == chess.PAWN and p.color == chess.WHITE:
                        return False
            return True
    white_blocked = 0
    black_blocked = 0
    for sq, piece in board.piece_map().items():
        if piece.piece_type == chess.PAWN and is_passed(sq, piece.color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if piece.color == chess.WHITE:
                # check squares r+1 .. 7 on same file for an enemy rook
                for ar in range(r+1, 8):
                    p = board.piece_at(chess.square(f, ar))
                    if p and p.piece_type == chess.ROOK and p.color == chess.BLACK:
                        white_blocked += 1
                        break
            else:
                for ar in range(r-1, -1, -1):
                    p = board.piece_at(chess.square(f, ar))
                    if p and p.piece_type == chess.ROOK and p.color == chess.WHITE:
                        black_blocked += 1
                        break
    # positive means White is relatively less blocked (black_blocked - white_blocked)
    return float(black_blocked - white_blocked)

def feature(board: chess.Board) -> float:
    'Rook influence on enemy half: (squares on opponent half attacked by your rooks normalized) difference (white - black)'
    def rook_attacks_on_half(color):
        attacked = 0
        # opponent half: for white it's ranks 4..7, for black ranks 0..3
        ranks = range(4, 8) if color == chess.WHITE else range(0, 4)
        for r in ranks:
            for f in range(0, 8):
                sq = chess.square(f, r)
                # check if any rook of color attacks this square
                attackers = board.attackers(color, sq)
                for a in attackers:
                    p = board.piece_at(a)
                    if p and p.piece_type == chess.ROOK and p.color == color:
                        attacked += 1
                        break
        return attacked
    w = rook_attacks_on_half(chess.WHITE)
    b = rook_attacks_on_half(chess.BLACK)
    # normalize by half-board size (32)
    return float((w - b) / 32.0)

def feature(board: chess.Board) -> float:
    'Number of opponent rooks attacked by your rooks minus vice versa (positive favors White)'
    w_attacks = 0
    b_attacks = 0
    for sq, piece in board.piece_map().items():
        if piece.piece_type == chess.ROOK:
            if piece.color == chess.WHITE:
                # is this rook attacked by any black rook?
                attackers = board.attackers(chess.BLACK, sq)
                for a in attackers:
                    p = board.piece_at(a)
                    if p and p.piece_type == chess.ROOK and p.color == chess.BLACK:
                        b_attacks += 1
                        break
                # does this white rook attack any black rook?
                for tsq, tp in board.piece_map().items():
                    if tp.piece_type == chess.ROOK and tp.color == chess.BLACK:
                        if sq in board.attackers(chess.WHITE, tsq):
                            w_attacks += 1
            else:
                attackers = board.attackers(chess.WHITE, sq)
                for a in attackers:
                    p = board.piece_at(a)
                    if p and p.piece_type == chess.ROOK and p.color == chess.WHITE:
                        w_attacks += 1
                        break
                for tsq, tp in board.piece_map().items():
                    if tp.piece_type == chess.ROOK and tp.color == chess.WHITE:
                        if sq in board.attackers(chess.BLACK, tsq):
                            b_attacks += 1
    # w_attacks counts how many black rooks are attacked by white rooks (possibly double-counted); b_attacks vice versa
    return float(w_attacks - b_attacks)

def feature(board: chess.Board) -> float:
    'King proximity to opponent-most-advanced passed pawn promotion square difference (black_dist - white_dist); positive favors White'
    def most_advanced_passed_promotion(color):
