def feature(board: chess.Board) -> float:
    'Hanging piece difference: (white undefended pieces attacked - black) normalized by 8'
    try:
        pieces = board.piece_map()
        white_hanging = 0
        black_hanging = 0
        for sq, p in pieces.items():
            opp = not p.color
            attacked_by_opp = board.is_attacked_by(opp, sq)
            defended_by_own = board.is_attacked_by(p.color, sq)
            if attacked_by_opp and not defended_by_own:
                if p.color == chess.WHITE:
                    white_hanging += 1
                else:
                    black_hanging += 1
        return float((white_hanging - black_hanging) / 8.0)
    except Exception:
