    for sq, p in board.piece_map().items():
        if p.piece_type not in thresh_types:
            continue
        enemy = not p.color
        if len(board.attackers(enemy, sq)) > 0:
            if p.color == chess.WHITE:
                white_threatened += values.get(p.piece_type,0)
            else:
                black_threatened += values.get(p.piece_type,0)
