        black_attacks_on_white_back = 0
        white_attacks_on_black_back = 0
        # rank 1 squares indices have rank 0, rank 8 rank 7
        white_back = [chess.square(f, 0) for f in range(8)]
        black_back = [chess.square(f, 7) for f in range(8)]
        for sq in white_back:
            if board.piece_at(sq) is not None:
                attackers = board.attackers(chess.BLACK, sq)
                black_attacks_on_white_back += len(attackers)
        for sq in black_back:
            if board.piece_at(sq) is not None:
                attackers = board.attackers(chess.WHITE, sq)
                white_attacks_on_black_back += len(attackers)
        return float(black_attacks_on_white_back - white_attacks_on_black_back)
    except Exception:
