def feature(board: chess.Board) -> float:
    'Net king exposure: (enemy attackers within distance<=2) - (friendly nearby pawns within 1); difference Black_on_White - White_on_Black'
    try:
        pieces = board.piece_map()
        white_king = None
        black_king = None
        for sq, pc in pieces.items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        if white_king is None or black_king is None:
            return 0.0
        def pawns_near(sq, color, radius=1):
            cnt = 0
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            for df in range(-radius, radius+1):
                for dr in range(-radius, radius+1):
                    if df==0 and dr==0: continue
                    nf, nr = f+df, r+dr
                    if 0<=nf<8 and 0<=nr<8:
                        p = board.piece_at(chess.square(nf,nr))
                        if p is not None and p.color == color and p.piece_type == chess.PAWN:
                            cnt += 1
            return cnt
        def enemy_attackers_within(sq, enemy_color, max_dist=2):
            cnt = 0
            for a_sq, pc in pieces.items():
                if pc.color != enemy_color: continue
                d = chess.square_distance(a_sq, sq)
                if d <= max_dist:
                    # only count if piece can move (approx) - pawns count as 0.8, majors more
                    val = 0.0
                    if pc.piece_type == chess.QUEEN: val = 2.5
                    elif pc.piece_type == chess.ROOK: val = 1.5
                    elif pc.piece_type in (chess.BISHOP, chess.KNIGHT): val = 1.2
                    elif pc.piece_type == chess.PAWN: val = 0.6
                    else: val = 0.8
                    cnt += val
            return cnt
        black_on_white = enemy_attackers_within(white_king, chess.BLACK, 2) - pawns_near(white_king, chess.WHITE, 1)
        white_on_black = enemy_attackers_within(black_king, chess.WHITE, 2) - pawns_near(black_king, chess.BLACK, 1)
        return float(black_on_white - white_on_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Gini-like concentration of non-pawn, non-king legal move destinations: (Black concentration - White concentration). Lower = more concentrated attack'
    try:
        from math import isclose
        # build destination frequency for legal moves by color excluding pawn and king moves
        white_dests = {}
        black_dests = {}
        for m in board.legal_moves:
            pc = board.piece_at(m.from_square)
            if pc is None: continue
            if pc.piece_type in (chess.PAWN, chess.KING): continue
            if pc.color == chess.WHITE:
                white_dests[m.to_square] = white_dests.get(m.to_square, 0) + 1
            else:
                black_dests[m.to_square] = black_dests.get(m.to_square, 0) + 1
        def gini_from_counts(dcts):
            total = sum(dcts.values())
            if total == 0:
                return 0.0
            s = 0.0
            for v in dcts.values():
                p = float(v)/float(total)
                s += p*p
            # concentration measure: higher s -> more concentrated; return 1 - s so lower means concentrated
            return 1.0 - s
        white_g = gini_from_counts(white_dests)
        black_g = gini_from_counts(black_dests)
        return float(black_g - white_g)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Weighted major-piece tropism: sum over rooks/queens of (value / distance_to_enemy_king), difference Black - White'
    try:
        pieces = board.piece_map()
        white_king = None
        black_king = None
        for sq, pc in pieces.items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        if white_king is None or black_king is None:
            return 0.0
        def score_for_color(color):
            s = 0.0
            for sq, pc in pieces.items():
                if pc.color != color: continue
                if pc.piece_type in (chess.QUEEN, chess.ROOK):
                    target = black_king if color == chess.WHITE else white_king
                    d = chess.square_distance(sq, target)
                    if d == 0:
                        d = 0.1
                    val = 9.0 if pc.piece_type==chess.QUEEN else 5.0
                    s += val / float(d)
            return s
        white_sc = score_for_color(chess.WHITE)
        black_sc = score_for_color(chess.BLACK)
        return float(black_sc - white_sc)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
