def feature(board: chess.Board) -> float:
    'Net king attack pressure weighted by attacker piece value: (black_pressure - white_pressure) positive favors White'
    try:
        value = {chess.PAWN: 1.0, chess.KNIGHT: 3.0, chess.BISHOP: 3.0, chess.ROOK: 5.0, chess.QUEEN: 9.0, chess.KING: 0.0}
        pieces = board.piece_map()
        wk = next((sq for sq, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        bk = next((sq for sq, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        if wk is None or bk is None:
            return 0.0
        black_attackers = board.attackers(chess.BLACK, wk)
        white_attackers = board.attackers(chess.WHITE, bk)
        black_pressure = sum(value.get(board.piece_at(sq).piece_type, 0.0) for sq in black_attackers if board.piece_at(sq) is not None)
        white_pressure = sum(value.get(board.piece_at(sq).piece_type, 0.0) for sq in white_attackers if board.piece_at(sq) is not None)
        return float(black_pressure - white_pressure)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in count of knight outposts (advanced and not attacked by enemy pawns): (white_outposts - black_outposts)'
    try:
        pieces = board.piece_map()
        pawn_sqs = {sq: p for sq, p in pieces.items() if p.piece_type == chess.PAWN}
        def attacked_by_pawn(square, pawn_color):
            # returns True if any pawn of pawn_color attacks square
            for psq, p in pawn_sqs.items():
                if p.color != pawn_color:
                    continue
                pr = chess.square_rank(psq)
                pf = chess.square_file(psq)
                if pawn_color == chess.WHITE:
                    targets = []
                    if pf - 1 >= 0 and pr + 1 <= 7:
                        targets.append(chess.square(pf - 1, pr + 1))
                    if pf + 1 <= 7 and pr + 1 <= 7:
                        targets.append(chess.square(pf + 1, pr + 1))
                else:
                    targets = []
                    if pf - 1 >= 0 and pr - 1 >= 0:
                        targets.append(chess.square(pf - 1, pr - 1))
                    if pf + 1 <= 7 and pr - 1 >= 0:
                        targets.append(chess.square(pf + 1, pr - 1))
                if square in targets:
                    return True
            return False
        white_out = 0
        black_out = 0
        for sq, p in pieces.items():
            if p.piece_type == chess.KNIGHT:
                r = chess.square_rank(sq)
                # advanced: ranks 4-6 for white (index >=4), for black index <=3
                if p.color == chess.WHITE:
                    if r >= 4 and not attacked_by_pawn(sq, chess.BLACK):
                        white_out += 1
                else:
                    if r <= 3 and not attacked_by_pawn(sq, chess.WHITE):
                        black_out += 1
        return float(white_out - black_out)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Bishop-pair advantage: (1 if White has two bishops else 0) - (1 if Black has two bishops else 0)'
    try:
        counts = {chess.WHITE: 0, chess.BLACK: 0}
        for p in board.piece_map().values():
            if p.piece_type == chess.BISHOP:
                counts[p.color] += 1
        return float((1.0 if counts[chess.WHITE] >= 2 else 0.0) - (1.0 if counts[chess.BLACK] >= 2 else 0.0))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Blocked passed pawns difference: (black_blocked_passed - white_blocked_passed) positive favors White'
    try:
        pieces = board.piece_map()
        pawn_sqs = {sq: p for sq, p in pieces.items() if p.piece_type == chess.PAWN}
        def is_passed(sq, color):
            sf = chess.square_file(sq)
            sr = chess.square_rank(sq)
            if color == chess.WHITE:
                for r in range(sr + 1, 8):
                    for f in (sf - 1, sf, sf + 1):
                        if 0 <= f <= 7:
                            s = chess.square(f, r)
                            p = pawn_sqs.get(s)
                            if p is not None and p.color == chess.BLACK:
                                return False
                return True
            else:
                for r in range(sr - 1, -1, -1):
                    for f in (sf - 1, sf, sf + 1):
                        if 0 <= f <= 7:
                            s = chess.square(f, r)
                            p = pawn_sqs.get(s)
                            if p is not None and p.color == chess.WHITE:
                                return False
                return True
        white_blocked = 0
        black_blocked = 0
        for sq, p in pawn_sqs.items():
            if is_passed(sq, p.color):
                # check direct square ahead occupied by opponent piece
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                ahead_r = r + 1 if p.color == chess.WHITE else r - 1
                if 0 <= ahead_r <= 7:
                    ahead_sq = chess.square(f, ahead_r)
                    occupant = board.piece_at(ahead_sq)
                    if occupant is not None and occupant.color != p.color:
                        if p.color == chess.WHITE:
                            white_blocked += 1
                        else:
                            black_blocked += 1
        return float(black_blocked - white_blocked)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King proximity / endgame indicator: normalized closeness of kings (1.0 = adjacent/close, 0.0 = far)'
    try:
        pieces = board.piece_map()
        wk = next((sq for sq, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        bk = next((sq for sq, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        if wk is None or bk is None:
            return 0.0
        dist = chess.square_distance(wk, bk)
        # maximum Chebyshev distance on board is 7, map to [0,1]
        return float(max(0.0, (7.0 - dist) / 7.0))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in fraction of non-king pieces that are defended: (white_fraction - black_fraction)'
    try:
        pieces = board.piece_map()
        white_total = 0
        black_total = 0
        white_defended = 0
        black_defended = 0
        for sq, p in pieces.items():
            if p.piece_type == chess.KING:
                continue
            if p.color == chess.WHITE:
                white_total += 1
                if len(board.attackers(chess.WHITE, sq)) > 0:
                    white_defended += 1
            else:
                black_total += 1
                if len(board.attackers(chess.BLACK, sq)) > 0:
                    black_defended += 1
        wf = (white_defended / white_total) if white_total > 0 else 0.0
        bf = (black_defended / black_total) if black_total > 0 else 0.0
        return float(wf - bf)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rook control of open/semi-open files: (white_score - black_score), open=1.0, semi-open=0.5'
    try:
        pieces = board.piece_map()
        pawn_files = {f: {'white': 0, 'black': 0} for f in range(8)}
        for sq, p in pieces.items():
            if p.piece_type == chess.PAWN:
                pf = chess.square_file(sq)
                pawn_files[pf]['white' if p.color == chess.WHITE else 'black'] += 1
        white_score = 0.0
        black_score = 0.0
        for sq, p in pieces.items():
            if p.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                total = pawn_files[f]['white'] + pawn_files[f]['black']
                if total == 0:
                    if p.color == chess.WHITE:
                        white_score += 1.0
                    else:
                        black_score += 1.0
                elif (p.color == chess.WHITE and pawn_files[f]['white'] == 0) or (p.color == chess.BLACK and pawn_files[f]['black'] == 0):
                    if p.color == chess.WHITE:
                        white_score += 0.5
                    else:
                        black_score += 0.5
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) in number of rooks occupying the opponent\'s seventh rank (very strong rooks)'
    try:
        white_seventh = 0
        black_seventh = 0
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.ROOK:
                rank = chess.square_rank(sq)
                if piece.color == chess.WHITE and rank == 6:
                    white_seventh += 1
                if piece.color == chess.BLACK and rank == 1:
                    black_seventh += 1
        return float(white_seventh - black_seventh)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) in number of rooks sitting on open files (files with no pawns)'
    try:
        pawn_files = set()
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.PAWN:
                pawn_files.add(chess.square_file(sq))
        white_open_rooks = 0
        black_open_rooks = 0
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                if f not in pawn_files:
                    if piece.color == chess.WHITE:
                        white_open_rooks += 1
                    else:
                        black_open_rooks += 1
        return float(white_open_rooks - black_open_rooks)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn-structure penalty difference (white - black): penalizes doubled, isolated and approximate backward pawns'
    try:
        def pawn_penalty(color):
            by_file = {f: [] for f in range(8)}
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.PAWN and p.color == color:
                    by_file[chess.square_file(sq)].append(chess.square_rank(sq))
            doubled = 0
            isolated = 0
            backward = 0
            for f in range(8):
                ranks = sorted(by_file[f])
                if len(ranks) > 1:
                    doubled += len(ranks) - 1
                # isolated if no friendly pawns on adjacent files
                if len(ranks) > 0 and ( (f-1 not in by_file or len(by_file[f-1])==0) and (f+1 not in by_file or len(by_file[f+1])==0) ):
                    isolated += len(ranks)
                # approximate backward: for each pawn, check no friendly pawn on adjacent files behind it
                for r in ranks:
                    behind_exists = False
                    if color == chess.WHITE:
                        for af in (f-1, f+1):
                            if 0 <= af < 8:
                                for ar in by_file.get(af, []):
                                    if ar < r:
                                        behind_exists = True
                                        break
                            if behind_exists:
                                break
                        if not behind_exists:
                            backward += 1
                    else:
                        for af in (f-1, f+1):
                            if 0 <= af < 8:
                                for ar in by_file.get(af, []):
                                    if ar > r:
                                        behind_exists = True
                                        break
                            if behind_exists:
                                break
                        if not behind_exists:
                            backward += 1
            # weighted penalty
            return 0.5 * doubled + 0.7 * isolated + 0.6 * backward
        return float(pawn_penalty(chess.WHITE) - pawn_penalty(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) in pawn shield strength in front of the king (counts friendly pawns in three-file window ahead 1-2 ranks)'
    try:
        def shield(color):
            kingsq = None
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == color:
                    kingsq = sq
                    break
            if kingsq is None:
                return 0.0
            kf = chess.square_file(kingsq)
            kr = chess.square_rank(kingsq)
            count = 0
            if color == chess.WHITE:
                ranks = [kr+1, kr+2]
            else:
                ranks = [kr-1, kr-2]
            for f in (kf-1, kf, kf+1):
                if 0 <= f < 8:
                    for r in ranks:
                        if 0 <= r < 8:
                            sq = chess.square(f, r)
                            p = board.piece_at(sq)
                            if p and p.piece_type == chess.PAWN and p.color == color:
                                # weight nearer pawns higher
                                dist = abs(r - kr)
                                weight = 1.0 if dist == 1 else 0.5
                                count += weight
            return count
        return float(shield(chess.WHITE) - shield(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) of offensive pressure on the enemy king measured by number of attackers on the enemy king square'
    try:
        # white pressure = number of white attackers on black king
        wk = None
        bk = None
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    wk = sq
                else:
                    bk = sq
        white_pressure = float(len(board.attackers(chess.WHITE, bk))) if bk is not None else 0.0
        black_pressure = float(len(board.attackers(chess.BLACK, wk))) if wk is not None else 0.0
        return white_pressure - black_pressure
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) in number of hanging pieces: opponent attacks > defenders for that piece'
    try:
        white_hanging = 0
        black_hanging = 0
        piece_map = board.piece_map()
        for sq, piece in piece_map.items():
            color = piece.color
            opp = not color
            attackers = len(board.attackers(opp, sq))
            defenders = len(board.attackers(color, sq))
            # defenders count includes the piece itself in some attack models; to be conservative, subtract one if defender is counted via discovered checks
            # using attackers API defenders should not include the piece itself; proceed normally
            if attackers > defenders and attackers > 0:
                if color == chess.WHITE:
                    white_hanging += 1
                else:
                    black_hanging += 1
        return float(white_hanging - black_hanging)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) of bishop pair/outpost influence: bishop-pair bonus plus bishops\' attacks into central squares'
    try:
        central_squares = [chess.parse_square(f + str(r)) for f in ['c','d','e','f'] for r in ['3','4','5','6']]
        white_score = 0.0
        black_score = 0.0
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.BISHOP:
                count = 0
                for cs in central_squares:
                    # test whether this bishop attacks cs by checking whether bishop square is in attackers of cs for bishop's color
                    if sq in board.attackers(piece.color, cs):
                        count += 1
                if piece.color == chess.WHITE:
                    white_score += count
                else:
                    black_score += count
        # bishop pair bonus
        wb = sum(1 for p in board.piece_map().values() if p.piece_type == chess.BISHOP and p.color == chess.WHITE)
        bb = sum(1 for p in board.piece_map().values() if p.piece_type == chess.BISHOP and p.color == chess.BLACK)
        white_score += 1.0 if wb >= 2 else 0.0
        black_score += 1.0 if bb >= 2 else 0.0
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) in queen proximity to the enemy king (closer queen is typically more active); large value if no queen'
    try:
        wq = None
        bq = None
        wk = None
        bk = None
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.QUEEN:
                if p.color == chess.WHITE:
                    wq = sq
                else:
                    bq = sq
            elif p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    wk = sq
                else:
                    bk = sq
        inf = 10.0
        wq_dist = inf
        bq_dist = inf
        if wq is not None and bk is not None:
            wq_dist = chess.square_distance(wq, bk)
        if bq is not None and wk is not None:
            bq_dist = chess.square_distance(bq, wk)
        # smaller distance is better for attacker; invert so larger is better
        w_score = (inf - wq_dist) if wq_dist < inf else 0.0
        b_score = (inf - bq_dist) if bq_dist < inf else 0.0
        return float(w_score - b_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) in number of knights on safe central outposts: knight on central 4x4 not attacked by enemy pawn'
    try:
        def pawn_attacks_to_square(color, sq):
            # returns True if any pawn of color attacks sq
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                # white pawns attack from rank-1 to rank (pawn sits one rank below to attack)
                sources = []
                for af in (f-1, f+1):
                    sr = r-1
                    if 0 <= af < 8 and 0 <= sr < 8:
                        sources.append(chess.square(af, sr))
            else:
                sources = []
                for af in (f-1, f+1):
                    sr = r+1
                    if 0 <= af < 8 and 0 <= sr < 8:
                        sources.append(chess.square(af, sr))
            for s in sources:
                p = board.piece_at(s)
                if p and p.piece_type == chess.PAWN and p.color == color:
                    return True
            return False
        central_files = range(2,6)  # c,d,e,f
        central_ranks = range(2,6)  # 3,4,5,6 (0-based)
        white_count = 0
        black_count = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KNIGHT:
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                if f in central_files and r in central_ranks:
                    # check attacked by enemy pawn?
                    enemy_color = not p.color
                    if not pawn_attacks_to_square(enemy_color, sq):
                        if p.color == chess.WHITE:
                            white_count += 1
                        else:
                            black_count += 1
        return float(white_count - black_count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Endgame king centralization advantage (white - black) applied when non-pawn material is low: prefers more central king in endgame'
    try:
        material_nonpawn = 0
        for p in board.piece_map().values():
            if p.piece_type == chess.KNIGHT or p.piece_type == chess.BISHOP:
                material_nonpawn += 3
            elif p.piece_type == chess.ROOK:
                material_nonpawn += 5
            elif p.piece_type == chess.QUEEN:
                material_nonpawn += 9
        # threshold for endgame-ish
        if material_nonpawn > 8:
            return 0.0
        # center coordinates are between files 3.5 and ranks 3.5 (0-based middle)
        center_file = 3.5
        center_rank = 3.5
        wk = None
        bk = None
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    wk = sq
                else:
                    bk = sq
        def centralization(kingsq):
            if kingsq is None:
                return 0.0
            f = chess.square_file(kingsq)
            r = chess.square_rank(kingsq)
            # smaller distance means more centralized; invert so larger is better
            d = abs(f - center_file) + abs(r - center_rank)
            return max(0.0, 7.0 - d)  # scale
        return float(centralization(wk) - centralization(bk))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of white pawns on the 7th rank (i.e., one step from promotion).'
    try:
        count = 0
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.PAWN and piece.color == chess.WHITE:
                if chess.square_rank(sq) == 6:
                    count += 1
        return float(count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Indicator (1.0/0.0) whether any white rook is directly behind the most advanced white pawn on the same file with no pieces between (support-from-behind).'
    try:
        # find most advanced white pawn (highest rank)
        white_pawns = [sq for sq, p in board.piece_map().items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        if not white_pawns:
            return 0.0
        pawn_sq = max(white_pawns, key=lambda s: chess.square_rank(s))
        pawn_file = chess.square_file(pawn_sq)
        pawn_rank = chess.square_rank(pawn_sq)
        # find white rooks on same file with lower rank
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK and p.color == chess.WHITE and chess.square_file(sq) == pawn_file and chess.square_rank(sq) < pawn_rank:
                # ensure path between rook and pawn is clear
                clear = True
                for r in range(chess.square_rank(sq) + 1, pawn_rank):
                    if board.piece_at(chess.square(pawn_file, r)) is not None:
                        clear = False
                        break
                if clear:
                    return 1.0
        return 0.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Support score of the most advanced white passed pawn by nearest friendly rook: 1/(1+Manhattan distance) (0 if no passed pawn or no rook).'
    try:
        # helper: is passed pawn
        def is_passed(sq, color):
            file = chess.square_file(sq)
            rank = chess.square_rank(sq)
            if color == chess.WHITE:
                for sq2, p in board.piece_map().items():
                    if p.piece_type == chess.PAWN and p.color == chess.BLACK:
                        f2 = chess.square_file(sq2); r2 = chess.square_rank(sq2)
                        if abs(f2 - file) <= 1 and r2 > rank:
                            return False
                return True
            else:
                for sq2, p in board.piece_map().items():
                    if p.piece_type == chess.PAWN and p.color == chess.WHITE:
                        f2 = chess.square_file(sq2); r2 = chess.square_rank(sq2)
                        if abs(f2 - file) <= 1 and r2 < rank:
                            return False
                return True
        # find most advanced white passed pawn
        white_passed = [sq for sq, p in board.piece_map().items() if p.piece_type == chess.PAWN and p.color == chess.WHITE and is_passed(sq, chess.WHITE)]
        if not white_passed:
            return 0.0
        pawn_sq = max(white_passed, key=lambda s: chess.square_rank(s))
        # find nearest white rook
        rooks = [sq for sq, p in board.piece_map().items() if p.piece_type == chess.ROOK and p.color == chess.WHITE]
        if not rooks:
            return 0.0
        dists = [chess.square_distance(pawn_sq, r) for r in rooks]
        dist = min(dists)
        return 1.0 / (1.0 + dist)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Whether any white rook "cuts" the black king by being on same rank/file with a clear path (1.0 if yes, else 0.0).'
    try:
        kings = {p.color: sq for sq, p in board.piece_map().items() if p.piece_type == chess.KING}
        if chess.BLACK not in kings:
            return 0.0
        black_king_sq = kings[chess.BLACK]
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK and p.color == chess.WHITE:
                rf = chess.square_file(sq); rk = chess.square_rank(sq)
                kf = chess.square_file(black_king_sq); kk = chess.square_rank(black_king_sq)
                # same file
                if rf == kf:
                    blocked = False
                    for r in range(min(rk, kk) + 1, max(rk, kk)):
                        if board.piece_at(chess.square(rf, r)) is not None:
                            blocked = True; break
                    if not blocked:
                        return 1.0
                # same rank
                if rk == kk:
                    blocked = False
                    for f in range(min(rf, kf) + 1, max(rf, kf)):
                        if board.piece_at(chess.square(f, rk)) is not None:
                            blocked = True; break
                    if not blocked:
                        return 1.0
        return 0.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) of attackers on the promotion square of the most advanced white pawn (positive means square is better controlled by White).'
    try:
        white_pawns = [sq for sq, p in board.piece_map().items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        if not white_pawns:
            return 0.0
        pawn_sq = max(white_pawns, key=lambda s: chess.square_rank(s))
        promo_sq = chess.square(chess.square_file(pawn_sq), 7)
        white_def = len(board.attackers(chess.WHITE, promo_sq))
        black_att = len(board.attackers(chess.BLACK, promo_sq))
        return float(white_def - black_att)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Fraction of squares on the pawn-to-promotion path that are empty for the most advanced white pawn (1.0 means completely clear).'
    try:
        white_pawns = [sq for sq, p in board.piece_map().items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        if not white_pawns:
            return 0.0
        pawn_sq = max(white_pawns, key=lambda s: chess.square_rank(s))
        pr = chess.square_rank(pawn_sq)
        file = chess.square_file(pawn_sq)
        steps = 7 - pr
        if steps <= 0:
            return 1.0
        empty = 0
        for r in range(pr + 1, 8):
            if board.piece_at(chess.square(file, r)) is None:
                empty += 1
        return float(empty) / float(steps)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in rook legal move counts (white rooks moves - black rooks moves), normalized by 10.'
    try:
        w_moves = 0
        b_moves = 0
        for mv in board.legal_moves:
            p = board.piece_at(mv.from_square)
            if p is None:
                continue
            if p.piece_type != chess.ROOK:
                continue
            if p.color == chess.WHITE:
                w_moves += 1
            else:
                b_moves += 1
        return float(w_moves - b_moves) / 10.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (black_dist - white_dist) of Manhattan distances of kings to the promotion square of the most advanced white pawn (positive if White king is closer).'
    try:
        kings = {p.color: sq for sq, p in board.piece_map().items() if p.piece_type == chess.KING}
        if chess.WHITE not in kings or chess.BLACK not in kings:
            return 0.0
        white_pawns = [sq for sq, p in board.piece_map().items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        if not white_pawns:
            return 0.0
        pawn_sq = max(white_pawns, key=lambda s: chess.square_rank(s))
        promo_sq = chess.square(chess.square_file(pawn_sq), 7)
        wd = chess.square_distance(kings[chess.WHITE], promo_sq)
        bd = chess.square_distance(kings[chess.BLACK], promo_sq)
        return float(bd - wd)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Indicator (1.0/0.0) whether any black rook currently attacks (controls) the promotion square of the most advanced white pawn.'
    try:
        white_pawns = [sq for sq, p in board.piece_map().items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        if not white_pawns:
            return 0.0
        pawn_sq = max(white_pawns, key=lambda s: chess.square_rank(s))
        promo_sq = chess.square(chess.square_file(pawn_sq), 7)
        attackers_black = board.attackers(chess.BLACK, promo_sq)
        return 1.0 if attackers_black else 0.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Indicator (1.0/0.0) whether any white rook directly attacks the black rook (clear line-of-sight same rank/file with no pieces between).'
    try:
        rooks = [(sq, p) for sq, p in board.piece_map().items() if p.piece_type == chess.ROOK]
        whites = [sq for sq, p in rooks if p.color == chess.WHITE]
        blacks = [sq for sq, p in rooks if p.color == chess.BLACK]
        if not whites or not blacks:
            return 0.0
        for wr in whites:
            for br in blacks:
                rf = chess.square_file(wr); rk = chess.square_rank(wr)
                bf = chess.square_file(br); bk = chess.square_rank(br)
                if rf == bf:
                    blocked = False
                    for r in range(min(rk, bk) + 1, max(rk, bk)):
                        if board.piece_at(chess.square(rf, r)) is not None:
                            blocked = True; break
                    if not blocked:
                        return 1.0
                if rk == bk:
                    blocked = False
                    for f in range(min(rf, bf) + 1, max(rf, bf)):
                        if board.piece_at(chess.square(f, rk)) is not None:
                            blocked = True; break
                    if not blocked:
                        return 1.0
        return 0.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of attacking threats against the 3x3 king area: (white attacking black king area) - (black attacking white king area)'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        if white_king_sq is None or black_king_sq is None:
            return 0.0
        def area_squares(king_sq):
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            res = []
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    f = kf + df
                    r = kr + dr
                    if 0 <= f <= 7 and 0 <= r <= 7:
                        res.append(chess.square(f, r))
            return res
        white_attacks_on_black = sum(1 for sq in area_squares(black_king_sq) if board.is_attacked_by(chess.WHITE, sq))
        black_attacks_on_white = sum(1 for sq in area_squares(white_king_sq) if board.is_attacked_by(chess.BLACK, sq))
        return float(white_attacks_on_black - black_attacks_on_white)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net value (in pawns) of undefended pieces that are attacked: (black_undefended - white_undefended) where values use pawn=1,kn=3.2,bi=3.3,rook=5,que=9'
    try:
        values = {chess.PAWN:1.0, chess.KNIGHT:3.2, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        white_sum = 0.0
        black_sum = 0.0
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.KING:
                continue
            own = piece.color
            opp = not own
            attacked_by_opp = board.is_attacked_by(opp, sq)
            defended_by_own = board.is_attacked_by(own, sq)
            if attacked_by_opp and not defended_by_own:
                val = values.get(piece.piece_type, 0.0)
                if piece.color == chess.WHITE:
                    white_sum += val
                else:
                    black_sum += val
        # return black - white so positive means Black has more undefended (bad for Black), thus favors White
        return float(black_sum - white_sum)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rook file control: sum over rooks (open file=1.0, semi-open=0.5) difference (white - black)'
    try:
        pawns_on_file_white = [False]*8
        pawns_on_file_black = [False]*8
        pawns_on_file_any = [False]*8
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                pawns_on_file_any[f] = True
                if p.color == chess.WHITE:
                    pawns_on_file_white[f] = True
                else:
                    pawns_on_file_black[f] = True
        score_w = 0.0
        score_b = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                if not pawns_on_file_any[f]:
                    val = 1.0
                elif (p.color == chess.WHITE and not pawns_on_file_white[f]) or (p.color == chess.BLACK and not pawns_on_file_black[f]):
                    val = 0.5
                else:
                    val = 0.0
                if p.color == chess.WHITE:
                    score_w += val
                else:
                    score_b += val
        return float(score_w - score_b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of likely-trapped pieces: (black_trapped_count - white_trapped_count). A piece is considered trapped if it has no legal moves for its side and is attacked.'
    try:
        trapped = {chess.WHITE:0, chess.BLACK:0}
        pm = board.piece_map()
        for sq, p in list(pm.items()):
            if p.piece_type == chess.KING:
                continue
            # is it under attack by opponent?
            if not board.is_attacked_by(not p.color, sq):
                continue
            # make a copy and set side-to-move to the piece color to inspect its legal moves
            b2 = board.copy()
            b2.turn = p.color
            moves_for_piece = 0
            for m in b2.legal_moves:
                if m.from_square == sq:
                    moves_for_piece += 1
                    if moves_for_piece >= 1:
                        break
            if moves_for_piece == 0:
                trapped[p.color] += 1
        return float(trapped[chess.BLACK] - trapped[chess.WHITE])
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in advanced minor-piece outposts (mainly knights): count knights supported by a friendly pawn and not attacked by an enemy pawn on advanced ranks (white - black)'
    try:
        def is_supported_by_pawn(color, sq):
            attackers = board.attackers(color, sq)
            for asq in attackers:
                p = board.piece_at(asq)
                if p and p.piece_type == chess.PAWN and p.color == color:
                    return True
            return False
        def attacked_by_enemy_pawn(color, sq):
            enemy = not color
            attackers = board.attackers(enemy, sq)
            for asq in attackers:
                p = board.piece_at(asq)
                if p and p.piece_type == chess.PAWN and p.color == enemy:
                    return True
            return False
        out_w = 0
        out_b = 0
        for sq, p in board.piece_map().items():
            if p.piece_type != chess.KNIGHT and p.piece_type != chess.BISHOP:
                continue
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                advanced = (r >= 4)  # 5th rank or beyond
            else:
                advanced = (r <= 3)  # 4th rank or beyond for black
            if not advanced:
                continue
            if not is_supported_by_pawn(p.color, sq):
                continue
            if attacked_by_enemy_pawn(p.color, sq):
                continue
            if p.color == chess.WHITE:
                out_w += 1.0 if p.piece_type == chess.KNIGHT else 0.5
            else:
                out_b += 1.0 if p.piece_type == chess.KNIGHT else 0.5
        return float(out_w - out_b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in king pawn-shield integrity: number of friendly pawns in front two ranks across three files (white - black)'
    try:
        pm = board.piece_map()
        def shield_count(color):
            king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == color), None)
            if king_sq is None:
                return 0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            cnt = 0
            if color == chess.WHITE:
                ranks = [kr+1, kr+2]
            else:
                ranks = [kr-1, kr-2]
            for f in (kf-1, kf, kf+1):
                for r in ranks:
                    if 0 <= f <= 7 and 0 <= r <= 7:
                        sq = chess.square(f, r)
                        p = board.piece_at(sq)
                        if p and p.piece_type == chess.PAWN and p.color == color:
                            cnt += 1
            return cnt
        return float(shield_count(chess.WHITE) - shield_count(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net queen tropism: sum(8 - manhattan_dist(white_queen, black_king) clipped at >=0) - sum(8 - manhattan_dist(black_queen, white_king))'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        if white_king_sq is None or black_king_sq is None:
            return 0.0
        score_w = 0.0
        score_b = 0.0
        for sq, p in pm.items():
            if p.piece_type == chess.QUEEN:
                if p.color == chess.WHITE:
                    dist = chess.square_distance(sq, black_king_sq)
                    val = max(0, 8 - dist)
                    score_w += val
                else:
                    dist = chess.square_distance(sq, white_king_sq)
                    val = max(0, 8 - dist)
                    score_b += val
        return float(score_w - score_b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn island difference: (black_pawn_islands - white_pawn_islands). Fewer islands = better; positive => White has fewer islands'
    try:
        def pawn_islands(color):
            files_has = [False]*8
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.PAWN and p.color == color:
                    files_has[chess.square_file(sq)] = True
            # count contiguous runs of True
            islands = 0
            i = 0
            while i < 8:
                if files_has[i]:
                    islands += 1
                    while i < 8 and files_has[i]:
                        i += 1
                else:
                    i += 1
            return islands
        return float(pawn_islands(chess.BLACK) - pawn_islands(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Bishop pair and control difference: (white_pair_bonus + white_bishop_scope/20) - (black_pair_bonus + black_bishop_scope/20)'
    try:
        def bishop_scope_and_pair(color):
            pm = board.piece_map()
            bishops = [sq for sq, p in pm.items() if p.piece_type == chess.BISHOP and p.color == color]
            scope_squares = set()
            for sq in bishops:
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                for df, dr in ((1,1),(1,-1),(-1,1),(-1,-1)):
                    nf, nr = f+df, r+dr
                    while 0 <= nf <= 7 and 0 <= nr <= 7:
                        nsq = chess.square(nf, nr)
                        scope_squares.add(nsq)
                        if board.piece_at(nsq) is not None:
                            break
                        nf += df
                        nr += dr
            pair_bonus = 1.0 if len(bishops) >= 2 else 0.0
            return pair_bonus, float(len(scope_squares))
        w_pair, w_scope = bishop_scope_and_pair(chess.WHITE)
        b_pair, b_scope = bishop_scope_and_pair(chess.BLACK)
        return float((w_pair + w_scope / 20.0) - (b_pair + b_scope / 20.0))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Heavy-piece tropism: weighted proximity of rooks/queens to the enemy king: sum(value/(1+dist))_white - sum(value/(1+dist))_black where value rook=5,queen=9'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        if white_king_sq is None or black_king_sq is None:
            return 0.0
        valmap = {chess.ROOK:5.0, chess.QUEEN:9.0}
        wsum = 0.0
        bsum = 0.0
        for sq, p in pm.items():
            if p.piece_type in (chess.ROOK, chess.QUEEN):
                if p.color == chess.WHITE:
                    dist = chess.square_distance(sq, black_king_sq)
                    wsum += valmap[p.piece_type] / (1.0 + dist)
                else:
                    dist = chess.square_distance(sq, white_king_sq)
                    bsum += valmap[p.piece_type] / (1.0 + dist)
        return float(wsum - bsum)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net count of rooks on the opponent 7th rank (white rooks on rank 7 - black rooks on rank 2) as a float'
    white_count = 0
    black_count = 0
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.ROOK:
            r = chess.square_rank(sq)
            if p.color == chess.WHITE and r == 6:  # white's 7th rank (rank index 6)
                white_count += 1
            if p.color == chess.BLACK and r == 1:  # black's 2nd rank (black attacking white's 7th)
                black_count += 1
    return float(white_count - black_count)

def feature(board: chess.Board) -> float:
    'Difference in heavy-piece (rook/queen) occupation of open files: (white - black)'
    # An open file has no pawns of either color on that file.
    files_with_pawn = [False] * 8
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.PAWN:
            files_with_pawn[chess.square_file(sq)] = True
    white_heavy_on_open = 0
    black_heavy_on_open = 0
    for sq, p in board.piece_map().items():
        if chess.square_file(sq) is None:
            continue
        if p.piece_type in (chess.ROOK, chess.QUEEN):
            f = chess.square_file(sq)
            if not files_with_pawn[f]:
                if p.color == chess.WHITE:
                    white_heavy_on_open += 1
                else:
