                        # Use chess.square to build; chess.square(file, rank) = file + 8*rank
                        sq2 = rf + 8 * rr
                        p = board.piece_at(sq2)
                        if p is not None and p.piece_type == chess.PAWN and p.color == chess.BLACK:
                            return False
            return True
        else:
            for rf in range(f - 1, f + 2):
                if 0 <= rf <= 7:
                    for rr in range(0, r):
                        sq2 = rf + 8 * rr
                        p = board.piece_at(sq2)
