            return True
    INF = 100.0
    white_min = INF
    black_min = INF
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.PAWN:
            r = chess.square_rank(sq)
            if p.color == chess.WHITE and is_passed(sq, chess.WHITE):
                dist = 7 - r
                white_min = min(white_min, dist)
            if p.color == chess.BLACK and is_passed(sq, chess.BLACK):
                dist = r
                black_min = min(black_min, dist)
    if white_min == INF and black_min == INF:
        return 0.0
    if white_min == INF:
        white_min = 10.0
    if black_min == INF:
