                for target_sq in pm.keys():
                    if pm[target_sq].color == chess.WHITE and target_sq in board.attacks(sq):
                        attacks_white = True
                        break
                if attacks_white:
                    black_eng += 1
    return float(white_eng - black_eng)

def feature(board: chess.Board) -> float:
