def feature(board: chess.Board) -> float:
    'Weighted sum of white major (queen/rook) proximity to enemy king minus black majors proximity to white king (closer majors count more)'
    try:
        pm = board.piece_map()
        white_majors = [sq for sq,p in pm.items() if p.color == chess.WHITE and p.piece_type in (chess.ROOK, chess.QUEEN)]
        black_majors = [sq for sq,p in pm.items() if p.color == chess.BLACK and p.piece_type in (chess.ROOK, chess.QUEEN)]
        white_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.WHITE), None)
        black_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.BLACK), None)
        if white_king_sq is None or black_king_sq is None:
            return 0.0
        def score(majors, target_king):
            s = 0.0
            for m in majors:
                d = chess.square_distance(m, target_king)
                # give heavier weight if directly attacking the king square or adjacent squares
                weight = 1.0/(1 + d)
                # extra boost if the major actually attacks any square near the king
                near = any(len(board.attackers(board.piece_at(m).color, sq))>0 for sq in [target_king] )
                s += weight * (1.5 if near else 1.0)
            return s
        return float(score(white_majors, black_king_sq) - score(black_majors, white_king_sq))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Number of legal moves for the side to move that immediately deliver checkmate (mate-in-one count)'
    try:
        count = 0
        for mv in board.legal_moves:
            nb = board.copy()
            nb.push(mv)
            if nb.is_checkmate():
                count += 1
        return float(count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of open files adjacent to each king (open = no pawns on that file); positive => black king more exposed'
    try:
        pm = board.piece_map()
        def king_sq(color):
            return next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==color), None)
        def open_adjacent_files(color):
            ks = king_sq(color)
            if ks is None:
                return 0
            kf = chess.square_file(ks)
            files = set([f for f in (kf-1,kf,kf+1) if 0 <= f <= 7])
            open_count = 0
            for f in files:
                # check for any pawn (either color) on that file
                has_pawn = any(( (p.piece_type==chess.PAWN) and (chess.square_file(sq)==f) ) for sq,p in pm.items())
                if not has_pawn:
                    open_count += 1
            return open_count
        return float(open_adjacent_files(chess.BLACK) - open_adjacent_files(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net value of undefended attackers near kings: sum(values of attackers that are not defended) around black king minus same around white king'
    try:
        pm = board.piece_map()
        vals = {chess.PAWN:100.0,chess.KNIGHT:320.0,chess.BISHOP:330.0,chess.ROOK:500.0,chess.QUEEN:900.0,chess.KING:0.0}
        def king_attacker_undefended_sum(king_color):
            ks = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==king_color), None)
            if ks is None:
                return 0.0
            opp = not king_color
            sumv = 0.0
            # consider attackers to squares within manhattan distance <=1 (king+adjacent)
            squares = [sq for sq in range(64) if chess.square_distance(sq, ks) <= 1]
            attacker_sqs = set()
            for sq in squares:
                for a in board.attackers(opp, sq):
                    attacker_sqs.add(a)
            for a in attacker_sqs:
                p = pm.get(a)
                if p is None:
                    continue
                # if attacker square is not attacked by the defender (i.e., undefended)
                if not board.is_attacked_by(king_color, a):
                    sumv += vals.get(p.piece_type, 0.0)
            return sumv
        return float(king_attacker_undefended_sum(chess.BLACK) - king_attacker_undefended_sum(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Back-rank/linear attack weakness: count of opponent rooks/queens on same rank/file with clear line to king (weighted); positive -> white has more clear lines to black king'
    try:
        pm = board.piece_map()
        def clear_linear_attack(king_color):
            ks = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==king_color), None)
            if ks is None:
                return 0.0
            opp = not king_color
            score = 0.0
            kf = chess.square_file(ks); kr = chess.square_rank(ks)
            directions = [ (1,0),(-1,0),(0,1),(0,-1) ]
            for dx,dy in directions:
                x = kf + dx; y = kr + dy
                blocked = False
                while 0 <= x <= 7 and 0 <= y <= 7:
                    sq = chess.square(x,y)
                    p = pm.get(sq)
                    if p is not None:
                        if p.color == opp and p.piece_type in (chess.ROOK, chess.QUEEN):
                            if not blocked:
                                # closer attackers scored higher
                                dist = max(abs(x-kf), abs(y-kr))
                                score += 1.0/(1+dist)
                        blocked = True
                    x += dx; y += dy
            return score
        return float(clear_linear_attack(chess.BLACK) - clear_linear_attack(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Stable knights near opponent king: number of knights within manhattan distance 2 of enemy king that are not attacked by opponent pawns (white minus black)'
    try:
        pm = board.piece_map()
        def stable_knights(attacker_color, defender_color):
            ks = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==defender_color), None)
            if ks is None:
                return 0.0
            count = 0.0
            for sq,p in pm.items():
                if p.color==attacker_color and p.piece_type==chess.KNIGHT and chess.square_distance(sq, ks) <= 2:
                    # check if attacked by any opponent pawn
                    pawn_attacked = any(pm[a].piece_type==chess.PAWN for a in board.attackers(defender_color, sq))
                    if not pawn_attacked:
                        count += 1.0
            return count
        return float(stable_knights(chess.WHITE, chess.BLACK) - stable_knights(chess.BLACK, chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Major vs minor material tilt: (white rooks+queens) - (white bishops+knights) minus same for black, in pawn-centipawn units'
    try:
        pm = board.piece_map()
        major = {chess.ROOK:500.0, chess.QUEEN:900.0}
        minor = {chess.BISHOP:330.0, chess.KNIGHT:320.0}
        def imbalance(color):
            maj = sum(major.get(p.piece_type,0.0) for sq,p in pm.items() if p.color==color)
            mino = sum(minor.get(p.piece_type,0.0) for sq,p in pm.items() if p.color==color)
            return maj - mino
        return float((imbalance(chess.WHITE) - imbalance(chess.BLACK)))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Mobility towards the enemy king: number of legal moves for each side that move a piece to within distance<=2 of the opponent king (white minus black)'
    try:
        pm = board.piece_map()
        wk = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.WHITE), None)
        bk = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.BLACK), None)
        if wk is None or bk is None:
            return 0.0
        def moves_towards(color, target_king):
            nb = board.copy()
            nb.turn = color
            cnt = 0
            for mv in nb.legal_moves:
                if chess.square_distance(mv.to_square, target_king) <= 2:
                    cnt += 1
            return cnt
        return float(moves_towards(chess.WHITE, bk) - moves_towards(chess.BLACK, wk))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count difference of hanging pieces (attacked and undefended): white hanging pieces - black hanging pieces'
    try:
        pm = board.piece_map()
        def hanging_count(color):
            cnt = 0.0
            opp = not color
            for sq,p in pm.items():
                if p.color != color:
                    continue
                attackers = list(board.attackers(opp, sq))
                if attackers and (not board.is_attacked_by(color, sq)):
                    cnt += 1.0
            return cnt
        return float(hanging_count(chess.WHITE) - hanging_count(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King escape deficit heuristic: for each king count how many legal adjacent squares are safe (not occupied by own pieces and not attacked by opponent); return black_escape_deficit - white_escape_deficit (higher means black more trapped)'
    try:
        pm = board.piece_map()
        def escape_deficit(king_color):
            ks = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==king_color), None)
            if ks is None:
                return 0.0
            opp = not king_color
            safe = 0
            for sq in range(64):
                if chess.square_distance(sq, ks) == 1:
                    occ = pm.get(sq)
                    # square is safe if not occupied by own piece and not attacked by opponent
                    if occ is not None and occ.color == king_color:
                        continue
                    if not board.is_attacked_by(opp, sq):
                        safe += 1
            # deficit: fewer safe squares -> higher deficit; normalize to 0..8
            return float(8 - safe)
        return float(escape_deficit(chess.BLACK) - escape_deficit(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net weighted value of enemy attackers on each king (white minus black). Attackers are weighted by piece-scores (p=1,n=3,b=3,r=5,q=9).'
    # Sum value of pieces attacking the white king (attacked by black) minus those attacking the black king (attacked by white)
    values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    pm = board.piece_map()
    white_king_sq = None
    black_king_sq = None
    for sq, pc in pm.items():
        if pc.piece_type == chess.KING:
            if pc.color == chess.WHITE:
                white_king_sq = sq
            else:
                black_king_sq = sq
    try:
        val_white_attacked = 0.0
        val_black_attacked = 0.0
        if white_king_sq is not None:
            attackers = board.attackers(chess.BLACK, white_king_sq)
            for a in attackers:
                p = board.piece_at(a)
                if p is not None:
                    val_white_attacked += values.get(p.piece_type, 0.0)
        if black_king_sq is not None:
            attackers = board.attackers(chess.WHITE, black_king_sq)
            for a in attackers:
                p = board.piece_at(a)
                if p is not None:
                    val_black_attacked += values.get(p.piece_type, 0.0)
        return float(val_white_attacked - val_black_attacked)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white minus black) in number of safe adjacent king-squares: adjacent squares not occupied by own piece and not attacked by opponent, normalized by 8.'
    pm = board.piece_map()
    def find_king(color):
        for sq, pc in pm.items():
            if pc.piece_type == chess.KING and pc.color == color:
                return sq
        return None
    def safe_adjacent_count(king_sq, color):
        if king_sq is None:
            return 0
        opp = chess.BLACK if color == chess.WHITE else chess.WHITE
        safe = 0
        kf = chess.square_file(king_sq)
        kr = chess.square_rank(king_sq)
        for df in (-1,0,1):
            for dr in (-1,0,1):
                if df == 0 and dr == 0:
                    continue
                f = kf + df
                r = kr + dr
                if 0 <= f <= 7 and 0 <= r <= 7:
                    sq = chess.square(f, r)
                    occupant = board.piece_at(sq)
                    if occupant is not None and occupant.color == color:
                        continue
                    # safe if not attacked by opponent
                    if not board.is_attacked_by(opp, sq):
                        safe += 1
        return safe
    try:
        wk = find_king(chess.WHITE)
        bk = find_king(chess.BLACK)
        w_safe = safe_adjacent_count(wk, chess.WHITE)
        b_safe = safe_adjacent_count(bk, chess.BLACK)
        return float((w_safe - b_safe) / 8.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white minus black) of Manhattan distance from each king to the nearest enemy major (rook or queen). Larger positive means white king is farther from attackers relative to black king.'
    pm = board.piece_map()
    def find_king(color):
        for sq, pc in pm.items():
            if pc.piece_type == chess.KING and pc.color == color:
                return sq
        return None
    def min_dist_to_enemy_majors(king_sq, enemy_color):
        if king_sq is None:
            return 8.0
        min_d = 8.0
        for sq, pc in pm.items():
            if pc.color == enemy_color and (pc.piece_type == chess.ROOK or pc.piece_type == chess.QUEEN):
                d = chess.square_distance(king_sq, sq)
                if d < min_d:
                    min_d = float(d)
        return min_d
    try:
        wking = find_king(chess.WHITE)
        bking = find_king(chess.BLACK)
        d_w = min_dist_to_enemy_majors(wking, chess.BLACK)
        d_b = min_dist_to_enemy_majors(bking, chess.WHITE)
        return float(d_w - d_b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Backrank/file direct attackers count difference (white minus black): number of enemy rooks/queens that have a clear rank/file/diagonal line to the king when the king sits on its backrank (counts only those aligned and unobstructed).'
    pm = board.piece_map()
    def find_king(color):
        for sq, pc in pm.items():
            if pc.piece_type == chess.KING and pc.color == color:
                return sq
        return None
    def clear_line(a, b):
        af = chess.square_file(a); ar = chess.square_rank(a)
        bf = chess.square_file(b); br = chess.square_rank(b)
        df = bf - af; dr = br - ar
        step_f = 0 if df == 0 else (1 if df > 0 else -1)
        step_r = 0 if dr == 0 else (1 if dr > 0 else -1)
        # must be straight or diagonal
        if not (df == 0 or dr == 0 or abs(df) == abs(dr)):
            return False
        x, y = af + step_f, ar + step_r
        while (x, y) != (bf, br):
            sq = chess.square(x, y)
            if sq in pm:
                return False
            x += step_f; y += step_r
        return True
    def backrank_attacks(color):
        ksq = find_king(color)
        if ksq is None:
            return 0
        kr = chess.square_rank(ksq)
        # backrank for white is rank 0, for black rank 7
        if not (kr == 0 or kr == 7):
            return 0
        count = 0
        enemy = chess.BLACK if color == chess.WHITE else chess.WHITE
        for sq, pc in pm.items():
            if pc.color == enemy and (pc.piece_type == chess.ROOK or pc.piece_type == chess.QUEEN):
                # check if aligned and unobstructed
                if clear_line(sq, ksq):
                    count += 1
        return count
    try:
        w_att = backrank_attacks(chess.WHITE)
        b_att = backrank_attacks(chess.BLACK)
        return float(w_att - b_att)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Total value of "hanging" pieces near each king (within manhattan distance 2) that are attacked by enemy and undefended; returns (white_hanging_value - black_hanging_value).'
    values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    pm = board.piece_map()
    def find_king(color):
        for sq, pc in pm.items():
            if pc.piece_type == chess.KING and pc.color == color:
                return sq
        return None
    def hanging_value_near_king(color):
        ksq = find_king(color)
        if ksq is None:
            return 0.0
        total = 0.0
        for sq, pc in pm.items():
            if pc.color != color:
                continue
            if chess.square_distance(sq, ksq) <= 2:
                enemy = chess.BLACK if color == chess.WHITE else chess.WHITE
                enemy_attackers = len(board.attackers(enemy, sq))
                friendly_defenders = len(board.attackers(color, sq))
                if enemy_attackers > 0 and friendly_defenders == 0:
                    total += values.get(pc.piece_type, 0.0)
        return total
    try:
        return float(hanging_value_near_king(chess.WHITE) - hanging_value_near_king(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Indicator (1.0 or 0.0) whether the side to move has a mate-in-1. Safe simulation via copy; returns 1.0 if any legal move immediately checkmates the opponent.'
    try:
        # iterate legal moves and simulate
        for mv in board.legal_moves:
            try:
                nb = board.copy()
                nb.push(mv)
                if nb.is_checkmate():
                    return 1.0
            except Exception:
                continue
        return 0.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white minus black) in count of friendly pieces attacking any square adjacent to their king (measures local defensive presence).'
    pm = board.piece_map()
    def find_king(color):
        for sq, pc in pm.items():
            if pc.piece_type == chess.KING and pc.color == color:
                return sq
        return None
    def defenders_near_king(color):
        ksq = find_king(color)
        if ksq is None:
            return 0.0
        adj = set()
        kf = chess.square_file(ksq); kr = chess.square_rank(ksq)
        for df in (-1,0,1):
            for dr in (-1,0,1):
                if df == 0 and dr == 0:
                    continue
                f = kf + df; r = kr + dr
                if 0 <= f <= 7 and 0 <= r <= 7:
                    adj.add(chess.square(f, r))
        count = 0
        for sq, pc in pm.items():
            if pc.color != color:
                continue
            if pc.piece_type == chess.KING:
                continue
            for target in adj:
                if sq in board.attackers(color, target):
                    count += 1
                    break
        return float(count)
    try:
        return float(defenders_near_king(chess.WHITE) - defenders_near_king(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'White rooks on the 7th rank minus black rooks on the 7th rank (counts white rooks on rank index 6 and black rooks on rank index 1).'
    pm = board.piece_map()
    w = 0
    b = 0
    try:
        for sq, pc in pm.items():
            if pc.piece_type == chess.ROOK:
                r = chess.square_rank(sq)
                if pc.color == chess.WHITE and r == 6:
                    w += 1
                if pc.color == chess.BLACK and r == 1:
                    b += 1
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white minus black) in number of pinned pieces to the king by enemy sliding pieces (rook, bishop, queen). A piece is considered pinned if it lies on the line between its king and an enemy slider with no other intervening pieces.'
    pm = board.piece_map()
    def find_king(color):
        for sq, pc in pm.items():
            if pc.piece_type == chess.KING and pc.color == color:
                return sq
        return None
    def is_slider_piece(pc, along_diag):
        if pc is None:
            return False
        if pc.piece_type == chess.QUEEN:
            return True
        if along_diag:
            return pc.piece_type == chess.BISHOP
        else:
            return pc.piece_type == chess.ROOK
    def count_pins(color):
        king_sq = find_king(color)
        if king_sq is None:
            return 0
        cnt = 0
        kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
        enemy = chess.BLACK if color == chess.WHITE else chess.WHITE
        for sq, pc in pm.items():
            if pc.color != color:
                continue
            if pc.piece_type == chess.KING:
                continue
            pf = chess.square_file(sq); pr = chess.square_rank(sq)
            df = pf - kf; dr = pr - kr
            # must be collinear
            if not (df == 0 or dr == 0 or abs(df) == abs(dr)):
                continue
            step_f = 0 if df == 0 else (1 if df > 0 else -1)
            step_r = 0 if dr == 0 else (1 if dr > 0 else -1)
            # search beyond the piece for an enemy slider
            x = pf + step_f; y = pr + step_r
            pieces_between = 0
            blocked = False
            while 0 <= x <= 7 and 0 <= y <= 7:
                s = chess.square(x, y)
                if s in pm:
                    pieces_between += 1
                    # if we hit any piece that's not the enemy slider after the candidate, it's blocked
                    p2 = pm[s]
                    along_diag = (abs(df) == abs(dr))
                    if p2.color == enemy and is_slider_piece(p2, along_diag):
                        # now ensure there is exactly one piece between king and this slider: the candidate piece
                        # count pieces on segment between king and slider (exclusive)
                        # compute squares between king and s
                        cnt_between = 0
                        ax = kf + (1 if pf - kf > 0 else (-1 if pf - kf < 0 else 0))
                        ay = kr + (1 if pr - kr > 0 else (-1 if pr - kr < 0 else 0))
                        while (ax, ay) != (x, y):
                            ss = chess.square(ax, ay)
                            if ss in pm:
                                cnt_between += 1
                            ax += (1 if pf - kf > 0 else (-1 if pf - kf < 0 else 0))
                            ay += (1 if pr - kr > 0 else (-1 if pr - kr < 0 else 0))
                        # candidate should be the only one between king and slider
                        if cnt_between == 1:
                            cnt += 1
                        blocked = True
                        break
                    else:
                        blocked = True
                        break
                x += step_f; y += step_r
            # continue to next candidate
        return cnt
    try:
        return float(count_pins(chess.WHITE) - count_pins(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Mobility imbalance and check pressure: (white_moves - black_moves)/40 + (white_in_check?1:-1 if black_in_check) ; positive favors White mobility/less check.'
    try:
        # count white moves
        w_moves = 0
        b_moves = 0
        try:
            bc_w = board.copy(); bc_w.turn = chess.WHITE
            w_moves = sum(1 for _ in bc_w.legal_moves)
        except Exception:
            # fallback: if copy not available, try to count if current turn is white
            if board.turn == chess.WHITE:
                w_moves = sum(1 for _ in board.legal_moves)
            else:
                # try toggling by making a null move if allowed would be complex; fallback to 0
                w_moves = 0
        try:
            bc_b = board.copy(); bc_b.turn = chess.BLACK
            b_moves = sum(1 for _ in bc_b.legal_moves)
        except Exception:
            if board.turn == chess.BLACK:
                b_moves = sum(1 for _ in board.legal_moves)
            else:
                b_moves = 0
        # check flags
        try:
            bc = board.copy(); bc.turn = chess.WHITE
            white_in_check = bc.is_check()
        except Exception:
            white_in_check = False
        try:
            bc = board.copy(); bc.turn = chess.BLACK
            black_in_check = bc.is_check()
        except Exception:
            black_in_check = False
        mobility = (w_moves - b_moves) / 40.0
        check_term = (1.0 if white_in_check else 0.0) - (1.0 if black_in_check else 0.0)
        return float(mobility + check_term)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in count of 7th-rank passed pawns that have a friendly rook behind them on the same file (rook supports promotion from behind)'
    piece_map = board.piece_map()
    def is_passed(p_sq, color):
        p_file = chess.square_file(p_sq)
        p_rank = chess.square_rank(p_sq)
        for sq, p in piece_map.items():
            if p.piece_type == chess.PAWN and p.color != color:
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                if abs(f - p_file) <= 1:
                    if color == chess.WHITE and r > p_rank:
                        return False
                    if color == chess.BLACK and r < p_rank:
                        return False
        return True
    def has_friendly_rook_behind(p_sq, color):
        p_file = chess.square_file(p_sq)
        p_rank = chess.square_rank(p_sq)
        for sq, p in piece_map.items():
            if p.piece_type == chess.ROOK and p.color == color:
                r_file = chess.square_file(sq)
                r_rank = chess.square_rank(sq)
                if r_file == p_file:
                    if color == chess.WHITE and r_rank < p_rank:
                        return True
                    if color == chess.BLACK and r_rank > p_rank:
                        return True
        return False
    white_count = 0
    black_count = 0
    for sq, p in piece_map.items():
        if p.piece_type == chess.PAWN and p.color == chess.WHITE and chess.square_rank(sq) == 6 and is_passed(sq, chess.WHITE):
            if has_friendly_rook_behind(sq, chess.WHITE):
                white_count += 1
        if p.piece_type == chess.PAWN and p.color == chess.BLACK and chess.square_rank(sq) == 1 and is_passed(sq, chess.BLACK):
            if has_friendly_rook_behind(sq, chess.BLACK):
                black_count += 1
    return float(white_count - black_count)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in count of enemy rooks that lie on the pawn file between a 7th-rank pawn and the opponent king (a cutting rook)'
    pm = board.piece_map()
    def count_cutting(color):
        cnt = 0
        for sq, p in pm.items():
            if p.piece_type != chess.PAWN or p.color != color:
                continue
            rank = chess.square_rank(sq)
            file = chess.square_file(sq)
            if not ((color == chess.WHITE and rank == 6) or (color == chess.BLACK and rank == 1)):
                continue
            # opponent king location
            king_sq = None
            for s,q in pm.items():
                if q.piece_type == chess.KING and q.color != color:
                    king_sq = s
                    break
            if king_sq is None:
                continue
            king_rank = chess.square_rank(king_sq)
            for r_sq, r in pm.items():
                if r.piece_type == chess.ROOK and r.color != color:
                    rook_file = chess.square_file(r_sq)
                    rook_rank = chess.square_rank(r_sq)
                    if rook_file != file:
                        continue
                    # rook between pawn and king on the file?
                    # ensure it's strictly between pawn and king
                    if (rook_rank - rank) * (king_rank - rank) > 0 and abs(rook_rank - rank) < abs(king_rank - rank):
                        cnt += 1
                        break
        return cnt
    return float(count_cutting(chess.WHITE) - count_cutting(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in rook mobility measured as reachable squares (empty squares + first enemy capture) summed over rooks'
    pm = board.piece_map()
    def rook_mobility_for(color):
        mobility = 0
        for sq, p in pm.items():
            if p.piece_type != chess.ROOK or p.color != color:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            for df, dr in ((1,0),(-1,0),(0,1),(0,-1)):
                nf, nr = f + df, r + dr
                while 0 <= nf < 8 and 0 <= nr < 8:
                    nsq = nf + nr * 8
                    if nsq in pm:
                        # blocked; if enemy piece, count as capturable then break
                        if pm[nsq].color != color:
                            mobility += 1
                        break
                    mobility += 1
                    nf += df
                    nr += dr
        return mobility
    return float(rook_mobility_for(chess.WHITE) - rook_mobility_for(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Difference (Black_mean_distance - White_mean_distance) of king-to-7th-pawn Manhattan distances (smaller distance is better for the pawn side)'
    pm = board.piece_map()
    white_dists = []
    black_dists = []
    # find kings
    white_king = None
    black_king = None
    for sq, p in pm.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                white_king = sq
            else:
                black_king = sq
    for sq, p in pm.items():
        if p.piece_type == chess.PAWN and p.color == chess.WHITE and chess.square_rank(sq) == 6:
            if white_king is not None:
                white_dists.append(chess.square_distance(sq, white_king))
        if p.piece_type == chess.PAWN and p.color == chess.BLACK and chess.square_rank(sq) == 1:
            if black_king is not None:
                black_dists.append(chess.square_distance(sq, black_king))
    if not white_dists and not black_dists:
        return 0.0
    # use large default mean for missing side
    default = 14.0
    white_mean = sum(white_dists)/len(white_dists) if white_dists else default
    black_mean = sum(black_dists)/len(black_dists) if black_dists else default
    return float(black_mean - white_mean)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in count of enemy rooks occupying or directly on the promotion square (blocking immediate promotion) for 7th-rank pawns'
    pm = board.piece_map()
    white_block = 0
    black_block = 0
    for sq, p in pm.items():
        if p.piece_type != chess.PAWN:
            continue
        file = chess.square_file(sq)
        rank = chess.square_rank(sq)
        if p.color == chess.WHITE and rank == 6:
            promo_sq = file + 7*8
            occ = pm.get(promo_sq)
            if occ is not None and occ.piece_type == chess.ROOK and occ.color != chess.WHITE:
                white_block += 1
        if p.color == chess.BLACK and rank == 1:
            promo_sq = file + 0*8
            occ = pm.get(promo_sq)
            if occ is not None and occ.piece_type == chess.ROOK and occ.color != chess.BLACK:
                black_block += 1
    return float(white_block - black_block)

def feature(board: chess.Board) -> float:
    'Difference (Black_min - White_min) of opponent-king Manhattan distances to promotion squares of 7th-rank pawns (larger positive favors White)'
    pm = board.piece_map()
    # find kings
    white_king = None
    black_king = None
    for sq, p in pm.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                white_king = sq
            else:
                black_king = sq
    white_min = 100
    black_min = 100
    for sq, p in pm.items():
        if p.piece_type != chess.PAWN:
            continue
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if p.color == chess.WHITE and r == 6:
            promo = f + 7*8
            if black_king is not None:
                d = chess.square_distance(promo, black_king)
                if d < white_min:
                    white_min = d
        if p.color == chess.BLACK and r == 1:
            promo = f + 0*8
            if white_king is not None:
                d = chess.square_distance(promo, white_king)
                if d < black_min:
                    black_min = d
    if white_min == 100 and black_min == 100:
        return 0.0
    if white_min == 100:
        white_min = 14
    if black_min == 100:
        black_min = 14
    return float(black_min - white_min)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in count of isolated 7th-rank passed pawns (a passed pawn with no friendly pawns on adjacent files)'
    pm = board.piece_map()
    # helper to check any friendly pawn on adjacent files
    file_to_pawns = {}
    for sq, p in pm.items():
        if p.piece_type == chess.PAWN:
            f = chess.square_file(sq)
            file_to_pawns.setdefault((p.color, f), 0)
            file_to_pawns[(p.color, f)] += 1
    def is_isolated_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        # only consider 7th rank pawns
        if color == chess.WHITE and r != 6:
            return False
        if color == chess.BLACK and r != 1:
            return False
        # passed check (simple)
        for osq, op in pm.items():
            if op.piece_type == chess.PAWN and op.color != color:
                of = chess.square_file(osq)
                orank = chess.square_rank(osq)
                if abs(of - f) <= 1:
                    if color == chess.WHITE and orank > r:
                        return False
                    if color == chess.BLACK and orank < r:
                        return False
        # check adjacent friendly pawns any rank
        for af in (f-1, f+1):
            if 0 <= af < 8 and file_to_pawns.get((color, af), 0) > 0:
                return False
        return True
    white_iso = 0
    black_iso = 0
    for sq, p in pm.items():
        if p.piece_type == chess.PAWN:
            if p.color == chess.WHITE and is_isolated_passed(sq, chess.WHITE):
                white_iso += 1
            if p.color == chess.BLACK and is_isolated_passed(sq, chess.BLACK):
                black_iso += 1
    return float(white_iso - black_iso)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in count of 7th-rank passed pawns that have both a friendly king within distance<=2 and a friendly rook on the pawn file (good king+rook coordination)'
    pm = board.piece_map()
    # find kings
    white_king = None
    black_king = None
    for sq, p in pm.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                white_king = sq
            else:
                black_king = sq
    def has_rook_on_file(file, color):
        for sq, p in pm.items():
            if p.piece_type == chess.ROOK and p.color == color and chess.square_file(sq) == file:
                return True
        return False
    white_score = 0
    black_score = 0
    for sq, p in pm.items():
        if p.piece_type != chess.PAWN:
            continue
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if p.color == chess.WHITE and r == 6:
            if white_king is not None and chess.square_distance(sq, white_king) <= 2 and has_rook_on_file(f, chess.WHITE):
                white_score += 1
        if p.color == chess.BLACK and r == 1:
            if black_king is not None and chess.square_distance(sq, black_king) <= 2 and has_rook_on_file(f, chess.BLACK):
                black_score += 1
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in count of 7th-rank pawns whose forward (promotion) square is empty (indicates immediate promotion if it becomes that side\'s move)'
    pm = board.piece_map()
    white_ready = 0
    black_ready = 0
    for sq, p in pm.items():
        if p.piece_type != chess.PAWN:
            continue
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if p.color == chess.WHITE and r == 6:
            promo_sq = f + 7*8
            if promo_sq not in pm:
                white_ready += 1
        if p.color == chess.BLACK and r == 1:
            promo_sq = f + 0*8
            if promo_sq not in pm:
                black_ready += 1
    return float(white_ready - black_ready)

def feature(board: chess.Board) -> float:
    'Attacking pressure on each king: (white attackers around black king) - (black attackers around white king), normalized'
    try:
        # helper to sum attackers to king-square and adjacent squares
        def king_pressure(target_color_attackers, king_square):
            if king_square is None:
                return 0
            total = 0
            kr = chess.square_rank(king_square)
            kf = chess.square_file(king_square)
            # consider king square and surrounding 8 squares
            for dr in (-1, 0, 1):
                for df in (-1, 0, 1):
                    r = kr + dr
                    f = kf + df
                    if 0 <= r <= 7 and 0 <= f <= 7:
                        sq = chess.square(f, r)
                        try:
                            total += len(board.attackers(target_color_attackers, sq))
                        except Exception:
                            # attackers may raise on odd cases; ignore
                            total += 0
            return total
        wm = None
        bm = None
        # find kings
        white_king_sq = None
        black_king_sq = None
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king_sq = sq
                else:
                    black_king_sq = sq
        white_pressure_on_black = king_pressure(chess.WHITE, black_king_sq)
        black_pressure_on_white = king_pressure(chess.BLACK, white_king_sq)
        # normalize by max possible ~ 16 attackers around area, keep as pawn-units by dividing by 8
        return float((white_pressure_on_black - black_pressure_on_white) / 8.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in mobility (legal moves): #white_legal_moves - #black_legal_moves, normalized'
    try:
        # try to use board.copy() to query opponent legal moves safely
        bcopy = board.copy()
        bcopy.turn = chess.WHITE
        white_moves = sum(1 for _ in bcopy.legal_moves)
        bcopy = board.copy()
        bcopy.turn = chess.BLACK
        black_moves = sum(1 for _ in bcopy.legal_moves)
        # normalize by typical max ~ 50
        return float((white_moves - black_moves) / 50.0)
    except Exception:
        # fallback: if we can't copy, return mobility for current side and 0 for other
        try:
            curr = sum(1 for _ in board.legal_moves)
            if board.turn == chess.WHITE:
                return float(curr / 50.0)
            else:
                return float(-curr / 50.0)
        except Exception:
            return 0.0

def feature(board: chess.Board) -> float:
    'Rooks on open or semi-open files: (white advantage) open_file_count + 0.5*semi_open_count difference'
    try:
        # file has a pawn if any pawn on that file
        pawn_files = [False] * 8
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                pawn_files[chess.square_file(sq)] = True
        white_score = 0.0
        black_score = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                if not pawn_files[f]:
                    # open file
                    if p.color == chess.WHITE:
                        white_score += 1.0
                    else:
                        black_score += 1.0
                else:
                    # check for semi-open: no own pawns on that file
                    has_own_pawn = False
                    for s2, p2 in board.piece_map().items():
                        if p2.piece_type == chess.PAWN and p2.color == p.color and chess.square_file(s2) == f:
                            has_own_pawn = True
                            break
                    if not has_own_pawn:
                        if p.color == chess.WHITE:
                            white_score += 0.5
                        else:
                            black_score += 0.5
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Connected passed pawns advantage: counts passed pawns that have same-color pawn on adjacent file behind them (weighted)'
    try:
        def is_passed(sq, color):
            r = chess.square_rank(sq)
            f = chess.square_file(sq)
            # iterate forward files ahead for opponent pawns
            if color == chess.WHITE:
                for af in (f-1, f, f+1):
                    for rr in range(r+1, 8):
                        if 0 <= af <= 7:
                            p = board.piece_at(chess.square(af, rr))
                            if p and p.piece_type == chess.PAWN and p.color == chess.BLACK:
                                return False
                return True
            else:
                for af in (f-1, f, f+1):
                    for rr in range(r-1, -1, -1):
                        if 0 <= af <= 7:
                            p = board.piece_at(chess.square(af, rr))
                            if p and p.piece_type == chess.PAWN and p.color == chess.WHITE:
                                return False
                return True
        white = 0.0
        black = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                if is_passed(sq, p.color):
                    f = chess.square_file(sq)
                    r = chess.square_rank(sq)
                    # check for supporting pawn on adjacent file behind (closer to own side)
                    support = 0
                    for adj in (f-1, f+1):
                        if 0 <= adj <= 7:
                            if p.color == chess.WHITE:
                                behind_rank = r-1
                            else:
                                behind_rank = r+1
                            if 0 <= behind_rank <= 7:
                                p2 = board.piece_at(chess.square(adj, behind_rank))
                                if p2 and p2.piece_type == chess.PAWN and p2.color == p.color:
                                    support += 1
                    score = 1.0 + 0.5 * support
                    if p.color == chess.WHITE:
                        white += score
                    else:
                        black += score
        return float(white - black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material-under-attack: sum of my pieces that are attacked by enemy (in pawn units, white - black)'
    try:
        values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:20000}
        white_attacked = 0
        black_attacked = 0
        for sq, p in board.piece_map().items():
            try:
                if p.color == chess.WHITE:
                    if board.is_attacked_by(chess.BLACK, sq):
                        white_attacked += values.get(p.piece_type, 0)
                else:
                    if board.is_attacked_by(chess.WHITE, sq):
                        black_attacked += values.get(p.piece_type, 0)
            except Exception:
                continue
        # return as pawn-equivalents (divide by 100)
        return float((black_attacked - white_attacked) / 100.0)  # positive means white is attacking more of black
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn shield density near king: (#pawns in 8-neighborhood of king) difference white - black'
    try:
        def pawn_shield(king_sq, color):
            if king_sq is None:
                return 0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            count = 0
            for dr in (-1, 0, 1):
                for df in (-1, 0, 1):
                    if dr == 0 and df == 0:
                        continue
                    r = kr + dr
                    f = kf + df
                    if 0 <= r <= 7 and 0 <= f <= 7:
                        p = board.piece_at(chess.square(f, r))
                        if p and p.piece_type == chess.PAWN and p.color == color:
                            count += 1
            return count
        white_king = None
        black_king = None
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        return float(pawn_shield(black_king, chess.WHITE) - pawn_shield(white_king, chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rooks on opponent seventh rank advantage (white_rooks_on_7 - black_rooks_on_7)'
    try:
        white = 0
        black = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                r = chess.square_rank(sq)
                # white seventh rank is rank index 6, black seventh rank is index 1
                if p.color == chess.WHITE and r == 6:
                    white += 1
                if p.color == chess.BLACK and r == 1:
                    black += 1
        return float(white - black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Low-mobility (potentially trapped) pieces count: (#my_nonpawn_pieces_with<=1_legal_move) difference white - black'
    try:
        def low_mobility_count(color):
            try:
                b = board.copy()
                b.turn = color
                # map from square to count of legal moves
                counts = {}
                for mv in b.legal_moves:
                    counts[mv.from_square] = counts.get(mv.from_square, 0) + 1
                total = 0
                for sq, p in b.piece_map().items():
                    if p.color == color and p.piece_type != chess.PAWN:
                        c = counts.get(sq, 0)
                        if c <= 1:
                            total += 1
                return total
            except Exception:
                return 0
        return float(low_mobility_count(chess.WHITE) - low_mobility_count(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Queen proximity to enemy king advantage: (black_queen_dist - white_queen_dist) normalized (positive if white queen is closer)'
    try:
        # find kings
        white_king = None
        black_king = None
        white_q_d = 8
        black_q_d = 8
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.QUEEN:
                if p.color == chess.WHITE and black_king is not None:
                    white_q_d = min(white_q_d, chess.square_distance(sq, black_king))
                if p.color == chess.BLACK and white_king is not None:
                    black_q_d = min(black_q_d, chess.square_distance(sq, white_king))
        # if no queen set distance large (8). Return difference (black - white) so positive => white closer
        return float((black_q_d - white_q_d) / 8.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn promotion progress advantage: sum over pawns of normalized advancement toward promotion (white - black)'
    try:
        white_progress = 0.0
        black_progress = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                r = chess.square_rank(sq)
                if p.color == chess.WHITE:
                    # distance to rank 8: 7 - r. Normalize by 7 so a pawn on rank8 gives 0..1 range
                    prog = (r) / 7.0  # r=0 rank1 -> 0.0 ; r=6 -> 6/7 ; r=7 -> 1.0
                    white_progress += prog
                else:
                    # black pawn progress toward white side: (7 - r)/7 but from black perspective distance to rank1
                    prog = (7 - r) / 7.0
                    black_progress += prog
        return float(white_progress - black_progress)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of advanced (one-step-from-promotion) pawns: white_on_7th - black_on_2nd'
    wm = 0
    bm = 0
    for sq, p in board.piece_map().items():
        if p.piece_type != chess.PAWN:
            continue
        r = chess.square_rank(sq)
        if p.color == chess.WHITE and r == 6:
            # approximate threat: forward square must be empty (simple heuristic)
            forward = chess.square(chess.square_file(sq), 7)
            if board.piece_at(forward) is None:
                wm += 1
        if p.color == chess.BLACK and r == 1:
            forward = chess.square(chess.square_file(sq), 0)
            if board.piece_at(forward) is None:
                bm += 1
    return float(wm - bm)

def feature(board: chess.Board) -> float:
    'Count of friendly rooks placed directly behind pawns on same file (white - black)'
    white_count = 0
    black_count = 0
    pieces = board.piece_map()
    for sq, p in pieces.items():
        if p.piece_type != chess.PAWN:
            continue
        file = chess.square_file(sq)
        rank = chess.square_rank(sq)
        if p.color == chess.WHITE:
            # look for white rook on same file with rank < pawn rank (behind)
            for rsq, rp in pieces.items():
                if rp.piece_type == chess.ROOK and rp.color == chess.WHITE and chess.square_file(rsq) == file and chess.square_rank(rsq) < rank:
                    # ensure no blocking piece directly between rook and pawn (approx)
                    blocked = False
                    for r in range(chess.square_rank(rsq) + 1, rank):
                        if board.piece_at(chess.square(file, r)) is not None:
                            blocked = True
                            break
                    if not blocked:
                        white_count += 1
                        break
        else:
            # black pawn: rook should be behind it (higher rank number)
            for rsq, rp in pieces.items():
                if rp.piece_type == chess.ROOK and rp.color == chess.BLACK and chess.square_file(rsq) == file and chess.square_rank(rsq) > rank:
                    blocked = False
                    for r in range(rank + 1, chess.square_rank(rsq)):
                        if board.piece_at(chess.square(file, r)) is not None:
                            blocked = True
                            break
                    if not blocked:
                        black_count += 1
                        break
    return float(white_count - black_count)

def feature(board: chess.Board) -> float:
    'Friendly rook cutting off the opponent king from a pawn promotion file (white_cutoffs - black_cutoffs)'
    white_cut = 0
    black_cut = 0
    pieces = board.piece_map()
    # find kings
    wk = bk = None
    for sq, p in pieces.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                wk = sq
            else:
                bk = sq
    for sq, p in list(pieces.items()):
        if p.piece_type != chess.PAWN:
            continue
        file = chess.square_file(sq)
        pr = 7 if p.color == chess.WHITE else 0
        promo_sq = chess.square(file, pr)
        opp_king = bk if p.color == chess.WHITE else wk
        if opp_king is None:
            continue
        kf = chess.square_file(opp_king)
        kr = chess.square_rank(opp_king)
        # consider only same file cutoffs (simple heuristic)
        if kf != file:
            continue
        # check for a friendly rook between opp king and promotion square
        for rsq, rp in pieces.items():
            if rp.piece_type != chess.ROOK or rp.color != p.color:
                continue
            rr = chess.square_rank(rsq)
            krange_min = min(kr, pr)
            krange_max = max(kr, pr)
            if krange_min < rr < krange_max:
                # no need to check blocking; rook itself is between
                if p.color == chess.WHITE:
                    white_cut += 1
                else:
                    black_cut += 1
                break
    return float(white_cut - black_cut)

def feature(board: chess.Board) -> float:
    'Count of pawns on advanced ranks (rank >=5 for white, rank <=2 for black) that are defended by rook or king (white - black)'
    pieces = board.piece_map()
    wdef = 0.0
    bdef = 0.0
    # precompute king square
    kings = {p.color: sq for sq, p in pieces.items() if p.piece_type == chess.KING}
    for sq, p in pieces.items():
        if p.piece_type != chess.PAWN:
            continue
        r = chess.square_rank(sq)
        if p.color == chess.WHITE and r >= 5:
            defended = False
            # defended by a rook
            attackers = board.attackers(chess.WHITE, sq)
            for a in attackers:
                ap = board.piece_at(a)
                if ap is not None and ap.piece_type == chess.ROOK and ap.color == chess.WHITE:
                    defended = True
                    break
            # defended by king adjacency
            wk_sq = kings.get(chess.WHITE)
            if not defended and wk_sq is not None and chess.square_distance(wk_sq, sq) <= 1:
                defended = True
            if defended:
                wdef += 1.0
        if p.color == chess.BLACK and r <= 2:
            defended = False
            attackers = board.attackers(chess.BLACK, sq)
            for a in attackers:
                ap = board.piece_at(a)
                if ap is not None and ap.piece_type == chess.ROOK and ap.color == chess.BLACK:
                    defended = True
                    break
            bk_sq = kings.get(chess.BLACK)
            if not defended and bk_sq is not None and chess.square_distance(bk_sq, sq) <= 1:
                defended = True
            if defended:
                bdef += 1.0
    return float(wdef - bdef)

def feature(board: chess.Board) -> float:
    'Squares on opponent half attacked by rooks (white_rook_attacks_on_black_half - black_rook_attacks_on_white_half)'
    pieces = board.piece_map()
    white_attacks = 0
    black_attacks = 0
    # iterate every square and test if an attacker rook of given color attacks it
    for sq in range(64):
        r = chess.square_rank(sq)
        # white rooks attacking squares on black half (r >= 4)
        if r >= 4:
            attackers = board.attackers(chess.WHITE, sq)
            for a in attackers:
                ap = board.piece_at(a)
                if ap is not None and ap.piece_type == chess.ROOK and ap.color == chess.WHITE:
                    white_attacks += 1
                    break
        # black rooks attacking squares on white half (r <= 3)
        if r <= 3:
            attackers = board.attackers(chess.BLACK, sq)
            for a in attackers:
                ap = board.piece_at(a)
                if ap is not None and ap.piece_type == chess.ROOK and ap.color == chess.BLACK:
                    black_attacks += 1
                    break
    return float(white_attacks - black_attacks)

def feature(board: chess.Board) -> float:
    'Difference in distance from nearest friendly rook to the pawn promotion square: (black_min - white_min); smaller is better for that side'
    pieces = board.piece_map()
    white_rooks = [sq for sq, p in pieces.items() if p.piece_type == chess.ROOK and p.color == chess.WHITE]
    black_rooks = [sq for sq, p in pieces.items() if p.piece_type == chess.ROOK and p.color == chess.BLACK]
    INF = 100.0
    white_min = INF
    black_min = INF
    for sq, p in pieces.items():
        if p.piece_type != chess.PAWN:
            continue
        file = chess.square_file(sq)
        promo_rank = 7 if p.color == chess.WHITE else 0
        promo_sq = chess.square(file, promo_rank)
        if p.color == chess.WHITE:
            for rs in white_rooks:
                d = chess.square_distance(rs, promo_sq)
                if d < white_min:
                    white_min = d
        else:
            for rs in black_rooks:
                d = chess.square_distance(rs, promo_sq)
                if d < black_min:
                    black_min = d
    if white_min == INF:
        white_min = 14.0
    if black_min == INF:
        black_min = 14.0
    return float(black_min - white_min)

def feature(board: chess.Board) -> float:
    'Count of advanced pawns (white on 7th / black on 2nd) that are attacked by an enemy rook (white_attacked - black_attacked)'
    pieces = board.piece_map()
    w_att = 0
    b_att = 0
    for sq, p in pieces.items():
        if p.piece_type != chess.PAWN:
            continue
        r = chess.square_rank(sq)
        if p.color == chess.WHITE and r == 6:
            # if attacked by black rook
            attackers = board.attackers(chess.BLACK, sq)
            for a in attackers:
                ap = board.piece_at(a)
                if ap is not None and ap.piece_type == chess.ROOK and ap.color == chess.BLACK:
                    w_att += 1
                    break
        if p.color == chess.BLACK and r == 1:
            attackers = board.attackers(chess.WHITE, sq)
            for a in attackers:
                ap = board.piece_at(a)
                if ap is not None and ap.piece_type == chess.ROOK and ap.color == chess.WHITE:
                    b_att += 1
                    break
    return float(w_att - b_att)

def feature(board: chess.Board) -> float:
    'Difference in Manhattan distance from kings to their nearest pawn promotion square: (black_min_dist - white_min_dist)'
    pieces = board.piece_map()
    kings = {p.color: sq for sq, p in pieces.items() if p.piece_type == chess.KING}
    white_min = 100
    black_min = 100
    for sq, p in pieces.items():
        if p.piece_type != chess.PAWN:
            continue
        promo_sq = chess.square(chess.square_file(sq), 7 if p.color == chess.WHITE else 0)
        if chess.square_rank(sq) >= 0:  # any pawn
            if p.color == chess.WHITE and kings.get(chess.WHITE) is not None:
                d = chess.square_distance(kings[chess.WHITE], promo_sq)
                if d < white_min:
                    white_min = d
            if p.color == chess.BLACK and kings.get(chess.BLACK) is not None:
                d = chess.square_distance(kings[chess.BLACK], promo_sq)
                if d < black_min:
                    black_min = d
    if white_min == 100:
        white_min = 14
    if black_min == 100:
        black_min = 14
    return float(black_min - white_min)

def feature(board: chess.Board) -> float:
    'Isolated pawn count difference (black_isolated - white_isolated); isolated pawns are more of a weakness for that side'
    pieces = board.piece_map()
    white_pawns_by_file = {f: 0 for f in range(8)}
    black_pawns_by_file = {f: 0 for f in range(8)}
    for sq, p in pieces.items():
        if p.piece_type != chess.PAWN:
            continue
        f = chess.square_file(sq)
        if p.color == chess.WHITE:
            white_pawns_by_file[f] += 1
        else:
            black_pawns_by_file[f] += 1
    white_iso = 0
    black_iso = 0
    for f in range(8):
        if white_pawns_by_file[f] > 0:
            neigh = 0
            if f - 1 >= 0:
                neigh += white_pawns_by_file[f - 1]
            if f + 1 <= 7:
                neigh += white_pawns_by_file[f + 1]
            if neigh == 0:
                white_iso += white_pawns_by_file[f]
        if black_pawns_by_file[f] > 0:
            neigh = 0
            if f - 1 >= 0:
                neigh += black_pawns_by_file[f - 1]
            if f + 1 <= 7:
                neigh += black_pawns_by_file[f + 1]
            if neigh == 0:
                black_iso += black_pawns_by_file[f]
    return float(black_iso - white_iso)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in total attack pressure on the opponent king neighborhood (sum of attackers on king-adjacent squares), normalized'
    try:
        wm = 0
        bm = 0
        # find kings
        white_king_sq = None
        black_king_sq = None
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.KING:
                if piece.color == chess.WHITE:
                    white_king_sq = sq
                else:
                    black_king_sq = sq
        def neighborhood(sq):
            if sq is None:
                return []
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            neigh = []
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    nf = f + df
                    nr = r + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        neigh.append(chess.square(nf, nr))
            return neigh
        for sq in neighborhood(black_king_sq):
            # how many white pieces attack squares around black king
            try:
                wm += len(board.attackers(chess.WHITE, sq))
            except Exception:
                wm += 0
        for sq in neighborhood(white_king_sq):
            try:
                bm += len(board.attackers(chess.BLACK, sq))
            except Exception:
                bm += 0
        # normalize by a reasonable cap (max neighborhood attacks ~48)
        return float(max(min((wm - bm) / 12.0, 10.0), -10.0))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in legal mobility (legal moves count), normalized by 80'
    try:
        # current side moves
        cur_moves = len(list(board.legal_moves))
        # try to get other side by copying board
        try:
            b2 = board.copy()
            b2.turn = not board.turn
            other_moves = len(list(b2.legal_moves))
        except Exception:
            # fallback: approximate by generating pseudo-legal moves if copy not available
            other_moves = 0
        if board.turn == chess.WHITE:
            white_moves = cur_moves
            black_moves = other_moves
        else:
            white_moves = other_moves
            black_moves = cur_moves
        return float((white_moves - black_moves) / 80.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of pawn structure weaknesses: weighted count of isolated and doubled pawns (isolated*0.7 + doubled*0.5)'
    try:
        pm = board.piece_map()
        wp_files = {}
        bp_files = {}
        for sq, piece in pm.items():
            if piece.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if piece.color == chess.WHITE:
                    wp_files.setdefault(f, 0)
                    wp_files[f] += 1
                else:
                    bp_files.setdefault(f, 0)
                    bp_files[f] += 1
        def weakness(files_dict, color):
            iso = 0
            dbl = 0
            for f, count in files_dict.items():
                if count > 1:
                    dbl += (count - 1)
                # isolated: no pawns on adjacent files
                if (f - 1) not in files_dict and (f + 1) not in files_dict:
                    iso += files_dict[f]
            return iso * 0.7 + dbl * 0.5
        w_weak = weakness(wp_files, chess.WHITE)
        b_weak = weakness(bp_files, chess.BLACK)
        return float(w_weak - b_weak)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in number of rooks on open files (no pawns of either color on that file)'
    try:
