        return float(w_rooks - b_rooks)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in count of passed pawns that have a clear file path to promotion (no enemy pieces ahead on same file)'
    try:
        pm = board.piece_map()
        def is_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                # no enemy pawn on same file or adjacent files ahead (ranks > r)
                for sq2, p2 in pm.items():
                    if p2.piece_type == chess.PAWN and p2.color == chess.BLACK:
                        rf = chess.square_file(sq2)
                        rr = chess.square_rank(sq2)
                        if abs(rf - f) <= 1 and rr > r:
                            return False
                return True
            else:
                for sq2, p2 in pm.items():
                    if p2.piece_type == chess.PAWN and p2.color == chess.WHITE:
                        rf = chess.square_file(sq2)
                        rr = chess.square_rank(sq2)
                        if abs(rf - f) <= 1 and rr < r:
                            return False
                return True
        def clear_path(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                for rr in range(r + 1, 8):
                    piece = board.piece_at(chess.square(f, rr))
                    if piece is not None and piece.color == chess.BLACK:
                        return False
                return True
            else:
                for rr in range(r - 1, -1, -1):
                    piece = board.piece_at(chess.square(f, rr))
                    if piece is not None and piece.color == chess.WHITE:
                        return False
                return True
        w = 0
        b = 0
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                if is_passed(sq, p.color) and clear_path(sq, p.color):
                    if p.color == chess.WHITE:
                        w += 1
                    else:
                        b += 1
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in pawn-shield strength in front of the king (count of friendly pawns on up-to-3 shield squares directly in front of the king)'
    try:
