        def shield_for(color):
            # find king
            ksq = None
            for sq, p in pm.items():
                if p.piece_type == chess.KING and p.color == color:
                    ksq = sq
                    break
            if ksq is None:
                return 0.0
            f = chess.square_file(ksq)
            r = chess.square_rank(ksq)
            count = 0
            dr = 1 if color == chess.WHITE else -1
            nr = r + dr
            for df in (-1, 0, 1):
                if 0 <= f + df <= 7 and 0 <= nr <= 7:
                    piece = board.piece_at(chess.square(f + df, nr))
                    if piece is not None and piece.piece_type == chess.PAWN and piece.color == color:
                        count += 1
            return float(count)
        return shield_for(chess.WHITE) - shield_for(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
