def feature(board: chess.Board) -> float:
    'Difference (White - Black) in control of the central 4x4 area (count of central squares attacked by each side, normalized)'
    try:
        center_squares = []
        for f in range(2, 6):  # c-f files (0-based)
            for r in range(2, 6):  # ranks 3-6 (0-based)
                center_squares.append(chess.square(f, r))
        w = 0
        b = 0
        for sq in center_squares:
            if board.is_attacked_by(chess.WHITE, sq):
                w += 1
            if board.is_attacked_by(chess.BLACK, sq):
                b += 1
        return float((w - b) / len(center_squares))
    except Exception:
