def feature(board: chess.Board) -> float:
    'Difference (White - Black) of rooks actively supporting passed pawns: +1 for each rook behind or attacking a friendly passed pawn promotion path'
    try:
        pm = board.piece_map()
        # helper to detect passed pawn (simple: no opposing pawn in same/adjacent files ahead)
        def is_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            for sq2, p2 in pm.items():
                if p2.piece_type != chess.PAWN or p2.color == color:
                    continue
                rf = chess.square_file(sq2)
                rr = chess.square_rank(sq2)
                if abs(rf - f) <= 1:
                    if color == chess.WHITE and rr > r:
                        return False
                    if color == chess.BLACK and rr < r:
                        return False
            return True
        def rook_support_count(color):
            cnt = 0
            for sq, p in pm.items():
                if p.piece_type == chess.PAWN and p.color == color and is_passed(sq, color):
                    f = chess.square_file(sq)
                    r = chess.square_rank(sq)
                    # promotion square
                    prom_rank = 7 if color == chess.WHITE else 0
                    prom_sq = chess.square(f, prom_rank)
                    # any friendly rook on same file behind the pawn?
                    for sq2, p2 in pm.items():
                        if p2.piece_type == chess.ROOK and p2.color == color:
                            rf = chess.square_file(sq2)
                            rr = chess.square_rank(sq2)
                            if rf == f:
                                if color == chess.WHITE and rr < r:
                                    cnt += 1; break
                                if color == chess.BLACK and rr > r:
                                    cnt += 1; break
                    else:
                        # or rook attacking the promotion square
                        for sq2, p2 in pm.items():
                            if p2.piece_type == chess.ROOK and p2.color == color:
                                if prom_sq in board.attackers(color, prom_sq):
                                    cnt += 1
                                    break
            return cnt
        w = rook_support_count(chess.WHITE)
        b = rook_support_count(chess.BLACK)
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
