def feature(board: chess.Board) -> float:
    'Alignment and proximity of rooks to the enemy king: sum over rooks of (1 if same rank/file + 1/(1+rank_distance)) for White minus Black'
    try:
        pm = board.piece_map()
        white_score = 0.0
        black_score = 0.0
        # find kings
        wk = None
        bk = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    wk = sq
                else:
                    bk = sq
        for sq, p in pm.items():
            if p.piece_type != chess.ROOK:
                continue
            if p.color == chess.WHITE and bk is not None:
                same_file = (chess.square_file(sq) == chess.square_file(bk))
                same_rank = (chess.square_rank(sq) == chess.square_rank(bk))
                rank_dist = abs(chess.square_rank(sq) - chess.square_rank(bk))
                add = (1.0 if same_file else 0.0) + (1.0 if same_rank else 0.0) + (1.0 / (1.0 + rank_dist))
                white_score += add
            if p.color == chess.BLACK and wk is not None:
                same_file = (chess.square_file(sq) == chess.square_file(wk))
                same_rank = (chess.square_rank(sq) == chess.square_rank(wk))
                rank_dist = abs(chess.square_rank(sq) - chess.square_rank(wk))
                add = (1.0 if same_file else 0.0) + (1.0 if same_rank else 0.0) + (1.0 / (1.0 + rank_dist))
                black_score += add
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Normalized difference (positive favors White) of the distance-to-promotion of the closest passed pawn (lower distance = closer)'
    try:
        pm = board.piece_map()
        def is_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                for of in (f-1, f, f+1):
                    if 0 <= of <= 7:
                        for orank in range(r+1, 8):
                            occ = board.piece_at(chess.square(of, orank))
                            if occ is not None and occ.piece_type == chess.PAWN and occ.color == chess.BLACK:
                                return False
                return True
            else:
                for of in (f-1, f, f+1):
                    if 0 <= of <= 7:
                        for orank in range(0, r):
                            occ = board.piece_at(chess.square(of, orank))
                            if occ is not None and occ.piece_type == chess.PAWN and occ.color == chess.WHITE:
                                return False
                return True
        min_white = 8
        min_black = 8
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                r = chess.square_rank(sq)
                if p.color == chess.WHITE and is_passed(sq, chess.WHITE):
                    dist = 7 - r
                    if dist < min_white:
                        min_white = dist
                if p.color == chess.BLACK and is_passed(sq, chess.BLACK):
                    dist = r
                    if dist < min_black:
                        min_black = dist
        # normalize to [-1,1] roughly by dividing by 8
        return float((min_black - min_white) / 8.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count difference (White - Black) of rooks placed ahead of their own passed pawns on the same file (rook nearer to promotion than the pawn)'
    try:
