def feature(board: chess.Board) -> float:
    'Difference (White - Black) of rook mobility estimated by sliding squares available (ignores checks); counts captures on first occupied square'
    try:
        pm = board.piece_map()
        occ = set(pm.keys())
        def rook_mobility_from(sq, color):
            mobility = 0
            directions = [(1,0),(-1,0),(0,1),(0,-1)]
            f = chess.square_file(sq); r = chess.square_rank(sq)
            for df, dr in directions:
                cf, cr = f, r
                while True:
                    cf += df; cr += dr
                    if not (0 <= cf <= 7 and 0 <= cr <= 7):
                        break
                    nsq = chess.square(cf, cr)
                    if nsq in occ:
                        p = board.piece_at(nsq)
                        if p is not None and p.color != color:
                            mobility += 1
                        break
                    mobility += 1
            return mobility
        wmob = 0
        bmob = 0
        for sq, p in pm.items():
            if p.piece_type == chess.ROOK:
                if p.color == chess.WHITE:
                    wmob += rook_mobility_from(sq, chess.WHITE)
                else:
                    bmob += rook_mobility_from(sq, chess.BLACK)
        return float(wmob - bmob)
    except Exception:
        return 0.0

