def feature(board: chess.Board) -> float:
    'Difference (White - Black) of Manhattan distance from each king to the closest enemy rook (larger positive means Black kings are relatively further from enemy rooks)'
    try:
        pm = board.piece_map()
        wk = bk = None
        white_rooks = []
        black_rooks = []
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE: wk = sq
                else: bk = sq
            if p.piece_type == chess.ROOK:
                if p.color == chess.WHITE: white_rooks.append(sq)
                else: black_rooks.append(sq)
        def closest_distance(target_king, enemy_rooks):
            if target_king is None or len(enemy_rooks) == 0:
                return 8
            best = 100
            for rsq in enemy_rooks:
                d = chess.square_distance(target_king, rsq)
                if d < best: best = d
            return min(best, 8)
        wd = closest_distance(wk, black_rooks)
        bd = closest_distance(bk, white_rooks)
        return float((bd - wd) / 8.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in the number of opponent rooks attacking the promotion squares of passed pawns (counts attacks by rooks, not just presence)'
    try:
        pm = board.piece_map()
        def is_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                for of in (f-1, f, f+1):
                    if 0 <= of <= 7:
                        for orank in range(r+1, 8):
                            occ = board.piece_at(chess.square(of, orank))
                            if occ is not None and occ.piece_type == chess.PAWN and occ.color == chess.BLACK:
                                return False
                return True
            else:
                for of in (f-1, f, f+1):
                    if 0 <= of <= 7:
                        for orank in range(0, r):
                            occ = board.piece_at(chess.square(of, orank))
                            if occ is not None and occ.piece_type == chess.PAWN and occ.color == chess.WHITE:
                                return False
                return True
        white_attacks = 0
        black_attacks = 0
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN and p.color == chess.WHITE and is_passed(sq, chess.WHITE):
                prom = chess.square(chess.square_file(sq), 7)
                for atk in board.attackers(chess.WHITE, prom):
                    ap = board.piece_at(atk)
                    if ap is not None and ap.piece_type == chess.ROOK:
                        white_attacks += 1
            if p.piece_type == chess.PAWN and p.color == chess.BLACK and is_passed(sq, chess.BLACK):
                prom = chess.square(chess.square_file(sq), 0)
                for atk in board.attackers(chess.BLACK, prom):
                    ap = board.piece_at(atk)
                    if ap is not None and ap.piece_type == chess.ROOK:
                        black_attacks += 1
        return float(white_attacks - black_attacks)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
