    try:
        pm = board.piece_map()
        wk = bk = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE: wk = sq
                else: bk = sq
        def safe_escapes(king_sq, color):
            if king_sq is None:
                return 0
            cnt = 0
            kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
            opponent = not color
            for df in (-1,0,1):
                for dr in (-1,0,1):
                    if df == 0 and dr == 0: continue
                    nf = kf + df; nr = kr + dr
                    if not (0 <= nf <= 7 and 0 <= nr <= 7):
                        continue
                    nsq = chess.square(nf, nr)
                    occ = board.piece_at(nsq)
                    if occ is not None and occ.color == color:
                        continue
                    # if square would be attacked by opponent in current position, consider unsafe
                    if board.is_attacked_by(opponent, nsq):
                        continue
                    cnt += 1
            return cnt
        ws = safe_escapes(wk, chess.WHITE)
        bs = safe_escapes(bk, chess.BLACK)
