def feature(board: chess.Board) -> float:
    'Difference (White - Black) of minimum squares-to-promotion among passed pawns; smaller is closer to promotion'
    import chess
    pieces = board.piece_map()
    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        for sq2, p in pieces.items():
            if p.piece_type == chess.PAWN and p.color != color:
                f2 = chess.square_file(sq2)
                r2 = chess.square_rank(sq2)
                if abs(f2 - f) <= 1:
                    if color == chess.WHITE and r2 > r:
                        return False
                    if color == chess.BLACK and r2 < r:
                        return False
        return True
    def min_steps_to_promote(color):
        best = None
        for sq, p in pieces.items():
            if p.piece_type == chess.PAWN and p.color == color and is_passed(sq, color):
                r = chess.square_rank(sq)
                steps = (7 - r) if color == chess.WHITE else r
                if best is None or steps < best:
                    best = steps
        return float(best) if best is not None else 8.0
    w = min_steps_to_promote(chess.WHITE)
    b = min_steps_to_promote(chess.BLACK)
    return float(b - w)

