def feature(board: chess.Board) -> float:
    'White minus Black: king centrality measured as negative Manhattan distance to center (d4,e4,d5,e5 averaged), higher favors more central king'
    import chess
    center_sqs = [chess.parse_square(s) for s in ('d4','e4','d5','e5')]
    pieces = board.piece_map()
    def king_centrality(color):
        ks = None
        for sq,p in pieces.items():
            if p.piece_type == chess.KING and p.color == color:
                ks = sq
                break
        if ks is None:
            return 0.0
        # take min manhattan distance to center squares and invert
        best = min(chess.square_distance(ks, cs) for cs in center_sqs)
        # Normalize: distances 0..7 -> map to 1..-1
        return float((7 - best) / 7.0)
    import chess as _c
    return king_centrality(_c.WHITE) - king_centrality(_c.BLACK)

def feature(board: chess.Board) -> float:
