def feature(board: chess.Board) -> float:
    'White minus Black: isolated pawn count difference (isolated pawns have no friendly pawns on adjacent files)'
    import chess
    pieces = board.piece_map()
    files_white = [0]*8
    files_black = [0]*8
    pawns = []
    for sq,p in pieces.items():
        if p.piece_type == chess.PAWN:
            f = chess.square_file(sq)
            if p.color == chess.WHITE:
                files_white[f] += 1
            else:
                files_black[f] += 1
            pawns.append((sq,p.color))
    def isolated_count(color):
        cnt = 0
        for sq,c in pawns:
            if c != color: continue
            f = chess.square_file(sq)
            left = files_white[f-1] if color==chess.WHITE and f-1>=0 else (files_black[f-1] if color==chess.BLACK and f-1>=0 else 0)
            right = files_white[f+1] if color==chess.WHITE and f+1<=7 else (files_black[f+1] if color==chess.BLACK and f+1<=7 else 0)
            # above logic is incorrect if we mix; instead compute per color arrays:
        return 0.0
    # Correct isolated calculation using per-color arrays
    def isolated_count_correct(color):
        cnt = 0
        arr = files_white if color==chess.WHITE else files_black
        for f in range(8):
            if arr[f] == 0: continue
            left = arr[f-1] if f-1>=0 else 0
            right = arr[f+1] if f+1<=7 else 0
            if left == 0 and right == 0:
                cnt += arr[f]
        return float(cnt)
    import chess as _c
    return isolated_count_correct(_c.WHITE) - isolated_count_correct(_c.BLACK)

def feature(board: chess.Board) -> float:
    'White minus Black: bishop control bonus for opponent passed-pawn promotion squares (1 if a bishop attacks the promotion square, else 0) summed'
    import chess
    pieces = board.piece_map()
    def is_passed(sq, color):
