        for sq2,p in pieces.items():
            if p.piece_type==chess.PAWN and p.color!=color:
                f2=chess.square_file(sq2); r2=chess.square_rank(sq2)
                if abs(f2-f)<=1:
                    if color==chess.WHITE and r2>r: return False
                    if color==chess.BLACK and r2<r: return False
        return True
    score_w = 0.0
    score_b = 0.0
    for sq,p in pieces.items():
        if p.piece_type == chess.PAWN and is_passed(sq, p.color):
            promo = chess.square(chess.square_file(sq), 7 if p.color==chess.WHITE else 0)
            # check if same side has a bishop attacking that square
            attackers_white = board.attackers(chess.WHITE, promo)
            attackers_black = board.attackers(chess.BLACK, promo)
            # consider bishops only
            w_bishop = any(board.piece_at(a) is not None and board.piece_at(a).piece_type==chess.BISHOP and board.piece_at(a).color==chess.WHITE for a in attackers_white)
            b_bishop = any(board.piece_at(a) is not None and board.piece_at(a).piece_type==chess.BISHOP and board.piece_at(a).color==chess.BLACK for a in attackers_black)
            if p.color == chess.WHITE:
                if w_bishop: score_w += 1.0
                if b_bishop: score_b += 0.0  # opponent bishop attacking white promotion is not a friendly control
            else:
                if b_bishop: score_b += 1.0
                if w_bishop: score_w += 0.0
    return float(score_w - score_b)

def feature(board: chess.Board) -> float:
    'Pawn shield strength in front of each king: (#friendly pawns on three front-shield squares) - 0.7*(#opponent attacks on those squares), white minus black'
    piece_map = board.piece_map()
    def king_square(color):
        for s, p in piece_map.items():
            if p.piece_type == chess.KING and p.color == color:
                return s
        return None
    def shield_score(color):
        ks = king_square(color)
        if ks is None:
            return 0.0
        f = chess.square_file(ks)
        r = chess.square_rank(ks)
        score = 0.0
        # for white we look "ahead" toward increasing ranks; for black decreasing
        direction = 1 if color == chess.WHITE else -1
        opponent = not color
        for df in (-1, 0, 1):
            sq_rank = r + direction
            sq_file = f + df
            if 0 <= sq_rank <= 7 and 0 <= sq_file <= 7:
                sq = chess.square(sq_file, sq_rank)
                p = board.piece_at(sq)
                if p is not None and p.piece_type == chess.PAWN and p.color == color:
                    score += 1.0
                if board.is_attacked_by(opponent, sq):
                    score -= 0.7
        return score
    ws = shield_score(chess.WHITE)
    bs = shield_score(chess.BLACK)
    return float(ws - bs)

def feature(board: chess.Board) -> float:
    'Weighted count of attackers in the 2-square king zone (attacking any square with Manhattan distance <=2 from enemy king), white attacking black king minus black attacking white king'
    piece_values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    piece_map = board.piece_map()
    def king_sq(color):
        for s, p in piece_map.items():
            if p.piece_type == chess.KING and p.color == color:
                return s
        return None
    def zone_attack_weight(attacker_color, target_king_sq):
        if target_king_sq is None:
            return 0.0
        attackers = board.attackers(attacker_color, target_king_sq)
        total = 0.0
        for sq in attackers:
            p = board.piece_at(sq)
            if p is None:
                continue
            dist = chess.square_distance(sq, target_king_sq)
            weight = piece_values.get(p.piece_type, 1.0)
            # closer attackers count more; distance 0 impossible here but safe
            total += weight * (1.0 / (1.0 + dist))
        return total
    w_king = king_sq(chess.WHITE)
    b_king = king_sq(chess.BLACK)
    white_att_on_black = zone_attack_weight(chess.WHITE, b_king)
    black_att_on_white = zone_attack_weight(chess.BLACK, w_king)
    return float(white_att_on_black - black_att_on_white)

def feature(board: chess.Board) -> float:
    'Queen activity and centralization: for each queen count legal moves + small bonus for proximity to center; returns white minus black'
    center_squares = [chess.parse_square(s) for s in ('d4','d5','e4','e5')]
    legal_from_count = {}
    for mv in board.legal_moves:
        legal_from_count[mv.from_square] = legal_from_count.get(mv.from_square, 0) + 1
    def queen_score(color):
        score = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.QUEEN and p.color == color:
                moves = legal_from_count.get(sq, 0)
                # center proximity: smaller distance -> bonus up to +2
                min_dist = min(chess.square_distance(sq, cs) for cs in center_squares)
                center_bonus = max(0.0, 2.0 - float(min_dist))
                score += moves + center_bonus
        return score
    return float(queen_score(chess.WHITE) - queen_score(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Weighted sum of pieces that are attacked more times than they are defended (vulnerability); weights by piece value, white minus black'
    piece_val = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    vm = board.piece_map()
    white_vuln = 0.0
    black_vuln = 0.0
    for sq, p in vm.items():
        color = p.color
        opp = not color
        attackers = len(board.attackers(opp, sq))
        defenders = len(board.attackers(color, sq))
        excess = max(0, attackers - defenders)
        if excess > 0:
            weight = piece_val.get(p.piece_type, 1.0) * float(excess)
            if color == chess.WHITE:
                white_vuln += weight
            else:
                black_vuln += weight
    return float(white_vuln - black_vuln)

def feature(board: chess.Board) -> float:
    'Count of likely trapped pieces: pieces with <=1 legal escape moves and which are attacked by opponent, weighted by piece value, white minus black'
    piece_val = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
