        w = 0.0
        b = 0.0
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.ROOK:
                rank = chess.square_rank(sq)
                if piece.color == chess.WHITE and rank == 6:
                    w += 1.0
                if piece.color == chess.BLACK and rank == 1:
                    b += 1.0
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Number of undefended (hanging) non-king pieces attacked by the opponent: white minus black'
    try:
        import chess
        white_hung = 0
        black_hung = 0
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.KING:
                continue
            occ_color = piece.color
            attackers = board.attackers(not occ_color, sq)
            if len(attackers) == 0:
                continue
            defenders = board.attackers(occ_color, sq)
            if len(defenders) == 0:
                if occ_color == chess.WHITE:
