def feature(board: chess.Board) -> float:
    'Weighted attackers on each king square: (White attackers on Black king weighted) - (Black attackers on White king weighted) using piece-value weights'
    try:
        import chess
        weights = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        pm = board.piece_map()
        white_king = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        def king_attack_weight(attacker_color, king_sq):
            if king_sq is None:
                return 0.0
            total = 0.0
            for a_sq in board.attackers(attacker_color, king_sq):
                p = board.piece_at(a_sq)
                if p is not None:
                    total += weights.get(p.piece_type, 0.0)
            return total
        white_on_black = king_attack_weight(chess.WHITE, black_king)
        black_on_white = king_attack_weight(chess.BLACK, white_king)
        # Return White attacking Black minus Black attacking White (positive = advantage for White)
        return float(white_on_black - black_on_white)
    except Exception:
        return 0.0

