def feature(board: chess.Board) -> float:
    'Sum of sliding and knight mobility for major pieces (queen and rooks) difference (White - Black) approximated by ray reachability (ignores checks)'
    try:
        import chess
        pm = board.piece_map()
        def sliding_reach(sq, deltas):
            cnt = 0
            f0 = chess.square_file(sq)
            r0 = chess.square_rank(sq)
            for df, dr in deltas:
                f = f0 + df
                r = r0 + dr
                while 0 <= f <= 7 and 0 <= r <= 7:
                    nsq = chess.square(f, r)
                    cnt += 1
                    if board.piece_at(nsq) is not None:
                        break
                    f += df
                    r += dr
            return cnt
        rook_dirs = [(1,0),(-1,0),(0,1),(0,-1)]
        bishop_dirs = [(1,1),(1,-1),(-1,1),(-1,-1)]
        white_mob = 0
        black_mob = 0
        for sq, p in pm.items():
            if p.piece_type == chess.ROOK:
                val = sliding_reach(sq, rook_dirs)
            elif p.piece_type == chess.QUEEN:
                val = sliding_reach(sq, rook_dirs) + sliding_reach(sq, bishop_dirs)
            else:
                val = 0
            if p.color == chess.WHITE:
                white_mob += val
            else:
                black_mob += val
        return float(white_mob - black_mob)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count difference of isolated passed pawns (passed and isolated) White - Black; passed pawn: no opposing pawn on same or adjacent files ahead'
    try:
        import chess
        pm = board.piece_map()
        def is_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                enemy_pawn_squares = [s for s, p in pm.items() if p.piece_type == chess.PAWN and p.color == chess.BLACK]
                for ef in range(max(0,f-1), min(7,f+1)+1):
                    for er in range(r+1,8):
                        if chess.square(ef, er) in enemy_pawn_squares:
                            return False
                return True
            else:
                enemy_pawn_squares = [s for s, p in pm.items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
                for ef in range(max(0,f-1), min(7,f+1)+1):
                    for er in range(0, r):
                        if chess.square(ef, er) in enemy_pawn_squares:
                            return False
                return True
        def is_isolated(sq, color):
            f = chess.square_file(sq)
            for af in (f-1, f+1):
                if 0 <= af <= 7:
                    for s, p in pm.items():
                        if p.piece_type == chess.PAWN and p.color == color and chess.square_file(s) == af:
                            return False
            return True
        white_cnt = 0
        black_cnt = 0
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                if is_passed(sq, p.color) and is_isolated(sq, p.color):
                    if p.color == chess.WHITE:
                        white_cnt += 1
                    else:
                        black_cnt += 1
        return float(white_cnt - black_cnt)
    except Exception:
        return 0.0

