def feature(board: chess.Board) -> float:
    'Net score for majors (rook/queen) aligned on same rank/file with opposing king with clear path; returns (white - black) in pawn units'
    try:
        values = {chess.ROOK:500, chess.QUEEN:900}
        piece_map = board.piece_map()
        white_score = 0.0
        black_score = 0.0
        # find kings
        white_king = None
        black_king = None
        for sq, p in piece_map.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        def path_clear(sq1, sq2):
            f1 = chess.square_file(sq1); r1 = chess.square_rank(sq1)
            f2 = chess.square_file(sq2); r2 = chess.square_rank(sq2)
            if f1 == f2:
                step = 1 if r2 > r1 else -1
                for r in range(r1 + step, r2, step):
                    if board.piece_at(chess.square(f1, r)) is not None:
                        return False
                return True
            if r1 == r2:
                step = 1 if f2 > f1 else -1
                for f in range(f1 + step, f2, step):
                    if board.piece_at(chess.square(f, r1)) is not None:
                        return False
                return True
            return False
        for sq, p in piece_map.items():
            if p.piece_type in (chess.ROOK, chess.QUEEN):
                if p.color == chess.WHITE and black_king is not None:
                    if chess.square_file(sq) == chess.square_file(black_king) or chess.square_rank(sq) == chess.square_rank(black_king):
                        if path_clear(sq, black_king):
                            white_score += values[p.piece_type] / 100.0
                if p.color == chess.BLACK and white_king is not None:
                    if chess.square_file(sq) == chess.square_file(white_king) or chess.square_rank(sq) == chess.square_rank(white_king):
                        if path_clear(sq, white_king):
                            black_score += values[p.piece_type] / 100.0
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Number of checking legal moves available to the side to move (how many moves immediately give check)'
    try:
        count = 0
        for mv in board.legal_moves:
            try:
                board.push(mv)
                if board.is_check():
                    count += 1
            finally:
                board.pop()
        return float(count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in control of opponent king file by majors when the attacking side has a semi-open file (white - black)'
    try:
        piece_map = board.piece_map()
        def semi_open_control(attacker_color):
            # opponent king
            opp_king_sq = None
            for sq, p in piece_map.items():
                if p.piece_type == chess.KING and p.color != attacker_color:
                    opp_king_sq = sq
                    break
            if opp_king_sq is None:
                return 0.0
            kf = chess.square_file(opp_king_sq)
            # check for pawns of attacker_color on that file (if any, not semi-open)
            for r in range(8):
                sq = chess.square(kf, r)
                p = board.piece_at(sq)
                if p is not None and p.piece_type == chess.PAWN and p.color == attacker_color:
                    return 0.0
            # now see if any rook/queen of attacker_color sits on that file with clear path
            score = 0.0
            for sq, p in piece_map.items():
                if p.color == attacker_color and p.piece_type in (chess.ROOK, chess.QUEEN):
                    if chess.square_file(sq) == kf:
                        # check clear
                        r1 = chess.square_rank(sq)
                        r2 = chess.square_rank(opp_king_sq)
                        step = 1 if r2 > r1 else -1
                        clear = True
                        for r in range(r1 + step, r2, step):
                            if board.piece_at(chess.square(kf, r)) is not None:
                                clear = False
                                break
                        if clear:
                            score += (500 if p.piece_type == chess.ROOK else 900) / 100.0
            return score
        return float(semi_open_control(chess.WHITE) - semi_open_control(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in summed material (pawn units) of opponent pieces within Manhattan distance <=2 of each king (black_near_white - white_near_black)'
    try:
        values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900}
        piece_map = board.piece_map()
        white_king_sq = None
        black_king_sq = None
        for sq, p in piece_map.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king_sq = sq
                else:
                    black_king_sq = sq
        def prox_sum(king_sq, attacker_color):
            s = 0
            if king_sq is None:
                return 0
            for sq, p in piece_map.items():
                if p.color == attacker_color and p.piece_type != chess.KING:
                    if chess.square_distance(sq, king_sq) <= 2:
                        s += values.get(p.piece_type, 0)
            return s
        b_near_w = prox_sum(white_king_sq, chess.BLACK)
        w_near_b = prox_sum(black_king_sq, chess.WHITE)
        return float((b_near_w - w_near_b) / 100.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in pawn shield counts in front of the kings (white_shield_count - black_shield_count)'
    try:
        piece_map = board.piece_map()
        white_king = None
        black_king = None
        for sq, p in piece_map.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        def shield_count(king_sq, color):
            if king_sq is None:
                return 0
            kr = chess.square_rank(king_sq)
            kf = chess.square_file(king_sq)
            cnt = 0
            # for white, in front is increasing ranks; for black decreasing
            drs = (1, 2) if color == chess.WHITE else (-1, -2)
            for df in (-1, 0, 1):
                for dr in drs:
                    rf = kf + df
                    rr = kr + dr
                    if 0 <= rf <= 7 and 0 <= rr <= 7:
                        sq = chess.square(rf, rr)
                        p = board.piece_at(sq)
                        if p is not None and p.piece_type == chess.PAWN and p.color == color:
                            cnt += 1
            return cnt
        w_sh = shield_count(white_king, chess.WHITE)
        b_sh = shield_count(black_king, chess.BLACK)
        return float(w_sh - b_sh)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Indicator difference whether a side has only king and pawns (1.0 if only king+pawns else 0.0); returns (white_only_king_pawns - black_only_king_pawns)'
    try:
