def feature(board: chess.Board) -> float:
    'Net material value (in pawn units) of pieces currently attacking the enemy king square (black_attack_value_on_white_king - white_attack_value_on_black_king)'
    try:
        values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900}
        piece_map = board.piece_map()
        white_king = None
        black_king = None
        for sq, p in piece_map.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        def attackers_value(king_sq, attacker_color):
            if king_sq is None:
                return 0
            atk_sqs = board.attackers(attacker_color, king_sq)
            s = 0
            for a in atk_sqs:
                p = board.piece_at(a)
