def feature(board: chess.Board) -> float:
    'King pawn shield balance: difference in number of friendly pawns immediately shielding the king (white - black)'
    try:
        pieces = board.piece_map()
        white_shield = 0
        black_shield = 0
        for sq, piece in pieces.items():
            if piece.piece_type == chess.KING:
                kfile = chess.square_file(sq)
                krank = chess.square_rank(sq)
                # consider pawns in same file and adjacent files, within 2 ranks ahead (relative to color)
                for df in (-1, 0, 1):
                    f = kfile + df
                    if not (0 <= f <= 7):
                        continue
                    if piece.color == chess.WHITE:
                        for dr in (1, 2):
                            r = krank + dr
                            if 0 <= r <= 7:
                                s = r * 8 + f
                                p = board.piece_at(s)
                                if p and p.piece_type == chess.PAWN and p.color == chess.WHITE:
                                    white_shield += 1
                    else:
                        for dr in (1, 2):
                            r = krank - dr
                            if 0 <= r <= 7:
                                s = r * 8 + f
                                p = board.piece_at(s)
                                if p and p.piece_type == chess.PAWN and p.color == chess.BLACK:
                                    black_shield += 1
        return float(white_shield - black_shield)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Open and semi-open file rook presence: (white_score - black_score) where open file rook=1.0, semi-open=0.5'
    try:
        pieces = board.piece_map()
        # precompute pawns per file
        pawns_on_file = {f: {'w': 0, 'b': 0} for f in range(8)}
        for sq, p in pieces.items():
            if p.piece_type == chess.PAWN:
                pawns_on_file[chess.square_file(sq)]['w' if p.color == chess.WHITE else 'b'] += 1
        def rook_score_for_color(color):
            score = 0.0
            for sq, p in pieces.items():
                if p.piece_type == chess.ROOK and p.color == color:
                    f = chess.square_file(sq)
                    total_pawns = pawns_on_file[f]['w'] + pawns_on_file[f]['b']
                    friendly_pawns = pawns_on_file[f]['w'] if color == chess.WHITE else pawns_on_file[f]['b']
                    if total_pawns == 0:
                        score += 1.0
                    elif friendly_pawns == 0:
                        score += 0.5
            return score
        return float(rook_score_for_color(chess.WHITE) - rook_score_for_color(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Sum value of attacked-but-undefended pieces (white - black) in centipawns (pawn=100, knight=320, bishop=330, rook=500, queen=900)'
    try:
        values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        wm = 0
        bm = 0
        pieces = board.piece_map()
        for sq, p in pieces.items():
            attackers = board.attackers(not p.color, sq)
            defenders = board.attackers(p.color, sq)
            if attackers and len(defenders) == 0:
                v = values.get(p.piece_type, 0)
                if p.color == chess.WHITE:
                    wm += v
                else:
                    bm += v
        return float(wm - bm)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Knight outpost score difference: number of knights on outpost squares (no enemy pawn can attack) weighted by 300 (white - black)'
    try:
        pieces = board.piece_map()
        white_out = 0
        black_out = 0
        for sq, p in pieces.items():
            if p.piece_type != chess.KNIGHT:
                continue
            # define outpost as being on ranks 4-6 (1-based) -> ranks index 3..5 and not attacked by enemy pawns
            r = chess.square_rank(sq)
            if 3 <= r <= 5:
                enemy = chess.BLACK if p.color == chess.WHITE else chess.WHITE
                attackers = board.attackers(enemy, sq)
                pawn_attacker_exists = False
                for a in attackers:
                    pa = board.piece_at(a)
                    if pa and pa.piece_type == chess.PAWN:
                        pawn_attacker_exists = True
                        break
                if not pawn_attacker_exists:
                    if p.color == chess.WHITE:
                        white_out += 1
                    else:
                        black_out += 1
        return float((white_out - black_out) * 300)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Minor-piece mobility difference: average legal moves per knight/bishop for white minus black (returns raw difference, 0 if no pieces)'
    try:
        # count legal moves originating from knights and bishops for each color
        white_moves = 0
        black_moves = 0
        white_pieces = 0
        black_pieces = 0
        for mv in board.legal_moves:
            p = board.piece_at(mv.from_square)
            if not p:
                continue
            if p.piece_type in (chess.KNIGHT, chess.BISHOP):
                if p.color == chess.WHITE:
                    white_moves += 1
                else:
                    black_moves += 1
        # count pieces
        for sq, p in board.piece_map().items():
            if p.piece_type in (chess.KNIGHT, chess.BISHOP):
                if p.color == chess.WHITE:
                    white_pieces += 1
                else:
                    black_pieces += 1
        wm = white_moves / (white_pieces if white_pieces > 0 else 1)
        bm = black_moves / (black_pieces if black_pieces > 0 else 1)
        return float(wm - bm)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King centrality: (black_king_distance - white_king_distance) Manhattan distance to center (d4,e4,d5,e5); positive favors White being more central'
    try:
        center_sqs = [chess.parse_square('d4'), chess.parse_square('e4'), chess.parse_square('d5'), chess.parse_square('e5')]
        def min_center_distance(color):
            min_d = 100.0
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == color:
                    for c in center_sqs:
                        d = chess.square_distance(sq, c)
                        if d < min_d:
                            min_d = d
                    return float(min_d)
            return 100.0
        wk = min_center_distance(chess.WHITE)
        bk = min_center_distance(chess.BLACK)
        # smaller distance is better; return positive if white is closer: black - white
        return float(bk - wk)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn structure weakness score difference: isolated pawns *50 + doubled pawns *30 (white - black)'
    try:
        pawns = {chess.WHITE: {}, chess.BLACK: {}}
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                pawns[p.color].setdefault(f, []).append(sq)
        def score_for(color):
            sc = 0
            files_with_pawns = set(pawns[color].keys())
            # isolated: no friendly pawn on adjacent files
            for f, lst in pawns[color].items():
                isolated = True
                if (f - 1) in files_with_pawns or (f + 1) in files_with_pawns:
                    isolated = False
                if isolated:
                    sc += 50 * len(lst)
                # doubled: extra pawns on same file count as weaknesses
                if len(lst) > 1:
                    sc += 30 * (len(lst) - 1)
            return sc
        return float(score_for(chess.WHITE) - score_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rooks on opponent seventh (white rooks on rank 7 and black rooks on rank 2) difference weighted by 400 (white - black)'
    try:
        wcount = 0
        bcount = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                r = chess.square_rank(sq)
                if p.color == chess.WHITE and r == 6:
                    wcount += 1
                if p.color == chess.BLACK and r == 1:
                    bcount += 1
        return float((wcount - bcount) * 400)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pinned pieces total value difference: sum of values of pieces pinned to their king (white - black) in centipawns'
    try:
        values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        pieces = board.piece_map()
        pinned_white = 0
        pinned_black = 0
        for color in (chess.WHITE, chess.BLACK):
            # find king square
            king_sq = None
            for sq, p in pieces.items():
                if p.piece_type == chess.KING and p.color == color:
                    king_sq = sq
                    break
            if king_sq is None:
                continue
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            # scan enemy sliders
            enemy = not color
            for sq, p in pieces.items():
                if p.color != enemy:
                    continue
                if p.piece_type not in (chess.ROOK, chess.BISHOP, chess.QUEEN):
                    continue
                af = chess.square_file(sq)
                ar = chess.square_rank(sq)
                df = af - kf
                dr = ar - kr
                step_f = 0 if df == 0 else (1 if df > 0 else -1)
                step_r = 0 if dr == 0 else (1 if dr > 0 else -1)
                # aligned if same file, same rank, or same diagonal
                if not (df == 0 or dr == 0 or abs(df) == abs(dr)):
                    continue
                # step along from king to attacker, counting pieces in between
                cur_f = kf + step_f
                cur_r = kr + step_r
                between = []
                blocked = False
                while (cur_f != af) or (cur_r != ar):
                    if not (0 <= cur_f <= 7 and 0 <= cur_r <= 7):
                        blocked = True
                        break
                    s = cur_r * 8 + cur_f
                    if s in pieces:
                        between.append((s, pieces[s]))
                    cur_f += step_f
                    cur_r += step_r
                if blocked:
                    continue
                # exactly one piece between king and attacker => that piece is pinned (if it's friendly)
                if len(between) == 1:
                    between_sq, between_piece = between[0]
                    if between_piece.color == color:
                        v = values.get(between_piece.piece_type, 0)
                        if color == chess.WHITE:
                            pinned_white += v
                        else:
                            pinned_black += v
        return float(pinned_white - pinned_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Immediate capture opportunities difference: sum of opponent piece values that are attacked by more friendly attackers than defenders (white - black) in centipawns'
    try:
        values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        pieces = board.piece_map()
        white_ops = 0
        black_ops = 0
        for sq, p in pieces.items():
            attackers_white = board.attackers(chess.WHITE, sq)
            attackers_black = board.attackers(chess.BLACK, sq)
            if p.color == chess.BLACK:
                # white attacking black piece
                if len(attackers_white) > len(attackers_black):
                    white_ops += values.get(p.piece_type, 0)
            else:
                if len(attackers_black) > len(attackers_white):
                    black_ops += values.get(p.piece_type, 0)
        return float(white_ops - black_ops)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Weighted density of opponent attackers near each king: sum of attackers*piece_value within manhattan radius 2 around king (white - black), returned in pawns (divide by 100)'
    piece_value = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    def king_attack_density(color):
        # find king
        king_sq = None
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING and p.color == color:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        total = 0.0
        opp = not color
        kr = chess.square_rank(king_sq)
        kf = chess.square_file(king_sq)
        for r in range(max(0, kr-2), min(7, kr+2)+1):
            for f in range(max(0, kf-2), min(7, kf+2)+1):
                sq = chess.square(f, r)
                attackers = board.attackers(opp, sq)
                if attackers:
                    # weight by piece type of each attacker (sum)
                    for a in attackers:
                        ap = board.piece_at(a)
                        if ap is not None:
                            total += piece_value.get(ap.piece_type, 0)
        return total
    w = king_attack_density(chess.WHITE)
    b = king_attack_density(chess.BLACK)
    return float((w - b) / 100.0)

def feature(board: chess.Board) -> float:
    'Pawn-shield score for kings: counts friendly pawns on the three-file shield in the 1-2 ranks in front of each king (white - black)'
    def shield_for(color):
        # find king
        king_sq = None
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING and p.color == color:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        kr = chess.square_rank(king_sq)
        kf = chess.square_file(king_sq)
        total = 0
        if color == chess.WHITE:
            ranks = [kr+1, kr+2]
        else:
            ranks = [kr-1, kr-2]
        for rf in ranks:
            if rf < 0 or rf > 7:
                continue
            for ff in range(max(0, kf-1), min(7, kf+1)+1):
                sq = chess.square(ff, rf)
                p = board.piece_at(sq)
                if p is not None and p.piece_type == chess.PAWN and p.color == color:
                    total += 1
        return total
    return float(shield_for(chess.WHITE) - shield_for(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Count of loose high-value pieces (non-pawn, non-king) that are undefended but attacked (white - black)'
    def loose_count(color):
        cnt = 0
        for sq, p in board.piece_map().items():
            if p.color != color:
                continue
            if p.piece_type in (chess.PAWN, chess.KING):
                continue
            defenders = board.attackers(color, sq)
            attackers = board.attackers(not color, sq)
            if len(defenders) == 0 and len(attackers) > 0:
                cnt += 1
        return cnt
    return float(loose_count(chess.WHITE) - loose_count(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Number of rooks on completely open files (no pawns of either color on the file) (white - black)'
    def rook_open_files(color):
        cnt = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK and p.color == color:
                f = chess.square_file(sq)
                has_pawn = False
                for r in range(8):
                    s = chess.square(f, r)
                    pp = board.piece_at(s)
                    if pp is not None and pp.piece_type == chess.PAWN:
                        has_pawn = True
                        break
                if not has_pawn:
                    cnt += 1
        return cnt
    return float(rook_open_files(chess.WHITE) - rook_open_files(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Centralization score: sum over non-pawn pieces of (max(0,4 - min_distance_to_center)) (white - black); promotes pieces nearer to center'
    center_sqs = [chess.parse_square(s) for s in ('d4','e4','d5','e5')]
    def central_score(color):
        score = 0.0
        for sq, p in board.piece_map().items():
            if p.color != color:
                continue
            if p.piece_type == chess.PAWN:
                continue
            # min manhattan distance to center squares
            md = min(chess.square_distance(sq, cs) for cs in center_sqs)
            add = max(0.0, 4.0 - float(md))
            score += add
        return score
    return float(central_score(chess.WHITE) - central_score(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Count of direct linear attacks on the enemy king by sliding pieces (rook/queen on file/rank or bishop/queen on diagonal) with a clear ray (white - black)'
    def aligned_attacks(color):
        total = 0
        # find enemy king
        enemy = not color
        king_sq = None
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING and p.color == enemy:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        kf = chess.square_file(king_sq)
        kr = chess.square_rank(king_sq)
        for sq, p in board.piece_map().items():
            if p.color != color:
                continue
            if p.piece_type not in (chess.ROOK, chess.BISHOP, chess.QUEEN):
                continue
            pf = chess.square_file(sq); pr = chess.square_rank(sq)
            df = kf - pf; dr = kr - pr
            step_f = 0 if df == 0 else (1 if df > 0 else -1)
            step_r = 0 if dr == 0 else (1 if dr > 0 else -1)
            # check alignment type
            if p.piece_type == chess.ROOK and not (df == 0 or dr == 0):
                continue
            if p.piece_type == chess.BISHOP and abs(df) != abs(dr):
                continue
            if p.piece_type == chess.QUEEN and not (df == 0 or dr == 0 or abs(df) == abs(dr)):
                continue
            # step from piece toward king and ensure no blocking pieces until king
            cur_f, cur_r = pf + step_f, pr + step_r
            blocked = False
            while (cur_f, cur_r) != (kf, kr):
                if cur_f < 0 or cur_f > 7 or cur_r < 0 or cur_r > 7:
                    blocked = True
                    break
                s = chess.square(cur_f, cur_r)
                if board.piece_at(s) is not None:
                    blocked = True
                    break
                cur_f += step_f; cur_r += step_r
            if not blocked:
                total += 1
        return total
    return float(aligned_attacks(chess.WHITE) - aligned_attacks(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Number of passed pawns that are immediately blocked by an enemy piece directly in front of them (white - black)'
    def is_passed(sq, color):
        # crude passed pawn detection: no enemy pawn on same file or adjacent files ahead of pawn
        f = chess.square_file(sq); r = chess.square_rank(sq)
        enemy = not color
        if color == chess.WHITE:
            for rr in range(r+1, 8):
                for ff in range(max(0, f-1), min(7, f+1)+1):
                    p = board.piece_at(chess.square(ff, rr))
                    if p is not None and p.piece_type == chess.PAWN and p.color == enemy:
                        return False
            return True
        else:
            for rr in range(r-1, -1, -1):
                for ff in range(max(0, f-1), min(7, f+1)+1):
                    p = board.piece_at(chess.square(ff, rr))
                    if p is not None and p.piece_type == chess.PAWN and p.color == enemy:
                        return False
            return True
    def blocked_passed(color):
        cnt = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN and p.color == color:
                if not is_passed(sq, color):
                    continue
                f = chess.square_file(sq); r = chess.square_rank(sq)
                if color == chess.WHITE:
                    ahead_r = r + 1
                else:
                    ahead_r = r - 1
                if ahead_r < 0 or ahead_r > 7:
                    continue
                ahead_sq = chess.square(f, ahead_r)
                ap = board.piece_at(ahead_sq)
                if ap is not None and ap.color != color:
                    cnt += 1
        return cnt
    return float(blocked_passed(chess.WHITE) - blocked_passed(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Count of legal king escape squares available (adjacent squares not occupied by friendly piece and not attacked by opponent) (white - black)'
    def king_escape_count(color):
        king_sq = None
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING and p.color == color:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        kr = chess.square_rank(king_sq); kf = chess.square_file(king_sq)
        opp = not color
        cnt = 0
        for dr in (-1,0,1):
            for df in (-1,0,1):
                if dr == 0 and df == 0:
                    continue
                rr = kr + dr; ff = kf + df
                if rr < 0 or rr > 7 or ff < 0 or ff > 7:
                    continue
                sq = chess.square(ff, rr)
                occ = board.piece_at(sq)
                if occ is not None and occ.color == color:
                    continue
                # if square is attacked by opponent, it's unsafe
                if board.is_attacked_by(opp, sq):
                    continue
                cnt += 1
        return float(cnt)
    return float(king_escape_count(chess.WHITE) - king_escape_count(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Detect if a side has two bishops on the same color squares (penalizes lack of complementary bishops): returns (white_same_color_bishop_pair - black_same_color_bishop_pair)'
    def same_color_bishop_pair(color):
        bishops = []
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.BISHOP and p.color == color:
                bishops.append(sq)
        if len(bishops) < 2:
            return 0.0
        # check if any pair are on same-colored squares
        for i in range(len(bishops)):
            for j in range(i+1, len(bishops)):
                s1 = bishops[i]; s2 = bishops[j]
                c1 = (chess.square_file(s1) + chess.square_rank(s1)) & 1
                c2 = (chess.square_file(s2) + chess.square_rank(s2)) & 1
                if c1 == c2:
                    return 1.0
        return 0.0
    return float(same_color_bishop_pair(chess.WHITE) - same_color_bishop_pair(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Tactical overload score: sum over opponent pieces of max(0, (num_attackers - num_defenders)) * piece_value, aggregated (white attacking black - black attacking white), returned in pawns'
    piece_value = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    def overload_for(attacker_color):
        total = 0.0
        defender = not attacker_color
        for sq, p in board.piece_map().items():
            if p.color != defender:
                continue
            attackers = board.attackers(attacker_color, sq)
            defenders = board.attackers(defender, sq)
            adv = len(attackers) - len(defenders)
            if adv > 0:
                total += adv * piece_value.get(p.piece_type, 0)
        return total
    w = overload_for(chess.WHITE)
    b = overload_for(chess.BLACK)
    return float((w - b) / 100.0)

def feature(board: chess.Board) -> float:
    'Difference in pawn-island count (white pawn islands - black pawn islands); fewer islands = healthier pawn structure'
    try:
        wm = [False] * 8
        bm = [False] * 8
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if p.color == chess.WHITE:
                    wm[f] = True
                else:
                    bm[f] = True
        def islands(arr):
            count = 0
            i = 0
            while i < 8:
                if arr[i]:
                    count += 1
                    while i < 8 and arr[i]:
                        i += 1
                else:
                    i += 1
            return count
        return float(islands(wm) - islands(bm))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Average king-proximity advantage for passed pawns: (enemy-king-distance - own-king-distance) averaged over passed pawns (positive favors the pawn owner)'
    try:
        pm = board.piece_map()
        # find kings
        wk = bk = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    wk = sq
                else:
                    bk = sq
        def is_passed(sq, color):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if color == chess.WHITE:
                # no black pawn on same or adjacent files with rank > r
                for of in range(max(0, f - 1), min(7, f + 1) + 1):
                    for orr in range(r + 1, 8):
                        s2 = orr * 8 + of
                        p2 = pm.get(s2)
                        if p2 is not None and p2.piece_type == chess.PAWN and p2.color == chess.BLACK:
                            return False
                return True
            else:
                for of in range(max(0, f - 1), min(7, f + 1) + 1):
                    for orr in range(0, r):
                        s2 = orr * 8 + of
                        p2 = pm.get(s2)
                        if p2 is not None and p2.piece_type == chess.PAWN and p2.color == chess.WHITE:
                            return False
                return True
        white_vals = []
        black_vals = []
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                if is_passed(sq, p.color):
                    if p.color == chess.WHITE and wk is not None and bk is not None:
                        d_own = chess.square_distance(sq, wk)
                        d_enemy = chess.square_distance(sq, bk)
                        white_vals.append(float(d_enemy - d_own) / 8.0)
                    if p.color == chess.BLACK and wk is not None and bk is not None:
                        d_own = chess.square_distance(sq, bk)
                        d_enemy = chess.square_distance(sq, wk)
                        black_vals.append(float(d_enemy - d_own) / 8.0)
        white_avg = sum(white_vals) / max(1.0, len(white_vals))
        black_avg = sum(black_vals) / max(1.0, len(black_vals))
        return float(white_avg - black_avg)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in fraction of passed pawns that are blocked directly in front by any piece (white - black)'
    try:
        pm = board.piece_map()
        def is_passed_and_blocked(sq, color):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            # passed test
            if color == chess.WHITE:
                for of in range(max(0, f - 1), min(7, f + 1) + 1):
                    for orr in range(r + 1, 8):
                        s2 = orr * 8 + of
                        p2 = pm.get(s2)
                        if p2 is not None and p2.piece_type == chess.PAWN and p2.color == chess.BLACK:
                            return (False, False)
                # blocked?
                if r + 1 <= 7:
                    ahead = (r + 1) * 8 + f
                    return (True, pm.get(ahead) is not None)
                return (True, False)
            else:
                for of in range(max(0, f - 1), min(7, f + 1) + 1):
                    for orr in range(0, r):
                        s2 = orr * 8 + of
                        p2 = pm.get(s2)
                        if p2 is not None and p2.piece_type == chess.PAWN and p2.color == chess.WHITE:
                            return (False, False)
                if r - 1 >= 0:
                    ahead = (r - 1) * 8 + f
                    return (True, pm.get(ahead) is not None)
                return (True, False)
        w_passed = w_blocked = b_passed = b_blocked = 0
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                passed, blocked = is_passed_and_blocked(sq, p.color)
                if passed:
                    if p.color == chess.WHITE:
                        w_passed += 1
                        if blocked:
                            w_blocked += 1
                    else:
                        b_passed += 1
                        if blocked:
                            b_blocked += 1
        w_frac = (w_blocked / w_passed) if w_passed > 0 else 0.0
        b_frac = (b_blocked / b_passed) if b_passed > 0 else 0.0
        return float(w_frac - b_frac)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in total open-diagonal squares available to bishops (white - black), normalized roughly by maximum (~13)'
    try:
        pm = board.piece_map()
        dirs = ((1, 1), (1, -1), (-1, 1), (-1, -1))
        def bishop_reach(sq):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            total = 0
            for df, dr in dirs:
                cf, cr = f + df, r + dr
                while 0 <= cf < 8 and 0 <= cr < 8:
                    s2 = cr * 8 + cf
                    if pm.get(s2) is None:
                        total += 1
                        cf += df; cr += dr
                    else:
                        # can capture that piece (counts as 1) then stop
                        total += 1
                        break
            return total
        w_sum = b_sum = 0
        for sq, p in pm.items():
            if p.piece_type == chess.BISHOP:
                if p.color == chess.WHITE:
                    w_sum += bishop_reach(sq)
                else:
                    b_sum += bishop_reach(sq)
        # normalize by plausible max 13
        return float((w_sum - b_sum) / 13.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King proximity (normalized): (8 - Manhattan distance between kings)/8 signed by side to move (positive when side-to-move has closer king)'
    try:
        pm = board.piece_map()
        wk = bk = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    wk = sq
                else:
                    bk = sq
        if wk is None or bk is None:
            return 0.0
        dist = chess.square_distance(wk, bk)
        score = float((8.0 - float(dist)) / 8.0)
        return score if board.turn == chess.WHITE else -score
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of hanging non-king pieces (white hanging - black hanging): piece attacked by opponent and not defended'
    try:
        pm = board.piece_map()
        white_hang = 0
        black_hang = 0
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                continue
            if p.color == chess.WHITE:
                attacked = board.is_attacked_by(chess.BLACK, sq)
                defended = board.is_attacked_by(chess.WHITE, sq)
                if attacked and not defended:
                    white_hang += 1
            else:
                attacked = board.is_attacked_by(chess.WHITE, sq)
                defended = board.is_attacked_by(chess.BLACK, sq)
                if attacked and not defended:
                    black_hang += 1
        return float(white_hang - black_hang)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in pawn advancement extremes: (max white pawn rank normalized) - (max black pawn advancement normalized)'
    try:
        pm = board.piece_map()
        w_max = -1
        b_min = 8
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                r = chess.square_rank(sq)
                if p.color == chess.WHITE:
                    if r > w_max:
                        w_max = r
                else:
                    if r < b_min:
                        b_min = r
        w_adv = float(w_max) / 7.0 if w_max >= 0 else 0.0
        b_adv = float(7 - b_min) / 7.0 if b_min <= 7 else 0.0
        return float(w_adv - b_adv)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net count of bishops that are currently attacking a square within two squares of the enemy king (white - black)'
    try:
        pm = board.piece_map()
        wk = bk = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    wk = sq
                else:
                    bk = sq
        if wk is None or bk is None:
            return 0.0
        w_count = 0
        b_count = 0
        for sq, p in pm.items():
            if p.piece_type != chess.BISHOP:
                continue
            # target squares within manhattan radius 2 of enemy king
            target_center = bk if p.color == chess.WHITE else wk
            tx = chess.square_file(target_center); ty = chess.square_rank(target_center)
            found = False
            for dx in range(-2, 3):
                for dy in range(-2, 3):
                    x = tx + dx; y = ty + dy
                    if 0 <= x < 8 and 0 <= y < 8:
                        tsq = y * 8 + x
                        # check if this bishop attacks that target square (board.attackers gives attackers)
                        attackers = board.attackers(p.color, tsq)
                        if sq in attackers:
                            found = True
                            break
                if found:
                    break
            if found:
                if p.color == chess.WHITE:
                    w_count += 1
                else:
                    b_count += 1
        return float(w_count - b_count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Central control difference: number of central squares (d4,e4,d5,e5) attacked by White minus Black, normalized to [-1,1]'
    try:
        centers = [chess.parse_square(s) for s in ('d4', 'e4', 'd5', 'e5')]
        w = sum(1 for s in centers if board.is_attacked_by(chess.WHITE, s))
        b = sum(1 for s in centers if board.is_attacked_by(chess.BLACK, s))
        return float((w - b) / 4.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of passed pawns that are currently attacked by an allied bishop (supporting bishops): white - black'
    try:
        pm = board.piece_map()
        def is_passed(sq, color):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if color == chess.WHITE:
                for of in range(max(0, f - 1), min(7, f + 1) + 1):
                    for orr in range(r + 1, 8):
                        s2 = orr * 8 + of
                        p2 = pm.get(s2)
                        if p2 is not None and p2.piece_type == chess.PAWN and p2.color == chess.BLACK:
                            return False
                return True
            else:
                for of in range(max(0, f - 1), min(7, f + 1) + 1):
                    for orr in range(0, r):
                        s2 = orr * 8 + of
                        p2 = pm.get(s2)
                        if p2 is not None and p2.piece_type == chess.PAWN and p2.color == chess.WHITE:
                            return False
                return True
        w_supported = 0
        b_supported = 0
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN and is_passed(sq, p.color):
                # check if any allied bishop attacks this pawn square
                if p.color == chess.WHITE:
                    if any((s in board.attackers(chess.WHITE, sq)) for s, pp in pm.items() if pp.piece_type == chess.BISHOP and pp.color == chess.WHITE):
                        w_supported += 1
                else:
                    if any((s in board.attackers(chess.BLACK, sq)) for s, pp in pm.items() if pp.piece_type == chess.BISHOP and pp.color == chess.BLACK):
                        b_supported += 1
        return float(w_supported - b_supported)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Sum of opponent pieces that are hanging (attacked and undefended) measured in pawn-equivalents (positive = white advantage)'
    weights = {chess.PAWN:1.0, chess.KNIGHT:3.2, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    wm_hang = 0.0
    bm_hang = 0.0
    try:
        for sq, piece in board.piece_map().items():
            # piece is at sq belonging to piece.color
            attackers = board.attackers(not piece.color, sq)
            defenders = board.attackers(piece.color, sq)
            if attackers and not defenders:
                val = weights.get(piece.piece_type, 0.0)
                if piece.color == chess.WHITE:
                    wm_hang += val
                else:
                    bm_hang += val
    except Exception:
        return 0.0
    # positive if Black has more hanging material (good for White)
    return float(bm_hang - wm_hang)

def feature(board: chess.Board) -> float:
    'Signed proximity of the best passed pawn to promotion: (White best closeness) - (Black best closeness) in [ -1 .. 1 ]'
    def is_passed(bd, sq, color):
        file = chess.square_file(sq)
        rank = chess.square_rank(sq)
        if color == chess.WHITE:
            # no black pawn on same file or adjacent files in front of the pawn
            for f in range(max(0, file-1), min(7, file+1)+1):
                for r in range(rank+1, 8):
                    s = chess.square(f, r)
                    p = bd.piece_at(s)
                    if p and p.piece_type == chess.PAWN and p.color == chess.BLACK:
                        return False
            return True
        else:
            for f in range(max(0, file-1), min(7, file+1)+1):
                for r in range(0, rank):
                    s = chess.square(f, r)
                    p = bd.piece_at(s)
                    if p and p.piece_type == chess.PAWN and p.color == chess.WHITE:
                        return False
            return True
    best_white = -1.0
    best_black = -1.0
    try:
        for sq, piece in board.piece_map().items():
            if piece.piece_type != chess.PAWN:
                continue
            rank = chess.square_rank(sq)
            if piece.color == chess.WHITE and is_passed(board, sq, chess.WHITE):
                # closeness: 1.0 means on 7th rank (one step to promote), 0.0 means on 2nd rank or behind
                closeness = (rank) / 7.0
                best_white = max(best_white, closeness)
            if piece.color == chess.BLACK and is_passed(board, sq, chess.BLACK):
                # for black, rank 6 is one away from promotion (rank index 1), closeness invert
                closeness = (7 - rank) / 7.0
                best_black = max(best_black, closeness)
    except Exception:
        return 0.0
    if best_white < 0 and best_black < 0:
        return 0.0
    return float(max(0.0, best_white) - max(0.0, best_black))

def feature(board: chess.Board) -> float:
    'Difference in king-zone attack pressure: (attacks on black king neighborhood) - (attacks on white king neighborhood); positive = white advantage'
    def king_zone_attacks(bd, king_color):
        # find king square
        ksq = None
        for sq, p in bd.piece_map().items():
            if p.piece_type == chess.KING and p.color == king_color:
                ksq = sq
                break
        if ksq is None:
            return 0
        # king neighborhood = king square + adjacent squares (8-neighborhood)
        neigh = {ksq}
        kf = chess.square_file(ksq)
        kr = chess.square_rank(ksq)
        for df in (-1,0,1):
            for dr in (-1,0,1):
                f = kf + df
                r = kr + dr
                if 0 <= f <= 7 and 0 <= r <= 7:
                    neigh.add(chess.square(f, r))
        # count attacks by opposite color into this neighborhood
        opp = not king_color
        cnt = 0
        for s in neigh:
            try:
                if bd.is_attacked_by(opp, s):
                    # count how many attackers (gives magnitude)
                    cnt += len(bd.attackers(opp, s))
            except Exception:
                continue
        return cnt
    try:
        black_pressure = king_zone_attacks(board, chess.BLACK)
        white_pressure = king_zone_attacks(board, chess.WHITE)
    except Exception:
        return 0.0
    # positive if White attacks black king zone more than vice versa
    return float(black_pressure - white_pressure)

def feature(board: chess.Board) -> float:
    'Central minor piece presence difference: (# of white knights/bishops on central 4x4) - (same for black)'
    central_files = set(range(2, 6))  # c,d,e,f
    central_ranks = set(range(2, 6))  # 3,4,5,6 (0-indexed)
    wcnt = 0
    bcnt = 0
    try:
        for sq, piece in board.piece_map().items():
            if piece.piece_type in (chess.KNIGHT, chess.BISHOP):
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                if f in central_files and r in central_ranks:
                    if piece.color == chess.WHITE:
                        wcnt += 1
                    else:
                        bcnt += 1
    except Exception:
        return 0.0
    return float(wcnt - bcnt)

def feature(board: chess.Board) -> float:
    'Difference in number of legal moves that give check (White checks available - Black checks available); tests moves by temporarily switching turn'
    def checks_for_color(bd, color):
        cnt = 0
        try:
            bb = bd.copy(stack=False)
            bb.turn = color
            for mv in list(bb.legal_moves):
                try:
                    bb.push(mv)
                    if bb.is_check():
                        cnt += 1
                    bb.pop()
                except Exception:
                    # if move illegal or push/pop issue, skip
                    try:
                        # ensure pop if push succeeded unexpectedly
                        bb.pop()
                    except Exception:
                        pass
            return cnt
        except Exception:
            return 0
    try:
        w_checks = checks_for_color(board, chess.WHITE)
        b_checks = checks_for_color(board, chess.BLACK)
    except Exception:
        return 0.0
    return float(w_checks - b_checks)

def feature(board: chess.Board) -> float:
    'Difference in number of isolated pawns (no friendly pawn on adjacent files): white isolated pawns - black isolated pawns'
    def isolated_for_color(bd, color):
        files_with_pawns = {f:0 for f in range(8)}
        for sq, p in bd.piece_map().items():
            if p.piece_type == chess.PAWN and p.color == color:
                files_with_pawns[chess.square_file(sq)] += 1
        cnt = 0
        for sq, p in bd.piece_map().items():
            if p.piece_type == chess.PAWN and p.color == color:
                f = chess.square_file(sq)
                if files_with_pawns.get(f-1,0) == 0 and files_with_pawns.get(f+1,0) == 0:
                    cnt += 1
        return cnt
    try:
        w_iso = isolated_for_color(board, chess.WHITE)
        b_iso = isolated_for_color(board, chess.BLACK)
    except Exception:
        return 0.0
    return float(w_iso - b_iso)

def feature(board: chess.Board) -> float:
    'Difference in number of rooks/queens occupying open files (no pawns on that file): white - black'
    def heavy_on_open_files(bd, color):
        pawn_files = set()
        for sq, p in bd.piece_map().items():
            if p.piece_type == chess.PAWN:
                pawn_files.add(chess.square_file(sq))
        cnt = 0
        for sq, p in bd.piece_map().items():
            if p.color == color and p.piece_type in (chess.ROOK, chess.QUEEN):
                if chess.square_file(sq) not in pawn_files:
                    cnt += 1
        return cnt
    try:
        w = heavy_on_open_files(board, chess.WHITE)
        b = heavy_on_open_files(board, chess.BLACK)
    except Exception:
        return 0.0
    return float(w - b)

def feature(board: chess.Board) -> float:
    'Number of knight outposts difference (knight not attacked by any enemy pawn and supported by a friendly pawn behind it): white - black'
    def is_supported_by_pawn(bd, sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            behind_r = r - 1
        else:
            behind_r = r + 1
        if 0 <= behind_r <= 7:
            s = chess.square(f, behind_r)
            p = bd.piece_at(s)
            return p is not None and p.piece_type == chess.PAWN and p.color == color
        return False
    def outposts_for_color(bd, color):
        cnt = 0
        for sq, p in bd.piece_map().items():
            if p.piece_type == chess.KNIGHT and p.color == color:
                # not attacked by enemy pawns
                attacked_by_enemy_pawns = False
                try:
                    pawn_attackers = bd.attackers(not color, sq)
                    for a in pawn_attackers:
                        ap = bd.piece_at(a)
                        if ap and ap.piece_type == chess.PAWN:
                            attacked_by_enemy_pawns = True
                            break
                except Exception:
                    attacked_by_enemy_pawns = True
                if attacked_by_enemy_pawns:
                    continue
                if not is_supported_by_pawn(bd, sq, color):
                    continue
                # prefer more advanced ranks (for white ranks >=3, for black ranks <=4)
                r = chess.square_rank(sq)
                if (color == chess.WHITE and r >= 3) or (color == chess.BLACK and r <= 4):
                    cnt += 1
        return cnt
    try:
        w = outposts_for_color(board, chess.WHITE)
        b = outposts_for_color(board, chess.BLACK)
    except Exception:
        return 0.0
    return float(w - b)

def feature(board: chess.Board) -> float:
    'Sum of material value of opponent pieces that are attacked by more attackers than defenders (tactical targets), difference white - black'
    weights = {chess.PAWN:1.0, chess.KNIGHT:3.2, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    w_targets = 0.0
    b_targets = 0.0
    try:
        for sq, piece in board.piece_map().items():
            attackers = board.attackers(not piece.color, sq)
            defenders = board.attackers(piece.color, sq)
            # count numeric attackers/defenders
            na = len(attackers) if attackers is not None else 0
            nd = len(defenders) if defenders is not None else 0
            if na > nd:
                val = weights.get(piece.piece_type, 0.0)
                if piece.color == chess.BLACK:
                    # black piece is target for white
                    w_targets += val
                else:
                    b_targets += val
    except Exception:
        return 0.0
    return float(w_targets - b_targets)

def feature(board: chess.Board) -> float:
    'Fork threat value difference: sum of opponent piece values that are attacked by at least two of our pieces (white - black)'
    weights = {chess.PAWN:1.0, chess.KNIGHT:3.2, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    w_fork = 0.0
    b_fork = 0.0
    try:
        for sq, piece in board.piece_map().items():
            # attackers by opposite color
            attackers = board.attackers(not piece.color, sq)
            na = len(attackers) if attackers is not None else 0
            if na >= 2:
                val = weights.get(piece.piece_type, 0.0)
                if piece.color == chess.BLACK:
                    w_fork += val
                else:
                    b_fork += val
    except Exception:
        return 0.0
    return float(w_fork - b_fork)

def feature(board: chess.Board) -> float:
    'Difference in pawn shield size in front of each king (White - Black), normalized'
    piece_map = board.piece_map()
    vals = {chess.PAWN: 1}
    def king_shield(king_sq, color):
        if king_sq is None:
            return 0
        f = chess.square_file(king_sq)
        r = chess.square_rank(king_sq)
        shield_count = 0
        # forward direction for pawns of that color
        dr = 1 if color == chess.WHITE else -1
        # check up to two ranks in front and three-file span (file-1,file,file+1)
        for step in (1, 2):
            rr = r + dr * step
            if 0 <= rr <= 7:
                for df in (-1, 0, 1):
                    ff = f + df
                    if 0 <= ff <= 7:
                        sq = chess.square(ff, rr)
                        p = board.piece_at(sq)
                        if p is not None and p.piece_type == chess.PAWN and p.color == color:
                            shield_count += 1
        return float(shield_count)
    # find kings
    wking = None
    bking = None
    for sq, p in piece_map.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                wking = sq
            else:
                bking = sq
    w_shield = king_shield(wking, chess.WHITE)
    b_shield = king_shield(bking, chess.BLACK)
    # normalize by maximum possible (6)
    return (w_shield - b_shield) / 6.0

def feature(board: chess.Board) -> float:
    'Weighted attackers on each king: sum(piece_value of attackers) attacking enemy king (White - Black) in pawn units'
    pv = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    piece_map = board.piece_map()
    wking = bking = None
    for sq, p in piece_map.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                wking = sq
            else:
                bking = sq
    def attackers_value(target_sq, attacker_color):
        if target_sq is None:
            return 0.0
        atks = board.attackers(attacker_color, target_sq)
        s = 0
        for a in atks:
            p = board.piece_at(a)
            if p is not None:
                s += pv.get(p.piece_type, 0)
        return float(s)
    white_attacks_black = attackers_value(bking, chess.WHITE)
    black_attacks_white = attackers_value(wking, chess.BLACK)
    # return in pawn units (divide by 100)
    return (white_attacks_black - black_attacks_white) / 100.0

def feature(board: chess.Board) -> float:
    'Count of heavy-piece (rook/queen) unobstructed file attacks on enemy king (weighted, White - Black)'
    piece_map = board.piece_map()
    def side_score(attacker_color, target_king_sq):
        if target_king_sq is None:
            return 0.0
        score = 0.0
        target_file = chess.square_file(target_king_sq)
        for sq, p in piece_map.items():
            if p.color == attacker_color and (p.piece_type == chess.ROOK or p.piece_type == chess.QUEEN):
                if chess.square_file(sq) == target_file:
                    # check squares between sq and target_king_sq for any pawn blocking
                    f = target_file
                    r1 = chess.square_rank(sq)
                    r2 = chess.square_rank(target_king_sq)
                    step = 1 if r2 > r1 else -1
                    blocked = False
                    rr = r1 + step
                    while rr != r2:
                        inter = chess.square(f, rr)
                        inter_p = board.piece_at(inter)
                        if inter_p is not None and inter_p.piece_type == chess.PAWN:
                            blocked = True
                            break
                        rr += step
                    if not blocked:
                        # weight rook=5, queen=9, return in pawn units
                        if p.piece_type == chess.ROOK:
                            score += 500
                        else:
                            score += 900
        return score
    # find kings
    wking = bking = None
    for sq, p in piece_map.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                wking = sq
            else:
                bking = sq
    white_score = side_score(chess.WHITE, bking)
    black_score = side_score(chess.BLACK, wking)
    return (white_score - black_score) / 100.0

def feature(board: chess.Board) -> float:
    'Queen tropism: inverse-distance of queen to enemy king (White - Black), 1/(1+dist)'
    piece_map = board.piece_map()
    wq = bq = wking = bking = None
    for sq, p in piece_map.items():
        if p.piece_type == chess.QUEEN:
            if p.color == chess.WHITE:
                wq = sq
            else:
                bq = sq
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                wking = sq
            else:
                bking = sq
    def q_tropism(q_sq, target_king_sq):
        if q_sq is None or target_king_sq is None:
            return 0.0
        d = chess.square_distance(q_sq, target_king_sq)
        # higher when closer
        return 1.0 / (1.0 + d)
    return q_tropism(wq, bking) - q_tropism(bq, wking)

def feature(board: chess.Board) -> float:
    'Sum of values of undefended pieces that are attacked (hanging pieces) (White - Black) in pawn units'
    pv = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    score_w = 0
    score_b = 0
    for sq, p in board.piece_map().items():
        if p is None:
            continue
        attackers = board.attackers(not p.color, sq)
        defenders = board.attackers(p.color, sq)
        if len(attackers) > 0 and len(defenders) == 0:
            val = pv.get(p.piece_type, 0)
            if p.color == chess.WHITE:
                score_w += val
            else:
                score_b += val
    return (score_w - score_b) / 100.0

def feature(board: chess.Board) -> float:
    'Count of minor pieces (knights/bishops) on central outpost squares (d4,e4,d5,e5) supported by a pawn and not attacked by opponent pawns (White - Black)'
    outposts = {chess.parse_square(s) for s in ('d4','e4','d5','e5')}
    def pawn_supporters(square, color):
        # True if attacked by own pawn
        attackers = board.attackers(color, square)
        for a in attackers:
            p = board.piece_at(a)
            if p is not None and p.piece_type == chess.PAWN and p.color == color:
                return True
        return False
    def attacked_by_enemy_pawn(square, enemy_color):
        attackers = board.attackers(enemy_color, square)
        for a in attackers:
            p = board.piece_at(a)
            if p is not None and p.piece_type == chess.PAWN and p.color == enemy_color:
                return True
        return False
    score_w = 0
    score_b = 0
    for sq in outposts:
        p = board.piece_at(sq)
        if p is None:
            continue
        if p.piece_type in (chess.KNIGHT, chess.BISHOP):
            if pawn_supporters(sq, p.color) and not attacked_by_enemy_pawn(sq, not p.color):
                if p.color == chess.WHITE:
                    score_w += 1
                else:
                    score_b += 1
    return float(score_w - score_b)

def feature(board: chess.Board) -> float:
    'King tropism: sum over pieces of (piece_value / (1 + manhattan_distance_to_enemy_king)) (White - Black), normalized to pawns'
    pv = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    piece_map = board.piece_map()
    wking = bking = None
    for sq, p in piece_map.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                wking = sq
            else:
                bking = sq
    def side_tropism(attacker_color, enemy_king_sq):
        if enemy_king_sq is None:
            return 0.0
        s = 0.0
        for sq, p in piece_map.items():
            if p is None or p.color != attacker_color:
                continue
            # distance to enemy king
            d = chess.square_distance(sq, enemy_king_sq)
            s += pv.get(p.piece_type, 0) / (1.0 + d)
        return s
    w_score = side_tropism(chess.WHITE, bking)
    b_score = side_tropism(chess.BLACK, wking)
    return (w_score - b_score) / 100.0

def feature(board: chess.Board) -> float:
    'Difference in pawn island count (White - Black): number of contiguous file-groups that have pawns'
    def pawn_islands(color):
        files_with_pawn = [False]*8
        for sq, p in board.piece_map().items():
            if p is not None and p.color == color and p.piece_type == chess.PAWN:
                files_with_pawn[chess.square_file(sq)] = True
        islands = 0
        i = 0
        while i < 8:
            if files_with_pawn[i]:
                islands += 1
                while i < 8 and files_with_pawn[i]:
                    i += 1
            else:
                i += 1
        return islands
    w_islands = pawn_islands(chess.WHITE)
    b_islands = pawn_islands(chess.BLACK)
    return float(w_islands - b_islands)

def feature(board: chess.Board) -> float:
    'Rook effectiveness: count of rooks on open files (1.0) and semi-open files (0.5) (White - Black)'
    def rook_score(color):
        score = 0.0
        # precompute pawns per file
        pawns_in_file = [0]*8
        pawns_of_file_color = [0]*8
        for sq, p in board.piece_map().items():
            if p is not None and p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                pawns_in_file[f] += 1
                if p.color == color:
                    pawns_of_file_color[f] += 1
        for sq, p in board.piece_map().items():
            if p is None or p.color != color or p.piece_type != chess.ROOK:
                continue
            f = chess.square_file(sq)
            if pawns_in_file[f] == 0:
                score += 1.0
            elif pawns_of_file_color[f] == 0:
                score += 0.5
        return score
    return rook_score(chess.WHITE) - rook_score(chess.BLACK)

def feature(board: chess.Board) -> float:
    'Fractional difference of non-king pieces that are under-defended (attacked more times than defended): White - Black'
    try:
        piece_map = board.piece_map()
        undefended_white = 0
        total_white = 0
        undefended_black = 0
        total_black = 0
        for sq, piece in piece_map.items():
            if piece.piece_type == chess.KING:
                continue
            if piece.color == chess.WHITE:
                total_white += 1
                attackers = len(board.attackers(chess.BLACK, sq))
                defenders = len(board.attackers(chess.WHITE, sq))
                if attackers > defenders:
                    undefended_white += 1
            else:
                total_black += 1
                attackers = len(board.attackers(chess.WHITE, sq))
                defenders = len(board.attackers(chess.BLACK, sq))
                if attackers > defenders:
                    undefended_black += 1
        # avoid division by zero
        frac_white = (undefended_white / total_white) if total_white > 0 else 0.0
        frac_black = (undefended_black / total_black) if total_black > 0 else 0.0
        return float(frac_white - frac_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net king attack pressure: weighted sum of attackers targeting squares adjacent to the opponent king (weights: Q=9,R=5,B/N=3,P=1). Returns White - Black pressure.'
    weights = {chess.PAWN: 1.0, chess.KNIGHT: 3.0, chess.BISHOP: 3.0, chess.ROOK: 5.0, chess.QUEEN: 9.0, chess.KING: 0.0}
    try:
        pm = board.piece_map()
        def pressure_on_king(king_color):
            # which side is attacking the king
            if king_color == chess.WHITE:
                attacker = chess.BLACK
            else:
                attacker = chess.WHITE
            # find king square
            king_sq = None
            for sq, p in pm.items():
                if p.piece_type == chess.KING and p.color == king_color:
                    king_sq = sq
                    break
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
            total = 0.0
            # include king square and adjacent squares
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    f = kf + df; r = kr + dr
                    if 0 <= f < 8 and 0 <= r < 8:
                        sq = r * 8 + f
                        for atk_sq in board.attackers(attacker, sq):
                            atk_piece = board.piece_at(atk_sq)
                            if atk_piece:
                                total += weights.get(atk_piece.piece_type, 0.0)
            return total
        white_on_black = pressure_on_king(chess.BLACK)
        black_on_white = pressure_on_king(chess.WHITE)
        return float(white_on_black - black_on_white)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of safe king escape squares: (number of adjacent squares the king could move to that are not attacked and not occupied by own piece) White - Black'
    try:
        pm = board.piece_map()
        def safe_escapes(king_color):
            king_sq = None
            for sq, p in pm.items():
                if p.piece_type == chess.KING and p.color == king_color:
                    king_sq = sq
                    break
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
            escapes = 0
            enemy = not king_color
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    f = kf + df; r = kr + dr
                    if 0 <= f < 8 and 0 <= r < 8:
                        sq = r * 8 + f
                        occ = board.piece_at(sq)
                        if occ is not None and occ.color == king_color:
                            continue
                        # if square is attacked by enemy, it's unsafe
                        if board.is_attacked_by(enemy, sq):
                            continue
                        escapes += 1
            return float(escapes)
        w = safe_escapes(chess.WHITE)
        b = safe_escapes(chess.BLACK)
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rook activity advantage: White rooks on opponent seventh + 0.5 per rook on open file minus same for Black. Returns White - Black.'
    try:
        pm = board.piece_map()
        def rook_score_for(color):
            score = 0.0
            for sq, p in pm.items():
                if p.piece_type == chess.ROOK and p.color == color:
                    f = chess.square_file(sq); r = chess.square_rank(sq)
                    # seventh rank for white is rank 6 (index), for black is rank 1
                    if color == chess.WHITE and r == 6:
                        score += 1.0
                    if color == chess.BLACK and r == 1:
                        score += 1.0
                    # open file: no pawns of either color on that file
                    pawn_on_file = False
                    for rr in range(8):
                        sqq = rr * 8 + f
                        piece = board.piece_at(sqq)
                        if piece and piece.piece_type == chess.PAWN:
                            pawn_on_file = True
                            break
                    if not pawn_on_file:
                        score += 0.5
            return score
        return float(rook_score_for(chess.WHITE) - rook_score_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn shield integrity around the king: for each side count friendly pawns in the three files ahead of the king on the first two ranks in front; returns White - Black (higher means better shield).'
    try:
        pm = board.piece_map()
        def shield_count(color):
            king_sq = None
            for sq, p in pm.items():
                if p.piece_type == chess.KING and p.color == color:
                    king_sq = sq
                    break
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
            count = 0
            # direction: for white pawns are increasing rank; for black decreasing
            dir = 1 if color == chess.WHITE else -1
            for df in (-1, 0, 1):
                for step in (1, 2):
                    f = kf + df
                    r = kr + dir * step
                    if 0 <= f < 8 and 0 <= r < 8:
                        sq = r * 8 + f
                        piece = board.piece_at(sq)
                        if piece and piece.piece_type == chess.PAWN and piece.color == color:
                            count += 1
            return float(count)
        return float(shield_count(chess.WHITE) - shield_count(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Capture potential imbalance: sum of enemy piece values that are tactically vulnerable (more attackers by the opponent than defenders). Values: pawn=1,knight=3,bishop=3,rook=5,queen=9. Returns White - Black.'
    vals = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    try:
        total_white_potential = 0.0
        total_black_potential = 0.0
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.KING:
                continue
            if piece.color == chess.BLACK:
                attackers = len(board.attackers(chess.WHITE, sq))
                defenders = len(board.attackers(chess.BLACK, sq))
                if attackers > defenders and attackers > 0:
                    total_white_potential += vals.get(piece.piece_type, 0.0)
            else:
                attackers = len(board.attackers(chess.BLACK, sq))
                defenders = len(board.attackers(chess.WHITE, sq))
                if attackers > defenders and attackers > 0:
                    total_black_potential += vals.get(piece.piece_type, 0.0)
        return float(total_white_potential - total_black_potential)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Bishop mobility difference (sum of reachable diagonal squares for bishops) White - Black. Approximates activity of bishops by sliding until blocked.'
    try:
        pm = board.piece_map()
        def bishop_mobility_for(color):
            total = 0
            for sq, p in pm.items():
                if p.piece_type == chess.BISHOP and p.color == color:
                    f = chess.square_file(sq); r = chess.square_rank(sq)
                    for df, dr in ((1,1),(1,-1),(-1,1),(-1,-1)):
                        cf, cr = f + df, r + dr
                        while 0 <= cf < 8 and 0 <= cr < 8:
                            s2 = cr * 8 + cf
                            total += 1
                            if board.piece_at(s2) is not None:
                                break
                            cf += df; cr += dr
            return float(total)
        return float(bishop_mobility_for(chess.WHITE) - bishop_mobility_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King tropism: sum over pieces of (piece_value / (manhattan distance to enemy king + 1)). Returns White - Black to indicate which side has more force aimed at opponent king.'
    vals = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    try:
        pm = board.piece_map()
        white_king_sq = None
        black_king_sq = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king_sq = sq
                else:
                    black_king_sq = sq
        wscore = 0.0
        bscore = 0.0
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                continue
            if p.color == chess.WHITE and black_king_sq is not None:
                d = chess.square_distance(sq, black_king_sq)
                wscore += vals.get(p.piece_type, 0.0) / (d + 1.0)
            if p.color == chess.BLACK and white_king_sq is not None:
                d = chess.square_distance(sq, white_king_sq)
                bscore += vals.get(p.piece_type, 0.0) / (d + 1.0)
        return float(wscore - bscore)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Back-rank attacking potential: number of heavy pieces (rook/queen) that are on the same rank as the enemy king with no pawns between attacker and king. Returns White - Black.'
    try:
        pm = board.piece_map()
        def backrank_for(color):
            # attackers are color; target is enemy king
            target_king_sq = None
            for sq, p in pm.items():
                if p.piece_type == chess.KING and p.color != color:
                    target_king_sq = sq
                    break
            if target_king_sq is None:
                return 0.0
            tr = chess.square_rank(target_king_sq); tf = chess.square_file(target_king_sq)
            count = 0.0
            for sq, p in pm.items():
                if p.color == color and (p.piece_type == chess.ROOK or p.piece_type == chess.QUEEN):
                    rf = chess.square_file(sq); rr = chess.square_rank(sq)
                    if rr == tr:
                        # check pawns between files
                        step = 1 if rf < tf else -1
                        blocked = False
                        for f in range(rf + step, tf, step):
                            s2 = tr * 8 + f
                            piece_between = board.piece_at(s2)
                            if piece_between and piece_between.piece_type == chess.PAWN:
                                blocked = True
                                break
                        if not blocked:
                            count += 1.0
            return count
        return float(backrank_for(chess.WHITE) - backrank_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Isolated pawn difference: count of isolated pawns (no friendly pawn on adjacent files) White - Black. Measures pawn structure weakness.'
    try:
        pm = board.piece_map()
        # gather pawn files per color
        files_with_white_pawns = {f:0 for f in range(8)}
        files_with_black_pawns = {f:0 for f in range(8)}
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if p.color == chess.WHITE:
                    files_with_white_pawns[f] += 1
                else:
                    files_with_black_pawns[f] += 1
        def isolated_count(files_map):
            cnt = 0
            for f, c in files_map.items():
                if c == 0:
                    continue
                left = files_map.get(f-1, 0)
                right = files_map.get(f+1, 0)
                if left == 0 and right == 0:
                    cnt += c  # count each pawn on that isolated file
            return float(cnt)
        iw = isolated_count(files_with_white_pawns)
        ib = isolated_count(files_with_black_pawns)
        return float(iw - ib)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in count of rooks sitting on the opponent seventh rank (White - Black)'
    try:
        wm = 0
        bm = 0
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.ROOK:
                rank = chess.square_rank(sq)
                if piece.color == chess.WHITE and rank == 6:
                    wm += 1
                if piece.color == chess.BLACK and rank == 1:
