def feature(board: chess.Board) -> float:
    'Difference in pawn shield strength in front of each king: (White pawn shield - Black pawn shield). Counts friendly pawns in king-file +/-1 within 2 ranks forward'
    try:
        def pawn_shield_for_king(king_sq, color):
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            count = 0
            if color == chess.WHITE:
                ranks = [kr + 1, kr + 2]
            else:
                ranks = [kr - 1, kr - 2]
            for f in [kf - 1, kf, kf + 1]:
                if 0 <= f <= 7:
                    for r in ranks:
                        if 0 <= r <= 7:
                            sq = chess.square(f, r)
                            p = board.piece_at(sq)
                            if p is not None and p.piece_type == chess.PAWN and p.color == color:
                                count += 1
            return count
        wk = board.king(chess.WHITE)
        bk = board.king(chess.BLACK)
        if wk is None or bk is None:
            return 0.0
        ws = pawn_shield_for_king(wk, chess.WHITE)
        bs = pawn_shield_for_king(bk, chess.BLACK)
        return float(ws - bs)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of rooks on open files (no pawns of either color on that file): (White - Black)'
    try:
        pawn_files = set()
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.PAWN:
                pawn_files.add(chess.square_file(sq))
        w = 0
        b = 0
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                if f not in pawn_files:
                    if piece.color == chess.WHITE:
                        w += 1
                    else:
                        b += 1
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net king-zone safety difference: (White king defenders - Black attackers in white zone) - (Black king defenders - White attackers in black zone)'
    try:
        wk = board.king(chess.WHITE)
        bk = board.king(chess.BLACK)
        if wk is None or bk is None:
            return 0.0
        def zone_net(king_sq, king_color):
            others = []
            for sq in range(64):
                if chess.square_distance(sq, king_sq) <= 2:
                    others.append(sq)
            attackers = 0
            defenders = 0
            for sq in others:
                attackers += len(board.attackers(not king_color, sq))
                defenders += len(board.attackers(king_color, sq))
            return defenders - attackers
        net_w = zone_net(wk, chess.WHITE)
        net_b = zone_net(bk, chess.BLACK)
        return float(net_w - net_b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in weighted "hanging piece pressure": sum over pieces of max(0, attackers - defenders)*value (White - Black)'
    try:
        values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0}
        white_score = 0.0
        black_score = 0.0
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.KING:
                continue
            atk = len(board.attackers(not piece.color, sq))
            defn = len(board.attackers(piece.color, sq))
            net = max(0, atk - defn)
            val = values.get(piece.piece_type, 0.0)
            if piece.color == chess.WHITE:
                white_score += net * val
            else:
                black_score += net * val
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in minimal Manhattan distance from any rook to the enemy king: (black_min - white_min). Positive means White rooks are closer on average'
    try:
        wk = board.king(chess.WHITE)
        bk = board.king(chess.BLACK)
        INF = 100.0
        wmin = INF
        bmin = INF
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.ROOK:
                if piece.color == chess.WHITE and bk is not None:
                    d = chess.square_distance(sq, bk)
                    if d < wmin:
                        wmin = d
                if piece.color == chess.BLACK and wk is not None:
                    d = chess.square_distance(sq, wk)
                    if d < bmin:
                        bmin = d
        if wmin == INF:
            wmin = 10.0
        if bmin == INF:
            bmin = 10.0
        return float(bmin - wmin)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in simple pawn structure weakness: (isolated pawns + 0.5 * doubled extra pawns) for White - Black'
    try:
        def pawn_metrics(color):
            files_count = {f:0 for f in range(8)}
            pawn_squares = []
            for sq, piece in board.piece_map().items():
                if piece.piece_type == chess.PAWN and piece.color == color:
                    f = chess.square_file(sq)
                    files_count[f] += 1
                    pawn_squares.append(sq)
            isolated = 0
            for sq in pawn_squares:
                f = chess.square_file(sq)
                has_adj = False
                for af in [f-1, f+1]:
                    if 0 <= af <= 7 and files_count.get(af,0) > 0:
                        has_adj = True
                        break
                if not has_adj:
                    isolated += 1
            doubled_extra = sum(max(0, cnt-1) for cnt in files_count.values())
            return isolated + 0.5 * doubled_extra
        wm = pawn_metrics(chess.WHITE)
        bm = pawn_metrics(chess.BLACK)
        return float(wm - bm)
    except Exception:
        return 0.0

