def feature(board: chess.Board) -> float:
    'Endgame king centrality advantage: if low material, return (black king dist to center - white king dist to center), else 0'
    try:
        values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0}
        material = 0.0
        for sq, piece in board.piece_map().items():
            if piece.piece_type != chess.KING:
                material += values.get(piece.piece_type, 0.0)
        # Consider endgame if material excluding kings <= 10
        if material > 10.0:
            return 0.0
        centers = [chess.parse_square(s) for s in ('d4','e4','d5','e5')]
        def king_central_dist(color):
            k = board.king(color)
            if k is None:
                return 100.0
            # minimal Manhattan distance to center squares
            return min(chess.square_distance(k, c) for c in centers)
        wd = king_central_dist(chess.WHITE)
        bd = king_central_dist(chess.BLACK)
        return float(bd - wd)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in back-rank vulnerability: 1.0 if king has enemy rook/queen with clear line and weak pawn shield, else 0 (White - Black)'
    try:
        def pawn_shield_one_rank(king_sq, color):
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            cnt = 0
            if color == chess.WHITE:
                r = kr + 1
            else:
                r = kr - 1
            for f in [kf - 1, kf, kf + 1]:
                if 0 <= f <= 7 and 0 <= r <= 7:
                    sq = chess.square(f, r)
                    p = board.piece_at(sq)
                    if p is not None and p.piece_type == chess.PAWN and p.color == color:
                        cnt += 1
            return cnt
        def has_clear_line(att_sq, king_sq):
            af = chess.square_file(att_sq); ar = chess.square_rank(att_sq)
            kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
            df = af - kf; dr = ar - kr
            stepf = 0 if df == 0 else (1 if df > 0 else -1)
            stepr = 0 if dr == 0 else (1 if dr > 0 else -1)
            if not (df == 0 or dr == 0 or abs(df) == abs(dr)):
                return False
            cf = kf + stepf
            cr = kr + stepr
            while (cf, cr) != (af, ar):
                mid = chess.square(cf, cr)
                if board.piece_at(mid) is not None:
                    return False
                cf += stepf
                cr += stepr
            return True
        w_vuln = 0.0
        b_vuln = 0.0
        wk = board.king(chess.WHITE)
        bk = board.king(chess.BLACK)
        if wk is not None:
            shield = pawn_shield_one_rank(wk, chess.WHITE)
            if shield <= 1:
                for sq, piece in board.piece_map().items():
                    if piece.color == chess.BLACK and piece.piece_type in (chess.ROOK, chess.QUEEN):
                        if has_clear_line(sq, wk):
                            w_vuln = 1.0
                            break
        if bk is not None:
            shield = pawn_shield_one_rank(bk, chess.BLACK)
            if shield <= 1:
                for sq, piece in board.piece_map().items():
                    if piece.color == chess.WHITE and piece.piece_type in (chess.ROOK, chess.QUEEN):
                        if has_clear_line(sq, bk):
                            b_vuln = 1.0
                            break
        return float(b_vuln - w_vuln)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net pressure of attackers on squares adjacent to the kings (White attacking Black king minus Black attacking White king)'
    try:
        pieces = board.piece_map()
        white_king_sq = next((sq for sq, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        def surrounding_attackers(target_sq, attacker_color):
            if target_sq is None:
                return 0
            rf = chess.square_file(target_sq)
            rr = chess.square_rank(target_sq)
            count = 0
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    nf = rf + df
                    nr = rr + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        sq = chess.square(nf, nr)
                        try:
                            count += len(board.attackers(attacker_color, sq))
                        except Exception:
                            count += 0
            return count
        black_pressure = surrounding_attackers(black_king_sq, chess.WHITE)
        white_pressure = surrounding_attackers(white_king_sq, chess.BLACK)
        return float(black_pressure - white_pressure)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of rooks on the seventh rank (White seventh rank minus Black seventh rank)'
    try:
        pieces = board.piece_map()
        w7 = 0
        b7 = 0
        for sq, p in pieces.items():
            if p.piece_type == chess.ROOK:
                rank = chess.square_rank(sq)
                if p.color == chess.WHITE and rank == 6:
                    w7 += 1
                if p.color == chess.BLACK and rank == 1:
                    b7 += 1
        return float(w7 - b7)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Queen centralization score: sum centrality of White queens minus Black queens (central squares d4,e4,d5,e5 weighted)'
    try:
        center_sqs = [chess.parse_square(n) for n in ('d4', 'e4', 'd5', 'e5')]
        pieces = board.piece_map()
        def queen_score(color):
            s = 0.0
            for sq, p in pieces.items():
                if p.piece_type == chess.QUEEN and p.color == color:
                    min_d = min(chess.square_distance(sq, c) for c in center_sqs)
                    # convert distance to a 0..1 centrality (closer -> higher)
                    score = max(0.0, (4.0 - min_d) / 4.0)
                    s += score
            return s
        return float(queen_score(chess.WHITE) - queen_score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in pawn islands (contiguous file groups with pawns): White islands minus Black islands'
    try:
        pieces = board.piece_map()
        def pawn_islands(color):
            files_with_pawns = sorted({chess.square_file(sq) for sq, p in pieces.items() if p.piece_type == chess.PAWN and p.color == color})
            if not files_with_pawns:
                return 0
            islands = 1
            prev = files_with_pawns[0]
            for f in files_with_pawns[1:]:
                if f - prev > 1:
                    islands += 1
                prev = f
            return islands
        return float(pawn_islands(chess.WHITE) - pawn_islands(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Value (in pawn units) of defended non-king pieces: White minus Black'
    try:
        values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0}
        pieces = board.piece_map()
        w_val = 0.0
        b_val = 0.0
        for sq, p in pieces.items():
            if p.piece_type == chess.KING:
                continue
            defenders = board.attackers(p.color, sq)
            if defenders and len(defenders) > 0:
                v = values.get(p.piece_type, 0.0)
                if p.color == chess.WHITE:
                    w_val += v
                else:
                    b_val += v
        return float(w_val - b_val)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Hanging material balance: total value of opponent pieces that are undefended and attacked (Black hanging minus White hanging, positive favors White)'
    try:
        values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0}
        pieces = board.piece_map()
        white_hanging = 0.0
        black_hanging = 0.0
        for sq, p in pieces.items():
            if p.piece_type == chess.KING:
                continue
            opp = chess.BLACK if p.color == chess.WHITE else chess.WHITE
            opp_attackers = len(board.attackers(opp, sq))
            own_defenders = len(board.attackers(p.color, sq))
            if opp_attackers > 0 and own_defenders == 0:
                if p.color == chess.WHITE:
                    white_hanging += values.get(p.piece_type, 0.0)
                else:
                    black_hanging += values.get(p.piece_type, 0.0)
        # Positive if Black has more hanging material (good for White)
        return float(black_hanging - white_hanging)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net number of direct attackers on the kings (White attackers on Black king minus Black attackers on White king)'
    try:
        pieces = board.piece_map()
        white_king_sq = next((sq for sq, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        wa_on_b = len(board.attackers(chess.WHITE, black_king_sq)) if black_king_sq is not None else 0
        ba_on_w = len(board.attackers(chess.BLACK, white_king_sq)) if white_king_sq is not None else 0
        return float(wa_on_b - ba_on_w)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Queenside pawn majority: number of White pawns on files a-d minus Black pawns on files a-d'
    try:
        pieces = board.piece_map()
        w = 0
        b = 0
        for sq, p in pieces.items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if f <= 3:
                    if p.color == chess.WHITE:
                        w += 1
                    else:
                        b += 1
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Active minor pieces in opponent half on central files (c-f): count of White minors minus Black minors'
    try:
        pieces = board.piece_map()
        def count_active(color):
            c = 0
            for sq, p in pieces.items():
                if p.color != color:
                    continue
                if p.piece_type in (chess.KNIGHT, chess.BISHOP):
                    file = chess.square_file(sq)
                    rank = chess.square_rank(sq)
                    on_central_files = 2 <= file <= 5  # c,d,e,f
                    if color == chess.WHITE:
                        in_opponent_half = rank >= 4
                    else:
                        in_opponent_half = rank <= 3
                    if on_central_files and in_opponent_half:
                        c += 1
            return c
        return float(count_active(chess.WHITE) - count_active(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of distinct squares attacked by each side (White minus Black), normalized by board size'
    try:
        white_attacked = 0
        black_attacked = 0
        for sq in range(64):
            if board.is_attacked_by(chess.WHITE, sq):
                white_attacked += 1
            if board.is_attacked_by(chess.BLACK, sq):
                black_attacked += 1
        return float((white_attacked - black_attacked) / 64.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in pressure on the squares immediately surrounding the king: (White - Black) count of opponent-king-adjacent squares attacked'
    def king_square(color):
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.KING and pc.color == color:
                return sq
        return None
    def adjacent_squares(sq):
        if sq is None:
            return []
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        res = []
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                if df == 0 and dr == 0:
                    continue
                nf = f + df
                nr = r + dr
                if 0 <= nf <= 7 and 0 <= nr <= 7:
                    res.append(chess.square(nf, nr))
        return res
    wking = king_square(chess.WHITE)
    bking = king_square(chess.BLACK)
    white_pressure = 0
    black_pressure = 0
    if bking is not None:
        for sq in adjacent_squares(bking):
            if board.is_attacked_by(chess.WHITE, sq):
                white_pressure += 1
    if wking is not None:
        for sq in adjacent_squares(wking):
            if board.is_attacked_by(chess.BLACK, sq):
                black_pressure += 1
    return float(white_pressure - black_pressure)

def feature(board: chess.Board) -> float:
    'Proximity of queens to the opposing king: sum(1/(1+Manhattan_distance)) for queens (White - Black), higher = more dangerous'
    # Use chess.square_distance which is Chebyshev, suitable as proximity metric
    def king_square(color):
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.KING and pc.color == color:
                return sq
        return None
    wking = king_square(chess.WHITE)
    bking = king_square(chess.BLACK)
    white_score = 0.0
    black_score = 0.0
    for sq, pc in board.piece_map().items():
        if pc.piece_type == chess.QUEEN:
            if pc.color == chess.WHITE and bking is not None:
                d = chess.square_distance(sq, bking)
                white_score += 1.0 / (1.0 + d)
            if pc.color == chess.BLACK and wking is not None:
                d = chess.square_distance(sq, wking)
                black_score += 1.0 / (1.0 + d)
    # scale to make more significant
    return float(10.0 * (white_score - black_score))

def feature(board: chess.Board) -> float:
    'Count of rooks on the opponent\'s seventh rank (White rooks on rank 7 / Black rooks on rank 2) difference (White - Black)'
    white_count = 0
    black_count = 0
    for sq, pc in board.piece_map().items():
        if pc.piece_type == chess.ROOK:
            r = chess.square_rank(sq)
            if pc.color == chess.WHITE:
                if r == 6:  # white rook on black 7th (0-based ranks)
                    white_count += 1
            else:
                if r == 1:  # black rook on white 7th
                    black_count += 1
    return float(white_count - black_count)

def feature(board: chess.Board) -> float:
    'Pawn shield in front of the king: number of friendly pawns on the three squares immediately in front of the king (White - Black)'
    def king_square(color):
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.KING and pc.color == color:
                return sq
        return None
    def pawn_shield_count(king_sq, color):
        if king_sq is None:
            return 0
        f = chess.square_file(king_sq)
        r = chess.square_rank(king_sq)
        dirs = []
        if color == chess.WHITE:
            dr = 1
        else:
            dr = -1
        for df in (-1, 0, 1):
            nf = f + df
            nr = r + dr
            if 0 <= nf <= 7 and 0 <= nr <= 7:
                sq = chess.square(nf, nr)
                pc = board.piece_at(sq)
                if pc is not None and pc.piece_type == chess.PAWN and pc.color == color:
                    dirs.append(sq)
        return len(dirs)
    wking = king_square(chess.WHITE)
    bking = king_square(chess.BLACK)
    return float(pawn_shield_count(wking, chess.WHITE) - pawn_shield_count(bking, chess.BLACK))

def feature(board: chess.Board) -> float:
    'Count of undefended (hanging) pieces excluding kings: number of pieces attacked by opponent with no defenders (White - Black)'
    white_hanging = 0
    black_hanging = 0
    for sq, pc in board.piece_map().items():
        if pc.piece_type == chess.KING:
            continue
        if pc.color == chess.WHITE:
            attackers = board.attackers(chess.BLACK, sq)
            defenders = board.attackers(chess.WHITE, sq)
            if attackers and not defenders:
                white_hanging += 1
        else:
            attackers = board.attackers(chess.WHITE, sq)
            defenders = board.attackers(chess.BLACK, sq)
            if attackers and not defenders:
                black_hanging += 1
    return float(white_hanging - black_hanging)

def feature(board: chess.Board) -> float:
    'Number of opponent pieces that are currently attacked by two or more friendly pieces (double-attack / overloaded target) difference (White - Black)'
    white_double_targets = 0
    black_double_targets = 0
    # For each occupied square check attackers count by each color
    for sq, pc in board.piece_map().items():
        if pc.color == chess.WHITE:
            cnt = len(board.attackers(chess.BLACK, sq))
            if cnt >= 2:
                black_double_targets += 1
        else:
            cnt = len(board.attackers(chess.WHITE, sq))
            if cnt >= 2:
                white_double_targets += 1
    return float(white_double_targets - black_double_targets)

def feature(board: chess.Board) -> float:
    'Sum of material (in centipawns) of opponent pieces that are attacked by the side (White - Black): measures tactical pressure on valuable pieces'
    VALUES = {
        chess.PAWN: 100.0,
        chess.KNIGHT: 320.0,
        chess.BISHOP: 330.0,
        chess.ROOK: 500.0,
        chess.QUEEN: 900.0,
        chess.KING: 20000.0
    }
    white_sum = 0.0
    black_sum = 0.0
    for sq, pc in board.piece_map().items():
        if pc.color == chess.WHITE:
            # white piece attacked by black?
            if board.is_attacked_by(chess.BLACK, sq):
                white_sum += VALUES.get(pc.piece_type, 0.0)
        else:
            if board.is_attacked_by(chess.WHITE, sq):
                black_sum += VALUES.get(pc.piece_type, 0.0)
    # careful: white_sum is material of white pieces attacked by black; we want material of opponent pieces attacked by side:
    # so return (material of black pieces attacked by white) - (material of white pieces attacked by black)
    return float(black_sum - white_sum)

def feature(board: chess.Board) -> float:
    'Count of safe adjacent king squares (not attacked and not occupied by own piece) difference (White - Black): measure of immediate king escape options'
    def king_square(color):
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.KING and pc.color == color:
                return sq
        return None
    def safe_adjacent(king_sq, color):
        if king_sq is None:
            return 0
        f = chess.square_file(king_sq)
        r = chess.square_rank(king_sq)
        cnt = 0
        opp = not color
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                if df == 0 and dr == 0:
                    continue
                nf = f + df
                nr = r + dr
                if 0 <= nf <= 7 and 0 <= nr <= 7:
                    sq = chess.square(nf, nr)
                    occ = board.piece_at(sq)
                    if occ is not None and occ.color == color:
                        continue
                    if not board.is_attacked_by(chess.BLACK if color == chess.WHITE else chess.WHITE, sq):
                        cnt += 1
        return cnt
    wking = king_square(chess.WHITE)
    bking = king_square(chess.BLACK)
    return float(safe_adjacent(wking, chess.WHITE) - safe_adjacent(bking, chess.BLACK))

def feature(board: chess.Board) -> float:
    'Pawn structural weakness score: isolated pawns + 0.5*doubled pawns (White - Black)'
    # compute per-file pawn counts
    wpawns = [0]*8
    bpawns = [0]*8
    for sq, pc in board.piece_map().items():
        if pc.piece_type == chess.PAWN:
            f = chess.square_file(sq)
            if pc.color == chess.WHITE:
                wpawns[f] += 1
            else:
                bpawns[f] += 1
    def weakness(counts):
        iso = 0
        doubled = 0
        for f in range(8):
            if counts[f] > 0:
                left = counts[f-1] if f-1 >= 0 else 0
                right = counts[f+1] if f+1 <= 7 else 0
                if left + right == 0:
                    # number of isolated pawns on this file equals count
                    iso += counts[f]
                if counts[f] > 1:
                    doubled += (counts[f] - 1)
        return iso + 0.5 * doubled
    return float(weakness(wpawns) - weakness(bpawns))

def feature(board: chess.Board) -> float:
    'Open / semi-open file pressure adjacent to the king: count of files among king file and neighbors that are semi-open (no friendly pawns) and have an opponent rook/queen attacking a square on that file (White - Black)'
    def king_square(color):
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.KING and pc.color == color:
                return sq
        return None
    def has_rook_queen_pressure_on_file(file_idx, attacker_color):
        # a file has pressure if any square on that file is attacked by attacker_color
        # and at least one of the attackers is a rook or queen (indicating file pressure)
        for r in range(8):
            sq = chess.square(file_idx, r)
            if board.is_attacked_by(attacker_color, sq):
                attackers = board.attackers(attacker_color, sq)
                for a in attackers:
                    apc = board.piece_at(a)
                    if apc is not None and apc.piece_type in (chess.ROOK, chess.QUEEN):
                        return True
        return False
    def semi_open_and_pressured(king_sq, color):
        if king_sq is None:
            return 0
        f = chess.square_file(king_sq)
        cnt = 0
        for df in (-1, 0, 1):
            nf = f + df
            if not (0 <= nf <= 7):
                continue
            # semi-open: no friendly pawns on file
            friendly_pawn_on_file = False
            for r in range(8):
                pc = board.piece_at(chess.square(nf, r))
                if pc is not None and pc.piece_type == chess.PAWN and pc.color == color:
                    friendly_pawn_on_file = True
                    break
            if not friendly_pawn_on_file:
                attacker = chess.BLACK if color == chess.WHITE else chess.WHITE
                if has_rook_queen_pressure_on_file(nf, attacker):
                    cnt += 1
        return cnt
    wking = king_square(chess.WHITE)
    bking = king_square(chess.BLACK)
    return float(semi_open_and_pressured(wking, chess.WHITE) - semi_open_and_pressured(bking, chess.BLACK))

def feature(board: chess.Board) -> float:
    'Pressure on the opponent king: weighted sum of our attackers to the king ring (white - black)'
    piece_vals = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    pm = board.piece_map()
    # find kings
    wk = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.WHITE), None)
    bk = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.BLACK), None)
    def ring_pressure(king_sq, attacker_color):
        if king_sq is None:
            return 0.0
        kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
        total = 0.0
        for df in (-1,0,1):
            for dr in (-1,0,1):
                f = kf+df; r = kr+dr
                if 0 <= f <= 7 and 0 <= r <= 7:
                    sq = chess.square(f,r)
                    attackers = board.attackers(attacker_color, sq)
                    for a in attackers:
                        p = board.piece_at(a)
                        if p:
                            total += piece_vals.get(p.piece_type,0.0)
        return total
    white_pressure_on_black = ring_pressure(bk, chess.WHITE)
    black_pressure_on_white = ring_pressure(wk, chess.BLACK)
    return float(white_pressure_on_black - black_pressure_on_white)

def feature(board: chess.Board) -> float:
    'Rook effectiveness on open or semi-open files: open=1.0, semi-open=0.5; returns (white - black)'
    pm = board.piece_map()
    white_score = 0.0; black_score = 0.0
    # precompute pawn presence per file
    pawn_files_white = set()
    pawn_files_black = set()
    for sq,p in pm.items():
        if p.piece_type == chess.PAWN:
            f = chess.square_file(sq)
            if p.color == chess.WHITE:
                pawn_files_white.add(f)
            else:
                pawn_files_black.add(f)
    for sq,p in pm.items():
        if p.piece_type == chess.ROOK:
            f = chess.square_file(sq)
            any_pawn_on_file = (f in pawn_files_white) or (f in pawn_files_black)
            friendly_pawn_on_file = (f in pawn_files_white) if p.color==chess.WHITE else (f in pawn_files_black)
            score = 0.0
            if not any_pawn_on_file:
                score = 1.0
            elif not friendly_pawn_on_file:
                score = 0.5
            if p.color == chess.WHITE:
                white_score += score
            else:
                black_score += score
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Pawn-structure weakness penalty (doubled, isolated, backward) returned as (black_penalty - white_penalty) to align positive = white better'
    pm = board.piece_map()
    # gather pawn files and pawn ranks per file for both colors
    files_white = {f:[] for f in range(8)}
    files_black = {f:[] for f in range(8)}
    for sq,p in pm.items():
        if p and p.piece_type==chess.PAWN:
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if p.color==chess.WHITE:
                files_white[f].append(r)
            else:
                files_black[f].append(r)
    def penalties(files, enemy_files, color_is_white):
        doubled=0; isolated=0; backward=0
        for f in range(8):
            cnt = len(files[f])
            if cnt > 1:
                doubled += cnt - 1
            for r in files[f]:
                # isolated: no friendly pawns on adjacent files
                adj = False
                for af in (f-1,f+1):
                    if 0<=af<=7 and len(files[af])>0:
                        adj = True; break
                if not adj:
                    isolated += 1
                # backward approximation: isolated and enemy pawn ahead on adjacent file
                if not adj:
                    # check enemy pawns on adjacent files in front of this pawn
                    if color_is_white:
                        # enemy pawn is ahead if its rank > r
                        enemy_ahead = any(er > r for af in (f-1,f+1) if 0<=af<=7 for er in enemy_files[af])
                    else:
                        enemy_ahead = any(er < r for af in (f-1,f+1) if 0<=af<=7 for er in enemy_files[af])
                    if enemy_ahead:
                        backward += 1
        return doubled*0.6 + isolated*0.8 + backward*0.7
    white_pen = penalties(files_white, files_black, True)
    black_pen = penalties(files_black, files_white, False)
    # return black_pen - white_pen so positive means white position relatively better
    return float(black_pen - white_pen)

def feature(board: chess.Board) -> float:
    'Sum of the values of own pieces that are under-defended (attacked more than defended); returned as (white - black)'
    vals = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    pm = board.piece_map()
    white_sum = 0.0; black_sum = 0.0
    for sq,p in pm.items():
        if p is None: continue
        color = p.color
        opp = not color
        attackers = len(board.attackers(opp, sq))
        defenders = len(board.attackers(color, sq))
        if attackers > defenders:
            # count piece value as liability
            if color==chess.WHITE:
                white_sum += vals.get(p.piece_type,0.0)
            else:
                black_sum += vals.get(p.piece_type,0.0)
    return float(white_sum - black_sum)

def feature(board: chess.Board) -> float:
    'Mobility for sliding pieces (rooks, bishops, queens): count legal moves originating from sliders (white - black)'
    white_moves = 0; black_moves = 0
    for mv in board.legal_moves:
        from_sq = mv.from_square
        p = board.piece_at(from_sq)
        if p and p.piece_type in (chess.BISHOP, chess.ROOK, chess.QUEEN):
            if p.color == chess.WHITE:
                white_moves += 1
            else:
                black_moves += 1
    return float(white_moves - black_moves)

def feature(board: chess.Board) -> float:
    'King pawn shield: count friendly pawns in the three-file shield immediately in front of king (white - black)'
    pm = board.piece_map()
    wk = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.WHITE), None)
    bk = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.BLACK), None)
    def shield_count(king_sq, color):
        if king_sq is None:
            return 0.0
        kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
        cnt = 0
        for df in (-1,0,1):
            f = kf + df
            if 0 <= f <= 7:
                # look 1 and 2 squares in front depending on color
                if color == chess.WHITE:
                    for dr in (1,2):
                        r = kr + dr
                        if 0 <= r <= 7 and board.piece_at(chess.square(f,r)) and board.piece_at(chess.square(f,r)).piece_type==chess.PAWN and board.piece_at(chess.square(f,r)).color==color:
                            cnt += 1
                else:
                    for dr in (1,2):
                        r = kr - dr
                        if 0 <= r <= 7 and board.piece_at(chess.square(f,r)) and board.piece_at(chess.square(f,r)).piece_type==chess.PAWN and board.piece_at(chess.square(f,r)).color==color:
                            cnt += 1
        return float(cnt)
    white_shield = shield_count(wk, chess.WHITE)
    black_shield = shield_count(bk, chess.BLACK)
    return float(white_shield - black_shield)

def feature(board: chess.Board) -> float:
    'Count of pieces (non-pawns) on the opponent seventh rank (white - black)'
    pm = board.piece_map()
    white_count = 0; black_count = 0
    for sq,p in pm.items():
        if p is None or p.piece_type == chess.PAWN:
            continue
        r = chess.square_rank(sq)
        if p.color == chess.WHITE and r == 6:
            white_count += 1
        if p.color == chess.BLACK and r == 1:
            black_count += 1
    return float(white_count - black_count)

def feature(board: chess.Board) -> float:
    'Development: number of non-pawn pieces that have left their initial starting squares (white - black)'
    start_sqs_white = {chess.A1, chess.B1, chess.C1, chess.D1, chess.E1, chess.F1, chess.G1, chess.H1}
    start_sqs_black = {chess.A8, chess.B8, chess.C8, chess.D8, chess.E8, chess.F8, chess.G8, chess.H8}
    pm = board.piece_map()
    white_dev = 0; black_dev = 0
    for sq,p in pm.items():
        if p is None: continue
        if p.piece_type == chess.PAWN:
            continue
        if p.color == chess.WHITE:
            if sq not in start_sqs_white:
                white_dev += 1
        else:
            if sq not in start_sqs_black:
                black_dev += 1
    return float(white_dev - black_dev)

def feature(board: chess.Board) -> float:
    'Count of pinned pieces approximation: number of friendly pieces pinned to their king by an enemy sliding piece (returned as pinned_black - pinned_white so positive favors White)'
    pm = board.piece_map()
    # find kings
    wk = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.WHITE), None)
    bk = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.BLACK), None)
    def count_pinned(king_sq, king_color):
        if king_sq is None:
            return 0
        pinned = set()
        kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
        for sq,p in pm.items():
            if p is None or p.color == king_color:
                continue
            if p.piece_type not in (chess.ROOK, chess.BISHOP, chess.QUEEN):
                continue
            ef = chess.square_file(sq); er = chess.square_rank(sq)
            df = ef - kf; dr = er - kr
            # check alignment: same file, same rank or diagonal
            if df == 0:
                step_f = 0; step_r = 1 if dr>0 else -1
            elif dr == 0:
                step_r = 0; step_f = 1 if df>0 else -1
            elif abs(df) == abs(dr):
                step_f = 1 if df>0 else -1
                step_r = 1 if dr>0 else -1
            else:
                continue
            # walk from enemy piece towards king, count pieces in between
            cur_f = ef - step_f; cur_r = er - step_r
            between = []
            while (cur_f,cur_r) != (kf,kr):
                if not (0<=cur_f<=7 and 0<=cur_r<=7):
                    between = None; break
                s = chess.square(cur_f, cur_r)
                if board.piece_at(s):
                    between.append((s, board.piece_at(s)))
                cur_f -= step_f; cur_r -= step_r
            if between is None:
                continue
            if len(between) == 1:
                sq_between, piece_between = between[0]
                if piece_between.color == king_color:
                    pinned.add(sq_between)
        return len(pinned)
    pinned_white = count_pinned(wk, chess.WHITE)
    pinned_black = count_pinned(bk, chess.BLACK)
    # return pinned_black - pinned_white so positive means fewer white pins (good for White)
    return float(pinned_black - pinned_white)

def feature(board: chess.Board) -> float:
    'Difference in number of rooks occupying the opponent seventh rank (White - Black)'
    try:
        wm = 0
        bm = 0
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.ROOK:
                r = chess.square_rank(sq)
                if piece.color == chess.WHITE and r == 6:
                    wm += 1
                if piece.color == chess.BLACK and r == 1:
                    bm += 1
        return float(wm - bm)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net attacking material pressure on squares adjacent to the kings (White pressure on Black king - Black pressure on White king)'
    values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    def king_adjacent_pressure(king_color):
        # find king
        sq_king = None
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING and p.color == king_color:
                sq_king = sq
                break
        if sq_king is None:
            return 0
        pressure = 0
        enemy = not king_color
        for sq in chess.SQUARES:
            if chess.square_distance(sq, sq_king) <= 1 and sq != sq_king:
                attackers = board.attackers(enemy, sq)
                for a in attackers:
                    ap = board.piece_at(a)
                    if ap:
                        pressure += values.get(ap.piece_type, 0)
        return pressure
    try:
        wp = king_adjacent_pressure(chess.BLACK)  # white attacking black king
        bp = king_adjacent_pressure(chess.WHITE)  # black attacking white king
        return float(wp - bp)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Sum of values of pieces that are more attacked than defended (weighted by attack surplus), White minus Black'
    values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    try:
        total_white = 0.0
        total_black = 0.0
        for sq, piece in board.piece_map().items():
            own = piece.color
            opp = not own
            attackers = len(board.attackers(opp, sq))
            defenders = len(board.attackers(own, sq))
            surplus = attackers - defenders
            if surplus > 0:
                val = values.get(piece.piece_type, 0) * surplus
                if own == chess.WHITE:
                    total_white += val
                else:
                    total_black += val
        return float(total_white - total_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn-structure weakness score (penalizes isolated and doubled pawns); returns White - Black (penalty positive means White worse)'
    try:
        pawn_squares = {chess.WHITE: [], chess.BLACK: []}
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                pawn_squares[p.color].append(sq)
        def pawn_penalty(color):
            files = [chess.square_file(sq) for sq in pawn_squares[color]]
            penalty = 0.0
            # doubled pawns: count extras on each file
            for f in range(8):
                cnt = files.count(f)
                if cnt > 1:
                    penalty += (cnt - 1) * 0.5
            # isolated pawns: no friendly pawn on adjacent files
            for sq in pawn_squares[color]:
                f = chess.square_file(sq)
                if files.count(f-1) == 0 and files.count(f+1) == 0:
                    penalty += 0.5
            return penalty
        wpen = pawn_penalty(chess.WHITE)
        bpen = pawn_penalty(chess.BLACK)
        # we return White minus Black (positive means White worse pawn structure)
        return float(bpen - wpen)  # positive => White better (less penalty)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of major pieces (rooks and queens) on open or semi-open files weighted (open=1, semi-open=0.5), White - Black'
    try:
        file_has_pawn = [False]*8
        file_white_pawn = [0]*8
        file_black_pawn = [0]*8
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                file_has_pawn[f] = True
                if p.color == chess.WHITE:
                    file_white_pawn[f] += 1
                else:
                    file_black_pawn[f] += 1
        wscore = 0.0
        bscore = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type in (chess.ROOK, chess.QUEEN):
                f = chess.square_file(sq)
                if not file_has_pawn[f]:
                    bonus = 1.0
                elif (p.color == chess.WHITE and file_white_pawn[f] == 0) or (p.color == chess.BLACK and file_black_pawn[f] == 0):
                    bonus = 0.5
                else:
                    bonus = 0.0
                if p.color == chess.WHITE:
                    wscore += bonus
                else:
                    bscore += bonus
        return float(wscore - bscore)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of minor-piece outposts (knights or bishops on squares not attackable by enemy pawns and defended by own pieces), White - Black'
    try:
        def is_attacked_by_pawn(color, sq):
            attackers = board.attackers(color, sq)
            for a in attackers:
                ap = board.piece_at(a)
                if ap and ap.piece_type == chess.PAWN:
                    return True
            return False
        def outpost_count(color):
            cnt = 0
            for sq, p in board.piece_map().items():
                if p.color != color:
                    continue
                if p.piece_type not in (chess.KNIGHT, chess.BISHOP):
                    continue
                # defended by own piece?
                defended = len(board.attackers(color, sq)) > 0
                if not defended:
                    continue
                # not attacked by enemy pawns
                if is_attacked_by_pawn(not color, sq):
                    continue
                # advanced / central ranks: for White prefer ranks 4-6 (index 3..5), for Black 3-5 (index 2..4)
                r = chess.square_rank(sq)
                if color == chess.WHITE:
                    if 3 <= r <= 5:
                        cnt += 1
                else:
                    if 2 <= r <= 4:
                        cnt += 1
            return cnt
        return float(outpost_count(chess.WHITE) - outpost_count(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in king shield pawn count (number of friendly pawns in front of the king within 2 ranks and adjacent files), White - Black'
    try:
        def shield_count(color):
            # find king
            ks = None
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == color:
                    ks = sq
                    break
            if ks is None:
                return 0
            kf = chess.square_file(ks)
            kr = chess.square_rank(ks)
            cnt = 0
            if color == chess.WHITE:
                ranks = [kr+1, kr+2]
            else:
                ranks = [kr-1, kr-2]
            for r in ranks:
                if r < 0 or r > 7:
                    continue
                for f in [kf-1, kf, kf+1]:
                    if 0 <= f <= 7:
                        sq = chess.square(f, r)
                        p = board.piece_at(sq)
                        if p and p.piece_type == chess.PAWN and p.color == color:
                            cnt += 1
            return cnt
        return float(shield_count(chess.WHITE) - shield_count(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Back-rank vulnerability difference: (Black back-rank vulnerability) - (White back-rank vulnerability); positive means Black more vulnerable'
    try:
        def backrank_vuln(color):
            # measure vulnerability of color's king on its back rank
            ks = None
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == color:
                    ks = sq
                    break
            if ks is None:
                return 0.0
            r = chess.square_rank(ks)
            # for white back rank is 0, for black 7
            back_rank = 0 if color == chess.WHITE else 7
            if r != back_rank:
                return 0.0
            # pawns on the rank in front of back rank
            front_rank = 1 if color == chess.WHITE else 6
            pawns_in_front = 0
            for f in range(8):
                p = board.piece_at(chess.square(f, front_rank))
                if p and p.piece_type == chess.PAWN and p.color == color:
                    pawns_in_front += 1
            if pawns_in_front > 0:
                return 0.0
            # count distinct enemy heavy attackers (rooks/queens) that attack any square on the king's back rank near king file window
            kf = chess.square_file(ks)
            targets = []
            for f in range(max(0, kf-2), min(7, kf+2)+1):
                targets.append(chess.square(f, back_rank))
            heavy_attackers = set()
            enemy = not color
            for t in targets:
                for a in board.attackers(enemy, t):
                    ap = board.piece_at(a)
                    if ap and ap.piece_type in (chess.ROOK, chess.QUEEN):
                        heavy_attackers.add(a)
            return float(len(heavy_attackers))
        bv_black = backrank_vuln(chess.BLACK)
        bv_white = backrank_vuln(chess.WHITE)
        return float(bv_black - bv_white)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in count of almost-trapped pieces (non-king pieces with <=1 legal moves), White - Black'
    try:
        # count legal moves per origin square
        origin_counts = {}
        for mv in board.legal_moves:
            origin_counts[mv.from_square] = origin_counts.get(mv.from_square, 0) + 1
        wcnt = 0
        bcnt = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING:
                continue
            moves = origin_counts.get(sq, 0)
            if moves <= 1:
                if p.color == chess.WHITE:
                    wcnt += 1
                else:
                    bcnt += 1
        return float(wcnt - bcnt)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net advantage in overwhelming attacks on squares adjacent to the king: sum(max(0, attackers - defenders)) over adjacent squares, White - Black'
    try:
        def adj_overwhelm(king_color, attacker_color):
            # sum over squares adjacent to king of positive surplus of attackers over defenders
            ks = None
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == king_color:
                    ks = sq
                    break
            if ks is None:
                return 0
            total = 0
            for sq in chess.SQUARES:
                if chess.square_distance(sq, ks) <= 1 and sq != ks:
                    atk = len(board.attackers(attacker_color, sq))
                    defn = len(board.attackers(king_color, sq))
                    surplus = atk - defn
                    if surplus > 0:
                        total += surplus
            return total
        w_over = adj_overwhelm(chess.BLACK, chess.WHITE)  # white attacking black king
        b_over = adj_overwhelm(chess.WHITE, chess.BLACK)  # black attacking white king
        return float(w_over - b_over)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net summed attacker-weight on squares adjacent to each king (White - Black); weights: pawn=1,knight=3,bishop=3,rook=5,queen=9'
    weights = {chess.PAWN: 1.0, chess.KNIGHT: 3.0, chess.BISHOP: 3.0, chess.ROOK: 5.0, chess.QUEEN: 9.0, chess.KING: 0.5}
    def king_pressure(king_color):
        kingsq = None
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.KING and pc.color == king_color:
                kingsq = sq
                break
        if kingsq is None:
            return 0.0
        kf = chess.square_file(kingsq); kr = chess.square_rank(kingsq)
        pressure = 0.0
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                if df == 0 and dr == 0:
                    continue
                f = kf + df; r = kr + dr
                if 0 <= f <= 7 and 0 <= r <= 7:
                    sq = chess.square(f, r)
                    attackers = board.attackers(not king_color, sq)
                    for a in attackers:
                        pc = board.piece_at(a)
                        if pc:
                            pressure += weights.get(pc.piece_type, 1.0)
        return pressure
    try:
        wp = king_pressure(chess.WHITE)
        bp = king_pressure(chess.BLACK)
    except Exception:
        return 0.0
    return float(wp - bp)

def feature(board: chess.Board) -> float:
    'Difference in rook activity on open/semi-open files: open file=1.0, semi-open (no own pawns)=0.5; (White - Black)'
    def file_pawn_presence(file_index):
        w = any(pc for sq, pc in board.piece_map().items() if pc.piece_type == chess.PAWN and chess.square_file(sq) == file_index and pc.color == chess.WHITE)
        b = any(pc for sq, pc in board.piece_map().items() if pc.piece_type == chess.PAWN and chess.square_file(sq) == file_index and pc.color == chess.BLACK)
        return w, b
    white_score = 0.0
    black_score = 0.0
    for sq, pc in board.piece_map().items():
        if pc.piece_type == chess.ROOK:
            f = chess.square_file(sq)
            w_pawn, b_pawn = file_pawn_presence(f)
            # open if no pawns at all, semi-open if opponent has pawn but own doesn't
            if not (w_pawn or b_pawn):
                val = 1.0
            elif pc.color == chess.WHITE and not w_pawn:
                val = 0.5
            elif pc.color == chess.BLACK and not b_pawn:
                val = 0.5
            else:
                val = 0.0
            if pc.color == chess.WHITE:
                white_score += val
            else:
                black_score += val
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Bishop-structure feature: (bishop-pair advantage) - 0.5*(bad-bishop count difference); bad bishop = has ≥2 own pawns on same-square-color'
    def square_color(sq):
        return (chess.square_file(sq) + chess.square_rank(sq)) & 1
    w_bishops = 0; b_bishops = 0
    w_bad = 0; b_bad = 0
    pawn_squares = {sq: pc for sq, pc in board.piece_map().items() if pc.piece_type == chess.PAWN}
    for sq, pc in board.piece_map().items():
        if pc.piece_type == chess.BISHOP:
            col = square_color(sq)
            same_color_pawns = 0
            for psq, ppc in pawn_squares.items():
                if ppc.color == pc.color and square_color(psq) == col:
                    same_color_pawns += 1
            if pc.color == chess.WHITE:
                w_bishops += 1
                if same_color_pawns >= 2:
                    w_bad += 1
            else:
                b_bishops += 1
                if same_color_pawns >= 2:
                    b_bad += 1
    pair_diff = (1.0 if w_bishops >= 2 else 0.0) - (1.0 if b_bishops >= 2 else 0.0)
    bad_diff = float(w_bad - b_bad)
    return float(pair_diff - 0.5 * bad_diff)

def feature(board: chess.Board) -> float:
    'Difference in number of undefended non-king pieces (attacked by opponent and not defended by own pieces): White - Black'
    white_undef = 0
    black_undef = 0
    for sq, pc in board.piece_map().items():
        if pc.piece_type == chess.KING:
            continue
        own = pc.color
        opp = not own
        if board.is_attacked_by(opp, sq) and not board.is_attacked_by(own, sq):
            if own == chess.WHITE:
                white_undef += 1
            else:
                black_undef += 1
    return float(white_undef - black_undef)

def feature(board: chess.Board) -> float:
    'Count difference of pieces (excluding kings) that are pinned to their king: White - Black'
    white_pinned = 0
    black_pinned = 0
    # Use board.is_pinned if available; fallback to 0 if not
    is_pinned = getattr(board, 'is_pinned', None)
    if is_pinned is None:
        # conservative fallback: no pins detected
        return 0.0
    for sq, pc in board.piece_map().items():
        if pc.piece_type == chess.KING:
            continue
        try:
            if board.is_pinned(pc.color, sq):
                if pc.color == chess.WHITE:
                    white_pinned += 1
                else:
                    black_pinned += 1
        except Exception:
            continue
    return float(white_pinned - black_pinned)

def feature(board: chess.Board) -> float:
    'Difference in number of rooks occupying the opponent seventh rank (White rooks on rank 7, Black rooks on rank 2): White - Black'
    white_seventh = 0
    black_seventh = 0
    for sq, pc in board.piece_map().items():
        if pc.piece_type == chess.ROOK:
            r = chess.square_rank(sq)
            if pc.color == chess.WHITE and r == 6:
                white_seventh += 1
            if pc.color == chess.BLACK and r == 1:
                black_seventh += 1
    return float(white_seventh - black_seventh)

def feature(board: chess.Board) -> float:
    'Pawn shelter strength difference in front of each king: count of friendly pawns in king-adjacent files and 1-2 ranks forward (White - Black)'
    def shelter_for(king_color):
        kingsq = None
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.KING and pc.color == king_color:
                kingsq = sq
                break
        if kingsq is None:
            return 0.0
        kf = chess.square_file(kingsq); kr = chess.square_rank(kingsq)
        cnt = 0
        if king_color == chess.WHITE:
            ranks = [kr+1, kr+2]
        else:
            ranks = [kr-1, kr-2]
        for df in (-1, 0, 1):
            for r in ranks:
                f = kf + df
                if 0 <= f <= 7 and 0 <= r <= 7:
                    sq = chess.square(f, r)
                    pc = board.piece_at(sq)
                    if pc and pc.piece_type == chess.PAWN and pc.color == king_color:
                        cnt += 1
        return float(cnt)
    try:
        return float(shelter_for(chess.WHITE) - shelter_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in heavy-piece (rook+queen) mobility measured by legal moves for those pieces: (White moves - Black moves) normalized by 10'
    white_mov = 0
    black_mov = 0
    # count legal moves that are from a rook or queen square
    try:
        for mv in board.legal_moves:
            from_sq = mv.from_square
            pc = board.piece_at(from_sq)
            if pc and pc.piece_type in (chess.ROOK, chess.QUEEN):
                if pc.color == chess.WHITE:
                    white_mov += 1
                else:
                    black_mov += 1
        # For opponent side, evaluate by copying board and flipping turn
        try:
            copy = board.copy()
        except Exception:
            copy = chess.Board(board.fen())
        copy.turn = not board.turn
        opp_white_mov = 0
        opp_black_mov = 0
        for mv in copy.legal_moves:
            from_sq = mv.from_square
            pc = copy.piece_at(from_sq)
            if pc and pc.piece_type in (chess.ROOK, chess.QUEEN):
                if pc.color == chess.WHITE:
                    opp_white_mov += 1
                else:
                    opp_black_mov += 1
        # Now determine totals for each color regardless of who to move.
        total_white = white_mov if board.turn == chess.WHITE else opp_white_mov
        total_black = black_mov if board.turn == chess.BLACK else opp_black_mov
        return float((total_white - total_black) / 10.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn structure weakness metric: (pawn islands + doubled pawns count*0.7) difference (White - Black)'
    def pawn_structure(color):
        files_with_pawn = [0] * 8
        pawn_counts = [0] * 8
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.PAWN and pc.color == color:
                f = chess.square_file(sq)
                files_with_pawn[f] = 1
                pawn_counts[f] += 1
        islands = 0
        prev = 0
        for f in range(8):
            if files_with_pawn[f] and not prev:
                islands += 1
            prev = files_with_pawn[f]
        doubled = sum(max(0, cnt - 1) for cnt in pawn_counts)
        return float(islands + 0.7 * doubled)
    try:
        return float(pawn_structure(chess.WHITE) - pawn_structure(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net number of legal checking moves available for each side (White - Black): counts legal moves that deliver check'
    def checks_for(color):
        try:
            try:
                copy = board.copy()
            except Exception:
                copy = chess.Board(board.fen())
            copy.turn = color
            cnt = 0
            for mv in copy.legal_moves:
                try:
                    if copy.gives_check(mv):
                        cnt += 1
                except Exception:
                    # fallback: make the move and test for check
                    try:
                        c2 = copy.copy(stack=False)
                        c2.push(mv)
                        if c2.is_check():
                            cnt += 1
                    except Exception:
                        pass
            return cnt
        except Exception:
            return 0
    w = checks_for(chess.WHITE)
    b = checks_for(chess.BLACK)
    return float(w - b)

def feature(board: chess.Board) -> float:
    'King pawn shield difference: (white_shield_count - black_shield_count), counts friendly pawns in front/adjacent files of each king (0-6 range)'
    try:
        values = {chess.PAWN:1.0}
        def shield_count(color):
            king_sq = None
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == color:
                    king_sq = sq
                    break
            if king_sq is None:
                return 0.0
            file = chess.square_file(king_sq)
            rank = chess.square_rank(king_sq)
            cnt = 0
            # For white pawns, "in front" is + ranks; for black it's - ranks
            drs = [1, 2] if color == chess.WHITE else [-1, -2]
            for df in (-1, 0, 1):
                for dr in drs:
                    f = file + df
                    r = rank + dr
                    if 0 <= f < 8 and 0 <= r < 8:
                        sq = chess.square(f, r)
                        p = board.piece_at(sq)
                        if p is not None and p.piece_type == chess.PAWN and p.color == color:
                            cnt += 1
            return float(cnt)
        return float(shield_count(chess.WHITE) - shield_count(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Attacked material balance: (sum values of opponent pieces attacked by white) - (sum values attacked by black), returned in pawns (divide by 100)'
    try:
        values = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0, chess.KING:20000.0}
        sum_white = 0.0
        sum_black = 0.0
        for sq, p in board.piece_map().items():
            v = values.get(p.piece_type, 0.0)
            if p.color == chess.BLACK:
                if board.is_attacked_by(chess.WHITE, sq):
                    sum_white += v
            else:
                if board.is_attacked_by(chess.BLACK, sq):
                    sum_black += v
        return (sum_white - sum_black) / 100.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Immobile non-pawn non-king pieces difference: (white immobile pieces count - black immobile pieces count). A piece is immobile if it has zero legal moves.'
    try:
        immobile_w = 0
        immobile_b = 0
        piece_map = board.piece_map()
        for sq, p in piece_map.items():
            if p.piece_type in (chess.PAWN, chess.KING):
                continue
            # create a copy and set turn to the piece color to count legal moves for that piece
            b2 = board.copy()
            b2.turn = p.color
            has_move = False
            for m in b2.legal_moves:
                if m.from_square == sq:
                    has_move = True
                    break
            if not has_move:
                if p.color == chess.WHITE:
                    immobile_w += 1
                else:
                    immobile_b += 1
        return float(immobile_w - immobile_b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rooks on opponent seventh/second rank: (white_rooks_on_7th - black_rooks_on_2nd). Good rooks on enemy rank raise value.'
    try:
        w = 0
        b = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                r = chess.square_rank(sq)
                if p.color == chess.WHITE and r == 6:  # white rook on 7th rank (rank index 6)
                    w += 1
                if p.color == chess.BLACK and r == 1:  # black rook on white 2nd rank (rank index 1)
                    b += 1
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King attack density difference: (black_king_exposure - white_king_exposure). Exposure sums unique enemy attackers to king+adjacent squares weighted by 1/(1+distance).'
    try:
        def exposure_for_king(king_color):
            king_sq = None
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == king_color:
                    king_sq = sq
                    break
            if king_sq is None:
                return 0.0
            enemy = not king_color
            seen_attackers = {}
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    f = kf + df
                    r = kr + dr
                    if 0 <= f < 8 and 0 <= r < 8:
                        sq = chess.square(f, r)
                        attackers = board.attackers(enemy, sq)
                        for a in attackers:
                            if a not in seen_attackers:
                                dist = chess.square_distance(a, king_sq)
                                seen_attackers[a] = 1.0 / (1.0 + dist)
            return sum(seen_attackers.values())
        white_exp = exposure_for_king(chess.WHITE)
        black_exp = exposure_for_king(chess.BLACK)
        # We return black_exposure - white_exposure so positive means black king is more exposed (good for white)
        return float(black_exp - white_exp)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Undefended material difference: sum of values of pieces that are attacked and not defended (white - black), returned in pawns'
    try:
        values = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0, chess.KING:20000.0}
        sum_w = 0.0
        sum_b = 0.0
        for sq, p in board.piece_map().items():
            v = values.get(p.piece_type, 0.0)
            if p.color == chess.WHITE:
                attacked = board.is_attacked_by(chess.BLACK, sq)
                defended = board.is_attacked_by(chess.WHITE, sq)
                if attacked and not defended:
                    sum_w += v
            else:
                attacked = board.is_attacked_by(chess.WHITE, sq)
                defended = board.is_attacked_by(chess.BLACK, sq)
                if attacked and not defended:
                    sum_b += v
        return (sum_w - sum_b) / 100.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Mobility-weighted material: sum over pieces of value * (1 + legal_moves/10) for white minus black, returned in pawns'
    try:
        values = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0, chess.KING:20000.0}
        sum_w = 0.0
        sum_b = 0.0
        for sq, p in board.piece_map().items():
            v = values.get(p.piece_type, 0.0)
            # count legal moves for that piece by making a temporary copy and setting turn
            b2 = board.copy()
            b2.turn = p.color
            mv_count = 0
            for m in b2.legal_moves:
                if m.from_square == sq:
                    mv_count += 1
            weight = 1.0 + (mv_count / 10.0)
            if p.color == chess.WHITE:
                sum_w += v * weight
            else:
                sum_b += v * weight
        return (sum_w - sum_b) / 100.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn island advantage: (black_pawn_islands - white_pawn_islands). Positive means white has fewer pawn islands (structural advantage).'
    try:
        def pawn_islands(color):
            files_with_pawn = [False] * 8
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.PAWN and p.color == color:
                    f = chess.square_file(sq)
                    files_with_pawn[f] = True
            islands = 0
            prev = False
            for f in range(8):
                if files_with_pawn[f] and not prev:
                    islands += 1
                prev = files_with_pawn[f]
            return islands
        wi = pawn_islands(chess.WHITE)
        bi = pawn_islands(chess.BLACK)
        return float(bi - wi)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Bishop pair indicator: +1 if white has bishop pair and black does not, -1 if black has bishop pair and white does not, else 0.'
    try:
        wb = 0
        bb = 0
        for p in board.piece_map().values():
            if p.piece_type == chess.BISHOP:
                if p.color == chess.WHITE:
                    wb += 1
                else:
                    bb += 1
        if wb >= 2 and bb < 2:
            return 1.0
        if bb >= 2 and wb < 2:
            return -1.0
        return 0.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Available checks difference: (white_checks_available - black_checks_available) where checks are legal moves that give immediate check'
    try:
        def checks_for(color):
            cnt = 0
            b2 = board.copy()
            b2.turn = color
            # iterate legal moves with this turn
            for m in list(b2.legal_moves):
                if m.from_square is None:
                    continue
                b3 = b2.copy()
                try:
                    b3.push(m)
                    if b3.is_check():
                        cnt += 1
                except Exception:
                    # illegal move in some exotic positions or push failure -> skip
                    continue
            return cnt
        return float(checks_for(chess.WHITE) - checks_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of rooks on open files (white minus black). An open file has no pawns of either color.'
    try:
        wpawn_files = set()
        bpawn_files = set()
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.PAWN:
                if pc.color == chess.WHITE:
                    wpawn_files.add(chess.square_file(sq))
                else:
                    bpawn_files.add(chess.square_file(sq))
        pawn_files = wpawn_files.union(bpawn_files)
        white_open_rooks = 0
        black_open_rooks = 0
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                if f not in pawn_files:
                    if pc.color == chess.WHITE:
                        white_open_rooks += 1
                    else:
                        black_open_rooks += 1
        return float(white_open_rooks - black_open_rooks)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in minimum promotion distance of passed pawns (black_min - white_min). Smaller means closer to queening.'
    try:
        pieces = board.piece_map()
        white_passed_min = 8
        black_passed_min = 8
        # helper: check if pawn at sq is passed relative to its color
        def is_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            pm = pieces
            if color == chess.WHITE:
                for sf in range(max(0, f - 1), min(7, f + 1) + 1):
                    for rr in range(r + 1, 8):
                        target = chess.square(sf, rr)
                        pc = pm.get(target)
                        if pc and pc.piece_type == chess.PAWN and pc.color == chess.BLACK:
                            return False
                return True
            else:
                for sf in range(max(0, f - 1), min(7, f + 1) + 1):
                    for rr in range(r - 1, -1, -1):
                        target = chess.square(sf, rr)
                        pc = pm.get(target)
                        if pc and pc.piece_type == chess.PAWN and pc.color == chess.WHITE:
                            return False
                return True
        for sq, pc in pieces.items():
            if pc.piece_type == chess.PAWN:
                r = chess.square_rank(sq)
                if pc.color == chess.WHITE and is_passed(sq, chess.WHITE):
                    dist = 7 - r
                    white_passed_min = min(white_passed_min, dist)
                if pc.color == chess.BLACK and is_passed(sq, chess.BLACK):
                    dist = r - 0
                    black_passed_min = min(black_passed_min, dist)
        # if no passed pawns min remains 8
        return float(black_passed_min - white_passed_min)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in immediate pawn-shield strength in front of the kings (white_shield - black_shield). Counts friendly pawns on the three front squares.'
    try:
        pieces = board.piece_map()
        white_shield = 0
        black_shield = 0
        for color in (chess.WHITE, chess.BLACK):
            king_sq = None
            for sq, pc in pieces.items():
                if pc.piece_type == chess.KING and pc.color == color:
                    king_sq = sq
                    break
            if king_sq is None:
                continue
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            if color == chess.WHITE:
                ranks = [kr + 1]
            else:
                ranks = [kr - 1]
            count = 0
            for rf in ranks:
                if 0 <= rf <= 7:
                    for ff in range(max(0, kf - 1), min(7, kf + 1) + 1):
                        sq = chess.square(ff, rf)
                        pc = pieces.get(sq)
                        if pc and pc.piece_type == chess.PAWN and pc.color == color:
                            count += 1
            if color == chess.WHITE:
                white_shield = count
            else:
                black_shield = count
        return float(white_shield - black_shield)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material value (in centipawns/100) of attacked-and-undefended pieces (white_total - black_total). Useful to spot hanging material.'
    try:
        val = {chess.PAWN: 100.0, chess.KNIGHT: 320.0, chess.BISHOP: 330.0, chess.ROOK: 500.0, chess.QUEEN: 900.0, chess.KING: 0.0}
        pieces = board.piece_map()
        white_bad = 0.0
        black_bad = 0.0
        for sq, pc in pieces.items():
            if pc.piece_type == chess.KING:
                continue
            opp = not pc.color
            # attacked by opponent?
            if board.is_attacked_by(opp, sq):
                # defended by own side?
                defenders = board.attackers(pc.color, sq)
                if len(defenders) == 0:
                    if pc.color == chess.WHITE:
                        white_bad += val.get(pc.piece_type, 0.0)
                    else:
                        black_bad += val.get(pc.piece_type, 0.0)
        # convert to pawn-equivalent units (divide by 100 to match prior features) or leave as centipawns?
        # Keep consistent with earlier material-in-pawn-units: return pawns (so divide by 100).
        return (white_bad - black_bad) / 100.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'White rooks on the 7th rank minus black rooks on the 2nd rank (common sign of dominance).'
    try:
        white_count = 0
        black_count = 0
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.ROOK:
                r = chess.square_rank(sq)
                if pc.color == chess.WHITE and r == 6:
                    white_count += 1
                if pc.color == chess.BLACK and r == 1:
                    black_count += 1
        return float(white_count - black_count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'If materially an endgame (few pieces), returns difference in king-to-center proximity (black_dist - white_dist). Otherwise 0.'
    try:
        pieces = board.piece_map()
        major_or_minor = 0
        for pc in pieces.values():
            if pc.piece_type in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
                major_or_minor += 1
        # treat as endgame when <= 4 non-king non-pawn pieces (both sides combined)
        if major_or_minor > 4:
            return 0.0
        center_sqs = [chess.parse_square(s) for s in ('d4', 'e4', 'd5', 'e5')]
        def king_center_dist(color):
            for sq, pc in pieces.items():
                if pc.piece_type == chess.KING and pc.color == color:
                    d = min(chess.square_distance(sq, c) for c in center_sqs)
                    return d
            return 8
        wd = king_center_dist(chess.WHITE)
        bd = king_center_dist(chess.BLACK)
        return float(bd - wd)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) of summed bishop diagonal mobility (number of empty/hostile squares along bishop rays until blocked).'
    try:
        pieces = board.piece_map()
        def bishop_mobility_from(sq):
            mobility = 0
            directions = [(1,1),(1,-1),(-1,1),(-1,-1)]
            rf = chess.square_file(sq)
            rr = chess.square_rank(sq)
            for df, dr in directions:
                f = rf + df
                r = rr + dr
                while 0 <= f <= 7 and 0 <= r <= 7:
                    target = chess.square(f, r)
                    pc = pieces.get(target)
                    mobility += 1
                    if pc is not None:
                        break
                    f += df
                    r += dr
            return mobility
        white_sum = 0
        black_sum = 0
        for sq, pc in pieces.items():
            if pc.piece_type == chess.BISHOP:
                if pc.color == chess.WHITE:
                    white_sum += bishop_mobility_from(sq)
                else:
                    black_sum += bishop_mobility_from(sq)
        # normalize by a typical diagonal mobility (max ~13)
        return float((white_sum - black_sum) / 10.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in inverse Manhattan distance from queens to the opposing king (white - black). Closer queen to enemy king is often stronger.'
    try:
        pieces = board.piece_map()
        wq_sq = None
        bq_sq = None
        wking = None
        bking = None
        for sq, pc in pieces.items():
            if pc.piece_type == chess.QUEEN:
                if pc.color == chess.WHITE:
                    wq_sq = sq
                else:
                    bq_sq = sq
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    wking = sq
                else:
                    bking = sq
        def invdist(a, b):
            if a is None or b is None:
                return 0.0
            d = chess.square_distance(a, b)
            return 1.0 / (1.0 + d)
        # white queen to black king minus black queen to white king
        return float(invdist(wq_sq, bking) - invdist(bq_sq, wking))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn island count difference (black islands - white islands). More islands usually means weaker pawn structure.'
    try:
        board_map = board.piece_map()
        def pawn_islands(color):
            files_with_pawn = [False]*8
            for sq, pc in board_map.items():
                if pc.piece_type == chess.PAWN and pc.color == color:
                    files_with_pawn[chess.square_file(sq)] = True
            islands = 0
            i = 0
            while i < 8:
                if files_with_pawn[i]:
                    islands += 1
                    while i < 8 and files_with_pawn[i]:
                        i += 1
                else:
                    i += 1
            return islands
        w_islands = pawn_islands(chess.WHITE)
        b_islands = pawn_islands(chess.BLACK)
        return float(b_islands - w_islands)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in attacking pressure on the squares adjacent to the king (white_pressure - black_pressure). Counts opponent attackers of king-neighborhood squares.'
    try:
        pieces = board.piece_map()
        def pressure_on_king(king_color):
            king_sq = None
            for sq, pc in pieces.items():
                if pc.piece_type == chess.KING and pc.color == king_color:
                    king_sq = sq
                    break
            if king_sq is None:
                return 0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            opp = not king_color
            pressure = 0
            for ff in range(max(0, kf - 1), min(7, kf + 1) + 1):
                for rr in range(max(0, kr - 1), min(7, kr + 1) + 1):
                    sq = chess.square(ff, rr)
                    # count distinct attackers (could be multiple pieces attacking same square)
                    pressure += len(board.attackers(opp, sq))
            return pressure
        white_on_white = pressure_on_king(chess.WHITE)  # black pressure on white king
        black_on_black = pressure_on_king(chess.BLACK)  # white pressure on black king
        # return white pressure on black king minus black pressure on white king
        return float(black_on_black - white_on_white)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) of pawns that can promote on the next move (pawn on 7th rank and has at least one legal promotion destination)'
    try:
        wm = 0
        bm = 0
        for sq, pc in board.piece_map().items():
            if pc.piece_type != chess.PAWN:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if pc.color == chess.WHITE:
                if r == 6:
                    # forward
                    forward = chess.square(f, 7)
                    can = False
                    if board.piece_at(forward) is None:
                        can = True
                    # capture promotions
                    for df in (-1, 1):
                        ff = f + df
                        if 0 <= ff <= 7:
                            cap_sq = chess.square(ff, 7)
                            occ = board.piece_at(cap_sq)
                            if occ is not None and occ.color == chess.BLACK:
                                can = True
                    if can:
                        wm += 1
            else:
                if r == 1:
                    forward = chess.square(f, 0)
                    can = False
                    if board.piece_at(forward) is None:
                        can = True
                    for df in (-1, 1):
                        ff = f + df
                        if 0 <= ff <= 7:
                            cap_sq = chess.square(ff, 0)
                            occ = board.piece_at(cap_sq)
                            if occ is not None and occ.color == chess.WHITE:
                                can = True
                    if can:
                        bm += 1
        return float(wm - bm)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) of the strongest passed pawn promotion margin: enemy king moves to promotion square minus pawn moves to promote (higher means pawn is more likely to promote before king arrives)'
    def is_passed(sq, color, pieces):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            for other_sq, other_pc in pieces.items():
                if other_pc.piece_type == chess.PAWN and other_pc.color == chess.BLACK:
                    of = chess.square_file(other_sq); orr = chess.square_rank(other_sq)
                    if abs(of - f) <= 1 and orr > r:
                        return False
            return True
        else:
            for other_sq, other_pc in pieces.items():
                if other_pc.piece_type == chess.PAWN and other_pc.color == chess.WHITE:
                    of = chess.square_file(other_sq); orr = chess.square_rank(other_sq)
                    if abs(of - f) <= 1 and orr < r:
                        return False
            return True
    try:
        pieces = board.piece_map()
        white_best = -999
        black_best = -999
        # find kings
        wk = bk = None
        for sq, pc in pieces.items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    wk = sq
                else:
                    bk = sq
        for sq, pc in pieces.items():
            if pc.piece_type != chess.PAWN:
                continue
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if not is_passed(sq, pc.color, pieces):
                continue
            if pc.color == chess.WHITE:
                to_rank = 7
                pawn_moves = 7 - r
                promo_sq = chess.square(f, 7)
                king_dist = chess.square_distance(bk, promo_sq) if bk is not None else 100
                margin = king_dist - pawn_moves
                if margin > white_best:
                    white_best = margin
            else:
                to_rank = 0
                pawn_moves = r - 0
                promo_sq = chess.square(f, 0)
                king_dist = chess.square_distance(wk, promo_sq) if wk is not None else 100
                margin = king_dist - pawn_moves
                if margin > black_best:
                    black_best = margin
        if white_best == -999:
            white_best = -100.0
        if black_best == -999:
            black_best = -100.0
        return float(white_best - black_best)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) of passed pawns whose promotion square is currently attacked by the opponent (vulnerable promotion squares)'
    try:
        pieces = board.piece_map()
        def is_passed(sq, color):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if color == chess.WHITE:
                for other_sq, other_pc in pieces.items():
                    if other_pc.piece_type == chess.PAWN and other_pc.color == chess.BLACK:
                        of = chess.square_file(other_sq); orr = chess.square_rank(other_sq)
                        if abs(of - f) <= 1 and orr > r:
                            return False
                return True
            else:
                for other_sq, other_pc in pieces.items():
                    if other_pc.piece_type == chess.PAWN and other_pc.color == chess.WHITE:
                        of = chess.square_file(other_sq); orr = chess.square_rank(other_sq)
                        if abs(of - f) <= 1 and orr < r:
                            return False
                return True
        w_vul = 0
        b_vul = 0
        for sq, pc in pieces.items():
            if pc.piece_type != chess.PAWN:
                continue
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if pc.color == chess.WHITE:
                if not is_passed(sq, chess.WHITE): 
                    continue
                promo = chess.square(f, 7)
                if board.is_attacked_by(chess.BLACK, promo):
                    w_vul += 1
            else:
                if not is_passed(sq, chess.BLACK):
                    continue
                promo = chess.square(f, 0)
                if board.is_attacked_by(chess.WHITE, promo):
                    b_vul += 1
        return float(w_vul - b_vul)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) of the number of rooks or queens that attack the promotion square of any passed pawn (how many major pieces can contest promotion)'
    try:
        pieces = board.piece_map()
        def is_passed(sq, color):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if color == chess.WHITE:
                for other_sq, other_pc in pieces.items():
                    if other_pc.piece_type == chess.PAWN and other_pc.color == chess.BLACK:
                        of = chess.square_file(other_sq); orr = chess.square_rank(other_sq)
                        if abs(of - f) <= 1 and orr > r:
                            return False
                return True
            else:
                for other_sq, other_pc in pieces.items():
                    if other_pc.piece_type == chess.PAWN and other_pc.color == chess.WHITE:
                        of = chess.square_file(other_sq); orr = chess.square_rank(other_sq)
                        if abs(of - f) <= 1 and orr < r:
                            return False
                return True
        w_count = 0
        b_count = 0
        for sq, pc in pieces.items():
            if pc.piece_type != chess.PAWN:
                continue
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if pc.color == chess.WHITE and is_passed(sq, chess.WHITE):
                promo = chess.square(f, 7)
                # count enemy rooks/queens attacking promo square
                attackers = board.attackers(chess.BLACK, promo)
                for a in attackers:
                    ap = pieces.get(a)
                    if ap is not None and (ap.piece_type == chess.ROOK or ap.piece_type == chess.QUEEN):
                        w_count += 1
                # cap to not double count multiple attackers of same promo
            if pc.color == chess.BLACK and is_passed(sq, chess.BLACK):
                promo = chess.square(f, 0)
                attackers = board.attackers(chess.WHITE, promo)
                for a in attackers:
                    ap = pieces.get(a)
                    if ap is not None and (ap.piece_type == chess.ROOK or ap.piece_type == chess.QUEEN):
                        b_count += 1
        return float(w_count - b_count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) of friendly rooks located on the same file as a passed pawn and behind it (supporting that pawn)'
    try:
        pieces = board.piece_map()
        def is_passed(sq, color):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if color == chess.WHITE:
                for other_sq, other_pc in pieces.items():
                    if other_pc.piece_type == chess.PAWN and other_pc.color == chess.BLACK:
                        of = chess.square_file(other_sq); orr = chess.square_rank(other_sq)
                        if abs(of - f) <= 1 and orr > r:
                            return False
                return True
            else:
                for other_sq, other_pc in pieces.items():
                    if other_pc.piece_type == chess.PAWN and other_pc.color == chess.WHITE:
                        of = chess.square_file(other_sq); orr = chess.square_rank(other_sq)
                        if abs(of - f) <= 1 and orr < r:
                            return False
                return True
        w_support = 0
        b_support = 0
        for sq, pc in pieces.items():
            if pc.piece_type != chess.PAWN:
                continue
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if pc.color == chess.WHITE and is_passed(sq, chess.WHITE):
                for osq, opc in pieces.items():
                    if opc.piece_type == chess.ROOK and opc.color == chess.WHITE:
                        of = chess.square_file(osq); orr = chess.square_rank(osq)
                        if of == f and orr < r:
                            w_support += 1
            if pc.color == chess.BLACK and is_passed(sq, chess.BLACK):
                for osq, opc in pieces.items():
                    if opc.piece_type == chess.ROOK and opc.color == chess.BLACK:
                        of = chess.square_file(osq); orr = chess.square_rank(osq)
                        if of == f and orr > r:
                            b_support += 1
        return float(w_support - b_support)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) of rooks occupying open files (no pawns of either color on that file) — active rook potential'
    try:
        files_with_pawns = set()
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.PAWN:
                files_with_pawns.add(chess.square_file(sq))
        w_rooks = 0
        b_rooks = 0
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                if f not in files_with_pawns:
                    if pc.color == chess.WHITE:
                        w_rooks += 1
                    else:
                        b_rooks += 1
        return float(w_rooks - b_rooks)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) of pieces (non-pawn, non-king) that are within Manhattan distance 2 of the opponent king (king-zone pressure)'
    try:
        pieces = board.piece_map()
        wk = bk = None
        for sq, pc in pieces.items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    wk = sq
                else:
                    bk = sq
        w_pressure = 0
        b_pressure = 0
        for sq, pc in pieces.items():
            if pc.piece_type in (chess.PAWN, chess.KING):
                continue
            if pc.color == chess.WHITE and bk is not None:
                if chess.square_distance(sq, bk) <= 2:
                    w_pressure += 1
            if pc.color == chess.BLACK and wk is not None:
                if chess.square_distance(sq, wk) <= 2:
                    b_pressure += 1
        return float(w_pressure - b_pressure)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) of isolated passed pawns (passed pawn with no friendly pawns on adjacent files)'
    try:
        pieces = board.piece_map()
        def is_passed_and_isolated(sq, color):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            # passed?
            if color == chess.WHITE:
                for osq, opc in pieces.items():
                    if opc.piece_type == chess.PAWN and opc.color == chess.BLACK:
                        of = chess.square_file(osq); orr = chess.square_rank(osq)
                        if abs(of - f) <= 1 and orr > r:
                            return False
            else:
                for osq, opc in pieces.items():
                    if opc.piece_type == chess.PAWN and opc.color == chess.WHITE:
                        of = chess.square_file(osq); orr = chess.square_rank(osq)
                        if abs(of - f) <= 1 and orr < r:
                            return False
            # isolated: no friendly pawns on adjacent files
            for osq, opc in pieces.items():
                if opc.piece_type == chess.PAWN and opc.color == color:
                    of = chess.square_file(osq)
                    if abs(of - f) == 1:
                        return False
            return True
        w_iso = 0
        b_iso = 0
        for sq, pc in pieces.items():
            if pc.piece_type != chess.PAWN:
                continue
            if pc.color == chess.WHITE:
                if is_passed_and_isolated(sq, chess.WHITE):
                    w_iso += 1
            else:
                if is_passed_and_isolated(sq, chess.BLACK):
                    b_iso += 1
        return float(w_iso - b_iso)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) of connected passed pawn pairs (number of adjacent-file passed pawn pairs supporting each other)'
    try:
        pieces = board.piece_map()
        def is_passed(sq, color):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if color == chess.WHITE:
                for osq, opc in pieces.items():
                    if opc.piece_type == chess.PAWN and opc.color == chess.BLACK:
                        of = chess.square_file(osq); orr = chess.square_rank(osq)
                        if abs(of - f) <= 1 and orr > r:
                            return False
                return True
            else:
                for osq, opc in pieces.items():
                    if opc.piece_type == chess.PAWN and opc.color == chess.WHITE:
                        of = chess.square_file(osq); orr = chess.square_rank(osq)
                        if abs(of - f) <= 1 and orr < r:
                            return False
                return True
        wp_set = set()
        bp_set = set()
        for sq, pc in pieces.items():
            if pc.piece_type == chess.PAWN:
                if pc.color == chess.WHITE and is_passed(sq, chess.WHITE):
                    wp_set.add(chess.square_file(sq))
                if pc.color == chess.BLACK and is_passed(sq, chess.BLACK):
                    bp_set.add(chess.square_file(sq))
        w_pairs = 0
        b_pairs = 0
        for f in range(7):
            if f in wp_set and (f+1) in wp_set:
                w_pairs += 1
            if f in bp_set and (f+1) in bp_set:
                b_pairs += 1
        return float(w_pairs - b_pairs)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) in number of rooks occupying open files (a file with no pawns of either color)'
    piece_map = board.piece_map()
    # Determine which files are open (no pawns)
    pawn_files = set()
    for sq, p in piece_map.items():
        if p.piece_type == chess.PAWN:
            pawn_files.add(chess.square_file(sq))
    white_open_rooks = 0
    black_open_rooks = 0
    for sq, p in piece_map.items():
        if p.piece_type == chess.ROOK:
            if chess.square_file(sq) not in pawn_files:
                if p.color == chess.WHITE:
                    white_open_rooks += 1
                else:
                    black_open_rooks += 1
    return float(white_open_rooks - black_open_rooks)

def feature(board: chess.Board) -> float:
    'Difference (white - black) in heavy-piece (rook/queen) pressure on the opponent king rank (counts attackers on each square of the king rank)'
    piece_map = board.piece_map()
    # Find kings
    white_king_sq = None
    black_king_sq = None
    for sq, p in piece_map.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                white_king_sq = sq
            else:
                black_king_sq = sq
    def heavy_pressure_on_rank(king_sq, attacker_color):
        if king_sq is None:
            return 0
        rank = chess.square_rank(king_sq)
        pressure = 0
        for f in range(8):
            sq = chess.square(f, rank)
            attackers = board.attackers(attacker_color, sq)
            for a in attackers:
                ap = piece_map.get(a)
                if ap is not None and (ap.piece_type == chess.ROOK or ap.piece_type == chess.QUEEN):
                    pressure += 1
        return pressure
    white_pressure_on_black = heavy_pressure_on_rank(black_king_sq, chess.WHITE)
    black_pressure_on_white = heavy_pressure_on_rank(white_king_sq, chess.BLACK)
    return float(white_pressure_on_black - black_pressure_on_white)

def feature(board: chess.Board) -> float:
    'Difference (white - black) of a passed-pawn danger score: advanced passed pawns that are far from opposing pieces score higher'
    piece_map = board.piece_map()
    def passed_pawns_score(color):
        score = 0.0
        opp = not color
        # gather opponent pawns positions for quick checks
        opp_pawn_squares = [sq for sq, p in piece_map.items() if p.piece_type == chess.PAWN and p.color == opp]
        opp_piece_squares = [sq for sq, p in piece_map.items() if p.color == opp and p.piece_type != chess.KING]
        for sq, p in piece_map.items():
            if p.piece_type != chess.PAWN or p.color != color:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            is_passed = True
            if color == chess.WHITE:
                for ff in range(max(0, f-1), min(7, f+1)+1):
                    for rr in range(r+1, 8):
                        check_sq = chess.square(ff, rr)
                        if check_sq in opp_pawn_squares:
                            is_passed = False
                            break
                    if not is_passed:
                        break
            else:
                for ff in range(max(0, f-1), min(7, f+1)+1):
                    for rr in range(0, r):
                        check_sq = chess.square(ff, rr)
                        if check_sq in opp_pawn_squares:
                            is_passed = False
                            break
                    if not is_passed:
                        break
            if not is_passed:
                continue
            # advancement: normalized 0..1
            advancement = (r / 7.0) if color == chess.WHITE else ((7 - r) / 7.0)
            # min distance to nearest opposing piece (excluding king); if none, set to 7
            if opp_piece_squares:
                min_dist = min(chess.square_distance(sq, o) for o in opp_piece_squares)
            else:
                min_dist = 7
            # score grows with advancement and with distance (farther from blockers better)
            pawn_score = advancement * (1.0 + (min_dist / 7.0))
            score += pawn_score
        return score
    return float(passed_pawns_score(chess.WHITE) - passed_pawns_score(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Difference (white - black) of the summed number of opponent attackers on the 3x3 neighborhood around each king (higher means king is under more local attack)'
    piece_map = board.piece_map()
    white_king = None
    black_king = None
    for sq, p in piece_map.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                white_king = sq
            else:
                black_king = sq
    def neighborhood_attack_sum(king_sq, attacker_color):
        if king_sq is None:
            return 0.0
        kf = chess.square_file(king_sq)
        kr = chess.square_rank(king_sq)
        s = 0
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                f = kf + df
                r = kr + dr
                if 0 <= f <= 7 and 0 <= r <= 7:
                    sq = chess.square(f, r)
                    s += len(board.attackers(attacker_color, sq))
        return float(s)
    white_under_attack = neighborhood_attack_sum(white_king, chess.BLACK)
    black_under_attack = neighborhood_attack_sum(black_king, chess.WHITE)
    # Return white minus black: positive means White's king neighborhood is more attacked (worse for White)
    # We invert sign so positive means advantage for White (less attacked)
    return float(black_under_attack - white_under_attack)

def feature(board: chess.Board) -> float:
    'Difference (white - black) in number of rooks occupying the opponent seventh rank (very valuable for invasion)'
    piece_map = board.piece_map()
    white_count = 0
    black_count = 0
    for sq, p in piece_map.items():
        if p.piece_type == chess.ROOK:
            rank = chess.square_rank(sq)
            if p.color == chess.WHITE and rank == 6:  # White rook on Black's 7th rank
                white_count += 1
            if p.color == chess.BLACK and rank == 1:  # Black rook on White's 7th rank
                black_count += 1
    return float(white_count - black_count)

def feature(board: chess.Board) -> float:
    'Difference (white - black) in queen centralization: (4 - Manhattan distance to nearest central square), averaged so closer to center is higher'
    centers = [chess.parse_square(n) for n in ('d4', 'e4', 'd5', 'e5')]
    piece_map = board.piece_map()
    def queen_central_score(color):
        qs = [sq for sq, p in piece_map.items() if p.piece_type == chess.QUEEN and p.color == color]
        if not qs:
            return 0.0
        best = 0.0
        for q in qs:
            min_dist = min(chess.square_distance(q, c) for c in centers)
            # transform to a small positive score where 4 is center-proximity baseline
            score = max(0.0, 4.0 - float(min_dist))
            if score > best:
                best = score
        return best
    return float(queen_central_score(chess.WHITE) - queen_central_score(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Difference (white - black) in number of knights on "outpost" squares: knight not attacked by an enemy pawn and occupying an advanced rank (>=4 for White, <=3 for Black)'
    piece_map = board.piece_map()
    def is_attacked_by_pawn(square, by_color):
        # Pawn attack origins: for a target square, pawns of by_color would be on specific source squares
        r = chess.square_rank(square)
        f = chess.square_file(square)
        if by_color == chess.WHITE:
            sources = []
            if r + 1 <= 7:
                if f - 1 >= 0:
                    sources.append(chess.square(f-1, r+1))
                if f + 1 <= 7:
                    sources.append(chess.square(f+1, r+1))
        else:
            sources = []
            if r - 1 >= 0:
                if f - 1 >= 0:
                    sources.append(chess.square(f-1, r-1))
                if f + 1 <= 7:
                    sources.append(chess.square(f+1, r-1))
        for s in sources:
            p = piece_map.get(s)
            if p is not None and p.piece_type == chess.PAWN and p.color == by_color:
                return True
        return False
    white_outposts = 0
    black_outposts = 0
    for sq, p in piece_map.items():
        if p.piece_type != chess.KNIGHT:
            continue
        r = chess.square_rank(sq)
        if p.color == chess.WHITE:
            if r >= 3 and not is_attacked_by_pawn(sq, chess.BLACK):
                white_outposts += 1
        else:
            if r <= 4 and not is_attacked_by_pawn(sq, chess.WHITE):
                black_outposts += 1
    return float(white_outposts - black_outposts)

def feature(board: chess.Board) -> float:
    'Difference (white - black) in number of pawn islands (contiguous files with pawns); fewer islands is generally better'
    piece_map = board.piece_map()
    def pawn_islands(color):
        has_pawn_on_file = [False] * 8
        for sq, p in piece_map.items():
            if p.piece_type == chess.PAWN and p.color == color:
                has_pawn_on_file[chess.square_file(sq)] = True
        islands = 0
        i = 0
        while i < 8:
            if has_pawn_on_file[i]:
                islands += 1
                while i < 8 and has_pawn_on_file[i]:
                    i += 1
            else:
                i += 1
        return islands
    return float(pawn_islands(chess.WHITE) - pawn_islands(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Difference (white - black) in average bishop mobility (number of squares each bishop attacks/can influence); higher is better'
    piece_map = board.piece_map()
    # For each bishop, count target squares t such that this bishop is one of the attackers of t
    def bishop_mobility_avg(color):
        bishop_sqs = [sq for sq, p in piece_map.items() if p.piece_type == chess.BISHOP and p.color == color]
        if not bishop_sqs:
            return 0.0
        mob_sum = 0.0
        # For each potential target square, see which bishops attack it by checking board.attackers
        for b_sq in bishop_sqs:
            count = 0
            for t in range(64):
                attackers = board.attackers(color, t)
                if b_sq in attackers:
                    count += 1
            mob_sum += count
        return mob_sum / len(bishop_sqs)
    return float(bishop_mobility_avg(chess.WHITE) - bishop_mobility_avg(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Difference (white - black) in weighted central pawn presence: pawns on files c,d,e,f weighted by advancement toward center (advanced = more weight)'
    piece_map = board.piece_map()
    central_files = {2, 3, 4, 5}  # c,d,e,f -> files 2..5
    white_score = 0.0
    black_score = 0.0
    for sq, p in piece_map.items():
        if p.piece_type != chess.PAWN:
            continue
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if f not in central_files:
            continue
        if p.color == chess.WHITE:
            weight = (r / 7.0)  # more advanced pawns count more
            white_score += weight
        else:
            weight = ((7 - r) / 7.0)
            black_score += weight
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Difference in non-pawn attacker pressure in the 3x3 vicinity around each king (white - black)'
    try:
        pm = board.piece_map()
        # find kings
        white_king_sq = next((sq for sq,p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king_sq = next((sq for sq,p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        def vicinity_attacker_count(king_sq, attacker_color):
            if king_sq is None:
                return 0
            kr = chess.square_rank(king_sq)
            kf = chess.square_file(king_sq)
            cnt = 0
            for dr in (-1,0,1):
                for df in (-1,0,1):
                    r = kr + dr
                    f = kf + df
                    if 0 <= r < 8 and 0 <= f < 8:
                        sq = f + 8*r
                        attackers = board.attackers(attacker_color, sq)
                        for a in attackers:
                            p = board.piece_at(a)
                            if p is not None and p.piece_type != chess.PAWN:
                                cnt += 1
            return cnt
        white_pressure = vicinity_attacker_count(black_king_sq, chess.WHITE)  # white attacking around black king
        black_pressure = vicinity_attacker_count(white_king_sq, chess.BLACK)  # black attacking around white king
        return float(white_pressure - black_pressure)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in heavy-piece (rook/queen) control of open or semi-open files (white - black); open=1, semi-open=0.5'
    try:
        def file_pawn_presence(file):
            # returns (has_white_pawn, has_black_pawn)
            wp = bp = False
            for r in range(8):
                sq = file + 8*r
                p = board.piece_at(sq)
                if p is not None and p.piece_type == chess.PAWN:
                    if p.color == chess.WHITE:
                        wp = True
                    else:
                        bp = True
            return wp, bp
        score = {chess.WHITE:0.0, chess.BLACK:0.0}
        for sq,p in board.piece_map().items():
            if p.piece_type in (chess.ROOK, chess.QUEEN):
                f = chess.square_file(sq)
                wp,bp = file_pawn_presence(f)
                if not wp and not bp:
                    val = 1.0
                elif p.color == chess.WHITE and not wp:
                    val = 0.5
                elif p.color == chess.BLACK and not bp:
                    val = 0.5
                else:
                    val = 0.0
                score[p.color] += val
        return float(score[chess.WHITE] - score[chess.BLACK])
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in nearby pawn shield counts for kings: number of friendly pawns within manhattan distance <=2 (white - black)'
    try:
        pm = board.piece_map()
        def pawn_shield(color):
            king_sq = next((sq for sq,p in pm.items() if p.piece_type == chess.KING and p.color == color), None)
            if king_sq is None:
                return 0
            cnt = 0
            for sq,p in pm.items():
                if p.piece_type == chess.PAWN and p.color == color:
                    if chess.square_distance(sq, king_sq) <= 2:
                        cnt += 1
            return cnt
        return float(pawn_shield(chess.WHITE) - pawn_shield(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of non-pawn non-king pieces that are more attacked than defended (vulnerable pieces) (white - black)'
    try:
        pm = board.piece_map()
        vulnerable = {chess.WHITE:0, chess.BLACK:0}
        for sq,p in pm.items():
            if p.piece_type == chess.KING or p.piece_type == chess.PAWN:
                continue
            attackers = len(board.attackers(not p.color, sq))
            defenders = len(board.attackers(p.color, sq))
            if attackers > defenders:
                vulnerable[p.color] += 1
        return float(vulnerable[chess.WHITE] - vulnerable[chess.BLACK])
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of rooks on the opponent\'s seventh rank (white rooks on rank 7, black rooks on rank 2) (white - black)'
    try:
        w = b = 0
        for sq,p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                r = chess.square_rank(sq)
                if p.color == chess.WHITE and r == 6:  # white on 7th rank (rank index 6)
                    w += 1
                if p.color == chess.BLACK and r == 1:  # black on 2nd rank (rank index 1)
                    b += 1
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in total squares attacked by bishops (approximate bishop mobility by scanning diagonals) (white - black)'
    try:
        # diagonal directions: (df, dr)
        dirs = ((1,1),(1,-1),(-1,1),(-1,-1))
        bishop_mob = {chess.WHITE:0, chess.BLACK:0}
        for sq,p in board.piece_map().items():
            if p.piece_type != chess.BISHOP:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            count = 0
            for df,dr in dirs:
                nf, nr = f+df, r+dr
                while 0 <= nf < 8 and 0 <= nr < 8:
                    nsq = nf + 8*nr
                    count += 1
                    if board.piece_at(nsq) is not None:
                        break
                    nf += df
                    nr += dr
            bishop_mob[p.color] += count
        return float(bishop_mob[chess.WHITE] - bishop_mob[chess.BLACK])
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Centralization difference for non-pawn non-king pieces: closeness to the 4 central squares summed (white - black)'
    try:
        center_sqs = [ (3 + 8*3), (4 + 8*3), (3 + 8*4), (4 + 8*4) ]  # d4,e4,d5,e5
        def closeness(sq):
            # smaller distance => larger closeness; map distance 0..7 to score 4-dist
            dist = min(chess.square_distance(sq, csq) for csq in center_sqs)
            return max(0, 4 - dist)
        score = {chess.WHITE:0.0, chess.BLACK:0.0}
        for sq,p in board.piece_map().items():
            if p.piece_type in (chess.PAWN, chess.KING):
                continue
            score[p.color] += closeness(sq)
        return float(score[chess.WHITE] - score[chess.BLACK])
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in pawn structure weakness penalty (doubled, isolated, backward) where higher is better for white (white - black)'
    try:
        pm = board.piece_map()
        # collect pawn files and ranks
        pawns_by_color_file = {chess.WHITE: {f:[] for f in range(8)}, chess.BLACK: {f:[] for f in range(8)}}
        for sq,p in pm.items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                pawns_by_color_file[p.color][f].append(r)
        penalties = {chess.WHITE:0.0, chess.BLACK:0.0}
        for color in (chess.WHITE, chess.BLACK):
            for f in range(8):
                ranks = pawns_by_color_file[color][f]
                if not ranks:
                    continue
                # doubled
                if len(ranks) > 1:
                    penalties[color] += 0.5 * (len(ranks) - 1)
                for r in ranks:
                    # isolated: no friendly pawn on adjacent files
                    adj_has = False
                    for af in (f-1, f+1):
                        if 0 <= af < 8 and len(pawns_by_color_file[color][af]) > 0:
                            adj_has = True
                    if not adj_has:
                        penalties[color] += 0.7
                    # backward: no friendly pawn on adjacent files behind this pawn (for white behind means lower rank, for black behind means higher rank)
                    behind_found = False
                    if color == chess.WHITE:
                        for af in (f-1,f+1):
                            if 0 <= af < 8:
                                for ar in pawns_by_color_file[color][af]:
                                    if ar < r:
                                        behind_found = True
                                        break
                            if behind_found:
                                break
                    else:
                        for af in (f-1,f+1):
                            if 0 <= af < 8:
                                for ar in pawns_by_color_file[color][af]:
                                    if ar > r:
                                        behind_found = True
                                        break
                            if behind_found:
                                break
                    if not behind_found:
                        penalties[color] += 0.6
        # produce score where less penalty is better -> invert penalties
        score_white = -penalties[chess.WHITE]
        score_black = -penalties[chess.BLACK]
        return float(score_white - score_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Endgame king activity bonus difference: if material is low, reward king closeness to center (white - black)'
    try:
        # estimate material as sum of non-king piece values
        vals = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900}
        total_nonking = 0
        for p in board.piece_map().values():
            if p.piece_type != chess.KING:
                total_nonking += vals.get(p.piece_type,0)
        # only apply when simplified (few pieces)
        if total_nonking > 1500:  # fairly non-endgame
            return 0.0
        center_sqs = [ (3 + 8*3), (4 + 8*3), (3 + 8*4), (4 + 8*4) ]
        pm = board.piece_map()
        def king_center_bonus(color):
            king_sq = next((sq for sq,p in pm.items() if p.piece_type == chess.KING and p.color == color), None)
            if king_sq is None:
                return 0.0
            dist = min(chess.square_distance(king_sq, csq) for csq in center_sqs)
            # normalize: dist 0 -> 1.0, dist 7 -> 0.0
            return max(0.0, (4 - dist) / 4.0)
        return float(king_center_bonus(chess.WHITE) - king_center_bonus(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in total value of pieces that are more attacked than defended (sum of piece values * (attackers-defenders)) (white - black), higher means white has more vulnerable material'
    try:
        vals = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        vuln_value = {chess.WHITE:0.0, chess.BLACK:0.0}
        pm = board.piece_map()
        for sq,p in pm.items():
            if p.piece_type == chess.KING:
                continue
            attackers = len(board.attackers(not p.color, sq))
            defenders = len(board.attackers(p.color, sq))
            if attackers > defenders:
                weight = float(attackers - defenders)
                vuln_value[p.color] += vals.get(p.piece_type,0) * weight / 100.0  # convert to pawn-equivalents
        return float(vuln_value[chess.WHITE] - vuln_value[chess.BLACK])
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in number of unique attackers that attack any square in the opponent king ring (adjacent 8 squares).'
    try:
        pm = board.piece_map()
        # find kings
        white_king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        if white_king_sq is None or black_king_sq is None:
            return 0.0
        def ring_squares(ksq):
            kf = chess.square_file(ksq); kr = chess.square_rank(ksq)
            res = []
            for df in (-1,0,1):
                for dr in (-1,0,1):
                    if df==0 and dr==0: continue
                    nf, nr = kf+df, kr+dr
                    if 0 <= nf <=7 and 0 <= nr <=7:
                        res.append(chess.square(nf,nr))
            return res
        white_attackers = set()
        black_attackers = set()
        for sq in ring_squares(black_king_sq):
            at = board.attackers(chess.WHITE, sq)
            white_attackers |= set(at)
        for sq in ring_squares(white_king_sq):
            at = board.attackers(chess.BLACK, sq)
            black_attackers |= set(at)
        # normalized by max possible (16)
        return float(len(white_attackers) - len(black_attackers))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of closest queen proximity to the enemy king expressed as (1 - normalized distance), higher = closer.'
    try:
        pm = board.piece_map()
        def closest_queen_to_king_distance(color):
            king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==color), None)
            if king_sq is None:
                return None
            enemy_color = not color
            queen_sqs = [sq for sq,p in pm.items() if p.piece_type==chess.QUEEN and p.color==enemy_color]
            if not queen_sqs:
                return None
            dists = [chess.square_distance(q, king_sq) for q in queen_sqs]
            return min(dists)
        wd = closest_queen_to_king_distance(chess.WHITE)
        bd = closest_queen_to_king_distance(chess.BLACK)
        def score(d):
            if d is None:
                return 0.0
            return max(0.0, 1.0 - (d / 8.0))
        return float(score(wd) - score(bd))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) counting rooks that sit on the opponent seventh rank or on an open file (no pawns of either color); weighted (7th rank=1.2, open file=1.0).'
    try:
        pm = board.piece_map()
        # precompute files that have any pawn
        pawn_files = set()
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                pawn_files.add(chess.square_file(sq))
        def score_for_color(color):
            s = 0.0
            for sq, p in pm.items():
                if p.color != color or p.piece_type != chess.ROOK:
                    continue
                rank = chess.square_rank(sq)
                file = chess.square_file(sq)
                # opponent's seventh rank: for white attacker this is rank 6, for black attacker rank 1
                target_seventh = 6 if color == chess.WHITE else 1
                if rank == target_seventh:
                    s += 1.2
                # open file
                if file not in pawn_files:
                    s += 1.0
            return s
        return float(score_for_color(chess.WHITE) - score_for_color(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in the number of distinct pieces directly attacking the enemy king square (attackers on the king square).'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.WHITE), None)
        black_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.BLACK), None)
        if white_king_sq is None or black_king_sq is None:
            return 0.0
        white_attack_on_black = len(board.attackers(chess.WHITE, black_king_sq))
        black_attack_on_white = len(board.attackers(chess.BLACK, white_king_sq))
        return float(white_attack_on_black - black_attack_on_white)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White_missing - Black_missing) in pawn shield pieces adjacent to each king. Counts missing pawns on the three typical shield squares in front of the king (0..3).'
    try:
        pm = board.piece_map()
        def shield_missing(color):
            king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==color), None)
            if king_sq is None:
                return 3.0
            kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
            # pawn direction: white pawns toward increasing rank, black toward decreasing
            dr = 1 if color == chess.WHITE else -1
            missing = 0
            for df in (-1,0,1):
                nf, nr = kf + df, kr + dr
                if not (0 <= nf <= 7 and 0 <= nr <= 7):
                    missing += 1
                else:
                    sq = chess.square(nf, nr)
                    p = board.piece_at(sq)
                    if p is None or p.piece_type != chess.PAWN or p.color != color:
                        missing += 1
            return float(missing)
        return float(shield_missing(chess.WHITE) - shield_missing(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in number of legal king moves to squares not attacked by the opponent (approximate king mobility/safety).'
    try:
        pm = board.piece_map()
        def safe_king_moves(color):
            king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==color), None)
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
            opp = not color
            safe = 0
            for df in (-1,0,1):
                for dr in (-1,0,1):
                    if df == 0 and dr == 0: continue
                    nf, nr = kf + df, kr + dr
                    if not (0 <= nf <= 7 and 0 <= nr <= 7): continue
                    sq = chess.square(nf, nr)
                    occ = board.piece_at(sq)
                    if occ is not None and occ.color == color:
                        continue
                    # square should not be attacked by opponent
                    try:
                        if board.is_attacked_by(opp, sq):
                            continue
                    except Exception:
                        pass
                    safe += 1
            return float(safe)
        return float(safe_king_moves(chess.WHITE) - safe_king_moves(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) representing inverted average Chebyshev distance of non-pawn non-king pieces to the enemy king (higher = attacking pieces are on average closer).'
    try:
        pm = board.piece_map()
        def avg_inv_dist(color):
            enemy_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color!=color), None)
            if enemy_king_sq is None:
                return 0.0
            dists = []
            for sq, p in pm.items():
                if p.color == color and p.piece_type not in (chess.PAWN, chess.KING):
                    d = chess.square_distance(sq, enemy_king_sq)
                    dists.append(d)
            if not dists:
                return 0.0
            avg = sum(dists)/len(dists)
            return max(0.0, 1.0 - (avg / 8.0))
        return float(avg_inv_dist(chess.WHITE) - avg_inv_dist(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in heavy pieces (rook/queen) sitting on the opponent back rank (white attacking rank 7, black attacking rank 0).'
    try:
        pm = board.piece_map()
        def heavy_on_backrank(color):
            target_rank = 7 if color == chess.WHITE else 0
            cnt = 0
            for sq, p in pm.items():
                if p.color == color and p.piece_type in (chess.ROOK, chess.QUEEN):
                    if chess.square_rank(sq) == target_rank:
                        cnt += 1
            return float(cnt)
        return float(heavy_on_backrank(chess.WHITE) - heavy_on_backrank(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in king-zone domination: fraction of squares within Chebyshev distance 2 of the king that are attacked by the enemy (higher = more dominated by attacker).'
    try:
        pm = board.piece_map()
        def zone_attack_fraction(color):
            king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==color), None)
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
            opp = not color
            zone = []
            for df in range(-2,3):
                for dr in range(-2,3):
                    nf, nr = kf+df, kr+dr
                    if not (0 <= nf <= 7 and 0 <= nr <= 7):
                        continue
                    zone.append(chess.square(nf,nr))
            if not zone:
                return 0.0
            attacked = 0
            for sq in zone:
                if board.is_attacked_by(opp, sq):
                    attacked += 1
            return float(attacked) / float(len(zone))
        return float(zone_attack_fraction(chess.BLACK) - zone_attack_fraction(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in pawn presence in central files (d/e files) around the center (ranks 3..4). Encourages central pawn majorities.'
    try:
        pm = board.piece_map()
        def central_pawn_count(color):
            cnt = 0
            for rank in (3,4):
                for file in (3,4):  # d,e files -> 3,4
                    sq = chess.square(file, rank)
                    p = board.piece_at(sq)
                    if p is not None and p.piece_type == chess.PAWN and p.color == color:
                        cnt += 1
            return float(cnt)
        return float(central_pawn_count(chess.WHITE) - central_pawn_count(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in unique attackers that attack any of the squares adjacent (king neighbourhood) to the opponent king (white - black)'
    try:
        piece_map = board.piece_map()
        # find kings
        white_king = None
        black_king = None
        for sq, p in piece_map.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        def adj_squares(king_sq):
            if king_sq is None:
                return []
            kf, kr = chess.square_file(king_sq), chess.square_rank(king_sq)
            res = []
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    f = kf + df
                    r = kr + dr
                    if 0 <= f <= 7 and 0 <= r <= 7:
                        res.append(chess.square(f, r))
            return res
        # unique attacker squares for each side
        attackers_to_black_adj = set()
        attackers_to_white_adj = set()
        for sq in adj_squares(black_king):
            for atk in board.attackers(chess.WHITE, sq):
                attackers_to_black_adj.add(atk)
        for sq in adj_squares(white_king):
            for atk in board.attackers(chess.BLACK, sq):
                attackers_to_white_adj.add(atk)
        result = float(len(attackers_to_black_adj) - len(attackers_to_white_adj))
        return result
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in minimum Manhattan distance from each king to the nearest enemy major piece (rook or queen): (black_min - white_min)'
    try:
        piece_map = board.piece_map()
        white_king = None
        black_king = None
        white_majors = []
        black_majors = []
        for sq, p in piece_map.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
            if p.piece_type in (chess.ROOK, chess.QUEEN):
                if p.color == chess.WHITE:
                    white_majors.append(sq)
                else:
                    black_majors.append(sq)
        INF = 100.0
        def min_dist(king_sq, enemy_list):
            if king_sq is None or not enemy_list:
                return INF
            return min(chess.square_distance(king_sq, e) for e in enemy_list)
        white_min = min_dist(white_king, black_majors)
        black_min = min_dist(black_king, white_majors)
        return float(black_min - white_min)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Piece tropism: sum(value/(1+distance)) of enemy pieces directed at the king (white_tropism - black_tropism). Higher means more concentration of enemy force toward that king.'
    try:
        VALUES = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        piece_map = board.piece_map()
        white_king = None
        black_king = None
        for sq, p in piece_map.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        def tropism_toward(king_sq, attacker_color):
            if king_sq is None:
                return 0.0
            s = 0.0
            for sq, p in piece_map.items():
                if p.color == attacker_color:
                    val = VALUES.get(p.piece_type, 1.0)
                    d = chess.square_distance(king_sq, sq)
                    s += val / (1.0 + float(d))
            return s
        white_trop = tropism_toward(white_king, chess.BLACK)
        black_trop = tropism_toward(black_king, chess.WHITE)
        return float(white_trop - black_trop)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of friendly pawn shield squares in front of the king (white - black). Counts pawns on same and adjacent files within one or two ranks in front of the king.'
    try:
        piece_map = board.piece_map()
        white_king = None
        black_king = None
        for sq, p in piece_map.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        def shield_count(king_sq, color):
            if king_sq is None:
                return 0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            cnt = 0
            if color == chess.WHITE:
                ranks = [kr+1, kr+2]
            else:
                ranks = [kr-1, kr-2]
            for f in (kf-1, kf, kf+1):
                for r in ranks:
                    if 0 <= f <= 7 and 0 <= r <= 7:
                        sq = chess.square(f, r)
                        p = board.piece_at(sq)
                        if p is not None and p.piece_type == chess.PAWN and p.color == color:
                            cnt += 1
            return cnt
        return float(shield_count(white_king, chess.WHITE) - shield_count(black_king, chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of attackers directly attacking the king square (white attackers on black king - black attackers on white king)'
    try:
        piece_map = board.piece_map()
        white_king = None
        black_king = None
        for sq, p in piece_map.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        attackers_on_black = 0
        attackers_on_white = 0
        if black_king is not None:
            attackers_on_black = len(board.attackers(chess.WHITE, black_king))
        if white_king is not None:
            attackers_on_white = len(board.attackers(chess.BLACK, white_king))
        return float(attackers_on_black - attackers_on_white)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in safe escape squares for each king: count of adjacent squares the king could move to that are not attacked by the opponent and are empty or capturable (white - black)'
    try:
        piece_map = board.piece_map()
        white_king = None
        black_king = None
        for sq, p in piece_map.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        def safe_escapes(king_sq, own_color):
            if king_sq is None:
                return 0
            opp = not own_color
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            cnt = 0
            for df in (-1,0,1):
                for dr in (-1,0,1):
                    if df == 0 and dr == 0:
                        continue
                    f = kf + df
                    r = kr + dr
                    if 0 <= f <= 7 and 0 <= r <= 7:
                        sq = chess.square(f, r)
                        # square must be empty or occupied by opponent (capture possible)
                        p = board.piece_at(sq)
                        if p is None or p.color != own_color:
                            # must not be attacked by opponent
                            if not board.is_attacked_by(opp, sq):
                                cnt += 1
            return cnt
        white_safe = safe_escapes(white_king, chess.WHITE)
        black_safe = safe_escapes(black_king, chess.BLACK)
        return float(white_safe - black_safe)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of rooks on the opponent seventh rank (white rooks on rank 7 - black rooks on rank 2), which often signals strong invasion (white - black)'
    try:
        piece_map = board.piece_map()
        white_count = 0
        black_count = 0
        for sq, p in piece_map.items():
            if p.piece_type == chess.ROOK:
                r = chess.square_rank(sq)
                if p.color == chess.WHITE:
                    if r == 6:
                        white_count += 1
                else:
                    if r == 1:
                        black_count += 1
        return float(white_count - black_count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in minimum Manhattan distance from the king to the nearest enemy queen (black_min - white_min). Useful to detect direct queen threats.'
    try:
        piece_map = board.piece_map()
        white_king = None
        black_king = None
        white_queens = []
        black_queens = []
        for sq, p in piece_map.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
            if p.piece_type == chess.QUEEN:
                if p.color == chess.WHITE:
                    white_queens.append(sq)
                else:
                    black_queens.append(sq)
        INF = 100.0
        def min_qdist(king_sq, enemy_queens):
            if king_sq is None or not enemy_queens:
                return INF
            return min(chess.square_distance(king_sq, q) for q in enemy_queens)
        white_min = min_qdist(white_king, black_queens)
        black_min = min_qdist(black_king, white_queens)
        return float(black_min - white_min)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in total enemy non-pawn piece value within manhattan distance <=2 of each king (white_near - black_near). Measures concentration of heavy pieces near the king.'
    try:
        VALUES = {chess.KNIGHT:3.0, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0, chess.PAWN:0.0}
        piece_map = board.piece_map()
        white_king = None
        black_king = None
        for sq, p in piece_map.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        def near_value(king_sq, enemy_color):
            if king_sq is None:
                return 0.0
            s = 0.0
            for sq, p in piece_map.items():
                if p.color == enemy_color and p.piece_type != chess.PAWN:
                    d = chess.square_distance(king_sq, sq)
                    if d <= 2:
                        s += VALUES.get(p.piece_type, 0.0)
            return s
        white_near = near_value(white_king, chess.BLACK)
        black_near = near_value(black_king, chess.WHITE)
        return float(white_near - black_near)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in weighted count of hanging pieces (pieces attacked by opponent and not defended by own side), weighted by piece value (white - black)'
    try:
        VALUES = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        piece_map = board.piece_map()
        white_hanging = 0.0
        black_hanging = 0.0
        for sq, p in piece_map.items():
            own = p.color
            opp = not own
            attacked_by_opp = len(board.attackers(opp, sq)) > 0
            defended_by_own = len(board.attackers(own, sq)) > 0
            if attacked_by_opp and not defended_by_own:
                val = VALUES.get(p.piece_type, 0.0)
                if own == chess.WHITE:
                    white_hanging += val
                else:
                    black_hanging += val
        return float(white_hanging - black_hanging)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King pawn-shield strength difference: counts pawns directly in front of each king (files ky-1, ky, ky+1 on the two ranks in front), White minus Black'
    try:
        pieces = board.piece_map()
        white_shield = 0.0
        black_shield = 0.0
        for color in (chess.WHITE, chess.BLACK):
            king_sq = None
            for sq, pc in pieces.items():
                if pc.piece_type == chess.KING and pc.color == color:
                    king_sq = sq
                    break
            if king_sq is None:
                continue
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            # direction forward for the color
            forward = 1 if color == chess.WHITE else -1
            shield = 0
            for df in (-1, 0, 1):
                for step in (1, 2):
                    rf = kr + forward * step
                    ff = kf + df
                    if 0 <= rf <= 7 and 0 <= ff <= 7:
                        sq = chess.square(ff, rf)
                        pc = board.piece_at(sq)
                        if pc and pc.piece_type == chess.PAWN and pc.color == color:
                            # closer pawns count more
                            shield += 1.5 if step == 1 else 1.0
            if color == chess.WHITE:
                white_shield = shield
            else:
                black_shield = shield
        return float(white_shield - black_shield)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Open/half-open file control by rooks and queens (white minus black). Open file weighted 1.5, half-open 1.0 per major piece on that file'
    try:
        def file_pawn_info(f):
            has_white_pawn = False
            has_black_pawn = False
            for r in range(8):
                sq = chess.square(f, r)
                pc = board.piece_at(sq)
                if pc and pc.piece_type == chess.PAWN:
                    if pc.color == chess.WHITE:
                        has_white_pawn = True
                    else:
                        has_black_pawn = True
            return has_white_pawn, has_black_pawn
        score = 0.0
        for f in range(8):
            has_w, has_b = file_pawn_info(f)
            for r in range(8):
                sq = chess.square(f, r)
                pc = board.piece_at(sq)
                if not pc:
                    continue
                if pc.piece_type in (chess.ROOK, chess.QUEEN):
                    if not has_w and not has_b:
                        weight = 1.5
                    elif (pc.color == chess.WHITE and not has_w) or (pc.color == chess.BLACK and not has_b):
                        weight = 1.0
                    else:
                        weight = 0.0
                    score += weight if pc.color == chess.WHITE else -weight
        return float(score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Sum of undefended attacked piece value (in pawn units) difference: (white undefended attacked piece value) - (black ...). Higher means side has more hanging material'
    try:
        VAL = {chess.PAWN:1.0, chess.KNIGHT:3.2, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        white_sum = 0.0
        black_sum = 0.0
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.KING:
                continue
            attackers = board.attackers(not pc.color, sq)
            if not attackers:
                continue
            defenders = board.attackers(pc.color, sq)
            if len(defenders) == 0:
                v = VAL.get(pc.piece_type, 0.0)
                if pc.color == chess.WHITE:
                    white_sum += v
                else:
                    black_sum += v
        return float(white_sum - black_sum)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Mobility proxy: difference in number of distinct squares attacked by each side (white - black)'
    try:
        white_count = 0
        black_count = 0
        for sq in range(64):
            if board.is_attacked_by(chess.WHITE, sq):
                white_count += 1
            if board.is_attacked_by(chess.BLACK, sq):
                black_count += 1
        return float(white_count - black_count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King tropism metric: distance-weighted attacking force toward opponent king (white - black). Each piece contributes piece_value/(1+manhattan_distance_to_enemy_king)'
    try:
        VAL = {chess.PAWN:1.0, chess.KNIGHT:3.2, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        pieces = board.piece_map()
        white_score = 0.0
        black_score = 0.0
        # find kings
        white_king = None
        black_king = None
        for sq, pc in pieces.items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        for sq, pc in pieces.items():
            if pc.piece_type == chess.KING:
                continue
            if pc.color == chess.WHITE and black_king is not None:
                d = chess.square_distance(sq, black_king)
                white_score += VAL.get(pc.piece_type, 0.0) / (1.0 + d)
            if pc.color == chess.BLACK and white_king is not None:
                d = chess.square_distance(sq, white_king)
                black_score += VAL.get(pc.piece_type, 0.0) / (1.0 + d)
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Heavy-piece attack density near each king (within Chebyshev distance 2): weighted attackers value sum (white - black)'
    try:
        VAL = {chess.PAWN:1.0, chess.KNIGHT:3.2, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        pieces = board.piece_map()
        white_density = 0.0
        black_density = 0.0
        def chebyshev(a, b):
            return max(abs(chess.square_file(a) - chess.square_file(b)), abs(chess.square_rank(a) - chess.square_rank(b)))
        # locate kings
        kings = {chess.WHITE: None, chess.BLACK: None}
        for sq, pc in pieces.items():
            if pc.piece_type == chess.KING:
                kings[pc.color] = sq
        for color in (chess.WHITE, chess.BLACK):
            king_sq = kings[color]
            if king_sq is None:
                continue
            total = 0.0
            for target_sq in range(64):
                if chebyshev(target_sq, king_sq) <= 2:
                    attackers = board.attackers(not color, target_sq)
                    for a in attackers:
                        ap = board.piece_at(a)
                        if ap:
                            total += VAL.get(ap.piece_type, 0.0)
            if color == chess.WHITE:
                white_density = total
            else:
                black_density = total
        return float(white_density - black_density)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Promotion imminence: counts passed pawns on 6th or 7th rank (for white ranks 5 and 6, for black ranks 2 and 1) weighted by advancement (higher is more imminent). Returns white - black'
    try:
        def is_passed(sq, color):
            # basic passed pawn test: no opposing pawns on same or adjacent files ahead of it
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                ahead_ranks = range(r+1, 8)
                opp_color = chess.BLACK
            else:
                ahead_ranks = range(r-1, -1, -1)
                opp_color = chess.WHITE
            for af in (f-1, f, f+1):
                if 0 <= af <= 7:
                    for ar in ahead_ranks:
                        sq2 = chess.square(af, ar)
                        pc = board.piece_at(sq2)
                        if pc and pc.piece_type == chess.PAWN and pc.color == opp_color:
                            return False
            return True
        white_score = 0.0
        black_score = 0.0
        for sq, pc in board.piece_map().items():
            if pc.piece_type != chess.PAWN:
                continue
            r = chess.square_rank(sq)
            if pc.color == chess.WHITE and is_passed(sq, chess.WHITE):
                if r >= 6:  # 7th or 8th rank (6 index => 7th real rank)
                    white_score += 3.0
                elif r == 5:
                    white_score += 1.5
            if pc.color == chess.BLACK and is_passed(sq, chess.BLACK):
                if r <= 1:
                    black_score += 3.0
                elif r == 2:
                    black_score += 1.5
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rooks on opponent seventh rank (white rooks on rank 6, black rooks on rank 1) difference: counts white - black'
    try:
        w = 0
        b = 0
        for sq, pc in board.piece_map().items():
            if pc.piece_type == chess.ROOK:
                r = chess.square_rank(sq)
                if pc.color == chess.WHITE and r == 6:
                    w += 1
                if pc.color == chess.BLACK and r == 1:
                    b += 1
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King safe squares difference: number of adjacent/king-move squares that are not attacked by opponent and not occupied by own piece (white - black), normalized to [ -8 .. 8 ]'
    try:
        def safe_squares_for(color):
            pieces = board.piece_map()
            ksq = None
            for sq, pc in pieces.items():
                if pc.piece_type == chess.KING and pc.color == color:
                    ksq = sq
                    break
            if ksq is None:
                return 0.0
            safe = 0
            kf = chess.square_file(ksq)
            kr = chess.square_rank(ksq)
            opp = not color
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    ff = kf + df
                    rr = kr + dr
                    if 0 <= ff <= 7 and 0 <= rr <= 7:
                        sq = chess.square(ff, rr)
                        occupant = board.piece_at(sq)
                        # cannot move to square occupied by own piece
                        if occupant and occupant.color == color:
                            continue
                        # safe if not attacked by opponent
                        if not board.is_attacked_by(opp, sq):
                            safe += 1
            return float(safe)
        return float(safe_squares_for(chess.WHITE) - safe_squares_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Material-to-mobility imbalance: (material in pawn units) / (1 + mobility proxy) difference (white - black). Positive means side has more material per unit mobility (could indicate trapped material)'
    try:
        VAL_CP = {chess.PAWN:1.0, chess.KNIGHT:3.2, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        material = {chess.WHITE:0.0, chess.BLACK:0.0}
        mobility = {chess.WHITE:0, chess.BLACK:0}
        for sq, pc in board.piece_map().items():
            material[pc.color] += VAL_CP.get(pc.piece_type, 0.0)
        for sq in range(64):
            if board.is_attacked_by(chess.WHITE, sq):
                mobility[chess.WHITE] += 1
            if board.is_attacked_by(chess.BLACK, sq):
                mobility[chess.BLACK] += 1
        w_score = material[chess.WHITE] / (1.0 + mobility[chess.WHITE]/8.0)
        b_score = material[chess.BLACK] / (1.0 + mobility[chess.BLACK]/8.0)
        return float(w_score - b_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference between major-piece advantage and minor-piece advantage (White - Black), in pawn units'
    PIECE_VALUE = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:20000}
    white_major = 0
    black_major = 0
    white_minor = 0
    black_minor = 0
    for sq, piece in board.piece_map().items():
        if piece.piece_type in (chess.ROOK, chess.QUEEN):
            if piece.color == chess.WHITE:
                white_major += PIECE_VALUE[piece.piece_type]
            else:
                black_major += PIECE_VALUE[piece.piece_type]
        elif piece.piece_type in (chess.BISHOP, chess.KNIGHT):
            if piece.color == chess.WHITE:
                white_minor += PIECE_VALUE[piece.piece_type]
            else:
                black_minor += PIECE_VALUE[piece.piece_type]
    # (white_major - white_minor) - (black_major - black_minor), normalized to pawns
    return float((white_major - white_minor - (black_major - black_minor)) / 100.0)

def feature(board: chess.Board) -> float:
    'Net count of rooks on opponent seventh rank (White sevens - Black sevens)'
    white_seventh = 0
    black_seventh = 0
    for sq, piece in board.piece_map().items():
        if piece.piece_type == chess.ROOK:
            rank = chess.square_rank(sq)
            if piece.color == chess.WHITE and rank == 6:  # White on 7th rank
                white_seventh += 1
            if piece.color == chess.BLACK and rank == 1:  # Black on 2nd rank (White's 7th from Black view)
                black_seventh += 1
    return float(white_seventh - black_seventh)

def feature(board: chess.Board) -> float:
    'Difference in king pawn-shield proximity: (White king distance to nearest white pawn) - (Black king distance to nearest black pawn). Positive means White more exposed'
    INF = 8
    piece_map = board.piece_map()
    white_king_sq = None
    black_king_sq = None
    white_pawns = []
    black_pawns = []
    for sq, pc in piece_map.items():
        if pc.piece_type == chess.KING:
            if pc.color == chess.WHITE:
                white_king_sq = sq
            else:
                black_king_sq = sq
        elif pc.piece_type == chess.PAWN:
            if pc.color == chess.WHITE:
                white_pawns.append(sq)
            else:
                black_pawns.append(sq)
    def nearest_dist(king_sq, pawns):
        if king_sq is None:
            return 0.0
        if not pawns:
            return float(INF)
        md = min(chess.square_distance(king_sq, p) for p in pawns)
        return float(md)
    white_dist = nearest_dist(white_king_sq, white_pawns)
    black_dist = nearest_dist(black_king_sq, black_pawns)
    # positive -> White more exposed (farther from its pawn shield)
    return float(white_dist - black_dist)

def feature(board: chess.Board) -> float:
    'Maximum high-value piece (except king) that is currently attacked by the opponent (White_attacked_max - Black_attacked_max) in pawn units'
    PIECE_VALUE = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900}
    white_max = 0
    black_max = 0
    pm = board.piece_map()
    for sq, pc in pm.items():
        if pc.piece_type == chess.KING:
            continue
        attackers_by_opponent = board.attackers(not pc.color, sq)
        if attackers_by_opponent:
            val = PIECE_VALUE.get(pc.piece_type, 0)
            if pc.color == chess.WHITE:
                white_max = max(white_max, val)
            else:
                black_max = max(black_max, val)
    return float((white_max - black_max) / 100.0)

def feature(board: chess.Board) -> float:
    'Net number of attackers on kings: (attackers on Black king by White) - (attackers on White king by Black)'
    pm = board.piece_map()
    wking = None
    bking = None
    for sq, pc in pm.items():
        if pc.piece_type == chess.KING:
            if pc.color == chess.WHITE:
                wking = sq
            else:
                bking = sq
    if wking is None or bking is None:
        return 0.0
    attackers_on_b = len(board.attackers(chess.WHITE, bking))
    attackers_on_w = len(board.attackers(chess.BLACK, wking))
    return float(attackers_on_b - attackers_on_w)

def feature(board: chess.Board) -> float:
    'Difference in net vulnerable material pressure: sum over pieces of (max(0, attackers - defenders) * piece_value) for White minus Black, in pawn units'
    PIECE_VALUE = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:20000}
    white_pressure = 0
    black_pressure = 0
    for sq, pc in board.piece_map().items():
        attackers = len(board.attackers(not pc.color, sq))
        defenders = len(board.attackers(pc.color, sq))
        pressure = max(0, attackers - defenders)
        val = PIECE_VALUE.get(pc.piece_type, 0)
        if pc.color == chess.WHITE:
            white_pressure += pressure * val
        else:
            black_pressure += pressure * val
    return float((white_pressure - black_pressure) / 100.0)

def feature(board: chess.Board) -> float:
    'Difference in number of connected passed pawns (White - Black). Connected passed means a passed pawn with a friendly pawn on an adjacent file.'
    def is_passed(sq, color, pm):
        file = chess.square_file(sq)
        rank = chess.square_rank(sq)
        if color == chess.WHITE:
            # any black pawn on same or adjacent files with higher rank blocks
            for f in (file-1, file, file+1):
                if 0 <= f <= 7:
                    for r in range(rank+1, 8):
                        s = chess.square(f, r)
                        p = pm.get(s)
                        if p is not None and p.piece_type == chess.PAWN and p.color == chess.BLACK:
                            return False
            return True
        else:
            for f in (file-1, file, file+1):
                if 0 <= f <= 7:
                    for r in range(0, rank):
                        s = chess.square(f, r)
                        p = pm.get(s)
                        if p is not None and p.piece_type == chess.PAWN and p.color == chess.WHITE:
                            return False
            return True
    pm = board.piece_map()
    white_connected = 0
    black_connected = 0
    # Precompute friendly pawns by file
    white_pawn_files = set()
    black_pawn_files = set()
    for s, p in pm.items():
        if p.piece_type == chess.PAWN:
            if p.color == chess.WHITE:
                white_pawn_files.add(chess.square_file(s))
            else:
                black_pawn_files.add(chess.square_file(s))
    for sq, p in pm.items():
        if p.piece_type != chess.PAWN:
            continue
        if p.color == chess.WHITE:
            if is_passed(sq, chess.WHITE, pm):
                f = chess.square_file(sq)
                if (f-1 in white_pawn_files) or (f+1 in white_pawn_files):
                    white_connected += 1
        else:
            if is_passed(sq, chess.BLACK, pm):
                f = chess.square_file(sq)
                if (f-1 in black_pawn_files) or (f+1 in black_pawn_files):
                    black_connected += 1
    return float(white_connected - black_connected)

def feature(board: chess.Board) -> float:
    'Difference in rooks occupying open files (no pawns on that file): White_open_rooks - Black_open_rooks'
    files_have_pawn = [False]*8
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.PAWN:
            files_have_pawn[chess.square_file(sq)] = True
    white_open_rooks = 0
    black_open_rooks = 0
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.ROOK:
            if not files_have_pawn[chess.square_file(sq)]:
                if p.color == chess.WHITE:
                    white_open_rooks += 1
                else:
                    black_open_rooks += 1
    return float(white_open_rooks - black_open_rooks)

def feature(board: chess.Board) -> float:
    'Relative queen proximity to the enemy king: closeness score (higher = more dangerous). Returns (White queen closeness to Black king) - (Black queen closeness to White king)'
    pm = board.piece_map()
    wking = None
    bking = None
    white_queens = []
    black_queens = []
    for sq, p in pm.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                wking = sq
            else:
                bking = sq
        elif p.piece_type == chess.QUEEN:
            if p.color == chess.WHITE:
                white_queens.append(sq)
            else:
                black_queens.append(sq)
    def closeness(queens, enemy_king):
        if enemy_king is None or not queens:
            return 0.0
        d = min(chess.square_distance(q, enemy_king) for q in queens)
        # translate distance to closeness: 8 - d (so smaller distance => larger score)
        return float(max(0, 8 - d))
    return float(closeness(white_queens, bking) - closeness(black_queens, wking))

def feature(board: chess.Board) -> float:
    'Pawn pressure on the opponent king file measured by pawn advancement: sum of pawn-advance ranks on the enemy king file (White - Black). Higher means more pawn pressure toward that king'
    pm = board.piece_map()
    wking = None
    bking = None
    for sq, p in pm.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                wking = sq
            else:
                bking = sq
    white_pressure = 0.0
    black_pressure = 0.0
    if bking is not None:
        bk_file = chess.square_file(bking)
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN and p.color == chess.WHITE and chess.square_file(sq) == bk_file:
                # advancement measured by rank (0..7): higher is more advanced for White
                white_pressure += float(chess.square_rank(sq))
    if wking is not None:
        wk_file = chess.square_file(wking)
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN and p.color == chess.BLACK and chess.square_file(sq) == wk_file:
                # advancement for Black toward White's side: higher when rank is lower, so use (7 - rank)
                black_pressure += float(7 - chess.square_rank(sq))
    # normalize by 8 to keep in reasonable range
    return float((white_pressure - black_pressure) / 8.0)

def feature(board: chess.Board) -> float:
    'Normalized mobility: number of legal moves for side to move (divided by 100)'
    try:
        moves = board.legal_moves
        # legal_moves is an iterator; convert to list length safely
        n = sum(1 for _ in moves)
    except Exception:
        n = 0
    return float(n) / 100.0

def feature(board: chess.Board) -> float:
    'Net hanging pieces: (# of opponent-attacked & undefended white pieces) - (same for black)'
    hanging_white = 0
    hanging_black = 0
    try:
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.KING:
                continue
            opp = not piece.color
            attackers = board.attackers(opp, sq)
            defenders = board.attackers(piece.color, sq)
            if attackers and not defenders:
                if piece.color == chess.WHITE:
                    hanging_white += 1
                else:
                    hanging_black += 1
    except Exception:
        pass
    return float(hanging_white - hanging_black)

def feature(board: chess.Board) -> float:
    'Rooks on open files difference: (#white rooks on files with no pawns) - (#black rooks same)'
    white_open = 0
    black_open = 0
    try:
        pawns_on_file = [0] * 8
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                pawns_on_file[chess.square_file(sq)] += 1
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                if pawns_on_file[f] == 0:
                    if p.color == chess.WHITE:
                        white_open += 1
                    else:
                        black_open += 1
    except Exception:
        pass
    return float(white_open - black_open)

def feature(board: chess.Board) -> float:
    'Rooks on opponent seventh rank (white rooks on rank 7 minus black rooks on rank 2)'
    white_seventh = 0
    black_seventh = 0
    try:
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                r = chess.square_rank(sq)
                if p.color == chess.WHITE and r == 6:
                    white_seventh += 1
                if p.color == chess.BLACK and r == 1:
                    black_seventh += 1
    except Exception:
        pass
    return float(white_seventh - black_seventh)

def feature(board: chess.Board) -> float:
    'Pawn islands difference: number of separate pawn file groups (white - black)'
    def pawn_islands(color):
        files_has = [False] * 8
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN and p.color == color:
                files_has[chess.square_file(sq)] = True
        islands = 0
        i = 0
        while i < 8:
            if files_has[i]:
                islands += 1
                while i < 8 and files_has[i]:
                    i += 1
            else:
                i += 1
        return islands
    try:
        return float(pawn_islands(chess.WHITE) - pawn_islands(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Isolated pawns difference: count of isolated pawns (white - black)'
    isolated_white = 0
    isolated_black = 0
    try:
        white_files = [0] * 8
        black_files = [0] * 8
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                if p.color == chess.WHITE:
                    white_files[chess.square_file(sq)] += 1
                else:
                    black_files[chess.square_file(sq)] += 1
        for f in range(8):
            if white_files[f] > 0:
                left = white_files[f-1] if f-1 >= 0 else 0
                right = white_files[f+1] if f+1 <= 7 else 0
                if left + right == 0:
                    isolated_white += white_files[f]
            if black_files[f] > 0:
                left = black_files[f-1] if f-1 >= 0 else 0
                right = black_files[f+1] if f+1 <= 7 else 0
                if left + right == 0:
                    isolated_black += black_files[f]
    except Exception:
        pass
    return float(isolated_white - isolated_black)

def feature(board: chess.Board) -> float:
    'King zone pressure: (number of black attacks on white king neighborhood) - (white attacks on black king neighborhood)'
    def king_zone_attacks(king_color):
        # count total attacking pieces (may double-count attackers on multiple squares)
        attacks = 0
        king_sq = None
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING and p.color == king_color:
                king_sq = sq
                break
        if king_sq is None:
            return 0
        kf = chess.square_file(king_sq)
        kr = chess.square_rank(king_sq)
        opp = not king_color
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                nf = kf + df
                nr = kr + dr
                if 0 <= nf <= 7 and 0 <= nr <= 7:
                    nsq = chess.square(nf, nr)
                    try:
                        attacks += len(board.attackers(opp, nsq))
                    except Exception:
                        pass
        return attacks
    try:
        return float(king_zone_attacks(chess.WHITE) - king_zone_attacks(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Average defenders per piece difference: (avg defenders of white pieces) - (avg defenders of black pieces)'
    try:
        white_def_sum = 0
        white_count = 0
        black_def_sum = 0
        black_count = 0
        for sq, p in board.piece_map().items():
            defs = len(board.attackers(p.color, sq))
            if p.color == chess.WHITE:
                white_def_sum += defs
                white_count += 1
            else:
                black_def_sum += defs
                black_count += 1
        avg_white = (white_def_sum / white_count) if white_count > 0 else 0.0
        avg_black = (black_def_sum / black_count) if black_count > 0 else 0.0
        return float(avg_white - avg_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn promotion threat: sum over passed pawns of (1 / rank_distance_to_promotion) weighted (white - black)'
    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            for of in (f-1, f, f+1):
                if 0 <= of <= 7:
                    # any black pawn ahead (higher rank) on these files blocks passing
                    for rr in range(r+1, 8):
                        occ = board.piece_at(chess.square(of, rr))
                        if occ and occ.piece_type == chess.PAWN and occ.color == chess.BLACK:
                            return False
            return True
        else:
            for of in (f-1, f, f+1):
                if 0 <= of <= 7:
                    for rr in range(0, r):
                        occ = board.piece_at(chess.square(of, rr))
                        if occ and occ.piece_type == chess.PAWN and occ.color == chess.WHITE:
                            return False
            return True
    score_white = 0.0
    score_black = 0.0
    try:
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                if is_passed(sq, p.color):
                    r = chess.square_rank(sq)
                    if p.color == chess.WHITE:
                        dist = 7 - r
                        if dist <= 0:
                            val = 1.0
                        else:
                            val = 1.0 / float(dist)
                        score_white += val
                    else:
                        dist = r
                        if dist <= 0:
                            val = 1.0
                        else:
                            val = 1.0 / float(dist)
                        score_black += val
    except Exception:
        pass
    return float(score_white - score_black)

def feature(board: chess.Board) -> float:
    'Rook alignment to enemy king: (#white rooks with clear file/rank to black king) - (same for black)'
    def clear_path(sq1, sq2):
        f1, r1 = chess.square_file(sq1), chess.square_rank(sq1)
        f2, r2 = chess.square_file(sq2), chess.square_rank(sq2)
        if f1 != f2 and r1 != r2:
            return False
        df = 0 if f1 == f2 else (1 if f2 > f1 else -1)
        dr = 0 if r1 == r2 else (1 if r2 > r1 else -1)
        cf, cr = f1 + df, r1 + dr
        while (cf, cr) != (f2, r2):
            if board.piece_at(chess.square(cf, cr)) is not None:
                return False
            cf += df
            cr += dr
        return True
    try:
        black_king = None
        white_king = None
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        white_count = 0
        black_count = 0
        if black_king is not None:
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.ROOK and p.color == chess.WHITE:
                    if (chess.square_file(sq) == chess.square_file(black_king) or
                        chess.square_rank(sq) == chess.square_rank(black_king)):
                        if clear_path(sq, black_king):
                            white_count += 1
        if white_king is not None:
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.ROOK and p.color == chess.BLACK:
                    if (chess.square_file(sq) == chess.square_file(white_king) or
                        chess.square_rank(sq) == chess.square_rank(white_king)):
                        if clear_path(sq, white_king):
                            black_count += 1
        return float(white_count - black_count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in number of rooks sitting on the opponent 7th rank (white rooks on rank 7 (index 6), black rooks on rank 2 (index 1))'
    try:
        white = 0
        black = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                r = chess.square_rank(sq)
                if p.color == chess.WHITE and r == 6:
                    white += 1
                if p.color == chess.BLACK and r == 1:
                    black += 1
        return float(white - black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of count of rooks positioned directly behind their own passed pawns on the same file (rook is on same file and closer to own baseline than the pawn)'
    try:
        def is_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                for sq2, p2 in board.piece_map().items():
                    if p2.piece_type == chess.PAWN and p2.color == chess.BLACK:
                        f2 = chess.square_file(sq2)
                        r2 = chess.square_rank(sq2)
                        if abs(f2 - f) <= 1 and r2 > r:
                            return False
                return True
            else:
                for sq2, p2 in board.piece_map().items():
                    if p2.piece_type == chess.PAWN and p2.color == chess.WHITE:
                        f2 = chess.square_file(sq2)
                        r2 = chess.square_rank(sq2)
                        if abs(f2 - f) <= 1 and r2 < r:
                            return False
                return True

        white = 0
        black = 0
        # map files to rooks for quick lookup
        rooks_by_file = {f: {chess.WHITE: [], chess.BLACK: []} for f in range(8)}
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                rooks_by_file[chess.square_file(sq)][p.color].append(sq)
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                if is_passed(sq, p.color):
                    # for white: rook behind means rook rank < pawn rank
                    for r_sq in rooks_by_file[f][p.color]:
                        rr = chess.square_rank(r_sq)
                        if p.color == chess.WHITE and rr < r:
                            white += 1
                            break
                        if p.color == chess.BLACK and rr > r:
                            black += 1
                            break
        return float(white - black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) score for kings blocking opponent passed pawns (positive if white king blocks black passed pawns and/or avoids being blocked)'
    try:
        def is_passed(sq, color):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if color == chess.WHITE:
                for sq2, p2 in board.piece_map().items():
                    if p2.piece_type == chess.PAWN and p2.color == chess.BLACK:
                        f2 = chess.square_file(sq2); r2 = chess.square_rank(sq2)
                        if abs(f2 - f) <= 1 and r2 > r:
                            return False
                return True
            else:
                for sq2, p2 in board.piece_map().items():
                    if p2.piece_type == chess.PAWN and p2.color == chess.WHITE:
                        f2 = chess.square_file(sq2); r2 = chess.square_rank(sq2)
                        if abs(f2 - f) <= 1 and r2 < r:
                            return False
                return True

        piece_map = board.piece_map()
        white_king_sq = None
        black_king_sq = None
        for sq, p in piece_map.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king_sq = sq
                else:
                    black_king_sq = sq
        score = 0.0
        for sq, p in piece_map.items():
            if p.piece_type == chess.PAWN and is_passed(sq, p.color):
                f = chess.square_file(sq); r = chess.square_rank(sq)
                if p.color == chess.WHITE:
                    # promotion square rank 7 (index 7)
                    # if black king sits on same file between pawn and promotion (r < king_r < 8)
                    if black_king_sq is not None:
                        kr = chess.square_rank(black_king_sq); kf = chess.square_file(black_king_sq)
                        if kf == f and kr > r:
                            # black king blocks white pawn -> bad for white
                            score -= 1.0
                else:
                    if white_king_sq is not None:
                        kr = chess.square_rank(white_king_sq); kf = chess.square_file(white_king_sq)
                        if kf == f and kr < r:
                            # white king blocks black pawn -> good for white
                            score += 1.0
        return float(score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) evaluating rook control of open/semi-open files (open file = no pawns; semi-open = no own pawns on that file). Open=1.0, semi-open=0.5'
    try:
        file_has_pawn = [False] * 8
        file_has_white_pawn = [False] * 8
        file_has_black_pawn = [False] * 8
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                file_has_pawn[f] = True
                if p.color == chess.WHITE:
                    file_has_white_pawn[f] = True
                else:
                    file_has_black_pawn[f] = True
        w_score = 0.0
        b_score = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                if not file_has_pawn[f]:
                    if p.color == chess.WHITE:
                        w_score += 1.0
                    else:
                        b_score += 1.0
                else:
                    if p.color == chess.WHITE and not file_has_white_pawn[f]:
                        w_score += 0.5
                    if p.color == chess.BLACK and not file_has_black_pawn[f]:
                        b_score += 0.5
        return float(w_score - b_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (Black_penalty - White_penalty) of king cornering: kings closer to corners get a higher penalty; positive result means position favors White (Black more cornered)'
    try:
        corners = [chess.A1, chess.A8, chess.H1, chess.H8]
        def corner_penalty(king_sq):
            if king_sq is None:
                return 0.0
            min_dist = min(chess.square_distance(king_sq, c) for c in corners)
            # normalize: max distance on board is 7+7=14 Manhattan; use that to scale
            return 1.0 - (min_dist / 14.0)
        wm = bm = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    wm = corner_penalty(sq)
                else:
                    bm = corner_penalty(sq)
        # we want positive when White is better => black more cornered than white
        return float(bm - wm)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (Black_exposed_ratio - White_exposed_ratio): fraction of non-pawn pieces attacked by enemy; positive means Black pieces are more exposed (favors White)'
    try:
        white_total = white_attacked = 0
        black_total = black_attacked = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                continue
            if p.color == chess.WHITE:
                white_total += 1
                if board.is_attacked_by(chess.BLACK, sq):
                    white_attacked += 1
            else:
                black_total += 1
                if board.is_attacked_by(chess.WHITE, sq):
                    black_attacked += 1
        def ratio(att, tot):
            return (att / tot) if tot > 0 else 0.0
        return float(ratio(black_attacked, black_total) - ratio(white_attacked, white_total))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in number of advanced unprotected pawns (advanced: rank >=5 for White, rank <=2 for Black; unprotected means no friendly piece attacks the pawn square)'
    try:
        white = 0
        black = 0
        for sq, p in board.piece_map().items():
            if p.piece_type != chess.PAWN:
                continue
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                if r >= 4:  # rank 5..8 (index 4..7) treat as advanced
                    if len(board.attackers(chess.WHITE, sq)) <= 1:  # attackers includes the pawn itself? attackers returns set of squares attacking square; a pawn does not "attack" its own square so ok
                        # ensure no friendly attacker (protection)
                        if len(board.attackers(chess.WHITE, sq)) == 0:
                            white += 1
            else:
                if r <= 3:  # rank 4..1 (index 0..3) count as advanced for black (closer to promotion)
                    if len(board.attackers(chess.BLACK, sq)) == 0:
                        black += 1
        return float(white - black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of count of king-near squares (Manhattan distance <=2) that are safe: not attacked by the opponent and not occupied by an enemy piece (higher = safer king)'
    try:
        def safe_zone_count(king_sq, opponent_color):
            if king_sq is None:
                return 0.0
            count = 0
            for sq in chess.SQUARES:
                if chess.square_distance(sq, king_sq) <= 2:
                    piece = board.piece_at(sq)
                    if piece is not None and piece.color == opponent_color:
                        continue
                    if board.is_attacked_by(opponent_color, sq):
                        continue
                    count += 1
            return count
        wk = bk = None
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    wk = sq
                else:
                    bk = sq
        wcount = safe_zone_count(wk, chess.BLACK)
        bcount = safe_zone_count(bk, chess.WHITE)
        # normalize by maximum possible squares in radius 2 (at most 25)
        return float((wcount - bcount) / 25.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Normalized difference (White - Black) of minimal rook-to-opponent-king file distance (smaller is better); value in [-1,1], positive if White rooks are closer to Black king than vice versa'
    try:
        white_min = 8
        black_min = 8
        bk_sq = wk_sq = None
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    wk_sq = sq
                else:
                    bk_sq = sq
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                rf = chess.square_file(sq)
                if p.color == chess.WHITE and bk_sq is not None:
                    bf = chess.square_file(bk_sq)
                    white_min = min(white_min, abs(rf - bf))
                if p.color == chess.BLACK and wk_sq is not None:
                    wf = chess.square_file(wk_sq)
                    black_min = min(black_min, abs(rf - wf))
        if white_min == 8 and black_min == 8:
            return 0.0
        # smaller distance is better for attacker; we want positive if White is better -> black_min - white_min
        val = (black_min - white_min) / 8.0
        return float(val)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of attacker-weight sums on promotion squares of passed pawns (weights: pawn=1, knight=3, bishop=3, rook=5, queen=9)'
    try:
        weights = {
            chess.PAWN: 1.0,
            chess.KNIGHT: 3.0,
            chess.BISHOP: 3.0,
            chess.ROOK: 5.0,
            chess.QUEEN: 9.0,
            chess.KING: 0.5
        }
        def is_passed(sq, color):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if color == chess.WHITE:
                for sq2, p2 in board.piece_map().items():
                    if p2.piece_type == chess.PAWN and p2.color == chess.BLACK:
                        f2 = chess.square_file(sq2); r2 = chess.square_rank(sq2)
                        if abs(f2 - f) <= 1 and r2 > r:
                            return False
                return True
            else:
                for sq2, p2 in board.piece_map().items():
                    if p2.piece_type == chess.PAWN and p2.color == chess.WHITE:
                        f2 = chess.square_file(sq2); r2 = chess.square_rank(sq2)
                        if abs(f2 - f) <= 1 and r2 < r:
                            return False
                return True

        white_threat = 0.0
        black_threat = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN and is_passed(sq, p.color):
                # promotion square
                if p.color == chess.WHITE:
                    promo_sq = chess.square(chess.square_file(sq), 7)
                    # attackers by black against that promotion square
                    for attacker_sq in board.attackers(chess.BLACK, promo_sq):
                        attacker = board.piece_at(attacker_sq)
                        if attacker:
                            black_threat += weights.get(attacker.piece_type, 0.0)
                else:
                    promo_sq = chess.square(chess.square_file(sq), 0)
                    for attacker_sq in board.attackers(chess.WHITE, promo_sq):
                        attacker = board.piece_at(attacker_sq)
                        if attacker:
                            white_threat += weights.get(attacker.piece_type, 0.0)
        return float(white_threat - black_threat)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in number of rooks occupying the opponent seventh rank (white on rank 7 (rank index 6), black on rank 2 (rank index 1))'
    try:
        wm = 0
        bm = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                r = chess.square_rank(sq)
                if p.color == chess.WHITE and r == 6:
                    wm += 1
                if p.color == chess.BLACK and r == 1:
                    bm += 1
        return float(wm - bm)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in total material value of pieces that are attacked and under-defended (attackers > defenders), values in pawn units (pawn=1)'
    try:
        values = {chess.PAWN:1.0, chess.KNIGHT:3.2, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        white_sum = 0.0
        black_sum = 0.0
        pm = board.piece_map()
        for sq, p in pm.items():
            attackers = board.attackers(not p.color, sq)
            defenders = board.attackers(p.color, sq)
            if len(attackers) > len(defenders):
                v = values.get(p.piece_type, 0.0)
                if p.color == chess.WHITE:
                    white_sum += v
                else:
                    black_sum += v
        # Advantage for side whose opponent has more under-defended attacked material
        return float(black_sum - white_sum)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn-shield around each king: (number of friendly pawns in 3x3 neighborhood plus same-file forward 2 squares) difference White - Black'
    try:
        pm = board.piece_map()
        king_sq = {chess.WHITE: None, chess.BLACK: None}
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                king_sq[p.color] = sq
        def pawn_shield_for(color):
            ks = king_sq.get(color)
            if ks is None:
                return 0.0
            count = 0
            kf, kr = chess.square_file(ks), chess.square_rank(ks)
            # 3x3 neighborhood
            for df in (-1,0,1):
                for dr in (-1,0,1):
                    ff = kf + df
                    rr = kr + dr
                    if 0 <= ff < 8 and 0 <= rr < 8:
                        s = chess.square(ff, rr)
                        p = board.piece_at(s)
                        if p and p.piece_type == chess.PAWN and p.color == color:
                            count += 1
            # same-file forward two squares (forward relative to color)
            if color == chess.WHITE:
                for dr in (1,2):
                    rr = kr + dr
                    if 0 <= rr < 8:
                        s = chess.square(kf, rr)
                        p = board.piece_at(s)
                        if p and p.piece_type == chess.PAWN and p.color == color:
                            count += 0.7  # small extra weight
            else:
                for dr in (1,2):
                    rr = kr - dr
                    if 0 <= rr < 8:
                        s = chess.square(kf, rr)
                        p = board.piece_at(s)
                        if p and p.piece_type == chess.PAWN and p.color == color:
                            count += 0.7
            return count
        return float(pawn_shield_for(chess.WHITE) - pawn_shield_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed-pawn advancement weighted by support: sum over passed pawns of (advancement_fraction * (1 + 0.5*number_of_friendly_attackers)), returned White - Black'
    try:
        pm = board.piece_map()
        # Build list of pawn squares by color for quick checks
        pawn_squares_by_color = {chess.WHITE: set(), chess.BLACK: set()}
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                pawn_squares_by_color[p.color].add(sq)
        def is_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            enemy = not color
            for df in (-1,0,1):
                ff = f + df
                if 0 <= ff < 8:
                    for esq in pawn_squares_by_color[enemy]:
                        if chess.square_file(esq) == ff:
                            er = chess.square_rank(esq)
                            if color == chess.WHITE:
                                # enemy pawn ahead or on same rank and closer to promotion blocks
                                if er > r:
                                    return False
                            else:
                                if er < r:
                                    return False
            return True
        def advancement_fraction(sq, color):
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                return float(r) / 7.0
            else:
                return float(7 - r) / 7.0
        white_score = 0.0
        black_score = 0.0
        for sq, p in pm.items():
            if p.piece_type != chess.PAWN:
                continue
            try:
                if is_passed(sq, p.color):
                    adv = advancement_fraction(sq, p.color)
                    # number of friendly attackers of the pawn square (exclude the pawn itself)
                    attackers = board.attackers(p.color, sq)
                    # attacker set may include the pawn's own square in some contexts; safe to count other squares
                    support = max(0, len(attackers) - 0)  # keep attackers count as proxy for support
                    score = adv * (1.0 + 0.5 * support)
                    if p.color == chess.WHITE:
                        white_score += score
                    else:
                        black_score += score
            except Exception:
                continue
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in number of rooks occupying open files (files with no pawns of either color)'
    try:
        pm = board.piece_map()
        pawns_on_file = [0]*8
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                pawns_on_file[chess.square_file(sq)] += 1
        white_open_rooks = 0
        black_open_rooks = 0
        for sq, p in pm.items():
            if p.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                if pawns_on_file[f] == 0:
                    if p.color == chess.WHITE:
                        white_open_rooks += 1
                    else:
                        black_open_rooks += 1
        return float(white_open_rooks - black_open_rooks)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of distinct squares attacked by White minus squares attacked by Black, normalized by board size (64)'
    try:
        white_attacks = 0
        black_attacks = 0
        for sq in range(64):
            if board.is_attacked_by(chess.WHITE, sq):
                white_attacks += 1
            if board.is_attacked_by(chess.BLACK, sq):
                black_attacks += 1
        return float((white_attacks - black_attacks) / 64.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in heavyweight or minor pieces that are attacked while having defenders <= attackers (counts weighted by piece value in pawn units)'
    try:
        values = {chess.KNIGHT:3.2, chess.BISHOP:3.3, chess.ROOK:5.0, chess.QUEEN:9.0}
        white_bad = 0.0
        black_bad = 0.0
        pm = board.piece_map()
        for sq, p in pm.items():
            if p.piece_type in values:
                attackers = len(board.attackers(not p.color, sq))
                defenders = len(board.attackers(p.color, sq))
                if attackers > 0 and defenders <= attackers:
                    if p.color == chess.WHITE:
                        white_bad += values[p.piece_type]
                    else:
                        black_bad += values[p.piece_type]
        # More bad pieces for the opponent is good for the side, so return black_bad - white_bad
        return float(black_bad - white_bad)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn-majority balance: (White - Black) difference of pawn counts on queenside (files a-c) minus pawn counts on kingside (files f-h). Positive means White has better queenside majority relative to kingside'
    try:
        pm = board.piece_map()
        w_qs = 0
        b_qs = 0
        w_ks = 0
        b_ks = 0
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if f <= 2:  # files a-c
                    if p.color == chess.WHITE:
                        w_qs += 1
                    else:
                        b_qs += 1
                if f >= 5:  # files f-h
                    if p.color == chess.WHITE:
                        w_ks += 1
                    else:
                        b_ks += 1
        qs_diff = (w_qs - b_qs)
        ks_diff = (w_ks - b_ks)
        return float(qs_diff - ks_diff)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in number of safe escape squares for each king (adjacent squares that are not occupied by friendly pieces and not attacked by the opponent)'
    try:
        pm = board.piece_map()
        king_sq = {chess.WHITE: None, chess.BLACK: None}
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                king_sq[p.color] = sq
        def safe_squares(color):
            ks = king_sq.get(color)
            if ks is None:
                return 0.0
            kf = chess.square_file(ks)
            kr = chess.square_rank(ks)
            count = 0
            enemy = not color
            for df in (-1,0,1):
                for dr in (-1,0,1):
                    if df == 0 and dr == 0:
                        continue
                    ff = kf + df
                    rr = kr + dr
                    if 0 <= ff < 8 and 0 <= rr < 8:
                        s = chess.square(ff, rr)
                        occ = board.piece_at(s)
                        if occ and occ.color == color:
                            continue
                        # square is candidate; consider it safe if not attacked by enemy
                        try:
                            if not board.is_attacked_by(enemy, s):
                                count += 1
                        except Exception:
                            # fallback: if attack query fails, treat as unsafe
                            continue
            return count
        return float(safe_squares(chess.WHITE) - safe_squares(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Simple indicator (-1,0,1) for queen vs two-rooks imbalance: +1 if White has a queen and Black has >=2 rooks (and Black has no queen), -1 for the converse, else 0'
    try:
        pm = board.piece_map()
        counts = {chess.WHITE: {'q':0, 'r':0}, chess.BLACK: {'q':0, 'r':0}}
        for sq, p in pm.items():
            if p.piece_type == chess.QUEEN:
                counts[p.color]['q'] += 1
            if p.piece_type == chess.ROOK:
                counts[p.color]['r'] += 1
        # White advantageous if White has a queen and Black has >=2 rooks and Black has no queen
        if counts[chess.WHITE]['q'] >= 1 and counts[chess.BLACK]['q'] == 0 and counts[chess.BLACK]['r'] >= 2:
            return 1.0
        if counts[chess.BLACK]['q'] >= 1 and counts[chess.WHITE]['q'] == 0 and counts[chess.WHITE]['r'] >= 2:
            return -1.0
        return 0.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Normalized difference in total legal move counts (White - Black), divided by 100'
    try:
        moves = list(board.legal_moves)
        # Count legal moves for side to move is irrelevant; count by destination color by making temporary pseudo-splits:
        # We can infer the mover from move.uci() doesn't contain color; use from-square piece color
        white_moves = 0
        black_moves = 0
        for m in moves:
            p = board.piece_at(m.from_square)
            if p is None:
                continue
            if p.color == chess.WHITE:
                white_moves += 1
            else:
                black_moves += 1
        return float(white_moves - black_moves) / 100.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in major-piece (rooks+queens) mobility: legal moves originating from rooks/queens (White - Black), normalized by 50'
    try:
        moves = list(board.legal_moves)
        w = 0
        b = 0
        for m in moves:
            p = board.piece_at(m.from_square)
            if p is None:
                continue
            if p.piece_type in (chess.ROOK, chess.QUEEN):
                if p.color == chess.WHITE:
                    w += 1
                else:
                    b += 1
        return float(w - b) / 50.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net attacker-weight on kings: (sum of attacker piece-values on White king) - (same on Black king), expressed in pawn-units (divide by 100)'
    VAL = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:20000}
    try:
        pm = board.piece_map()
        white_king_sq = None
        black_king_sq = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king_sq = sq
                else:
                    black_king_sq = sq
        def attackers_value_on(square, attacker_color):
            if square is None:
                return 0
            total = 0
            for a_sq in board.attackers(attacker_color, square):
                ap = board.piece_at(a_sq)
                if ap is None:
                    continue
                total += VAL.get(ap.piece_type, 0)
            return total
        white_pressure = attackers_value_on(white_king_sq, chess.BLACK)
        black_pressure = attackers_value_on(black_king_sq, chess.WHITE)
        # return difference White_under_attack - Black_under_attack (positive means White under heavier pressure)
        return float(white_pressure - black_pressure) / 100.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net value of tactically vulnerable pieces: sum(value*(attackers-defenders) for pieces where attackers>defenders) (White - Black) in pawn units'
    VAL = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:20000}
    try:
        pm = board.piece_map()
        score_white = 0
        score_black = 0
        for sq, p in pm.items():
            own = p.color
            opp = not own
            attackers = len(board.attackers(opp, sq))
            defenders = len(board.attackers(own, sq))
            excess = attackers - defenders
            if excess > 0:
                val = VAL.get(p.piece_type, 0) * excess
                if own == chess.WHITE:
                    score_white += val
                else:
                    score_black += val
        return float(score_white - score_black) / 100.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of rooks on open or semi-open files (White - Black). Open: no pawns; Semi-open: no own pawns on file'
    try:
        files = range(8)
        # precompute pawns presence per file
        pawn_on_file_white = [0]*8
        pawn_on_file_black = [0]*8
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if p.color == chess.WHITE:
                    pawn_on_file_white[f] += 1
                else:
                    pawn_on_file_black[f] += 1
        w_count = 0
        b_count = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                if pawn_on_file_white[f] == 0 and pawn_on_file_black[f] == 0:
                    # open file
                    if p.color == chess.WHITE:
                        w_count += 1.0
                    else:
                        b_count += 1.0
                elif (p.color == chess.WHITE and pawn_on_file_white[f] == 0) or (p.color == chess.BLACK and pawn_on_file_black[f] == 0):
                    # semi-open
                    if p.color == chess.WHITE:
                        w_count += 0.5
                    else:
                        b_count += 0.5
        return float(w_count - b_count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Average closeness of non-king pieces to the board center (3.5,3.5): (Black_avg - White_avg) where smaller distance is better for activity'
    try:
        pm = board.piece_map()
        def avg_dist(color):
            s = 0.0
            c = 0
            for sq, p in pm.items():
                if p.color != color or p.piece_type == chess.KING:
                    continue
                fx = chess.square_file(sq)
                ry = chess.square_rank(sq)
                # Euclidean distance to center (3.5,3.5)
                d = ((fx - 3.5)**2 + (ry - 3.5)**2)**0.5
                s += d
                c += 1
            return s / c if c > 0 else 8.0
        w_avg = avg_dist(chess.WHITE)
        b_avg = avg_dist(chess.BLACK)
        # return Black_avg - White_avg (positive means Black pieces further from center -> worse for Black)
        return float(b_avg - w_avg)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Proximity of queens to opposing kings: (8 - min_distance for WhiteQueen->BlackKing) - (8 - min_distance for BlackQueen->WhiteKing); higher means White queens are more menacing'
    MAXD = 8.0
    try:
        pm = board.piece_map()
        white_queens = [sq for sq, p in pm.items() if p.piece_type == chess.QUEEN and p.color == chess.WHITE]
        black_queens = [sq for sq, p in pm.items() if p.piece_type == chess.QUEEN and p.color == chess.BLACK]
        white_king = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        def min_dist(queens, king_sq):
            if king_sq is None or not queens:
                return MAXD
            md = MAXD
            for q in queens:
                d = chess.square_distance(q, king_sq)
                if d < md:
                    md = d
            return float(md)
        d_wq_bk = min_dist(white_queens, black_king)
        d_bq_wk = min_dist(black_queens, white_king)
        return (MAXD - d_wq_bk) - (MAXD - d_bq_wk)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of rooks occupying the opponent-second-rank (White rooks on rank 7 / Black rooks on rank 2), normalized (White - Black)'
    try:
        w = 0
        b = 0
        for sq, p in board.piece_map().items():
            if p.piece_type != chess.ROOK:
                continue
            r = chess.square_rank(sq)
            if p.color == chess.WHITE and r == 6:  # White on 7th rank (index 6)
                w += 1
            if p.color == chess.BLACK and r == 1:  # Black on 2nd rank (index 1) from White's perspective
                b += 1
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net count of immobilized non-pawn pieces (zero legal moves from their square): (White - Black), useful to catch trapped pieces'
    try:
        moves = list(board.legal_moves)
        # map from from_square to count of moves
        from_counts = {}
        for m in moves:
            from_counts[m.from_square] = from_counts.get(m.from_square, 0) + 1
        w_trapped = 0
        b_trapped = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN or p.piece_type == chess.KING:
                continue
            cnt = from_counts.get(sq, 0)
            # if piece has zero legal moves and is not immediately capturable trivially (we still count)
            if cnt == 0:
                if p.color == chess.WHITE:
                    w_trapped += 1
                else:
                    b_trapped += 1
        return float(w_trapped - b_trapped)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net friendly-piece defense links: number of own pieces defended by another own piece (counts) (White - Black), higher = better coordination'
    try:
        pm = board.piece_map()
        w_defended = 0
        b_defended = 0
        for sq, p in pm.items():
            # count defenders from own color excluding the piece itself
            defenders = board.attackers(p.color, sq)
            # board.attackers includes squares of own pieces that attack that square
            # If there is at least one other own attacker, consider it defended.
            defender_count = sum(1 for a in defenders if a != sq and (board.piece_at(a) is not None and board.piece_at(a).color == p.color))
            if defender_count > 0:
                if p.color == chess.WHITE:
                    w_defended += 1
                else:
                    b_defended += 1
        return float(w_defended - b_defended)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Returns 1.0 if the side to move has any legal mate-in-one, else 0.0'
    try:
        for move in board.legal_moves:
            b = board.copy()
            b.push(move)
            if b.is_checkmate():
                return 1.0
    except Exception:
        return 0.0
    return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of number of rooks sitting on the opponent seventh rank (white on rank 7 => rank index 6, black on rank 2 => rank index 1)'
    wm = 0
    bm = 0
    try:
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.ROOK:
                r = chess.square_rank(sq)
                if piece.color == chess.WHITE and r == 6:
                    wm += 1
                if piece.color == chess.BLACK and r == 1:
                    bm += 1
    except Exception:
        return 0.0
    return float(wm - bm)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of count of friendly rooks behind same-file passed pawns, weighted by pawn advancement (0..1)'
    def is_passed(sq, color):
        pr = chess.square_rank(sq)
        pf = chess.square_file(sq)
        opp = not color
        if color == chess.WHITE:
            ranks = range(pr + 1, 8)
        else:
            ranks = range(pr - 1, -1, -1)
        for r in ranks:
            for f in (pf - 1, pf, pf + 1):
                if 0 <= f <= 7:
                    piece = board.piece_at(chess.square(f, r))
                    if piece is not None and piece.piece_type == chess.PAWN and piece.color == opp:
                        return False
        return True

    wm = 0.0
    bm = 0.0
    try:
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.PAWN:
                if is_passed(sq, piece.color):
                    pr = chess.square_rank(sq)
                    pf = chess.square_file(sq)
                    adv = (pr / 7.0) if piece.color == chess.WHITE else ((7 - pr) / 7.0)
                    # look for friendly rooks on same file behind pawn
                    for rsq, rpiece in board.piece_map().items():
                        if rpiece.piece_type == chess.ROOK and rpiece.color == piece.color:
                            rr = chess.square_rank(rsq)
                            rf = chess.square_file(rsq)
                            if rf == pf:
                                if (piece.color == chess.WHITE and rr < pr) or (piece.color == chess.BLACK and rr > pr):
                                    if piece.color == chess.WHITE:
                                        wm += adv
                                    else:
                                        bm += adv
                                    break
    except Exception:
        return 0.0
    return float(wm - bm)

def feature(board: chess.Board) -> float:
    'Number of legal rook moves by the side to move that give check (returns integer as float)'
    cnt = 0
    try:
        for move in board.legal_moves:
            if board.piece_at(move.from_square) and board.piece_at(move.from_square).piece_type == chess.ROOK:
                b = board.copy()
                b.push(move)
                if b.is_check():
                    cnt += 1
    except Exception:
        return 0.0
    return float(cnt)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) total score of passed pawns with clear promotion path (no opposing pieces between pawn and promotion on its file), weighted by advancement (0..1)'
    def is_passed(sq, color):
        pr = chess.square_rank(sq)
        pf = chess.square_file(sq)
        opp = not color
        if color == chess.WHITE:
            ranks = range(pr + 1, 8)
        else:
            ranks = range(pr - 1, -1, -1)
        for r in ranks:
            for f in (pf - 1, pf, pf + 1):
                if 0 <= f <= 7:
                    piece = board.piece_at(chess.square(f, r))
                    if piece is not None and piece.piece_type == chess.PAWN and piece.color == opp:
                        return False
        return True

    wm = 0.0
    bm = 0.0
    try:
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.PAWN and is_passed(sq, piece.color):
                pr = chess.square_rank(sq)
                pf = chess.square_file(sq)
                # check blocking pieces on same file between pawn and promotion
                blocking = 0
                if piece.color == chess.WHITE:
                    for r in range(pr + 1, 8):
                        p = board.piece_at(chess.square(pf, r))
                        if p is not None and p.piece_type != chess.KING:
                            blocking += 1
                else:
                    for r in range(pr - 1, -1, -1):
                        p = board.piece_at(chess.square(pf, r))
                        if p is not None and p.piece_type != chess.KING:
                            blocking += 1
                adv = (pr / 7.0) if piece.color == chess.WHITE else ((7 - pr) / 7.0)
                score = adv * (1.0 if blocking == 0 else 0.0)
                if piece.color == chess.WHITE:
                    wm += score
                else:
                    bm += score
    except Exception:
        return 0.0
    return float(wm - bm)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of pawn cover in front of each king: count friendly pawns on up-to-three squares in front of king (0..3)'
    try:
        wp = 0
        bp = 0
        pm = board.piece_map()
        # find kings
        wk_sq = None
        bk_sq = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    wk_sq = sq
                else:
                    bk_sq = sq
        def cover_for_king(kingsq, color):
            if kingsq is None:
                return 0
            kf = chess.square_file(kingsq)
            kr = chess.square_rank(kingsq)
            cnt = 0
            if color == chess.WHITE:
                target_rank = kr + 1
            else:
                target_rank = kr - 1
            for f in (kf - 1, kf, kf + 1):
                if 0 <= f <= 7 and 0 <= target_rank <= 7:
                    p = board.piece_at(chess.square(f, target_rank))
                    if p is not None and p.piece_type == chess.PAWN and p.color == color:
                        cnt += 1
            return cnt
        wp = cover_for_king(wk_sq, chess.WHITE)
        bp = cover_for_king(bk_sq, chess.BLACK)
    except Exception:
        return 0.0
    return float(wp - bp)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of safe king squares: how many adjacent squares each king could move to that are not attacked by opponent (normalized 0..8)'
    def safe_moves_for_king(kingsq, color):
        if kingsq is None:
            return 0.0
        opp = not color
        kf = chess.square_file(kingsq)
        kr = chess.square_rank(kingsq)
        cnt = 0
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                if df == 0 and dr == 0:
                    continue
                f = kf + df
                r = kr + dr
                if 0 <= f <= 7 and 0 <= r <= 7:
                    target = chess.square(f, r)
                    p = board.piece_at(target)
                    # cannot move onto own piece
                    if p is not None and p.color == color:
                        continue
                    # square must not be attacked by opponent
                    try:
                        if board.is_attacked_by(opp, target):
                            continue
                    except Exception:
                        continue
                    cnt += 1
        return float(cnt)
    try:
        pm = board.piece_map()
        wk_sq = None
        bk_sq = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    wk_sq = sq
                else:
                    bk_sq = sq
        w_safe = safe_moves_for_king(wk_sq, chess.WHITE)
        b_safe = safe_moves_for_king(bk_sq, chess.BLACK)
    except Exception:
        return 0.0
    return float(w_safe - b_safe)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of coordination metric: for the most advanced passed pawn of each side, 1 - (min rook Manhattan distance / 8). If no passed pawn, contributes 0.'
    def is_passed(sq, color):
        pr = chess.square_rank(sq)
        pf = chess.square_file(sq)
        opp = not color
        if color == chess.WHITE:
            ranks = range(pr + 1, 8)
        else:
            ranks = range(pr - 1, -1, -1)
        for r in ranks:
            for f in (pf - 1, pf, pf + 1):
                if 0 <= f <= 7:
                    piece = board.piece_at(chess.square(f, r))
                    if piece is not None and piece.piece_type == chess.PAWN and piece.color == opp:
                        return False
        return True

    try:
        passed_white = []
        passed_black = []
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                if p.color == chess.WHITE and is_passed(sq, chess.WHITE):
                    passed_white.append(sq)
                if p.color == chess.BLACK and is_passed(sq, chess.BLACK):
                    passed_black.append(sq)
        def best_coord(passeds, color):
            if not passeds:
                return 0.0
            rooks = [sq for sq, p in board.piece_map().items() if p.piece_type == chess.ROOK and p.color == color]
            if not rooks:
                return 0.0
            # choose most advanced passed pawn
            if color == chess.WHITE:
                best_p = max(passeds, key=lambda s: chess.square_rank(s))
            else:
                best_p = min(passeds, key=lambda s: chess.square_rank(s))
            mind = min(chess.square_distance(best_p, r) for r in rooks)
            return 1.0 - (mind / 8.0)
        wscore = best_coord(passed_white, chess.WHITE)
        bscore = best_coord(passed_black, chess.BLACK)
    except Exception:
        return 0.0
    return float(wscore - bscore)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of count of passed pawns that have a friendly rook directly behind on the same file and no enemy rook/queen between pawn and promotion (simple open-file rook support count)'
    def is_passed(sq, color):
        pr = chess.square_rank(sq)
        pf = chess.square_file(sq)
        opp = not color
        if color == chess.WHITE:
            ranks = range(pr + 1, 8)
        else:
            ranks = range(pr - 1, -1, -1)
        for r in ranks:
            for f in (pf - 1, pf, pf + 1):
                if 0 <= f <= 7:
                    piece = board.piece_at(chess.square(f, r))
                    if piece is not None and piece.piece_type == chess.PAWN and piece.color == opp:
                        return False
        return True

    wm = 0
    bm = 0
    try:
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN and is_passed(sq, p.color):
                pf = chess.square_file(sq)
                pr = chess.square_rank(sq)
                friendly_rook_behind = False
                for rsq, rp in board.piece_map().items():
                    if rp.piece_type == chess.ROOK and rp.color == p.color and chess.square_file(rsq) == pf:
                        rr = chess.square_rank(rsq)
                        if (p.color == chess.WHITE and rr < pr) or (p.color == chess.BLACK and rr > pr):
                            friendly_rook_behind = True
                            break
                if not friendly_rook_behind:
                    continue
                # check no enemy rook/queen between pawn and promotion on that file
                blocked = False
                if p.color == chess.WHITE:
                    rng = range(pr + 1, 8)
                else:
                    rng = range(pr - 1, -1, -1)
                for r in rng:
                    piece_between = board.piece_at(chess.square(pf, r))
                    if piece_between is not None and piece_between.color != p.color and piece_between.piece_type in (chess.ROOK, chess.QUEEN):
                        blocked = True
                        break
                if not blocked:
                    if p.color == chess.WHITE:
                        wm += 1
                    else:
                        bm += 1
    except Exception:
        return 0.0
    return float(wm - bm)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of number of legal captures (for each side) that are "safe": after the capture the capturing square is not attacked by an opponent (counts whole-board, not only side-to-move)'
    def safe_captures_for_color(col):
        cnt = 0
        bcopy = board.copy()
        bcopy.turn = col
        try:
            for move in list(bcopy.legal_moves):
                if move.drop is not None:
                    continue
                if bcopy.is_capture(move):
                    b2 = bcopy.copy()
                    b2.push(move)
                    opp = not col
                    # if the destination square is attacked by opponent, capture is unsafe
                    if not b2.is_attacked_by(opp, move.to_square):
                        cnt += 1
        except Exception:
            return 0
        return cnt
    try:
        w = safe_captures_for_color(chess.WHITE)
        b = safe_captures_for_color(chess.BLACK)
    except Exception:
        return 0.0
    return float(w - b)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of advancement of passed pawns: sum of ranks-to-promotion normalized (0..1 per pawn)'
    import chess
    white_score = 0.0
    black_score = 0.0
    pieces = board.piece_map()
    # find pawn squares by color
    pawn_squares = [(sq, p) for sq, p in pieces.items() if p.piece_type == chess.PAWN]
    # helper to detect passed pawn
    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            # any black pawn on same or adjacent file with rank greater (ahead)
            for sq2, p2 in pawn_squares:
                if p2.color == chess.BLACK:
                    f2 = chess.square_file(sq2)
                    r2 = chess.square_rank(sq2)
                    if abs(f2 - f) <= 1 and r2 > r:
                        return False
            return True
        else:
            for sq2, p2 in pawn_squares:
                if p2.color == chess.WHITE:
                    f2 = chess.square_file(sq2)
                    r2 = chess.square_rank(sq2)
                    if abs(f2 - f) <= 1 and r2 < r:
                        return False
            return True
    for sq, p in pawn_squares:
        r = chess.square_rank(sq)
        if p.color == chess.WHITE:
            if is_passed(sq, chess.WHITE):
                # normalized advancement: 0 at start rank 1 (rank index 1) to 1 at rank 7 (index 7)
                adv = (r) / 7.0
                white_score += adv
        else:
            if is_passed(sq, chess.BLACK):
                adv = (7 - r) / 7.0
                black_score += adv
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) counting rooks that are directly behind a pawn on the same file with no pieces between (supports promotion)'
    import chess
    pieces = board.piece_map()
    score_w = 0.0
    score_b = 0.0
    # iterate pawns
    for sq, p in list(pieces.items()):
        if p.piece_type != chess.PAWN:
            continue
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        color = p.color
        # look for own rook on same file behind the pawn (towards own side)
        found = False
        for sq2, p2 in pieces.items():
            if p2.piece_type == chess.ROOK and p2.color == color and chess.square_file(sq2) == f:
                r2 = chess.square_rank(sq2)
                if color == chess.WHITE and r2 < r:
                    # check intervening squares between r2+1..r-1
                    blocked = False
                    for rr in range(r2 + 1, r):
                        if (f + rr * 8) in pieces:
                            blocked = True
                            break
                    if not blocked:
                        found = True
                        break
                if color == chess.BLACK and r2 > r:
                    blocked = False
                    for rr in range(r + 1, r2):
                        if (f + rr * 8) in pieces:
                            blocked = True
                            break
                    if not blocked:
                        found = True
                        break
        if found:
            if color == chess.WHITE:
                score_w += 1.0
            else:
                score_b += 1.0
    return float(score_w - score_b)

def feature(board: chess.Board) -> float:
    'Average (over passed pawns) of defender_king_distance - attacker_king_distance to that pawn\'s promotion square (positive favors the pawn side)'
    import chess, math
    pieces = board.piece_map()
    # find kings
    white_king_sq = None
    black_king_sq = None
    for sq, p in pieces.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                white_king_sq = sq
            else:
                black_king_sq = sq
    if white_king_sq is None or black_king_sq is None:
        return 0.0
    pawn_squares = [(sq, p) for sq, p in pieces.items() if p.piece_type == chess.PAWN]
    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        for sq2, p2 in pawn_squares:
            if p2.color != color:
                f2 = chess.square_file(sq2)
                r2 = chess.square_rank(sq2)
                if abs(f2 - f) <= 1:
                    if color == chess.WHITE and r2 > r:
                        return False
                    if color == chess.BLACK and r2 < r:
                        return False
        return True
    vals = []
    for sq, p in pawn_squares:
        if not is_passed(sq, p.color):
            continue
        f = chess.square_file(sq)
        # promotion square
        if p.color == chess.WHITE:
            prom = chess.square(f, 7)
            attacker_k = white_king_sq
            defender_k = black_king_sq
        else:
            prom = chess.square(f, 0)
            attacker_k = black_king_sq
            defender_k = white_king_sq
        if attacker_k is None or defender_k is None:
            continue
        da = chess.square_distance(attacker_k, prom)
        dd = chess.square_distance(defender_k, prom)
        vals.append(float(dd - da))
    if not vals:
        return 0.0
    return sum(vals) / len(vals)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) counting rooks on the opponent\'s seventh rank (one point each)'
    import chess
    pieces = board.piece_map()
    white_cnt = 0.0
    black_cnt = 0.0
    for sq, p in pieces.items():
        if p.piece_type != chess.ROOK:
            continue
        r = chess.square_rank(sq)
        if p.color == chess.WHITE and r == 6:
            white_cnt += 1.0
        if p.color == chess.BLACK and r == 1:
            black_cnt += 1.0
    return float(white_cnt - black_cnt)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) counting passed pawns that have a rook "behind" them without blockers AND the rook is on the same side (strong support)'
    import chess
    pieces = board.piece_map()
    pawn_squares = [(sq, p) for sq, p in pieces.items() if p.piece_type == chess.PAWN]
    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        for sq2, p2 in pawn_squares:
            if p2.color != color:
                f2 = chess.square_file(sq2)
                r2 = chess.square_rank(sq2)
                if abs(f2 - f) <= 1:
                    if color == chess.WHITE and r2 > r:
                        return False
                    if color == chess.BLACK and r2 < r:
                        return False
        return True
    w = 0.0
    b = 0.0
    for sq, p in pawn_squares:
        if not is_passed(sq, p.color):
            continue
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        color = p.color
        # require an own rook on same file directly behind (one or more squares) with no blockers
        for sq2, p2 in pieces.items():
            if p2.piece_type == chess.ROOK and p2.color == color and chess.square_file(sq2) == f:
                r2 = chess.square_rank(sq2)
                if color == chess.WHITE and r2 < r:
                    blocked = False
                    for rr in range(r2 + 1, r):
                        if (f + rr * 8) in pieces:
                            blocked = True
                            break
                    if not blocked:
                        w += 1.0
                        break
                if color == chess.BLACK and r2 > r:
                    blocked = False
                    for rr in range(r + 1, r2):
                        if (f + rr * 8) in pieces:
                            blocked = True
                            break
                    if not blocked:
                        b += 1.0
                        break
    return float(w - b)

def feature(board: chess.Board) -> float:
    '1 if White has any immediate promotion move, -1 if Black has any immediate promotion move, 0 otherwise'
    import chess
    white_has = False
    black_has = False
    for mv in board.legal_moves:
        if mv.promotion is not None:
            # move.promotion is int piece type
            # determine mover color
            mover = board.piece_at(mv.from_square)
            if mover is None:
                continue
            if mover.color == chess.WHITE:
                white_has = True
            else:
                black_has = True
            if white_has and black_has:
                break
    if white_has and not black_has:
        return 1.0
    if black_has and not white_has:
        return -1.0
    return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of the Manhattan distance from the king to the nearest enemy passed pawn (smaller distance is better for the king that can stop it)'
    import chess
    pieces = board.piece_map()
    pawn_squares = [(sq, p) for sq, p in pieces.items() if p.piece_type == chess.PAWN]
    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        for sq2, p2 in pawn_squares:
            if p2.color != color:
                f2 = chess.square_file(sq2)
                r2 = chess.square_rank(sq2)
                if abs(f2 - f) <= 1:
                    if color == chess.WHITE and r2 > r:
                        return False
                    if color == chess.BLACK and r2 < r:
                        return False
        return True
    # find kings
    white_king = None
    black_king = None
    for sq, p in pieces.items():
        if p.piece_type == chess.KING:
            if p.color == chess.WHITE:
                white_king = sq
            else:
                black_king = sq
    if white_king is None or black_king is None:
        return 0.0
    # find nearest enemy passed pawn for each king
    import math
    def nearest_dist_to_enemy_passed(king_sq, enemy_color):
        best = None
        for sq, p in pawn_squares:
            if p.color == enemy_color and is_passed(sq, enemy_color):
                d = chess.square_distance(king_sq, sq)
                if best is None or d < best:
                    best = d
        return best if best is not None else 100.0
    white_nearest = nearest_dist_to_enemy_passed(white_king, chess.BLACK)
    black_nearest = nearest_dist_to_enemy_passed(black_king, chess.WHITE)
    # positive means White king is closer to stopping Black's passed pawn than Black king is to stopping White's
    return float(black_nearest - white_nearest)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of rook centralization: sum of 1/(1+euclidean_distance_to_center) for rooks'
    import chess, math
    pieces = board.piece_map()
    def rook_score(sq):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        # center is between d4/e5: use (3.5,3.5)
        dx = (f - 3.5)
        dy = (r - 3.5)
        d = math.hypot(dx, dy)
        return 1.0 / (1.0 + d)
    w = 0.0
    b = 0.0
    for sq, p in pieces.items():
        if p.piece_type == chess.ROOK:
            if p.color == chess.WHITE:
                w += rook_score(sq)
            else:
                b += rook_score(sq)
    return float(w - b)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) of rook mobility measured as the number of rook legal moves available to that side'
    import chess
    w_moves = 0
    b_moves = 0
    # iterate legal moves and count rook moves by mover color
    for mv in board.legal_moves:
        from_sq = mv.from_square
        piece = board.piece_at(from_sq)
        if piece is None:
            continue
        if piece.piece_type != chess.ROOK:
            continue
        if piece.color == chess.WHITE:
            w_moves += 1
        else:
            b_moves += 1
    return float(w_moves - b_moves)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) scoring passed pawns whose promotion square is NOT attacked by an enemy rook (1 if safe, -1 if attacked)'
    import chess
    pieces = board.piece_map()
    pawn_squares = [(sq, p) for sq, p in pieces.items() if p.piece_type == chess.PAWN]
    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        for sq2, p2 in pawn_squares:
            if p2.color != color:
                f2 = chess.square_file(sq2)
                r2 = chess.square_rank(sq2)
                if abs(f2 - f) <= 1:
                    if color == chess.WHITE and r2 > r:
                        return False
                    if color == chess.BLACK and r2 < r:
                        return False
        return True
    score_w = 0.0
    score_b = 0.0
    for sq, p in pawn_squares:
        if not is_passed(sq, p.color):
            continue
        f = chess.square_file(sq)
        prom_sq = chess.square(f, 7) if p.color == chess.WHITE else chess.square(f, 0)
        enemy = chess.BLACK if p.color == chess.WHITE else chess.WHITE
        # check if any enemy rook attacks promotion square
        attacked = False
        for attacker_sq in board.attackers(enemy, prom_sq):
            ap = board.piece_at(attacker_sq)
            if ap is not None and ap.piece_type == chess.ROOK and ap.color == enemy:
                attacked = True
                break
        if p.color == chess.WHITE:
            score_w += (0.0 if attacked else 1.0)
        else:
            score_b += (0.0 if attacked else 1.0)
    return float(score_w - score_b)

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in number of friendly pawns forming a basic pawn shield in front of the king (files king_file-1..king_file+1, one rank ahead). Higher favors the side with pawns shielding its king.'
    try:
        pm = board.piece_map()
        def shield_count(color):
            king_sq = None
            for sq, p in pm.items():
                if p.piece_type == chess.KING and p.color == color:
                    king_sq = sq
                    break
            if king_sq is None:
                return 0
            kfile = chess.square_file(king_sq)
            krank = chess.square_rank(king_sq)
            count = 0
            # direction: white pawns are forward by +1 rank, black by -1 rank
            forward = 1 if color == chess.WHITE else -1
            target_rank = krank + forward
            if 0 <= target_rank <= 7:
                for df in (-1, 0, 1):
                    f = kfile + df
                    if 0 <= f <= 7:
                        sq = chess.square(f, target_rank)
                        p = pm.get(sq)
                        if p is not None and p.piece_type == chess.PAWN and p.color == color:
                            count += 1
            return count
        return float(shield_count(chess.WHITE) - shield_count(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in number of pawns on the 7th rank (i.e., one square from promotion).'
    try:
        pm = board.piece_map()
        w = 0
        b = 0
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                rank = chess.square_rank(sq)
                if p.color == chess.WHITE and rank == 6:
                    w += 1
                if p.color == chess.BLACK and rank == 1:
                    b += 1
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in count of bishops that sit on the two long diagonals (a1-h8 or h1-a8). Long-diagonal bishops often control promotion routes and long lines.'
    try:
        pm = board.piece_map()
        def on_long_diag(sq):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            return f == r or (f + r) == 7
        w = 0
        b = 0
        for sq, p in pm.items():
            if p.piece_type == chess.BISHOP:
                if on_long_diag(sq):
                    if p.color == chess.WHITE:
                        w += 1
                    else:
                        b += 1
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in number of open files (no pawns) that contain a rook or queen of that side (simple measure of heavy-piece access to open files).'
    try:
        pm = board.piece_map()
        # precompute pawns per file
        pawn_on_file = [False]*8
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                pawn_on_file[chess.square_file(sq)] = True
        w = 0
        b = 0
        for sq, p in pm.items():
            if not pawn_on_file[chess.square_file(sq)] and (p.piece_type == chess.ROOK or p.piece_type == chess.QUEEN):
                if p.color == chess.WHITE:
                    w += 1
                else:
                    b += 1
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in number of enemy pawns that are directly attacked by at least one bishop (measures how many pawns are tactical targets for bishops).'
    try:
        pm = board.piece_map()
        white_targets = 0
        black_targets = 0
        # iterate enemy pawns and see if any bishop of the opposite color attacks them
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                if p.color == chess.BLACK:
                    attackers = board.attackers(chess.WHITE, sq)
                    for att in attackers:
                        ap = pm.get(att)
                        if ap is not None and ap.piece_type == chess.BISHOP and ap.color == chess.WHITE:
                            white_targets += 1
                            break
                else:
                    attackers = board.attackers(chess.BLACK, sq)
                    for att in attackers:
                        ap = pm.get(att)
                        if ap is not None and ap.piece_type == chess.BISHOP and ap.color == chess.BLACK:
                            black_targets += 1
                            break
        return float(white_targets - black_targets)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Support proximity: (1/(1+min_distance_white)) - (1/(1+min_distance_black)) where min_distance_* is Manhattan distance from that side\'s king to its nearest pawn. Higher means White king is relatively closer to its pawns (favors supporting passed/advanced pawns).'
    try:
        pm = board.piece_map()
        def min_king_pawn_dist(color):
            king_sq = None
            pawns = []
            for sq, p in pm.items():
                if p.piece_type == chess.KING and p.color == color:
                    king_sq = sq
                if p.piece_type == chess.PAWN and p.color == color:
                    pawns.append(sq)
            if king_sq is None or not pawns:
                return 100.0
            min_d = min(chess.square_distance(king_sq, psq) for psq in pawns)
            return float(min_d)
        wd = min_king_pawn_dist(chess.WHITE)
        bd = min_king_pawn_dist(chess.BLACK)
        return (1.0 / (1.0 + wd)) - (1.0 / (1.0 + bd))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in count of advanced isolated pawns: isolated pawns (no friendly pawns on adjacent files) that are on rank >=5 (white) or rank <=3 (black). These are often weaknesses/strengths in endgames.'
    try:
        pm = board.piece_map()
        white_count = 0
        black_count = 0
        # precompute pawn files for each color
        white_pawn_files = set()
        black_pawn_files = set()
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                if p.color == chess.WHITE:
                    white_pawn_files.add(chess.square_file(sq))
                else:
                    black_pawn_files.add(chess.square_file(sq))
        for sq, p in pm.items():
            if p.piece_type != chess.PAWN:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                if r >= 4:  # 5th rank or beyond
                    if (f-1 not in white_pawn_files) and (f+1 not in white_pawn_files):
                        white_count += 1
            else:
                if r <= 3:  # black advanced to 4th rank or beyond (from black perspective)
                    if (f-1 not in black_pawn_files) and (f+1 not in black_pawn_files):
                        black_count += 1
        return float(white_count - black_count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in non-pawn enemy piece pressure around the king: (# of white pieces (non-pawn) attacking squares near black king) - (# of black pieces attacking squares near white king). Positive favors White.'
    try:
        pm = board.piece_map()
        def pressure_on_king(king_color):
            # count unique enemy non-pawn attackers to squares within Manhattan distance <=2 of king
            king_sq = None
            for sq, p in pm.items():
                if p.piece_type == chess.KING and p.color == king_color:
                    king_sq = sq
                    break
            if king_sq is None:
                return 0
            attackers_set = set()
            kr = chess.square_rank(king_sq)
            kf = chess.square_file(king_sq)
            enemy = not king_color
            for rf in range(kf-2, kf+3):
                for rr in range(kr-2, kr+3):
                    if 0 <= rf <= 7 and 0 <= rr <= 7:
                        sq = chess.square(rf, rr)
                        att = board.attackers(enemy, sq)
                        for a in att:
                            ap = pm.get(a)
                            if ap is not None and ap.piece_type != chess.PAWN and ap.color == enemy:
                                attackers_set.add(a)
            return len(attackers_set)
        pressure_on_white = pressure_on_king(chess.WHITE)
        pressure_on_black = pressure_on_king(chess.BLACK)
        return float(pressure_on_black - pressure_on_white)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (Black_blockades - White_blockades) where a pawn is considered blockaded if the square directly in front of it is occupied by an enemy piece. Positive means Black has more blockaded pawns (favors White).'
    try:
        pm = board.piece_map()
        white_block = 0
        black_block = 0
        for sq, p in pm.items():
            if p.piece_type != chess.PAWN:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                ahead_r = r + 1
                if ahead_r <= 7:
                    ahead_sq = chess.square(f, ahead_r)
                    occ = pm.get(ahead_sq)
                    if occ is not None and occ.color == chess.BLACK:
                        white_block += 1
            else:
                ahead_r = r - 1
                if ahead_r >= 0:
                    ahead_sq = chess.square(f, ahead_r)
                    occ = pm.get(ahead_sq)
                    if occ is not None and occ.color == chess.WHITE:
                        black_block += 1
        return float(black_block - white_block)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Normalized mobility difference: (White legal moves - Black legal moves) / 10. Uses copies of the board to evaluate mobility for the side not to move as well. Positive favors White.'
    try:
        # white mobility
        bcopy = board.copy()
        bcopy.turn = chess.WHITE
        w_moves = sum(1 for _ in bcopy.legal_moves)
        bcopy.turn = chess.BLACK
        b_moves = sum(1 for _ in bcopy.legal_moves)
        return float((w_moves - b_moves) / 10.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Normalized mobility difference: (white legal moves - black legal moves) / 60, clipped'
    import chess
    try:
        b = board.copy()
        b.turn = chess.WHITE
        white_moves = sum(1 for _ in b.legal_moves)
        b.turn = chess.BLACK
        black_moves = sum(1 for _ in b.legal_moves)
        result = (white_moves - black_moves) / 60.0
        # clip to a reasonable range
        if result != result or result == float('inf') or result == float('-inf'):
            return 0.0
        return float(max(-1.0, min(1.0, result)))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Imbalance of direct attackers on kings: (#white attackers on black king) - (#black attackers on white king)'
    import chess
    try:
