def feature(board: chess.Board) -> float:
    'Passed-pawn advancement score: sum of squared advancement for passed pawns (white - black), range [-1,1]'
    import chess
    try:
        km = board.piece_map()
        white_pawns = [sq for sq, p in km.items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        black_pawns = [sq for sq, p in km.items() if p.piece_type == chess.PAWN and p.color == chess.BLACK]
        black_pawn_set = set(black_pawns)
        white_pawn_set = set(white_pawns)
        def is_passed_white(sq):
            rf = chess.square_file(sq)
            rr = chess.square_rank(sq)
            for f in (rf-1, rf, rf+1):
                if 0 <= f <= 7:
                    for r in range(rr+1, 8):
                        sq2 = chess.square(f, r)
                        if sq2 in black_pawn_set:
                            return False
            return True
        def is_passed_black(sq):
            rf = chess.square_file(sq)
            rr = chess.square_rank(sq)
            for f in (rf-1, rf, rf+1):
                if 0 <= f <= 7:
                    for r in range(0, rr):
                        sq2 = chess.square(f, r)
                        if sq2 in white_pawn_set:
                            return False
            return True
        white_score = 0.0
        for sq in white_pawns:
            if is_passed_white(sq):
                r = chess.square_rank(sq)
                adv = (r / 7.0)
                white_score += adv * adv
        black_score = 0.0
        for sq in black_pawns:
            if is_passed_black(sq):
                r = chess.square_rank(sq)
                adv = ((7 - r) / 7.0)
                black_score += adv * adv
        # normalize roughly into [-1,1]
        val = white_score - black_score
        return float(max(-1.0, min(1.0, val)))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Under-defended pieces imbalance: (black under-defended pieces) - (white under-defended pieces), positive favors White'
    import chess
    try:
        pm = board.piece_map()
        white_under = 0
        black_under = 0
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                continue
            attackers = len(board.attackers(not p.color, sq))
            defenders = len(board.attackers(p.color, sq))
            if attackers > 0 and defenders < attackers:
                if p.color == chess.WHITE:
                    white_under += 1
                else:
                    black_under += 1
        return float(black_under - white_under)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn shield size in front of the kings: (white pawn shield count) - (black pawn shield count), counts pawns on 3-file window 1-2 ranks ahead'
    import chess
    try:
        pm = board.piece_map()
        white_king = None
        black_king = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        def shield_count(king_sq, color):
            if king_sq is None:
                return 0
            f = chess.square_file(king_sq)
            r = chess.square_rank(king_sq)
            cnt = 0
            if color == chess.WHITE:
                ranks = [r+1, r+2]
            else:
                ranks = [r-1, r-2]
            for rf in (f-1, f, f+1):
                if 0 <= rf <= 7:
                    for rr in ranks:
                        if 0 <= rr <= 7:
                            sq = chess.square(rf, rr)
                            p = board.piece_at(sq)
                            if p is not None and p.piece_type == chess.PAWN and p.color == color:
                                cnt += 1
            return cnt
        w_shield = shield_count(white_king, chess.WHITE)
        b_shield = shield_count(black_king, chess.BLACK)
        return float(w_shield - b_shield)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Bishop pair plus mobility: (white_score) - (black_score); score = 0.5*#bishops + mobility/20'
    import chess
    try:
        pm = board.piece_map()
        dirs = ((1,1),(1,-1),(-1,1),(-1,-1))
        def bishop_mobility_and_count(color):
            count = 0
            mobility = 0
            for sq, p in pm.items():
                if p.piece_type == chess.BISHOP and p.color == color:
                    count += 1
                    f = chess.square_file(sq)
                    r = chess.square_rank(sq)
                    for df, dr in dirs:
                        ff = f + df
                        rr = r + dr
                        while 0 <= ff <= 7 and 0 <= rr <= 7:
                            s2 = chess.square(ff, rr)
                            mobility += 1
                            if board.piece_at(s2) is not None:
                                break
                            ff += df
                            rr += dr
            return count, mobility
        w_count, w_mob = bishop_mobility_and_count(chess.WHITE)
        b_count, b_mob = bishop_mobility_and_count(chess.BLACK)
        w_score = 0.5 * w_count + (w_mob / 20.0)
        b_score = 0.5 * b_count + (b_mob / 20.0)
        return float(w_score - b_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rooks on open files difference: (#white rooks on fully open files) - (#black rooks on fully open files)'
    import chess
    try:
