def feature(board: chess.Board) -> float:
    'Queen centrality: (sum over White queens of 8 - min_distance_to d4,e4,d5,e5) minus same for Black (higher => queen(s) closer to center)'
    try:
        centers = [chess.parse_square(s) for s in ('d4', 'e4', 'd5', 'e5')]
        pm = board.piece_map()
        w_score = 0
        b_score = 0
        for sq, pc in pm.items():
            if pc.piece_type == chess.QUEEN:
                min_d = min(chess.square_distance(sq, c) for c in centers)
                score = max(0, 8 - min_d)  # bounded
                if pc.color == chess.WHITE:
                    w_score += score
                else:
                    b_score += score
        return float(w_score - b_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn structural weakness score difference: (White weaknesses) - (Black weaknesses), where weaknesses = isolated_pawns + doubled_pawns_count (per-file extra pawns counted)'
    try:
        pm = board.piece_map()
        # collect pawn files
        w_files = {f: [] for f in range(8)}
        b_files = {f: [] for f in range(8)}
        for sq, pc in pm.items():
            if pc.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                if pc.color == chess.WHITE:
                    w_files[f].append(sq)
                else:
                    b_files[f].append(sq)
        def weakness_score(files_map):
            doubled = 0
            isolated = 0
            for f in range(8):
                cnt = len(files_map[f])
                if cnt > 1:
                    doubled += (cnt - 1)  # extra pawns on file count as doubled/stacked weaknesses
                if cnt >= 1:
                    left = len(files_map.get(f-1, [])) if f-1 in files_map else 0
                    right = len(files_map.get(f+1, [])) if f+1 in files_map else 0
                    if left == 0 and right == 0:
                        isolated += cnt
            return doubled + isolated
        w_weak = weakness_score(w_files)
        b_weak = weakness_score(b_files)
        return float(w_weak - b_weak)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Advanced knight outpost count difference: number of knights on enemy half (White ranks 5-8, Black ranks 1-4) that are not attacked by any enemy pawn (White - Black)'
    try:
        pm = board.piece_map()
        w_outposts = 0
        b_outposts = 0
        for sq, pc in pm.items():
            if pc.piece_type == chess.KNIGHT:
                rank = chess.square_rank(sq)
                if pc.color == chess.WHITE:
                    # enemy half for White is ranks 4..7 (0-indexed 4-7)
                    if rank >= 4:
                        # check if any black pawn attacks this square
                        attackers = board.attackers(chess.BLACK, sq)
                        pawn_attacker = False
                        for a in attackers:
                            p = board.piece_at(a)
                            if p is not None and p.piece_type == chess.PAWN:
                                pawn_attacker = True
                                break
                        if not pawn_attacker:
                            w_outposts += 1
                else:
                    if rank <= 3:
                        attackers = board.attackers(chess.WHITE, sq)
                        pawn_attacker = False
                        for a in attackers:
                            p = board.piece_at(a)
                            if p is not None and p.piece_type == chess.PAWN:
                                pawn_attacker = True
                                break
                        if not pawn_attacker:
                            b_outposts += 1
        return float(w_outposts - b_outposts)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King danger differential: weighted sum of enemy piece proximity to kings (positive -> Black king more in danger)'
    try:
        import chess
        VAL = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        pm = board.piece_map()
        white_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.WHITE), None)
        black_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.BLACK), None)
        def threat_to(king_sq, king_color):
            if king_sq is None: 
                return 0.0
            s = 0.0
            for sq,p in pm.items():
                if p.color != king_color:
                    dist = chess.square_distance(sq, king_sq)
                    s += VAL.get(p.piece_type,0.0) / (dist + 1)
            return s
        white_king_threat = threat_to(white_king_sq, chess.WHITE)
        black_king_threat = threat_to(black_king_sq, chess.BLACK)
        # positive when black king is under more threat (good for White)
        return float(black_king_threat - white_king_threat)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn-shield solidity difference around kings: counts friendly pawns in a 3-file by 2-rank box in front of king (white - black)'
    try:
        import chess
        pm = board.piece_map()
        def shield_count(king_sq, color):
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            cnt = 0
            if color == chess.WHITE:
                ranks = range(kr+1, min(kr+3,8))
            else:
                ranks = range(max(kr-2,0), kr)
            for rf in range(max(kf-1,0), min(kf+2,8)):
                for r in ranks:
                    sq = chess.square(rf, r)
                    p = board.piece_at(sq)
                    if p and p.piece_type==chess.PAWN and p.color==color:
                        cnt += 1
            return float(cnt)
        white_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.WHITE), None)
        black_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.BLACK), None)
        return float(shield_count(white_king_sq, chess.WHITE) - shield_count(black_king_sq, chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rooks on open or semi-open files (open=1.0, semi-open=0.5) difference (white - black)'
    try:
        import chess
        pm = board.piece_map()
        def rook_file_score(color):
            score = 0.0
            for sq,p in pm.items():
                if p.piece_type==chess.ROOK and p.color==color:
                    f = chess.square_file(sq)
                    pawns_on_file = [sq2 for sq2,p2 in pm.items() if p2.piece_type==chess.PAWN and chess.square_file(sq2)==f]
                    if len(pawns_on_file)==0:
                        score += 1.0
                    else:
                        # semi-open if no friendly pawns on file
                        has_friendly = any(p2.color==color for _,p2 in [(s,pm[s]) for s in pawns_on_file])
                        if not has_friendly:
                            score += 0.5
            return score
        return float(rook_file_score(chess.WHITE) - rook_file_score(chess.BLACK))
    except Exception:
        return 0.0

