def feature(board: chess.Board) -> float:
    'Outposted knights difference: knights on opponent half, not attacked by enemy pawns, and defended (white - black)'
    try:
        import chess
        pm = board.piece_map()
        def count_outposts(color):
            cnt = 0.0
            for sq,p in pm.items():
                if p.piece_type==chess.KNIGHT and p.color==color:
                    r = chess.square_rank(sq)
                    # on opponent half
                    if color==chess.WHITE and r < 4: 
                        continue
                    if color==chess.BLACK and r > 3:
                        continue
                    # attacked by enemy pawns?
                    attackers = list(board.attackers(not color, sq))
                    attacked_by_pawn = any(board.piece_at(a).piece_type==chess.PAWN for a in attackers)
                    if attacked_by_pawn:
                        continue
                    # defended by at least one friendly piece
                    defenders = len(list(board.attackers(color, sq)))
                    if defenders >= 1:
                        cnt += 1.0
            return cnt
        return float(count_outposts(chess.WHITE) - count_outposts(chess.BLACK))
    except Exception:
        return 0.0

