            if p.color == chess.WHITE:
                w_sum += values.get(p.piece_type, 0.0)
            else:
                b_sum += values.get(p.piece_type, 0.0)
    return float((w_sum - b_sum) / 100.0)

def feature(board: chess.Board) -> float:
    'King mobility difference: (legal king moves for White) - (legal king moves for Black)'
    try:
        # helper to count legal king moves for a given color
        def king_moves_for(color):
            b = board.copy()
            b.turn = color
            count = 0
            for m in b.legal_moves:
                # safe: move.from_square for python-chess Move
                if b.piece_type_at(m.from_square) == chess.KING:
                    count += 1
            return count
        white_k = king_moves_for(chess.WHITE)
        black_k = king_moves_for(chess.BLACK)
        return float(white_k - black_k)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Proximity attack potential: weighted sum of allied pieces within distance<=2 of enemy king (white - black), weights ~ material'
    try:
        piece_weights = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
        pm = board.piece_map()
        # find kings
        white_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.WHITE), None)
        black_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.BLACK), None)
        def proximity_sum(color, target_king_sq):
            if target_king_sq is None:
                return 0.0
            s = 0.0
            for sq,p in pm.items():
                if p.color==color and p.piece_type!=chess.KING:
                    if chess.square_distance(sq, target_king_sq) <= 2:
                        s += piece_weights.get(p.piece_type,0.0)
            return s
        white_score = proximity_sum(chess.WHITE, black_king_sq)
        black_score = proximity_sum(chess.BLACK, white_king_sq)
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King adjacent vulnerability: (# of adjacent squares to White king attacked by Black and not defended by White) - (mirror for Black)'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.WHITE), None)
        black_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.BLACK), None)
        def vuln(king_sq, opp_color, own_color):
            if king_sq is None:
                return 0.0
            c = 0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            for df in (-1,0,1):
                for dr in (-1,0,1):
                    if df==0 and dr==0:
                        continue
                    f = kf + df
                    r = kr + dr
                    if 0 <= f <= 7 and 0 <= r <= 7:
                        sq = chess.square(f,r)
                        attacked_by_opp = board.is_attacked_by(opp_color, sq)
                        attacked_by_own = board.is_attacked_by(own_color, sq)
                        if attacked_by_opp and not attacked_by_own:
                            c += 1
            return float(c)
        v_white = vuln(white_king_sq, chess.BLACK, chess.WHITE)
        v_black = vuln(black_king_sq, chess.WHITE, chess.BLACK)
        return float(v_white - v_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn advancement score: sum of advanced passed-pawn ranks for White minus Black (higher is better for White)'
    try:
        pm = board.piece_map()
        def is_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            # for white: no black pawn on same or adjacent files with higher rank
            if color==chess.WHITE:
                for bf,bp in pm.items():
                    if bp.piece_type==chess.PAWN and bp.color==chess.BLACK:
                        bf_file = chess.square_file(bf)
                        if abs(bf_file - f) <= 1 and chess.square_rank(bf) > r:
                            return False
                return True
            else:
                for wf,wpp in pm.items():
                    if wpp.piece_type==chess.PAWN and wpp.color==chess.WHITE:
                        wf_file = chess.square_file(wf)
                        if abs(wf_file - f) <= 1 and chess.square_rank(wf) < r:
                            return False
                return True
        white_score = 0.0
        black_score = 0.0
        for sq,p in pm.items():
            if p.piece_type==chess.PAWN:
                if is_passed(sq, p.color):
                    r = chess.square_rank(sq)
                    if p.color==chess.WHITE:
                        white_score += (r / 7.0)  # normalized advancement 0..1
                    else:
                        black_score += ((7 - r) / 7.0)
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rook openness: (open-rook count + 0.5*semiopen-rook count) for White minus Black'
    try:
        pm = board.piece_map()
        def rook_score(color):
            score = 0.0
            # for each rook of color
            for sq,p in pm.items():
                if p.piece_type==chess.ROOK and p.color==color:
                    f = chess.square_file(sq)
                    has_white_pawn = any((q_p.piece_type==chess.PAWN and q_p.color==chess.WHITE and chess.square_file(q_sq)==f) for q_sq,q_p in pm.items())
                    has_black_pawn = any((q_p.piece_type==chess.PAWN and q_p.color==chess.BLACK and chess.square_file(q_sq)==f) for q_sq,q_p in pm.items())
                    if not has_white_pawn and not has_black_pawn:
                        score += 1.0  # open file
                    else:
                        # semi-open if no friendly pawns on file
                        if color==chess.WHITE:
                            if not any((q_p.piece_type==chess.PAWN and q_p.color==chess.WHITE and chess.square_file(q_sq)==f) for q_sq,q_p in pm.items()):
                                score += 0.5
                        else:
                            if not any((q_p.piece_type==chess.PAWN and q_p.color==chess.BLACK and chess.square_file(q_sq)==f) for q_sq,q_p in pm.items()):
                                score += 0.5
            return score
        return float(rook_score(chess.WHITE) - rook_score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Minor piece proximity to enemy king: sum_{minor pieces} value*(1/(1+distance)) for White minus Black'
    try:
        pm = board.piece_map()
        white_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.WHITE), None)
        black_king_sq = next((sq for sq,p in pm.items() if p.piece_type==chess.KING and p.color==chess.BLACK), None)
        def minor_score(color, target_king_sq):
            if target_king_sq is None:
                return 0.0
            s = 0.0
            for sq,p in pm.items():
                if p.color==color and p.piece_type in (chess.BISHOP, chess.KNIGHT):
                    d = chess.square_distance(sq, target_king_sq)
                    s += 3.0 * (1.0 / (1.0 + d))
            return s
        return float(minor_score(chess.WHITE, black_king_sq) - minor_score(chess.BLACK, white_king_sq))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Back-rank pawn shield count difference: (# white pawns on rank 2) - (# black pawns on rank 7)'
    try:
        pm = board.piece_map()
        white_shield = sum(1 for sq,p in pm.items() if p.piece_type==chess.PAWN and p.color==chess.WHITE and chess.square_rank(sq)==1)
        black_shield = sum(1 for sq,p in pm.items() if p.piece_type==chess.PAWN and p.color==chess.BLACK and chess.square_rank(sq)==6)
        return float(white_shield - black_shield)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Immediate mate opportunities difference: (# legal moves that deliver mate for White) - (# legal moves that deliver mate for Black)'
    try:
        def mate_moves_for(color):
            b = board.copy()
            b.turn = color
            cnt = 0
            for m in list(b.legal_moves):
                b2 = b.copy()
                try:
                    b2.push(m)
                except Exception:
                    continue
                if b2.is_checkmate():
                    cnt += 1
            return cnt
        return float(mate_moves_for(chess.WHITE) - mate_moves_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn structural isolation: (isolated pawn count for Black) - (isolated pawn count for White) (positive favors White when negative)'
    try:
        pm = board.piece_map()
        def isolated_count(color):
            files_with_own = {}
            for sq,p in pm.items():
                if p.piece_type==chess.PAWN and p.color==color:
                    f = chess.square_file(sq)
                    files_with_own.setdefault(f, []).append(sq)
            count = 0
            for sq,p in pm.items():
                if p.piece_type==chess.PAWN and p.color==color:
                    f = chess.square_file(sq)
                    if not files_with_own.get(f-1) and not files_with_own.get(f+1):
                        count += 1
            return count
        white_iso = isolated_count(chess.WHITE)
        black_iso = isolated_count(chess.BLACK)
        # return white - black (fewer white isolated pawns is good => positive)
        return float(white_iso - black_iso)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Mutual defense pairs difference: (# unordered mutual-defense pairs for White) - (for Black)'
    try:
        pm = board.piece_map()
        def mutual_pairs(color):
            squares = [sq for sq,p in pm.items() if p.color==color]
            s = 0
            seen = set()
            for a in squares:
                for b in squares:
                    if a >= b:
                        continue
                    if (a,b) in seen:
                        continue
                    # a defends b and b defends a
                    if board.is_attacked_by(color, b) and board.is_attacked_by(color, a):
                        # That check is insufficient; refine: does piece on a attack b and piece on b attack a?
                        # We'll check attackers sets for each square by opposite color of owner: use attackers with color
                        attackers_of_b_by_color = board.attackers(color, b)
                        attackers_of_a_by_color = board.attackers(color, a)
                        if a in attackers_of_b_by_color and b in attackers_of_a_by_color:
                            s += 1
                            seen.add((a,b))
            return s
        return float(mutual_pairs(chess.WHITE) - mutual_pairs(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King pawn-shield difference: (White pawn shield in front of king) - (Black pawn shield), higher means White king better sheltered'
    # Count friendly pawns on the three files in the 1st and 2nd ranks in front of each king
    try:
        piece_map = board.piece_map()
    except Exception:
        return 0.0
    def king_shield(color):
        # find king
        king_sq = None
        for sq, p in piece_map.items():
            if p.piece_type == chess.KING and p.color == color:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        kf = chess.square_file(king_sq)
        kr = chess.square_rank(king_sq)
        shield = 0
        # forward direction: white +1 rank, black -1 rank
        dir = 1 if color == chess.WHITE else -1
        for df in (-1, 0, 1):
            for step in (1, 2):
                r = kr + dir * step
                f = kf + df
                if 0 <= r <= 7 and 0 <= f <= 7:
                    sq = chess.square(f, r)
                    p = board.piece_at(sq)
                    if p is not None and p.piece_type == chess.PAWN and p.color == color:
                        shield += 1
        return float(shield)
    w_shield = king_shield(chess.WHITE)
    b_shield = king_shield(chess.BLACK)
    # higher means White more sheltered than Black
    return float(w_shield - b_shield)

def feature(board: chess.Board) -> float:
    'Weighted attackers on king squares: sum of attacker piece values attacking the opponent king (White - Black) in centipawn weights'
    values = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0, chess.KING:0.0}
    try:
        piece_map = board.piece_map()
    except Exception:
        return 0.0
    def attackers_sum(attacker_color, target_color):
        # find target king
        king_sq = None
        for sq, p in piece_map.items():
            if p.piece_type == chess.KING and p.color == target_color:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        atk_sqs = board.attackers(attacker_color, king_sq)
        s = 0.0
        for sq in atk_sqs:
            p = board.piece_at(sq)
            if p is None:
                continue
            s += values.get(p.piece_type, 0.0)
        return s
    w_on_b = attackers_sum(chess.WHITE, chess.BLACK)
    b_on_w = attackers_sum(chess.BLACK, chess.WHITE)
    return float(w_on_b - b_on_w)

def feature(board: chess.Board) -> float:
    'Passed pawn advancement difference: sum of advancedness of passed pawns (White - Black). Advancedness is higher for pawns closer to promotion.'
    try:
        piece_map = board.piece_map()
    except Exception:
        return 0.0
    w_score = 0.0
    b_score = 0.0
    # Precompute opponent pawn files for quicker checks
    white_pawn_files = set()
    black_pawn_files = set()
    for sq, p in piece_map.items():
        if p.piece_type == chess.PAWN:
            if p.color == chess.WHITE:
                white_pawn_files.add(chess.square_file(sq))
            else:
                black_pawn_files.add(chess.square_file(sq))
    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            # no black pawns on same or adjacent files on ranks > r
            for bf in (f-1, f, f+1):
                if 0 <= bf <= 7:
                    for rr in range(r+1, 8):
                        sq2 = chess.square(bf, rr)
                        p = board.piece_at(sq2)
                        if p is not None and p.piece_type == chess.PAWN and p.color == chess.BLACK:
                            return False
            return True
        else:
            for bf in (f-1, f, f+1):
                if 0 <= bf <= 7:
                    for rr in range(0, r):
                        sq2 = chess.square(bf, rr)
                        p = board.piece_at(sq2)
                        if p is not None and p.piece_type == chess.PAWN and p.color == chess.WHITE:
                            return False
            return True
    for sq, p in piece_map.items():
        if p.piece_type != chess.PAWN:
            continue
        if p.color == chess.WHITE:
            if is_passed(sq, chess.WHITE):
                # advancedness: rank index (0..7), higher is closer to promotion
                r = chess.square_rank(sq)
                w_score += float(r)
        else:
            if is_passed(sq, chess.BLACK):
                r = chess.square_rank(sq)
                # black advancedness measured from black perspective: 7 - r
                b_score += float(7 - r)
    return float(w_score - b_score)

def feature(board: chess.Board) -> float:
    'Rooks on open/semi-open files difference: open files count + 0.5*semi-open (White - Black)'
    try:
        piece_map = board.piece_map()
    except Exception:
        return 0.0
    # collect any pawns on each file
    pawns_on_file = {f: {'white':0, 'black':0} for f in range(8)}
    for sq, p in piece_map.items():
        if p.piece_type == chess.PAWN:
            pawns_on_file[chess.square_file(sq)]['white' if p.color==chess.WHITE else 'black'] += 1
    w_score = 0.0
    b_score = 0.0
    for sq, p in piece_map.items():
        if p.piece_type != chess.ROOK:
            continue
        f = chess.square_file(sq)
        has_white = pawns_on_file[f]['white'] > 0
        has_black = pawns_on_file[f]['black'] > 0
        if not has_white and not has_black:
            # open file
            if p.color == chess.WHITE:
                w_score += 1.0
            else:
                b_score += 1.0
        else:
            # semi-open if no friendly pawns
            if p.color == chess.WHITE and not has_white:
                w_score += 0.5
            if p.color == chess.BLACK and not has_black:
                b_score += 0.5
    return float(w_score - b_score)

def feature(board: chess.Board) -> float:
    'Queen centralization: sum of central proximity of queens (White - Black). Closer to d4/e4/d5/e5 yields higher score.'
    center_sqs = [chess.parse_square(s) for s in ('d4','e4','d5','e5')]
    try:
        piece_map = board.piece_map()
    except Exception:
        return 0.0
    def queen_score_for_color(color):
        s = 0.0
        for sq, p in piece_map.items():
            if p.piece_type == chess.QUEEN and p.color == color:
                # minimum chebyshev distance to central squares
                min_dist = min(chess.square_distance(sq, c) for c in center_sqs)
                # proximity benefit: 4 - dist (clamped), gives more for being near center
                contrib = max(0.0, 4.0 - float(min_dist))
                s += contrib
        return s
    return float(queen_score_for_color(chess.WHITE) - queen_score_for_color(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Long-range bishop mobility difference: sum over bishops of number of empty squares reachable along diagonals (White - Black)'
    try:
        piece_map = board.piece_map()
    except Exception:
        return 0.0
    dirs = [(1,1),(1,-1),(-1,1),(-1,-1)]
    def bishop_mobility(color):
        s = 0.0
        for sq, p in piece_map.items():
            if p.piece_type == chess.BISHOP and p.color == color:
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                for df, dr in dirs:
                    steps = 0
                    nf, nr = f + df, r + dr
                    while 0 <= nf <= 7 and 0 <= nr <= 7:
                        nsq = chess.square(nf, nr)
                        npiece = board.piece_at(nsq)
                        if npiece is None:
                            steps += 1
                            nf += df; nr += dr
                            continue
                        else:
                            # blocked by a piece (stop), but if it's an enemy piece we do not count beyond
                            break
                    s += float(steps)
        return s
    return float(bishop_mobility(chess.WHITE) - bishop_mobility(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Piece support edges: number of same-color pieces that are defended/attacked by another friendly non-pawn piece (White - Black)'
    try:
        piece_map = board.piece_map()
    except Exception:
        return 0.0
    def support_count(color):
        count = 0
        for sq, p in piece_map.items():
            if p.color != color:
                continue
            if p.piece_type in (chess.PAWN, chess.KING):
                continue
            # how many friendly pieces attack this square?
            attackers = board.attackers(color, sq)
            # exclude self (shouldn't be present) and count unique
            # attackers might include pawns; include any piece type as support here, but we will count only if attacker is not the same square
            for a_sq in attackers:
                if a_sq == sq:
                    continue
                attacker_piece = board.piece_at(a_sq)
                if attacker_piece is None:
                    continue
                if attacker_piece.color == color:
                    count += 1.0
                    break  # count at most 1 support per target to reduce dominance
        return float(count)
    return float(support_count(chess.WHITE) - support_count(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Developed non-pawn pieces difference: (count of non-pawn, non-king pieces off their original backrank for White) - (for Black)'
    try:
        piece_map = board.piece_map()
    except Exception:
        return 0.0
    w = 0.0
    b = 0.0
    for sq, p in piece_map.items():
        if p.piece_type in (chess.PAWN, chess.KING):
            continue
        r = chess.square_rank(sq)
        if p.color == chess.WHITE:
            # white original backrank is rank 0
            if r != 0:
                w += 1.0
        else:
            # black original backrank is rank 7
            if r != 7:
                b += 1.0
    return float(w - b)

def feature(board: chess.Board) -> float:
    'Undefended attacked enemy pieces weighted difference: sum of values of opponent pieces attacked by you with zero defenders (White - Black)'
    values = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0, chess.KING:0.0}
    try:
        piece_map = board.piece_map()
    except Exception:
        return 0.0
    def undefended_targets(attacker_color, victim_color):
        s = 0.0
        for sq, p in piece_map.items():
            if p.color != victim_color:
                continue
            # is this victim attacked by attacker_color?
            atk = board.attackers(attacker_color, sq)
            if not atk:
                continue
            # are there any defenders from victim_color?
            defs = board.attackers(victim_color, sq)
            if not defs:
                s += values.get(p.piece_type, 0.0)
        return s
    w_targets = undefended_targets(chess.WHITE, chess.BLACK)
    b_targets = undefended_targets(chess.BLACK, chess.WHITE)
    return float(w_targets - b_targets)

def feature(board: chess.Board) -> float:
    'Weighted pressure on the kings: sum of attacker piece values on black king square minus on white king square (in pawn units)'
    try:
        values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        pm = board.piece_map()
        # find kings
        bk = wk = None
        for sq,pc in pm.items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    wk = sq
                else:
                    bk = sq
        def pressure_on(square, attacker_color):
            if square is None:
                return 0
            attackers = board.attackers(attacker_color, square)
            s = 0
            for a in attackers:
                p = pm.get(a)
                if p:
                    s += values.get(p.piece_type,0)
            return s
        white_on_black = pressure_on(bk, chess.WHITE)
        black_on_white = pressure_on(wk, chess.BLACK)
        # return in pawn units (divide by 100) and as white minus black advantage
        return float((white_on_black - black_on_white) / 100.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Proximity of queens to opposing kings: (min distance of white queens to black king) - (min distance of black queens to white king) (smaller distance = better)'
    try:
        pm = board.piece_map()
        wq_squares = [sq for sq,pc in pm.items() if pc.piece_type==chess.QUEEN and pc.color==chess.WHITE]
        bq_squares = [sq for sq,pc in pm.items() if pc.piece_type==chess.QUEEN and pc.color==chess.BLACK]
        wk = bk = None
        for sq,pc in pm.items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    wk = sq
                else:
                    bk = sq
        def min_dist(squares, target):
            if target is None or not squares:
                return 100.0
            m = min(chess.square_distance(sq, target) for sq in squares)
            return float(m)
        wd = min_dist(wq_squares, bk)
        bd = min_dist(bq_squares, wk)
        # smaller distance is stronger; return black-distance minus white-distance so positive favors White
        return float(bd - wd)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Open/half-open rook files advantage: (#white rooks on open or half-open files) - (#black rooks on open or half-open files), open= no pawns, half-open=no friendly pawns'
    try:
        pm = board.piece_map()
        pawn_files = {f: {'white':0,'black':0} for f in range(8)}
        for sq,pc in pm.items():
            if pc.piece_type == chess.PAWN:
                pawn_files[chess.square_file(sq)][ 'white' if pc.color==chess.WHITE else 'black'] += 1
        def rook_score(color):
            score = 0
            for sq,pc in pm.items():
                if pc.piece_type==chess.ROOK and pc.color==color:
                    f = chess.square_file(sq)
                    total_pawns = pawn_files[f]['white'] + pawn_files[f]['black']
                    if total_pawns == 0:
                        score += 1.0  # open file
                    elif pawn_files[f]['white' if color==chess.WHITE else 'black']==0:
                        score += 0.5  # half-open
            return score
        return float(rook_score(chess.WHITE) - rook_score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Back-rank pawn shield: (# of friendly pawns on the rank ahead of white king) - (same for black). Higher means safer king in terms of back-rank pawns'
    try:
        pm = board.piece_map()
        white_king = black_king = None
        for sq,pc in pm.items():
            if pc.piece_type==chess.KING:
                if pc.color==chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        def pawns_in_front(king_sq, color):
            if king_sq is None:
                return 0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            target_rank = kr + 1 if color==chess.WHITE else kr - 1
            if target_rank < 0 or target_rank > 7:
                return 0
            count = 0
            for df in (-1,0,1):
                f = kf + df
                if 0 <= f <= 7:
                    try:
                        sq = chess.parse_square('abcdefgh'[f] + str(target_rank+1))
                        p = pm.get(sq)
                        if p and p.piece_type==chess.PAWN and p.color==color:
                            count += 1
                    except Exception:
                        continue
            return count
        wpf = pawns_in_front(white_king, chess.WHITE)
        bpf = pawns_in_front(black_king, chess.BLACK)
        return float(wpf - bpf)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King escape square pressure: (number of adjacent squares around black king attacked by White) - (same around white king attacked by Black). Positive favors White'
    try:
        pm = board.piece_map()
        white_king = black_king = None
        for sq,pc in pm.items():
            if pc.piece_type==chess.KING:
                if pc.color==chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        def attacked_adjacent(king_sq, attacker_color):
            if king_sq is None:
                return 0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            cnt = 0
            for df in (-1,0,1):
                for dr in (-1,0,1):
                    if df==0 and dr==0:
                        continue
                    f = kf + df
                    r = kr + dr
                    if 0 <= f <= 7 and 0 <= r <= 7:
                        sq = chess.parse_square('abcdefgh'[f] + str(r+1))
                        if board.is_attacked_by(attacker_color, sq):
                            cnt += 1
            return cnt
        b_att = attacked_adjacent(black_king, chess.WHITE)
        w_att = attacked_adjacent(white_king, chess.BLACK)
        return float(b_att - w_att)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn advantage: (number of white passed pawns) - (number of black passed pawns)'
    try:
        pm = board.piece_map()
        def is_passed(sq, color):
            if sq is None:
                return False
            if pm.get(sq) is None or pm[sq].piece_type != chess.PAWN:
                return False
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            # direction forward
            if color==chess.WHITE:
                opponent = chess.BLACK
                ranks = range(r+1,8)
            else:
                opponent = chess.WHITE
                ranks = range(r-1,-1,-1)
            for rf in (f-1, f, f+1):
                if 0 <= rf <= 7:
                    for rr in ranks:
                        sq2 = chess.parse_square('abcdefgh'[rf] + str(rr+1))
                        p = pm.get(sq2)
                        if p and p.piece_type==chess.PAWN and p.color==opponent:
                            return False
            return True
        wp = bp = 0
        for sq,pc in pm.items():
            if pc.piece_type==chess.PAWN:
                if pc.color==chess.WHITE and is_passed(sq, chess.WHITE):
                    wp += 1
                if pc.color==chess.BLACK and is_passed(sq, chess.BLACK):
                    bp += 1
        return float(wp - bp)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pseudo-mobility of non-pawn pieces weighted by piece values (white - black) normalized by 100: counts empty squares reachable in straight lines for sliders and knight jumps'
    try:
        values = {chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        pm = board.piece_map()
        files = 'abcdefgh'
        def square_from(f,r):
            return chess.parse_square(files[f] + str(r+1))
        def slider_moves(sq, directions):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            cnt = 0
            for df,dr in directions:
                nf, nr = f+df, r+dr
                while 0 <= nf <= 7 and 0 <= nr <= 7:
                    s2 = square_from(nf,nr)
                    if s2 in pm:
                        # can capture but cannot jump; count the capture square as 1 and stop
                        cnt += 1
                        break
                    cnt += 1
                    nf += df; nr += dr
            return cnt
        def knight_moves(sq):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            cnt = 0
            for df,dr in ((1,2),(2,1),(2,-1),(1,-2),(-1,-2),(-2,-1),(-2,1),(-1,2)):
                nf, nr = f+df, r+dr
                if 0 <= nf <= 7 and 0 <= nr <= 7:
                    cnt += 1
            return cnt
        white_score = black_score = 0.0
        rook_dirs = ((1,0),(-1,0),(0,1),(0,-1))
        bishop_dirs = ((1,1),(1,-1),(-1,1),(-1,-1))
        for sq,pc in pm.items():
            if pc.piece_type in (chess.BISHOP, chess.ROOK, chess.QUEEN, chess.KNIGHT):
                mobility = 0
                if pc.piece_type==chess.KNIGHT:
                    mobility = knight_moves(sq)
                elif pc.piece_type==chess.ROOK:
                    mobility = slider_moves(sq, rook_dirs)
                elif pc.piece_type==chess.BISHOP:
                    mobility = slider_moves(sq, bishop_dirs)
                elif pc.piece_type==chess.QUEEN:
                    mobility = slider_moves(sq, rook_dirs + bishop_dirs)
                val = values.get(pc.piece_type,0) * (mobility / 8.0)  # normalize mobility
                if pc.color==chess.WHITE:
                    white_score += val
                else:
                    black_score += val
        return float((white_score - black_score) / 100.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of potentially trapped major pieces (rook/queen) difference: (#white trapped majors) - (#black trapped majors); trapped ~ attacked more than defended and few adjacent empty escapes'
    try:
        pm = board.piece_map()
        majors = (chess.ROOK, chess.QUEEN)
        files = 'abcdefgh'
        def square_from(f,r):
            return chess.parse_square(files[f] + str(r+1))
        def adjacent_empty_count(sq):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            cnt = 0
            for df in (-1,0,1):
                for dr in (-1,0,1):
                    if df==0 and dr==0:
                        continue
                    nf, nr = f+df, r+dr
                    if 0 <= nf <=7 and 0 <= nr <=7:
                        s2 = square_from(nf,nr)
                        if s2 not in pm:
                            cnt += 1
            return cnt
        def trapped_count(color):
            count = 0
            for sq,pc in pm.items():
                if pc.piece_type in majors and pc.color==color:
                    attackers = len(board.attackers(not color, sq))
                    defenders = len(board.attackers(color, sq))
                    adj_empty = adjacent_empty_count(sq)
                    if attackers > defenders and adj_empty <= 2:
                        count += 1
            return count
        return float(trapped_count(chess.WHITE) - trapped_count(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King centralization difference: (min king distance to central squares for Black) - (for White). Positive favors White having more central king'
    try:
        pm = board.piece_map()
        centers = [chess.parse_square(s) for s in ['d4','e4','d5','e5']]
        wk = bk = None
        for sq,pc in pm.items():
            if pc.piece_type==chess.KING:
                if pc.color==chess.WHITE:
                    wk = sq
                else:
                    bk = sq
        def min_center_dist(king_sq):
            if king_sq is None:
                return 100.0
            return float(min(chess.square_distance(king_sq, c) for c in centers))
        wd = min_center_dist(wk)
        bd = min_center_dist(bk)
        return float(bd - wd)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Hanging pieces total value: sum of values of pieces that are attacked and undefended (white - black) in pawn units'
    try:
        values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        pm = board.piece_map()
        white_sum = black_sum = 0
        for sq,pc in pm.items():
            attackers_white = len(board.attackers(chess.WHITE, sq))
            attackers_black = len(board.attackers(chess.BLACK, sq))
            if pc.color==chess.WHITE:
                defenders = attackers_white
                attackers = attackers_black
                if attackers > 0 and defenders == 0:
                    white_sum += values.get(pc.piece_type,0)
            else:
                defenders = attackers_black
                attackers = attackers_white
                if attackers > 0 and defenders == 0:
                    black_sum += values.get(pc.piece_type,0)
        return float((white_sum - black_sum) / 100.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in pawn island count (White - Black). A pawn island is a contiguous group of files containing pawns of that color.'
    try:
        pawn_files_white = [False] * 8
        pawn_files_black = [False] * 8
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if piece.color == chess.WHITE:
                    pawn_files_white[f] = True
                else:
                    pawn_files_black[f] = True
        def count_islands(files_bool):
            islands = 0
            in_island = False
            for f in files_bool:
                if f and not in_island:
                    islands += 1
                    in_island = True
                elif not f:
                    in_island = False
            return islands
        return float(count_islands(pawn_files_white) - count_islands(pawn_files_black))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Advantage from rooks/queens on open or semi-open files: sum over pieces on files with (open=1.0, semi-open=0.5) (White - Black).'
    try:
        file_has_white_pawn = [False] * 8
        file_has_black_pawn = [False] * 8
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if piece.color == chess.WHITE:
                    file_has_white_pawn[f] = True
                else:
                    file_has_black_pawn[f] = True
        def file_score_for_color(f, color):
            if not file_has_white_pawn[f] and not file_has_black_pawn[f]:
                return 1.0  # open
            if color == chess.WHITE and not file_has_white_pawn[f]:
                return 0.5  # semi-open for White
            if color == chess.BLACK and not file_has_black_pawn[f]:
                return 0.5  # semi-open for Black
            return 0.0
        score_white = 0.0
        score_black = 0.0
        for sq, piece in board.piece_map().items():
            if piece.piece_type in (chess.ROOK, chess.QUEEN):
                f = chess.square_file(sq)
                if piece.color == chess.WHITE:
                    score_white += file_score_for_color(f, chess.WHITE)
                else:
                    score_black += file_score_for_color(f, chess.BLACK)
        return float(score_white - score_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn shield in front of each king: (number of friendly pawns on the three files in the immediate forward rank) White - Black. Measures immediate king shelter.'
    try:
        def king_shield(color):
            kings = [sq for sq, p in board.piece_map().items() if p.piece_type == chess.KING and p.color == color]
            if not kings:
                return 0
            ksq = kings[0]
            kf = chess.square_file(ksq)
            kr = chess.square_rank(ksq)
            shield_count = 0
            # For White king, pawns "in front" are at rank+1; for Black king, rank-1
            dr = 1 if color == chess.WHITE else -1
            target_rank = kr + dr
            for df in (-1, 0, 1):
                f = kf + df
                if 0 <= f <= 7 and 0 <= target_rank <= 7:
                    sq = chess.square(f, target_rank)
                    p = board.piece_at(sq)
                    if p is not None and p.piece_type == chess.PAWN and p.color == color:
                        shield_count += 1
            return shield_count
        return float(king_shield(chess.WHITE) - king_shield(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Bishop pair advantage: 1.0 if White has two or more bishops, -1.0 if Black has two or more, 0 otherwise. Useful long-term advantage indicator.'
    try:
        w_b = 0
        b_b = 0
        for p in board.piece_map().values():
            if p.piece_type == chess.BISHOP:
                if p.color == chess.WHITE:
                    w_b += 1
                else:
                    b_b += 1
        return float((1.0 if w_b >= 2 else 0.0) - (1.0 if b_b >= 2 else 0.0))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Mobility concentration difference: (max attacked squares by a single non-king piece / mean attacked squares per non-king piece) for White minus Black. Higher means mobility is concentrated in one piece.'
    try:
        piece_squares_white = []
        piece_squares_black = []
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING:
                continue
            if p.color == chess.WHITE:
                piece_squares_white.append(sq)
            else:
                piece_squares_black.append(sq)
        def attacked_counts_for_list(squares, color):
            counts = []
            if not squares:
                return counts
            # For each square s, count number of target squares t where s attacks t
            for s in squares:
                c = 0
                for t in range(64):
                    try:
                        attackers = board.attackers(color, t)
                    except Exception:
                        attackers = set()
                    if s in attackers:
                        c += 1
                counts.append(c)
            return counts
        w_counts = attacked_counts_for_list(piece_squares_white, chess.WHITE)
        b_counts = attacked_counts_for_list(piece_squares_black, chess.BLACK)
        def concentration(counts):
            if not counts:
                return 0.0
            mean = sum(counts) / (len(counts) + 1e-9)
            mx = max(counts)
            return mx / (mean + 1e-6)
        return float(concentration(w_counts) - concentration(b_counts))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count difference of undefended major pieces (rooks and queens) that are attacked by opponent and have zero defenders (White - Black). Highlights free material.'
    try:
        w_hanging = 0
        b_hanging = 0
        for sq, p in board.piece_map().items():
            if p.piece_type not in (chess.ROOK, chess.QUEEN):
                continue
            # defenders: same-color attackers of this square
            defenders = board.attackers(p.color, sq)
            # attackers: opponent attackers of this square
            attackers = board.attackers(not p.color, sq)
            if len(attackers) > 0 and len(defenders) == 0:
                if p.color == chess.WHITE:
                    w_hanging += 1
                else:
                    b_hanging += 1
        return float(w_hanging - b_hanging)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in king distance to the center (d4,e4,d5,e5). Lower distance often means more central (endgame) or more exposed; returns WhiteDist - BlackDist.'
    try:
        centers = [chess.parse_square(s) for s in ('d4', 'e4', 'd5', 'e5')]
        def min_center_dist(color):
            kings = [sq for sq, p in board.piece_map().items() if p.piece_type == chess.KING and p.color == color]
            if not kings:
                return 0.0
            k = kings[0]
            best = min(chess.square_distance(k, c) for c in centers)
            return float(best)
        return float(min_center_dist(chess.WHITE) - min_center_dist(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Queen reach difference: number of squares attacked by queens (sum over queens) White - Black. Measures queen activity / dominance.'
    try:
        w_reach = 0
        b_reach = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.QUEEN:
                cnt = 0
                for t in range(64):
                    try:
                        attackers = board.attackers(p.color, t)
                    except Exception:
                        attackers = set()
                    if sq in attackers:
                        cnt += 1
                if p.color == chess.WHITE:
                    w_reach += cnt
                else:
                    b_reach += cnt
        return float(w_reach - b_reach)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn count difference (White - Black). A pawn is passed if there is no enemy pawn on its file or adjacent files ahead of it.'
    try:
        def is_passed(sq, color):
            if board.piece_at(sq) is None or board.piece_at(sq).piece_type != chess.PAWN:
                return False
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                ranks_to_check = range(r + 1, 8)
            else:
                ranks_to_check = range(0, r)
            for df in (-1, 0, 1):
                ff = f + df
                if 0 <= ff <= 7:
                    for rr in ranks_to_check:
                        t = chess.square(ff, rr)
                        p = board.piece_at(t)
                        if p is not None and p.piece_type == chess.PAWN and p.color != color:
                            return False
            return True
        w_passed = 0
        b_passed = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                if is_passed(sq, p.color):
                    if p.color == chess.WHITE:
                        w_passed += 1
                    else:
                        b_passed += 1
        return float(w_passed - b_passed)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Piece coordination ratio difference: fraction of non-king pieces that are defended by at least one friendly piece (White - Black).'
    try:
        def defended_ratio(color):
            pieces = [sq for sq, p in board.piece_map().items() if p.color == color and p.piece_type != chess.KING]
            if not pieces:
                return 0.0
            defended = 0
            for sq in pieces:
                defs = board.attackers(color, sq)
                if len(defs) > 0:
                    defended += 1
            return defended / len(pieces)
        return float(defended_ratio(chess.WHITE) - defended_ratio(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of legal moves for the side to move that produce immediate checkmate (mate-in-1 count)'
    try:
        mate_count = 0
        # list() to avoid generator invalidation when pushing/popping
        for move in list(board.legal_moves):
            board.push(move)
            try:
                if board.is_checkmate():
                    mate_count += 1
            finally:
                board.pop()
        return float(mate_count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Number of legal king moves for the side to move (safe king escape count)'
    try:
        king_sq = None
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING and p.color == board.turn:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        count = 0
        for move in board.legal_moves:
            if move.from_square == king_sq:
                count += 1
        return float(count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of open/half-open files adjacent to the king-file for the side to move (open=1.0, half-open=0.5)'
    try:
        pm = board.piece_map()
        king_sq = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING and p.color == board.turn:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        kf = chess.square_file(king_sq)
        score = 0.0
        for f in range(max(0, kf - 1), min(7, kf + 1) + 1):
            total_pawns = 0
            friendly_pawns = 0
            for sq, p in pm.items():
                if p.piece_type == chess.PAWN and chess.square_file(sq) == f:
                    total_pawns += 1
                    if p.color == board.turn:
                        friendly_pawns += 1
            if total_pawns == 0:
                score += 1.0
            elif friendly_pawns == 0:
                score += 0.5
        return float(score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Number of opponent sliding pieces (rook/bishop/queen) that have an unobstructed straight-line path to the side-to-move king'
    try:
        pm = board.piece_map()
        king_sq = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING and p.color == board.turn:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        count = 0
        kf = chess.square_file(king_sq)
        kr = chess.square_rank(king_sq)
        for sq, p in pm.items():
            if p.color == (not board.turn) and p.piece_type in (chess.ROOK, chess.BISHOP, chess.QUEEN):
                pf = chess.square_file(sq)
                pr = chess.square_rank(sq)
                df = kf - pf
                dr = kr - pr
                # Determine alignment
                if df == 0:
                    dx, dy = 0, 1 if dr > 0 else -1
                elif dr == 0:
                    dx, dy = 1 if df > 0 else -1, 0
                elif abs(df) == abs(dr):
                    dx, dy = (1 if df > 0 else -1), (1 if dr > 0 else -1)
                else:
                    continue  # not aligned
                # Verify piece type supports this direction
                if p.piece_type == chess.ROOK and not (df == 0 or dr == 0):
                    continue
                if p.piece_type == chess.BISHOP and not (abs(df) == abs(dr)):
                    continue
                # step from p towards king, check obstruction
                delta = dy * 8 + dx
                cur = sq + delta
                blocked = False
                # walk until we reach king_sq (or go offboard)
                while cur != king_sq:
                    # bounds check: if file/rank out of [0,7] break as blocked (safety)
                    cf = chess.square_file(cur)
                    cr = chess.square_rank(cur)
                    if cf < 0 or cf > 7 or cr < 0 or cr > 7:
                        blocked = True
                        break
                    if board.piece_at(cur) is not None:
                        blocked = True
                        break
                    cur += delta
                if not blocked:
                    count += 1
        return float(count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Proximity score: (8 - minimal square distance) to the nearest enemy rook or queen (higher => major piece closer to king)'
    try:
        pm = board.piece_map()
        king_sq = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING and p.color == board.turn:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        min_dist = 100
        for sq, p in pm.items():
            if p.color != board.turn and p.piece_type in (chess.ROOK, chess.QUEEN):
                d = chess.square_distance(king_sq, sq)
                if d < min_dist:
                    min_dist = d
        if min_dist == 100:
            return 0.0
        return float(max(0, 8 - min_dist))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of opponent rooks/queens on the same rank as the side-to-move king (back-rank pressure indicator)'
    try:
        pm = board.piece_map()
        king_sq = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING and p.color == board.turn:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        kr = chess.square_rank(king_sq)
        cnt = 0
        for sq, p in pm.items():
            if p.color != board.turn and p.piece_type in (chess.ROOK, chess.QUEEN) and chess.square_rank(sq) == kr:
                cnt += 1
        return float(cnt)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Sum of material values of enemy non-pawn pieces within manhattan distance <= 2 of the side-to-move king that are attacked by the side to move (vulnerable high-value pieces)'
    try:
        values = {chess.KNIGHT: 3.0, chess.BISHOP: 3.0, chess.ROOK: 5.0, chess.QUEEN: 9.0}
        pm = board.piece_map()
        king_sq = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING and p.color == board.turn:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        s = 0.0
        for sq, p in pm.items():
            if p.color != board.turn and p.piece_type in values:
                if chess.square_distance(king_sq, sq) <= 2:
                    if board.is_attacked_by(board.turn, sq):
                        s += values[p.piece_type]
        return float(s)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn shield strength: number of friendly pawns in the three-file × two-rank area immediately "in front" of the king (higher is safer)'
    try:
        pm = board.piece_map()
        king_sq = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING and p.color == board.turn:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        kf = chess.square_file(king_sq)
        kr = chess.square_rank(king_sq)
        shield_count = 0
        # Determine forward direction relative to the king's color
        if board.turn == chess.WHITE:
            ranks = [kr + 1, kr + 2]
        else:
            ranks = [kr - 1, kr - 2]
        for f in range(max(0, kf - 1), min(7, kf + 1) + 1):
            for r in ranks:
                if 0 <= r <= 7:
                    sq = r * 8 + f
                    p = board.piece_at(sq)
                    if p is not None and p.piece_type == chess.PAWN and p.color == board.turn:
                        shield_count += 1
        return float(shield_count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of passed pawns belonging to the side to move that are within two squares of promotion (promotion-threat passed pawns)'
    try:
        pm = board.piece_map()
        cnt = 0
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN and p.color == board.turn:
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                is_passed = True
                if board.turn == chess.WHITE:
                    # no enemy pawns on same file or adjacent files ahead (r+1 .. 7)
                    for sq2, p2 in pm.items():
                        if p2.piece_type == chess.PAWN and p2.color == chess.BLACK:
                            f2 = chess.square_file(sq2)
                            r2 = chess.square_rank(sq2)
                            if abs(f - f2) <= 1 and r2 > r:
                                is_passed = False
                                break
                    dist = 7 - r
                else:
                    for sq2, p2 in pm.items():
                        if p2.piece_type == chess.PAWN and p2.color == chess.WHITE:
                            f2 = chess.square_file(sq2)
                            r2 = chess.square_rank(sq2)
                            if abs(f - f2) <= 1 and r2 < r:
                                is_passed = False
                                break
                    dist = r
                if is_passed and dist <= 2:
                    cnt += 1
        return float(cnt)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Number of pinned pieces of the side to move (non-king pieces that, if removed, would expose the king to a sliding enemy attack)'
    try:
        pm = board.piece_map()
        king_sq = None
        for sq, p in pm.items():
            if p.piece_type == chess.KING and p.color == board.turn:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        pinned = 0
        # helper to compute sign
        def sign(x):
            return 0 if x == 0 else (1 if x > 0 else -1)
        for sq, p in list(pm.items()):
            if p.color == board.turn and p.piece_type != chess.KING:
                # check if removing this piece would create an unobstructed line from any enemy sliding piece to king
                for esq, ep in pm.items():
                    if ep.color != board.turn and ep.piece_type in (chess.ROOK, chess.BISHOP, chess.QUEEN):
                        pf = chess.square_file(esq); pr = chess.square_rank(esq)
                        kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
                        df = kf - pf; dr = kr - pr
                        # must be aligned
                        if not (df == 0 or dr == 0 or abs(df) == abs(dr)):
                            continue
                        # direction vector
                        dx, dy = sign(df), sign(dr)
                        # check that this direction is compatible with piece type
                        if ep.piece_type == chess.ROOK and not (df == 0 or dr == 0):
                            continue
                        if ep.piece_type == chess.BISHOP and not (abs(df) == abs(dr)):
                            continue
                        delta = dy * 8 + dx
                        cur = esq + delta
                        blocker_count = 0
                        blocker_sq = None
                        blocked = False
                        while cur != king_sq:
                            if cur < 0 or cur > 63:
                                blocked = True
                                break
                            occ = board.piece_at(cur)
                            if occ is not None:
                                blocker_count += 1
                                blocker_sq = cur
                                # more than one blocker: not a pin via single piece
                                if blocker_count > 1:
                                    break
                            cur += delta
                        if blocked or blocker_count != 1:
                            continue
                        # if the single blocker is the candidate piece, it's pinned
                        if blocker_sq == sq:
                            pinned += 1
                            break  # count each pinned piece once
        return float(pinned)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of safe king-adjacent squares (white minus black); safe = empty or enemy, and not attacked by opponent'
    try:
        pieces = board.piece_map()
        white_king_sq = next((s for s, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king_sq = next((s for s, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        def safe_squares(king_sq, color):
            if king_sq is None:
                return 0.0
            opp = chess.BLACK if color == chess.WHITE else chess.WHITE
            kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
            count = 0
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    f = kf + df; r = kr + dr
                    if 0 <= f < 8 and 0 <= r < 8:
                        sq = chess.square(f, r)
                        occ = board.piece_at(sq)
                        # safe if not occupied by own piece and not attacked by opponent
                        if occ is None or occ.color != color:
                            if not board.is_attacked_by(opp, sq):
                                count += 1
            return float(count)
        return safe_squares(white_king_sq, chess.WHITE) - safe_squares(black_king_sq, chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn structure weakness difference (white minus black): doubled pawns + 1.2 * isolated pawns'
    try:
        pieces = board.piece_map()
        white_pawns_by_file = {f:0 for f in range(8)}
        black_pawns_by_file = {f:0 for f in range(8)}
        white_pawn_sqs = []
        black_pawn_sqs = []
        for sq, p in pieces.items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if p.color == chess.WHITE:
                    white_pawns_by_file[f] += 1
                    white_pawn_sqs.append(sq)
                else:
                    black_pawns_by_file[f] += 1
                    black_pawn_sqs.append(sq)
        def compute_penalty(pawn_sqs, pawns_by_file):
            doubled = sum(1 for v in pawns_by_file.values() if v > 1)
            isolated = 0
            for sq in pawn_sqs:
                f = chess.square_file(sq)
                adj = (pawns_by_file.get(f-1,0) + pawns_by_file.get(f+1,0))
                if adj == 0:
                    isolated += 1
            return float(doubled) + 1.2 * float(isolated)
        return compute_penalty(white_pawn_sqs, white_pawns_by_file) - compute_penalty(black_pawn_sqs, black_pawns_by_file)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of rooks on the opponent seventh rank (white minus black)'
    try:
        pieces = board.piece_map()
        white_count = 0
        black_count = 0
        for sq, p in pieces.items():
            if p.piece_type == chess.ROOK:
                r = chess.square_rank(sq)
                if p.color == chess.WHITE and r == 6:
                    white_count += 1
                if p.color == chess.BLACK and r == 1:
                    black_count += 1
        return float(white_count - black_count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Bishop-pair advantage (1 if side has two or more bishops, else 0) difference: white - black'
    try:
        pieces = board.piece_map()
        wb = sum(1 for p in pieces.values() if p.piece_type == chess.BISHOP and p.color == chess.WHITE)
        bb = sum(1 for p in pieces.values() if p.piece_type == chess.BISHOP and p.color == chess.BLACK)
        return (1.0 if wb >= 2 else 0.0) - (1.0 if bb >= 2 else 0.0)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in count of central outpost knights (well-defended knights on central squares not attacked by enemy pawns): white - black'
    try:
        pieces = board.piece_map()
        # build pawn-attack sets
        pawn_attacks_white = set()
        pawn_attacks_black = set()
        for sq, p in pieces.items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq); r = chess.square_rank(sq)
                if p.color == chess.WHITE:
                    for df in (-1, 1):
                        nf = f + df; nr = r + 1
                        if 0 <= nf < 8 and 0 <= nr < 8:
                            pawn_attacks_white.add(chess.square(nf, nr))
                else:
                    for df in (-1, 1):
                        nf = f + df; nr = r - 1
                        if 0 <= nf < 8 and 0 <= nr < 8:
                            pawn_attacks_black.add(chess.square(nf, nr))
        central_files = {3,4}  # d/e files
        central_ranks = {3,4}  # 4/5 ranks
        def count_outpost(color):
            opp_pawn_attacks = pawn_attacks_white if color == chess.BLACK else pawn_attacks_black
            cnt = 0
            for sq, p in pieces.items():
                if p.piece_type == chess.KNIGHT and p.color == color:
                    f = chess.square_file(sq); r = chess.square_rank(sq)
                    if f in central_files and r in central_ranks:
                        # not attacked by opponent pawns and has at least one friendly defender
                        if sq not in opp_pawn_attacks and len(board.attackers(color, sq)) > 0:
                            cnt += 1
            return cnt
        return float(count_outpost(chess.WHITE) - count_outpost(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of hanging major pieces (rooks or queens attacked by opponent and lacking defenders): white - black'
    try:
        pieces = board.piece_map()
        def count_hanging(color):
            opp = chess.BLACK if color == chess.WHITE else chess.WHITE
            cnt = 0
            for sq, p in pieces.items():
                if p.color == color and (p.piece_type == chess.ROOK or p.piece_type == chess.QUEEN):
                    if len(board.attackers(opp, sq)) > 0 and len(board.attackers(color, sq)) == 0:
                        cnt += 1
            return cnt
        return float(count_hanging(chess.WHITE) - count_hanging(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn shield gap difference in front of kings (missing friendly pawns on three-file shield within two ranks): white - black'
    try:
        pieces = board.piece_map()
        white_king_sq = next((s for s, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king_sq = next((s for s, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        def shield_gap(king_sq, color):
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
            missing = 0
            if color == chess.WHITE:
                ranks = [kr+1, kr+2]
            else:
                ranks = [kr-1, kr-2]
            for f in (kf-1, kf, kf+1):
                for r in ranks:
                    if 0 <= f < 8 and 0 <= r < 8:
                        sq = chess.square(f, r)
                        p = board.piece_at(sq)
                        if p is None or p.piece_type != chess.PAWN or p.color != color:
                            missing += 1
            return float(missing)
        return shield_gap(white_king_sq, chess.WHITE) - shield_gap(black_king_sq, chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Connected passed pawn potential difference (white minus black): passed pawns weighted by distance to promotion and +50% if supported by a neighbor pawn'
    try:
        pieces = board.piece_map()
        white_pawns = [s for s, p in pieces.items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        black_pawns = [s for s, p in pieces.items() if p.piece_type == chess.PAWN and p.color == chess.BLACK]
        black_pawn_positions = set(black_pawns)
        white_pawn_positions = set(white_pawns)
        def is_passed(sq, color):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            if color == chess.WHITE:
                for rr in range(r+1, 8):
                    for ff in (f-1, f, f+1):
                        if 0 <= ff < 8:
                            if chess.square(ff, rr) in black_pawn_positions:
                                return False
                return True
            else:
                for rr in range(0, r):
                    for ff in (f-1, f, f+1):
                        if 0 <= ff < 8:
                            if chess.square(ff, rr) in white_pawn_positions:
                                return False
                return True
        def connected_bonus(sq, color):
            f = chess.square_file(sq); r = chess.square_rank(sq)
            neighbors = []
            for df in (-1, 1):
                nf = f + df
                if 0 <= nf < 8:
                    # check adjacent-file pawn with rank difference <=1
                    for dr in (-1, 0, 1):
                        nr = r + dr
                        if 0 <= nr < 8:
                            neighbors.append(chess.square(nf, nr))
            pawn_set = white_pawn_positions if color == chess.WHITE else black_pawn_positions
            return any(n in pawn_set for n in neighbors)
        def score_for_color(pawn_sqs, color):
            s = 0.0
            for sq in pawn_sqs:
                if is_passed(sq, color):
                    r = chess.square_rank(sq)
                    base = float(7 - r) if color == chess.WHITE else float(r)  # distance to promotion
                    if base < 0:
                        base = 0.0
                    mult = 1.5 if connected_bonus(sq, color) else 1.0
                    s += base * mult
            return s
        return score_for_color(white_pawns, chess.WHITE) - score_for_color(black_pawns, chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in rooks on open/semi-open files pressure (white minus black): open file = no pawns, semi-open = no friendly pawns'
    try:
        pieces = board.piece_map()
        pawns_on_file = {f: {'w':0, 'b':0} for f in range(8)}
        for sq, p in pieces.items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                pawns_on_file[f]['w' if p.color == chess.WHITE else 'b'] += 1
        def rook_pressure(color):
            score = 0.0
            for sq, p in pieces.items():
                if p.piece_type == chess.ROOK and p.color == color:
                    f = chess.square_file(sq)
                    total_pawns = pawns_on_file[f]['w'] + pawns_on_file[f]['b']
                    friendly = pawns_on_file[f]['w'] if color == chess.WHITE else pawns_on_file[f]['b']
                    if total_pawns == 0:
                        score += 1.0
                    elif friendly == 0:
                        score += 0.5
            return score
        return float(rook_pressure(chess.WHITE) - rook_pressure(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King centrality difference (white minus black): closeness to central squares d4,e4,d5,e5 (higher = more central)'
    try:
        pieces = board.piece_map()
        centers = [chess.parse_square(s) for s in ('d4','e4','d5','e5')]
        def centrality(color):
            king_sq = next((s for s, p in pieces.items() if p.piece_type == chess.KING and p.color == color), None)
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
            min_cheb = min(max(abs(kf - chess.square_file(c)), abs(kr - chess.square_rank(c))) for c in centers)
            # convert to centrality: higher when closer; scale so center gets 4.0, far corners ~0
            return float(max(0.0, 4.0 - min_cheb))
        return centrality(chess.WHITE) - centrality(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Weighted attack pressure on the opponent king area: (White pressure on black king) - (Black pressure on white king). Weigh attackers by piece value (P=1,N/B=3,R=5,Q=9). Includes king square and its 8 neighbors.'
    values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    def pressure_on_king_by(color, king_sq):
        if king_sq is None:
            return 0.0
        opp = not color
        total = 0.0
        king_file = chess.square_file(king_sq)
        king_rank = chess.square_rank(king_sq)
        for df in (-1,0,1):
            for dr in (-1,0,1):
                f = king_file + df
                r = king_rank + dr
                if 0 <= f <= 7 and 0 <= r <= 7:
                    sq = chess.parse_square(chess.square_name(chess.square(f,r)))
                    attackers = board.attackers(color, sq)
                    for a in attackers:
                        piece = board.piece_at(a)
                        if piece:
                            total += values.get(piece.piece_type, 0.0)
        return total
    bking = board.king(chess.BLACK)
    wking = board.king(chess.WHITE)
    white_pressure_on_black = pressure_on_king_by(chess.WHITE, bking)
    black_pressure_on_white = pressure_on_king_by(chess.BLACK, wking)
    return float(white_pressure_on_black - black_pressure_on_white)

def feature(board: chess.Board) -> float:
    'Passed pawn advancement score difference: sum over passed pawns of (progress factor 0..1) for each side: (White) - (Black). A pawn is passed if no opposing pawn exists on same or adjacent files ahead.'
    def is_passed_pawn(sq, color):
        if board.piece_at(sq) is None or board.piece_at(sq).piece_type != chess.PAWN:
            return False
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            for af in (f-1,f,f+1):
                if 0 <= af <= 7:
                    for ar in range(r+1, 8):
                        s = chess.square(af, ar)
                        p = board.piece_at(s)
                        if p and p.piece_type == chess.PAWN and p.color == chess.BLACK:
                            return False
            return True
        else:
            for af in (f-1,f,f+1):
                if 0 <= af <= 7:
                    for ar in range(0, r):
                        s = chess.square(af, ar)
                        p = board.piece_at(s)
                        if p and p.piece_type == chess.PAWN and p.color == chess.WHITE:
                            return False
            return True
    white_score = 0.0
    black_score = 0.0
    for sq, piece in board.piece_map().items():
        if piece.piece_type == chess.PAWN:
            if is_passed_pawn(sq, piece.color):
                r = chess.square_rank(sq)
                if piece.color == chess.WHITE:
                    white_score += (r / 7.0) if r >= 0 else 0.0
                else:
                    black_score += ((7 - r) / 7.0) if r >= 0 else 0.0
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'King-file exposure: penalty for open/semi-open files adjacent to the king. Score = (#open files adjacent)*1.0 + (#semi-open files adjacent)*0.5. Returns white - black.'
    def file_status(file_index):
        has_white_pawn = False
        has_black_pawn = False
        for r in range(8):
            p = board.piece_at(chess.square(file_index, r))
            if p and p.piece_type == chess.PAWN:
                if p.color == chess.WHITE:
                    has_white_pawn = True
                else:
                    has_black_pawn = True
        if not has_white_pawn and not has_black_pawn:
            return 'open'
        if not has_white_pawn:
            return 'semi_open_white'
        if not has_black_pawn:
            return 'semi_open_black'
        return 'closed'
    def king_exposure(color):
        ksq = board.king(color)
        if ksq is None:
            return 0.0
        f = chess.square_file(ksq)
        score = 0.0
        for af in (f-1,f,f+1):
            if 0 <= af <= 7:
                st = file_status(af)
                if st == 'open':
                    score += 1.0
                elif (st == 'semi_open_white' and color == chess.BLACK) or (st == 'semi_open_black' and color == chess.WHITE):
                    # opponent has no pawn on that file -> semi-open hurting the king
                    score += 0.5
        return score
    return float(king_exposure(chess.WHITE) - king_exposure(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Rooks on opponent seventh (or second) rank: count white rooks on rank 6 and black rooks on rank 1. Returns white_count - black_count.'
    wcount = 0
    bcount = 0
    for sq, p in board.piece_map().items():
        if p.piece_type == chess.ROOK:
            r = chess.square_rank(sq)
            if p.color == chess.WHITE and r == 6:
                wcount += 1
            if p.color == chess.BLACK and r == 1:
                bcount += 1
    return float(wcount - bcount)

def feature(board: chess.Board) -> float:
    'Minor-piece outposts difference: number of knights or bishops on squares not attacked by enemy pawns and supported by a friendly pawn attack. Returns white - black.'
    def is_supported_by_pawn(sq, color):
        attackers = board.attackers(color, sq)
        for a in attackers:
            p = board.piece_at(a)
            if p and p.piece_type == chess.PAWN:
                return True
        return False
    def attacked_by_enemy_pawn(sq, enemy_color):
        attackers = board.attackers(enemy_color, sq)
        for a in attackers:
            p = board.piece_at(a)
            if p and p.piece_type == chess.PAWN:
                return True
        return False
    w = 0
    b = 0
    for sq, p in board.piece_map().items():
        if p.piece_type in (chess.KNIGHT, chess.BISHOP):
            if p.color == chess.WHITE:
                if not attacked_by_enemy_pawn(sq, chess.BLACK) and is_supported_by_pawn(sq, chess.WHITE):
                    w += 1
            else:
                if not attacked_by_enemy_pawn(sq, chess.WHITE) and is_supported_by_pawn(sq, chess.BLACK):
                    b += 1
    return float(w - b)

def feature(board: chess.Board) -> float:
    'Major vs minor balance difference emphasizing composition: (R*5 + Q*9) - (N*3 + B*3) for White minus Black.'
    def compositional_score(color):
        r = q = n = b = 0
        for p in board.piece_map().values():
            if p.color != color:
                continue
            if p.piece_type == chess.ROOK:
                r += 1
            elif p.piece_type == chess.QUEEN:
                q += 1
            elif p.piece_type == chess.KNIGHT:
                n += 1
            elif p.piece_type == chess.BISHOP:
                b += 1
        return r*5.0 + q*9.0 - (n*3.0 + b*3.0)
    return float(compositional_score(chess.WHITE) - compositional_score(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Count of rooks/queens on files without a friendly pawn (free/semi-open file control) difference: (white) - (black).'
    def file_has_friendly_pawn(file_index, color):
        for r in range(8):
            p = board.piece_at(chess.square(file_index, r))
            if p and p.piece_type == chess.PAWN and p.color == color:
                return True
        return False
    w = 0
    b = 0
    for sq, p in board.piece_map().items():
        if p.piece_type in (chess.ROOK, chess.QUEEN):
            f = chess.square_file(sq)
            if not file_has_friendly_pawn(f, p.color):
                if p.color == chess.WHITE:
                    w += 1
                else:
                    b += 1
    return float(w - b)

def feature(board: chess.Board) -> float:
    'Count of undefended high-value pieces (queen or rook) that are attacked at least once but have zero defenders. Returns white - black.'
    def undefended_high_value(color):
        cnt = 0
        opp = not color
        for sq, p in board.piece_map().items():
            if p.color != color:
                continue
            if p.piece_type in (chess.QUEEN, chess.ROOK):
                attackers = len(board.attackers(opp, sq))
                defenders = len(board.attackers(color, sq))
                if attackers > 0 and defenders == 0:
                    cnt += 1
        return cnt
    return float(undefended_high_value(chess.WHITE) - undefended_high_value(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Back-rank escape squares difference: number of empty squares on the king\'s current rank within two files that are not attacked by the opponent. Returns white - black.'
    def escapes(color):
        ksq = board.king(color)
        if ksq is None:
            return 0.0
        f = chess.square_file(ksq)
        r = chess.square_rank(ksq)
        opp = not color
        cnt = 0
        for af in range(max(0,f-2), min(7,f+2)+1):
            sq = chess.square(af, r)
            if board.piece_at(sq) is None and not board.is_attacked_by(opp, sq):
                cnt += 1
        return float(cnt)
    return float(escapes(chess.WHITE) - escapes(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Piece coordination index difference: sum of 1/(1+manhattan_distance) over all unordered pairs of non-pawn, non-king pieces per side. Higher = more concentrated pieces. Returns white - black.'
    def coordination(color):
        squares = [sq for sq, p in board.piece_map().items() if p.color == color and p.piece_type not in (chess.PAWN, chess.KING)]
        total = 0.0
        n = len(squares)
        for i in range(n):
            for j in range(i+1, n):
                d = chess.square_distance(squares[i], squares[j])
                total += 1.0 / (1.0 + d)
        return total
    return float(coordination(chess.WHITE) - coordination(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Difference in king pawn-shield solidity: (white_shield - black_shield). Counts friendly pawns on three squares in front of each king (files f-1,f,f+1, one rank forward).'
    try:
        def shield_count(color):
            king_sq = None
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == color:
                    king_sq = sq
                    break
            if king_sq is None:
                return 0.0
            kr = chess.square_rank(king_sq)
            kf = chess.square_file(king_sq)
            count = 0
            if color == chess.WHITE:
                ranks = [kr + 1]
            else:
                ranks = [kr - 1]
            for rf in ranks:
                if 0 <= rf <= 7:
                    for ff in [kf - 1, kf, kf + 1]:
                        if 0 <= ff <= 7:
                            sq = chess.square(ff, rf)
                            p = board.piece_at(sq)
                            if p is not None and p.piece_type == chess.PAWN and p.color == color:
                                count += 1
            return float(count)
        return shield_count(chess.WHITE) - shield_count(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn advancement difference: sum of normalized advancement of passed pawns (white - black). Each passed pawn contributes rank/7 (0..1) for white, (7-rank)/7 for black.'
    try:
        wm = 0.0
        bm = 0.0
        pawns = [(sq, p) for sq, p in board.piece_map().items() if p.piece_type == chess.PAWN]
        # build quick lookup of pawn files by color and rank
        white_pawn_positions = [sq for sq, p in pawns if p.color == chess.WHITE]
        black_pawn_positions = [sq for sq, p in pawns if p.color == chess.BLACK]
        def is_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                # no black pawns on same or adjacent files with rank > r
                for bsq in black_pawn_positions:
                    bf = chess.square_file(bsq); br = chess.square_rank(bsq)
                    if abs(bf - f) <= 1 and br > r:
                        return False
                return True
            else:
                for wsq in white_pawn_positions:
                    wf = chess.square_file(wsq); wr = chess.square_rank(wsq)
                    if abs(wf - f) <= 1 and wr < r:
                        return False
                return True
        for sq, p in pawns:
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                if is_passed(sq, chess.WHITE):
                    wm += (r / 7.0)
            else:
                if is_passed(sq, chess.BLACK):
                    bm += ((7 - r) / 7.0)
        return float(wm - bm)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in undefended high-value pieces (queen weight=2, rook weight=1): counts high-value pieces that are attacked and have zero defenders (white - black).'
    try:
        vals = {chess.QUEEN: 2.0, chess.ROOK: 1.0}
        def side_score(color):
            s = 0.0
            for sq, p in board.piece_map().items():
                if p.color != color:
                    continue
                if p.piece_type not in vals:
                    continue
                opp = not color
                attacked = board.is_attacked_by(opp, sq)
                defenders = len(board.attackers(color, sq))
                if attacked and defenders == 0:
                    s += vals[p.piece_type]
            return s
        return float(side_score(chess.WHITE) - side_score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in king centralization: normalized closeness to center (white - black). Central squares are d4,d5,e4,e5; closer kings to center score higher (range roughly -1..1).'
    try:
        center_sqs = [chess.parse_square(n) for n in ('d4', 'd5', 'e4', 'e5')]
        def centrality(color):
            king_sq = None
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == color:
                    king_sq = sq
                    break
            if king_sq is None:
                return 0.0
            # use min Manhattan distance to center squares, normalize with max possible 7
            min_d = min(chess.square_distance(king_sq, csq) for csq in center_sqs)
            return (7.0 - float(min_d)) / 7.0
        return centrality(chess.WHITE) - centrality(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn structure weakness difference: (isolated + doubled pawns) for white minus black. Each isolated pawn counts 1, doubled pawns counted per extra pawn on a file.'
    try:
        def weaknesses(color):
            files = [0] * 8
            pawn_sqs = [sq for sq, p in board.piece_map().items() if p.piece_type == chess.PAWN and p.color == color]
            for sq in pawn_sqs:
                files[chess.square_file(sq)] += 1
            iso = 0
            doubled = 0
            for f in range(8):
                cnt = files[f]
                if cnt == 0:
                    continue
                # isolated if no friendly pawns on adjacent files
                if (f == 0 or files[f-1] == 0) and (f == 7 or files[f+1] == 0):
                    iso += cnt
                if cnt > 1:
                    doubled += (cnt - 1)
            return float(iso + doubled)
        return weaknesses(chess.WHITE) - weaknesses(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Attacking pressure around kings difference: number (weighted) of opponent pieces attacking squares adjacent to the king (white - black). Weights: pawn 0.5, knight 1.0, bishop 1.0, rook 1.2, queen 1.5.'
    try:
        weights = {chess.PAWN:0.5, chess.KNIGHT:1.0, chess.BISHOP:1.0, chess.ROOK:1.2, chess.QUEEN:1.5}
        def pressure_against(color):
            # pressure against color's king by opponent pieces
            king_sq = None
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == color:
                    king_sq = sq
                    break
            if king_sq is None:
                return 0.0
            kr = chess.square_rank(king_sq); kf = chess.square_file(king_sq)
            ring = []
            for dr in (-1,0,1):
                for df in (-1,0,1):
                    rf = kf + df; rr = kr + dr
                    if 0 <= rf <= 7 and 0 <= rr <= 7:
                        ring.append(chess.square(rf, rr))
            opp = not color
            attackers = set()
            total = 0.0
            for sq in ring:
                for atk_sq in board.attackers(opp, sq):
                    if atk_sq in attackers:
                        continue
                    attackers.add(atk_sq)
                    p = board.piece_at(atk_sq)
                    if p is None:
                        continue
                    total += weights.get(p.piece_type, 0.7)
            return total
        return pressure_against(chess.WHITE) - pressure_against(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Promotion proximity difference: 1/(1+min_moves_to_promote) for white pawns minus same for black pawns. Uses rank distance to promotion; empty if no pawns -> 0.'
    try:
        inf = 100.0
        w_min = inf
        b_min = inf
        for sq, p in board.piece_map().items():
            if p.piece_type != chess.PAWN:
                continue
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                d = 7 - r
                if d < w_min:
                    w_min = d
            else:
                d = r
                if d < b_min:
                    b_min = d
        def inv(d):
            if d == inf:
                return 0.0
            return 1.0 / (1.0 + float(d))
        return inv(w_min) - inv(b_min)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Minor-to-major mobility ratio difference: (white_minor_mobility/ (white_major_mobility+0.1)) - (black_minor_mobility/ (black_major_mobility+0.1)). Mobility measured as legal moves by piece types.'
    try:
        minor_types = {chess.KNIGHT, chess.BISHOP}
        major_types = {chess.ROOK, chess.QUEEN}
        def mobility(color):
            minor = 0
            major = 0
            for mv in board.legal_moves:
                from_sq = mv.from_square
                p = board.piece_at(from_sq)
                if p is None or p.color != color:
                    continue
                if p.piece_type in minor_types:
                    minor += 1
                elif p.piece_type in major_types:
                    major += 1
            return minor, major
        wmin, wmaj = mobility(chess.WHITE)
        bmin, bmaj = mobility(chess.BLACK)
        wratio = (wmin / (wmaj + 0.1)) if (wmin + wmaj) > 0 else 0.0
        bratio = (bmin / (bmaj + 0.1)) if (bmin + bmaj) > 0 else 0.0
        return float(wratio - bratio)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of immediate checkmates available (white - black): counts legal moves that result in checkmate for the mover.'
    try:
        wm = 0.0
        bm = 0.0
        # iterate legal moves for both sides by creating copies with appropriate turn
        # moves when white to move:
        for mv in board.legal_moves:
            try:
                b2 = board.copy()
                b2.push(mv)
                mover = not b2.turn  # mover is side that just moved
                if b2.is_checkmate():
                    if mover == chess.WHITE:
                        wm += 1.0
                    else:
                        bm += 1.0
            except Exception:
                continue
        return float(wm - bm)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Trapped-piece mobility penalty difference: sum over non-king pieces of max(0,3 - piece_move_count) * piece_value * (1 if attacked else 0.6). Higher means more trapped pieces for white minus black.'
    try:
        values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0}
        # count legal moves per from_square
        move_counts = {}
        for mv in board.legal_moves:
            move_counts[mv.from_square] = move_counts.get(mv.from_square, 0) + 1
        def trap_penalty(color):
            total = 0.0
            for sq, p in board.piece_map().items():
                if p.color != color or p.piece_type == chess.KING:
                    continue
                cnt = move_counts.get(sq, 0)
                penalty_mult = float(max(0, 3 - cnt))
                attacked = board.is_attacked_by(not color, sq)
                weight = 1.0 if attacked else 0.6
                total += penalty_mult * weight * values.get(p.piece_type, 1.0)
            return total
        return float(trap_penalty(chess.WHITE) - trap_penalty(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Weighted density of attackers within Chebyshev radius 2 around each king: (White attackers near Black king) - (Black attackers near White king), weighted by piece value'
    try:
        piece_values = {chess.PAWN: 100.0, chess.KNIGHT: 320.0, chess.BISHOP: 330.0, chess.ROOK: 500.0, chess.QUEEN: 900.0, chess.KING: 20000.0}
        pm = board.piece_map()
        # find kings
        white_king = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        def density_around(king_sq, attacker_color):
            if king_sq is None:
                return 0.0
            kf, kr = chess.square_file(king_sq), chess.square_rank(king_sq)
            total = 0.0
            for sq, p in pm.items():
                if p.color != attacker_color:
                    continue
                # Chebyshev distance <=2
                if max(abs(chess.square_file(sq) - kf), abs(chess.square_rank(sq) - kr)) <= 2:
                    total += piece_values.get(p.piece_type, 0.0)
            return total
        result = density_around(black_king, chess.WHITE) - density_around(white_king, chess.BLACK)
        return float(result)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net king defender advantage: (number of friendly defenders of White king minus attackers on White king) - (same for Black king). Positive means White better defended'
    try:
        pm = board.piece_map()
        white_king = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        def defense_minus_attack(king_sq, king_color):
            if king_sq is None:
                return 0.0
            defenders = set(board.attackers(king_color, king_sq))
            attackers = set(board.attackers(not king_color, king_sq))
            # remove the king square itself if present
            defenders.discard(king_sq)
            return float(len(defenders) - len(attackers))
        w = defense_minus_attack(white_king, chess.WHITE)
        b = defense_minus_attack(black_king, chess.BLACK)
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of pinned non-king pieces: (White pinned pieces) - (Black pinned pieces). A piece is pinned if an opponent slider has it as unique blocker to that side\'s king.'
    try:
        pm = board.piece_map()
        # find kings
        kings = {chess.WHITE: None, chess.BLACK: None}
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                kings[p.color] = sq
        pinned = {chess.WHITE: 0, chess.BLACK: 0}
        slider_types = {chess.ROOK, chess.BISHOP, chess.QUEEN}
        for attacker_sq, attacker in pm.items():
            if attacker.piece_type not in slider_types:
                continue
            attacker_color = attacker.color
            target_color = not attacker_color
            king_sq = kings[target_color]
            if king_sq is None:
                continue
            # check alignment between attacker and king
            af, ar = chess.square_file(attacker_sq), chess.square_rank(attacker_sq)
            kf, kr = chess.square_file(king_sq), chess.square_rank(king_sq)
            df = kf - af
            dr = kr - ar
            step_f = 0 if df == 0 else (1 if df > 0 else -1)
            step_r = 0 if dr == 0 else (1 if dr > 0 else -1)
            # must be straight or diagonal
            if not (df == 0 or dr == 0 or abs(df) == abs(dr)):
                continue
            # walk from attacker towards king and count pieces between
            curr_f, curr_r = af + step_f, ar + step_r
            blockers = []
            while 0 <= curr_f <= 7 and 0 <= curr_r <= 7:
                curr_sq = curr_r * 8 + curr_f
                if curr_sq == king_sq:
                    break
                if curr_sq in pm:
                    blockers.append((curr_sq, pm[curr_sq]))
                curr_f += step_f
                curr_r += step_r
            # If exactly one blocker and it belongs to the king's color, that piece is pinned
            if len(blockers) == 1:
                blocker_sq, blocker_piece = blockers[0]
                if blocker_piece.color == target_color and blocker_piece.piece_type != chess.KING:
                    pinned[target_color] += 1
        return float(pinned[chess.WHITE] - pinned[chess.BLACK])
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Major-piece penetration: (White rooks/queens on Black back rank) - (Black rooks/queens on White back rank). Encourages pieces deep in enemy camp.'
    try:
        pm = board.piece_map()
        white_count = 0
        black_count = 0
        for sq, p in pm.items():
            if p.piece_type not in (chess.ROOK, chess.QUEEN):
                continue
            rank = chess.square_rank(sq)
            if p.color == chess.WHITE and rank == 7:
                white_count += 1
            if p.color == chess.BLACK and rank == 0:
                black_count += 1
        return float(white_count - black_count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rooks/queens on open files difference: (White count on open files) - (Black count on open files). Open file = no pawns of either color on that file.'
    try:
        pm = board.piece_map()
        # determine files that have pawns
        pawn_files = set()
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                pawn_files.add(chess.square_file(sq))
        def count_on_open(color):
            cnt = 0
            for sq, p in pm.items():
                if p.color != color:
                    continue
                if p.piece_type not in (chess.ROOK, chess.QUEEN):
                    continue
                if chess.square_file(sq) not in pawn_files:
                    cnt += 1
            return cnt
        return float(count_on_open(chess.WHITE) - count_on_open(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King space difference: number of empty squares adjacent (Chebyshev radius 1) to White king minus same for Black king. More escape squares often means safer king.'
    try:
        pm = board.piece_map()
        def king_space_for(color):
            king_sq = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == color), None)
            if king_sq is None:
                return 0.0
            kf, kr = chess.square_file(king_sq), chess.square_rank(king_sq)
            space = 0
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    nf, nr = kf + df, kr + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        nsq = nr * 8 + nf
                        if nsq not in pm:
                            space += 1
            return float(space)
        return king_space_for(chess.WHITE) - king_space_for(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Weighted count of undefended high-value pieces: sum of piece values for White pieces that are attacked by opponent and have zero friendly defenders minus same for Black.'
    try:
        pm = board.piece_map()
        values = {chess.PAWN: 100.0, chess.KNIGHT: 320.0, chess.BISHOP: 330.0, chess.ROOK: 500.0, chess.QUEEN: 900.0, chess.KING: 20000.0}
        def undefended_value(color):
            total = 0.0
            for sq, p in pm.items():
                if p.color != color:
                    continue
                # find friendly defenders (excluding the piece itself)
                defenders = set(board.attackers(color, sq))
                defenders.discard(sq)
                attackers = set(board.attackers(not color, sq))
                if len(defenders) == 0 and len(attackers) > 0:
                    total += values.get(p.piece_type, 0.0)
            return total
        return float(undefended_value(chess.WHITE) - undefended_value(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rooks on opponent\'s seventh rank difference: (White rooks on rank 6) - (Black rooks on rank 1). Seventh-rank rooks are often decisive.'
    try:
        pm = board.piece_map()
        w = 0
        b = 0
        for sq, p in pm.items():
            if p.piece_type != chess.ROOK:
                continue
            r = chess.square_rank(sq)
            if p.color == chess.WHITE and r == 6:
                w += 1
            if p.color == chess.BLACK and r == 1:
                b += 1
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Average pairwise Manhattan distance among non-king, non-pawn pieces per side: (Black average) - (White average). Lower average -> better coordination; sign indicates which side is more clustered.'
    try:
        pm = board.piece_map()
        def avg_pairwise(color):
            squares = [sq for sq, p in pm.items() if p.color == color and p.piece_type not in (chess.KING, chess.PAWN)]
            n = len(squares)
            if n < 2:
                return 0.0
            total = 0
            pairs = 0
            for i in range(n):
                for j in range(i+1, n):
                    total += chess.square_distance(squares[i], squares[j])
                    pairs += 1
            return float(total) / pairs if pairs > 0 else 0.0
        return float(avg_pairwise(chess.BLACK) - avg_pairwise(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Advanced passed-pawn proximity to enemy king: sum over passed pawns advanced beyond rank 4 that are within Manhattan distance 2 of opponent king (White minus Black), weighted by pawn advancement'
    try:
        pm = board.piece_map()
        def is_passed(sq, color):
            file = chess.square_file(sq)
            rank = chess.square_rank(sq)
            # For white, check files file-1..file+1 for any black pawn on higher rank; for black vice versa
            for df in (-1, 0, 1):
                f = file + df
                if not (0 <= f <= 7):
                    continue
                for r in range(0, 8):
                    osq = r * 8 + f
                    if osq in pm and pm[osq].piece_type == chess.PAWN and pm[osq].color != color:
                        # for white pawn, opponent pawn ahead means not passed
                        if color == chess.WHITE and r > rank:
                            return False
                        if color == chess.BLACK and r < rank:
                            return False
            return True
        # find kings
        white_king = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king = next((sq for sq, p in pm.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        def score_for(color):
            total = 0.0
            for sq, p in pm.items():
                if p.piece_type != chess.PAWN or p.color != color:
                    continue
                rank = chess.square_rank(sq)
                advanced = (rank >= 4) if color == chess.WHITE else (rank <= 3)
                if not advanced:
                    continue
                if not is_passed(sq, color):
                    continue
                opp_king = black_king if color == chess.WHITE else white_king
                if opp_king is None:
                    continue
                dist = chess.square_distance(sq, opp_king)
                if dist <= 2:
                    # weight by advancement (closer to promotion gives higher score)
                    weight = (rank - 3) if color == chess.WHITE else (4 - rank)
                    total += max(1.0, float(weight))
            return total
        return float(score_for(chess.WHITE) - score_for(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net passed pawns: (white passed pawns) - (black passed pawns), counted as whole pawns'
    try:
        wm = 0
        bm = 0
        pieces = board.piece_map()
        # Precompute pawn squares by color and file
        pawns_by_color = {chess.WHITE: [], chess.BLACK: []}
        for sq, p in pieces.items():
            if p.piece_type == chess.PAWN:
                pawns_by_color[p.color].append(sq)
        # Helper: is pawn passed
        def is_passed(sq, color):
            file = chess.square_file(sq)
            rank = chess.square_rank(sq)
            enemy = not color
            # For white, enemy pawns ahead have rank > rank; for black, enemy pawns ahead have rank < rank
            for ep in pawns_by_color[enemy]:
                ef = chess.square_file(ep)
                er = chess.square_rank(ep)
                if abs(ef - file) <= 1:
                    if color == chess.WHITE and er > rank:
                        return False
                    if color == chess.BLACK and er < rank:
                        return False
            return True
        for sq, p in pieces.items():
            if p.piece_type == chess.PAWN:
                if is_passed(sq, p.color):
                    if p.color == chess.WHITE:
                        wm += 1
                    else:
                        bm += 1
        return float(wm - bm)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of rooks/queens on open or semi-open files: (white score) - (black score). Open=1.0, semi-open=0.5'
    try:
        files_with_white_pawn = set()
        files_with_black_pawn = set()
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if p.color == chess.WHITE:
                    files_with_white_pawn.add(f)
                else:
                    files_with_black_pawn.add(f)
        white_score = 0.0
        black_score = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type in (chess.ROOK, chess.QUEEN):
                f = chess.square_file(sq)
                # open file: no pawns of either color
                if f not in files_with_white_pawn and f not in files_with_black_pawn:
                    v = 1.0
                # semi-open: no friendly pawns on the file
                elif (p.color == chess.WHITE and f not in files_with_white_pawn) or (p.color == chess.BLACK and f not in files_with_black_pawn):
                    v = 0.5
                else:
                    v = 0.0
                if p.color == chess.WHITE:
                    white_score += v
                else:
                    black_score += v
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King mobility safety: (number of safe adjacent squares for White king) - (same for Black). Safe means not attacked by enemy and not occupied by friendly piece'
    try:
        def safe_adjacent_count(color):
            ks = board.king(color)
            if ks is None:
                return 0.0
            kr = chess.square_rank(ks)
            kf = chess.square_file(ks)
            opp = not color
            count = 0
            for dr in (-1, 0, 1):
                for df in (-1, 0, 1):
                    if dr == 0 and df == 0:
                        continue
                    r = kr + dr
                    f = kf + df
                    if 0 <= r <= 7 and 0 <= f <= 7:
                        sq = chess.square(f, r)
                        occ = board.piece_at(sq)
                        # Square is candidate if empty or occupied by opponent (king could capture)
                        if occ is None or occ.color != color:
                            if not board.is_attacked_by(opp, sq):
                                count += 1
            return float(count)
        return safe_adjacent_count(chess.WHITE) - safe_adjacent_count(chess.BLACK)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Weighted undefended pieces difference (white - black) using centipawn weights (pawn=100,knight=320,bishop=330,rook=500,queen=900)'
    try:
        vals = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0, chess.KING:0.0}
        total_white = 0.0
        total_black = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING:
                continue
            attackers_enemy = board.attackers(not p.color, sq)
            attackers_own = board.attackers(p.color, sq)
            if attackers_enemy and not attackers_own:
                w = vals.get(p.piece_type, 0.0)
                if p.color == chess.WHITE:
                    total_white += w
                else:
                    total_black += w
        return float(total_white - total_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Bishop activity difference: (sum of legal moves from bishop squares for White) - (same for Black)'
    try:
        # Count legal moves originating from each square
        move_counts = {}
        for mv in board.legal_moves:
            move_counts[mv.from_square] = move_counts.get(mv.from_square, 0) + 1
        white_sum = 0.0
        black_sum = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.BISHOP:
                c = move_counts.get(sq, 0)
                if p.color == chess.WHITE:
                    white_sum += c
                else:
                    black_sum += c
        return float(white_sum - black_sum)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Knight outpost heuristic: (white outpost knights) - (black outpost knights). An outpost here = knight on advanced rank and no enemy pawns on adjacent files'
    try:
        pawns = board.piece_map()
        # Precompute enemy pawn files sets
        white_pawn_files = set()
        black_pawn_files = set()
        for sq, p in pawns.items():
            if p.piece_type == chess.PAWN:
                if p.color == chess.WHITE:
                    white_pawn_files.add(chess.square_file(sq))
                else:
                    black_pawn_files.add(chess.square_file(sq))
        w_out = 0
        b_out = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KNIGHT:
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                left = f-1
                right = f+1
                if p.color == chess.WHITE:
                    # advanced rank heuristic: rank >=4 (index >=3)
                    if r >= 3 and (left not in black_pawn_files) and (right not in black_pawn_files):
                        w_out += 1
                else:
                    # black advanced towards rank <=4 (index <=4)
                    if r <= 4 and (left not in white_pawn_files) and (right not in white_pawn_files):
                        b_out += 1
        return float(w_out - b_out)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Queen-to-opponent-king proximity advantage: (min distance of black queen to White king) - (min distance of white queen to Black king). Larger positive => White queens are closer to Black king relative to Black queens'
    try:
        wk = board.king(chess.WHITE)
        bk = board.king(chess.BLACK)
        def min_dist_of_color_queens_to(square, color):
            if square is None:
                return 8.0
            mind = 8
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.QUEEN and p.color == color:
                    d = chess.square_distance(sq, square)
                    if d < mind:
                        mind = d
            return float(mind if mind < 8 else 8.0)
        d_bq_to_wk = min_dist_of_color_queens_to(wk, chess.BLACK)
        d_wq_to_bk = min_dist_of_color_queens_to(bk, chess.WHITE)
        # We want positive when white queens are closer to black king (good for White)
        return float(d_bq_to_wk - d_wq_to_bk)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn-structure penalty difference in centipawns: (black penalty) - (white penalty) where penalty = doubled*0.5 + isolated*1.0, scaled *100'
    try:
        files = range(8)
        pawn_files_white = {f:0 for f in files}
        pawn_files_black = {f:0 for f in files}
        pawn_squares_by_color = {chess.WHITE: [], chess.BLACK: []}
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if p.color == chess.WHITE:
                    pawn_files_white[f] += 1
                    pawn_squares_by_color[chess.WHITE].append(sq)
                else:
                    pawn_files_black[f] += 1
                    pawn_squares_by_color[chess.BLACK].append(sq)
        def penalty_for(color):
            pf = pawn_files_white if color == chess.WHITE else pawn_files_black
            doubled = sum(1 for f in pf if pf[f] > 1)
            isolated = 0
            # isolated pawn if no same-color pawns on adjacent files
            for sq in pawn_squares_by_color[color]:
                f = chess.square_file(sq)
                if (f-1 not in pf or pf.get(f-1,0) == 0) and (f+1 not in pf or pf.get(f+1,0) == 0):
                    isolated += 1
            return (doubled * 0.5 + isolated * 1.0) * 100.0
        white_pen = penalty_for(chess.WHITE)
        black_pen = penalty_for(chess.BLACK)
        # Positive means White structurally better (black penalty higher)
        return float(black_pen - white_pen)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rooks on the seventh rank advantage: (white rooks on rank 7) - (black rooks on rank 2) as a simple count'
    try:
        w_count = 0
        b_count = 0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.ROOK:
                r = chess.square_rank(sq)
                if p.color == chess.WHITE and r == 6:
                    w_count += 1
                if p.color == chess.BLACK and r == 1:
                    b_count += 1
        return float(w_count - b_count)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in pinned-material (white - black) where pinned pieces are weighted by simple piece values'
    try:
        vals = {chess.PAWN:100.0, chess.KNIGHT:320.0, chess.BISHOP:330.0, chess.ROOK:500.0, chess.QUEEN:900.0, chess.KING:0.0}
        white_sum = 0.0
        black_sum = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING:
                continue
            try:
                if board.is_pinned(p.color, sq):
                    if p.color == chess.WHITE:
                        white_sum += vals.get(p.piece_type, 0.0)
                    else:
                        black_sum += vals.get(p.piece_type, 0.0)
            except Exception:
                # Some older chess versions may not have is_pinned; ignore
                pass
        return float(white_sum - black_sum)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count of legal mate-in-one moves for the side to move (0.0 if none)'
    count = 0
    try:
        for m in board.legal_moves:
            board.push(m)
            if board.is_checkmate():
                count += 1
            board.pop()
    except Exception:
        # Be robust to weird positions / iterator invalidation
        try:
            # fallback: return 0 if something odd happens
            return 0.0
        except Exception:
            return 0.0
    return float(count)

def feature(board: chess.Board) -> float:
    'Sum of values of opponent pieces that are attacked by side-to-move and undefended (weighted, divided by 1000)'
    values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    side = board.turn
    opp = not side
    total = 0
    try:
        for sq, piece in board.piece_map().items():
            if piece.color != opp:
                continue
            if board.is_attacked_by(side, sq):
                defenders = board.attackers(opp, sq)
                if len(defenders) == 0:
                    total += values.get(piece.piece_type, 0)
    except Exception:
        return 0.0
    return float(total) / 1000.0

def feature(board: chess.Board) -> float:
    'Number of safe adjacent squares available to the side-to-move king (not attacked by opponent and not occupied by own pieces), 0..8'
    side = board.turn
    opp = not side
    king_sq = None
    try:
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING and p.color == side:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        kf = chess.square_file(king_sq)
        kr = chess.square_rank(king_sq)
        safe = 0
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                if df == 0 and dr == 0:
                    continue
                f = kf + df
                r = kr + dr
                if not (0 <= f <= 7 and 0 <= r <= 7):
                    continue
                sq2 = chess.square(f, r)
                occ = board.piece_at(sq2)
                # cannot move to a square occupied by own piece
                if occ is not None and occ.color == side:
                    continue
                # square must not be attacked by opponent
                if board.is_attacked_by(opp, sq2):
                    continue
                safe += 1
        return float(safe)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (white - black) in count of major pieces (rooks and queens) sitting on open files (no pawns on that file)'
    white_count = 0
    black_count = 0
    try:
        pawn_files = set()
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                pawn_files.add(chess.square_file(sq))
        for sq, p in board.piece_map().items():
            if p.piece_type in (chess.ROOK, chess.QUEEN):
                f = chess.square_file(sq)
                if f not in pawn_files:
                    if p.color == chess.WHITE:
                        white_count += 1
                    else:
                        black_count += 1
    except Exception:
        return 0.0
    return float(white_count - black_count)

def feature(board: chess.Board) -> float:
    'Passed-pawn advancement score: sum over passed pawns of normalized advancement (white - black), roughly in [ -#pawns .. #pawns ]'
    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        for sq2, p2 in board.piece_map().items():
            if p2.piece_type != chess.PAWN or p2.color == color:
                continue
            f2 = chess.square_file(sq2)
            r2 = chess.square_rank(sq2)
            if abs(f2 - f) <= 1:
                if color == chess.WHITE and r2 > r:
                    return False
                if color == chess.BLACK and r2 < r:
                    return False
        return True
    def advancement_norm(sq, color):
        rank_index = chess.square_rank(sq) + 1  # 1..8
        if color == chess.WHITE:
            if rank_index <= 2:
                return 0.0
            if rank_index >= 7:
                return 1.0
            return float(rank_index - 2) / 5.0
        else:
            # black advances to rank 1
            if rank_index >= 7:
                return 0.0
            if rank_index <= 2:
                return 1.0
            return float(7 - rank_index) / 5.0
    white_score = 0.0
    black_score = 0.0
    try:
        for sq, p in board.piece_map().items():
            if p.piece_type != chess.PAWN:
                continue
            if is_passed(sq, p.color):
                if p.color == chess.WHITE:
                    white_score += advancement_norm(sq, chess.WHITE)
                else:
                    black_score += advancement_norm(sq, chess.BLACK)
    except Exception:
        return 0.0
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Pressure on the opponent king: weighted sum of attackers (by side-to-move) to the king and surrounding squares, normalized by ~1000'
    side = board.turn
    opp = not side
    # find opponent king
    king_sq = None
    try:
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KING and p.color == opp:
                king_sq = sq
                break
        if king_sq is None:
            return 0.0
        weight = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
        total = 0.0
        # consider king square + adjacent 8 squares
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                f = chess.square_file(king_sq) + df
                r = chess.square_rank(king_sq) + dr
                if not (0 <= f <= 7 and 0 <= r <= 7):
                    continue
                sq2 = chess.square(f, r)
                attackers = list(board.attackers(side, sq2))
                for a in attackers:
                    ap = board.piece_at(a)
                    if ap is None:
                        continue
                    dist = chess.square_distance(a, king_sq)
                    total += weight.get(ap.piece_type, 0) / (1.0 + float(dist))
        return float(total) / 1000.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in sum of the top-two non-pawn piece values (white - black), measured in pawn-equivalents (/1000)'
    vals = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    white_vals = []
    black_vals = []
    try:
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN or p.piece_type == chess.KING:
                continue
            if p.color == chess.WHITE:
                white_vals.append(vals.get(p.piece_type, 0))
            else:
                black_vals.append(vals.get(p.piece_type, 0))
        white_vals.sort(reverse=True)
        black_vals.sort(reverse=True)
        white_sum = sum(white_vals[:2])
        black_sum = sum(black_vals[:2])
        return float(white_sum - black_sum) / 1000.0
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of pinned non-king pieces (white pinned - black pinned)'
    def sign(x):
        return 0 if x == 0 else (1 if x > 0 else -1)
    pinned_white = 0
    pinned_black = 0
    try:
        pos_map = board.piece_map()
        # find king squares
        king_sq = {chess.WHITE: None, chess.BLACK: None}
        for sq, p in pos_map.items():
            if p.piece_type == chess.KING:
                king_sq[p.color] = sq
        for sq, p in list(pos_map.items()):
            if p.piece_type == chess.KING:
                continue
            ksq = king_sq.get(p.color)
            if ksq is None:
                continue
            f1 = chess.square_file(ksq)
            r1 = chess.square_rank(ksq)
            f2 = chess.square_file(sq)
            r2 = chess.square_rank(sq)
            df = f2 - f1
            dr = r2 - r1
            # must be aligned
            if df == 0:
                step = (0, sign(dr))
            elif dr == 0:
                step = (sign(df), 0)
            elif abs(df) == abs(dr):
                step = (sign(df), sign(dr))
            else:
                continue
            # check there are no other pieces between king and this piece
            blocked = False
            step_f, step_r = step
            cur_f = f1 + step_f
            cur_r = r1 + step_r
            while (cur_f, cur_r) != (f2, r2):
                if not (0 <= cur_f <= 7 and 0 <= cur_r <= 7):
                    blocked = True
                    break
                if board.piece_at(chess.square(cur_f, cur_r)) is not None:
                    blocked = True
                    break
                cur_f += step_f
                cur_r += step_r
            if blocked:
                continue
            # now look beyond the piece outward away from king for the first piece
            out_f = f2 + step_f
            out_r = r2 + step_r
            attacker_found = False
            while 0 <= out_f <= 7 and 0 <= out_r <= 7:
                sq3 = chess.square(out_f, out_r)
                p3 = board.piece_at(sq3)
                if p3 is not None:
                    # must be opponent sliding piece of appropriate type
                    if p3.color != p.color:
                        if step == (0, 1) or step == (0, -1) or step == (1, 0) or step == (-1, 0):
                            if p3.piece_type in (chess.ROOK, chess.QUEEN):
                                attacker_found = True
                        else:
                            if p3.piece_type in (chess.BISHOP, chess.QUEEN):
                                attacker_found = True
                    break
                out_f += step_f
                out_r += step_r
            if attacker_found:
                if p.color == chess.WHITE:
                    pinned_white += 1
                else:
                    pinned_black += 1
        return float(pinned_white - pinned_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Count difference (white - black) of passed pawns that have a friendly rook/queen directly behind on same file with clear path (support for promotion)'
    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        for sq2, p2 in board.piece_map().items():
            if p2.piece_type != chess.PAWN or p2.color == color:
                continue
            f2 = chess.square_file(sq2)
            r2 = chess.square_rank(sq2)
            if abs(f2 - f) <= 1:
                if color == chess.WHITE and r2 > r:
                    return False
                if color == chess.BLACK and r2 < r:
                    return False
        return True
    def has_rook_support(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        # for white, rook behind means rook has smaller rank (closer to white base)
        if color == chess.WHITE:
            rng = range(r - 1, -1, -1)
        else:
            rng = range(r + 1, 8)
        for rr in rng:
            sq2 = chess.square(f, rr)
            p2 = board.piece_at(sq2)
            if p2 is None:
                continue
            if p2.color != color:
                return False
            if p2.piece_type in (chess.ROOK, chess.QUEEN):
                # ensure path between rook and pawn contains only those two pieces (we scanned outward so any blocker would have returned False)
                return True
            # any other friendly piece blocks support
            return False
        return False
    white_support = 0
    black_support = 0
    try:
        for sq, p in board.piece_map().items():
            if p.piece_type != chess.PAWN:
                continue
            if is_passed(sq, p.color) and has_rook_support(sq, p.color):
                if p.color == chess.WHITE:
                    white_support += 1
                else:
                    black_support += 1
        return float(white_support - black_support)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Central control difference: (number of central squares attacked by White - attacked by Black) / 4'
    central = [chess.parse_square(s) for s in ('d4', 'e4', 'd5', 'e5')]
    try:
        w = 0
        b = 0
        for sq in central:
            if board.is_attacked_by(chess.WHITE, sq):
                w += 1
            if board.is_attacked_by(chess.BLACK, sq):
                b += 1
        return float(w - b) / 4.0
    except Exception:
        return 0.0

def feature(board: 'chess.Board') -> float:
    'Difference in number of rooks on the opponent 7th rank (White on rank7 - Black on rank2)'
    import chess
    try:
        wm = 0
        bm = 0
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.ROOK:
                rank = chess.square_rank(sq)
                if piece.color == chess.WHITE and rank == 6:  # white on 7th rank (index 6)
                    wm += 1
                if piece.color == chess.BLACK and rank == 1:  # black on white's 7th (index 1)
                    bm += 1
        return float(wm - bm)
    except Exception:
        return 0.0

def feature(board: 'chess.Board') -> float:
    'Net heavy-piece (rooks/queens) attack pressure onto squares adjacent to the enemy king (White pressure on Black king - Black on White)'
    import chess
    try:
        def king_square(color):
            for s, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == color:
                    return s
            return None
        def adj_squares(sq):
            if sq is None:
                return []
            kf, kr = chess.square_file(sq), chess.square_rank(sq)
            res = []
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    nf, nr = kf + df, kr + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        res.append(chess.square(nf, nr))
            return res
        wk = king_square(chess.WHITE)
        bk = king_square(chess.BLACK)
        white_pressure = 0
        black_pressure = 0
        for sq in adj_squares(bk):
            attackers = board.attackers(chess.WHITE, sq)
            for a in attackers:
                p = board.piece_at(a)
                if p and p.piece_type in (chess.ROOK, chess.QUEEN):
                    white_pressure += 1
        for sq in adj_squares(wk):
            attackers = board.attackers(chess.BLACK, sq)
            for a in attackers:
                p = board.piece_at(a)
                if p and p.piece_type in (chess.ROOK, chess.QUEEN):
                    black_pressure += 1
        return float(white_pressure - black_pressure)
    except Exception:
        return 0.0

def feature(board: 'chess.Board') -> float:
    'Balance of control of open files: (number of open files with White heavy on file) - (same for Black)'
    import chess
    try:
        files_control_white = 0
        files_control_black = 0
        piece_map = board.piece_map()
        for f in range(8):
            has_pawn = False
            for r in range(8):
                sq = chess.square(f, r)
                p = piece_map.get(sq)
                if p and p.piece_type == chess.PAWN:
                    has_pawn = True
                    break
            if has_pawn:
                continue
            # open file, check if a rook or queen of a color occupies file (or controls file by occupying)
            w_present = any((piece_map.get(chess.square(f, r)) and piece_map[chess.square(f, r)].color == chess.WHITE and piece_map[chess.square(f, r)].piece_type in (chess.ROOK, chess.QUEEN)) for r in range(8))
            b_present = any((piece_map.get(chess.square(f, r)) and piece_map[chess.square(f, r)].color == chess.BLACK and piece_map[chess.square(f, r)].piece_type in (chess.ROOK, chess.QUEEN)) for r in range(8))
            if w_present:
                files_control_white += 1
            if b_present:
                files_control_black += 1
        return float(files_control_white - files_control_black)
    except Exception:
        return 0.0

def feature(board: 'chess.Board') -> float:
    'Balance of doubled rooks per file: sum_{files} max(0, white_rooks_on_file-1) - same for black'
    import chess
    try:
        piece_map = board.piece_map()
        white_extra = 0
        black_extra = 0
        for f in range(8):
            w_count = 0
            b_count = 0
            for r in range(8):
                p = piece_map.get(chess.square(f, r))
                if p and p.piece_type == chess.ROOK:
                    if p.color == chess.WHITE:
                        w_count += 1
                    else:
                        b_count += 1
            if w_count > 1:
                white_extra += (w_count - 1)
            if b_count > 1:
                black_extra += (b_count - 1)
        return float(white_extra - black_extra)
    except Exception:
        return 0.0

def feature(board: 'chess.Board') -> float:
    'Pawn shield measure: (count of white pawns immediately shielding white king) - (same for black). Lower means weaker shield.'
    import chess
    try:
        piece_map = board.piece_map()
        def find_king(color):
            for s,p in piece_map.items():
                if p.piece_type == chess.KING and p.color == color:
                    return s
            return None
        def shield_count(king_sq, color):
            if king_sq is None:
                return 0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            # forward direction for shield: white -> kr+1, black -> kr-1
            step = 1 if color == chess.WHITE else -1
            fr = kr + step
            cnt = 0
            for df in (-1, 0, 1):
                nf = kf + df
                if 0 <= nf <= 7 and 0 <= fr <= 7:
                    sq = chess.square(nf, fr)
                    p = piece_map.get(sq)
                    if p and p.piece_type == chess.PAWN and p.color == color:
                        cnt += 1
            return cnt
        wk = find_king(chess.WHITE)
        bk = find_king(chess.BLACK)
        return float(shield_count(wk, chess.WHITE) - shield_count(bk, chess.BLACK))
    except Exception:
        return 0.0

def feature(board: 'chess.Board') -> float:
    'Net forwardness of non-pawn, non-king pieces: sum(normalized distance into enemy half) White - Black'
    import chess
    try:
        piece_map = board.piece_map()
        score_w = 0.0
        score_b = 0.0
        for s, p in piece_map.items():
            if p.piece_type in (chess.PAWN, chess.KING):
                continue
            r = chess.square_rank(s)
            if p.color == chess.WHITE:
                # closer to rank 7 is more advanced: normalized 0..1
                score_w += (r / 7.0)
            else:
                # for black, closer to rank 0 is more advanced from black's perspective
                score_b += ((7 - r) / 7.0)
        return float(score_w - score_b)
    except Exception:
        return 0.0

def feature(board: 'chess.Board') -> float:
    'Count of squares in opponent half attacked by two or more friendly major pieces (rooks/queens) (White - Black)'
    import chess
    try:
        def count_multi_attacks(color):
            total = 0
            # opponent half: for white attacking black half ranks 4..7, for black ranks 0..3
            ranks = range(4, 8) if color == chess.WHITE else range(0, 4)
            for r in ranks:
                for f in range(8):
                    sq = chess.square(f, r)
                    attackers = board.attackers(color, sq)
                    cnt = 0
                    for a in attackers:
                        p = board.piece_at(a)
                        if p and p.color == color and p.piece_type in (chess.ROOK, chess.QUEEN):
                            cnt += 1
                    if cnt >= 2:
                        total += 1
            return total
        return float(count_multi_attacks(chess.WHITE) - count_multi_attacks(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: 'chess.Board') -> float:
    'Weighted material-at-risk: sum for pieces where attackers > defenders of (attackers-defenders)*piece_value (White - Black)'
    import chess
    try:
        values = {
            chess.PAWN: 1.0, chess.KNIGHT: 3.2, chess.BISHOP: 3.3,
            chess.ROOK: 5.0, chess.QUEEN: 9.0, chess.KING: 0.0
        }
        w_risk = 0.0
        b_risk = 0.0
        for sq, p in board.piece_map().items():
            attackers_by_opponent = len(board.attackers(not p.color, sq))
            defenders_by_self = len(board.attackers(p.color, sq))
            diff = attackers_by_opponent - defenders_by_self
            if diff > 0:
                val = values.get(p.piece_type, 0.0)
                if p.color == chess.WHITE:
                    w_risk += diff * val
                else:
                    b_risk += diff * val
        return float(w_risk - b_risk)
    except Exception:
        return 0.0

def feature(board: 'chess.Board') -> float:
    'Count of unobstructed in-line attacks by major pieces (rook/queen) on enemy king (same rank/file/diagonal with empty path) (White - Black)'
    import chess
    try:
        def find_king(color):
            for s,p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == color:
                    return s
            return None
        def clear_between(a, b):
            af, ar = chess.square_file(a), chess.square_rank(a)
            bf, br = chess.square_file(b), chess.square_rank(b)
            df = bf - af
            dr = br - ar
            step_f = 0 if df == 0 else (1 if df > 0 else -1)
            step_r = 0 if dr == 0 else (1 if dr > 0 else -1)
            # must be straight or diagonal
            if not (df == 0 or dr == 0 or abs(df) == abs(dr)):
                return False
            cf, cr = af + step_f, ar + step_r
            while (cf, cr) != (bf, br):
                if board.piece_at(chess.square(cf, cr)):
                    return False
                cf += step_f
                cr += step_r
                if not (0 <= cf <= 7 and 0 <= cr <= 7):
                    break
            return True
        wk = find_king(chess.WHITE)
        bk = find_king(chess.BLACK)
        w_count = 0
        b_count = 0
        for sq, p in board.piece_map().items():
            if p.piece_type in (chess.ROOK, chess.QUEEN):
                if p.color == chess.WHITE and bk is not None:
                    # aligned?
                    if clear_between(sq, bk):
                        # ensure line alignment
                        af, ar = chess.square_file(sq), chess.square_rank(sq)
                        bf, br = chess.square_file(bk), chess.square_rank(bk)
                        if af == bf or ar == br or abs(af - bf) == abs(ar - br):
                            w_count += 1
                if p.color == chess.BLACK and wk is not None:
                    if clear_between(sq, wk):
                        af, ar = chess.square_file(sq), chess.square_rank(sq)
                        bf, br = chess.square_file(wk), chess.square_rank(wk)
                        if af == bf or ar == br or abs(af - bf) == abs(ar - br):
                            b_count += 1
        return float(w_count - b_count)
    except Exception:
        return 0.0

def feature(board: 'chess.Board') -> float:
    'Advanced passed pawn score: sum over passed pawns of progress-to-promotion (0..1) weighted by color (White - Black)'
    import chess
    try:
        piece_map = board.piece_map()
        def is_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if color == chess.WHITE:
                # any black pawn on same or adjacent file in ranks > r blocks it
                for bf in (f-1, f, f+1):
                    if 0 <= bf <= 7:
                        for br in range(r+1, 8):
                            p = piece_map.get(chess.square(bf, br))
                            if p and p.piece_type == chess.PAWN and p.color == chess.BLACK:
                                return False
                return True
            else:
                for bf in (f-1, f, f+1):
                    if 0 <= bf <= 7:
                        for br in range(0, r):
                            p = piece_map.get(chess.square(bf, br))
                            if p and p.piece_type == chess.PAWN and p.color == chess.WHITE:
                                return False
                return True
        w_score = 0.0
        b_score = 0.0
        for sq, p in piece_map.items():
            if p.piece_type != chess.PAWN:
                continue
            r = chess.square_rank(sq)
            if is_passed(sq, p.color):
                if p.color == chess.WHITE:
                    # progress normalized: rank 1->6 map to ~0..1 (avoid rank0 edge)
                    progress = r / 7.0
                    w_score += progress
                else:
                    progress = (7 - r) / 7.0
                    b_score += progress
        return float(w_score - b_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of rooks on the opponent seventh rank (White - Black)'
    try:
        wm = 0
        bm = 0
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.ROOK:
                rank = chess.square_rank(sq)
                if piece.color == chess.WHITE and rank == 6:
                    wm += 1
                if piece.color == chess.BLACK and rank == 1:
                    bm += 1
        return float(wm - bm)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of rooks placed on open files (no pawns on that file) (White - Black)'
    try:
        files_with_pawns = set()
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.PAWN:
                files_with_pawns.add(chess.square_file(sq))
        wcount = 0
        bcount = 0
        for sq, piece in board.piece_map().items():
            if piece.piece_type == chess.ROOK:
                if chess.square_file(sq) not in files_with_pawns:
                    if piece.color == chess.WHITE:
                        wcount += 1
                    else:
                        bcount += 1
        return float(wcount - bcount)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of passed pawns (White - Black), simple adjacent-file check'
    try:
        pm = board.piece_map()
        white_passed = 0
        black_passed = 0
        # build pawn lists by color and file
        pawns_by_color = {chess.WHITE: [], chess.BLACK: []}
        for sq, piece in pm.items():
            if piece.piece_type == chess.PAWN:
                pawns_by_color[piece.color].append(sq)
        # helper to test presence of enemy pawn on file and ahead
        for sq in pawns_by_color[chess.WHITE]:
            r = chess.square_rank(sq)
            f = chess.square_file(sq)
            is_passed = True
            for ef in (f - 1, f, f + 1):
                if 0 <= ef <= 7:
                    for esq in pawns_by_color[chess.BLACK]:
                        if chess.square_file(esq) == ef and chess.square_rank(esq) > r:
                            is_passed = False
                            break
                if not is_passed:
                    break
            if is_passed:
                white_passed += 1
        for sq in pawns_by_color[chess.BLACK]:
            r = chess.square_rank(sq)
            f = chess.square_file(sq)
            is_passed = True
            for ef in (f - 1, f, f + 1):
                if 0 <= ef <= 7:
                    for esq in pawns_by_color[chess.WHITE]:
                        if chess.square_file(esq) == ef and chess.square_rank(esq) < r:
                            is_passed = False
                            break
                if not is_passed:
                    break
            if is_passed:
                black_passed += 1
        return float(white_passed - black_passed)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in pawn shield strength around the king (friendly pawns in front two ranks and adjacent files) White - Black'
    try:
        def shield_for_king(color):
            king_sq = None
            for sq, pc in board.piece_map().items():
                if pc.piece_type == chess.KING and pc.color == color:
                    king_sq = sq
                    break
            if king_sq is None:
                return 0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            count = 0
            if color == chess.WHITE:
                ranks = [kr + 1, kr + 2]
            else:
                ranks = [kr - 1, kr - 2]
            for rf in ranks:
                if 0 <= rf <= 7:
                    for ff in (kf - 1, kf, kf + 1):
                        if 0 <= ff <= 7:
                            sq = chess.square(ff, rf)
                            p = board.piece_at(sq)
                            if p is not None and p.piece_type == chess.PAWN and p.color == color:
                                count += 1
            return count
        return float(shield_for_king(chess.WHITE) - shield_for_king(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of minor pieces (knights/bishops) securely posted on central outpost squares (d4,e4,d5,e5) without an enemy pawn attacking them (White - Black)'
    try:
        center_names = ['d4', 'e4', 'd5', 'e5']
        centers = [chess.parse_square(n) for n in center_names]
        wm = 0
        bm = 0
        for sq, piece in board.piece_map().items():
            if piece.piece_type in (chess.KNIGHT, chess.BISHOP):
                if sq in centers:
                    enemy = chess.BLACK if piece.color == chess.WHITE else chess.WHITE
                    attackers = board.attackers(enemy, sq)
                    attacked_by_enemy_pawn = False
                    for a in attackers:
                        ap = board.piece_at(a)
                        if ap is not None and ap.piece_type == chess.PAWN:
                            attacked_by_enemy_pawn = True
                            break
                    if not attacked_by_enemy_pawn:
                        if piece.color == chess.WHITE:
                            wm += 1
                        else:
                            bm += 1
        return float(wm - bm)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in average pairwise Chebyshev distance between non-king pieces (Black avg - White avg); positive means White pieces are more clustered'
    try:
        pm = board.piece_map()
        white_sq = [sq for sq, p in pm.items() if p.piece_type != chess.KING and p.color == chess.WHITE]
        black_sq = [sq for sq, p in pm.items() if p.piece_type != chess.KING and p.color == chess.BLACK]
        def avg_pairwise(sqs):
            n = len(sqs)
            if n <= 1:
                return 0.0
            total = 0.0
            pairs = 0
            for i in range(n):
                for j in range(i+1, n):
                    total += chess.square_distance(sqs[i], sqs[j])
                    pairs += 1
            return total / pairs if pairs else 0.0
        wa = avg_pairwise(white_sq)
        ba = avg_pairwise(black_sq)
        return float(ba - wa)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of passed pawns that are defended by at least one friendly piece (White - Black)'
    try:
        pm = board.piece_map()
        pawns_by_color = {chess.WHITE: [], chess.BLACK: []}
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                pawns_by_color[p.color].append(sq)
        def is_passed(sq, color):
            r = chess.square_rank(sq)
            f = chess.square_file(sq)
            enemy = chess.BLACK if color == chess.WHITE else chess.WHITE
            if color == chess.WHITE:
                for ef in (f-1, f, f+1):
                    if 0 <= ef <= 7:
                        for esq in pawns_by_color[enemy]:
                            if chess.square_file(esq) == ef and chess.square_rank(esq) > r:
                                return False
            else:
                for ef in (f-1, f, f+1):
                    if 0 <= ef <= 7:
                        for esq in pawns_by_color[enemy]:
                            if chess.square_file(esq) == ef and chess.square_rank(esq) < r:
                                return False
            return True
        wdef = 0
        bdef = 0
        for sq in pawns_by_color[chess.WHITE]:
            if is_passed(sq, chess.WHITE):
                if board.attackers(chess.WHITE, sq):
                    wdef += 1
        for sq in pawns_by_color[chess.BLACK]:
            if is_passed(sq, chess.BLACK):
                if board.attackers(chess.BLACK, sq):
                    bdef += 1
        return float(wdef - bdef)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King centralization advantage measured as (black king distance to center - white king distance to center); positive favors White'
    try:
        centers = [chess.parse_square(n) for n in ('d4','e4','d5','e5')]
        def king_min_dist(color):
            for sq, p in board.piece_map().items():
                if p.piece_type == chess.KING and p.color == color:
                    ks = sq
                    break
            else:
                return 8.0
            d = min(chess.square_distance(ks, c) for c in centers)
            return float(d)
        return float(king_min_dist(chess.BLACK) - king_min_dist(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in minor-piece mobility penalty: sum over knights and bishops of 1/(1+legal_moves_from_square) (White - Black). Higher = more stuck pieces.'
    try:
        pm = board.piece_map()
        # Precompute legal move-from counts
        moves_from = {}
        for mv in board.legal_moves:
            moves_from.setdefault(mv.from_square, 0)
            moves_from[mv.from_square] += 1
        wsum = 0.0
        bsum = 0.0
        for sq, p in pm.items():
            if p.piece_type in (chess.KNIGHT, chess.BISHOP):
                cnt = moves_from.get(sq, 0)
                penalty = 1.0 / (1.0 + cnt)
                if p.color == chess.WHITE:
                    wsum += penalty
                else:
                    bsum += penalty
        return float(wsum - bsum)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of isolated pawns (no friendly pawns on adjacent files) (White - Black)'
    try:
        pm = board.piece_map()
        pawns_files = {chess.WHITE: set(), chess.BLACK: set()}
        pawns_by_file = {chess.WHITE: {}, chess.BLACK: {}}
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                pawns_files[p.color].add(f)
                pawns_by_file[p.color].setdefault(f, []).append(sq)
        def isolated_count(color):
            cnt = 0
            for f in list(pawns_files[color]):
                if not ((f-1) in pawns_files[color] or (f+1) in pawns_files[color]):
                    # each pawn on that file counts as isolated (double isolated if multiple)
                    cnt += len(pawns_by_file[color].get(f, []))
            return cnt
        return float(isolated_count(chess.WHITE) - isolated_count(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Weighted sum of non-pawn White pieces proximity to the Black king minus Black pieces proximity to the White king (higher -> more attacking mass near enemy king)'
    # piece values in centipawns
    values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    pm = board.piece_map()
    # find kings
    white_king_sq = None
    black_king_sq = None
    for sq, pc in pm.items():
        if pc.piece_type == chess.KING:
            if pc.color == chess.WHITE:
                white_king_sq = sq
            else:
                black_king_sq = sq
    if white_king_sq is None or black_king_sq is None:
        return 0.0
    def mass_towards(king_sq, color):
        s = 0.0
        for sq, pc in pm.items():
            if pc.color != color and pc.piece_type != chess.PAWN:
                val = values.get(pc.piece_type, 0)
                d = chess.square_distance(sq, king_sq)
                # use inverse-distance weighting; if on the king square (rare), treat as very close
                s += val / (1.0 + d)
        return s
    white_mass = mass_towards(black_king_sq, chess.WHITE)
    black_mass = mass_towards(white_king_sq, chess.BLACK)
    # return in pawn units (divide by 100) for comparability with other features
    return (white_mass - black_mass) / 100.0

def feature(board: chess.Board) -> float:
    'Difference in number of defended passed pawns (White - Black); counts only pawns that are passed and have at least one friendly attacker or pawn defender'
    pm = board.piece_map()
    def is_passed(sq, color):
        rank = chess.square_rank(sq)
        file = chess.square_file(sq)
        # direction: white moves up (rank increases), black moves down (rank decreases)
        if color == chess.WHITE:
            forward_range = range(rank+1, 8)
            opp_pawns = [sq2 for sq2, pc in pm.items() if pc.piece_type==chess.PAWN and pc.color==chess.BLACK]
            for r in forward_range:
                for f in (file-1, file, file+1):
                    if 0 <= f < 8:
                        if chess.parse_square(chess.square_name(chess.square(f, r))) in opp_pawns:
                            return False
            return True
        else:
            forward_range = range(rank-1, -1, -1)
            opp_pawns = [sq2 for sq2, pc in pm.items() if pc.piece_type==chess.PAWN and pc.color==chess.WHITE]
            for r in forward_range:
                for f in (file-1, file, file+1):
                    if 0 <= f < 8:
                        if chess.parse_square(chess.square_name(chess.square(f, r))) in opp_pawns:
                            return False
            return True
    # More robust implementation: iterate pawns and check opposing pawns on same/adj files ahead
    def is_passed_alt(sq, color):
        rank = chess.square_rank(sq)
        file = chess.square_file(sq)
        for sq2, pc in pm.items():
            if pc.piece_type == chess.PAWN and pc.color != color:
                f2 = chess.square_file(sq2)
                r2 = chess.square_rank(sq2)
                if abs(f2 - file) <= 1:
                    if color == chess.WHITE and r2 > rank:
                        return False
                    if color == chess.BLACK and r2 < rank:
                        return False
        return True
    def has_friendly_defender(sq, color):
        # a defender is any friendly piece that attacks this square (including pawns)
        try:
            attackers = board.attackers(color, sq)
            return len(attackers) > 0
        except Exception:
            return False
    wp = 0
    bp = 0
    for sq, pc in pm.items():
        if pc.piece_type == chess.PAWN:
            if pc.color == chess.WHITE:
                if is_passed_alt(sq, chess.WHITE) and has_friendly_defender(sq, chess.WHITE):
                    wp += 1
            else:
                if is_passed_alt(sq, chess.BLACK) and has_friendly_defender(sq, chess.BLACK):
                    bp += 1
    return float(wp - bp)

def feature(board: chess.Board) -> float:
    'Rook file quality: open files count weighted (open=1.0, half-open=0.5) for White minus Black (higher -> better rook activity)'
    pm = board.piece_map()
    # collect pawn presence per file
    file_has_white_pawn = [False]*8
    file_has_black_pawn = [False]*8
    for sq, pc in pm.items():
        if pc.piece_type == chess.PAWN:
            f = chess.square_file(sq)
            if pc.color == chess.WHITE:
                file_has_white_pawn[f] = True
            else:
                file_has_black_pawn[f] = True
    def rook_score(color):
        score = 0.0
        for sq, pc in pm.items():
            if pc.piece_type == chess.ROOK and pc.color == color:
                f = chess.square_file(sq)
                white_p = file_has_white_pawn[f]
                black_p = file_has_black_pawn[f]
                if not white_p and not black_p:
                    score += 1.0  # open file
                elif (color == chess.WHITE and not white_p) or (color == chess.BLACK and not black_p):
                    score += 0.5  # half-open for that rook
        return score
    return float(rook_score(chess.WHITE) - rook_score(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Count difference of friendly pawns within Manhattan distance <=2 of own king (White minus Black); proxies pawn-shield integrity (higher -> better protected)'
    pm = board.piece_map()
    white_king_sq = None
    black_king_sq = None
    for sq, pc in pm.items():
        if pc.piece_type == chess.KING:
            if pc.color == chess.WHITE:
                white_king_sq = sq
            else:
                black_king_sq = sq
    def pawn_shield_count(king_sq, color):
        if king_sq is None:
            return 0
        count = 0
        for sq, pc in pm.items():
            if pc.piece_type == chess.PAWN and pc.color == color:
                if chess.square_distance(sq, king_sq) <= 2:
                    count += 1
        return count
    return float(pawn_shield_count(chess.parse_square(chess.square_name(white_king_sq)) if white_king_sq is not None else None, chess.WHITE) - pawn_shield_count(chess.parse_square(chess.square_name(black_king_sq)) if black_king_sq is not None else None, chess.BLACK)) if False else float((0 if white_king_sq is None else sum(1 for sq,pc in pm.items() if pc.piece_type==chess.PAWN and pc.color==chess.WHITE and chess.square_distance(sq, white_king_sq)<=2)) - (0 if black_king_sq is None else sum(1 for sq,pc in pm.items() if pc.piece_type==chess.PAWN and pc.color==chess.BLACK and chess.square_distance(sq, black_king_sq)<=2)))

def feature(board: chess.Board) -> float:
    'Number of non-pawn White pieces attacking squares within distance 2 of the Black king minus the analogous Black count (measures pressure close to king)'
    pm = board.piece_map()
    white_king_sq = None
    black_king_sq = None
    for sq, pc in pm.items():
        if pc.piece_type == chess.KING:
            if pc.color == chess.WHITE:
                white_king_sq = sq
            else:
                black_king_sq = sq
    if white_king_sq is None or black_king_sq is None:
        return 0.0
    def pressure_on_king(king_sq, attacker_color):
        count = 0
        for sq, pc in pm.items():
            if pc.color == attacker_color and pc.piece_type != chess.PAWN:
                # does this piece attack any square within distance<=2 of king?
                try:
                    for target in range(64):
                        if chess.square_distance(target, king_sq) <= 2 and board.is_attacked_by(attacker_color, target):
                            # ensure the piece at sq actually contributes: check if that piece attacks target
                            if sq in board.attackers(attacker_color, target):
                                count += 1
                                break
                except Exception:
                    continue
        return count
    white_pressure = pressure_on_king(black_king_sq, chess.WHITE)
    black_pressure = pressure_on_king(white_king_sq, chess.BLACK)
    return float(white_pressure - black_pressure)

def feature(board: chess.Board) -> float:
    'Number of squares attacked by at least two distinct White non-king pieces minus same for Black (measures double-attack potential / coordination)'
    pm = board.piece_map()
    def multi_attack_count(color):
        counts = 0
        for sq in range(64):
            # count how many distinct non-king pieces of color attack this square
            try:
                attackers = board.attackers(color, sq)
            except Exception:
                attackers = set()
            n = 0
            for a in attackers:
                pc = board.piece_at(a)
                if pc is None:
                    continue
                if pc.color == color and pc.piece_type != chess.KING:
                    n += 1
                    if n >= 2:
                        counts += 1
                        break
        return counts
    return float(multi_attack_count(chess.WHITE) - multi_attack_count(chess.BLACK))

def feature(board: chess.Board) -> float:
    'Back-rank pawn shield weakness difference: (Black weakness - White weakness) where weakness counts missing pawns immediately in front of the king on its home-ish rank (positive -> White advantage)'
    pm = board.piece_map()
    white_king_sq = None
    black_king_sq = None
    for sq, pc in pm.items():
        if pc.piece_type == chess.KING:
            if pc.color == chess.WHITE:
                white_king_sq = sq
            else:
                black_king_sq = sq
    def backrank_weakness(king_sq, color):
        if king_sq is None:
            return 0
        kr = chess.square_rank(king_sq)
        kf = chess.square_file(king_sq)
        weakness = 0
        # examine up to three files centered on king file for pawn presence on the rank in front of the king
        front_rank = kr + 1 if color == chess.WHITE else kr - 1
        for f in range(kf-1, kf+2):
            if 0 <= f < 8 and 0 <= front_rank < 8:
                sq = chess.square(f, front_rank)
                pc = board.piece_at(sq)
                if not (pc and pc.piece_type == chess.PAWN and pc.color == color):
                    weakness += 1
        return weakness
    white_w = backrank_weakness(white_king_sq, chess.WHITE)
    black_w = backrank_weakness(black_king_sq, chess.BLACK)
    return float(black_w - white_w)

def feature(board: chess.Board) -> float:
    'Bishop-versus-knight structural balance: (White bishops - White knights) - (Black bishops - Black knights) in piece-count units (positive favors White bishops)'
    pm = board.piece_map()
    wb = wn = bb = bn = 0
    for sq, pc in pm.items():
        if pc.piece_type == chess.BISHOP:
            if pc.color == chess.WHITE: wb += 1
            else: bb += 1
        elif pc.piece_type == chess.KNIGHT:
            if pc.color == chess.WHITE: wn += 1
            else: bn += 1
    return float((wb - wn) - (bb - bn))

def feature(board: chess.Board) -> float:
    'Pressure on high-value pieces: sum over non-pawn pieces of value*(max(0, attackers-defenders)) for White minus Black (measures net imbalance of pressure)'
    values = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    pm = board.piece_map()
    white_pressure = 0.0
    black_pressure = 0.0
    for sq, pc in pm.items():
        if pc.piece_type == chess.PAWN:
            continue
        try:
            attackers_white = len([a for a in board.attackers(chess.WHITE, sq) if board.piece_at(a) and board.piece_at(a).color==chess.WHITE])
            attackers_black = len([a for a in board.attackers(chess.BLACK, sq) if board.piece_at(a) and board.piece_at(a).color==chess.BLACK])
        except Exception:
            attackers_white = attackers_black = 0
        if pc.color == chess.WHITE:
            net = max(0, attackers_black - attackers_white)
            white_pressure += values.get(pc.piece_type, 0) * net
        else:
            net = max(0, attackers_white - attackers_black)
            black_pressure += values.get(pc.piece_type, 0) * net
    # return in pawn units
    return (white_pressure - black_pressure) / 100.0

def feature(board: chess.Board) -> float:
    'Pawn structure weakness difference: (Black weakness - White weakness) where weakness = isolated pawns + 0.5 * doubled pawns (positive -> White advantage)'
    pm = board.piece_map()
    def pawn_weakness(color):
        pawns_by_file = {f:[] for f in range(8)}
        for sq, pc in pm.items():
            if pc.piece_type == chess.PAWN and pc.color == color:
                pawns_by_file[chess.square_file(sq)].append(sq)
        isolated = 0
        doubled = 0
        for f in range(8):
            if len(pawns_by_file[f]) == 0:
                continue
            # doubled if more than one pawn on file
            if len(pawns_by_file[f]) > 1:
                doubled += (len(pawns_by_file[f]) - 1)
            # isolated if no friendly pawn on adjacent files
            adj = False
            for af in (f-1, f+1):
                if 0 <= af < 8 and len(pawns_by_file[af]) > 0:
                    adj = True
                    break
            if not adj:
                isolated += len(pawns_by_file[f])
        return isolated + 0.5 * doubled
    return float(pawn_weakness(chess.BLACK) - pawn_weakness(chess.WHITE))

def feature(board: chess.Board) -> float:
    'Difference in pawn-shield integrity in front of each king (White - Black). Counts friendly pawns on the three-files in the two ranks immediately in front of the king'
    try:
        pieces = board.piece_map()
        # locate kings
        white_king = next((sq for sq, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        black_king = next((sq for sq, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        def shield_count(king_sq, color):
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            forward = 1 if color == chess.WHITE else -1
            count = 0
            for dr in (1, 2):
                r = kr + forward * dr
                if not (0 <= r <= 7):
                    continue
                for df in (-1, 0, 1):
                    f = kf + df
                    if not (0 <= f <= 7):
                        continue
                    sq = chess.square(f, r)
                    p = board.piece_at(sq)
                    if p is not None and p.piece_type == chess.PAWN and p.color == color:
                        count += 1
            return float(count)
        return float(shield_count(white_king, chess.WHITE) - shield_count(black_king, chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn pressure difference (White - Black). Sum over passed pawns weighted by advancement (rank for white, 7-rank for black)'
    try:
        pieces = board.piece_map()
        white_score = 0.0
        black_score = 0.0
        for sq, p in pieces.items():
            if p.piece_type != chess.PAWN:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if p.color == chess.WHITE:
                # check for any black pawn on same or adjacent files ahead (higher rank)
                blocking = False
                for af in (f-1, f, f+1):
                    if af < 0 or af > 7:
                        continue
                    for br in range(r+1, 8):
                        bsq = chess.square(af, br)
                        bp = board.piece_at(bsq)
                        if bp is not None and bp.piece_type == chess.PAWN and bp.color == chess.BLACK:
                            blocking = True
                            break
                    if blocking:
                        break
                if not blocking:
                    white_score += (r / 7.0) + 0.2  # weight by advancement (0..1) plus small base
            else:
                # black pawn: check for white pawns ahead (lower rank)
                blocking = False
                for af in (f-1, f, f+1):
                    if af < 0 or af > 7:
                        continue
                    for br in range(r-1, -1, -1):
                        bsq = chess.square(af, br)
                        bp = board.piece_at(bsq)
                        if bp is not None and bp.piece_type == chess.PAWN and bp.color == chess.WHITE:
                            blocking = True
                            break
                    if blocking:
                        break
                if not blocking:
                    black_score += ((7 - r) / 7.0) + 0.2
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rook presence on open or semi-open files difference (White - Black). Rooks on files with no pawns get bonus; semi-open (only enemy pawns) get smaller bonus'
    try:
        pawn_files = {f: {'white':0, 'black':0} for f in range(8)}
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.PAWN:
                pawn_files[chess.square_file(sq)][ 'white' if p.color == chess.WHITE else 'black'] += 1
        white_score = 0.0
        black_score = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type != chess.ROOK:
                continue
            f = chess.square_file(sq)
            files_info = pawn_files[f]
            total = files_info['white'] + files_info['black']
            if total == 0:
                bonus = 1.5
            elif files_info['white'] == 0 and files_info['black'] > 0:
                bonus = 1.0
            elif files_info['black'] == 0 and files_info['white'] > 0:
                bonus = 1.0
            else:
                bonus = 0.0
            if p.color == chess.WHITE:
                white_score += bonus
            else:
                black_score += bonus
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Central knight presence difference (White - Black). Counts knights on the four central squares (d4,e4,d5,e5)'
    try:
        central = {chess.parse_square(s) for s in ('d4','e4','d5','e5')}
        white = 0.0
        black = 0.0
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KNIGHT:
                if sq in central:
                    if p.color == chess.WHITE:
