def feature(board: chess.Board) -> float:
    'King pawn-shield weakness: for each side, count missing pawns on the three-file front shield (files king_file-1..+1), return White - Black (higher = weaker white shelter)'
    try:
        def missing_shield_for_king(color):
            king_sq = board.king(color)
            if king_sq is None:
                return 3.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            missing = 0
            forward = 1 if color == chess.WHITE else -1
            # check the rank immediately in front of the king
            shield_rank = kr + forward
            for df in (-1, 0, 1):
                f = kf + df
                if 0 <= f < 8 and 0 <= shield_rank < 8:
                    sq = chess.square(f, shield_rank)
                    piece = board.piece_at(sq)
                    if not (piece and piece.piece_type == chess.PAWN and piece.color == color):
                        missing += 1
                else:
                    missing += 1
            return missing
        return float(missing_shield_for_king(chess.WHITE) - missing_shield_for_king(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
