def feature(board: chess.Board) -> float:
    'Passed pawn potential difference: sum over passed pawns weighted by advancement (higher = stronger); result is White - Black'
    try:
        wpawns = [sq for sq, p in board.piece_map().items() if p.piece_type == chess.PAWN and p.color == chess.WHITE]
        bpawns = [sq for sq, p in board.piece_map().items() if p.piece_type == chess.PAWN and p.color == chess.BLACK]
        wp_score = 0.0
        bp_score = 0.0
        bp_files = {chess.square_file(sq) for sq in bpawns}
        wp_files = {chess.square_file(sq) for sq in wpawns}
        # helper to check passed
        def is_passed(sq, color, opp_pawns):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            for of in (f-1, f, f+1):
                if 0 <= of < 8:
                    for opsq in opp_pawns:
                        orank = chess.square_rank(opsq)
                        if color == chess.WHITE:
                            if orank > r and chess.square_file(opsq) == of:
                                return False
                        else:
                            if orank < r and chess.square_file(opsq) == of:
                                return False
            return True
        for sq in wpawns:
            if is_passed(sq, chess.WHITE, bpawns):
                adv = chess.square_rank(sq)  # 0..7, larger means more advanced
                wp_score += 1.0 + (adv / 7.0)
        for sq in bpawns:
            if is_passed(sq, chess.BLACK, wpawns):
                adv = 7 - chess.square_rank(sq)
                bp_score += 1.0 + (adv / 7.0)
        return float(wp_score - bp_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference (White - Black) in number of pinned non-king pieces (simple geometric detection by ray between opponent slider and king)'
    try:
        pm = board.piece_map()
        pinned_white = 0
        pinned_black = 0
        # sliding opponent pieces we consider
        sliders = {chess.ROOK, chess.BISHOP, chess.QUEEN}
        # helper to get sign
        def sgn(x):
            return 0 if x == 0 else (1 if x > 0 else -1)
        # Precompute piece positions for fast lookup
        occupancy = {sq: p for sq, p in pm.items()}
        for sq, p in pm.items():
            if p.piece_type == chess.KING:
                continue
        # For each side, inspect opponent sliders
        for side in (chess.WHITE, chess.BLACK):
            king_sq = board.king(side)
            if king_sq is None:
                continue
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            # iterate opponent sliders
            for osq, op in pm.items():
                if op.color == (not side) and op.piece_type in sliders:
                    of = chess.square_file(osq)
                    orank = chess.square_rank(osq)
                    df = kf - of
                    dr = kr - orank
                    # must be aligned along rook or bishop or queen ray
                    if df == 0 or dr == 0 or abs(df) == abs(dr):
                        step_f = sgn(df)
                        step_r = sgn(dr)
                        # walk from opponent piece towards king, count pieces encountered
                        cur_f = of + step_f
                        cur_r = orank + step_r
                        pieces_encountered = []
                        blocked = False
                        while 0 <= cur_f < 8 and 0 <= cur_r < 8:
                            cur_sq = chess.square(cur_f, cur_r)
                            if cur_sq in occupancy:
                                pieces_encountered.append((cur_sq, occupancy[cur_sq]))
                                if len(pieces_encountered) > 2:
                                    blocked = True
                                    break
                            if cur_sq == king_sq:
                                break
                            cur_f += step_f
                            cur_r += step_r
                        if blocked:
                            continue
                        # If exactly one non-king piece between slider and king, that piece is pinned
                        if len(pieces_encountered) == 1:
                            mid_sq, mid_p = pieces_encountered[0]
                            if mid_p.piece_type != chess.KING and mid_p.color == side:
                                if side == chess.WHITE:
                                    pinned_white += 1
                                else:
                                    pinned_black += 1
        return float(pinned_white - pinned_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Difference in number of friendly pawn-defenders immediately adjacent to the king (within one king-move), White - Black (higher means better defended)'
    try:
        def pawn_defenders(color):
            ks = board.king(color)
            if ks is None:
                return 0.0
            defenders = 0
            kf = chess.square_file(ks)
            kr = chess.square_rank(ks)
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    f = kf + df
                    r = kr + dr
                    if 0 <= f < 8 and 0 <= r < 8:
                        sq = chess.square(f, r)
                        p = board.piece_at(sq)
                        if p and p.color == color and p.piece_type == chess.PAWN:
                            defenders += 1
            return float(defenders)
        return float(pawn_defenders(chess.WHITE) - pawn_defenders(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Knight mobility imbalance: (sum legal moves of White knights) - (sum legal moves of Black knights) normalized, knights trapped will score low'
    try:
        wm = 0
        bm = 0
        # legal_moves is an iterator; collect by origin
        legal_from = {}
        for mv in board.legal_moves:
            legal_from.setdefault(mv.from_square, 0)
            legal_from[mv.from_square] += 1
        for sq, p in board.piece_map().items():
            if p.piece_type == chess.KNIGHT:
                mcount = legal_from.get(sq, 0)
                if p.color == chess.WHITE:
                    wm += mcount
                else:
                    bm += mcount
        # normalize by max(1, number of knights) to keep scale reasonable
        wkn = sum(1 for p in board.piece_map().values() if p.piece_type == chess.KNIGHT and p.color == chess.WHITE)
        bkn = sum(1 for p in board.piece_map().values() if p.piece_type == chess.KNIGHT and p.color == chess.BLACK)
        wm_norm = wm / max(1.0, wkn)
        bm_norm = bm / max(1.0, bkn)
        return float(wm_norm - bm_norm)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Back-rank pressure: (White heavy pieces — rooks/queens) on Black back rank (rank 7) minus Black heavy pieces on White back rank; useful for mate/back-rank threats'
    try:
        wcount = 0
        bcount = 0
        for sq, p in board.piece_map().items():
            if p.piece_type in (chess.ROOK, chess.QUEEN):
                r = chess.square_rank(sq)
                if p.color == chess.WHITE and r == 7:
                    wcount += 1
                if p.color == chess.BLACK and r == 0:
                    bcount += 1
        return float(wcount - bcount)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Major-piece coordination: (Black avg pairwise distance between rooks+queens) - (White avg pairwise distance between rooks+queens). Lower distance means better coordination; positive means White better coordinated'
    try:
        def avg_pairwise_distance(color):
            squares = [sq for sq, p in board.piece_map().items() if p.color == color and p.piece_type in (chess.ROOK, chess.QUEEN)]
            n = len(squares)
            if n < 2:
                return 8.0  # large distance penalty when few majors
            total = 0
            pairs = 0
            for i in range(n):
                for j in range(i+1, n):
                    total += chess.square_distance(squares[i], squares[j])
                    pairs += 1
            return total / pairs if pairs > 0 else 8.0
        b_avg = avg_pairwise_distance(chess.BLACK)
        w_avg = avg_pairwise_distance(chess.WHITE)
        # smaller average distance -> better coordination, so invert and return White - Black
        return float((1.0 / (1.0 + w_avg)) - (1.0 / (1.0 + b_avg)))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn structural weakness difference: (doubled + isolated pawns) for White minus Black (higher = worse for White)'
    try:
        pm = board.piece_map()
        wp_files = {}
        bp_files = {}
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if p.color == chess.WHITE:
                    wp_files.setdefault(f, []).append(sq)
                else:
                    bp_files.setdefault(f, []).append(sq)
        def structural_penalty(files_dict, color):
            doubled = sum(max(0, len(lst)-1) for lst in files_dict.values())
            isolated = 0
            for f in range(8):
                if f not in files_dict:
                    continue
                # isolated if no friendly pawns on adjacent files
                if (f-1 not in files_dict) and (f+1 not in files_dict):
                    isolated += len(files_dict[f])
            return doubled + isolated
        wp = structural_penalty(wp_files, chess.WHITE)
        bp = structural_penalty(bp_files, chess.BLACK)
        return float(wp - bp)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King proximity danger: weighted sum of enemy piece proximity to each king (White minus Black)'
    import chess
    try:
        piece_map = board.piece_map()
        # weights for piece types (in arbitrary danger units)
        weights = {
            chess.PAWN: 10.0,
            chess.KNIGHT: 30.0,
            chess.BISHOP: 30.0,
            chess.ROOK: 50.0,
            chess.QUEEN: 90.0,
            chess.KING: 20.0
        }
        def king_danger(king_sq, attacker_color):
            danger = 0.0
            if king_sq is None:
                return 0.0
            for sq, piece in piece_map.items():
                if piece.color != attacker_color:
                    continue
                wt = weights.get(piece.piece_type, 10.0)
                dist = chess.square_distance(king_sq, sq)  # Manhattan distance
                # farther pieces contribute less; avoid div by zero
                danger += wt / (1.0 + dist)
            return danger
        # find kings
        white_king = None
        black_king = None
        for sq, piece in piece_map.items():
            if piece.piece_type == chess.KING:
                if piece.color == chess.WHITE:
                    white_king = sq
                else:
                    black_king = sq
        # danger to white king from black pieces and danger to black king from white pieces
        danger_to_white = king_danger(white_king, chess.BLACK)
        danger_to_black = king_danger(black_king, chess.WHITE)
        return float(danger_to_black - danger_to_white)  # positive = White safer
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn advancement: sum of advanced passed-pawn scores (White minus Black), normalized 0..1 per pawn'
    import chess
    try:
        piece_map = board.piece_map()
        white_score = 0.0
        black_score = 0.0
        # Precompute enemy pawns positions for quick checks by file and rank
        pawn_squares_by_color = {chess.WHITE: [], chess.BLACK: []}
        for sq, p in piece_map.items():
            if p.piece_type == chess.PAWN:
                pawn_squares_by_color[p.color].append(sq)
        for sq, p in piece_map.items():
            if p.piece_type != chess.PAWN:
                continue
            file = chess.square_file(sq)
            rank = chess.square_rank(sq)
            is_passed = True
            if p.color == chess.WHITE:
                # no black pawn on same file or adjacent files on any rank > rank
                for enemy_sq in pawn_squares_by_color[chess.BLACK]:
                    ef = chess.square_file(enemy_sq)
                    er = chess.square_rank(enemy_sq)
                    if abs(ef - file) <= 1 and er > rank:
                        is_passed = False
                        break
                if is_passed:
                    # advanced pawns (higher rank) are stronger
                    white_score += (rank / 7.0)  # 0..1
            else:
                for enemy_sq in pawn_squares_by_color[chess.WHITE]:
                    ef = chess.square_file(enemy_sq)
                    er = chess.square_rank(enemy_sq)
                    if abs(ef - file) <= 1 and er < rank:
                        is_passed = False
                        break
                if is_passed:
                    black_score += ((7 - rank) / 7.0)
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rooks on opponent seventh rank count (White minus Black), rook on 7th = high pressure'
    import chess
    try:
        piece_map = board.piece_map()
        white_count = 0
        black_count = 0
        for sq, p in piece_map.items():
            if p.piece_type != chess.ROOK:
