def feature(board: chess.Board) -> float:
    'Rook open/semi-open file advantage: sum(+1 for rook on open file, +0.5 for rook on semi-open file) (White - Black)'
    try:
        pieces = board.piece_map()
    except Exception:
        return 0.0
    # precompute pawn existence per file and color
    pawns_on_file = {f: {'white': 0, 'black': 0, 'any': 0} for f in range(8)}
    for sq, piece in pieces.items():
        if piece.piece_type == chess.PAWN:
            f = chess.square_file(sq)
            if piece.color == chess.WHITE:
                pawns_on_file[f]['white'] += 1
            else:
                pawns_on_file[f]['black'] += 1
            pawns_on_file[f]['any'] += 1
    white_score = 0.0
    black_score = 0.0
    for sq, piece in pieces.items():
        if piece.piece_type == chess.ROOK:
            f = chess.square_file(sq)
            if pawns_on_file[f]['any'] == 0:
                add = 1.0
            elif (piece.color == chess.WHITE and pawns_on_file[f]['white'] == 0) or (piece.color == chess.BLACK and pawns_on_file[f]['black'] == 0):
                add = 0.5
            else:
                add = 0.0
            if piece.color == chess.WHITE:
                white_score += add
            else:
                black_score += add
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Difference in safe king escape squares: number of adjacent squares a king can move to that are not attacked by the opponent (White - Black)'
    try:
        pieces = board.piece_map()
    except Exception:
        return 0.0
    white_safe = 0
    black_safe = 0
    for sq, piece in pieces.items():
        if piece.piece_type != chess.KING:
            continue
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        opp = not piece.color
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                if df == 0 and dr == 0:
                    continue
                nf = f + df
                nr = r + dr
                if not (0 <= nf <= 7 and 0 <= nr <= 7):
                    continue
                nsq = nr * 8 + nf
                occ = board.piece_at(nsq)
                # square is occupiable if empty or occupied by opponent
                if occ and occ.color == piece.color:
                    continue
                # cannot move into attacked square
                try:
                    attacked = board.is_attacked_by(opp, nsq)
                except Exception:
                    attacked = False
                if not attacked:
                    if piece.color == chess.WHITE:
                        white_safe += 1
                    else:
                        black_safe += 1
    return float(white_safe - black_safe)

def feature(board: chess.Board) -> float:
