def feature(board: chess.Board) -> float:
    'Difference in count of low-mobility non-pawn pieces (<=1 legal move): (white low mobility pieces) - (black low mobility pieces)'
    try:
        # build move counts per from-square
        move_counts = {}
        for mv in board.legal_moves:
            try:
                frm = mv.from_square
            except Exception:
                # older or restricted API: skip
                continue
            move_counts[frm] = move_counts.get(frm, 0) + 1
    except Exception:
        move_counts = {}
    try:
        pieces = board.piece_map()
    except Exception:
        return 0.0
    white_trapped = 0
    black_trapped = 0
    for sq, piece in pieces.items():
        if piece.piece_type == chess.PAWN:
            continue
        cnt = move_counts.get(sq, 0)
        if cnt <= 1:
            if piece.color == chess.WHITE:
                white_trapped += 1
            else:
                black_trapped += 1
    return float(white_trapped - black_trapped)

def feature(board: chess.Board) -> float:
    'Queen proximity to enemy king: sum over queens of 1/(distance+1) to the opposing king (White sum - Black sum)'
    try:
        pieces = board.piece_map()
    except Exception:
        return 0.0
    white_score = 0.0
    black_score = 0.0
    # find kings
    white_king_sq = None
    black_king_sq = None
    for sq, piece in pieces.items():
        if piece.piece_type == chess.KING:
            if piece.color == chess.WHITE:
                white_king_sq = sq
            else:
                black_king_sq = sq
    for sq, piece in pieces.items():
        if piece.piece_type == chess.QUEEN:
            if piece.color == chess.WHITE and black_king_sq is not None:
                d = chess.square_distance(sq, black_king_sq)
                white_score += 1.0 / (d + 1.0)
            if piece.color == chess.BLACK and white_king_sq is not None:
                d = chess.square_distance(sq, white_king_sq)
                black_score += 1.0 / (d + 1.0)
    return float(white_score - black_score)

def feature(board: chess.Board) -> float:
    'Bishop long-diagonal control: weighted sum of diagonal ray lengths (long rays >3 counted more) for White minus Black'
    try:
        pieces = board.piece_map()
    except Exception:
        return 0.0
    def ray_length_from(sq, df, dr):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        length = 0
        nf = f + df
        nr = r + dr
        while 0 <= nf <= 7 and 0 <= nr <= 7:
            nsq = nr * 8 + nf
            length += 1
            if board.piece_at(nsq) is not None:
                break
            nf += df
            nr += dr
        return length
    white_sum = 0.0
    black_sum = 0.0
    for sq, piece in pieces.items():
        if piece.piece_type != chess.BISHOP:
            continue
        total_long = 0
        for df, dr in ((1,1),(1,-1),(-1,1),(-1,-1)):
            ln = ray_length_from(sq, df, dr)
            # emphasize long diagonals: reward length beyond 3
            if ln >= 4:
                total_long += ln
            else:
                total_long += ln * 0.3
        if piece.color == chess.WHITE:
            white_sum += total_long
        else:
            black_sum += total_long
    return float(white_sum - black_sum)

def feature(board: chess.Board) -> float:
    'King pawn shield integrity: (white shield count - black shield count) where shield counts pawns on the three front-adjacent squares'
    try:
        piece_map = board.piece_map()
        white_shield = 0
        black_shield = 0
        for sq, piece in piece_map.items():
            if piece.piece_type == chess.KING:
                f = chess.square_file(sq)
                r = chess.square_rank(sq)
                if piece.color == chess.WHITE:
                    # squares in front for white are rank+1
                    for df in (-1, 0, 1):
                        nf = f + df
                        nr = r + 1
                        if 0 <= nf <= 7 and 0 <= nr <= 7:
                            s2 = chess.square(nf, nr)
                            p2 = board.piece_at(s2)
                            if p2 and p2.piece_type == chess.PAWN and p2.color == chess.WHITE:
                                white_shield += 1
                else:
                    # black moves downwards: front is rank-1
                    for df in (-1, 0, 1):
                        nf = f + df
                        nr = r - 1
                        if 0 <= nf <= 7 and 0 <= nr <= 7:
                            s2 = chess.square(nf, nr)
                            p2 = board.piece_at(s2)
                            if p2 and p2.piece_type == chess.PAWN and p2.color == chess.BLACK:
                                black_shield += 1
        return float(white_shield - black_shield)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Net king attackers weighted by attacker piece value: (white-king-attacked-weight - black-king-attacked-weight)'
    values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    try:
        pm = board.piece_map()
        white_king_sq = None
        black_king_sq = None
        for s, pc in pm.items():
            if pc.piece_type == chess.KING:
                if pc.color == chess.WHITE:
                    white_king_sq = s
                else:
                    black_king_sq = s
        white_att = 0.0
        black_att = 0.0
        if white_king_sq is not None:
            for attacker_sq in board.attackers(chess.BLACK, white_king_sq):
                p = board.piece_at(attacker_sq)
                if p:
                    white_att += values.get(p.piece_type, 0.0)
        if black_king_sq is not None:
            for attacker_sq in board.attackers(chess.WHITE, black_king_sq):
                p = board.piece_at(attacker_sq)
                if p:
                    black_att += values.get(p.piece_type, 0.0)
        # positive => white king under heavier attack (bad for white)
        return float(white_att - black_att)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
