def feature(board: chess.Board) -> float:
    'Difference in king mobility: number of legal king moves available to White minus to Black'
    try:
        # helper to count king moves when it is color's turn
        def king_moves_for(color):
            b = board.copy()
            b.turn = color
            count = 0
            for m in b.legal_moves:
                p = b.piece_at(m.from_square)
                if p is not None and p.piece_type == chess.KING and p.color == color:
                    count += 1
            return count
        wm = king_moves_for(chess.WHITE)
        bm = king_moves_for(chess.BLACK)
        return float(wm - bm)
    except Exception:
