            else:
                for sq, p in pieces.items():
                    if p.piece_type == chess.PAWN and p.color == chess.WHITE:
                        ff = chess.square_file(sq); rr = chess.square_rank(sq)
                        if abs(ff - f) <= 1 and rr < r:
                            return False
                return True
        def rook_behind_for_color(color):
            # find most advanced passed pawn for color
            best_sq = None; best_rank = -1
            for sq, p in pieces.items():
                if p.piece_type == chess.PAWN and p.color == color and is_passed(sq, color):
                    r = chess.square_rank(sq) if color == chess.WHITE else (7 - chess.square_rank(sq))
                    if r > best_rank:
                        best_rank = r; best_sq = sq
            if best_sq is None: return False
            f = chess.square_file(best_sq); r = chess.square_rank(best_sq)
            # check for rook of same color on same file behind the pawn with no blockers between
            for sq, p in pieces.items():
                if p.piece_type == chess.ROOK and p.color == color and chess.square_file(sq) == f:
                    rr = chess.square_rank(sq)
                    if color == chess.WHITE:
                        # rook must be on a lower rank than pawn to be behind (further from promotion)
                        if rr < r:
                            # check no blockers between rr+1..r-1
                            blocked = False
                            step = 1
                            for rrk in range(rr+1, r):
                                if board.piece_at(chess.square(f, rrk)) is not None:
                                    blocked = True; break
                            if not blocked: return True
                    else:
                        if rr > r:
                            blocked = False
                            for rrk in range(r+1, rr):
                                if board.piece_at(chess.square(f, rrk)) is not None:
                                    blocked = True; break
                            if not blocked: return True
            return False
        w = 1.0 if rook_behind_for_color(chess.WHITE) else 0.0
        b = 1.0 if rook_behind_for_color(chess.BLACK) else 0.0
        return float(w - b)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Advantage in race to promotion for most dangerous passed pawn: (enemy king distance to promotion - pawn steps) difference (White - Black)'
    try:
        pieces = board.piece_map()
        white_king_sq = None; black_king_sq = None
        for sq, p in pieces.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE: white_king_sq = sq
                else: black_king_sq = sq
        def is_passed(p_sq, color):
            f = chess.square_file(p_sq); r = chess.square_rank(p_sq)
            if color == chess.WHITE:
                for sq, p in pieces.items():
                    if p.piece_type == chess.PAWN and p.color == chess.BLACK:
                        ff = chess.square_file(sq); rr = chess.square_rank(sq)
