            else:
                for sq, p in pieces.items():
                    if p.piece_type == chess.PAWN and p.color == chess.WHITE:
                        ff = chess.square_file(sq); rr = chess.square_rank(sq)
                        if abs(ff - f) <= 1 and rr < r:
                            return False
                return True
        best_white_val = None
        best_black_val = None
        for sq, p in pieces.items():
