                king_dist = chess.square_distance(black_king_sq, promo_sq) if black_king_sq is not None else 99
                val = king_dist - pawn_steps
                if best_white_val is None or val > best_white_val: best_white_val = val
            if p.piece_type == chess.PAWN and p.color == chess.BLACK and is_passed(sq, chess.BLACK):
                promo_sq = chess.square(chess.square_file(sq), 0)
                pawn_steps = chess.square_rank(sq) - 0
                king_dist = chess.square_distance(white_king_sq, promo_sq) if white_king_sq is not None else 99
                val = king_dist - pawn_steps
                if best_black_val is None or val > best_black_val: best_black_val = val
        if best_white_val is None: best_white_val = 0.0
        if best_black_val is None: best_black_val = 0.0
        return float(best_white_val - best_black_val)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rook mobility difference (sum of sliding reachable squares for all rooks, White - Black)'
    try:
        pieces = board.piece_map()
        def rook_reach(sq):
            if sq is None: return 0
            res = 0
            f0 = chess.square_file(sq); r0 = chess.square_rank(sq)
            directions = [(1,0),(-1,0),(0,1),(0,-1)]
            for df, dr in directions:
                f = f0 + df; r = r0 + dr
                while 0 <= f <= 7 and 0 <= r <= 7:
                    s = chess.square(f, r)
                    res += 1
                    if board.piece_at(s) is not None:
                        break
                    f += df; r += dr
            return res
        wsum = 0; bsum = 0
        for sq, p in pieces.items():
            if p.piece_type == chess.ROOK:
                if p.color == chess.WHITE: wsum += rook_reach(sq)
                else: bsum += rook_reach(sq)
        # normalize by a typical max (14 per rook * number of rooks)
        return float((wsum - bsum))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Defenders minus attackers on the most advanced passed pawn for each side, returned (White - Black)'
    try:
        pieces = board.piece_map()
        def is_passed(p_sq, color):
            f = chess.square_file(p_sq); r = chess.square_rank(p_sq)
            if color == chess.WHITE:
                for sq, p in pieces.items():
                    if p.piece_type == chess.PAWN and p.color == chess.BLACK:
                        ff = chess.square_file(sq); rr = chess.square_rank(sq)
                        if abs(ff - f) <= 1 and rr > r:
                            return False
                return True
            else:
                for sq, p in pieces.items():
                    if p.piece_type == chess.PAWN and p.color == chess.WHITE:
                        ff = chess.square_file(sq); rr = chess.square_rank(sq)
                        if abs(ff - f) <= 1 and rr < r:
                            return False
                return True
        best_white_sq = None; best_white_rank = -1
        best_black_sq = None; best_black_rank = -1
        for sq, p in pieces.items():
            if p.piece_type == chess.PAWN:
                if p.color == chess.WHITE and is_passed(sq, chess.WHITE):
                    r = chess.square_rank(sq)
                    if r > best_white_rank:
                        best_white_rank = r; best_white_sq = sq
                if p.color == chess.BLACK and is_passed(sq, chess.BLACK):
                    r = 7 - chess.square_rank(sq)
                    if r > best_black_rank:
                        best_black_rank = r; best_black_sq = sq
        def defense_balance(p_sq, color):
            if p_sq is None: return 0.0
            defenders = len(board.attackers(color, p_sq))
            attackers = len(board.attackers(not color, p_sq))
            return float(defenders - attackers)
        wval = defense_balance(best_white_sq, chess.WHITE)
        bval = defense_balance(best_black_sq, chess.BLACK)
        return float(wval - bval)
    except Exception:
        return 0.0

