def feature(board: chess.Board) -> float:
    'Back-rank major-piece threat difference: (# black major attacks to White back rank near king) - (# white major attacks to Black back rank near king)'
    try:
        pieces = board.piece_map()
        wk = None; bk = None
        for sq, p in pieces.items():
            if p.piece_type == chess.KING:
                if p.color == chess.WHITE: wk = sq
                else: bk = sq
        def backrank_threats(king_sq, attacker_color):
            if king_sq is None: return 0
            kr = chess.square_rank(king_sq)
            # determine back rank: for white king it's rank 0; for black rank 7
            back_rank = 0 if chess.square_rank(king_sq) <= 1 else chess.square_rank(king_sq)
            # but prefer absolute back rank: white -> 0, black -> 7
            back_rank = 0 if board.piece_at(king_sq) and board.piece_at(king_sq).color == chess.WHITE else 7
            threats = 0
            for file in range(8):
                sq = chess.square(file, back_rank)
                for a in board.attackers(attacker_color, sq):
                    ap = board.piece_at(a)
                    if ap and ap.piece_type in (chess.ROOK, chess.QUEEN):
                        threats += 1
            return threats
        w_threats_from_black = backrank_threats(wk, chess.BLACK)
        b_threats_from_white = backrank_threats(bk, chess.WHITE)
        return float(w_threats_from_black - b_threats_from_white)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Isolated pawn count difference (White - Black): number of isolated pawns (no friendly pawn on adjacent files)'
    try:
        pieces = board.piece_map()
        white_files = {f:0 for f in range(8)}
        black_files = {f:0 for f in range(8)}
        for sq, p in pieces.items():
            if p.piece_type == chess.PAWN:
                f = chess.square_file(sq)
                if p.color == chess.WHITE: white_files[f] += 1
                else: black_files[f] += 1
        def isolated_count(files):
            cnt = 0
            for f in range(8):
                if files.get(f,0) > 0:
                    left = files.get(f-1,0) if f-1 >= 0 else 0
                    right = files.get(f+1,0) if f+1 <= 7 else 0
                    if left == 0 and right == 0:
                        # count each pawn on that file as isolated
                        cnt += files[f]
            return cnt
        w_iso = isolated_count(white_files)
        b_iso = isolated_count(black_files)
        return float(w_iso - b_iso)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn-shield strength in front of each king: (white_shield_count - black_shield_count)'
    try:
        pieces = board.piece_map()
        wk = next((sq for sq, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.WHITE), None)
        bk = next((sq for sq, p in pieces.items() if p.piece_type == chess.KING and p.color == chess.BLACK), None)
        pawn_squares = {sq for sq, p in pieces.items() if p.piece_type == chess.PAWN}
        def shield_count(king_sq, color):
            if king_sq is None:
                return 0
            f = chess.square_file(king_sq)
            r = chess.square_rank(king_sq)
            count = 0
            # For white, shield pawns are on rank+1; for black, rank-1
            target_rank = r + 1 if color == chess.WHITE else r - 1
            if 0 <= target_rank <= 7:
                for df in (-1, 0, 1):
                    ff = f + df
                    if 0 <= ff <= 7:
                        sq = chess.square(ff, target_rank)
                        if sq in pawn_squares:
                            count += 1
            return count
        white_shield = shield_count(wk, chess.WHITE)
        black_shield = shield_count(bk, chess.BLACK)
        return float(white_shield - black_shield)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rook presence on open (1.0) or semi-open (0.5) files: (white_score - black_score)'
    try:
        pieces = board.piece_map()
        pawns_by_file = {f: [] for f in range(8)}
        for sq, p in pieces.items():
            if p.piece_type == chess.PAWN:
                pawns_by_file[chess.square_file(sq)].append((sq, p.color))
        white_score = 0.0
        black_score = 0.0
        for sq, p in pieces.items():
            if p.piece_type == chess.ROOK:
                f = chess.square_file(sq)
                pawns = pawns_by_file[f]
                if len(pawns) == 0:
                    val = 1.0
                else:
                    # semi-open if no friendly pawn on this file
                    has_friendly = any(col == p.color for _, col in pawns)
                    val = 0.0 if has_friendly and len(pawns) > 0 else 0.5
                    # If there are opponent pawns but no friendly, semi-open = 0.5
                    if len(pawns) > 0 and not has_friendly:
                        val = 0.5
                if p.color == chess.WHITE:
                    white_score += val
                else:
                    black_score += val
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Minor-piece mobility: (white_minor_moves_per_piece - black_minor_moves_per_piece)'
    try:
        pieces = board.piece_map()
        # Count minor pieces
        white_minors = sum(1 for p in pieces.values() if p.color == chess.WHITE and p.piece_type in (chess.KNIGHT, chess.BISHOP))
        black_minors = sum(1 for p in pieces.values() if p.color == chess.BLACK and p.piece_type in (chess.KNIGHT, chess.BISHOP))
        # Count legal moves originating from knights/bishops
        white_moves = 0
        black_moves = 0
        for mv in board.legal_moves:
            p = board.piece_at(mv.from_square)
            if p and p.piece_type in (chess.KNIGHT, chess.BISHOP):
                if p.color == chess.WHITE:
                    white_moves += 1
                else:
                    black_moves += 1
        # Normalize to per-piece to avoid bias from piece count
        wm = white_moves / max(1.0, white_minors)
        bm = black_moves / max(1.0, black_minors)
        return float(wm - bm)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Bishop unobstructed reach: average number of free diagonal squares per bishop (white - black)'
    try:
        pieces = board.piece_map()
        def reach_for_bishop(sq):
            if sq is None: return 0
            count = 0
            directions = ((1,1),(1,-1),(-1,1),(-1,-1))
            f0 = chess.square_file(sq)
            r0 = chess.square_rank(sq)
            for df, dr in directions:
                f, r = f0 + df, r0 + dr
                while 0 <= f <= 7 and 0 <= r <= 7:
                    tsq = chess.square(f, r)
                    if tsq in pieces:
                        break
                    count += 1
                    f += df; r += dr
            return count
        white_reach = []
        black_reach = []
        for sq, p in pieces.items():
            if p.piece_type == chess.BISHOP:
                if p.color == chess.WHITE:
                    white_reach.append(reach_for_bishop(sq))
                else:
                    black_reach.append(reach_for_bishop(sq))
        avg_white = sum(white_reach) / max(1.0, len(white_reach))
        avg_black = sum(black_reach) / max(1.0, len(black_reach))
        return float(avg_white - avg_black)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    "Rooks on opponent's seventh rank: (white_rooks_on_7th - black_rooks_on_7th)"
    try:
        pieces = board.piece_map()
        w = 0
