def feature(board: chess.Board) -> float:
    'Open-file pressure on kings: counts adjacent files with no friendly pawn in 1-4 squares ahead weighted by enemy heavy pieces on the file (positive favors White)'
    try:
        pieces = board.piece_map()
        def side_score(color):
            king_sq = next((s for s,p in pieces.items() if p.piece_type==chess.KING and p.color==color), None)
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            score = 0.0
            # consider files kf-1, kf, kf+1
            for df in (-1,0,1):
                f = kf + df
                if f < 0 or f > 7:
                    continue
                # search for friendly pawns within 1..4 ranks forward (toward opponent)
                found_friendly = False
                if color == chess.WHITE:
                    ranks = range(kr+1, min(7, kr+4)+1)
                else:
                    ranks = range(max(0, kr-4), kr)
                for r in ranks:
                    sq = chess.square(f, r)
                    p = pieces.get(sq)
                    if p is not None and p.piece_type==chess.PAWN and p.color==color:
                        found_friendly = True
                        break
                if found_friendly:
                    continue
                # count enemy heavy pieces (rook/queen) anywhere on this file
                heavy_count = 0
                for r in range(8):
                    p = pieces.get(chess.square(f,r))
                    if p is not None and p.color != color and (p.piece_type in (chess.ROOK, chess.QUEEN)):
                        heavy_count += 1
                score += heavy_count
            return float(score)
        white_score = side_score(chess.WHITE)
        black_score = side_score(chess.BLACK)
        return float(black_score - white_score)  # positive means Black has more pressure -> bad for White, invert?
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn advantage weighted by rank advancement: sum for each passed pawn of (1 + rank_index/6), returned as (White - Black)'
    try:
        pieces = board.piece_map()
        def is_passed(sq, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if board.piece_at(sq) is None or board.piece_at(sq).piece_type != chess.PAWN or board.piece_at(sq).color != color:
                return False
            # for white, any black pawn on same/adj files with rank > r blocks
            for df in (-1,0,1):
                ff = f + df
                if ff < 0 or ff > 7:
                    continue
                for rr in range(r+1,8) if color==chess.WHITE else range(0,r):
                    sq2 = chess.square(ff, rr)
                    p = pieces.get(sq2)
                    if p is not None and p.piece_type==chess.PAWN and p.color!=color:
                        return False
            return True
        def side_score(color):
            s = 0.0
            for sq,p in pieces.items():
                if p.piece_type==chess.PAWN and p.color==color and is_passed(sq,color):
                    r = chess.square_rank(sq)
                    adv = (r/6.0) if color==chess.WHITE else ((7-r)/6.0)
                    s += 1.0 + adv
            return s
        return float(side_score(chess.WHITE) - side_score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Rooks on the seventh (or second) rank: weighted count of attacking rooks on opponent\'s back ranks (positive favors White)'
    try:
        pieces = board.piece_map()
        white_score = 0.0
        black_score = 0.0
        for sq,p in pieces.items():
            if p.piece_type==chess.ROOK:
                r = chess.square_rank(sq)
                if p.color == chess.WHITE and r == 6:  # white rook on 7th rank
                    white_score += 1.5
                if p.color == chess.BLACK and r == 1:  # black rook on 2nd rank (white's 7th)
                    black_score += 1.5
                # also reward rooks on files with enemy king on same file (pressure)
                ksq = next((s for s,pp in pieces.items() if pp.piece_type==chess.KING and pp.color!=p.color), None)
                if ksq is not None and chess.square_file(ksq) == chess.square_file(sq):
                    # check if rook has line to king (no blocker)
                    df = 0
                    sf = chess.square_file(sq)
                    sr = chess.square_rank(sq)
                    kr = chess.square_rank(ksq)
                    step = 1 if kr>sr else -1
                    blocked = False
                    for rr in range(sr+step, kr, step):
                        if pieces.get(chess.square(sf, rr)) is not None:
                            blocked = True
                            break
                    if not blocked:
                        if p.color==chess.WHITE:
                            white_score += 0.8
                        else:
                            black_score += 0.8
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Bishop pair and diagonal targeting of enemy king: (White - Black) score combining bishop pair and unobstructed diagonal lines to the king'
    try:
        pieces = board.piece_map()
        def diag_target_count(color):
            count = 0.0
            king_sq = next((s for s,p in pieces.items() if p.piece_type==chess.KING and p.color!=color), None)
            for sq,p in pieces.items():
                if p.piece_type==chess.BISHOP and p.color==color:
                    # bishop pair bonus added later
                    if king_sq is None:
                        continue
                    sf = chess.square_file(sq); sr = chess.square_rank(sq)
                    kf = chess.square_file(king_sq); kr = chess.square_rank(king_sq)
                    if abs(sf - kf) == abs(sr - kr):
                        df = 1 if kf>sf else -1
                        dr = 1 if kr>sr else -1
                        blocked = False
                        x,y = sf+df, sr+dr
                        while x!=kf and y!=kr:
                            if pieces.get(chess.square(x,y)) is not None:
                                blocked = True
                                break
                            x += df; y += dr
                        if not blocked:
                            # closer bishops count more
                            dist = abs(sf-kf)
                            count += 0.6 + 0.2*(6-max(0,dist-1))/6.0
            return count
        white_bishops = sum(1 for p in pieces.values() if p.piece_type==chess.BISHOP and p.color==chess.WHITE)
        black_bishops = sum(1 for p in pieces.values() if p.piece_type==chess.BISHOP and p.color==chess.BLACK)
        white_score = (white_bishops - black_bishops) * 0.9 + diag_target_count(chess.WHITE)
        black_score = 0.0 + diag_target_count(chess.BLACK)
        return float(white_score - black_score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Pawn-structure health: (isolated + 0.5*doubled) difference (White - Black), lower is worse, so positive favors White'
    try:
        pieces = board.piece_map()
        def counts(color):
            pawns_by_file = {f:[] for f in range(8)}
            for sq,p in pieces.items():
                if p.piece_type==chess.PAWN and p.color==color:
                    pawns_by_file[chess.square_file(sq)].append(sq)
            isolated = 0
            doubled = 0
            for f, lst in pawns_by_file.items():
                if len(lst) >= 2:
                    doubled += (len(lst)-1)
                # isolated: check if any friendly pawn on adjacent files
                if len(lst) == 0:
                    continue
                has_adj = False
                for af in (f-1, f+1):
                    if 0 <= af <= 7 and len(pawns_by_file.get(af,[]))>0:
                        has_adj = True
                        break
                if not has_adj:
                    isolated += len(lst)
            return isolated, doubled
        wi, wd = counts(chess.WHITE)
        bi, bd = counts(chess.BLACK)
        # smaller structure penalty is better; return White - Black
        score = ((bi + 0.5*bd) - (wi + 0.5*wd))
        return float(score)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Trapped minor pieces: counts of knights/bishops with <=1 legal move (Black trapped minus White trapped), positive favors White'
    try:
        pieces = board.piece_map()
        legal = list(board.legal_moves)
        def trapped_count(color):
            cnt = 0
            for sq,p in pieces.items():
                if p.color==color and p.piece_type in (chess.KNIGHT, chess.BISHOP):
                    moves = sum(1 for m in legal if m.from_square == sq)
                    if moves <= 1:
                        cnt += 1
            return cnt
        white_trapped = trapped_count(chess.WHITE)
        black_trapped = trapped_count(chess.BLACK)
        return float(black_trapped - white_trapped)
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Heavy-piece battery alignment towards enemy king: counts aligned heavy-piece pairs (rook/queen) that form a battery aimed at the king (White - Black)'
    try:
        pieces = board.piece_map()
        def battery_score(color):
            score = 0.0
            king_sq = next((s for s,p in pieces.items() if p.piece_type==chess.KING and p.color!=color), None)
            heavies = [ (sq,p) for sq,p in pieces.items() if p.color==color and p.piece_type in (chess.ROOK, chess.QUEEN) ]
            if king_sq is None:
                return 0.0
            for i,(sq1,p1) in enumerate(heavies):
                for j,(sq2,p2) in enumerate(heavies):
                    if i>=j: continue
                    f1,r1 = chess.square_file(sq1), chess.square_rank(sq1)
                    f2,r2 = chess.square_file(sq2), chess.square_rank(sq2)
                    kf,kr = chess.square_file(king_sq), chess.square_rank(king_sq)
                    # check collinearity (rank/file/diag)
                    if not ( (f1==f2==kf) or (r1==r2==kr) or (abs(f1-f2)==abs(r1-r2) and abs(f1-kf)==abs(r1-kr) and abs(f2-kf)==abs(r2-kr)) ):
                        continue
                    # ensure ordering: sq1 closer to attacker side than sq2 and king beyond both
                    # we'll check along vector from nearer to king to farthest
                    # find attacker-most and nearer-to-king ordering by distance to king
                    d1 = abs(f1-kf) + abs(r1-kr)
                    d2 = abs(f2-kf) + abs(r2-kr)
                    if d1 == d2:
                        continue
                    if d1 > d2:
                        nearer, farther = sq2, sq1
                    else:
                        nearer, farther = sq1, sq2
                    # check no blockers between nearer and king, and between farther and nearer (except the pieces themselves)
                    def path_clear(a,b):
                        fa,ra = chess.square_file(a), chess.square_rank(a)
                        fb,rb = chess.square_file(b), chess.square_rank(b)
                        df = 0 if fa==fb else (1 if fb>fa else -1)
                        dr = 0 if ra==rb else (1 if rb>ra else -1)
                        x,y = fa+df, ra+dr
                        while (x,y) != (fb,rb):
                            if pieces.get(chess.square(x,y)) is not None:
                                return False
                            x += df; y += dr
                        return True
                    if not path_clear(nearer, king_sq):
                        continue
                    # ensure nearer piece and farther piece are in line without other blockers between them
                    if not path_clear(farther, nearer):
                        continue
                    # weight by combination types (queen stronger)
                    val = 0.0
                    for s,p in ((sq1,p1),(sq2,p2)):
                        val += 9.0 if p.piece_type==chess.QUEEN else 5.0
                    score += val/14.0
            return score
        return float(battery_score(chess.WHITE) - battery_score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'King pawn shield gaps: number of empty or enemy-occupied shield squares in 1-3 ranks in front of king across adjacent files (positive favors White)'
    try:
        pieces = board.piece_map()
        def shield_gaps(color):
            king_sq = next((s for s,p in pieces.items() if p.piece_type==chess.KING and p.color==color), None)
            if king_sq is None:
                return 0.0
            kf = chess.square_file(king_sq)
            kr = chess.square_rank(king_sq)
            gaps = 0.0
            for df in (-1,0,1):
                f = kf+df
                if f<0 or f>7: continue
                if color==chess.WHITE:
                    ranks = range(kr+1, min(7,kr+3)+1)
                else:
                    ranks = range(max(0,kr-3), kr)
                for r in ranks:
                    sq = chess.square(f,r)
                    p = pieces.get(sq)
                    if p is None:
                        gaps += 0.5
                    elif p.color!=color:
                        gaps += 0.8
            return gaps
        return float(shield_gaps(chess.BLACK) - shield_gaps(chess.WHITE))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Centralization index for minor pieces and queen: sum of (3 - manhattan distance to center) clipped at 0, returned as (White - Black)'
    try:
        pieces = board.piece_map()
        center_squares = [chess.parse_square(s) for s in ('d4','e4','d5','e5')]
        def central_score(color):
            s = 0.0
            for sq,p in pieces.items():
                if p.color!=color: continue
                if p.piece_type in (chess.KNIGHT, chess.BISHOP, chess.QUEEN, chess.ROOK):
                    # measure distance to nearest central square using square_distance (Chebyshev-like Manhattan in doc)
                    d = min(chess.square_distance(sq, c) for c in center_squares)
                    val = max(0.0, 3.0 - float(d))
                    if p.piece_type==chess.QUEEN:
                        val *= 1.2
                    elif p.piece_type==chess.ROOK:
                        val *= 0.9
                    s += val
            return s
        return float(central_score(chess.WHITE) - central_score(chess.BLACK))
    except Exception:
        return 0.0

def feature(board: chess.Board) -> float:
    'Passed pawn strength difference: sum(white passed pawn advancement) - sum(black passed pawn advancement)'
    import chess
    piece_map = board.piece_map()
    pawn_positions = {chess.WHITE: [], chess.BLACK: []}
    for sq, p in piece_map.items():
        if p.piece_type == chess.PAWN:
            pawn_positions[p.color].append((sq, chess.square_file(sq), chess.square_rank(sq)))
    def is_passed(sq, file, rank, color):
        # For white: no black pawn on same or adjacent files with rank > rank
        # For black: no white pawn on same or adjacent files with rank < rank
        for osq, op, orank in pawn_positions[not color]:
            if abs(op - file) <= 1:
                if color == chess.WHITE and orank > rank:
                    return False
                if color == chess.BLACK and orank < rank:
                    return False
        return True
    def advance_weight(rank, color):
        # white starting rank for pawns is 1 (index), promotion at 7 => rank index 7
        # weight by how advanced toward promotion (0..6)
        if color == chess.WHITE:
            return max(0.0, rank - 1) / 6.0
        else:
            return max(0.0, 6 - rank) / 6.0
    wscore = 0.0
    bscore = 0.0
    for sq, f, r in pawn_positions[chess.WHITE]:
        if is_passed(sq, f, r, chess.WHITE):
            wscore += 1.0 + advance_weight(r, chess.WHITE) * 2.0
    for sq, f, r in pawn_positions[chess.BLACK]:
        if is_passed(sq, f, r, chess.BLACK):
            bscore += 1.0 + advance_weight(r, chess.BLACK) * 2.0
    return float(wscore - bscore)

def feature(board: chess.Board) -> float:
    'Hanging material difference: (sum values of enemy-attacked but undefended white pieces) - (same for black)'
    import chess
    piece_values = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    pm = board.piece_map()
    white_hang = 0.0
    black_hang = 0.0
    for sq, p in pm.items():
        attackers = board.attackers(not p.color, sq)
        defenders = board.attackers(p.color, sq)
        if attackers and not defenders:
            # piece is attacked and undefended
            val = piece_values.get(p.piece_type, 0.0)
            if p.color == chess.WHITE:
                white_hang += val
            else:
                black_hang += val
    return float(white_hang - black_hang)

def feature(board: chess.Board) -> float:
    'Open/semi-open rook file advantage: weighted count of rooks on open or semi-open files (White - Black)'
    import chess
    pm = board.piece_map()
    def file_pawn_counts(file):
        wp = bp = 0
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN and chess.square_file(sq) == file:
                if p.color == chess.WHITE:
                    wp += 1
                else:
                    bp += 1
        return wp, bp
    wscore = 0.0
    bscore = 0.0
    for sq, p in pm.items():
        if p.piece_type == chess.ROOK:
            f = chess.square_file(sq)
            wp, bp = file_pawn_counts(f)
            if wp == 0 and bp == 0:
                score = 2.0  # open file
            elif (p.color == chess.WHITE and wp == 0 and bp > 0) or (p.color == chess.BLACK and bp == 0 and wp > 0):
                score = 1.2  # semi-open (only opponent pawns)
            else:
                score = 0.0
            if p.color == chess.WHITE:
                wscore += score
            else:
                bscore += score
    return float(wscore - bscore)

def feature(board: chess.Board) -> float:
    'Local king attack density: weighted sum of opponent attackers to squares within manhattan dist<=2 of each king (White pressure on Black king - Black on White king)'
    import chess, math
    pm = board.piece_map()
    vals = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    kings = {}
    for sq, p in pm.items():
        if p.piece_type == chess.KING:
            kings[p.color] = sq
    def pressure_on(king_sq, by_color):
        if king_sq is None:
            return 0.0
        total = 0.0
        for sq in range(64):
            if chess.square_distance(sq, king_sq) <= 2:
                attackers = board.attackers(by_color, sq)
                for a in attackers:
                    pa = pm.get(a)
                    if pa:
                        # weight by piece value and proximity to king square
                        d = chess.square_distance(a, king_sq)
                        total += vals.get(pa.piece_type,0.0) / (1.0 + d)
        return total
    w_k = kings.get(chess.WHITE)
    b_k = kings.get(chess.BLACK)
    white_pressure_on_black = pressure_on(b_k, chess.WHITE)
    black_pressure_on_white = pressure_on(w_k, chess.BLACK)
    return float(white_pressure_on_black - black_pressure_on_white)

def feature(board: chess.Board) -> float:
    'Trapped piece count difference: number (weighted by piece value) of pieces with zero pseudo-mobility for White - Black'
    import chess
    pm = board.piece_map()
    vals = {chess.PAWN:1.0, chess.KNIGHT:3.0, chess.BISHOP:3.0, chess.ROOK:5.0, chess.QUEEN:9.0, chess.KING:0.0}
    # directions for sliding pieces
    orth_dirs = [(-1,0),(1,0),(0,-1),(0,1)]
    diag_dirs = [(-1,-1),(-1,1),(1,-1),(1,1)]
    knight_moves = [(-2,-1),(-2,1),(-1,-2),(-1,2),(1,-2),(1,2),(2,-1),(2,1)]
    def sq_coords(sq):
        return chess.square_file(sq), chess.square_rank(sq)
    def in_board(f,r):
        return 0 <= f < 8 and 0 <= r < 8
    def pseudo_mobility(sq, p):
        f,r = sq_coords(sq)
        moves = 0
        if p.piece_type == chess.KNIGHT:
            for df,dr in knight_moves:
                nf, nr = f+df, r+dr
                if not in_board(nf,nr): continue
                nsq = chess.square(nf,nr)
                occ = pm.get(nsq)
                if occ is None or occ.color != p.color:
                    moves += 1
        elif p.piece_type == chess.BISHOP or p.piece_type == chess.QUEEN:
            for df,dr in diag_dirs:
                nf, nr = f+df, r+dr
                while in_board(nf,nr):
                    nsq = chess.square(nf,nr)
                    occ = pm.get(nsq)
                    if occ is None:
                        moves += 1
                    else:
                        if occ.color != p.color:
                            moves += 1
                        break
                    nf += df; nr += dr
        if p.piece_type == chess.ROOK or p.piece_type == chess.QUEEN:
            for df,dr in orth_dirs:
                nf, nr = f+df, r+dr
                while in_board(nf,nr):
                    nsq = chess.square(nf,nr)
                    occ = pm.get(nsq)
                    if occ is None:
                        moves += 1
                    else:
                        if occ.color != p.color:
                            moves += 1
                        break
                    nf += df; nr += dr
        if p.piece_type == chess.PAWN:
            dir = 1 if p.color == chess.WHITE else -1
            # forward
            nf, nr = f, r+dir
            if in_board(nf,nr):
                nsq = chess.square(nf,nr)
                if pm.get(nsq) is None:
                    moves += 1
            # captures
            for df in (-1,1):
                nf, nr = f+df, r+dir
                if in_board(nf,nr):
                    nsq = chess.square(nf,nr)
                    occ = pm.get(nsq)
                    if occ is not None and occ.color != p.color:
                        moves += 1
        if p.piece_type == chess.KING:
            for df,dr in orth_dirs + diag_dirs:
                nf, nr = f+df, r+dr
                if in_board(nf,nr):
                    nsq = chess.square(nf,nr)
                    occ = pm.get(nsq)
                    if occ is None or occ.color != p.color:
                        moves += 1
        return moves
    wtrap = 0.0
    btrap = 0.0
    for sq, p in pm.items():
        mobility = pseudo_mobility(sq, p)
        if mobility == 0:
            if p.color == chess.WHITE:
                wtrap += vals.get(p.piece_type,0.0)
            else:
                btrap += vals.get(p.piece_type,0.0)
    return float(wtrap - btrap)

def feature(board: chess.Board) -> float:
    'Pawn structure weaknesses difference: (isolated + doubled*0.8) for White - Black'
    import chess
    pm = board.piece_map()
    def pawn_files(color):
        files = {}
        for sq, p in pm.items():
            if p.piece_type == chess.PAWN and p.color == color:
                f = chess.square_file(sq)
                files.setdefault(f, []).append(sq)
        return files
    wfiles = pawn_files(chess.WHITE)
    bfiles = pawn_files(chess.BLACK)
    def weakness(files):
        iso = 0
        doubled = 0
        for f, lst in files.items():
            # isolated if no friendly pawn on adjacent files
            if not any((f-1 in files) or (f+1 in files) for _ in [0]):  # trick to check adjacency
                # above line is awkward; redo properly below
                pass
        # redo
    # redo proper calculation
    def calc(files):
        iso = 0
        doubled = 0
        for f, lst in files.items():
            if (f-1) not in files and (f+1) not in files:
                iso += len(lst)
